    if [ "$dist" == "mac" ] && [[ "$sh_locale" =~ ^en ]] && [ ! -d "$TEXTDOMAINDIR/$sh_locale" ]
    then
        ln -s "$TEXTDOMAINDIR/en_GB" "$TEXTDOMAINDIR"/en
    fi

    Println "$info You can always use command ${green}tv c <en|ru|de|zh_CN...>${normal} to change/update language!"
    Println "Downloading ${green}$sh_locale${normal} language file...\n"

    DepInstall wget

    if [ "$sh_locale" == "zh_CN" ]
    then
        echo -e "sh_locale=$sh_locale\nexport LANG=zh_CN.UTF-8\nlocale_fix=0" > "$i18n_FILE"
        i18nSetupFastPath
        i18nResetCache
        i18nGetMsg
        Println "$(eval_gettext "\${green}成功!\${normal}")\n"
        return 0
    fi

    local mo_dir="$TEXTDOMAINDIR/$sh_locale/LC_MESSAGES"
    local mo_file="$mo_dir/${TEXTDOMAIN}.mo"
    local tmp_mo
    mkdir -p "$mo_dir"
    tmp_mo=$(mktemp)

    if wget --timeout=15 --tries=3 --no-check-certificate "$FFMPEG_MIRROR_LINK/locale/po/aios.sh-$sh_locale.mo" -qO "$tmp_mo" \
        && [ -s "$tmp_mo" ] \
        && ( ! command -v msgunfmt > /dev/null 2>&1 || msgunfmt "$tmp_mo" > /dev/null 2>&1 )
    then
        chmod 644 "$tmp_mo"
        mv -f "$tmp_mo" "$mo_file"
        echo -e "sh_locale=$sh_locale\nexport LANG=en_US.UTF-8\nlocale_fix=0" > "$i18n_FILE"
        i18nSetupFastPath
        i18nResetCache
        i18nGetMsg
        Println "$(eval_gettext "\${green}成功!\${normal}")\n"
    else
        rm -f "$tmp_mo"
        Println "$(eval_gettext "\${red}失败! 请稍后再试!\${normal}")\n"
        exit 1
    fi
}

