    inquirer:on_input_page() {
        if [ "$input_page" = true ] && [[ "$1" =~ [0-9] ]] 
        then
            input_page_num="${input_page_num:-}$1"
            input_page_num=${input_page_num#\0}
        else
            input_page=true
            input_page_num=""
        fi
    }

    inquirer:on_checkbox_input_enter() {
        local i

        if [ "$input_search" = true ] 
        then
            if [ -n "$text_input" ] 
            then
                tput cub "$(tput cols)"
                tput el
                tput cuu1
                tput el
                tput cuu1
                tput el
                tput cuu1
                tput el
                tput cud1

                local checkbox_list_page

                for i in "${!checkbox_list[@]}"
                do
                    if [[ "${checkbox_list[i]}" =~ "$text_input" ]] 
                    then
                        checkbox_list_page=$((i/list_perpage+1))
                        inquirer:print "${green}P${checkbox_list_page}${normal} ${checkbox_list[i]}\n"
                    fi
                done

                if [ -n "${checkbox_list_page:-}" ] 
                then
                    tput cud1
                fi

                inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${pages_tip:-}${dim}`gettext \"(按 <space> 选择, <enter> 确认)\"`${normal}\n\n\n"
            fi
            inquirer:on_checkbox_input_up
            return
        fi

        if [ "$input_page" = true ] 
        then
            input_page=false
            if [ -n "${input_page_num:-}" ] 
            then
                if [ "$input_page_num" -gt "$pages_count" ] || [ "$input_page_num" -eq $((pages_index+1)) ]
                then
                    input_page_num=""
                    return
                fi

                pages_index=$((input_page_num-1))

                pages_tip="${dim}$pages_arrows $((pages_index+1))/$pages_count `gettext \"页\"`${normal}"

                if [ "$input_page_num" -eq "$pages_count" ] 
                then
                    page_list_count=$((list_count-pages_index*list_perpage))
                else
                    page_list_count=$list_perpage
                fi

                inquirer:page_instructions
                tput cub "$(tput cols)"
                tput cud $((list_perpage-current_index+1))

                for((i=0;i<=list_perpage;i++));
                do
                    tput el
                    tput cuu1
                done

                tput el

                if [ "$current_index" -gt "$page_list_count" ] 
                then
                    current_index=$page_list_count
                fi

                page_list=()
                checkbox_page_selected=()
                checkbox_page_select_all=true

                for((i=0;i<page_list_count;i++));
                do
                    page_list+=("${checkbox_list[i+list_perpage*pages_index]}")

                    if [ "$i" = "$current_index" ] 
                    then
                        if [ "${checkbox_selected[i+list_perpage*pages_index]}" = true ]
                        then
                            checkbox_page_selected+=("true")
                            inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${page_list[i]}\n"
                        else
                            checkbox_page_selected+=("false")
                            checkbox_page_select_all=false
                            inquirer:print "${cyan}${arrow}${normal}${unchecked} ${page_list[i]}\n"
                        fi
                    else
                        if [ "${checkbox_selected[i+list_perpage*pages_index]}" = true ]
                        then
                            checkbox_page_selected+=("true")
                            inquirer:print " ${green}${checked}${normal} ${page_list[i]}\n"
                        else
                            checkbox_page_selected+=("false")
                            checkbox_page_select_all=false
                            inquirer:print " ${unchecked} ${page_list[i]}\n"
                        fi
                    fi
                done

                page_list+=("$(gettext 全选)")

                if [ "$current_index" -eq $page_list_count ] 
                then
                    if [ "$checkbox_page_select_all" = true ] 
                    then
                        checkbox_page_selected+=("true")
                        inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${page_list[page_list_count]}\n"
                    else
                        checkbox_page_selected+=("false")
                        inquirer:print "${cyan}${arrow}${normal}${unchecked} ${page_list[page_list_count]}\n"
                    fi
                else
                    if [ "$checkbox_page_select_all" = true ] 
                    then
                        checkbox_page_selected+=("true")
                        inquirer:print " ${green}${checked}${normal} ${page_list[page_list_count]}\n"
                    else
                        checkbox_page_selected+=("false")
                        inquirer:print " ${unchecked} ${page_list[page_list_count]}\n"
                    fi
                fi

                page_list_count=$((page_list_count+1))

                tput cuu $((page_list_count-current_index))

                input_page_num=""
            fi
            return
        fi

        for i in "${!checkbox_list[@]}"
        do
            if [ "${checkbox_selected[i]}" = true ] 
            then
                checkbox_selected_indices+=("$i")
                checkbox_selected_options+=("${checkbox_list[i]}")
            fi
        done

        tput cub "$(tput cols)"

        if [ -z "${checkbox_selected_indices:-}" ] 
        then
            tput sc
            failed_count=$((failed_count+1))
            tput cuu $((current_index+1))
            tput cuf $((prompt_width+3))
            inquirer:print "${bg_black}${red}${checkbox_input_failed_msg}${normal}"
            tput rc
        else
            tput cud $((page_list_count-current_index))

            for i in $(seq $((page_list_count+1)))
            do
                tput el
                tput cuu1
            done

            tput cuf $((prompt_width+3))
            inquirer:print "${bg_black}${cyan}$(inquirer:join checkbox_selected_options)${normal}\n"

            break_keypress=true
        fi
    }

    inquirer:on_checkbox_input_space() {
        if [ "$input_search" = true ] 
        then
            inquirer:on_text_input_ascii
            return
        fi

        local i

        inquirer:remove_instructions
        tput cub "$(tput cols)"
        tput el

        if [ "$current_index" -eq $((page_list_count-1)) ] 
        then
            if [ "${checkbox_page_selected[current_index]}" = true ]
            then
                tput cuu $current_index
                for i in "${!page_list[@]}"
                do
                    if [ "$i" -eq "$current_index" ]
                    then
                        inquirer:print "${cyan}${arrow}${normal}${unchecked} ${page_list[i]}"
                    else
                        inquirer:print " ${unchecked} ${page_list[i]}\n"
                        checkbox_selected[i+pages_index*list_perpage]=false
                    fi
                    checkbox_page_selected[i]=false
                done
            else
                tput cuu $current_index
                for i in "${!page_list[@]}"
                do
                    if [ "$i" -eq "$current_index" ]
                    then
                        inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${page_list[i]}"
                    else
                        inquirer:print " ${green}${checked}${normal} ${page_list[i]}\n"
                        checkbox_selected[i+pages_index*list_perpage]=true
                    fi
                    checkbox_page_selected[i]=true
                done
            fi
        else
            if [ "${checkbox_page_selected[current_index]}" = true ]
            then
                checkbox_page_selected[current_index]=false
                checkbox_selected[current_index+pages_index*list_perpage]=false
                inquirer:print "${cyan}${arrow}${normal}${unchecked} ${page_list[current_index]}"
            else
                checkbox_page_selected[current_index]=true
                checkbox_selected[current_index+pages_index*list_perpage]=true
                inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${page_list[current_index]}"
            fi
        fi
    }

    inquirer:on_checkbox_input_ascii() {
        local key=$1

        if [ "$input_search" = false ] 
        then
            case "$key" in
                "w" ) 
                    inquirer:on_checkbox_input_up
                    return
                ;;
                "s" ) 
                    inquirer:on_checkbox_input_down
                    return
                ;;
                "a" ) 
                    inquirer:on_checkbox_input_left
                    return
                ;;
                "d" ) 
                    inquirer:on_checkbox_input_right
                    return
                ;;
            esac
            if [ "$key" == "/" ]
            then
                if [ "$pages_count" -eq 1 ] 
                then
                    return
                fi

                input_search=true
                text_input=""
                current_pos=0

                tput cub "$(tput cols)"
                tput cud $((list_perpage-current_index+1))

                for((i=0;i<=list_perpage;i++));
                do
                    tput el
                    tput cuu1
                done

                tput el
                tput cud1

                inquirer:print "${green}?${normal} ${bold}${bg_black}${white}$(gettext "输入搜索内容")${bold} ${dim}( $arrow_up $(gettext "返回"))${normal}\n"

                stty -echo
                tput cnorm
            elif [[ "$key" =~ [0-9Pp] ]]
            then
                inquirer:on_input_page "$key"
            fi
            return
        fi

        inquirer:on_text_input_ascii "$key"
    }

    inquirer:on_checkbox_input_not_ascii() {
        if [ "$input_search" = false ] 
        then
            return
        fi

        inquirer:on_text_input_not_ascii "$1"
    }

    inquirer:on_checkbox_input_backspace() {
        if [ "$input_search" = false ] 
        then
            return
        fi

        inquirer:on_text_input_backspace
    }

    inquirer:_checkbox_input() {
        local i var=("$2"[@])
        list_perpage=${4:-$list_perpage}
        checkbox_list=("${!var}")
        list_count=${#checkbox_list[@]}

        if [ "$list_count" -eq 1 ] 
        then
            checkbox_selected_options=("${checkbox_list[@]}")
            checkbox_selected_indices=(0)

            inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${bg_black}${cyan}$(inquirer:join checkbox_selected_options)${normal}\n"
            return
        fi

        checkbox_selected=()
        checkbox_selected_indices=()
        checkbox_selected_options=()
        checkbox_input_failed_msg=$(gettext "选择不能为空")
        current_index=0
        failed_count=0
        first_keystroke=true

        trap inquirer:control_c EXIT

        stty -echo
        tput civis

        if [ "$list_perpage" -gt 0 ] && [ "$list_count" -gt "$list_perpage" ] 
        then
            pages_count=$((list_count/list_perpage))
            if [[ $((list_perpage*pages_count)) -lt "$list_count" ]] 
            then
                pages_count=$((pages_count+1))
            fi
            pages_tip="${dim}$pages_arrows $((pages_index+1))/$pages_count `gettext \"页\"`${normal} "
        fi

        inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${pages_tip:-}${dim}`gettext \"(按 <space> 选择, <enter> 确认)\"`${normal}\n"

        for i in "${!checkbox_list[@]}"
        do
            checkbox_selected[i]=false
        done

        var=("$3"[@])
        if [[ -n ${!var:-} ]] 
        then
            checkbox_selected_indices=("${!var}")
            for i in "${checkbox_selected_indices[@]}"
            do
                checkbox_selected[i]=true
            done
            checkbox_selected_indices=()
        fi

        for i in "${!checkbox_list[@]}"
        do
            if [ "$i" = 0 ]
            then
                if [ "${checkbox_selected[i]}" = true ]
                then
                    inquirer:print "${cyan}${arrow}${green}${checked}${normal} ${checkbox_list[i]}\n"
                else
                    inquirer:print "${cyan}${arrow}${normal}${unchecked} ${checkbox_list[i]}\n"
                fi
            elif [ "$pages_count" -gt 1 ] && [ "$i" = "$list_perpage" ] 
            then
                break
            else
                if [ "${checkbox_selected[i]}" = true ]
                then
                    inquirer:print " ${green}${checked}${normal} ${checkbox_list[i]}\n"
                else
                    inquirer:print " ${unchecked} ${checkbox_list[i]}\n"
                fi
            fi
            page_list_count=$((page_list_count+1))
            page_list+=("${checkbox_list[i]}")
        done

        for((i=0;i<page_list_count;i++));
        do
            if [ "${checkbox_selected[i]}" = true ] 
            then
                checkbox_page_selected+=("true")
            else
                checkbox_page_selected+=("false")
                checkbox_page_select_all=false
            fi
        done

        page_list+=("$(gettext 全选)")
        page_list_count=$((page_list_count+1))

        if [ "$checkbox_page_select_all" = true ] 
        then
            checkbox_page_selected+=("true")
            inquirer:print " ${green}${checked}${normal} ${page_list[page_list_count-1]}\n"
        else
            checkbox_page_selected+=("false")
            inquirer:print " ${unchecked} ${page_list[page_list_count-1]}\n"
        fi

        tput cuu $page_list_count

        inquirer:on_keypress inquirer:on_checkbox_input_up inquirer:on_checkbox_input_down inquirer:on_checkbox_input_space inquirer:on_checkbox_input_enter inquirer:on_checkbox_input_left inquirer:on_checkbox_input_right inquirer:on_checkbox_input_ascii inquirer:on_checkbox_input_backspace inquirer:on_checkbox_input_not_ascii
    }

    inquirer:checkbox_input() {
        var_name=$3

        inquirer:_checkbox_input "$1" "$2" "$var_name" "${4:-}"

        read -r -a ${var_name?} <<< "${checkbox_selected_options[@]}"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:checkbox_input_indices() {
        var_name=$3

        inquirer:_checkbox_input "$1" "$2" "$var_name" "${4:-}"

        read -r -a ${var_name?} <<< "${checkbox_selected_indices[@]}"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:on_sort_up() {
        if [ "${#sort_options[@]}" -eq 1 ]
        then
            return
        fi

        tput cub "$(tput cols)"

        inquirer:print "  ${sort_options[current_index]}"

        if [ $current_index = 0 ]
        then
            current_index=$((${#sort_options[@]}-1))
            tput cud $((${#sort_options[@]}-1))
        else
            current_index=$((current_index-1))
            tput cuu1
        fi

        tput cub "$(tput cols)"

        inquirer:print "${cyan}${arrow} ${sort_options[current_index]} ${normal}"
    }

    inquirer:on_sort_down() {
        if [ "${#sort_options[@]}" -eq 1 ]
        then
            return
        fi

        tput cub "$(tput cols)"

        inquirer:print "  ${sort_options[current_index]}"

        if [ $current_index = $((${#sort_options[@]}-1)) ]
        then
            current_index=0
            tput cuu $((${#sort_options[@]}-1))
        else
            current_index=$((current_index+1))
            tput cud1
        fi

        tput cub "$(tput cols)"

        inquirer:print "${cyan}${arrow} ${sort_options[current_index]} ${normal}"
    }

    inquirer:on_sort_move_up() {
        if [ "${#sort_options[@]}" -eq 1 ]
        then
            return
        fi

        local i

        tput cub "$(tput cols)"

        if [ $current_index = 0 ]
        then
            for((i=1;i<${#sort_options[@]};i++));
            do
                inquirer:print "  ${sort_options[i]}\n"
            done
            inquirer:print "${cyan}${arrow} ${sort_options[current_index]} ${normal}"
            current_index=$((${#sort_options[@]}-1))
            sort_options=( "${sort_options[@]:1}" "${sort_options[@]:0:1}" )
            sort_indices=( "${sort_indices[@]:1}" "${sort_indices[@]:0:1}" )
        else
            inquirer:print "  ${sort_options[current_index-1]}"
            tput cuu1
            tput cub "$(tput cols)"
            inquirer:print "${cyan}${arrow} ${sort_options[current_index]} ${normal}"
            local tmp="${sort_options[current_index]}"
            sort_options[current_index]="${sort_options[current_index-1]}"
            sort_options[current_index-1]="$tmp"
            tmp="${sort_indices[current_index]}"
            sort_indices[current_index]="${sort_indices[current_index-1]}"
            sort_indices[current_index-1]="$tmp"
            current_index=$((current_index-1))
        fi
    }

    inquirer:on_sort_move_down() {
        if [ "${#sort_options[@]}" -eq 1 ]
        then
            return
        fi

        local i

        tput cub "$(tput cols)"

        if [ $current_index = $((${#sort_options[@]}-1)) ]
        then
            tput cuu $((${#sort_options[@]}-1))
            inquirer:print "${cyan}${arrow} ${sort_options[current_index]} ${normal}\n"
            for((i=0;i<current_index;i++));
            do
                inquirer:print "  ${sort_options[i]}\n"
            done
            tput cuu ${#sort_options[@]}
            sort_options=( "${sort_options[@]:current_index}" "${sort_options[@]:0:current_index}" )
            sort_indices=( "${sort_indices[@]:current_index}" "${sort_indices[@]:0:current_index}" )
            current_index=0
        else
            inquirer:print "  ${sort_options[current_index+1]}"
            tput cud1
            tput cub "$(tput cols)"
            inquirer:print "${cyan}${arrow} ${sort_options[current_index]} ${normal}"
            local tmp="${sort_options[current_index]}"
            sort_options[current_index]="${sort_options[current_index+1]}"
            sort_options[current_index+1]="$tmp"
            tmp="${sort_indices[current_index]}"
            sort_indices[current_index]="${sort_indices[current_index+1]}"
            sort_indices[current_index+1]="$tmp"
            current_index=$((current_index+1))
        fi
    }

    inquirer:on_sort_ascii() {
        case "$1" in
            "w" ) inquirer:on_sort_move_up;;
            "s" ) inquirer:on_sort_move_down;;
        esac
    }

    inquirer:on_sort_enter_space() {
        local i

        tput cud $((${#sort_options[@]}-current_index))
        tput cub "$(tput cols)"

        for i in $(seq $((${#sort_options[@]}+1)))
        do
            tput el
            tput cuu1
        done

        tput cuf $((prompt_width+3))
        inquirer:print "${bg_black}${cyan}$(inquirer:join sort_options)${normal}\n"

        break_keypress=true
    }

    inquirer:_sort_input() {
        local i var=("$2"[@])
        sort_options=("${!var}")
        sort_indices=("${!sort_options[@]}")

        current_index=0

        trap inquirer:control_c EXIT

        stty -echo
        tput civis

        inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${dim}`gettext \"(上下箭头选择, 按 <w> <s> 上下移动)\"`${normal}\n"

        for i in "${!sort_options[@]}"
        do
            if [ $i = 0 ]
            then
                inquirer:print "${cyan}${arrow} ${sort_options[i]} ${normal}\n"
            else
                inquirer:print "  ${sort_options[i]}\n"
            fi
        done

        tput cuu ${#sort_options[@]}

        inquirer:on_keypress inquirer:on_sort_up inquirer:on_sort_down inquirer:on_sort_enter_space inquirer:on_sort_enter_space inquirer:on_default inquirer:on_default inquirer:on_sort_ascii
    }

    inquirer:sort_input() {
        var_name=$3

        inquirer:_sort_input "$1" "$2"

        read -r -a ${var_name?} <<< "${sort_options[@]}"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:sort_input_indices() {
        var_name=$3

        inquirer:_sort_input "$1" "$2"

        read -r -a ${var_name?} <<< "${sort_indices[@]}"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:on_list_input_up() {
        if [ "$input_search" = true ] 
        then
            tput cub "$(tput cols)"
            tput el
            tput cuu1
            tput el
            tput cuu1
            tput el

            stty -echo
            tput civis

            local i

            for((i=0;i<page_list_count;i++));
            do
                if [ "$i" = "$current_index" ] 
                then
                    inquirer:print "${cyan}${arrow} ${page_list[i]} ${normal}\n"
                else
                    inquirer:print "  ${page_list[i]}\n"
                fi
            done

            tput cuu $((page_list_count-current_index))

            input_search=false
            return
        fi

        inquirer:remove_instructions

        tput cub "$(tput cols)"

        inquirer:print "  ${page_list[current_index]}"

        if [ $current_index = 0 ]
        then
            current_index=$((page_list_count-1))
            tput cud $((page_list_count-1))
        else
            current_index=$((current_index-1))
            tput cuu1
        fi

        tput cub "$(tput cols)"

        inquirer:print "${cyan}${arrow} ${page_list[current_index]}${normal}"
    }

    inquirer:on_list_input_down() {
        if [ "$input_search" = true ] 
        then
            return
        fi

        inquirer:remove_instructions

        tput cub "$(tput cols)"

        inquirer:print "  ${page_list[current_index]}"

        if [ $current_index = $((page_list_count-1)) ]
        then
            current_index=0
            tput cuu $((page_list_count-1))
        else
            current_index=$((current_index+1))
            tput cud1
        fi

        tput cub "$(tput cols)"

        inquirer:print "${cyan}${arrow} ${page_list[current_index]} ${normal}"
    }

    inquirer:on_list_input_left() {
        if [ -z "${pages_tip:-}" ] 
        then
            return
        fi

        if [ "$input_search" = true ] 
        then
            inquirer:on_text_input_left
            return
        fi

        local i

        if [ "$pages_index" -eq 0 ] 
        then
            pages_index=$((pages_count-1))
            page_list_count=$((list_count-list_perpage*pages_index))
        else
            pages_index=$((pages_index-1))
            page_list_count=$list_perpage
        fi

        pages_tip="${dim}$pages_arrows $((pages_index+1))/$pages_count `gettext \"页\"`${normal}"

        inquirer:page_instructions
        tput cub "$(tput cols)"
        tput cud $((list_perpage-current_index))

        for((i=0;i<list_perpage;i++));
        do
            tput el
            tput cuu1
        done

        tput el

        if [ "$current_index" -ge "$page_list_count" ] 
        then
            current_index=$((page_list_count-1))
        fi

        page_list=()

        for((i=0;i<page_list_count;i++));
        do
            page_list+=("${list_options[i+list_perpage*pages_index]}")

            if [ "$i" = "$current_index" ] 
            then
                inquirer:print "${cyan}${arrow} ${page_list[i]} ${normal}\n"
            else
                inquirer:print "  ${page_list[i]}\n"
            fi
        done

        tput cuu $((page_list_count-current_index))
    }

    inquirer:on_list_input_right() {
        if [ -z "${pages_tip:-}" ] 
        then
            return
        fi

        if [ "$input_search" = true ] 
        then
            inquirer:on_text_input_right
            return
        fi

        local i

        if [ "$pages_index" -eq $((pages_count-1)) ] 
        then
            pages_index=0
            page_list_count=$list_perpage
        else
            pages_index=$((pages_index+1))
            if [ "$pages_index" -eq $((pages_count-1)) ] 
            then
                page_list_count=$((list_count-pages_index*list_perpage))
            else
                page_list_count=$list_perpage
            fi
        fi

        pages_tip="${dim}$pages_arrows $((pages_index+1))/$pages_count `gettext \"页\"`${normal}"

        inquirer:page_instructions
        tput cub "$(tput cols)"
        tput cud $((list_perpage-current_index))

        for((i=0;i<list_perpage;i++));
        do
            tput el
            tput cuu1
        done

        tput el

        if [ "$current_index" -ge "$page_list_count" ] 
        then
            current_index=$((page_list_count-1))
        fi

        page_list=()

        for((i=0;i<page_list_count;i++));
        do
            page_list+=("${list_options[i+list_perpage*pages_index]}")

            if [ "$i" = "$current_index" ] 
            then
                inquirer:print "${cyan}${arrow} ${page_list[i]} ${normal}\n"
            else
                inquirer:print "  ${page_list[i]}\n"
            fi
        done

        tput cuu $((page_list_count-current_index))
    }

    inquirer:on_list_input_space() {
        if [ "$input_search" = true ] 
        then
            inquirer:on_text_input_ascii
            return
        fi

        local i

        tput cud $((page_list_count-current_index))
        tput cub "$(tput cols)"

        for i in $(seq $((page_list_count+1)))
        do
            tput el
            tput cuu1
        done

        tput cuf $((prompt_width+3))
        inquirer:print "${bg_black}${cyan}${page_list[current_index]}${normal}\n"

        break_keypress=true
    }

    inquirer:on_list_input_enter() {
        local i

        if [ "$input_search" = true ] 
        then
            if [ -n "$text_input" ] 
            then
                tput cub "$(tput cols)"
                tput el
                tput cuu1
                tput el
                tput cuu1
                tput el
                tput cuu1
                tput el
                tput cud1

                local list_page

                for i in "${!list_options[@]}"
                do
                    if [[ "${list_options[i]}" =~ "$text_input" ]] 
                    then
                        list_page=$((i/list_perpage+1))
                        inquirer:print "${green}P${list_page}${normal} ${list_options[i]}\n"
                    fi
                done

                if [ -n "${list_page:-}" ] 
                then
                    tput cud1
                fi

                inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${pages_tip:-}${dim}`gettext \"(使用上下箭头选择)\"`${normal}\n\n\n"
            fi
            inquirer:on_list_input_up
            return
        fi

        if [ "$input_page" = true ] 
        then
            input_page=false
            if [ -n "${input_page_num:-}" ] 
            then
                if [ "$input_page_num" -gt "$pages_count" ] || [ "$input_page_num" -eq $((pages_index+1)) ]
                then
                    input_page_num=""
                    return
                fi

                pages_index=$((input_page_num-1))

                pages_tip="${dim}$pages_arrows $((pages_index+1))/$pages_count `gettext \"页\"`${normal}"

                if [ "$input_page_num" -eq "$pages_count" ] 
                then
                    page_list_count=$((list_count-pages_index*list_perpage))
                else
                    page_list_count=$list_perpage
                fi

                inquirer:page_instructions
                tput cub "$(tput cols)"
                tput cud $((list_perpage-current_index+1))

                for((i=0;i<=list_perpage;i++));
                do
                    tput el
                    tput cuu1
                done

                tput el

                if [ "$current_index" -ge "$page_list_count" ] 
                then
                    current_index=$((page_list_count-1))
                fi

                page_list=()

                for((i=0;i<page_list_count;i++));
                do
                    page_list+=("${list_options[i+list_perpage*pages_index]}")

                    if [ "$i" = "$current_index" ] 
                    then
                        inquirer:print "${cyan}${arrow} ${page_list[i]} ${normal}\n"
                    else
                        inquirer:print "  ${page_list[i]}\n"
                    fi
                done

                tput cuu $((page_list_count-current_index))

                input_page_num=""
            fi
            return
        fi

        tput cud $((page_list_count-current_index))
        tput cub "$(tput cols)"

        for i in $(seq $((page_list_count+1)))
        do
            tput el
            tput cuu1
        done

        tput cuf $((prompt_width+3))
        inquirer:print "${bg_black}${cyan}${page_list[current_index]}${normal}\n"

        break_keypress=true
    }

    inquirer:on_list_input_ascii() {
        local key=$1

        if [ "$input_search" = false ] 
        then
            case "$key" in
                "w" ) 
                    inquirer:on_list_input_up
                    return
                ;;
                "s" ) 
                    inquirer:on_list_input_down
                    return
                ;;
                "a" ) 
                    inquirer:on_list_input_left
                    return
                ;;
                "d" ) 
                    inquirer:on_list_input_right
                    return
                ;;
            esac
            if [ "$key" == "/" ]
            then
                if [ "$pages_count" -eq 1 ] 
                then
                    return
                fi

                input_search=true
                text_input=""
                current_pos=0

                tput cub "$(tput cols)"
                tput cud $((list_perpage-current_index+1))

                for((i=0;i<=list_perpage;i++));
                do
                    tput el
                    tput cuu1
                done

                tput el
                tput cud1

                inquirer:print "${green}?${normal} ${bold}${bg_black}${white}$(gettext "输入搜索内容")${bold} ${dim}( $arrow_up $(gettext "返回"))${normal}\n"

                stty -echo
                tput cnorm
            elif [[ "$key" =~ [0-9Pp] ]]
            then
                inquirer:on_input_page "$key"
            fi
            return
        fi

        inquirer:on_text_input_ascii "$key"
    }

    inquirer:on_list_input_not_ascii() {
        if [ "$input_search" = false ] 
        then
            return
        fi

        inquirer:on_text_input_not_ascii "$1"
    }

    inquirer:on_list_input_backspace() {
        if [ "$input_search" = false ] 
        then
            return
        fi

        inquirer:on_text_input_backspace
    }

    inquirer:_list_input() {
        local i var=("$2"[@])
        list_perpage=${3:-$list_perpage}
        list_options=("${!var}")
        list_count=${#list_options[@]}
        current_index=0

        if [ "$list_count" -eq 1 ] 
        then
            inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${bg_black}${cyan}${list_options[current_index]}${normal}\n"
            page_list=("${list_options[@]}")
            return
        fi

        first_keystroke=true

        trap inquirer:control_c EXIT

        stty -echo
        tput civis

        if [ "$list_perpage" -gt 0 ] && [ "$list_count" -gt "$list_perpage" ] 
        then
            pages_count=$((list_count/list_perpage))
            if [[ $((list_perpage*pages_count)) -lt "$list_count" ]] 
            then
                pages_count=$((pages_count+1))
            fi
            pages_tip="${dim}$pages_arrows $((pages_index+1))/$pages_count `gettext \"页\"`${normal} "
        fi

        inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${pages_tip:-}${dim}`gettext \"(使用上下箭头选择)\"`${normal}\n"

        for i in "${!list_options[@]}"
        do
            if [ $i = 0 ]
            then
                inquirer:print "${cyan}${arrow} ${list_options[i]} ${normal}\n"
            elif [ "$pages_count" -gt 1 ] && [ "$i" = "$list_perpage" ] 
            then
                break
            else
                inquirer:print "  ${list_options[i]}\n"
            fi
            page_list_count=$((page_list_count+1))
            page_list+=("${list_options[i]}")
        done

        tput cuu $page_list_count

        inquirer:on_keypress inquirer:on_list_input_up inquirer:on_list_input_down inquirer:on_list_input_space inquirer:on_list_input_enter inquirer:on_list_input_left inquirer:on_list_input_right inquirer:on_list_input_ascii inquirer:on_list_input_backspace inquirer:on_list_input_not_ascii
    }

    inquirer:list_input() {
        var_name=$3

        inquirer:_list_input "$1" "$2" ${4:-$list_perpage}

        read -r ${var_name?} <<< "${page_list[current_index]}"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:list_input_yn() {
        var_name=$3
        local hidden_var=("$2"[@])
        local hidden_options=("${!hidden_var}")

        inquirer:_list_input "$1" yn_options

        read -r ${var_name?} <<< "${hidden_options[current_index]}"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:list_input_ny() {
        var_name=$3
        local hidden_var=("$2"[@])
        local hidden_options=("${!hidden_var}")

        inquirer:_list_input "$1" ny_options

        read -r ${var_name?} <<< "${hidden_options[current_index]}"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:list_input_index() {
        var_name=$3

        inquirer:_list_input "$1" "$2" ${4:-$list_perpage}

        read -r ${var_name?} <<< "$((list_perpage*pages_index+current_index))"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:on_text_input_left() {
        if [[ $current_pos -gt 0 ]]
        then
            local current=${text_input:$current_pos:1} current_width
            current_width=$(inquirer:display_length "$current")

            tput cub $current_width
            current_pos=$((current_pos-1))
        fi
    }

    inquirer:on_text_input_right() {
        if [[ $((current_pos+1)) -eq ${#text_input} ]] 
        then
            tput cuf1
            current_pos=$((current_pos+1))
        elif [[ $current_pos -lt ${#text_input} ]]
        then
            local next=${text_input:$((current_pos+1)):1} next_width
            next_width=$(inquirer:display_length "$next")

            tput cuf $next_width
            current_pos=$((current_pos+1))
        fi
    }

    inquirer:on_text_input_enter() {
        local validate_failed_msg

        text_input=${text_input:-$text_default}

        if [ "$text_default" == "$i18n_blank" ] && [ "$text_input" == "$i18n_blank" ]
        then
            text_input=""
        fi

        tput civis
        tput cub "$(tput cols)"
        tput el

        if validate_failed_msg=$($text_input_validator "$text_input")
        then
            tput sc
            tput cuu $((1+failed_count*3))
            tput cuf $((prompt_width+3))
            inquirer:print "${bg_black}${cyan}"
            inquirer:print_input "${text_input:-$text_default}"
            inquirer:print "${normal}"
            tput rc
            break_keypress=true
        else
            failed_count=$((failed_count+1))
            tput cud1
            inquirer:print "${bg_black}${red}${validate_failed_msg:-$text_input_validate_failed_msg}${normal}\n"
            tput cud1
            if [ "$text_input:-$text_default" == "$text_default" ] 
            then
                text_input=""
                current_pos=0
            else
                inquirer:print_input "${text_input}"
                tput cub "$(tput cols)"
                tput cuf "$current_pos"
            fi
        fi

        tput cnorm
    }

    inquirer:on_text_input_ascii() {
        local c=${1:- }
        local rest=${text_input:$current_pos} rest_width
        local current=${text_input:$current_pos:1} current_width

        rest_width=$(inquirer:display_length "$rest")
        current_width=$(inquirer:display_length "$current")
        text_input="${text_input:0:$current_pos}$c$rest"
        current_pos=$((current_pos+1))

        tput civis

        [[ $current_width -gt 1 ]] && tput cub $((current_width-1))

        inquirer:print_input "$c$rest"

        if [[ $rest_width -gt 0 ]]
        then
            tput cub $((rest_width-current_width+1))
        fi

        tput cnorm
    }

    inquirer:on_text_input_not_ascii() {
        local c=$1
        local rest="${text_input:$current_pos}" rest_width
        local current=${text_input:$current_pos:1} current_width

        rest_width=$(inquirer:display_length "$rest")
        current_width=$(inquirer:display_length "$current")
        text_input="${text_input:0:$current_pos}$c$rest"
        current_pos=$((current_pos+1))

        tput civis

        [[ $current_width -gt 1 ]] && tput cub $((current_width-1))

        inquirer:print_input "$c$rest"

        if [[ $rest_width -gt 0 ]]
        then
            tput cub $((rest_width-current_width+1))
        fi

        tput cnorm
    }

    inquirer:on_text_input_backspace() {
        if [ $current_pos -gt 0 ] || { [ $current_pos -eq 0 ] && [ "${#text_input}" -gt 0 ]; }
        then
            local start rest rest_width del del_width next next_width offset
            local current=${text_input:$current_pos:1} current_width
            current_width=$(inquirer:display_length "$current")

            tput civis
            if [ $current_pos -eq 0 ] 
            then
                rest=${text_input:$((current_pos+1))}
                next=${text_input:$((current_pos+1)):1}
                rest_width=$(inquirer:display_length "$rest")
                next_width=$(inquirer:display_length "$next")
                offset=$((current_width-1))
                [[ $offset -gt 0 ]] && tput cub $offset
                inquirer:print_input "$rest"
                offset=$((rest_width-next_width+1))
                [[ $offset -gt 0 ]] && tput cub $offset
                text_input="$rest"
            else
                rest=${text_input:$current_pos}
                start=${text_input:0:$((current_pos-1))}
                del=${text_input:$((current_pos-1)):1}
                rest_width=$(inquirer:display_length "$rest")
                del_width=$(inquirer:display_length "$del")
                current_pos=$((current_pos-1))
                if [[ $current_width -gt 1 ]] 
                then
                    tput cub $((del_width+current_width-1))
                    inquirer:print_input "$rest"
                    tput cub $((rest_width-current_width+1))
                else
                    tput cub $del_width
                    inquirer:print_input "$rest"
                    [[ $rest_width -gt 0 ]] && tput cub $((rest_width-current_width+1))
                fi
                text_input="$start$rest"
            fi
            tput cnorm
        fi
    }

    inquirer:text_input_default_validator() {
        return
    }

    inquirer:text_input() {
        var_name=$2
        text_default=${3:-}
        text_input=""
        current_pos=0
        failed_count=0
        local text_default_tip

        if [ -n "$text_default" ] 
        then
            text_default_tip=" ${bold}${dim}($text_default)${normal}"
        else
            text_default_tip="${normal}"
        fi

        text_input_validator=${4:-inquirer:text_input_default_validator}
        text_input_validate_failed_msg=${5:-$(gettext "输入验证错误")}

        inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt}${text_default_tip}\n"

        trap inquirer:control_c EXIT

        # stty -echo
        # tput cnorm
        # inquirer:on_keypress inquirer:on_default inquirer:on_default inquirer:on_text_input_ascii inquirer:on_text_input_enter inquirer:on_text_input_left inquirer:on_text_input_right inquirer:on_text_input_ascii inquirer:on_text_input_backspace inquirer:on_text_input_not_ascii

        # read -r ${var_name?} <<< "$text_input"

        while true 
        do
            read -e text_input

            text_input=${text_input:-$text_default}

            if [ "$text_default" == "$i18n_blank" ] && [ "$text_input" == "$i18n_blank" ]
            then
                text_input=""
            fi

            if validate_failed_msg=$($text_input_validator "$text_input")  
            then
                break
            fi

            inquirer:print "\n${bg_black}${red}${validate_failed_msg:-$text_input_validate_failed_msg}${normal}\n\n"
        done

        read -r ${var_name?} <<< "$text_input"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:date_pick_default_validator() {
        if ! date +%s -d "$1" > /dev/null 2>&1
        then
            return 1
        fi
        return
    }

    inquirer:remove_date_instructions() {
        if [ "$first_keystroke" = true ]
        then
            tput sc
            tput civis
            tput cuu 1
            tput cub "$(tput cols)"
            tput cuf $((prompt_width+3))
            tput el
            tput rc
            tput cnorm
            first_keystroke=false
        fi
    }

    inquirer:on_date_pick_ascii() {
        case "$1" in
            "w" ) inquirer:on_date_pick_up;;
            "s" ) inquirer:on_date_pick_down;;
            "a" ) inquirer:on_date_pick_left;;
            "d" ) inquirer:on_date_pick_right;;
        esac
    }

    inquirer:on_date_pick_up() {
        inquirer:remove_date_instructions
        case $current_pos in
            3)  date_pick="$((${date_pick:0:4}+1))${date_pick:4}"
            ;;
            6) 
                local month=$((10#${date_pick:5:2}+1))
                [ "$month" -eq 13 ] && month=1
                date_pick="${date_pick:0:5}$(printf %02d "$month")${date_pick:7}"
            ;;
            9) 
                local day=$((10#${date_pick:8:2}+1))
                [ "$day" -eq 32 ] && day=1
                date_pick="${date_pick:0:8}$(printf %02d "$day")${date_pick:10}"
            ;;
            12) 
                local hour=$(((10#${date_pick:11:2}+1)%24))
                date_pick="${date_pick:0:11}$(printf %02d "$hour")${date_pick:13}"
            ;;
            15) 
                local min=$(((10#${date_pick:14:2}+1)%60))
                date_pick="${date_pick:0:14}$(printf %02d "$min")${date_pick:16}"
            ;;
            18) 
                local sec=$(((10#${date_pick:17:2}+1)%60))
                date_pick="${date_pick:0:17}$(printf %02d "$sec")${date_pick:19}"
            ;;
        esac

        tput sc
        tput civis
        tput cub $current_pos
        inquirer:print "$date_pick"
        tput rc
        tput cnorm
    }

    inquirer:on_date_pick_down() {
        inquirer:remove_date_instructions
        case $current_pos in
            3)  
                local year=$((${date_pick:0:4}-1))
                [ "$year" -eq 2020 ] && return
                date_pick="$year${date_pick:4}"
            ;;
            6) 
                local month=$((10#${date_pick:5:2}-1))
                [ "$month" -eq 0 ] && month=12
                date_pick="${date_pick:0:5}$(printf %02d "$month")${date_pick:7}"
            ;;
            9) 
                local day=$((10#${date_pick:8:2}-1))
                [ "$day" -eq 0 ] && day=31
                date_pick="${date_pick:0:8}$(printf %02d "$day")${date_pick:10}"
            ;;
            12) 
                local hour=$(((10#${date_pick:11:2}+23)%24))
                date_pick="${date_pick:0:11}$(printf %02d "$hour")${date_pick:13}"
            ;;
            15) 
                local min=$(((10#${date_pick:14:2}+59)%60))
                date_pick="${date_pick:0:14}$(printf %02d "$min")${date_pick:16}"
            ;;
            18) 
                local sec=$(((10#${date_pick:17:2}+59)%60))
                date_pick="${date_pick:0:17}$(printf %02d "$sec")${date_pick:19}"
            ;;
        esac

        tput sc
        tput civis
        tput cub $current_pos
        inquirer:print "$date_pick"
        tput rc
        tput cnorm
    }

    inquirer:on_date_pick_left() {
        inquirer:remove_date_instructions
        if [[ $current_pos -gt 3 ]] 
        then
            tput cub 3
            current_pos=$((current_pos-3))
        fi
    }

    inquirer:on_date_pick_right() {
        inquirer:remove_date_instructions
        if [[ $current_pos -lt 18 ]] 
        then
            tput cuf 3
            current_pos=$((current_pos+3))
        fi
    }

    inquirer:on_date_pick_enter_space() {
        tput civis
        tput cub $current_pos
        tput el

        if $date_pick_validator "$date_pick"
        then
            tput sc
            tput cuu $((1+failed_count*3))
            tput cuf $((prompt_width+3))
            inquirer:print "${bg_black}${cyan}${date_pick}${normal}"
            tput rc
            break_keypress=true
        else
            failed_count=$((failed_count+1))
            tput cud1
            inquirer:print "${bg_black}${red}${date_pick_validate_failed_msg}${normal}\n"
            tput cud1
            inquirer:print "${date_pick}"
            tput cub $((19-current_pos))
        fi

        tput cnorm
    }

    inquirer:date_pick() {
        var_name=$2
        date_pick_validator=${3:-inquirer:date_pick_default_validator}
        date_pick_validate_failed_msg=${4:-$(gettext "时间验证错误")}
        PrintfTime date_pick '%Y-%m-%d %H:%M:%S' "${!var_name:--1}"
        current_pos=12
        failed_count=0
        first_keystroke=true

        inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${dim}`gettext \"(使用箭头选择)\"`${normal}\n"
        inquirer:print "$date_pick"
        tput cub 7

        trap inquirer:control_c EXIT

        stty -echo
        tput cnorm

        inquirer:on_keypress inquirer:on_date_pick_up inquirer:on_date_pick_down inquirer:on_date_pick_enter_space inquirer:on_date_pick_enter_space inquirer:on_date_pick_left inquirer:on_date_pick_right inquirer:on_date_pick_ascii
        read -r ${var_name?} <<< $(date +%s -d "$date_pick")

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:remove_color_instructions() {
        if [ "$first_keystroke" = true ]
        then
            tput cuu 1
            tput cub "$(tput cols)"
            tput cuf $((prompt_width+3))
            tput el
            tput cud 1
            first_keystroke=false
        fi
    }

    inquirer:on_color_pick_ascii() {
        case "$1" in
            "w" ) inquirer:on_color_pick_up;;
            "s" ) inquirer:on_color_pick_down;;
            "a" ) inquirer:on_color_pick_left;;
            "d" ) inquirer:on_color_pick_right;;
        esac
    }

    inquirer:on_color_pick_up() {
        inquirer:remove_color_instructions
        tput cub "$(tput cols)"
        colors_index=$(((colors_index+1)%16))
        inquirer:print "${bg_colors[bg_colors_index]}${colors[colors_index]}$text_default${normal}"
    }

    inquirer:on_color_pick_down() {
        inquirer:remove_color_instructions
        tput cub "$(tput cols)"
        colors_index=$(((colors_index-1)%16))
        inquirer:print "${bg_colors[bg_colors_index]}${colors[colors_index]}$text_default${normal}"
    }

    inquirer:on_color_pick_left() {
        inquirer:remove_color_instructions
        tput cub "$(tput cols)"
        bg_colors_index=$(((bg_colors_index-1)%17))
        inquirer:print "${bg_colors[bg_colors_index]}${colors[colors_index]}$text_default${normal}"
    }

    inquirer:on_color_pick_right() {
        inquirer:remove_color_instructions
        tput cub "$(tput cols)"
        bg_colors_index=$(((bg_colors_index+1)%17))
        inquirer:print "${bg_colors[bg_colors_index]}${colors[colors_index]}$text_default${normal}"
    }

    inquirer:on_color_pick_enter_space() {
        tput cub "$(tput cols)"
        tput el
        tput sc
        tput cuu 1
        tput cuf $((prompt_width+3))
        inquirer:print "${bg_colors[bg_colors_index]}${colors[colors_index]}$text_default${normal}"
        tput rc
        break_keypress=true

        tput cnorm
    }

    inquirer:color_pick() {
        var_name=$2
        text_default="${3:-$(gettext "示例文字 ABC 123")}"
        colors=( '\033[30m' '\033[31m' '\033[32m' '\033[33m' '\033[34m' '\033[35m' '\033[36m' '\033[37m' 
            '\033[90m' '\033[91m' '\033[92m' '\033[93m' '\033[94m' '\033[95m' '\033[96m' '\033[97m' )
        bg_colors=( '' '\033[40m' '\033[41m' '\033[42m' '\033[43m' '\033[44m' '\033[45m' '\033[46m' '\033[47m' 
            '\033[100m' '\033[101m' '\033[102m' '\033[103m' '\033[104m' '\033[105m' '\033[106m' '\033[107m' )
        colors_index=7
        bg_colors_index=0
        first_keystroke=true

        inquirer:print "${green}?${normal} ${bold}${bg_black}${white}${prompt} ${dim}`gettext \"(上下/左右 箭头选择 文字/背景颜色)\"`${normal}\n"
        inquirer:print "${colors[colors_index]}${bg_colors[bg_colors_index]}$text_default${normal}"

        trap inquirer:control_c EXIT

        tput civis

        inquirer:on_keypress inquirer:on_color_pick_up inquirer:on_color_pick_down inquirer:on_color_pick_enter_space inquirer:on_color_pick_enter_space inquirer:on_color_pick_left inquirer:on_color_pick_right inquirer:on_color_pick_ascii

        read -r ${var_name?} <<< "${colors[colors_index]}${bg_colors[bg_colors_index]}"

        inquirer:cleanup

        trap - EXIT
    }

    inquirer:display_length() {
        local display_length=0 char_read byte_len char_len char_i char
        local oLC_ALL=${LC_ALL:-} oLANG=${LANG:-}

        while IFS= read -rsn1 char
        do
            case "$char" in
                '')
                ;;
                *[$'\x80'-$'\xFF']*) 
                    char_read="${char_read:-}$char"
                    LC_ALL= LANG=C
                    byte_len=${#char_read}
                    LC_ALL=$oLC_ALL LANG=$oLANG

                    if [ "$byte_len" -ne "${#char_read}" ] 
                    then
                        if [[ $byte_len -le 2 ]] 
                        then
                            display_length=$((display_length+1))
                        elif [[ $byte_len -le 4 ]] 
                        then
                            display_length=$((display_length+2))
                        else
                            display_length=$((display_length+3))
                        fi
                        char_read=""
                    fi
                ;;
                *) 
                    display_length=$((display_length+1))
                ;;
            esac
        done <<< "${1:-}"

        echo "$display_length"
    }

    local option=$1 var_name \
    prompt=${2:-} \
    prompt_raw \
    prompt_width \
    break_keypress \
    first_keystroke \
    current_index \
    list_perpage=0 \
    list_count \
    page_list=() \
    page_list_count=0 \
    pages_arrows="\xe2\x9d\xae\xe2\x9d\xaf" \
    pages_tip \
    pages_index=0 \
    pages_count=1 \
    input_page=false \
    input_page_num \
    input_search=false \
    checkbox_list=() \
    checkbox_page_selected=() \
    checkbox_page_select_all=true \
    checkbox_selected=() \
    checkbox_selected_indices=() \
    checkbox_selected_options=() \
    checkbox_input_failed_msg \
    sort_options=() \
    sort_indices=() \
    list_options=() \
    current_pos \
    failed_count \
    text_default \
    text_input \
    text_input_validate_failed_msg \
    text_input_validator \
    date_pick \
    date_pick_validate_failed_msg \
    date_pick_validator \
    colors=() \
    bg_colors=() \
    colors_index \
    bg_colors_index \
    arrow arrow_up checked unchecked bold dim normal

    prompt_raw=$(printf '%b' "$prompt"|sed 's/\x1b\[[0-9;]*m//g')
    prompt_width=$(inquirer:display_length "$prompt_raw")

    arrow='\xe2\x9d\xaf'
    arrow_up='\xe2\x86\x91'
    checked='\xe2\x97\x89'
    unchecked='\xe2\x97\xaf'
    red=${red:-'\033[31m'}
    green=${green:-'\033[32m'}
    yellow=${yellow:-'\033[33m'}
    blue=${blue:-'\033[34m'}
    cyan=${cyan:-'\033[36m'}
    white=${white:-'\033[37m'}
    bg_black=${bg_black:-'\033[40m'}
    bold='\033[1m'
    dim='\033[2m'
    normal='\033[0m'

    shift
    local _inq_rc=0
    inquirer:$option "$@" || _inq_rc=$?
    if [ "$_inq_mock_tty" = true ]
    then
        unset -f tput stty
    fi
    return $_inq_rc
}

ExitOnList()
{
    if [ "$1" == "y" ] 
    then
        inquirer list_input "$2" yn_options yn_option
    else
        inquirer list_input "$2" ny_options yn_option
    fi

    if [ "$yn_option" == "$i18n_no" ]
    then
        Println "$i18n_canceled...\n"
        exit 1
    fi
}

ExitOnText()
{
    inquirer text_input "$1" "$2" "$i18n_cancel" "${3:-}" "${4:-}"

    if [ "${!2}" == "$i18n_cancel" ] 
    then
        Println "$i18n_canceled...\n"
        exit 1
    fi
}
# based on https://raw.githubusercontent.com/kahkhang/ora.sh/master/ora.sh
Spinner()
{
    DepInstall tput

    local i=1 delay=0.05 FUNCTION_NAME="$2" VARIABLE_NAME="${3:-}" list TMP_FILE
    local green cyan normal
    green='\033[32m'
    cyan='\033[36m'
    normal='\033[0m'

    list=( '\xe2\xa0\x8b' '\xe2\xa0\x99' '\xe2\xa0\xb9' '\xe2\xa0\xb8' '\xe2\xa0\xbc' '\xe2\xa0\xb4' '\xe2\xa0\xa6' '\xe2\xa0\xa7' '\xe2\xa0\x87' '\xe2\xa0\x8f' )

    if TMP_FILE=$(mktemp -q) 
    then
        chmod +r "$TMP_FILE"
    else
        PrintfTime TMP_FILE '%m-%d-%H:%M:%S' -1
    fi

    trap '
        rm -f "${TMP_FILE:-}"
        inquirer cleanup
    ' EXIT

    if [ -t 0 ]
    then
        stty -echo
    fi
    tput civis 2> /dev/null || true

    $FUNCTION_NAME > "$TMP_FILE" 2>> "$TMP_FILE" &
    local pid=$!

    echo
    tput sc 2> /dev/null || true
    printf '%b %b' "${list[i]}" "${green}$1${normal}"
    tput el 2> /dev/null || true
    tput rc 2> /dev/null || true

    while ps -p $pid -o pid= >/dev/null
    do
        printf '%b' "$cyan${list[i]}${normal}"
        i=$(((i+1)%10))
        sleep $delay
        printf "\b\b\b"
    done

    tput el 2> /dev/null || true

    if [[ -n $VARIABLE_NAME ]]
    then
        read -r ${VARIABLE_NAME?} < "$TMP_FILE"
    else
        awk '{print}' "$TMP_FILE"
    fi

    rm -f "$TMP_FILE"

    tput cnorm 2> /dev/null || true
    if [ -t 0 ]
    then
        stty echo
    fi

    trap - EXIT

    wait $pid
}
Progress()
{
    local msg

    if [ -z "${1:-}" ] 
    then
        msg="`eval_gettext \"\\\$info 安装中, 请等待...\"`"
    else
        msg="$info $1..."
    fi

    echo -ne "\n$msg"

    while true
    do
        echo -n "."
        sleep 5
    done
}
ShFallback()
{
    DepInstall dig
    sh_txt=$(dig +short $SH_FALLBACK txt)
    sh_txt=${sh_txt#\"}
    sh_txt=${sh_txt%\"}

    if [[ $sh_txt == *[!0-9]* ]] 
    then
        SH_FALLBACK="https://"
        sh_nums=(${sh_txt% *})
        sh_txt="${sh_txt##* }"
        sh_nums_indices=("${!sh_nums[@]}")
    else
        SH_FALLBACK="http://"
    fi

    sh_txt_count=${#sh_txt}
    sh_txt_arr=()
    local i j k

    for((i=0;i<sh_txt_count;i+=3));
    do
        j=$((i/3+1))
        k=$((j%3))
        if [ "$k" -eq 0 ] 
        then
            sh_txt_arr+=("${sh_txt:$i:3}")
        elif [ "$k" -eq 1 ] 
        then
            sh_txt_arr+=("${sh_txt:$((i+1)):1}${sh_txt:$i:1}${sh_txt:$((i+2)):1}")
        elif [ "$k" -eq 2 ] 
        then
            sh_txt_arr+=("${sh_txt:$((i+2)):1}${sh_txt:$i:2}")
        fi
    done

    if [[ $sh_txt == *[!0-9]* ]] 
    then
        sh_txt_tmp=""

        for ele in "${sh_txt_arr[@]}"
        do
            ele=${ele#\-}
            ele=${ele#\-}
            sh_txt_tmp="$sh_txt_tmp$ele"
        done

        sh_txt=""

        for sh_nums_index in "${sh_nums_indices[@]}"
        do
            [ -n "$sh_txt" ] && sh_txt="$sh_txt."
            sh_index=$((${sh_nums[sh_nums_index]}+sh_nums_index+1))
            sh_txt="$sh_txt${sh_txt_tmp:0:$sh_index}"
            sh_txt_tmp="${sh_txt_tmp:$sh_index}"
        done
    else
        sh_txt=""

        for ele in "${sh_txt_arr[@]}"
        do
            [ -n "$sh_txt" ] && sh_txt="$sh_txt."
            ele=${ele#\0}
            ele=${ele#\0}
            sh_txt="$sh_txt$ele"
        done
    fi

    SH_FALLBACK="$SH_FALLBACK$sh_txt"
}

ShFileCheck()
{
    if [ ! -e "$SH_FILE" ] 
    then
        DepInstall curl
        ShFallback

        if curl -s -Lm 20 "$SH_LINK" -o "${SH_FILE}_tmp"
        then
            mv "${SH_FILE}_tmp" "$SH_FILE"
            chmod +x "$SH_FILE"
            Println "`eval_gettext \"\\\$info 脚本下载完成\"`"
        else
            Println "`eval_gettext \"\\\$error 无法连接到 Github ! 尝试备用链接...\"`"
            if curl -s -Lm 30 "$SH_FALLBACK/${SH_LINK##*/}" -o "${SH_FILE}_tmp" 
            then
                mv "${SH_FILE}_tmp" "$SH_FILE"
                chmod +x "$SH_FILE"
                Println "`eval_gettext \"\\\$info 脚本下载完成\"`"
            else
                Println "`eval_gettext \"\\\$error 无法连接备用链接! 脚本下载失败, 请稍后再试\"`\n"
                exit 1
            fi
        fi
    fi

    [ ! -e "$IBM_FILE" ] && ln -s "$SH_FILE" "$IBM_FILE"
    [ ! -e "$CF_FILE" ] && ln -s "$SH_FILE" "$CF_FILE"
    [ ! -e "$OR_FILE" ] && ln -s "$SH_FILE" "$OR_FILE"
    [ ! -e "$NX_FILE" ] && ln -s "$SH_FILE" "$NX_FILE"
    [ ! -e "$V2_FILE" ] && ln -s "$SH_FILE" "$V2_FILE"
    [ ! -e "$X_FILE" ] && ln -s "$SH_FILE" "$X_FILE"
    [ ! -e "$XC_FILE" ] && ln -s "$SH_FILE" "$XC_FILE"
    [ ! -e "$ARM_FILE" ] && ln -s "$SH_FILE" "$ARM_FILE"
    [ ! -e "$PVE_FILE" ] && ln -s "$SH_FILE" "$PVE_FILE"
    [ ! -e "$OPENLIST_FILE" ] && ln -s "$SH_FILE" "$OPENLIST_FILE"
    [ ! -e "$LIANHUANHUA_FILE" ] && ln -s "$SH_FILE" "$LIANHUANHUA_FILE"
    [ ! -e "$RCLONE_FILE" ] && ln -s "$SH_FILE" "$RCLONE_FILE"
    [ ! -e "$CALIBRE_FILE" ] && ln -s "$SH_FILE" "$CALIBRE_FILE"
    [ ! -e "$DOCKER_FILE" ] && ln -s "$SH_FILE" "$DOCKER_FILE"
    [ ! -e "$HAPROXY_FILE" ] && ln -s "$SH_FILE" "$HAPROXY_FILE"

    return 0
}

ShFileUpdate()
{
    sh_name=${1:-aios}

    Println "`eval_gettext \"\\\$info 更新 \\\$sh_name 脚本...\"`"

    ShFallback

    if curl -s -Lm 20 "$SH_LINK" -o "${SH_FILE}_tmp"
    then
        mv "${SH_FILE}_tmp" "$SH_FILE"
        chmod +x "$SH_FILE"
        Println "`eval_gettext \"\\\$info \\\$sh_name 脚本更新完成\"`"
        sh_new_ver=$(sed -nE 's/^[[:space:]]*sh_ver="?([^"[:space:]]+)"?/\1/p' "$SH_FILE" | head -n 1)
        if [ -n "$sh_new_ver" ] && [ "${sh_new_ver%.*}" != "${sh_ver%.*}" ]
        then
            rm -f "$LOCK_FILE"
        fi
    else
        Println "`eval_gettext \"\\\$error 无法连接到 Github ! 尝试备用链接...\"`"

        if curl -s -Lm 30 "$SH_FALLBACK/${SH_LINK##*/}" -o "${SH_FILE}_tmp"
        then
            mv "${SH_FILE}_tmp" "$SH_FILE"
            chmod +x "$SH_FILE"
            Println "`eval_gettext \"\\\$info \\\$sh_name 脚本更新完成\"`"
            sh_new_ver=$(sed -nE 's/^[[:space:]]*sh_ver="?([^"[:space:]]+)"?/\1/p' "$SH_FILE" | head -n 1)
            if [ -n "$sh_new_ver" ] && [ "${sh_new_ver%.*}" != "${sh_ver%.*}" ]
            then
                rm -f "$LOCK_FILE"
            fi
        else
            Println "`eval_gettext \"\\\$error 无法连接备用链接! \\\$sh_name 脚本更新失败, 请稍后再试\"`\n"
        fi
    fi

    [ "$sh_locale" != "zh_CN" ] && i18nInstall "$sh_locale" > /dev/null

    return 0
}
JQInstall()
{
    if [[ -x "$JQ_FILE" ]]
    then
        return
    elif [[ -x "$IPTV_ROOT"/jq ]]
    then
        JQ_FILE="$IPTV_ROOT"/jq
        return
    fi

    DepsCheck
    ArchCheck

    if [ "$dist" == "mac" ]
    then
        DepInstall jq check
        return 0
    elif grep -q "arm" <<< "$arch"
    then
        if ! /usr/local/bin/jq -V > /dev/null 2>&1
        then
            Println "`eval_gettext \"\\\$info 开始下载/安装 JQ...\"`"
            cd ~
            git clone "${JQ_REPO_LINK}.git" > /dev/null
            cd jq
            AptInstall flex bison libtool make automake autoconf
            git submodule update --init > /dev/null
            autoreconf -fi > /dev/null
            ./configure --with-oniguruma=builtin > /dev/null
            nproc="-j$(nproc 2> /dev/null)" || nproc=""
            make $nproc > /dev/null
            make install > /dev/null
        fi
        if [ "$JQ_FILE" != "/usr/local/bin/jq" ]
        then
            rm -f "$JQ_FILE"
            ln -sf /usr/local/bin/jq "$JQ_FILE"
        fi
        Println "`eval_gettext \"\\\$info JQ 安装完成\"`"
    else
        Println "`eval_gettext \"\\\$info 开始下载/安装 JQ...\"`"
        #experimental# grep -Po '"tag_name": "jq-\K.*?(?=")'
        if ! jq_ver=$(curl -s -m 10 "$FFMPEG_MIRROR_LINK/jq.json" |  grep '"tag_name":' | sed -E 's/.*"([^"]+)".*/\1/')
        then
            Println "`eval_gettext \"\\\$error 暂时无法连接服务器, 请稍后再试 !\"`"
            exit 1
        fi
        if grep -q 64 <<< "$arch"
        then
            jq_package="jq-linux64"
        else
            jq_package="jq-linux32"
        fi
        if curl -L "$FFMPEG_MIRROR_LINK/$jq_ver/$jq_package" -o "$JQ_FILE"
        then
            chmod +x "$JQ_FILE"
            Println "`eval_gettext \"\\\$info JQ 安装完成\"`"
        else
            rm -f "$JQ_FILE"
            Println "`eval_gettext \"\\\$error 下载 JQ 失败, 请重试 !\"`"
            exit 1
        fi
    fi
}

JQ()
{
    local jq_action=$1 FILE=$2 TMP_FILE jq_args=() jq_commands=() slurp_arg
    local jq_a3=${3:-none} jq_a4=${4:-none} jq_a5=${5:-none}

    jq_path=${jq_path:-}
    jq_path2=${jq_path2:-}

    jq_map_bool=${jq_map_bool:-false}
    jq_map_string=${jq_map_string:-false}
    jq_merge=${jq_merge:-false}
    jq_json=${jq_json:-false}
    jq_number=${jq_number:-false}
    jq_bool=${jq_bool:-false}
    jq_pre=${jq_pre:-false}
    jq_file=${jq_file:-false}
    jq_file_json=${jq_file_json:-false}

    local jq_rc=0
    if TMP_FILE=$(mktemp -q)
    then
        chmod +r "$TMP_FILE"
    else
        printf -v TMP_FILE "${FILE}_%s" "$$"
    fi

    if [ -n "$jq_path" ]
    then
        jq_args+=( --argjson path "$jq_path" )
    fi

    if [ -n "$jq_path2" ]
    then
        jq_args+=( --argjson path2 "$jq_path2" )
    fi

    case $jq_action in
        add)
            local add_op
            if [ "$jq_pre" = true ]
            then
                add_op='(if type == "array" then ($add + .) else $add end)'
            else
                add_op='(if type == "array" then (. + $add) else $add end)'
            fi

            if [ -n "${4:-}" ]
            then
                local match_val
                if [ "$jq_map_bool" = true ]
                then
                    match_val='($value|test("true"))'
                elif [ "$jq_map_string" = true ]
                then
                    match_val='$value'
                else
                    match_val='($value|tonumber)'
                fi

                local map_body
                if [ -n "$jq_path2" ]
                then
                    map_body='(select(type == "object" and .[$key] == '"$match_val"') | getpath($path2)) |= '"$add_op"
                else
                    map_body='select(type == "object" and .[$key] == '"$match_val"') |= '"$add_op"
                fi

                if [ -n "$jq_path" ]
                then
                    jq_commands=( 'getpath($path) |= (if type == "array" then map('"$map_body"') else [] end)' )
                else
                    jq_commands=( 'if type == "array" then map('"$map_body"') else [] end' )
                fi

                jq_args+=( --arg key "$3" --arg value "$4" )

                if [ "$jq_file" = true ]
                then
                    slurp_arg=("$5"[@])
                else
                    jq_args+=( --argjson add "$5" )
                fi
            else
                if [ -n "$jq_path" ]
                then
                    jq_commands=( 'getpath($path) |= '"$add_op" )
                else
                    jq_commands=( "$add_op" )
                fi

                if [ "$jq_file" = true ]
                then
                    slurp_arg=("$3"[@])
                else
                    jq_args+=( --argjson add "$3" )
                fi
            fi

            if [ "$jq_file" = true ]
            then
                jq_args+=( --slurpfile add "${TMP_FILE}_slurp" )

                if [[ -z ${!slurp_arg:-} ]]
                then
                    printf '%s' "" > "${TMP_FILE}_slurp"
                elif [ "$jq_file_json" = true ]
                then
                    printf '%s\n' "${!slurp_arg//\\\\/\\}" > "${TMP_FILE}_slurp"
                else
                    printf '"%s"\n' "${!slurp_arg//\"/\\\"}" > "${TMP_FILE}_slurp"
                fi
            fi
        ;;
        update)
            local upd_op
            if [ "$jq_merge" = true ]
            then
                upd_op='|= (if type == "object" then (. * $update) else $update end)'
            elif [ "$jq_number" = true ]
            then
                upd_op='= ($update | tonumber)'
            elif [ "$jq_bool" = true ]
            then
                upd_op='= ($update | test("true"))'
            else
                upd_op='= $update'
            fi

            if [ -n "${4:-}" ]
            then
                local match_val
                if [ "$jq_map_bool" = true ]
                then
                    match_val='($value|test("true"))'
                elif [ "$jq_map_string" = true ]
                then
                    match_val='$value'
                else
                    match_val='($value|tonumber)'
                fi

                local map_body
                if [ -n "$jq_path2" ]
                then
                    map_body='(select(type == "object" and .[$key] == '"$match_val"') | getpath($path2)) '"$upd_op"
                else
                    map_body='select(type == "object" and .[$key] == '"$match_val"') '"$upd_op"
                fi

                if [ -n "$jq_path" ]
                then
                    jq_commands=( 'getpath($path) |= (if type == "array" then map('"$map_body"') else . end)' )
                else
                    jq_commands=( 'if type == "array" then map('"$map_body"') else . end' )
                fi

                jq_args+=( --arg key "$3" --arg value "$4" )

                if [ "$jq_file" = true ]
                then
                    slurp_arg=("$5"[@])
                elif [ "$jq_json" = true ] || [ "$jq_merge" = true ]
                then
                    jq_args+=( --argjson update "$5" )
                else
                    jq_args+=( --arg update "$5" )
                fi
            else
                if [ -n "$jq_path" ]
                then
                    jq_commands=( 'getpath($path) '"$upd_op" )
                else
                    if [ "$jq_merge" = true ]
                    then
                        jq_commands=( 'if type == "object" then (. * $update) else $update end' )
                    elif [ "$jq_number" = true ]
                    then
                        jq_commands=( '($update | tonumber)' )
                    elif [ "$jq_bool" = true ]
                    then
                        jq_commands=( '($update | test("true"))' )
                    else
                        jq_commands=( '$update' )
                    fi
                fi

                if [ "$jq_file" = true ]
                then
                    slurp_arg=("$3"[@])
                elif [ "$jq_json" = true ] || [ "$jq_merge" = true ]
                then
                    jq_args+=( --argjson update "$3" )
                else
                    jq_args+=( --arg update "$3" )
                fi
            fi

            if [ "$jq_file" = true ]
            then
                jq_args+=( --slurpfile update "${TMP_FILE}_slurp" )

                if [[ -z ${!slurp_arg:-} ]]
                then
                    printf '%s' "" > "${TMP_FILE}_slurp"
                elif [ "$jq_file_json" = true ]
                then
                    printf '%s\n' "${!slurp_arg//\\\\/\\}" > "${TMP_FILE}_slurp"
                else
                    printf '"%s"\n' "${!slurp_arg//\"/\\\"}" > "${TMP_FILE}_slurp"
                fi
            fi
        ;;
        delete)
            if [ -n "${3:-}" ]
            then
                local match_val
                if [ "$jq_map_bool" = true ]
                then
                    match_val='($value|test("true"))'
                elif [ "$jq_map_string" = true ]
                then
                    match_val='$value'
                else
                    match_val='($value|tonumber)'
                fi

                jq_args+=( --arg key "$3" --arg value "$4" )

                if [ -z "${5:-}" ]
                then
                    local del_sel
                    if [ -n "$jq_path2" ]
                    then
                        del_sel='(select(type == "object" and .[$key] == '"$match_val"') | getpath($path2))'
                    else
                        del_sel='select(type == "object" and .[$key] == '"$match_val"')'
                    fi

                    if [ -n "$jq_path" ]
                    then
                        jq_commands=( 'if (getpath($path) | type) == "array" then del(getpath($path)[] | '"$del_sel"') else . end' )
                    else
                        jq_commands=( 'if type == "array" then del(.[] | '"$del_sel"') else . end' )
                    fi
                else
                    jq_args+=( --argjson delete "$5" )
                    local del_op='(if type == "array" then (. - $delete) else . end)'
                    local map_body
                    if [ -n "$jq_path2" ]
                    then
                        map_body='(select(type == "object" and .[$key] == '"$match_val"') | getpath($path2)) |= '"$del_op"
                    else
                        map_body='select(type == "object" and .[$key] == '"$match_val"') |= '"$del_op"
                    fi

                    if [ -n "$jq_path" ]
                    then
                        jq_commands=( 'getpath($path) |= (if type == "array" then map('"$map_body"') else . end)' )
                    else
                        jq_commands=( 'if type == "array" then map('"$map_body"') else . end' )
                    fi
                fi
            elif [ -n "$jq_path" ]
            then
                jq_commands+=( 'del(getpath($path))' )
            else
                rm -f "$TMP_FILE" "${TMP_FILE}_slurp"
                return 1
            fi
        ;;
        mutate)
            jq_commands=( "$3" )
            shift 3
            jq_args+=( "$@" )
        ;;
    esac

    if command -v flock > /dev/null 2>&1
    then
        {
            flock -x 200 || { LogErr "`eval_gettext \"\\\$FILE JQ fd 200 失败\"`"; exit 1; }

            if ! $JQ_FILE ${jq_args[@]+"${jq_args[@]}"} "${jq_commands[*]}" "$FILE" > "$TMP_FILE" || [ ! -s "$TMP_FILE" ]
            then
                rm -f "$TMP_FILE"
                LogInfo "JQ ERROR!! action: $jq_action, file: $FILE, tmp_file: $TMP_FILE, \$3: $jq_a3, \$4: $jq_a4, \$5: $jq_a5"
                jq_rc=1
            else
                mv "$TMP_FILE" "$FILE"
            fi

            rm -f "${TMP_FILE}_slurp"
        } 200>"$FILE.lock"
    else
        if ! $JQ_FILE ${jq_args[@]+"${jq_args[@]}"} "${jq_commands[*]}" "$FILE" > "$TMP_FILE" || [ ! -s "$TMP_FILE" ]
        then
            rm -f "$TMP_FILE"
            LogInfo "JQ ERROR!! action: $jq_action, file: $FILE, tmp_file: $TMP_FILE, \$3: $jq_a3, \$4: $jq_a4, \$5: $jq_a5"
            jq_rc=1
        else
            mv "$TMP_FILE" "$FILE"
        fi

        rm -f "${TMP_FILE}_slurp"
    fi

    jq_path=""
    jq_path2=""

    jq_map_bool=false
    jq_map_string=false
    jq_merge=false
    jq_json=false
    jq_number=false
    jq_bool=false
    jq_pre=false
    jq_file=false
    jq_file_json=false

    return $jq_rc
}

JQs()
{
    case $1 in
        "get")
            $JQ_FILE -c -r --argjson path "$jq_path" 'getpath($path)|'"${3:-.}"'' <<< "${!2}"
            jq_path=""
        ;;
        "gets")
            local jq_gets_in="${!2:-}"
            [ -z "$jq_gets_in" ] && jq_gets_in="{}"
            $JQ_FILE -c -r --argjson paths "$jq_path" '
                . as $root
                | $paths[] as $p
                | (
                    reduce $p[] as $k ($root;
                        if type == "object" and ($k | type) == "string" then .[$k]
                        elif type == "array" and ($k | type) == "number" then .[$k]
                        else null
                        end
                    )
                  ) as $v
                | "jq_\($p | join("_")): \(
                    if ($v | type) == "string" or ($v | type) == "number" or ($v | type) == "boolean" then
                        ($v | tostring)
                    else
                        ""
                    end
                )"
            ' <<< "$jq_gets_in"
            jq_path=""
        ;;
        "add")
            if [ "${4:-}" == "pre" ]
            then
                read -r $2 < <($JQ_FILE -c --argjson path "${jq_path:-[]}" --argjson value "$3" 'getpath($path) |= $value + .' <<< "${!2}")
            else
                read -r $2 < <($JQ_FILE -c --argjson path "${jq_path:-[]}" --argjson value "$3" 'getpath($path) += $value' <<< "${!2}")
            fi
            jq_path=""
        ;;
        "update")
            if [ "${4:-}" == "number" ]
            then
                read -r $2 < <($JQ_FILE -c --argjson path "$jq_path" --arg value "$3" 'getpath($path) = ($value | tonumber)' <<< "${!2}")
            else
                read -r $2 < <($JQ_FILE -c --argjson path "$jq_path" --arg value "$3" 'getpath($path) = $value' <<< "${!2}")
            fi
            jq_path=""
        ;;
        "replace")
            read -r $2 < <($JQ_FILE -c --argjson path "$jq_path" --argjson value "$3" 'getpath($path) = $value' <<< "${!2}")
            jq_path=""
        ;;
        "delete")
            if [ -z "${3:-}" ]
            then
                read -r $2 < <($JQ_FILE -c --argjson path "$jq_path" 'del(getpath($path))' <<< "${!2}")
            else
                read -r $2 < <($JQ_FILE -c --argjson path "$jq_path" --arg index "$3" 'del(getpath($path)[$index|tonumber])' <<< "${!2}")
            fi
            jq_path=""
        ;;
        "merge")
            read -r $2 < <($JQ_FILE -c -s '
            def merge(a;b):
                reduce b[] as $item (a;
                reduce ($item | keys_unsorted[]) as $key (.;
                $item[$key] as $val | ($val | type) as $type | .[$key] = if ($type == "object") then
                    merge({}; [if .[$key] == null then {} else .[$key] end, $val])
                elif ($type == "array") then
                    (.[$key] + $val | unique)
                else
                    $val
                end)
                );
            merge({}; .)' <<< "${!2} $3")
        ;;
        "merge_c")
            local var=$2
            shift 2
            read -r $var < <($JQ_FILE -c "$@" <<< "${!var}")
        ;;
        "query")
            local src=$2
            local expr=$3
            shift 3
            if [[ $src =~ ^/ ]]
            then
                [ -s "$src" ] || return 0
                $JQ_FILE -r "$@" "$expr" "$src"
            else
                [ -n "${!src:-}" ] || return 0
                $JQ_FILE -r "$@" "$expr" <<< "${!src}"
            fi
        ;;
        "build")
            local out_var=$2
            local expr=$3
            shift 3
            read -r $out_var < <($JQ_FILE -n -c "$@" '
                def compact_obj:
                    if type == "object" then
                        with_entries(
                            .value |= compact_obj
                            | select(.value != null and .value != "" and .value != [] and .value != {})
                        )
                    elif type == "array" then
                        map(compact_obj) | map(select(. != null and . != "" and . != [] and . != {}))
                    else
                        .
                    end;
                ('"$expr"') | compact_obj
            ')
        ;;
        "flat")
            local jq_src="$2"
            local jq_is_file=false
            if [[ $jq_src =~ ^/ ]]
            then
                if [ ! -s "$jq_src" ]
                then
                    printf '{}\n'
                    return 0
                fi
                jq_is_file=true
            elif [ -z "$jq_src" ]
            then
                printf '{}\n'
                return 0
            fi

            local pre="${3:-.} | if type == \"null\" or . == \"\" then {} else . end"

            if [ $# -ge 3 ]
            then
                shift 3
            else
                shift 2
            fi

            local jq_flat_prog='
            def structural_merge:
                type as $type
                | if $type == "object" then
                    with_entries(.value |= structural_merge)
                elif $type == "array" then
                    if length == 0 then []
                    elif ([ .[] | select(. != null and . != []) | type == "object" ] | unique | length == 2) then
                        .
                    elif (map(type == "object") | any) then
                        ( [ .[] | select(type == "object") | keys[] ] | unique ) as $all_keys
                        | map(. as $obj
                        | if $obj == null or $obj == [] or type != "object" then
                            $all_keys | map({key: ., value: null}) | from_entries
                        else
                            $all_keys | map({key: ., value: $obj[.]}) | from_entries
                        end)
                        | [ .[] | to_entries[] ]
                        | group_by(.key)
                        | map({
                            key: .[0].key,
                            value: (map(.value) | structural_merge)
                        })
                        | from_entries
                    else
                        map(structural_merge)
                        | if ([ .[] | select(. != null and . != []) | type == "object" ] | any) then structural_merge else . end
                    end
                else
                    .
                end;

            def finalize_strings($layer):
                type as $type
                | if $type == "object" then
                    with_entries(.value |= finalize_strings($layer + 1))
                elif $type == "array" then
                    if length == 0 then ""
                    else
                        map(
                            (if type == "array" then
                                finalize_strings($layer + 1)
                            elif type == "null" or . == "" then
                                ""
                            else
                                tostring
                            end) + ($delims[$layer] // "|")
                        )
                        | join("")
                    end
                elif $type == "null" or . == "" then
                    ""
                else
                    tostring
                end;

            '"$pre"' | structural_merge | finalize_strings(0)'

            if [ "$jq_is_file" = true ]
            then
                $JQ_FILE --argjson delims "$json_delimiters" -r -c "$@" "$jq_flat_prog" "$jq_src"
            else
                $JQ_FILE --argjson delims "$json_delimiters" -r -c "$@" "$jq_flat_prog" <<< "$jq_src"
            fi
        ;;
    esac
}
GitInstall()
{
    if [[ -x $(command -v git) ]] 
    then
        return 0
    fi

    Println "$(eval_gettext "\$info 安装 git")"

    case $dist in
        mac) brew install git
        ;;
        rpm) yum -y install git
        ;;
        deb) AptInstall git
        ;;
        ubu) 
            add-apt-repository ppa:git-core/ppa -y
            apt-get -y update
            AptInstall git
        ;;
    esac

    Println "$(eval_gettext "\$info git 安装成功")\n"
}
CurlImpersonateInstall()
{
    if [[ -x "$CURL_IMPERSONATE_FILE" ]] 
    then
        return 0
    fi

    DepsCheck
    ArchCheck

    DepInstall ca-certificates

    if [ "$dist" == "mac" ] 
    then
        DepInstall nss
    elif [ "$dist" == "rpm" ] 
    then
        DepInstall nss
        DepInstall nss-pem
    else
        DepInstall libnss3
        if [ "$dist" == "ubu" ] && grep -q "bionic" < "/etc/apt/sources.list" 
        then
            DepInstall libnsspem
        else
            DepInstall nss-plugin-pem
        fi
    fi

    JQInstall

    if ! curl_impersonate_ver=$(curl -s -Lm 30 "https://api.github.com/repos/lwthiker/curl-impersonate/releases/latest" | $JQ_FILE -r '.tag_name') 
    then
        Println "$(eval_gettext "\$error curl impersonate 下载出错, 无法连接 github ?")\n"
        return 1
    fi

    if [ "$arch" == "x86_64" ] 
    then
        if [ "$dist" == "mac" ] 
        then
            curl_impersonate_package_name="curl-impersonate-$curl_impersonate_ver.x86_64-macos"
        else
            curl_impersonate_package_name="curl-impersonate-$curl_impersonate_ver.x86_64-linux-gnu"
        fi
    elif [ "$arch" == "arm64" ] 
    then
        curl_impersonate_package_name="curl-impersonate-$curl_impersonate_ver.aarch64-linux-gnu"
    else
        Println "$(eval_gettext "\$error 系统不支持安装 curl impersonate")\n"
        return 1
    fi

    Println "$(eval_gettext "\$info 下载 curl impersonate ...")"

    mkdir -p "$DEPENDS_ROOT/curl-impersonate/"

    if ! curl -L "https://github.com/lwthiker/curl-impersonate/releases/download/$curl_impersonate_ver/$curl_impersonate_package_name.tar.gz" -o "$DEPENDS_ROOT/$curl_impersonate_package_name.tar.gz"
    then
        Println "$(eval_gettext "\$error curl impersonate 下载出错, 无法连接 github ?")\n"
        return 1
    fi

    tar -C "$DEPENDS_ROOT/curl-impersonate/" -xzf "$DEPENDS_ROOT/$curl_impersonate_package_name.tar.gz"

    rm -f "$CURL_IMPERSONATE_FILE"

    awk '!x{x=sub(/dir=.*/,"dir='"$DEPENDS_ROOT/curl-impersonate"'")}1' "$DEPENDS_ROOT/curl-impersonate/curl_chrome99" > "$CURL_IMPERSONATE_FILE"

    chmod +x "$CURL_IMPERSONATE_FILE"

    Println "$(eval_gettext "\$info curl impersonate 安装成功")"
}

CurlImpersonateValidateService()
{
    if [ "$1" == "$i18n_cancel" ] || [[ $1 =~ ^[A-Za-z0-9_.]+$ ]] 
    then
        return 0
    fi

    return 1
}

CurlImpersonateUpdate()
{
    if [[ -x "$CURL_IMPERSONATE_FILE" ]] 
    then
        echo
        inquirer list_input_index "$(gettext "curl impersonate 已经存在, 是否重新安装")" ny_options ny_index
        if [ "$ny_index" -eq 1 ] 
        then
            rm -f "$CURL_IMPERSONATE_FILE"
            CurlImpersonateInstall
        fi
    else
        CurlImpersonateInstall
    fi

    echo
    config_options=( "$(gettext "设置默认服务")" )

    if ls -A "$CURL_IMPERSONATE_FILE"/-* > /dev/null 2>&1
    then
        for service in "$CURL_IMPERSONATE_FILE"-*
        do
            service_name="${service#*${CURL_IMPERSONATE_FILE}-}"
            config_options+=("$service_name")
        done
    fi

    config_options+=( "$(gettext "新增服务")" )

    config_options_count=${#config_options[@]}

    inquirer list_input_index "$(gettext "选择操作")" config_options config_options_index

    impersonate_service_file="$CURL_IMPERSONATE_FILE"

    if [ "$config_options_index" -eq $((config_options_count-1)) ] 
    then
        echo
        ExitOnText "$(gettext "输入服务名称")" impersonate_service_name CurlImpersonateValidateService "$(gettext "请输入正确的服务名称(字母、数字、下划线组成)")"
        impersonate_service_file="$impersonate_service_file-$impersonate_service_name"
    elif [ "$config_options_index" -gt 0 ] 
    then
        impersonate_service_file="$impersonate_service_file-${config_options[config_options_index]}"
    fi

    impersonate_options=()

    for ele in "$DEPENDS_ROOT"/curl-impersonate/curl_*
    do
        impersonate_options+=("${ele##*/}")
    done

    echo
    inquirer list_input "$(gettext "选择 curl impersonate")" impersonate_options impersonate_option

    rm -f "$impersonate_service_file"

    awk '!x{x=sub(/dir=.*/,"dir='"$DEPENDS_ROOT/curl-impersonate"'")}1' "$DEPENDS_ROOT/curl-impersonate/$impersonate_option" > "$impersonate_service_file"

    chmod +x "$impersonate_service_file"

    headers_name=()
    headers_val=()

    while IFS= read -r line 
    do
        if [[ $line =~ ^[[:blank:]]*-H\ \'([^:]+):\ (.*)\'\ \\$ ]] 
        then
            headers_name+=("${BASH_REMATCH[1]}")
            headers_val+=("${BASH_REMATCH[2]}")
        fi
    done < "$impersonate_service_file"

    if [ -n "${headers_name:-}" ] 
    then
        echo
        inquirer checkbox_input_indices "$(gettext "选择修改的 header")" headers_name headers_name_indices

        config_options=( "$(gettext "输入")" "$(gettext "删除")" )

        for i in "${headers_name_indices[@]}"
        do
            local header_name="${headers_name[i]}"
            echo
            inquirer list_input_index "$(eval_gettext "对 \$header_name 选择操作")" config_options config_options_index
            if [ "$config_options_index" -eq 0 ] 
            then
                echo
                inquirer text_input "$(eval_gettext "输入 \$header_name 值")" header_val "${headers_val[i]}"

                echo "$(awk '!x{x=sub(/-H '\'''"${headers_name[i]}"': .*'\'' \\/,"-H '\'''"${headers_name[i]}"': '"$header_val"''\'' \\")}1' "$impersonate_service_file")" > "$impersonate_service_file"
                Println "$(eval_gettext "\$info \$header_name 修改成功")"
            else
                sed -i "/^[[:blank:]]*-H '${headers_name[i]}:/d" "$impersonate_service_file"
                Println "$(eval_gettext "\$info \$header_name 删除成功")"
            fi
        done
    fi

    Println "$(eval_gettext "\$info curl impersonate 设置成功")"
}

CurlImpersonateCompile()
{
    echo
    inquirer text_input "$(gettext "输入 curl-impersonate 安装目录")" curl_impersonate_prefix "$AIOS_PREFIX"/curl-impersonate

    GitInstall

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    if [ -d curl-impersonate.git ] 
    then
        PrintfTime update_date '%m-%d-%H:%M:%S' -1
        mv curl-impersonate.git curl-impersonate.git_"$update_date"
    fi

    git clone https://github.com/lwthiker/curl-impersonate.git curl-impersonate.git
    cd curl-impersonate.git

    GoInstall

    if [ "$dist" == "mac" ] 
    then
        DepInstall brew
        brew install pkg-config make cmake ninja autoconf automake libtool go
        mkdir build && cd build
        ../configure --prefix="$curl_impersonate_prefix"
        gmake chrome-build
        Println "$(eval_gettext "\$tip 可能需要输入密码建立安装路径 \$curl_impersonate_prefix")"
        sudo gmake chrome-install
    else
        if [ "$dist" == "rpm" ] 
        then
            yum groupinstall -y "Development Tools"
            # Fedora only
            # yum groupinstall "C Development Tools and Libraries"
            yum install -y cmake3 python3 python3-pip
            yum install -y ninja-build || pip3 install ninja
        else
            AptInstall build-essential pkg-config cmake ninja-build curl autoconf automake libtool unzip
        fi

        mkdir build && cd build
        ../configure --prefix="$curl_impersonate_prefix"
        make chrome-build
        sudo make chrome-install
        sudo ldconfig
    fi

    if [ "$dist" == "mac" ] 
    then
        Println "$(eval_gettext "\$tip 可能需要输入密码建立安装路径 \${curl_impersonate_prefix}/include/curl/")"
    fi

    sudo mkdir -p "$curl_impersonate_prefix"/include/curl/
    sudo cp -f curl-*/include/curl/* "$curl_impersonate_prefix"/include/curl/
    # sudo cp -f curl-*/curl-impersonate-chrome-config "$curl_impersonate_prefix"/bin/
    # sudo chmod +x "$curl_impersonate_prefix"/bin/curl-impersonate-chrome-config

    # rm -f "$AIOS_PREFIX"/bin/curl-config
    # sudo ln -s "$curl_impersonate_prefix"/bin/curl-impersonate-chrome-config "$AIOS_PREFIX"/bin/curl-config

    Println "$(eval_gettext "\$info curl impersonate 编译成功")\n"
}

NodeLibcurlImpersonateCompile()
{
    NodejsInstall

    echo
    inquirer text_input "$(gettext "输入编译安装好的 curl impersonate 路径")" curl_impersonate_prefix "$AIOS_PREFIX"/curl-impersonate

    if [ ! -d "$curl_impersonate_prefix" ] 
    then
        Println "$(eval_gettext "\$error curl impersonate 目录不存在, 请先编译安装")\n"
        return 1
    fi

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    if [ -d node-libcurl-impersonate ] 
    then
        PrintfTime update_date '%m-%d-%H:%M:%S' -1
        mv node-libcurl-impersonate node-libcurl-impersonate_"$update_date"
    fi

    git clone https://github.com/JCMais/node-libcurl.git node-libcurl-impersonate
    cd node-libcurl-impersonate
    curl -s -Lm 30 "$FFMPEG_MIRROR_LINK/node-libcurl-impersonate.patch" -o node-libcurl-impersonate.patch
    patch -p1 < node-libcurl-impersonate.patch || true

    if [ "$dist" == "mac" ] 
    then
