        sudo ln -s "${curl_impersonate_prefix}"/lib/libcurl-impersonate-chrome.*.dylib "$AIOS_PREFIX"/curl-impersonate/lib/libcurl.dylib
    fi

    rm -f "$AIOS_PREFIX"/bin/curl-config
    sudo ln -s "$curl_impersonate_prefix"/bin/curl-impersonate-chrome-config "$AIOS_PREFIX"/bin/curl-config
    npm run clean:dist
    npm install --force --build-from-source --unsafe-perm
    npm run build:dist

    Println "$(eval_gettext "\$info 查看 \$DEPENDS_ROOT/node-libcurl-impersonate/lib/binding/node_libcurl-impersonate.node")\n$(eval_gettext "可以这样使用 const { Curl, CurlFeature, CurlHttpVersion, CurlSslVersion } = require('\$DEPENDS_ROOT/node-libcurl-impersonate/dist')")\n$(gettext "详见 https://github.com/JCMais/node-libcurl/")\n"
}
ChangeLogFile()
