ProxyRenderOverview()
{
    local config_file="$1"
    local core_type="${2:-xray}"

    if [ ! -s "$config_file" ]
    then
        return 1
    fi

    ProxyInitI18nJson

    $JQ_FILE -r \
        --arg core "$core_type" \
        --arg g "$green" \
        --arg r "$red" \
        --arg n "$normal" \
        --argjson i18n "$PROXY_I18N_JSON" \
    '
    def cv($v): "\($g)\($v)\($n)";
    def yv($v): if $v == true then "\($g)\($i18n.yes)\($n)" else "\($r)\($i18n.no)\($n)" end;
    def arr($a): if ($a | type) == "array" then ($a | map(select(. != null) | tostring) | join(", ")) else ($a // "" | tostring) end;

    [
        (if (.log | type) == "object" then
            (if (.log.access | type) == "string" and (.log.access | length) > 0 then .log.access else "stdout" end) as $lacc
            | (if (.log.error | type) == "string" and (.log.error | length) > 0 then .log.error else "stdout" end) as $lerr
            | "Log: level=\(cv(.log.logLevel // .log.loglevel // "warning")) access=\(cv($lacc)) error=\(cv($lerr))"
              + (if $core == "xray" then " dnsLog=\(yv(.log.dnsLog // false))" + (if (.log.maskAddress // "") != "" then " maskAddress=\(cv(.log.maskAddress))" else "" end) else "" end)
        else empty end),
        (if (.api | type) == "object" then
            "API: tag=\(cv(.api.tag // ""))"
            + (if $core == "xray" and (.api.listen // "") != "" then " listen=\(cv(.api.listen))" else "" end)
            + " services=\(cv(arr(.api.services // [])))"
        else empty end),
        (if (.stats | type) == "object" then
            "Stats: \(cv($i18n.enabled))"
        else empty end),
        (if (.env | type) == "object" and (.env | length) > 0 then
            "Env: \(cv(.env | to_entries | map("\(.key)=\(.value | tostring)") | join(", ")))"
        else empty end),
        (if (.transport | type) == "object" and (.transport | length) > 0 then
            "Transport: \(cv(.transport | keys | join(", ")))"
        else empty end),
        (if (.fakedns | type) == "array" then
            "FakeDNS: " + (.fakedns | map(select(type == "object") | "\(.ipPool // "")(\(.poolSize // 65535))") | join(", ") | cv(.))
        elif (.fakedns | type) == "object" then
            "FakeDNS: \(cv("\(.fakedns.ipPool // "")(\(.fakedns.poolSize // 65535))"))"
        else empty end),
        (if (.observatory | type) == "object" then
            "Observatory: selector=\(cv(arr(.observatory.subjectSelector // .observatory.selector // []))) probe=\(cv(.observatory.probeUrl // .observatory.probeURL // "")) interval=\(cv(.observatory.probeInterval // ""))"
            + (if $core == "xray" then " concurrency=\(yv(.observatory.enableConcurrency // false))" else "" end)
        else empty end),
        (if $core == "xray" and (.burstObservatory | type) == "object" then
            (if (.burstObservatory.pingConfig | type) == "object" then .burstObservatory.pingConfig else {} end) as $pc
            | "BurstObservatory: selector=\(cv(arr(.burstObservatory.subjectSelector // []))) dest=\(cv($pc.destination // "")) interval=\(cv($pc.interval // ""))"
        else empty end),
        (if $core == "xray" and (.metrics | type) == "object" then
            "Metrics: tag=\(cv(.metrics.tag // "")) listen=\(cv(.metrics.listen // ""))"
        else empty end),
        (if $core == "xray" and (.geodata | type) == "object" then
            "Geodata: cron=\(cv(.geodata.cron // "")) outbound=\(cv(.geodata.outbound // "")) assets=\(cv((if (.geodata.assets | type) == "array" then (.geodata.assets | length) else 0 end)))"
        else empty end),
        (if $core == "xray" and (.version | type) == "object" then
            "Version: min=\(cv(.version.min // "")) max=\(cv(.version.max // ""))"
        else empty end),
        (if $core == "v2ray" and (.browserForwarder | type) == "object" then
            "BrowserForwarder: \(cv("\(.browserForwarder.listenAddr // ""):\(.browserForwarder.listenPort // "")"))"
        else empty end)
    ] | join("\n")
    ' "$config_file"
}

ProxyAddBound()
{
    local config_file="$1"
    local bound_type="$2"
    local bound_json="$3"

    if [ "$config_file" == "${X_CONFIG:-}" ]
    then
        ProxyMutateConfigTx "xray" '.[$bt] = ((if (.[$bt] | type) == "array" then .[$bt] else [] end) + [$item])' \
            --arg bt "$bound_type" --argjson item "$bound_json"
        return $?
    elif [ "$config_file" == "${V2_CONFIG:-}" ]
    then
        ProxyMutateConfigTx "v2ray" '.[$bt] = ((if (.[$bt] | type) == "array" then .[$bt] else [] end) + [$item])' \
            --arg bt "$bound_type" --argjson item "$bound_json"
        return $?
    fi

    local rc=0
    jq_path='["'"$bound_type"'"]'
    JQ add "$config_file" "[$bound_json]" || rc=$?
    jq_path=""
    return "$rc"
}

ProxyDeleteBound()
{
    local config_file="$1"
    local bound_type="$2"
    local bound_index="$3"

    if [ "$config_file" == "${X_CONFIG:-}" ]
    then
        ProxyMutateConfigTx "xray" 'if (.[$bt] | type) == "array" then del(.[$bt][$idx]) else . end' \
            --arg bt "$bound_type" --argjson idx "$bound_index"
        return $?
    elif [ "$config_file" == "${V2_CONFIG:-}" ]
    then
        ProxyMutateConfigTx "v2ray" 'if (.[$bt] | type) == "array" then del(.[$bt][$idx]) else . end' \
            --arg bt "$bound_type" --argjson idx "$bound_index"
        return $?
    fi

    local rc=0
    jq_path='["'"$bound_type"'",'"$bound_index"']'
    JQ delete "$config_file" || rc=$?
    jq_path=""
    return "$rc"
}

ProxySelectBound()
{
    local config_file="$1"
    local bound_type="$2"
    local prompt_title="$3"

    local options=()
    local i ridx
    if [ "$bound_type" == "inbounds" ]
    then
        ProxyLoadInboundsIndex "$config_file"
        if [ "$inbounds_count" -eq 0 ]
        then
            Println "$(eval_gettext "\$error 请先添加入站")\n"
            return 1
        fi
        for((i=0;i<inbounds_count;i++));
        do
            ridx="${inbounds_json_index[i]}"
            options+=("$((i+1)). [${inbounds_protocol[ridx]}] ${inbounds_tag[ridx]} (${inbounds_listen[ridx]}:${inbounds_port[ridx]})")
        done
        echo
        inquirer list_input_index "$prompt_title" options selected_bound_index
        selected_bound_index="${inbounds_json_index[selected_bound_index]}"
    else
        ProxyLoadOutboundsIndex "$config_file"
        if [ "$outbounds_count" -eq 0 ]
        then
            Println "$(eval_gettext "\$error 没有出站")\n"
            return 1
        fi
        for((i=0;i<outbounds_count;i++));
        do
            ridx="${outbounds_json_index[i]}"
            options+=("$((i+1)). [${outbounds_protocol[ridx]}] ${outbounds_tag[ridx]} (${outbounds_sendThrough[ridx]})")
        done
        echo
        inquirer list_input_index "$prompt_title" options selected_bound_index
        selected_bound_index="${outbounds_json_index[selected_bound_index]}"
    fi
}

ProxyToggleService()
{
    local service_name="$1"
    local config_file="$2"
    [ "$service_name" == "xray" ] && service_name="aios-xray"
    [ "$service_name" == "v2ray" ] && service_name="aios-v2ray"

    if [ ! -e "$config_file" ]
    then
        Println "$(eval_gettext "\$error \$service_name 未安装...")\n"
        exit 1
    fi

    echo
    local err_msg=""
    if ServiceControl is-active "$service_name"
    then
        ExitOnList y "$(eval_gettext "\$service_name 正在运行, 是否关闭")"
        if err_msg=$(ServiceControl stop "$service_name" 2>&1)
        then
            Println "$(eval_gettext "\$info \$service_name 已关闭")\n"
        else
            Println "$(eval_gettext "\$error \$service_name 关闭失败: \${err_msg}")\n"
            return 1
        fi
    else
        ExitOnList y "$(eval_gettext "\$service_name 未运行, 是否开启")"
        if err_msg=$(ServiceControl start "$service_name" 2>&1)
        then
            Println "$(eval_gettext "\$info \$service_name 已开启")\n"
        else
            Println "$(eval_gettext "\$error \$service_name 开启失败: \${err_msg}")\n"
            return 1
        fi
    fi
}

ProxyRestartService()
{
    local service_name="$1"
    local config_file="$2"
    [ "$service_name" == "xray" ] && service_name="aios-xray"
    [ "$service_name" == "v2ray" ] && service_name="aios-v2ray"

    if [ ! -e "$config_file" ]
    then
        Println "$(eval_gettext "\$error \$service_name 未安装...")\n"
        exit 1
    fi

    local err_msg=""
    if err_msg=$(ServiceControl restart "$service_name" 2>&1)
    then
        Println "$(eval_gettext "\$info \$service_name 已重启")\n"
    else
        Println "$(eval_gettext "\$error \$service_name 重启失败: \${err_msg}")\n"
        return 1
    fi
}

ProxyRestartIfActive()
{
    local service_name="$1"
    [ "$service_name" == "xray" ] && service_name="aios-xray"
    [ "$service_name" == "v2ray" ] && service_name="aios-v2ray"
    if ServiceControl is-active "$service_name"
    then
        local err_msg=""
        if ! err_msg=$(ServiceControl restart "$service_name" 2>&1)
        then
            Println "$(eval_gettext "\$error \$service_name 重启失败: \${err_msg}")\n"
            return 1
        fi
    fi
}
ServiceResolveLabel()
{
    [ -z "${dist:-}" ] && DistCheck

    local raw_id="$1"
    service_label="$raw_id"

    case "$raw_id" in
        aios-xray|aios-v2ray)
            if [ "$dist" == "mac" ]
            then
                service_label="com.aios.${raw_id}"
                service_file="$HOME/Library/LaunchAgents/${service_label}.plist"
            else
                service_label="$raw_id"
                service_file="/etc/systemd/system/${service_label}.service"
            fi
            return 0
        ;;
        v2ray|xray|nginx|openresty|trojan|dnscrypt-proxy)
            if [ "$dist" == "mac" ]
            then
                service_file="$HOME/Library/LaunchAgents/${service_label}.plist"
            else
                service_file="/etc/systemd/system/${service_label}.service"
            fi
            return 0
        ;;
    esac

    if [ "$dist" == "mac" ]
    then
        service_label="com.aios.$raw_id"
        service_file="$HOME/Library/LaunchAgents/${service_label}.plist"
    else
        service_label="aios.$raw_id"
        service_file="/etc/systemd/system/${service_label}.service"
    fi
}

ServiceControlIsActive()
{
    ServiceResolveLabel "$1"
    if [ "$dist" == "mac" ]
    then
        if [ ! -f "$service_file" ] || ! { launchctl print "gui/$UID/$service_label" 2> /dev/null | grep -q "pid ="; }
        then
            return 1
        fi
    else
        if [ ! -f "$service_file" ] || ! systemctl is-active --quiet "$service_label"
        then
            return 1
        fi
    fi
    return 0
}

ServiceControlIsEnabled()
{
    ServiceResolveLabel "$1"

    if [ "$dist" == "mac" ]
    then
        if [ ! -f "$service_file" ]
        then
            return 1
        fi
    else
        if command -v systemctl > /dev/null 2>&1
        then
            if ! systemctl is-enabled --quiet "$service_label" 2> /dev/null
            then
                return 1
            fi
        elif [ ! -f "$service_file" ]
        then
            return 1
        fi
    fi
    return 0
}

ServiceControlStatus()
{
    ServiceResolveLabel "$1"
    if [ "$dist" == "mac" ]
    then
        launchctl print "gui/$UID/$service_label"
    else
        systemctl --no-pager -l status "$service_label"
    fi
}

ServiceControlStart()
{
    if ServiceControlIsActive "$1"
    then
        printf '%s\n' "$(gettext "服务已启动")"
        return 0
    fi

    local args=() arg arr

    if [ -n "${2:-}" ]
    then
        local var=("$2"[@])
        if [[ -n "${!var:-}" ]]
        then
            args=("${!var}")
            if [[ ! -x "${args[0]}" ]]
            then
                echo "${args[0]} $(gettext "不存在")"
                return 1
            fi
        fi
    fi

    if [ "${#args[@]}" -eq 0 ] && [ ! -f "$service_file" ]
    then
        printf '%s\n' "$(eval_gettext "\$service_file 不存在")"
        return 1
    fi

    if [ "$dist" == "mac" ]
    then
        if [ ! -f "$service_file" ] || [ -n "${3:-}" ]
        then
            arr="<array>"
            for arg in "${args[@]}"
            do
                arr="$arr\n        <string>$arg</string>"
            done
            arr="$arr\n    </array>"
            arr=$(echo -e "$arr")
cat > "$service_file" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>$service_label</string>
    <key>ProgramArguments</key>
    $arr
    <key>RunAtLoad</key>
    <true/>
    <key>KeepAlive</key>
    <true/>
</dict>
</plist>
EOF
        fi
        launchctl load "$service_file"
    else
        if [ ! -f "$service_file" ] || [ -n "${3:-}" ]
        then
            local work_dir="/"
            if [ "${#args[@]}" -gt 0 ]
            then
                work_dir="${args[0]%/*}/"
            fi
cat > "$service_file" <<EOF
[Unit]
Description=${service_label}
After=syslog.target network-online.target nss-lookup.target
Wants=network-online.target

[Service]
ExecStart=${args[*]}
WorkingDirectory=${work_dir}
StartLimitInterval=60s
StartLimitBurst=5
RestartSec=5
Restart=on-failure

[Install]
WantedBy=multi-user.target
EOF
        fi
        systemctl daemon-reload
        systemctl enable "${service_label}.service"
        systemctl start "${service_label}.service"
    fi
}

ServiceControlStop()
{
    if ! ServiceControlIsActive "$1"
    then
        printf '%s\n' "$(gettext "服务未启动")"
        return 0
    fi

    if [ "$dist" == "mac" ]
    then
        launchctl unload "$service_file"
    else
        systemctl stop "${service_label}.service"
    fi
}

ServiceControlRestart()
{
    if ServiceControlIsActive "$1"
    then
        ServiceControlStop "$1"
    fi

    ServiceControlStart "$@"
}

ServiceControlDisable()
{
    if ServiceControlIsActive "$1"
    then
        ServiceControlStop "$1"
    fi

    if [ "$dist" == "mac" ]
    then
        rm -f "$service_file"
    else
        systemctl disable "${service_label}".service --now > /dev/null 2> /dev/null || true
        rm -f /etc/systemd/system/"${service_label}".service
        rm -f /lib/systemd/system/"${service_label}".service
        rm -f /etc/init.d/"${service_label}"
    fi
}

ServiceControlRename()
{
    local old_service_file="" new_service_file=""
    ServiceResolveLabel "$1"
    old_service_file="$service_file"
    ServiceResolveLabel "$2"
    new_service_file="$service_file"
    mv "$old_service_file" "$new_service_file"
}

ServiceControl()
{
    DistCheck

    local cmd=$1
    shift
    case $cmd in
        is-active)
            ServiceControlIsActive "$@"
        ;;
        is-enabled)
            ServiceControlIsEnabled "$@"
        ;;
        status)
            ServiceControlStatus "$@"
        ;;
        start)
            ServiceControlStart "$@"
        ;;
        stop)
            ServiceControlStop "$@"
        ;;
        restart)
            ServiceControlRestart "$@"
        ;;
        disable)
            ServiceControlDisable "$@"
        ;;
        rename)
            ServiceControlRename "$@"
        ;;
    esac
    return $?
}
PythonInstall()
{
    if [[ -x $(command -v python3) ]] && [[ -x $(command -v pip3) ]] 
    then
        return 0
    fi

    Println "`eval_gettext \"\\\$info 安装 python3 ...\"`"

    Progress &
    progress_pid=$!

    trap '
        kill $progress_pid
        wait $progress_pid 2> /dev/null
    ' EXIT

    if [ "$dist" == "mac" ] 
    then
        DepInstall python > /dev/null
    elif [ "$dist" == "rpm" ] 
    then
        if ! yum -y install python3 python3-pip > /dev/null 2>&1
        then
            yum groupinstall -y 'Development Tools' >/dev/null 2>&1
            yum install -y gcc openssl-devel bzip2-devel libffi-devel >/dev/null 2>&1
            echo -n "...50%..."
            cd ~
            wget --timeout=10 --tries=3 --no-check-certificate "${PYTHON_FTP_LINK}/${PYTHON_FALLBACK_VER}/Python-${PYTHON_FALLBACK_VER}.tgz" -qO "Python-${PYTHON_FALLBACK_VER}.tgz"
            tar xzf "Python-${PYTHON_FALLBACK_VER}.tgz"
            cd "Python-${PYTHON_FALLBACK_VER}"
            ./configure >/dev/null 2>&1
            make >/dev/null 2>&1
            make install >/dev/null 2>&1
            pip3 install requests > /dev/null
        fi
    else
        AptInstall python3 python3-pip
    fi

    kill $progress_pid
    wait $progress_pid 2> /dev/null || true
    trap - EXIT
    echo "...100%"
}
OpensslFetchPackUrl()
{
    local list_url="${1%/}"
    local major_filter="${2:-}"
    local href=""

    href=$(curl -s -L "${list_url}/" \
        | grep -oE "href=\"[^\"]*openssl-[0-9]+\.[0-9]+\.[0-9]+[a-z]?\.tar\.gz\"" \
        | sed -E 's/^href="//; s/"$//' \
        | while IFS= read -r u
          do
              local fname="${u##*/}"
              if [ -z "$major_filter" ] || [[ "$fname" == openssl-${major_filter}.* ]]
              then
                  printf '%s\n' "$u"
                  break
              fi
          done)

    if [ -z "$href" ]
    then
        return 1
    fi

    if [[ "$href" == http://* ]] || [[ "$href" == https://* ]]
    then
        printf '%s\n' "$href"
    else
        printf '%s/%s\n' "$list_url" "${href#./}"
    fi
}

OpensslSourceInstall()
{
    local build_dir=build args=() openssl_path="$DEPENDS_ROOT"/openssl

    DepInstall ca-certificates
    DepInstall perl

    if [ -z "${1:-}" ] 
    then
        openssl_install_options=( openssl@1.1 )
    else
        openssl_install_options=("$@")
    fi

    local openssl_pack_url=""
    if EleInArray openssl@4 openssl_install_options
    then
        openssl_url="$OPENSSL_SOURCE_LINK"
        openssl_path+=4
        openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "4")
    elif EleInArray openssl@3 openssl_install_options
    then
        openssl_url="$OPENSSL_SOURCE_LINK"
        openssl_path+=3
        openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "3")
    else
        openssl_url="$OPENSSL_SOURCE_LINK/old/1.1.1"
        openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "1")
    fi

    if [ -z "$openssl_pack_url" ]
    then
        Println "$(eval_gettext "\$error 无法从 \$openssl_url 获取 OpenSSL 源码包地址")\n"
        return 1
    fi

    openssl_pack="${openssl_pack_url##*/}"
    openssl_name="${openssl_pack%.tar*}"

    if EleInArray static openssl_install_options
    then
        build_dir+=-static
        openssl_path+=-static
    fi

    if [ -d "$DEPENDS_ROOT/$openssl_name/$build_dir" ] 
    then
        ln -sfn "$DEPENDS_ROOT/$openssl_name/$build_dir" "$openssl_path"
        return 0
    fi

    unset OPENSSL_LOCAL_CONFIG_DIR

    args=(
        --prefix="$DEPENDS_ROOT/$openssl_name/$build_dir"
        --openssldir="$DEPENDS_ROOT/$openssl_name/$build_dir"/etc
        --libdir=lib
    )

    if EleInArray static openssl_install_options
    then
        args+=(no-shared)
    fi

    ArchCheck

    if [ "$dist" == "mac" ] 
    then
        export PERL="$HOMEBREW_PREFIX"/opt/perl/bin/perl
        args+=( darwin64-${arch}-cc )
        SourceInstallReady
    else
        case $arch in
            x86_64) args+=( linux-x86_64 )
            ;;
            i386) args+=( linux-elf )
            ;;
            arm64) args+=( linux-aarch64 )
            ;;
            arm*) args+=( linux-armv4 )
            ;;
            *) Println "$(eval_gettext "\$error 不支持的架构 \$arch")\n"; return 1
        esac

        if [ "$dist" == "rpm" ] 
        then
            SourceInstallReady glibc-devel openssl-devel systemd-devel zlib-devel
        else
            SourceInstallReady gcc libc6-dev libssl-dev libsystemd-dev make zlib1g-dev
        fi
    fi

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    curl -L "$openssl_pack_url" -o "$openssl_pack"
    Println "$(eval_gettext "\$info 解压 \$openssl_name ...")"
    tar xzf "$openssl_pack"
    cd "$openssl_name"

    perl ./Configure ${args[@]+"${args[@]}"}
    make
    make install

    ln -sfn "$DEPENDS_ROOT/$openssl_name/$build_dir" "$openssl_path"
}

