GoInstall()
{
    if [[ ! "$PATH" =~ /usr/local/go/bin ]]
    then
        PATH="$PATH":/usr/local/go/bin
    fi

    go_path=${GOPATH:-"$HOME"/go}

    if [[ ! "$PATH" =~ $go_path ]]
    then
        PATH="${PATH}:${go_path}/bin"
    fi

    export PATH

    if [[ -x $(command -v go) ]] 
    then
        go_version_list=($(go version))
        if [[ "${go_version_list[2]}" =~ ^go([0-9]+)\.([0-9]+)\. ]] && [ "${BASH_REMATCH[1]}" -ge 1 ] && [ "${BASH_REMATCH[2]}" -ge 11 ]
        then
            return 0
        fi
    fi

    if [ "$dist" == "mac" ] 
    then
        DepInstall go
        return 0
    fi

    ArchCheck

    DepInstall curl

    JQInstall

    if ! go_version=$(curl -s -Lm 20 "${GO_DL_LINK}/?mode=json" | $JQ_FILE -r '.[0].version')
    then
        Println "$(eval_gettext "\$error 无法连接 go.dev ?")"
        go_version="$GO_FALLBACK_VER"
    fi

    if [ "$arch" == "i386" ] 
    then
        go_package="$go_version.linux-386.tar.gz"
    elif [ "$arch" == "x86_64" ] 
    then
        go_package="$go_version.linux-amd64.tar.gz"
    elif [ "$arch" == "arm64" ] || [ "$arch" == "armv6l" ]
    then
        go_package="$go_version.linux-$arch.tar.gz"
    else
        DepInstall golang
        return 0
    fi

    if ! curl -L "${GO_DL_LINK}/$go_package" -o ~/$go_package && ! curl -L "${GO_DL_MIRROR_LINK}/$go_package" -o ~/$go_package
    then
        Println "$(eval_gettext "\$error 下载 golang 失败, 请稍后再试")\n"
        return 1
    fi

    rm -rf /usr/local/go
    tar -C /usr/local -xzf ~/$go_package
}
NodejsInstall()
{
    if [[ -x $(command -v node) ]] && [[ -x $(command -v npm) ]]
    then
        return 0
    fi

    DepsCheck

    if [ "$dist" == "mac" ] 
    then
        DepInstall node
        return 0
    elif [ "$dist" == "rpm" ] && { [[ -x $(command -v node) ]] || [[ -x $(command -v npm) ]]; }
    then
        yum remove -y nodejs npm || true
    fi

    Progress &
    progress_pid=$!

    trap '
        kill $progress_pid
        wait $progress_pid 2> /dev/null
    ' EXIT

    if [ "$dist" == "rpm" ] 
    then
        yum -y install gcc-c++ make >/dev/null 2>&1
        # yum groupinstall 'Development Tools'

        if curl -fsSL "${NODESOURCE_RPM_LINK}/setup_${NODEJS_VER}.x" | sudo bash - > /dev/null
        then
            sudo yum install -y nsolid > /dev/null 2>&1
        fi
    else
        if curl -fsSL "${NODESOURCE_DEB_LINK}/setup_${NODEJS_VER}.x" | sudo bash - > /dev/null
        then
            AptInstall nodejs
        fi
    fi

    kill $progress_pid
    wait $progress_pid 2> /dev/null || true
    trap - EXIT

    echo -n "...100%"
    Println "$(eval_gettext "\$info nodejs 安装完成")"
}
MongodbInstall()
{
    if [[ -x $(command -v mongod) ]]
    then
        return 0
    fi

    DepsCheck

    if ! ResourceLimit 
    then
        Println "$(eval_gettext "\$error 可能环境是 Unprivileged Container ?")\n"
    fi

    DepInstall curl
    DepInstall ca-certificates

    ArchCheck

    if [ "$arch" == "arm64" ] 
    then
        arch_path="aarch64"
    elif [ "$arch" == "x86_64" ] || [ "$arch" == "s390x" ]
    then
        arch_path="$arch"
    else
        Println "$(eval_gettext "\$error 不支持的系统")\n"
        return 1
    fi

    case $dist in
        mac) 
            if ! xcode-select -p &> /dev/null
            then
                xcode-select --install
            fi
            brew tap mongodb/brew
            macos_version=$(sw_vers -productVersion)
            if [ "${macos_version%%.*}" -lt 12 ] 
            then
                mkdir -p "$DEPENDS_ROOT"
                if ! curl -Lm 20 https://github.com/Homebrew/homebrew-core/raw/HEAD/Formula/m/mongosh.rb -o "$DEPENDS_ROOT"/mongosh.rb
                then
                    curl -Lm 20 "$FFMPEG_MIRROR_LINK"/mongosh.rb -o "$DEPENDS_ROOT"/mongosh.rb
                fi
                sed -i "s/\"node\"/\"node@${NODEJS_VER}\"/g" "$DEPENDS_ROOT"/mongosh.rb
                brew install "$DEPENDS_ROOT"/mongosh.rb
                brew install mongodb-community --without-mongosh
            else
                brew install mongodb-community
            fi
            brew services start mongodb/brew/mongodb-community
            Println "$(eval_gettext "\$info mongodb 安装成功")\n"
            return 0
        ;;
        rpm) 
            DepInstall yum-utils
            if [ ! -f "/etc/yum.repos.d/mongodb-org-${MONGODB_VER}.repo" ] 
            then
                if grep -qi Amazon <<< "$ID" || grep -qi Amazon <<< "$NAME" 
                then
cat > "/etc/yum.repos.d/mongodb-org-${MONGODB_VER}.repo" <<EOF
[mongodb-org-${MONGODB_VER}]
name=MongoDB Repository
baseurl=${MONGODB_REPO_LINK}/yum/amazon/$VERSION/mongodb-org/${MONGODB_VER}/$arch_path/
gpgcheck=1
enabled=1
gpgkey=https://pgp.mongodb.com/server-${MONGODB_VER}.asc
EOF
                else
cat > "/etc/yum.repos.d/mongodb-org-${MONGODB_VER}.repo" <<EOF
[mongodb-org-${MONGODB_VER}]
name=MongoDB Repository
baseurl=${MONGODB_REPO_LINK}/yum/redhat/${VERSION_ID%%.*}/mongodb-org/${MONGODB_VER}/$arch_path/
gpgcheck=1
enabled=1
gpgkey=https://pgp.mongodb.com/server-${MONGODB_VER}.asc
EOF
                fi
            fi
            sudo yum-config-manager --enable "mongodb-org-${MONGODB_VER}"
            sudo yum install -y mongodb-org
        ;;
        ubu) 
            local mongo_codename
            mongo_codename=$(AptGetCodename)

            if [ ! -f "/etc/apt/sources.list.d/mongodb-org-${MONGODB_VER}.list" ] 
            then
                if ! AptRepoCheck "${MONGODB_REPO_LINK}/apt/ubuntu" "${mongo_codename}/mongodb-org/${MONGODB_VER}"
                then
                    local mongo_codename_text="${mongo_codename:-unknown}"
                    Println "$(eval_gettext "\$error MongoDB \${MONGODB_VER} 官方源暂不支持当前系统 (\$mongo_codename_text), 未写入失效源")\n"
                    return 1
                fi

                DepInstall ubuntu-keyring
                DepInstall gpg
                curl -fsSL "https://www.mongodb.org/static/pgp/server-${MONGODB_VER}.asc" | gpg --batch --yes --dearmor -o "/usr/share/keyrings/mongodb-server-${MONGODB_VER}.gpg"
                echo "deb [arch=amd64,arm64 signed-by=/usr/share/keyrings/mongodb-server-${MONGODB_VER}.gpg] ${MONGODB_REPO_LINK}/apt/ubuntu \
                ${mongo_codename}/mongodb-org/${MONGODB_VER} multiverse" | tee "/etc/apt/sources.list.d/mongodb-org-${MONGODB_VER}.list"
                AptUpdate force
            fi

            AptInstall mongodb-org
        ;;
        deb)
            local mongo_codename
            mongo_codename=$(AptGetCodename)

            if [ ! -f "/etc/apt/sources.list.d/mongodb-org-${MONGODB_VER}.list" ] 
            then
                if ! AptRepoCheck "${MONGODB_REPO_LINK}/apt/debian" "${mongo_codename}/mongodb-org/${MONGODB_VER}"
                then
                    local mongo_codename_text="${mongo_codename:-unknown}"
                    Println "$(eval_gettext "\$error MongoDB \${MONGODB_VER} 官方源暂不支持当前系统 (\$mongo_codename_text), 未写入失效源")\n"
                    return 1
                fi

                DepInstall debian-archive-keyring
                DepInstall gpg
                curl -fsSL "https://www.mongodb.org/static/pgp/server-${MONGODB_VER}.asc" | gpg --batch --yes --dearmor -o "/usr/share/keyrings/mongodb-server-${MONGODB_VER}.gpg"
                echo "deb [ signed-by=/usr/share/keyrings/mongodb-server-${MONGODB_VER}.gpg ] ${MONGODB_REPO_LINK}/apt/debian \
                ${mongo_codename}/mongodb-org/${MONGODB_VER} main" | tee "/etc/apt/sources.list.d/mongodb-org-${MONGODB_VER}.list"
                AptUpdate force
            fi

            AptInstall mongodb-org
        ;;
        sles)
            sudo zypper addrepo --gpgcheck "${MONGODB_REPO_LINK}/zypper/suse/${VERSION_ID%%.*}/mongodb-org/${MONGODB_VER}/$arch_path/" mongodb
            sudo zypper -n install mongodb-org
        ;;
    esac

    if [[ $(ps --no-headers -o comm 1) == "systemd" ]] 
    then
        sed -i "s/LimitNOFILE=.*/LimitNOFILE=$file_max/" /lib/systemd/system/mongod.service
        sed -i '/TasksAccounting=/a StartLimitInterval=60s\nStartLimitBurst=5\nRestartSec=5\nRestart=on-failure' /lib/systemd/system/mongod.service
        systemctl daemon-reload
        sed -i "s/destination: file/destination: syslog/" /etc/mongod.conf
        sed -i "s/  logAppend: true/  #logAppend: true/" /etc/mongod.conf
        sed -i "s+  path: /var/log/mongodb/mongod.log+  #path: /var/log/mongodb/mongod.log+" /etc/mongod.conf
        systemctl start mongod
        systemctl enable mongod
    else
        service mongod start
    fi

    Println "$(eval_gettext "\$info mongodb 安装成功")\n"
}
ServiceGet()
{
    JQInstall

    local service_id=$1

    if [ ! -s "$SERVICES_CONFIG" ] 
    then
        mkdir -p "$SERVICES_ROOT"
        printf '{"%s":{"%s":[]}}' "4gtv" "accounts" > "$SERVICES_CONFIG"
    fi

    SetDelimiters

    jq_payload=$(JQs flat "$SERVICES_CONFIG")

    case $service_id in
        4gtv) 
            jq_path='[
                ["4gtv","proxy"],
                ["4gtv","accounts","email"],
                ["4gtv","accounts","password"],
                ["4gtv","accounts","token"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            d_4gtv_proxy="$jq_4gtv_proxy"
            _4gtv_acc_email="$jq_4gtv_accounts_email"
            _4gtv_acc_pass="$jq_4gtv_accounts_password"
            _4gtv_acc_token="$jq_4gtv_accounts_token"

            IFS="${delimiters[3]}" read -r -a _4gtv_accs_email <<< "$_4gtv_acc_email"
            IFS="${delimiters[3]}" read -r -a _4gtv_accs_pass <<< "$_4gtv_acc_pass"
            IFS="${delimiters[3]}" read -r -a _4gtv_accs_token <<< "$_4gtv_acc_token"

            _4gtv_accs_count=${#_4gtv_accs_email[@]}
        ;;
        openlist) 
            jq_path='[
                ["openlist","name"],
                ["openlist","url"],
                ["openlist","accs","username"],
                ["openlist","accs","password"],
                ["openlist","accs","token"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            IFS="${delimiters[2]}" read -r -a openlists_name <<< "$jq_openlist_name"
            IFS="${delimiters[2]}" read -r -a openlists_url <<< "$jq_openlist_url"
            IFS="${delimiters[3]}" read -r -a openlists_acc_username <<< "$jq_openlist_accs_username"
            IFS="${delimiters[3]}" read -r -a openlists_acc_password <<< "$jq_openlist_accs_password"
            IFS="${delimiters[3]}" read -r -a openlists_acc_token <<< "$jq_openlist_accs_token"

            openlists_count=${#openlists_name[@]}
        ;;
        rclone) 
        case ${2:-} in
            serve) 
                jq_path='[
                    ["rclone","serve","remote"],
                    ["rclone","serve","protocol"],
                    ["rclone","serve","addr"],
                    ["rclone","serve","htpasswd"],
                    ["rclone","serve","args"],
                    ["rclone","serve","accs","user"],
                    ["rclone","serve","accs","pass"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                IFS="${delimiters[3]}" read -r -a rclone_serves_remote <<< "$jq_rclone_serve_remote"
                IFS="${delimiters[3]}" read -r -a rclone_serves_protocol <<< "$jq_rclone_serve_protocol"
                IFS="${delimiters[3]}" read -r -a rclone_serves_addr <<< "$jq_rclone_serve_addr"
                IFS="${delimiters[3]}" read -r -a rclone_serves_htpasswd <<< "$jq_rclone_serve_htpasswd"
                IFS="${delimiters[3]}" read -r -a rclone_serves_args <<< "$jq_rclone_serve_args"
                IFS="${delimiters[4]}" read -r -a rclone_serves_user <<< "$jq_rclone_serve_accs_user"
                IFS="${delimiters[4]}" read -r -a rclone_serves_pass <<< "$jq_rclone_serve_accs_pass"

                rclone_serves_count=${#rclone_serves_remote[@]}
            ;;
            sync) 
                jq_path='[
                    ["rclone","sync","rsync"],
                    ["rclone","sync","source"],
                    ["rclone","sync","target"],
                    ["rclone","sync","args"],
                    ["rclone","sync","exclude_before"],
                    ["rclone","sync","include"],
                    ["rclone","sync","exclude_after"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                IFS="${delimiters[3]}" read -r -a rclone_syncs_rsync <<< "$jq_rclone_sync_rsync"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_source <<< "$jq_rclone_sync_source"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_target <<< "$jq_rclone_sync_target"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_args <<< "$jq_rclone_sync_args"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_exclude_before <<< "$jq_rclone_sync_exclude_before"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_include <<< "$jq_rclone_sync_include"
                IFS="${delimiters[3]}" read -r -a rclone_syncs_exclude_after <<< "$jq_rclone_sync_exclude_after"

                rclone_syncs_count=${#rclone_syncs_rsync[@]}
            ;;
            *) 
                jq_path='[
                    ["rclone","remote","name"],
                    ["rclone","remote","type"],
                    ["rclone","remote","url"],
                    ["rclone","remote","vendor"],
                    ["rclone","remote","user"],
                    ["rclone","remote","pass"],
                    ["rclone","remote","mount","path"],
                    ["rclone","remote","mount","mount_path"],
                    ["rclone","remote","mount","flags"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                IFS="${delimiters[3]}" read -r -a rclone_remotes_name <<< "$jq_rclone_remote_name"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_type <<< "$jq_rclone_remote_type"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_url <<< "$jq_rclone_remote_url"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_vendor <<< "$jq_rclone_remote_vendor"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_user <<< "$jq_rclone_remote_user"
                IFS="${delimiters[3]}" read -r -a rclone_remotes_pass <<< "$jq_rclone_remote_pass"
                IFS="${delimiters[4]}" read -r -a rclone_remotes_path <<< "$jq_rclone_remote_mount_path"
                IFS="${delimiters[4]}" read -r -a rclone_remotes_mount_path <<< "$jq_rclone_remote_mount_mount_path"
                IFS="${delimiters[4]}" read -r -a rclone_remotes_mount_flag <<< "${jq_rclone_remote_mount_flags}"

                rclone_remotes_count=${#rclone_remotes_name[@]}
            ;;
        esac
        ;;
        kcc)
            jq_path='[
                ["kcc","format"],
                ["kcc","process"],
                ["kcc","args"],
                ["kcc","output"],
                ["kcc","source"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            kcc_format="$jq_kcc_format"
            kcc_process="$jq_kcc_process"
            kcc_args="$jq_kcc_args"
            kcc_output="$jq_kcc_output"

            IFS="${delimiters[2]}" read -r -a kcc_sources <<< "$jq_kcc_source"
        ;;
        iperf)
            jq_path='[
                ["iperf","name"],
                ["iperf","type"],
                ["iperf","target"],
                ["iperf","args"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            IFS="${delimiters[2]}" read -r -a iperf_names <<< "$jq_iperf_name"
            IFS="${delimiters[2]}" read -r -a iperf_types <<< "$jq_iperf_type"
            IFS="${delimiters[2]}" read -r -a iperf_targets <<< "$jq_iperf_target"
            IFS="${delimiters[2]}" read -r -a iperf_args <<< "$jq_iperf_args"

            iperf_count=${#iperf_types[@]}
        ;;
        *)
            jq_path='[
                ["'"$service_id"'","accounts","user_name"],
                ["'"$service_id"'","accounts","phone_number"],
                ["'"$service_id"'","accounts","password"],
                ["'"$service_id"'","accounts","access_token"],
                ["'"$service_id"'","accounts","device_no"],
                ["'"$service_id"'","accounts","device_id"],
                ["'"$service_id"'","accounts","refresh"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name##*_accounts_}
                var_name=m_"$var_name"
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            if [ -z "$m_user_name" ] 
            then
                ts_accs_count=0
                return 0
            fi

            IFS="${delimiters[3]}" read -r -a ts_accs_user_name <<< "$m_user_name"

            if [ -z "$m_phone_number" ] 
            then
                ts_accs_phone_number=("${ts_accs_user_name[@]//*/}")
            else
                IFS="${delimiters[3]}" read -r -a ts_accs_phone_number <<< "$m_phone_number"
            fi

            IFS="${delimiters[3]}" read -r -a ts_accs_password <<< "$m_password"
            IFS="${delimiters[3]}" read -r -a ts_accs_access_token <<< "$m_access_token"
            IFS="${delimiters[3]}" read -r -a ts_accs_device_no <<< "$m_device_no"
            IFS="${delimiters[3]}" read -r -a ts_accs_device_id <<< "$m_device_id"
            IFS="${delimiters[3]}" read -r -a ts_accs_refresh <<< "$m_refresh"

            ts_accs_count=${#ts_accs_user_name[@]}
        ;;
    esac

    return 0
}
NginxParseConfig()
{
    CrossplaneInstall

    if TMP_FILE=$(mktemp -q)
    then
        chmod +r "$TMP_FILE"
    else
        exit $?
    fi

    trap '
        rm -f "$TMP_FILE"
    ' EXIT

    if [ -z "${1:-}" ] 
    then
        parse_file="$nginx_prefix/conf/nginx.conf"
        parse_in=$(< $parse_file)
        parse_domain=0
    else
        parse_file="$nginx_prefix/conf/sites_available/$1.conf"
        parse_in="http {$(< $parse_file)}"
        parse_domain=1
    fi

    echo "$parse_in" > "$TMP_FILE"

    parse_out=$(crossplane parse "$TMP_FILE" --single-file)

    rm -f "$TMP_FILE"

    trap - EXIT

    jq_path='["config",0,"file"]'
    JQs update parse_out "$parse_file"
}
NginxGetConfig()
{
    SetDelimiters

    local jq_status="" jq_errors_error=""
    local jq_l1_dir="" jq_l1_args=""
    local jq_l2_dir="" jq_l2_args=""
    local jq_l3_dir="" jq_l3_args=""
    local jq_l4_dir="" jq_l4_args=""
    local jq_l5_dir="" jq_l5_args=""
    local key val

    while IFS="$field_sep" read -r key val
    do
        case "$key" in
            status) jq_status="$val" ;;
            errors) jq_errors_error="$val" ;;
            l1_dir) jq_l1_dir="$val" ;;
            l1_args) jq_l1_args="$val" ;;
            l2_dir) jq_l2_dir="$val" ;;
            l2_args) jq_l2_args="$val" ;;
            l3_dir) jq_l3_dir="$val" ;;
            l3_args) jq_l3_args="$val" ;;
            l4_dir) jq_l4_dir="$val" ;;
            l4_args) jq_l4_args="$val" ;;
            l5_dir) jq_l5_dir="$val" ;;
            l5_args) jq_l5_args="$val" ;;
        esac
    done < <($JQ_FILE -r --arg sep "$field_sep" --argjson d "$json_delimiters" '
        def jp($sep): if length == 0 then "" else map((. // "") + $sep) | join("") end;
        def arr_objs($x): if ($x | type) == "array" then ($x | map(select(type == "object"))) else [] end;
        def ea($sep): if (.args | type) == "array" then (.args | map(tostring) | join($sep)) else (.args // "" | tostring) end;
        def b: arr_objs(.block);
        (if (.config | type) == "array" and ((.config[0] // null) | type) == "object" then arr_objs(.config[0].parsed) else [] end) as $l1
        | ($l1 | map(b)) as $l2
        | ($l2 | map(map(b))) as $l3
        | ($l3 | map(map(map(b)))) as $l4
        | ($l4 | map(map(map(map(b))))) as $l5
        | [
            ["status", (if (.status | type) == "string" then .status else "" end)],
            ["errors", (if (.errors | type) == "array" then (.errors | map(if type == "object" then (.error // "") else tostring end) | join($d[0])) else "" end)],
            ["l1_dir", ($l1 | map(.directive // "") | jp($d[3]))],
            ["l1_args", ($l1 | map(ea($d[4])) | jp($d[3]))],
            ["l2_dir", (if ($l2 | map(length) | add // 0) == 0 then "" else ($l2 | map(map(.directive // "") | jp($d[4])) | jp($d[3])) end)],
            ["l2_args", (if ($l2 | map(length) | add // 0) == 0 then "" else ($l2 | map(map(ea($d[5])) | jp($d[4])) | jp($d[3])) end)],
            ["l3_dir", (if ($l3 | map(map(length) | add // 0) | add // 0) == 0 then "" else ($l3 | map(map(map(.directive // "") | jp($d[6])) | jp($d[5])) | jp($d[4])) end)],
            ["l3_args", (if ($l3 | map(map(length) | add // 0) | add // 0) == 0 then "" else ($l3 | map(map(map(ea($d[7])) | jp($d[6])) | jp($d[5])) | jp($d[4])) end)],
            ["l4_dir", (if ($l4 | map(map(map(length) | add // 0) | add // 0) | add // 0) == 0 then "" else ($l4 | map(map(map(map(.directive // "") | jp($d[8])) | jp($d[7])) | jp($d[6])) | jp($d[5])) end)],
            ["l4_args", (if ($l4 | map(map(map(length) | add // 0) | add // 0) | add // 0) == 0 then "" else ($l4 | map(map(map(map(ea($d[9])) | jp($d[8])) | jp($d[7])) | jp($d[6])) | jp($d[5])) end)],
            ["l5_dir", (if ($l5 | map(map(map(map(length) | add // 0) | add // 0) | add // 0) | add // 0) == 0 then "" else ($l5 | map(map(map(map(map(.directive // "") | jp($d[10])) | jp($d[9])) | jp($d[8])) | jp($d[7])) | jp($d[6])) end)],
            ["l5_args", (if ($l5 | map(map(map(map(length) | add // 0) | add // 0) | add // 0) | add // 0) == 0 then "" else ($l5 | map(map(map(map(map(ea($d[11])) | jp($d[10])) | jp($d[9])) | jp($d[8])) | jp($d[7])) | jp($d[6])) end)]
          ][]
        | "\(.[0])\($sep)\(.[1])"
    ' <<< "$parse_out")

    status="$jq_status"
    error_message="$jq_errors_error"
    level_1_directive="$jq_l1_dir"
    level_1_args="$jq_l1_args"
    level_2_directive="$jq_l2_dir"
    level_2_args="$jq_l2_args"
    level_3_directive="$jq_l3_dir"
    level_3_args="$jq_l3_args"
    level_4_directive="$jq_l4_dir"
    level_4_args="$jq_l4_args"
    level_5_directive="$jq_l5_dir"
    level_5_args="$jq_l5_args"

    if [ "$status" == "failed" ]
    then
        Println "$error ${error_message//${delimiters[0]}/$'\n'}\n"
        exit 1
    fi

    # level 1 - stream,http...
    # level 2 - map,upstream,server...
    # level 3 - location...
    # level 4 - proxy_pass,root,index...
    # level 5 - return...

    level_1_count=0
    level_2_d1_count=0
    level_3_d1_count=0
    level_4_d1_count=0
    level_5_d1_count=0

    level_1_directive_arr=()
    level_1_args_arr=()
    level_2_directive_arr=()
    level_2_args_arr=()
    level_3_directive_arr=()
    level_3_args_arr=()
    level_4_directive_arr=()
    level_4_args_arr=()
    level_5_directive_arr=()
    level_5_args_arr=()

    if [ -z "$level_1_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[3]}" read -r -a level_1_directive_arr <<< "$level_1_directive"
    IFS="${delimiters[3]}" read -r -a level_1_args_arr <<< "$level_1_args"

    level_1_count=${#level_1_directive_arr[@]}

    if [ -z "$level_2_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[3]}" read -r -a level_2_directive_arr <<< "$level_2_directive"
    IFS="${delimiters[3]}" read -r -a level_2_args_arr <<< "$level_2_args"

    level_2_d1_count=${#level_2_directive_arr[@]}

    if [ -z "$level_3_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[4]}" read -r -a level_3_directive_arr <<< "$level_3_directive"
    IFS="${delimiters[4]}" read -r -a level_3_args_arr <<< "$level_3_args"

    level_3_d1_count=${#level_3_directive_arr[@]}

    if [ -z "$level_4_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[5]}" read -r -a level_4_directive_arr <<< "$level_4_directive"
    IFS="${delimiters[5]}" read -r -a level_4_args_arr <<< "$level_4_args"

    level_4_d1_count=${#level_4_directive_arr[@]}

    if [ -z "$level_5_directive" ]
    then
        return 0
    fi

    IFS="${delimiters[6]}" read -r -a level_5_directive_arr <<< "$level_5_directive"
    IFS="${delimiters[6]}" read -r -a level_5_args_arr <<< "$level_5_args"

    level_5_d1_count=${#level_5_directive_arr[@]}
}
NginxBuildConf()
{
    if TMP_FILE=$(mktemp -q)
    then
        chmod +r "$TMP_FILE"
    else
        exit $?
    fi

    trap '
        rm -f "$TMP_FILE"
    ' EXIT

    if [ "$parse_domain" -eq 1 ]
    then
        parse_out_domain=${!1}
        jq_path='["config",0,"parsed",0,"block"]'
        domain_conf=$(JQs get parse_out_domain)
        jq_path='["config",0,"parsed"]'
        JQs replace parse_out_domain "$domain_conf"
        echo "$parse_out_domain" > "$TMP_FILE"
    else
        echo "${!1}" > "$TMP_FILE"
    fi

    crossplane build -f --no-headers "$TMP_FILE"

    rm -f "$TMP_FILE"

    trap - EXIT
}
AcmeCheck()
{
    [ -n "${ca_server:-}" ] && return 0

    if [ ! -f "$HOME/.acme.sh/acme.sh" ] 
    then
        DepInstall socat
        mkdir -p "$DEPENDS_ROOT"
        { curl -s -m 20 https://raw.githubusercontent.com/acmesh-official/acme.sh/master/acme.sh || curl -s -m 20 "$FFMPEG_MIRROR_LINK/acme.sh"; } \
        | sed "s+https://raw.githubusercontent.com/acmesh-official+$FFMPEG_MIRROR_LINK/acmesh-content+g" \
        | sed "s+| sh+| sed 's~PROJECT=\"https://github.com/acmesh-official~PROJECT=\"$FFMPEG_MIRROR_LINK/acmesh-project~' | sed 's~https://api.github.com~$FFMPEG_MIRROR_LINK/acmesh-api~g' | sh+g" > "$DEPENDS_ROOT"/acme.sh
        cd "$DEPENDS_ROOT"
        bash acme.sh --install
    else
        echo
        inquirer list_input_index "$(gettext "更新 acme.sh")" ny_options ny_index

        if [ "$ny_index" -eq 1 ] 
        then
            ~/.acme.sh/acme.sh --upgrade
        fi
    fi

    Println "$(eval_gettext "\$tip zerossl 不支持 tls-alpn-01")"
    ca_options=( letsencrypt zerossl )
    inquirer list_input "$(gettext "选择 CA")" ca_options ca_server

    if [ "$ca_server" == "zerossl" ] 
    then
        if [ -e ~/.acme.sh/ca/acme.zerossl.com/ca.conf ] 
        then
            . ~/.acme.sh/ca/acme.zerossl.com/ca.conf
        elif [ -e ~/.acme.sh/ca/acme.zerossl.com/v2/DV90/ca.conf ] 
        then
            . ~/.acme.sh/ca/acme.zerossl.com/v2/DV90/ca.conf
        fi

        if [ -n "${CA_EAB_KEY_ID:-}" ] && [ -n "${CA_EAB_HMAC_KEY:-}" ]
        then
            Println "$(eval_gettext "\$tip 请确保已有账号的 EAB 认证信息未过期, 否则请重新设置")"
            inquirer list_input "$(gettext "是否重新设置 zerossl 账号")" ny_options yn_option
            if [ "$yn_option" == "$i18n_no" ] 
            then
                return 0
            fi
        fi

        echo
        zerossl_options=( "$(gettext "注册新账号")" "$(gettext "输入已有账号的 EAB 认证信息")" )
        inquirer list_input_index "$(gettext "未发现 zerossl 账号")" zerossl_options zerossl_options_index

        if [ "$zerossl_options_index" -eq 0 ] 
        then
            echo
            ExitOnText "$(gettext "输入邮箱: ")" zerossl_email

            if ! ~/.acme.sh/acme.sh --register-account -m "$zerossl_email" --server zerossl 
            then
                Println "$(eval_gettext "\$error 注册账号失败, 请稍后再试或前往官网注册 https://app.zerossl.com/signup?fpr=iptv-sh ")\n"
                exit 1
            fi
        else
            Println "$(eval_gettext "\$tip 可以在 https://app.zerossl.com/developer?fpr=iptv-sh 页面获取")"
            ExitOnText "$(gettext "输入 EAB KID: ")" zerossl_eab_kid

            echo
            ExitOnText "$(gettext "输入 EAB HMAC Key: ")" zerossl_eab_hmac_key

            if ! ~/.acme.sh/acme.sh --register-account --server zerossl --eab-kid "$zerossl_eab_kid" --eab-hmac-key "$zerossl_eab_hmac_key" 
            then
                Println "$(eval_gettext "\$error 注册账号失败, 请确保输入正确")\n"
                exit 1
            fi
        fi

        Println "$(eval_gettext "\$info 账号注册成功")\n"
    fi
}
NginxPackageInstall()
{
    DepInstall curl
    DepInstall ca-certificates

    . /etc/os-release

    case $dist in
        ubu)
            local nginx_codename nginx_repo_base
            nginx_codename=$(AptGetCodename)

            if [ ! -f /etc/apt/sources.list.d/nginx.list ]
            then
                if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                then
                    nginx_repo_base="https://${USTC_MIRROR_HOST}/nginx/mainline/ubuntu"
                else
                    nginx_repo_base="${NGINX_REPO_LINK}/ubuntu"
                fi

                if AptRepoCheck "$nginx_repo_base" "$nginx_codename"
                then
                    DepInstall ubuntu-keyring
                    DepInstall gpg
                    curl -fsSL https://nginx.org/keys/nginx_signing.key | gpg --batch --yes --dearmor -o /usr/share/keyrings/nginx-archive-keyring.gpg
                    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/nginx-archive-keyring.gpg] ${nginx_repo_base} \
                    ${nginx_codename} nginx" | tee /etc/apt/sources.list.d/nginx.list
                    echo -e "Package: *\nPin: origin nginx.org\nPin: release o=nginx\nPin-Priority: 900\n" | sudo tee /etc/apt/preferences.d/99nginx
                    AptUpdate force
                else
                    local nginx_codename_display="${nginx_codename:-unknown}"
                    Println "$(eval_gettext "\$tip Nginx 官方源暂不支持当前系统 (\$nginx_codename_display), 改用系统默认源安装")"
                fi
            fi

            AptInstall nginx
        ;;
        deb)
            local nginx_codename nginx_repo_base
            nginx_codename=$(AptGetCodename)

            if [ ! -f /etc/apt/sources.list.d/nginx.list ]
            then
                if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                then
                    nginx_repo_base="https://${USTC_MIRROR_HOST}/nginx/mainline/debian"
                else
                    nginx_repo_base="${NGINX_REPO_LINK}/debian"
                fi

                if AptRepoCheck "$nginx_repo_base" "$nginx_codename"
                then
                    DepInstall debian-archive-keyring
                    DepInstall gpg
                    curl -fsSL https://nginx.org/keys/nginx_signing.key | gpg --batch --yes --dearmor -o /usr/share/keyrings/nginx-archive-keyring.gpg
                    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/nginx-archive-keyring.gpg] ${nginx_repo_base} \
                    ${nginx_codename} nginx" | sudo tee /etc/apt/sources.list.d/nginx.list
                    echo -e "Package: *\nPin: origin nginx.org\nPin: release o=nginx\nPin-Priority: 900\n" | sudo tee /etc/apt/preferences.d/99nginx
                    AptUpdate force
                else
                    local nginx_codename_display="${nginx_codename:-unknown}"
                    Println "$(eval_gettext "\$tip Nginx 官方源暂不支持当前系统 (\$nginx_codename_display), 改用系统默认源安装")"
                fi
            fi

            AptInstall nginx
        ;;
        rpm)
            if [ "${VERSION_ID%%.*}" -eq 7 ]
            then
                Println "$(eval_gettext "\$tip 官方说明: Packages for RHEL 7 and SLES 12 are built without HTTP/3 support because OpenSSL used by those doesn't support TLSv1.3.")"
            fi

            DepInstall yum-utils

            if [ ! -f /etc/yum.repos.d/nginx.repo ]
            then
                if grep -q Amazon < /etc/os-release
                then
                    if [ "$VERSION" == "2" ]
                    then
cat > /etc/yum.repos.d/nginx.repo <<EOF
[nginx-stable]
name=nginx stable repo
baseurl=http://nginx.org/packages/amzn2/\$releasever/\$basearch/
gpgcheck=1
enabled=1
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
priority=9

[nginx-mainline]
name=nginx mainline repo
baseurl=http://nginx.org/packages/mainline/amzn2/\$releasever/\$basearch/
gpgcheck=1
enabled=0
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
priority=9
EOF
                    elif [ "$VERSION" == "2023" ]
                    then
cat > /etc/yum.repos.d/nginx.repo <<EOF
[nginx-stable]
name=nginx stable repo
baseurl=http://nginx.org/packages/amzn/2023/\$basearch/
gpgcheck=1
enabled=1
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
priority=9

[nginx-mainline]
name=nginx mainline repo
baseurl=http://nginx.org/packages/mainline/amzn/2023/\$basearch/
gpgcheck=1
enabled=0
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
priority=9
EOF
                    else
                        Println "$(eval_gettext "\$error 不支持的系统")\n"
                        return 1
                    fi
                else
cat > /etc/yum.repos.d/nginx.repo <<EOF
[nginx-stable]
name=nginx stable repo
baseurl=http://nginx.org/packages/centos/\$releasever/\$basearch/
gpgcheck=1
enabled=1
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true

[nginx-mainline]
name=nginx mainline repo
baseurl=http://nginx.org/packages/mainline/centos/\$releasever/\$basearch/
gpgcheck=1
enabled=0
gpgkey=https://nginx.org/keys/nginx_signing.key
module_hotfixes=true
EOF
                fi
            fi
            sudo yum-config-manager --disable nginx-stable
            sudo yum-config-manager --enable nginx-mainline
            sudo yum -y install nginx
        ;;
        alpine)
            sudo apk add openssl curl ca-certificates
            printf "%s%s%s%s\n" \
            "@nginx " \
            "http://nginx.org/packages/mainline/alpine/v" \
            `egrep -o '^[0-9]+\.[0-9]+' /etc/alpine-release` \
            "/main" \
            | sudo tee -a /etc/apk/repositories
            curl -o /tmp/nginx_signing.rsa.pub https://nginx.org/keys/nginx_signing.rsa.pub
            sudo mv /tmp/nginx_signing.rsa.pub /etc/apk/keys/
            sudo apk add nginx@nginx
        ;;
        sles)
            if [ "${VERSION_ID%%.*}" -eq 12 ]
            then
                Println "$(eval_gettext "\$tip 官方说明: Packages for RHEL 7 and SLES 12 are built without HTTP/3 support because OpenSSL used by those doesn't support TLSv1.3.")"
            fi
            sudo zypper install curl ca-certificates gpg2
            sudo zypper addrepo --gpgcheck --type yum --refresh --check 'http://nginx.org/packages/mainline/sles/$releasever_major' nginx-mainline
            curl -o /tmp/nginx_signing.key https://nginx.org/keys/nginx_signing.key
            sudo rpmkeys --import /tmp/nginx_signing.key
            sudo zypper install nginx
        ;;
        *)
            Println "$(eval_gettext "\$error 不支持的系统")\n"
            return 1
        ;;
    esac

    if [ ! -d "$nginx_prefix" ]
    then
        mkdir -p "$nginx_prefix"/sbin
        mv /usr/sbin/nginx* "$nginx_prefix"/sbin/
        ln -sfn /etc/nginx "$nginx_prefix"/conf
        ln -sfn /var/log/nginx "$nginx_prefix"/logs
        ln -sfn /usr/share/nginx/html "$nginx_prefix"/html
        ln -sf /var/run/nginx.pid "$nginx_prefix"/logs/nginx.pid
        for file in "$nginx_prefix"/sbin/*
        do
            if [[ -x "$AIOS_PREFIX"/bin/${file##*/} ]]
            then
                continue
            fi
cat > "$AIOS_PREFIX"/bin/${file##*/} <<EOF
#!/bin/sh
$file -p "$nginx_prefix" "\$@"
EOF
            chmod +x "$AIOS_PREFIX"/bin/*
        done
    fi

    if ! grep -q "$nginx_name:" < "/etc/passwd"
    then
        if grep -q '\--group ' < <(adduser --help)
        then
            adduser "$nginx_name" --system --group --no-create-home > /dev/null
        else
            adduser "$nginx_name" --system --no-create-home > /dev/null
        fi
        usermod -s /usr/sbin/nologin "$nginx_name"
    fi

    sed -i "s/#user  nobody;/user $nginx_name $nginx_name;/" "$nginx_prefix/conf/nginx.conf"
    sed -i "s/worker_connections  1024;/worker_connections  51200;/" "$nginx_prefix/conf/nginx.conf"
    sed -i '/conf.d/d' "$nginx_prefix/conf/nginx.conf"
    sed -i 's|/var/log/nginx|logs|g' "$nginx_prefix/conf/nginx.conf"
    sed -i 's|/var/run|logs|g' "$nginx_prefix/conf/nginx.conf"
    sed -i 's|/etc/nginx/||g' "$nginx_prefix/conf/nginx.conf"

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"
    mkdir -p "$nginx_prefix/html/localhost/"

    CrossplaneInstall

    Println "$(eval_gettext "\$info \$nginx_name 安装成功")\n"
}

NginxSourceInstall()
{
    local install="$i18n_update"

    if [ -z "${1:-}" ]
    then
        if [[ -x $(command -v $nginx_name) ]]
        then
            return 0
        fi
        install="$i18n_install"
    elif [[ ! -x $(command -v $nginx_name) ]]
    then
        install="$i18n_install"
    fi

    DepsCheck

    echo
    pcre_options=( pcre pcre2 )
    inquirer list_input_index "$(gettext "选择 pcre 版本")" pcre_options pcre_options_index

    Println "$(eval_gettext "\$tip 如果选择 openssl, \$nginx_name 将不支持 ssl_early_data (0-RTT)")"
    openssl_options=( openssl@1.1 openssl@3 quictls )
    inquirer list_input_index "$(gettext "选择 openssl 版本")" openssl_options openssl_options_index

    if [ "$dist" == "mac" ] && [ ! -d "$nginx_prefix" ]
    then
        Println "$(eval_gettext "\$info 建立目录 \$nginx_prefix, 可能需要输入密码")\n"
        sudo mkdir "$nginx_prefix"
        sudo chown $USER "$nginx_prefix"
    fi

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    rm -rf nginx-http-flv-module-master
    curl -L "$FFMPEG_MIRROR_LINK/nginx-http-flv-module.zip" -o nginx-http-flv-module.zip
    Println "$(eval_gettext "\$info 解压 nginx-http-flv-module ...")"
    unzip nginx-http-flv-module.zip >/dev/null 2>&1

    #cd nginx-http-flv-module-master
    #curl -s -L "$FFMPEG_MIRROR_LINK/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch" -o Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch
    #patch -p1 < Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch
    #cd "$DEPENDS_ROOT"

    while IFS= read -r line
    do
        if [[ $line == *"/download/"* ]]
        then
            nginx_package_name=${line#*/download/}
            nginx_package_name=${nginx_package_name%%.tar.gz*}
            break
        fi
    done < <(curl -s -Lm 20 -H "User-Agent: $USER_AGENT_BROWSER" https://nginx.org/en/download.html 2> /dev/null)

    if [ ! -d "./$nginx_package_name" ]
    then
        curl -L "https://nginx.org/download/$nginx_package_name.tar.gz" -o "$nginx_package_name.tar.gz"
        Println "$(eval_gettext "\$info 解压 \$nginx_package_name ...")"
        tar xzf "$nginx_package_name.tar.gz"
    fi

    if [ "$dist" == "mac" ]
    then
        SourceInstallReady "${pcre_options[pcre_options_index]}" zlib

        cc_opt="-I$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/include -I$HOMEBREW_PREFIX/opt/zlib/include"
        ld_opt="-I$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/lib -L$HOMEBREW_PREFIX/opt/zlib/lib"

        if [ "$openssl_options_index" -eq 2 ]
        then
            QuictlsInstall
            cc_opt="$cc_opt -I$DEPENDS_ROOT/quictls/build/include"
            ld_opt="$ld_opt -L$DEPENDS_ROOT/quictls/build/lib"
        else
            DepInstall "${openssl_options[openssl_options_index]}"
            cc_opt="$cc_opt -I$HOMEBREW_PREFIX/opt/${openssl_options[openssl_options_index]}/include"
            ld_opt="$ld_opt -L$HOMEBREW_PREFIX/opt/${openssl_options[openssl_options_index]}/lib"
        fi

        cd "$DEPENDS_ROOT/$nginx_package_name/"

        ./configure \
        --with-cc-opt="$cc_opt" \
        --with-ld-opt="$ld_opt" \
        --add-module=../nginx-http-flv-module-master \
        --with-debug \
        --with-http_addition_module \
        --with-http_auth_request_module \
        --with-http_dav_module \
        --with-http_degradation_module \
        --with-http_gunzip_module \
        --with-http_gzip_static_module \
        --with-http_mp4_module \
        --with-http_random_index_module \
        --with-http_realip_module \
        --with-http_secure_link_module \
        --with-http_slice_module \
        --with-http_ssl_module \
        --with-http_stub_status_module \
        --with-http_sub_module \
        --with-http_v2_module \
        --with-http_v3_module \
        --with-http_flv_module \
        --with-mail \
        --with-mail_ssl_module \
        --with-pcre \
        --with-pcre-jit \
        --with-stream \
        --with-stream_realip_module \
        --with-stream_ssl_module \
        --with-stream_ssl_preread_module \
        --with-threads
    else
        if [ "$dist" == "rpm" ]
        then
            SourceInstallReady openssl-devel gcc
        else
            SourceInstallReady perl software-properties-common pkg-config libssl-dev libghc-zlib-dev libcurl4-gnutls-dev libexpat1-dev unzip gettext
        fi

        while IFS= read -r line
        do
            if [[ $line =~ \<A\ HREF=\"(.+)\.tar\.gz ]]
            then
                zlib_name=${BASH_REMATCH[1]}
                break
            fi
        done < <(curl -s -L -H "User-Agent: $USER_AGENT_BROWSER" https://www.zlib.net 2> /dev/null)

        if [ ! -d $zlib_name ]
        then
            curl -L https://www.zlib.net/$zlib_name.tar.gz -o $zlib_name.tar.gz
            Println "$(eval_gettext "\$info 解压 \$zlib_name ...")"
            tar xzf $zlib_name.tar.gz
        fi

        if [ "$pcre_options_index" -eq 0 ]
        then
            pcre_name="pcre-${PCRE_LEGACY_VER}"
            if [ ! -d $pcre_name ]
            then
                curl -L https://downloads.sourceforge.net/pcre/pcre/${pcre_name#*-}/$pcre_name.zip -o $pcre_name.zip
                Println "$(eval_gettext "\$info 解压 \$pcre_name ...")"
                unzip $pcre_name.zip >/dev/null 2>&1
            fi
        else
            pcre_name=$(curl -s -Lm 20 "$FFMPEG_MIRROR_LINK/pcre2.json" | $JQ_FILE -r '.tag_name')
            if [ ! -d $pcre_name ]
            then
                curl -L $FFMPEG_MIRROR_LINK/pcre2/$pcre_name/$pcre_name.zip -o $pcre_name.zip
                Println "$(eval_gettext "\$info 解压 \$pcre_name ...")"
                unzip $pcre_name.zip >/dev/null 2>&1
            fi
        fi

        if [ "$openssl_options_index" -eq 2 ]
        then
            openssl_name="openssl-${QUICTLS_TAG}"
            local openssl_short_name="${openssl_name#*-}"
            Println "$(eval_gettext "\$info 下载 \$openssl_short_name ...")"
            if ! curl -Lm 30 "${QUICTLS_REPO_LINK}/${openssl_name#*-}.tar.gz" -o "$openssl_name".tar.gz
            then
                curl -L "$FFMPEG_MIRROR_LINK/${openssl_name#*-}".tar.gz -o "$openssl_name".tar.gz
            fi
            Println "$(eval_gettext "\$info 解压 \$openssl_short_name ...")"
            tar xzf "$openssl_name".tar.gz
        else
            local openssl_pack_url=""
            if [ "$openssl_options_index" -eq 0 ]
            then
                openssl_url="${OPENSSL_SOURCE_LINK}/old/1.1.1"
                openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "1")
            else
                openssl_url="$OPENSSL_SOURCE_LINK"
                openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "3")
            fi

            if [ -z "$openssl_pack_url" ]
            then
                Println "$(eval_gettext "\$error 无法从 \$openssl_url 获取 OpenSSL 源码包地址")\n"
                return 1
            fi

            openssl_pack="${openssl_pack_url##*/}"
            openssl_name="${openssl_pack%.tar*}"

            if [ ! -d "./$openssl_name" ]
            then
                curl -L "$openssl_pack_url" -o "$openssl_pack"
                Println "$(eval_gettext "\$info 解压 \$openssl_name ...")"
                tar xzf "$openssl_pack"
            fi
        fi

        cd "$nginx_package_name/"

        ./configure \
        --add-module=../nginx-http-flv-module-master \
        --with-debug \
        --with-http_addition_module \
        --with-http_auth_request_module \
        --with-http_dav_module \
        --with-http_degradation_module \
        --with-http_gunzip_module \
        --with-http_gzip_static_module \
        --with-http_mp4_module \
        --with-http_random_index_module \
        --with-http_realip_module \
        --with-http_secure_link_module \
        --with-http_slice_module \
        --with-http_ssl_module \
        --with-http_stub_status_module \
        --with-http_sub_module \
        --with-http_v2_module \
        --with-http_v3_module \
        --with-http_flv_module \
        --with-mail \
        --with-mail_ssl_module \
        --with-pcre=../$pcre_name \
        --with-pcre-jit \
        --with-zlib=../$zlib_name \
        --with-stream \
        --with-stream_realip_module \
        --with-stream_ssl_module \
        --with-stream_ssl_preread_module \
        --with-openssl=../$openssl_name \
        --with-threads
    fi

    nproc="-j$(nproc 2> /dev/null)" || nproc="-j1"

    make $nproc
    make install

    ln -sf "$nginx_prefix"/sbin/nginx "$AIOS_PREFIX"/bin/

    if [ "$dist" != "mac" ]
    then
        if ! grep -q "$nginx_name:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser "$nginx_name" --system --group --no-create-home > /dev/null
            else
                adduser "$nginx_name" --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin "$nginx_name"
        fi

        sed -i "s/#user  nobody;/user $nginx_name $nginx_name;/" "$nginx_prefix/conf/nginx.conf"
    fi

    sed -i "s/worker_processes .*/worker_processes  ${nproc:2};/" "$nginx_prefix/conf/nginx.conf"
    sed -i "s/worker_connections  1024;/worker_connections  51200;/" "$nginx_prefix/conf/nginx.conf"

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"
    mkdir -p "$nginx_prefix/html/localhost/"

    CrossplaneInstall

    Println "$(eval_gettext "\$info \$nginx_name \${install}成功")\n"
}

NginxInstall()
{
    if [ -d "$nginx_prefix" ]
    then
        Println "$(eval_gettext "\$error \$nginx_name 已经存在 \$nginx_prefix !")\n"
        return 1
    elif [[ -x $(command -v $nginx_name) ]]
    then
        local nginx_cmd_path="$(command -v $nginx_name)"
        Println "$(eval_gettext "\$error \$nginx_name 已经存在 \$nginx_cmd_path, 请先卸载!")\n"
        return 1
    fi

    if [ "$dist" != "mac" ]
    then
        Println "$(eval_gettext "\$tip 选择快速安装将缺少 nginx-http-flv-module 以及 quictls 选择")"
        nginx_install_options=( "$(eval_gettext "\${nginx_name}官方包 (快速安装)")" "$(gettext "编译安装")" )
        inquirer list_input_index "$(gettext "选择安装方式")" nginx_install_options nginx_install_options_index

        if [ "$nginx_install_options_index" -eq 0 ]
        then
            NginxPackageInstall
            return
        fi
    fi

    NginxSourceInstall
}

NginxUninstall()
{
    if [ ! -d "$nginx_prefix" ]
    then
        Println "$(eval_gettext "\$error \$nginx_name 未安装 !")\n"
        return 1
    fi

    echo
    ExitOnList n "`eval_gettext \"确定删除 \\\$nginx_name 包括所有配置文件, 操作不可恢复\"`"

    ServiceControl disable $nginx_name

    DepInstall file

    if file -h "$nginx_prefix/conf" | grep -q 'symbolic link'
    then
        if [ "$dist" == "yum" ]
        then
            yum -y remove "$nginx_name" || true
        else
            apt-get -y --purge remove "$nginx_name"* || true
        fi
        rm -f "$AIOS_PREFIX"/bin/"$nginx_name"*
    elif [ "$dist" == "mac" ]
    then
        brew uninstall "$nginx_name"
        Println "$(eval_gettext "\$info 可能需要输入密码删除目录 \$nginx_prefix")\n"
    fi

    sudo rm -rf "$nginx_prefix"

    Println "$(eval_gettext "\$info \$nginx_name 卸载完成")\n"
}

NginxUpdate()
{
    ShFileUpdate "$nginx_name"

    if [ ! -d "$nginx_prefix" ]
    then
        Println "$(eval_gettext "\$error \$nginx_name 未安装 !")\n"
        return 1
    fi

    DepInstall file

    if ! file -h "$nginx_prefix/conf" | grep -q 'symbolic link'
    then
        NginxSourceInstall update
        return
    fi

    if [ "$dist" == "rpm" ]
    then
        yum update -y "$nginx_name"
    else
        apt-get -y install --only-upgrade "$nginx_name"
    fi
}
CrossplaneInstall()
{
    if [[ -x $(command -v crossplane) ]] 
    then
        return 0
    fi

    Println "$(eval_gettext "\$info 安装 crossplane ...")"

    PythonInstall
    pip3 install crossplane
}
PostfixInstall()
{
    if [ "$dist" == "rpm" ] 
    then
        yum -y install postfix > /dev/null
    else
        AptInstall postfix
    fi
}
TesseractInstall()
{
    if [[ -x $(command -v tesseract) ]] 
    then
        Println "$(eval_gettext "\$error tesseract 已存在!")\n"
        return 0
    fi

    DepsCheck

    if [ "$dist" == "ubu" ] 
    then
        add-apt-repository ppa:alex-p/tesseract-ocr -y
        apt-get -y update
        AptInstall tesseract
    elif [ "$dist" == "deb" ] 
    then
        Println "$(eval_gettext "\$info 参考 https://notesalexp.org/tesseract-ocr/ ...")\n"
    else
        Println "$(eval_gettext "\$info 参考 https://tesseract-ocr.github.io/tessdoc/Home.html ...")\n"
    fi
}
DNSCryptConfig()
{
    if [ "$location_china" == "$i18n_yes" ] 
    then
        echo "$(awk '!x{x=sub(/.*\[static\..*/,"  [static.\047alidns-doh-fix\047]")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
        echo "$(awk '!x{x=sub(/.* stamp = .*/,"  stamp = \047sdns://AgAAAAAAAAAAACCY49XlNq8pWM0vfxT3BO9KJ20l4zzWXy5l9eTycnwTMA5kbnMuYWxpZG5zLmNvbQovZG5zLXF1ZXJ5\047")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
        echo "$(awk '!x{x=sub(/.*server_names = \[.*/,"server_names = [\047dnspod-doh\047,\047alidns-doh-fix\047]")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
        echo "$(awk '!x{x=sub(/.*bootstrap_resolvers = .*/,"bootstrap_resolvers = [\047119.29.29.29:53\047, \047180.76.76.76:53\047, \0471.1.1.1:53\047, \047114.114.114.114:53\047, \0478.8.8.8:53\047]")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
        echo "$(awk '!x{x=sub(/.*netprobe_address = .*/,"netprobe_address = \0471.1.1.1:53\047")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
    else
        echo "$(awk '!x{x=sub(/.*server_names = \[.*/,"server_names = [\047google\047, \047cloudflare\047]")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
    fi

    echo "$(awk '!x{x=sub(/^listen_addresses = .*/,"listen_addresses = [\047[::]:'"${listen_port:-53}"'\047]")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
    echo "$(awk '!x{x=sub(/.*block_ipv6 = .*/,"block_ipv6 = '"${block_ipv6:-false}"'")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
    echo "$(awk '!x{x=sub(/.*require_dnssec = .*/,"require_dnssec = '"${require_dnssec:-true}"'")}1' dnscrypt-proxy.toml)" > dnscrypt-proxy.toml
}

IperfInstall()
{
    local install="$i18n_update"

    if [ -z "${1:-}" ] 
    then
        if [[ -x $(command -v iperf3) ]] 
        then
            return 0
        fi
        install="$i18n_install"
    elif [[ ! -x $(command -v iperf3) ]] 
    then
        install="$i18n_install"
    fi

    if [ "$dist" == "mac" ] 
    then
        brew install iperf3
        Println "$(eval_gettext "\$info iperf3 \${install}成功")\n"
        return 0
    fi

    Println "$info $install iperf3 ..."

    ArchCheck

    case $arch in
        i386) iperf_arch="x86"
        ;;
        x86_64) iperf_arch="x64"
        ;;
        arm64) iperf_arch="aarch64"
        ;;
        *) iperf_arch="arm"
        ;;
    esac

    if ! curl -s -L -o "$IPERF3_FILE" https://raw.githubusercontent.com/masonr/yet-another-bench-script/master/bin/iperf/iperf3_${iperf_arch} && ! curl -s -L -o "$IPERF3_FILE" "$FFMPEG_MIRROR_LINK"/iperf/iperf3_${iperf_arch}
    then
        Println "$(eval_gettext "\$error iperf3 \${install}失败")\n"
        return 1
    fi

    chmod +x "$IPERF3_FILE"

    Println "$(eval_gettext "\$info iperf3 \${install}成功")\n"
}

IperfView()
{
    IperfInstall
    ServiceGet iperf

    if [ "$iperf_count" -eq 0 ] 
    then
        [ -n "${1:-}" ] && return 0
        Println "$(eval_gettext "\$error 请先添加服务")\n"
        return 1
    fi

    local iperf_server_list="" iperf_client_list=""
    iperf_server_options=()
    iperf_server_indices=()
    iperf_client_options=()
    iperf_client_indices=()
    iperf_servers_name=()
    iperf_servers_args=()
    iperf_clients_name=()
    iperf_clients_target=()
    iperf_clients_args=()

    local i i18n_args i18n_target
    i18n_args=$(gettext "参数")
    i18n_target=$(gettext "目标")
    for((i=0;i<iperf_count;i++));
    do
        if [ "${iperf_types[i]}" == "server" ] 
        then
            iperf_servers_name+=("${iperf_names[i]}")
            iperf_servers_args+=("${iperf_args[i]}")
            iperf_server_options+=("${i18n_name}: ${iperf_names[i]:-$i18n_none}, ${i18n_args}: ${iperf_args[i]}")
            iperf_server_list="${iperf_server_list}${green}${#iperf_servers_name[@]}.${normal} ${i18n_name}: ${iperf_names[i]:-$i18n_none}, ${i18n_args}: ${iperf_args[i]:-$i18n_none}\n"
            iperf_server_indices+=("$i")
        else
            iperf_clients_name+=("${iperf_names[i]}")
            iperf_clients_target+=("${iperf_targets[i]}")
            iperf_clients_args+=("${iperf_args[i]}")
            iperf_client_options+=("${i18n_name}: ${iperf_names[i]:-$i18n_none}, ${i18n_target}: ${iperf_targets[i]}, ${i18n_args}: ${iperf_args[i]}")
            iperf_client_list="${iperf_client_list}${green}${#iperf_clients_name[@]}.${normal} ${i18n_name}: ${iperf_names[i]:-$i18n_none}, ${i18n_target}: ${iperf_targets[i]:-$i18n_none}, ${i18n_args}: ${iperf_args[i]:-$i18n_none}\n"
            iperf_client_indices+=("$i")
        fi
    done

    iperf_servers_count=${#iperf_servers_name[@]}
    iperf_clients_count=${#iperf_clients_name[@]}

    if [ -n "${iperf_server_list:-}" ] 
    then
        Println "$(gettext "服务端列表"):\n${iperf_server_list}\n"
    fi

    if [ -n "${iperf_client_list:-}" ] 
    then
        Println "$(gettext "客户端列表"):\n${iperf_client_list}\n"
    fi
}

IperfAdd()
{
    IperfView true
    iperf_type_options=( "$(gettext "服务端")" "$(gettext "客户端")" )
    echo
    inquirer list_input_index "$(gettext "请选择添加类型")" iperf_type_options iperf_type_index

    echo
    inquirer text_input "$(gettext "输入服务名称")" iperf_name "$i18n_blank"

    if [ "$iperf_type_index" -eq 1 ] 
    then
        iperf_target_options=( "$(gettext "输入目标地址")" )

        if iperf_target_hosts=($(grep "^Host " ~/.ssh/config | grep -v "Host \*" | awk '{print $2}'))
        then
            iperf_target_options+=("${iperf_target_hosts[@]}")
        fi

        echo
        inquirer list_input_index "$i18n_please_select" iperf_target_options iperf_target_index 20

        if [ "$iperf_target_index" -eq 0 ] 
        then
            echo
            ExitOnText "$(gettext "输入目标地址")" iperf_target
        else
            iperf_target="${iperf_target_options[iperf_target_index]}"
        fi

        iperf_type="client"
    else
        iperf_type="server"
        iperf_target=""
    fi

    echo
    inquirer text_input "$(gettext "输入 iperf3 参数")" iperf_args "$i18n_blank"

    iperf_service=$(
        $JQ_FILE -n \
            --arg type "$iperf_type" \
            --arg name "$iperf_name" \
            --arg target "$iperf_target" \
            --arg args "$iperf_args" \
            '{type:$type,name:$name,target:$target,args:$args}'
    )

    jq_path='["iperf"]'
    JQ add "$SERVICES_CONFIG" "[$iperf_service]"

    Println "$(eval_gettext "\$info 添加成功")\n"
}

IperfEdit()
{
    IperfView
    iperf_edit_options=( "$(gettext "服务端")" "$(gettext "客户端")" )
    echo
    inquirer list_input_index "$i18n_please_select" iperf_edit_options iperf_edit_options_index

    local i18n_target
    i18n_target=$(gettext "目标")

    if [ "$iperf_edit_options_index" -eq 0 ] 
    then
        if [ "$iperf_servers_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加服务端")\n"
            return 1
        fi
        iperf_options=("${iperf_server_options[@]}")
        iperf_indices=("${iperf_server_indices[@]}")
        iperf_edit_options=( "$i18n_name" "$(gettext "参数")" )
    else
        if [ "$iperf_clients_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加客户端")\n"
            return 1
        fi
        iperf_options=("${iperf_client_options[@]}")
        iperf_indices=("${iperf_client_indices[@]}")
        iperf_edit_options=( "$i18n_name" "$i18n_target" "$(gettext "参数")" )
    fi

    echo
    inquirer list_input_index "$i18n_please_select" iperf_options iperf_options_index

    echo
    inquirer checkbox_input_indices "$i18n_select_edit" iperf_edit_options iperf_edit_options_indices

    for iperf_edit_options_index in "${iperf_edit_options_indices[@]}"
    do
        case "${iperf_edit_options[iperf_edit_options_index]}" in
            "$i18n_name") 
                echo
                inquirer text_input "$(gettext "输入服务名称")" iperf_name "${iperf_name[iperf_indices[iperf_options_index]]:-$i18n_blank}"

                jq_path='["iperf",'"${iperf_indices[iperf_options_index]}"',"name"]'
                JQ update "$SERVICES_CONFIG" "$iperf_name"
            ;;
            "$i18n_target") 
                iperf_target_options=( "$(gettext "输入目标地址")" )

                if iperf_target_hosts=($(grep "^Host " ~/.ssh/config | grep -v "Host \*" | awk '{print $2}'))
                then
                    iperf_target_options+=("${iperf_target_hosts[@]}")
                fi

                echo
                inquirer list_input_index "$i18n_please_select" iperf_target_options iperf_target_index 20

                if [ "$iperf_target_index" -eq 0 ] 
                then
                    echo
                    inquirer text_input "$(gettext "输入目标地址")" iperf_target "${iperf_target[iperf_indices[iperf_options_index]]:-$i18n_blank}"
                else
                    iperf_target="${iperf_target_options[iperf_target_index]}"
                fi
                jq_path='["iperf",'"${iperf_indices[iperf_options_index]}"',"target"]'
                JQ update "$SERVICES_CONFIG" "$iperf_target"
            ;;
            *) 
                echo
                inquirer text_input "$(gettext "输入 iperf3 参数")" iperf_args "${iperf_args[iperf_indices[iperf_options_index]]:-$i18n_blank}"

                jq_path='["iperf",'"${iperf_indices[iperf_options_index]}"',"args"]'
                JQ update "$SERVICES_CONFIG" "$iperf_args"
            ;;
        esac
        local edit_opt_name="${iperf_edit_options[iperf_edit_options_index]}"
        Println "$(eval_gettext "\$info \$edit_opt_name 修改成功")\n"
    done

    return 0
}

IperfDel()
{
    IperfView
    iperf_del_options=( "$(gettext "服务端")" "$(gettext "客户端")" )
    echo
    inquirer list_input_index "$i18n_please_select" iperf_del_options iperf_del_options_index

    if [ "$iperf_del_options_index" -eq 0 ] 
    then
        if [ "$iperf_servers_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加服务端")\n"
            return 1
        fi
        iperf_options=("${iperf_server_options[@]}")
        iperf_indices=("${iperf_server_indices[@]}")
    else
        if [ "$iperf_clients_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加客户端")\n"
            return 1
        fi
        iperf_options=("${iperf_client_options[@]}")
        iperf_indices=("${iperf_client_indices[@]}")
    fi

    echo
    inquirer checkbox_input_indices "$(gettext "请选择删除")" iperf_options iperf_del_indices

    for iperf_del_index in "${iperf_del_indices[@]}"
    do
        jq_path='["iperf",'"${iperf_indices[iperf_del_index]}"']'
        JQ delete "$SERVICES_CONFIG"
    done

    Println "$(eval_gettext "\$info 删除成功")\n"
}

IperfStart()
{
    IperfView
    iperf_start_options=( "$(gettext "服务端")" "$(gettext "客户端")" )
    echo
    inquirer list_input_index "$i18n_please_select" iperf_start_options iperf_start_options_index

    if [ "$iperf_start_options_index" -eq 0 ] 
    then
        if [ "$iperf_servers_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加服务端")\n"
            return 1
        fi
        iperf_options=("${iperf_server_options[@]}")
        iperf_indices=("${iperf_server_indices[@]}")
    else
        if [ "$iperf_clients_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加客户端")\n"
            return 1
        fi
        iperf_options=("${iperf_client_options[@]}")
        iperf_indices=("${iperf_client_indices[@]}")
    fi

    echo
    inquirer checkbox_input_indices "$(gettext "请选择启动")" iperf_options iperf_start_indices

    for iperf_start_index in "${iperf_start_indices[@]}"
    do
        iperf_commands=()
        if [ "$iperf_start_options_index" -eq 0 ] 
        then
            iperf_commands+=("-s")
        else
            iperf_target="${iperf_targets[iperf_indices[iperf_start_index]]}"
            if [ -z "$iperf_target" ] 
            then
                local start_opt_name="${iperf_options[iperf_start_index]}"
                Println "$(eval_gettext "\$error 请先设置客户端 \$start_opt_name 目标地址")\n"
                continue
            fi
            iperf_target_host=$(awk -v host="$iperf_target" '$1 == "Host" && $2 == host {flag=1} flag && $1 == "Hostname" {print $2; exit}' ~/.ssh/config)
            if [ -n "${iperf_target_host}" ] 
            then
                iperf_target="$iperf_target_host"
            fi
            iperf_commands+=( -c "$iperf_target")
        fi
        iperf_commands+=(${iperf_args[iperf_indices[iperf_start_index]]})
        "$IPERF3_FILE" "${iperf_commands[@]}"
    done

    Println "$(eval_gettext "\$info 启动成功")\n"
}

IperfMenu()
{
    iperf_options=( "$(gettext "浏览")" "$(gettext "启动")" "$i18n_add" "$i18n_edit" "$i18n_delete" "$(gettext "安装/更新 iperf3")" )
    echo
    inquirer list_input_index "$i18n_please_select" iperf_options iperf_options_index

    case $iperf_options_index in
        0) IperfView
        ;;
        1) IperfStart
        ;;
        2) IperfAdd
        ;;
        3) IperfEdit
        ;;
        4) IperfDel
        ;;
        5) IperfInstall 1
        ;;
    esac

    return 0
}
QuictlsInstall()
{
    local build_dir=build args=() quictls_path="$DEPENDS_ROOT"/quictls

    if [ -z "${1:-}" ] 
    then
        quictls_install_options=()
    else
        quictls_install_options=("$@")
    fi

    if EleInArray static quictls_install_options
    then
        build_dir+=-static
        quictls_path+=-static
    fi

    if [ -d "$DEPENDS_ROOT/openssl-${QUICTLS_TAG}/$build_dir" ] 
    then
        ln -sfn "$DEPENDS_ROOT/openssl-${QUICTLS_TAG}/$build_dir" "$quictls_path"
        return 0
    fi

    DepInstall ca-certificates
    DepInstall perl

    unset OPENSSL_LOCAL_CONFIG_DIR

    args=(
        --prefix="$DEPENDS_ROOT/openssl-${QUICTLS_TAG}/$build_dir"
        --openssldir="$DEPENDS_ROOT/openssl-${QUICTLS_TAG}/$build_dir/etc"
        --libdir=lib
    )

    if EleInArray static quictls_install_options
    then
        args+=(no-shared)
    fi

    ArchCheck

    if [ "$dist" == "mac" ] 
    then
        export PERL="$HOMEBREW_PREFIX"/opt/perl/bin/perl
        args+=( darwin64-${arch}-cc )
        SourceInstallReady
    else
        case $arch in
            x86_64) args+=( linux-x86_64 )
            ;;
            i386) args+=( linux-elf )
            ;;
            arm64) args+=( linux-aarch64 )
            ;;
            arm*) args+=( linux-armv4 )
            ;;
            *) Println "$(eval_gettext "\$error 不支持的架构 \$arch")\n"; return 1
        esac

        if [ "$dist" == "rpm" ] 
        then
            SourceInstallReady glibc-devel openssl-devel systemd-devel zlib-devel
        else
            SourceInstallReady gcc libc6-dev libssl-dev libsystemd-dev make zlib1g-dev
        fi
    fi

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    if ! curl -Lm 30 "${QUICTLS_REPO_LINK}/${QUICTLS_TAG}.tar.gz" -o "${QUICTLS_TAG}.tar.gz"
    then
        curl -L "$FFMPEG_MIRROR_LINK/${QUICTLS_TAG}.tar.gz" -o "${QUICTLS_TAG}.tar.gz"
    fi

    Println "$(eval_gettext "\$info 解压 \${QUICTLS_TAG} ...")"
    tar xzf "${QUICTLS_TAG}.tar.gz"
    cd "openssl-${QUICTLS_TAG}"

    perl ./Configure "${args[@]}"
    make
    make install

    ln -s "$DEPENDS_ROOT/openssl-${QUICTLS_TAG}/$build_dir" "$quictls_path"
}
NginxViewStatus()
{
    if [ ! -d "$nginx_prefix" ] 
    then
        Println "$(eval_gettext "\$error \$nginx_name 未安装 !")\n"
    else
        systemctl --no-pager -l status $nginx_name
    fi
}
NginxToggle()
{
    echo
    if [[ $(systemctl is-active $nginx_name) == "active" ]] 
    then
        ExitOnList y "`eval_gettext \"\\\$nginx_name 正在运行, 是否关闭\"`"

        if [[ $(echo $SSH_CONNECTION | cut -d' ' -f3) == "127.0.0.1" ]] 
        then
            Println "$(eval_gettext "\$error 请使用非 \$nginx_name 监听端口连接 ssh 后重试")\n"
            exit 1
        fi
        systemctl stop $nginx_name
        Println "$(eval_gettext "\$info \$nginx_name 已关闭")\n"
    else
        ExitOnList y "`eval_gettext \"\\\$nginx_name 未运行, 是否开启\"`"

        systemctl start $nginx_name
        Println "$(eval_gettext "\$info \$nginx_name 已开启")\n"
    fi
}
NginxRestart()
{
    if ! $NGINX_FILE -t
    then
        Println "$(eval_gettext "\$error 请检查配置错误")\n"
        exit 1
    fi
    echo
    nginx_actions=( "$(gettext "重载配置")" "$(gettext "强制重启")" )
    inquirer list_input_index "$i18n_select_action" nginx_actions nginx_actions_index
    if [ "$nginx_actions_index" -eq 0 ] 
    then
        nginx_action=reload-or-restart
    else
        nginx_action=restart
    fi
    if systemctl $nginx_action $nginx_name 
    then
        Println "$(eval_gettext "\$info \$nginx_name 重启成功")\n"
    else
        Println "$(eval_gettext "\$error \$nginx_name 重启失败, 请检查配置")\n"
    fi
}
NginxListDomains()
{
    if [ ! -d "$nginx_prefix" ] 
    then
        Println "$(eval_gettext "\$error \$nginx_name 未安装 ! 输入 \$nginx_ctl 安装 \$nginx_name")\n"
        exit 1
    fi

    OpensslInstall

    nginx_domains_list=""
    nginx_domains_count=0
    nginx_domains=()
    nginx_domains_status=()

    if ls -A "$nginx_prefix/conf/sites_available/"* > /dev/null 2>&1
    then
        for f in "$nginx_prefix/conf/sites_available/"*
        do
            nginx_domains_count=$((nginx_domains_count+1))
            domain=${f##*/}
            domain=${domain%.conf}
            if [ -f "$nginx_prefix/conf/sites_enabled/$domain.conf" ] 
            then
                domain_status=1
                domain_status_text="${green} [$i18n_enabled] ${normal}"
            else
                domain_status=0
                domain_status_text="${red} [$i18n_disabled] ${normal}"
            fi
            if [ -f "$nginx_prefix/conf/sites_crt/$domain.crt" ] 
            then
                domain_expire_date=$(date +%c --date="$(openssl x509 -enddate -noout -in $nginx_prefix/conf/sites_crt/$domain.crt | cut -d= -f 2)")
                if openssl x509 -checkend 1209600 -noout -in "$nginx_prefix/conf/sites_crt/$domain.crt" > /dev/null
                then
                    domain_expire_text=" ${green}[$domain_expire_date]${normal}"
                elif openssl x509 -checkend 0 -noout -in "$nginx_prefix/conf/sites_crt/$domain.crt" > /dev/null
                then
                    domain_expire_text=" ${yellow}[$domain_expire_date]${normal}"
                else
                    domain_expire_text=" ${red}[$domain_expire_date]${normal}"
                fi
            else
                domain_expire_text=""
            fi
            nginx_domains_list="$nginx_domains_list ${green}$nginx_domains_count.${normal}${indent_6}$domain $domain_status_text$domain_expire_text\n\n"
            nginx_domains+=("$domain")
            nginx_domains_status+=("$domain_status")
        done
    fi

    if [ "$nginx_domains_count" -gt 0 ] 
    then
        Println "${green}$(gettext "域名列表:")${normal}\n\n$nginx_domains_list"
    fi
}
NginxSelectDomain()
{
    echo "$(gettext "选择域名")"
    while read -p "$i18n_default_cancel" nginx_domains_index
    do
        case "$nginx_domains_index" in
            "")
                Println "$i18n_canceled...\n"
                exit 1
            ;;
            *[!0-9]*)
                Println "$error $i18n_input_correct_no\n"
            ;;
            *)
                if [ "$nginx_domains_index" -gt 0 ] && [ "$nginx_domains_index" -le "$nginx_domains_count" ]
                then
                    nginx_domains_index=$((nginx_domains_index-1))
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done
}
NginxListDomain()
{
    level_1_add_indices=( 0 )

    NginxListDomains

    if [ "$nginx_domains_count" -eq 0 ]
    then
        Println "$(eval_gettext "\$error 没有域名")\n"
        exit 1
    fi

    NginxSelectDomain
    NginxParseConfig ${nginx_domains[nginx_domains_index]}
    NginxGetConfig

    if [ "$level_3_d1_count" -eq 0 ]
    then
        local current_domain="${nginx_domains[nginx_domains_index]}"
        Println "$(eval_gettext "\$error 请先添加 \$current_domain 配置")\n"
        exit 1
    fi

    nginx_domain_servers_list=""
    nginx_domain_servers_count=0
    nginx_domain_servers_indices=()
    nginx_domain_servers_name=()
    nginx_domain_servers_root=()

    level_1_index=0

    level_2_directive_d1=${level_2_directive_arr[level_1_index]}
    level_3_directive_d1=${level_3_directive_arr[level_1_index]}
    level_3_args_d1=${level_3_args_arr[level_1_index]}

    IFS="${delimiters[4]}" read -r -a level_2_directive_d1_arr <<< "$level_2_directive_d1"
    IFS="${delimiters[5]}" read -r -a level_3_directive_d1_arr <<< "$level_3_directive_d1"
    IFS="${delimiters[5]}" read -r -a level_3_args_d1_arr <<< "$level_3_args_d1"

    if [ "$level_4_d1_count" -gt 0 ]
    then
        level_4_directive_d1=${level_4_directive_arr[level_1_index]}
        level_4_args_d1=${level_4_args_arr[level_1_index]}
        IFS="${delimiters[6]}" read -r -a level_4_directive_d1_arr <<< "$level_4_directive_d1"
        IFS="${delimiters[6]}" read -r -a level_4_args_d1_arr <<< "$level_4_args_d1"
    fi

    for((level_2_index=0;level_2_index<${#level_2_directive_d1_arr[@]};level_2_index++));
    do
        if [ "${level_2_directive_d1_arr[level_2_index]}" == "server" ]
        then
            level_3_directive_d2=${level_3_directive_d1_arr[level_2_index]}
            level_3_args_d2=${level_3_args_d1_arr[level_2_index]}

            IFS="${delimiters[6]}" read -r -a level_3_directive_d2_arr <<< "$level_3_directive_d2"
            IFS="${delimiters[6]}" read -r -a level_3_args_d2_arr <<< "$level_3_args_d2"

            if [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_d1_arr[level_2_index]}" ]
            then
                level_4_directive_d2=${level_4_directive_d1_arr[level_2_index]}
                level_4_args_d2=${level_4_args_d1_arr[level_2_index]}
                IFS="${delimiters[7]}" read -r -a level_4_directive_d2_arr <<< "$level_4_directive_d2"
                IFS="${delimiters[7]}" read -r -a level_4_args_d2_arr <<< "$level_4_args_d2"
            fi

            nginx_domain_servers_count=$((nginx_domain_servers_count+1))
            nginx_domain_servers_indices+=("$level_2_index")
            nginx_domain_server_listen_list=""
            nginx_domain_server_name_list=""
            nginx_domain_server_flv_status="${red}$(gettext "未配置")${normal}"
            nginx_domain_server_nodejs_status="${red}$(gettext "未配置")${normal}"
            skip_find_nodejs=0
            server_root=""

            for((level_3_index=0;level_3_index<${#level_3_directive_d2_arr[@]};level_3_index++));
            do
                level_3_directive=${level_3_directive_d2_arr[level_3_index]}
                level_3_args=${level_3_args_d2_arr[level_3_index]}

                if [ "$level_3_directive" == "listen" ]
                then
                    [ -n "$nginx_domain_server_listen_list" ] && nginx_domain_server_listen_list="$nginx_domain_server_listen_list, "
                    nginx_domain_server_listen_list="$nginx_domain_server_listen_list${level_3_args//${delimiters[7]}/ }"
                elif [ "$level_3_directive" == "server_name" ]
                then
                    [ -n "$nginx_domain_server_name_list" ] && nginx_domain_server_name_list="$nginx_domain_server_name_list, "
                    nginx_domain_server_name_list="$nginx_domain_server_name_list${level_3_args//${delimiters[7]}/, }"
                elif [ "$level_3_directive" == "location" ]
                then
                    if [ "${level_3_args}" == "/flv" ]
                    then
                        nginx_domain_server_flv_status="${green}$(gettext "已配置")${normal}"
                    elif [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_d1_arr[level_2_index]}" ] && [ -n "${level_4_directive_d2_arr[level_3_index]}" ]
                    then
                        level_4_directive_d3=${level_4_directive_d2_arr[level_3_index]}
                        level_4_args_d3=${level_4_args_d2_arr[level_3_index]}
                        IFS="${delimiters[8]}" read -r -a level_4_directive_d3_arr <<< "$level_4_directive_d3"
                        IFS="${delimiters[8]}" read -r -a level_4_args_d3_arr <<< "$level_4_args_d3"

                        if [ "${level_3_args}" == "=${delimiters[7]}/" ] && [ "$skip_find_nodejs" -eq 0 ]
                        then
                            for((level_4_index=0;level_4_index<${#level_4_directive_d3_arr[@]};level_4_index++));
                            do
                                if [ "${level_4_directive_d3_arr[level_4_index]}" == "proxy_pass" ]
                                then
                                    if [[ ${level_4_args_d3_arr[level_4_index]} =~ ^http://nodejs ]]
                                    then
                                        nginx_domain_server_nodejs_status="${green}$(gettext "已配置")${normal}"
                                        skip_find_nodejs=1
                                    fi
                                    break
                                fi
                            done
                        elif [ "${level_3_args}" == "/" ]
                        then
                            for((level_4_index=0;level_4_index<${#level_4_directive_d3_arr[@]};level_4_index++));
                            do
                                if [ "${level_4_directive_d3_arr[level_4_index]}" == "root" ]
                                then
                                    if [ "${level_4_args_d3_arr[level_4_index]:0:1}" == "/" ]
                                    then
                                        server_root=${level_4_args_d3_arr[level_4_index]}
                                    else
                                        server_root="$nginx_prefix/${level_4_args_d3_arr[level_4_index]}"
                                    fi
                                    break
                                fi
                            done
                        fi
                    fi
                elif [ "$level_3_directive" == "root" ]
                then
                    if [ "${level_3_args_d2_arr[level_3_index]:0:1}" == "/" ]
                    then
                        server_root=${level_3_args_d2_arr[level_3_index]}
                    else
                        server_root="$nginx_prefix/${level_3_args_d2_arr[level_3_index]}"
                    fi
                fi
            done

            nginx_domain_servers_name+=("${nginx_domain_server_name_list//, /,}")
            nginx_domain_servers_root+=("$server_root")
            nginx_domain_servers_list="$nginx_domain_servers_list $nginx_domain_servers_count.${indent_6}$i18n_domain: ${green}${nginx_domain_server_name_list:-$i18n_not_set}${normal}\n${indent_6}$i18n_port: ${green}${nginx_domain_server_listen_list:-$i18n_not_set}${normal}\n${indent_6}flv: $nginx_domain_server_flv_status\n${indent_6}nodejs: $nginx_domain_server_nodejs_status\n\n"
        fi
    done

    if [ "$nginx_domain_servers_count" -eq 0 ]
    then
        local current_domain="${nginx_domains[nginx_domains_index]}"
        Println "$(eval_gettext "\$error 请先添加 \$current_domain 配置")\n"
        exit 1
    fi

    local current_domain="${nginx_domains[nginx_domains_index]}"
    Println "$(eval_gettext "域名 \${green}\$current_domain\${normal} 配置:")\n\n$nginx_domain_servers_list"
}
NginxSelectDomainServer()
{
    echo "$i18n_input_no"
    while read -p "$i18n_default_cancel" nginx_domain_servers_num
    do
        case "$nginx_domain_servers_num" in
            "")
                Println "$i18n_canceled...\n"
                exit 1
            ;;
            *[!0-9]*)
                Println "$error $i18n_input_correct_no\n"
            ;;
            *)
                if [ "$nginx_domain_servers_num" -gt 0 ] && [ "$nginx_domain_servers_num" -le "$nginx_domain_servers_count" ]
                then
                    nginx_domain_servers_index=$((nginx_domain_servers_num-1))
                    level_2_add_indices=( "${nginx_domain_servers_indices[nginx_domain_servers_index]}" )
                    server_root=${nginx_domain_servers_root[nginx_domain_servers_index]}
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done
}
NginxConfigDomain()
{
    NginxListDomain

    NginxSelectDomainServer

    echo
    domain_server_options=( "$(gettext "修改指令")" "$(gettext "更新证书")" "$(gettext "添加 flv 设置")" "$(gettext "添加 nodejs 设置")" )
    inquirer list_input_index "$i18n_select_action" domain_server_options domain_server_options_index

    if [ "$domain_server_options_index" -eq 0 ] 
    then
        NginxConfigDirective level_2
    elif [ "$domain_server_options_index" -eq 1 ] 
    then
        AcmeCheck
        NginxDomainServerUpdateCrt
    elif [ "$domain_server_options_index" -eq 2 ] 
    then
        updated=0
        NginxAddFlv
        if [ "$updated" -eq 1 ] 
        then
            NginxBuildConf parse_out
        fi
        Println "$(eval_gettext "\$info flv 配置添加成功")\n"
    else
        server_name=${nginx_domain_servers_name[nginx_domain_servers_index]}

        if [[ $server_name =~ , ]] 
        then
            IFS="," read -r -a domains <<< "$server_name"

            echo
            inquirer list_input "$(gettext "选择域名"): " domains server_name
        fi
        updated=0
        NginxAddNodejs
        if [ "$updated" -eq 1 ] 
        then
            NginxBuildConf parse_out
        fi
        Println "$(eval_gettext "\$info nodejs 配置添加成功")\n"
    fi
}
NginxGetStream()
{
    nginx_stream_server_name_list=""
    nginx_stream_protocol_list=""
    nginx_stream_alpn_protocols_list=""
    nginx_stream_upstream_list=""
    nginx_stream_server_name_count=0
    nginx_stream_protocol_count=0
    nginx_stream_alpn_protocols_count=0
    nginx_stream_upstream_count=0
    nginx_stream_server_name=()
    nginx_stream_protocol=()
    nginx_stream_alpn_protocols=()
    nginx_stream_upstream=()
    nginx_stream_upstream_indices=()

    for((level_1_index=0;level_1_index<level_1_count;level_1_index++));
    do
        if [ "${level_1_directive_arr[level_1_index]}" == "stream" ]
        then
            if [ -z "${level_3_directive_arr[level_1_index]}" ]
            then
                break
            fi

            level_1_add_indices=( "$level_1_index" )

            level_2_directive_d1=${level_2_directive_arr[level_1_index]}
            level_2_args_d1=${level_2_args_arr[level_1_index]}
            level_3_directive_d1=${level_3_directive_arr[level_1_index]}
            level_3_args_d1=${level_3_args_arr[level_1_index]}

            IFS="${delimiters[4]}" read -r -a level_2_directive_d1_arr <<< "$level_2_directive_d1"
            IFS="${delimiters[4]}" read -r -a level_2_args_d1_arr <<< "$level_2_args_d1"
            IFS="${delimiters[5]}" read -r -a level_3_directive_d1_arr <<< "$level_3_directive_d1"
            IFS="${delimiters[5]}" read -r -a level_3_args_d1_arr <<< "$level_3_args_d1"

            for((level_2_index=0;level_2_index<${#level_2_directive_d1_arr[@]};level_2_index++));
            do
                if [ -n "${level_3_directive_d1_arr[level_2_index]}" ]
                then
                    level_3_directive_d2=${level_3_directive_d1_arr[level_2_index]}
                    level_3_args_d2=${level_3_args_d1_arr[level_2_index]}

                    IFS="${delimiters[6]}" read -r -a level_3_directive_d2_arr <<< "$level_3_directive_d2"
                    IFS="${delimiters[6]}" read -r -a level_3_args_d2_arr <<< "$level_3_args_d2"

                    if [ "${level_2_directive_d1_arr[level_2_index]}" == "map" ]
                    then
                        if [ "${level_2_args_d1_arr[level_2_index]}" == "\$ssl_preread_server_name${delimiters[5]}\$upstream" ]
                        then
                            for((server_name_i=0;server_name_i<${#level_3_directive_d2_arr[@]};server_name_i++));
                            do
                                nginx_stream_server_name_list="$nginx_stream_server_name_list $((server_name_i+1)).${indent_6}${green}${level_3_directive_d2_arr[server_name_i]}${normal} => ${green}${level_3_args_d2_arr[server_name_i]}${normal}\n"
                                nginx_stream_server_name+=("${level_3_directive_d2_arr[server_name_i]} => ${level_3_args_d2_arr[server_name_i]}")
                            done
                        elif [ "${level_2_args_d1_arr[level_2_index]}" == "\$ssl_preread_protocol${delimiters[5]}\$ssl_proxy" ]
                        then
                            for((protocol_i=0;protocol_i<${#level_3_directive_d2_arr[@]};protocol_i++));
                            do
                                nginx_stream_protocol_list="$nginx_stream_protocol_list $((protocol_i+1)).${indent_6}${green}${level_3_directive_d2_arr[protocol_i]:-''}${normal} => ${green}${level_3_args_d2_arr[protocol_i]}${normal}\n"
                                nginx_stream_protocol+=("${level_3_directive_d2_arr[protocol_i]:-''} => ${level_3_args_d2_arr[protocol_i]}")
                            done
                        elif [ "${level_2_args_d1_arr[level_2_index]}" == "\$ssl_preread_alpn_protocols${delimiters[5]}\$proxy_pass" ]
                        then
                            for((alpn_protocols_i=0;alpn_protocols_i<${#level_3_directive_d2_arr[@]};alpn_protocols_i++));
                            do
                                nginx_stream_alpn_protocols_list="$nginx_stream_alpn_protocols_list $((alpn_protocols_i+1)).${indent_6}${green}${level_3_directive_d2_arr[alpn_protocols_i]}${normal} => ${green}${level_3_args_d2_arr[alpn_protocols_i]}${normal}\n"
                                nginx_stream_alpn_protocols+=("${level_3_directive_d2_arr[alpn_protocols_i]} => ${level_3_args_d2_arr[alpn_protocols_i]}")
                            done
                        fi
                    elif [ "${level_2_directive_d1_arr[level_2_index]}" == "upstream" ]
                    then
                        nginx_stream_upstream_indices+=("$level_2_index")
                        nginx_stream_upstream_count=$((nginx_stream_upstream_count+1))
                        nginx_stream_upstream_list="$nginx_stream_upstream_list $nginx_stream_upstream_count.${indent_6}${green}${level_2_args_d1_arr[level_2_index]}${normal} => ${green}${level_3_args_d2_arr[0]}${normal}\n"
                        nginx_stream_upstream+=("${level_2_args_d1_arr[level_2_index]} => ${level_3_args_d2_arr[0]}")
                    fi
                fi
            done
            break
        fi
    done

    if [ -n "${nginx_stream_server_name:-}" ]
    then
        nginx_stream_server_name_count=${#nginx_stream_server_name[@]}
    fi

    if [ -n "${nginx_stream_protocol:-}" ]
    then
        nginx_stream_protocol_count=${#nginx_stream_protocol[@]}
    fi

    if [ -n "${nginx_stream_alpn_protocols:-}" ]
    then
        nginx_stream_alpn_protocols_count=${#nginx_stream_alpn_protocols[@]}
    fi
}
NginxListStream()
{
    NginxGetStream

    Println "$(gettext "分流配置:")\n\n $(gettext "SNI 域名分流:")\n\n${nginx_stream_server_name_list:- $i18n_none}\n\n $(gettext "SSL 协议分流")(\$ssl_proxy):\n\n${nginx_stream_protocol_list:- $i18n_none}\n\n $(gettext "ALPN 协议分流:")\n\n${nginx_stream_alpn_protocols_list:- $i18n_none}\n\n $(gettext "分流后端")(\$upstream):\n\n${nginx_stream_upstream_list:- $i18n_none}\n\n"
}
NginxListLocalhost()
{
    NginxCheckLocalhost

    nginx_localhost_list=""
    nginx_localhost_server_count=0
    nginx_localhost_server_indices=()
    nginx_localhost_server_root=()

    for((level_1_index=0;level_1_index<level_1_count;level_1_index++));
    do
        if [ "${level_1_directive_arr[level_1_index]}" == "http" ]
        then
            if [ -z "${level_3_directive_arr[level_1_index]}" ]
            then
                break
            fi

            level_1_add_indices=( "$level_1_index" )

            level_2_directive_d1=${level_2_directive_arr[level_1_index]}
            level_3_directive_d1=${level_3_directive_arr[level_1_index]}
            level_3_args_d1=${level_3_args_arr[level_1_index]}

            IFS="${delimiters[4]}" read -r -a level_2_directive_d1_arr <<< "$level_2_directive_d1"
            IFS="${delimiters[5]}" read -r -a level_3_directive_d1_arr <<< "$level_3_directive_d1"
            IFS="${delimiters[5]}" read -r -a level_3_args_d1_arr <<< "$level_3_args_d1"

            if [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_arr[level_1_index]}" ]
            then
                level_4_directive_d1=${level_4_directive_arr[level_1_index]}
                level_4_args_d1=${level_4_args_arr[level_1_index]}
                IFS="${delimiters[6]}" read -r -a level_4_directive_d1_arr <<< "$level_4_directive_d1"
                IFS="${delimiters[6]}" read -r -a level_4_args_d1_arr <<< "$level_4_args_d1"
            fi

            for((level_2_index=0;level_2_index<${#level_2_directive_d1_arr[@]};level_2_index++));
            do
                if [ "${level_2_directive_d1_arr[level_2_index]}" == "server" ]
                then
                    level_3_directive_d2=${level_3_directive_d1_arr[level_2_index]}
                    level_3_args_d2=${level_3_args_d1_arr[level_2_index]}

                    IFS="${delimiters[6]}" read -r -a level_3_directive_d2_arr <<< "$level_3_directive_d2"
                    IFS="${delimiters[6]}" read -r -a level_3_args_d2_arr <<< "$level_3_args_d2"

                    if [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_arr[level_1_index]}" ] && [ -n "${level_4_directive_d1_arr[level_2_index]}" ]
                    then
                        level_4_directive_d2=${level_4_directive_d1_arr[level_2_index]}
                        level_4_args_d2=${level_4_args_d1_arr[level_2_index]}
                        IFS="${delimiters[7]}" read -r -a level_4_directive_d2_arr <<< "$level_4_directive_d2"
                        IFS="${delimiters[7]}" read -r -a level_4_args_d2_arr <<< "$level_4_args_d2"
                    fi

                    nginx_localhost_server_count=$((nginx_localhost_server_count+1))
                    nginx_localhost_server_indices+=("$level_2_index")
                    nginx_localhost_listen=""
                    nginx_localhost_flv_status="${red}$(gettext "未配置")${normal}"
                    nginx_localhost_nodejs_status="${red}$(gettext "未配置")${normal}"
                    skip_find_nodejs=0
                    server_root=""

                    for((level_3_index=0;level_3_index<${#level_3_directive_d2_arr[@]};level_3_index++));
                    do
                        level_3_directive=${level_3_directive_d2_arr[level_3_index]}
                        level_3_args=${level_3_args_d2_arr[level_3_index]}

                        if [ "$level_3_directive" == "listen" ]
                        then
                            [ -n "$nginx_localhost_listen" ] && nginx_localhost_listen="$nginx_localhost_listen, "
                            nginx_localhost_listen="$nginx_localhost_listen${level_3_args//${delimiters[7]}/ }"
                        elif [ "$level_3_directive" == "location" ]
                        then
                            if [ "${level_3_args}" == "/flv" ]
                            then
                                nginx_localhost_flv_status="${green}$(gettext "已配置")${normal}"
                            elif [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_arr[level_1_index]}" ] && [ -n "${level_4_directive_d1_arr[level_2_index]}" ] && [ -n "${level_4_directive_d2_arr[level_3_index]}" ]
                            then
                                level_4_directive_d3=${level_4_directive_d2_arr[level_3_index]}
                                level_4_args_d3=${level_4_args_d2_arr[level_3_index]}
                                IFS="${delimiters[8]}" read -r -a level_4_directive_d3_arr <<< "$level_4_directive_d3"
                                IFS="${delimiters[8]}" read -r -a level_4_args_d3_arr <<< "$level_4_args_d3"

                                if [ "${level_3_args}" == "=${delimiters[7]}/" ] && [ "$skip_find_nodejs" -eq 0 ]
                                then
                                    for((level_4_index=0;level_4_index<${#level_4_directive_d3_arr[@]};level_4_index++));
                                    do
                                        if [ "${level_4_directive_d3_arr[level_4_index]}" == "proxy_pass" ]
                                        then
                                            if [[ ${level_4_args_d3_arr[level_4_index]} =~ ^http://nodejs ]]
                                            then
                                                nginx_localhost_nodejs_status="${green}$(gettext "已配置")${normal}"
                                                skip_find_nodejs=1
                                            fi
                                            break
                                        fi
                                    done
                                elif [ "${level_3_args}" == "/" ]
                                then
                                    for((level_4_index=0;level_4_index<${#level_4_directive_d3_arr[@]};level_4_index++));
                                    do
                                        if [ "${level_4_directive_d3_arr[level_4_index]}" == "root" ]
                                        then
                                            if [ "${level_4_args_d3_arr[level_4_index]:0:1}" == "/" ]
                                            then
                                                server_root=${level_4_args_d3_arr[level_4_index]}
                                            else
                                                server_root="$nginx_prefix/${level_4_args_d3_arr[level_4_index]}"
                                            fi
                                            break
                                        fi
                                    done
                                fi
                            fi
                        elif [ "$level_3_directive" == "root" ]
                        then
                            if [ "${level_3_args_d2_arr[level_3_index]:0:1}" == "/" ]
                            then
                                server_root=${level_3_args_d2_arr[level_3_index]}
                            else
                                server_root="$nginx_prefix/${level_3_args_d2_arr[level_3_index]}"
                            fi
                        fi
                    done

                    nginx_localhost_server_root+=("$server_root")
                    nginx_localhost_list="$nginx_localhost_list $nginx_localhost_server_count.${indent_6}$i18n_port: ${green}${nginx_localhost_listen:-$i18n_not_set}${normal}\n${indent_6}flv: $nginx_localhost_flv_status\n${indent_6}nodejs: $nginx_localhost_nodejs_status\n\n"
                fi
            done
            break
        fi
    done

    if [ "$nginx_localhost_server_count" -eq 0 ]
    then
        Println "$(eval_gettext "\$error 请先添加本地配置")\n"
        exit 1
    fi

    Println "$(gettext "本地配置:")\n\n$nginx_localhost_list"
}
NginxSelectLocalhostServer()
{
    echo "$i18n_input_no"
    while read -p "$i18n_default_cancel" nginx_localhost_server_num
    do
        case "$nginx_localhost_server_num" in
            "")
                Println "$i18n_canceled...\n"
                exit 1
            ;;
            *[!0-9]*)
                Println "$error $i18n_input_correct_no\n"
            ;;
            *)
                if [ "$nginx_localhost_server_num" -gt 0 ] && [ "$nginx_localhost_server_num" -le "$nginx_localhost_server_count" ]
                then
                    nginx_localhost_server_index=$((nginx_localhost_server_num-1))
                    level_2_add_indices=( "${nginx_localhost_server_indices[nginx_localhost_server_index]}" )
                    server_root=${nginx_localhost_server_root[nginx_localhost_server_index]}
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done
}
NginxIsBlockDirective()
{
    local level=("level_${1}_block_directives"[@])
    local block_directives=("${!level}")
    for block_directive in "${block_directives[@]}"
    do
        if [ "$block_directive" == "$2" ] 
        then
            return 0
        fi
    done
    return 1
}
NginxInputArgs()
{
    new_args=""
    while true 
    do
        Println "$(eval_gettext "\$tip 空字符用 '' 表示")"
        inquirer text_input "$(gettext "输入单个指令值: ")" arg "$i18n_blank"

        if [ -z "$arg" ] 
        then
            break
        fi

        [ -n "$new_args" ] && new_args="$new_args,"

        if [ "$arg" == "''" ] 
        then
            arg=""
        else
            arg=${arg//\\/\\\\}
            arg=${arg//\"/\\\"}
        fi

        new_args="$new_args\"$arg\""

        echo
        inquirer list_input "$(gettext "继续添加指令值")" ny_options yn_option
        if [ "$yn_option" == "$i18n_no" ] 
        then
            break
        fi
    done
}
NginxAddDirective()
{
    case $1 in
        1)
            local level_1_index
            new_directive=""
            add_count=0
            level_1_add_indices=()

            for((directive_i=0;directive_i<${#directives[@]};directive_i++));
            do
                if [ "${check_directives[directive_i]:-1}" -eq 1 ]
                then
                    for((level_1_index=0;level_1_index<level_1_count;level_1_index++));
                    do
                        if [ "${level_1_directive_arr[level_1_index]}" == "${directives[directive_i]}" ]
                        then
                            if [ -n "${check_args[directive_i]:-}" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"args"]'
                                args=$(JQs get parse_out)
                                if [ "$args" == "${check_args[directive_i]}" ]
                                then
                                    level_1_add_indices+=("$level_1_index")
                                    continue 2
                                fi
                            else
                                level_1_add_indices+=("$level_1_index")
                                continue 2
                            fi
                        fi
                    done
                fi

                level_1_add_indices+=("$((level_1_count+add_count))")
                add_count=$((add_count+1))
                jq_path='["config",0,"parsed"]'
                new_directive="directive_${directives_val[directive_i]:-${directives[directive_i]}}"
                JQs add parse_out "[${!new_directive}]"
            done

            if [ -n "$new_directive" ]
            then
                NginxGetConfig
                updated=1
            fi
        ;;
        2)
            local level_1_index level_2_index
            new_directive=""
            add_count=0
            level_2_add_indices=()

            for((directive_i=0;directive_i<${#directives[@]};directive_i++));
            do
                level_1_index=${level_1_add_indices[directive_i]:-${level_1_add_indices[0]}}

                level_2_directive_d1=${level_2_directive_arr[level_1_index]}

                level_2_directive_d1_arr_count=0

                if [ -n "$level_2_directive_d1" ]
                then
                    IFS="${delimiters[4]}" read -r -a level_2_directive_d1_arr <<< "$level_2_directive_d1"
                    level_2_directive_d1_arr_count=${#level_2_directive_d1_arr[@]}
                fi

                if [ "${check_directives[directive_i]:-1}" -eq 1 ]
                then
                    for((level_2_index=0;level_2_index<level_2_directive_d1_arr_count;level_2_index++));
                    do
                        if [ "${level_2_directive_d1_arr[level_2_index]}" == "${directives[directive_i]}" ]
                        then
                            if [ -n "${check_args[directive_i]:-}" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"args"]'
                                args=$(JQs get parse_out)
                                if [ "$args" == "${check_args[directive_i]}" ]
                                then
                                    level_2_add_indices+=("$level_2_index")
                                    continue 2
                                fi
                            else
                                level_2_add_indices+=("$level_2_index")
                                continue 2
                            fi
                        fi
                    done
                fi

                level_2_add_indices+=("$((level_2_directive_d1_arr_count+add_count))")
                add_count=$((add_count+1))
                jq_path='["config",0,"parsed",'"$level_1_index"',"block"]'
                new_directive="directive_${directives_val[directive_i]:-${directives[directive_i]}}"
                JQs add parse_out "[${!new_directive}]"
            done

            if [ -n "$new_directive" ]
            then
                NginxGetConfig
                updated=1
            fi
        ;;
        3)
            local level_1_index level_2_index level_3_index
            new_directive=""
            add_count=0
            level_3_add_indices=()

            for((directive_i=0;directive_i<${#directives[@]};directive_i++));
            do
                level_1_index=${level_1_add_indices[directive_i]:-${level_1_add_indices[0]}}
                level_2_index=${level_2_add_indices[directive_i]:-${level_2_add_indices[0]}}

                level_3_directive_d1=${level_3_directive_arr[level_1_index]}
                IFS="${delimiters[5]}" read -r -a level_3_directive_d1_arr <<< "$level_3_directive_d1"

                level_3_directive_d2=${level_3_directive_d1_arr[level_2_index]}

                level_3_directive_d2_arr_count=0

                if [ -n "$level_3_directive_d2" ]
                then
                    IFS="${delimiters[6]}" read -r -a level_3_directive_d2_arr <<< "$level_3_directive_d2"
                    level_3_directive_d2_arr_count=${#level_3_directive_d2_arr[@]}
                fi

                if [ "${check_directives[directive_i]:-1}" -eq 1 ]
                then
                    for((level_3_index=0;level_3_index<level_3_directive_d2_arr_count;level_3_index++));
                    do
                        if [ "${level_3_directive_d2_arr[level_3_index]}" == "${directives[directive_i]}" ]
                        then
                            if [ -n "${check_args[directive_i]:-}" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"args"]'
                                args=$(JQs get parse_out)
                                if [ "$args" == "${check_args[directive_i]}" ]
                                then
                                    level_3_add_indices+=("$level_3_index")
                                    continue 2
                                fi
                            else
                                level_3_add_indices+=("$level_3_index")
                                continue 2
                            fi
                        fi
                    done
                fi

                level_3_add_indices+=("$((level_3_directive_d2_arr_count+add_count))")
                add_count=$((add_count+1))
                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block"]'
                new_directive="directive_${directives_val[directive_i]:-${directives[directive_i]}}"
                JQs add parse_out "[${!new_directive}]"
            done

            if [ -n "$new_directive" ]
            then
                NginxGetConfig
                updated=1
            fi
        ;;
        4)
            local level_1_index level_2_index level_3_index level_4_index
            new_directive=""
            add_count=0
            level_4_add_indices=()

            for((directive_i=0;directive_i<${#directives[@]};directive_i++));
            do
                level_1_index=${level_1_add_indices[directive_i]:-${level_1_add_indices[0]}}
                level_2_index=${level_2_add_indices[directive_i]:-${level_2_add_indices[0]}}
                level_3_index=${level_3_add_indices[directive_i]:-${level_3_add_indices[0]}}

                level_4_directive_d1=${level_4_directive_arr[level_1_index]}
                IFS="${delimiters[6]}" read -r -a level_4_directive_d1_arr <<< "$level_4_directive_d1"

                level_4_directive_d2=${level_4_directive_d1_arr[level_2_index]}
                IFS="${delimiters[7]}" read -r -a level_4_directive_d2_arr <<< "$level_4_directive_d2"

                level_4_directive_d3=${level_4_directive_d2_arr[level_3_index]}

                level_4_directive_d3_arr_count=0

                if [ -n "$level_4_directive_d3" ]
                then
                    IFS="${delimiters[8]}" read -r -a level_4_directive_d3_arr <<< "$level_4_directive_d3"
                    level_4_directive_d3_arr_count=${#level_4_directive_d3_arr[@]}
                fi

                if [ "${check_directives[directive_i]:-1}" -eq 1 ]
                then
                    for((level_4_index=0;level_4_index<level_4_directive_d3_arr_count;level_4_index++));
                    do
                        if [ "${level_4_directive_d3_arr[level_4_index]}" == "${directives[directive_i]}" ]
                        then
                            if [ -n "${check_args[directive_i]:-}" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"block",'"$level_4_index"',"args"]'
                                args=$(JQs get parse_out)
                                if [ "$args" == "${check_args[directive_i]}" ]
                                then
                                    level_4_add_indices+=("$level_4_index")
                                    continue 2
                                fi
                            else
                                level_4_add_indices+=("$level_4_index")
                                continue 2
                            fi
                        fi
                    done
                fi

                level_4_add_indices+=("$((level_4_directive_d3_arr_count+add_count))")
                add_count=$((add_count+1))
                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"block"]'
                new_directive="directive_${directives_val[directive_i]:-${directives[directive_i]}}"
                JQs add parse_out "[${!new_directive}]"
            done

            if [ -n "$new_directive" ]
            then
                NginxGetConfig
                updated=1
            fi
        ;;
        5)
            local level_1_index level_2_index level_3_index level_4_index level_5_index
            new_directive=""
            add_count=0
            level_5_add_indices=()

            for((directive_i=0;directive_i<${#directives[@]};directive_i++));
            do
                level_1_index=${level_1_add_indices[directive_i]:-${level_1_add_indices[0]}}
                level_2_index=${level_2_add_indices[directive_i]:-${level_2_add_indices[0]}}
                level_3_index=${level_3_add_indices[directive_i]:-${level_3_add_indices[0]}}
                level_4_index=${level_4_add_indices[directive_i]:-${level_4_add_indices[0]}}

                level_5_directive_d1=${level_5_directive_arr[level_1_index]}
                IFS="${delimiters[7]}" read -r -a level_5_directive_d1_arr <<< "$level_5_directive_d1"

                level_5_directive_d2=${level_5_directive_d1_arr[level_2_index]}
                IFS="${delimiters[8]}" read -r -a level_5_directive_d2_arr <<< "$level_5_directive_d2"

                level_5_directive_d3=${level_5_directive_d2_arr[level_3_index]}
                IFS="${delimiters[9]}" read -r -a level_5_directive_d3_arr <<< "$level_5_directive_d3"

                level_5_directive_d4=${level_5_directive_d3_arr[level_4_index]}

                level_5_directive_d4_arr_count=0

                if [ -n "$level_5_directive_d4" ]
                then
                    IFS="${delimiters[10]}" read -r -a level_5_directive_d4_arr <<< "$level_5_directive_d4"
                    level_5_directive_d4_arr_count=${#level_5_directive_d4_arr[@]}
                fi

                if [ "${check_directives[directive_i]:-1}" -eq 1 ]
                then
                    for((level_5_index=0;level_5_index<level_5_directive_d4_arr_count;level_5_index++));
                    do
                        if [ "${level_5_directive_d4_arr_count[level_5_index]}" == "${directives[directive_i]}" ]
                        then
                            if [ -n "${check_args[directive_i]:-}" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"block",'"$level_4_index"',"block",'"$level_5_index"',"args"]'
                                args=$(JQs get parse_out)
                                if [ "$args" == "${check_args[directive_i]}" ]
                                then
                                    level_5_add_indices+=("$level_5_index")
                                    continue 2
                                fi
                            else
                                level_5_add_indices+=("$level_5_index")
                                continue 2
                            fi
                        fi
                    done
                fi

                level_5_add_indices+=("$((level_5_directive_d4_arr_count+add_count))")
                add_count=$((add_count+1))
                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"block",'"$level_4_index"',"block"]'
                new_directive="directive_${directives_val[directive_i]:-${directives[directive_i]}}"
                JQs add parse_out "[${!new_directive}]"
            done

            if [ -n "$new_directive" ]
            then
                NginxGetConfig
                updated=1
            fi
        ;;
        level_1|level_2|level_3|level_4|level_5)
            level_id=${1#*_}

            zh=( "" "$(gettext "一")" "$(gettext "二")" "$(gettext "三")" "$(gettext "四")" "$(gettext "五")" )
            local level_zh="${zh[level_id]}"

            Println "$(eval_gettext "\$tip 空字符用 '' 表示")"
            inquirer text_input "$(eval_gettext "输入\${level_zh}级指令: ")" new_directive "$i18n_cancel"

            if [ "$new_directive" == "$i18n_cancel" ]
            then
                return 0
            fi

            if [ "$new_directive" == "''" ]
            then
                new_directive=""
            fi

            NginxInputArgs

            is_block_directive=0

            if [ "$level_id" -ne 5 ]
            then
                Println "$(eval_gettext "\$tip 如果需要添加下级指令请选择 是")"
                inquirer list_input "$(gettext "是否是 块 指令")" ny_options yn_option

                if [ "$yn_option" == "$i18n_yes" ]
                then
                    is_block_directive=1
                fi
            fi

            if [ "$is_block_directive" -eq 1 ]
            then
                directive=$(
                    $JQ_FILE -n --arg directive "$new_directive" --argjson args "[$new_args]" \
                    '{
                        "directive": $directive,
                        "args": $args,
                        "block":[]
                    }'
                )
            else
                directive=$(
                    $JQ_FILE -n --arg directive "$new_directive" --argjson args "[$new_args]" \
                    '{
                        "directive": $directive,
                        "args": $args
                    }'
                )
            fi

            jq_path='"config",0,"parsed"'

            for((level_i=1;level_i<level_id;level_i++));
            do
                index_name="level_${level_i}_index"
                jq_path="$jq_path,${!index_name},\"block\""
            done

            jq_path="[$jq_path]"
            JQs add parse_out "[$directive]"

            NginxBuildConf parse_out
            NginxGetConfig

            Println "$(eval_gettext "\$info 指令 \$new_directive 添加成功")\n"
        ;;
    esac
}
