NginxCheckLocalhost()
{
    if [ ! -d "$nginx_prefix" ]
    then
        Println "$(eval_gettext "\$error \$nginx_name 未安装 !")\n"
        exit 1
    fi

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"

    NginxParseConfig
    NginxGetConfig

    updated=0

    NginxAddUser

    NginxAddHttp

    NginxAddEnabled

    NginxAddSsl

    server_offset=0

    if [ "$level_2_d1_count" -gt 0 ]
    then
        for((level_1_index=0;level_1_index<level_1_count;level_1_index++));
        do
            if [ "${level_1_directive_arr[level_1_index]}" == "http" ]
            then
                if [ -z "${level_2_directive_arr[level_1_index]}" ]
                then
                    break
                fi

                level_2_directive_d1=${level_2_directive_arr[level_1_index]}
                level_2_args_d1=${level_2_args_arr[level_1_index]}

                IFS="${delimiters[4]}" read -r -a level_2_directive_d1_arr <<< "$level_2_directive_d1"
                IFS="${delimiters[4]}" read -r -a level_2_args_d1_arr <<< "$level_2_args_d1"

                if [ "$level_3_d1_count" -gt 0 ] && [ -n "${level_3_directive_arr[level_1_index]}" ]
                then
                    level_3_directive_d1=${level_3_directive_arr[level_1_index]}
                    level_3_args_d1=${level_3_args_arr[level_1_index]}
                    IFS="${delimiters[5]}" read -r -a level_3_directive_d1_arr <<< "$level_3_directive_d1"
                    IFS="${delimiters[5]}" read -r -a level_3_args_d1_arr <<< "$level_3_args_d1"
                fi

                for((level_2_index=0;level_2_index<${#level_2_directive_d1_arr[@]};level_2_index++));
                do
                    if [ "${level_2_directive_d1_arr[level_2_index]}" == "server" ] && [ "$level_3_d1_count" -gt 0 ] && [ -n "${level_3_directive_arr[level_1_index]}" ] && [ -n "${level_3_directive_d1_arr[level_2_index]}" ]
                    then
                        level_3_directive_d2=${level_3_directive_d1_arr[level_2_index]}
                        level_3_args_d2=${level_3_args_d1_arr[level_2_index]}
                        IFS="${delimiters[6]}" read -r -a level_3_directive_d2_arr <<< "$level_3_directive_d2"
                        IFS="${delimiters[6]}" read -r -a level_3_args_d2_arr <<< "$level_3_args_d2"

                        for((level_3_index=0;level_3_index<${#level_3_directive_d2_arr[@]};level_3_index++));
                        do
                            if [ "${level_3_directive_d2_arr[level_3_index]}" == "server_name" ]
                            then
                                if [ "${level_3_args_d2_arr[level_3_index]}" == "localhost" ]
                                then
                                    continue 2
                                fi
                                updated=1
                                IFS="${delimiters[7]}" read -r -a domains <<< "${level_3_args_d2_arr[level_3_index]}"
                                new_conf='{"status":"ok","errors":[],"config":[]}'
                                localhost_found=0
                                for((l=0;l<${#domains[@]};l++));
                                do
                                    if [ "${domains[l]}" == "localhost" ]
                                    then
                                        localhost_found=1
                                        continue
                                    fi
                                    jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"']'
                                    new_server=$(JQs get parse_out)
                                    jq_path='["block",'"$level_3_index"',"args"]'
                                    JQs replace new_server '["'${domains[l]}'"]'
                                    jq_path='["config"]'
                                    JQs add new_conf '[{"file":"'"$nginx_prefix/conf/sites_available/${domains[l]}.conf"'","status":"ok","errors":[],"parsed":['"$new_server"']}]'
                                    ln -sf "$nginx_prefix/conf/sites_available/${domains[l]}.conf" "$nginx_prefix/conf/sites_enabled/"
                                done
                                NginxBuildConf new_conf
                                if [ "$localhost_found" -eq 0 ]
                                then
                                    jq_path='["config",0,"parsed",'"$level_1_index"',"block"]'
                                    JQs delete parse_out "$((j-server_offset))"
                                    server_offset=$((server_offset+1))
                                else
                                    jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"args"]'
                                    JQs replace parse_out '["localhost"]'
                                fi
                            elif [ "${level_3_directive_d2_arr[level_3_index]}" == "add_header" ] && [ "${level_3_args_d2_arr[level_3_index]}" == 'Access-Control-Allow-Origin'"${delimiters[7]}"'$corsHost' ]
                            then
                                updated=1
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"args"]'
                                JQs replace parse_out '["Access-Control-Allow-Origin","$cors_host"]'
                            fi
                        done
                    elif [ "${level_2_directive_d1_arr[level_2_index]}" == "map" ] && [ "${level_2_args_d1_arr[level_2_index]}" == '$http_origin'"${delimiters[5]}"'$corsHost' ]
                    then
                        updated=1
                        jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"args"]'
                        JQs replace parse_out '["$http_origin","$cors_host"]'
                    fi
                done
                break
            fi
        done
    fi

    if [ "$server_offset" -gt 0 ]
    then
        NginxGetConfig
    fi

    NginxAddLocalhost

    if "$NGINX_FILE" -V 2>&1 | grep -qi nginx-http-flv-module
    then
        NginxAddRtmp
    fi

    if [ "$updated" -eq 1 ]
    then
        NginxBuildConf parse_out

        if ls -A "$nginx_prefix/conf/sites_available/"* > /dev/null 2>&1
        then
            for f in "$nginx_prefix/conf/sites_available/"*
            do
                sed -i 's/$corsHost/$cors_host/g' "$f"
            done
        fi

        sed -i 's/$corsHost/$cors_host/g' "$nginx_prefix/conf/nginx.conf"
    fi
}
NginxConfigDirective()
{
    local msg_add_directive msg_select_directive msg_edit_directive msg_delete_directive msg_back_select msg_confirm_delete
    msg_add_directive=$(gettext "添加指令")
    msg_select_directive=$(gettext "选择指令")
    msg_edit_directive=$(gettext "修改指令")
    msg_delete_directive=$(gettext "删除指令")
    msg_back_select=$(gettext "返回选择")
    msg_confirm_delete=$(gettext "确认删除, 此操作不可恢复")

    case $1 in
        level_1)
            local msg_edit_sub
            msg_edit_sub=$(gettext "修改二级指令")
            while true
            do
                level_1_options=()

                for((level_1_index=0;level_1_index<level_1_count;level_1_index++));
                do
                    level_1_option="${level_1_directive_arr[level_1_index]:-''}"

                    if [ -n "${level_1_args_arr[level_1_index]}" ]
                    then
                        IFS="${delimiters[4]}" read -r -a args <<< "${level_1_args_arr[level_1_index]}"
                        for arg in "${args[@]}"
                        do
                            level_1_option="$level_1_option ${arg:-''}"
                        done
                    fi

                    level_1_option=${level_1_option//\\\\/\\}

                    if [ "$level_2_d1_count" -gt 0 ] && [ -n "${level_2_directive_arr[level_1_index]}" ]
                    then
                        level_1_option="$level_1_option {...}"
                    fi

                    level_1_options+=("$level_1_option")
                done

                level_1_options+=("$msg_add_directive" "$i18n_cancel")
                level_1_options_count=${#level_1_options[@]}

                while true
                do
                    echo
                    inquirer list_input_index "$msg_select_directive" level_1_options level_1_index

                    if [ "$level_1_index" -eq "$((level_1_options_count-1))" ]
                    then
                        Println "$i18n_canceled...\n"
                        break
                    elif [ "$level_1_index" -eq "$((level_1_options_count-2))" ]
                    then
                        NginxAddDirective level_1
                        continue 2
                    else
                        level_1_actions=("$msg_edit_sub" "$msg_edit_directive" "$msg_delete_directive" "$msg_back_select")

                        echo
                        inquirer list_input "$i18n_select_action" level_1_actions level_1_action

                        if [ "$level_1_action" == "$msg_edit_sub" ]
                        then
                            from_level_1=1
                            NginxConfigDirective level_2
                            unset from_level_1
                        elif [ "$level_1_action" == "$msg_edit_directive" ]
                        then
                            NginxInputArgs
                            jq_path='["config",0,"parsed",'"$level_1_index"',"args"]'
                            JQs replace parse_out "[$new_args]"
                            NginxBuildConf parse_out
                            local directive_name="${level_1_directive_arr[level_1_index]}"
                            Println "$(eval_gettext "\$info \$directive_name 指令修改成功")\n"
                            NginxGetConfig
                            continue 2
                        elif [ "$level_1_action" == "$msg_delete_directive" ]
                        then
                            echo
                            inquirer list_input "$msg_confirm_delete" ny_options yn_option
                            if [ "$yn_option" == "$i18n_yes" ]
                            then
                                jq_path='["config",0,"parsed"]'
                                JQs delete parse_out "$level_1_index"
                                NginxBuildConf parse_out
                                local directive_name="${level_1_directive_arr[level_1_index]}"
                                Println "$(eval_gettext "\$info 已删除指令 \$directive_name")\n"
                                NginxGetConfig
                                continue 2
                            fi
                        fi
                    fi
                done
                break
            done
        ;;
        level_2)
            local msg_back_parent msg_edit_sub
            msg_back_parent=$(gettext "返回一级指令")
            msg_edit_sub=$(gettext "修改三级指令")
            while true
            do
                level_2_options=()

                if [ "$level_2_d1_count" -gt 0 ] && [ -n "${level_2_directive_arr[level_1_index]}" ]
                then
                    level_2_directive_d1=${level_2_directive_arr[level_1_index]}
                    level_2_args_d1=${level_2_args_arr[level_1_index]}

                    IFS="${delimiters[4]}" read -r -a level_2_directive_d1_arr <<< "${level_2_directive_d1}"
                    IFS="${delimiters[4]}" read -r -a level_2_args_d1_arr <<< "${level_2_args_d1}"

                    if [ "$level_3_d1_count" -gt 0 ] && [ -n "${level_3_directive_arr[level_1_index]}" ]
                    then
                        level_3_directive_d1=${level_3_directive_arr[level_1_index]}
                        IFS="${delimiters[5]}" read -r -a level_3_directive_d1_arr <<< "${level_3_directive_d1}"
                    fi

                    for((level_2_index=0;level_2_index<${#level_2_directive_d1_arr[@]};level_2_index++));
                    do
                        level_2_option="${level_2_directive_d1_arr[level_2_index]:-''}"

                        if [ -n "${level_2_args_d1_arr[level_2_index]}" ]
                        then
                            IFS="${delimiters[5]}" read -r -a args <<< "${level_2_args_d1_arr[level_2_index]}"
                            for arg in "${args[@]}"
                            do
                                level_2_option="$level_2_option ${arg:-''}"
                            done
                        fi

                        level_2_option=${level_2_option//\\\\/\\}

                        if [ "$level_3_d1_count" -gt 0 ] && [ -n "${level_3_directive_arr[level_1_index]}" ] && [ -n "${level_3_directive_d1_arr[level_2_index]}" ]
                        then
                            level_2_option="$level_2_option {...}"
                        fi

                        level_2_options+=("$level_2_option")
                    done
                fi

                level_2_options+=("$msg_add_directive")

                if [ "${from_level_1:-0}" -eq 1 ]
                then
                    level_2_options+=("$msg_back_parent")
                else
                    level_2_options+=("$i18n_cancel")
                fi

                level_2_options_count=${#level_2_options[@]}

                while true
                do
                    echo
                    inquirer list_input_index "$msg_select_directive" level_2_options level_2_index

                    if [ "$level_2_index" -eq "$((level_2_options_count-1))" ]
                    then
                        if [ "${from_level_1:-0}" -eq 0 ]
                        then
                            Println "$i18n_canceled...\n"
                        fi
                        break
                    elif [ "$level_2_index" -eq "$((level_2_options_count-2))" ]
                    then
                        NginxAddDirective level_2
                        continue 2
                    else
                        level_2_actions=("$msg_edit_sub" "$msg_edit_directive" "$msg_delete_directive" "$msg_back_select")

                        echo
                        inquirer list_input "$i18n_select_action" level_2_actions level_2_action

                        if [ "$level_2_action" == "$msg_edit_sub" ]
                        then
                            from_level_2=1
                            NginxConfigDirective level_3
                            unset from_level_2
                        elif [ "$level_2_action" == "$msg_edit_directive" ]
                        then
                            NginxInputArgs
                            jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"args"]'
                            JQs replace parse_out "[$new_args]"
                            NginxBuildConf parse_out
                            NginxGetConfig
                            local directive_name="${level_2_directive_d1_arr[level_2_index]}"
                            Println "$(eval_gettext "\$info \$directive_name 指令修改成功")\n"
                            continue 2
                        elif [ "$level_2_action" == "$msg_delete_directive" ]
                        then
                            echo
                            inquirer list_input "$msg_confirm_delete" ny_options yn_option
                            if [ "$yn_option" == "$i18n_yes" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block"]'
                                JQs delete parse_out "$level_2_index"
                                NginxBuildConf parse_out
                                NginxGetConfig
                                local directive_name="${level_2_directive_d1_arr[level_2_index]}"
                                Println "$(eval_gettext "\$info 已删除指令 \$directive_name")\n"
                                continue 2
                            fi
                        fi
                    fi
                done
                break
            done
        ;;
        level_3)
            local msg_back_parent msg_edit_sub
            msg_back_parent=$(gettext "返回二级指令")
            msg_edit_sub=$(gettext "修改四级指令")
            while true
            do
                level_3_options=()

                if [ "$level_3_d1_count" -gt 0 ] && [ -n "${level_3_directive_arr[level_1_index]}" ]
                then
                    level_3_directive_d1=${level_3_directive_arr[level_1_index]}
                    level_3_args_d1=${level_3_args_arr[level_1_index]}

                    IFS="${delimiters[5]}" read -r -a level_3_directive_d1_arr <<< "${level_3_directive_d1}"
                    IFS="${delimiters[5]}" read -r -a level_3_args_d1_arr <<< "${level_3_args_d1}"

                    if [ -n "${level_3_directive_d1_arr[level_2_index]}" ]
                    then
                        level_3_directive_d2=${level_3_directive_d1_arr[level_2_index]}
                        level_3_args_d2=${level_3_args_d1_arr[level_2_index]}

                        IFS="${delimiters[6]}" read -r -a level_3_directive_d2_arr <<< "${level_3_directive_d2}"
                        IFS="${delimiters[6]}" read -r -a level_3_args_d2_arr <<< "${level_3_args_d2}"

                        if [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_arr[level_1_index]}" ]
                        then
                            level_4_directive_d1=${level_4_directive_arr[level_1_index]}
                            IFS="${delimiters[6]}" read -r -a level_4_directive_d1_arr <<< "${level_4_directive_d1}"
                            if [ -n "${level_4_directive_d1_arr[level_2_index]}" ] && [ -n "${level_4_directive_d1_arr[level_2_index]}" ]
                            then
                                level_4_directive_d2=${level_4_directive_d1_arr[level_2_index]}
                                IFS="${delimiters[7]}" read -r -a level_4_directive_d2_arr <<< "${level_4_directive_d2}"
                            fi
                        fi

                        for((level_3_index=0;level_3_index<${#level_3_directive_d2_arr[@]};level_3_index++));
                        do
                            level_3_option="${level_3_directive_d2_arr[level_3_index]:-''}"

                            if [ -n "${level_3_args_d2_arr[level_3_index]}" ]
                            then
                                IFS="${delimiters[7]}" read -r -a args <<< "${level_3_args_d2_arr[level_3_index]}"
                                for arg in "${args[@]}"
                                do
                                    level_3_option="$level_3_option ${arg:-''}"
                                done
                            fi

                            level_3_option=${level_3_option//\\\\/\\}

                            if [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_arr[level_1_index]}" ] && [ -n "${level_4_directive_d1_arr[level_2_index]}" ] && [ -n "${level_4_directive_d2_arr[level_3_index]}" ]
                            then
                                level_3_option="$level_3_option {...}"
                            fi

                            level_3_options+=("$level_3_option")
                        done
                    fi
                fi

                level_3_options+=("$msg_add_directive")

                if [ "${from_level_2:-0}" -eq 1 ]
                then
                    level_3_options+=("$msg_back_parent")
                else
                    level_3_options+=("$i18n_cancel")
                fi

                level_3_options_count=${#level_3_options[@]}

                while true
                do
                    echo
                    inquirer list_input_index "$msg_select_directive" level_3_options level_3_index

                    if [ "$level_3_index" -eq "$((level_3_options_count-1))" ]
                    then
                        if [ "${from_level_2:-0}" -eq 0 ]
                        then
                            Println "$i18n_canceled...\n"
                        fi
                        break
                    elif [ "$level_3_index" -eq "$((level_3_options_count-2))" ]
                    then
                        NginxAddDirective level_3
                        continue 2
                    else
                        level_3_actions=("$msg_edit_sub" "$msg_edit_directive" "$msg_delete_directive" "$msg_back_select")

                        echo
                        inquirer list_input "$i18n_select_action" level_3_actions level_3_action

                        if [ "$level_3_action" == "$msg_edit_sub" ]
                        then
                            from_level_3=1
                            NginxConfigDirective level_4
                            unset from_level_3
                        elif [ "$level_3_action" == "$msg_edit_directive" ]
                        then
                            NginxInputArgs
                            jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"args"]'
                            JQs replace parse_out "[$new_args]"
                            NginxBuildConf parse_out
                            NginxGetConfig
                            local directive_name="${level_3_directive_d2_arr[level_3_index]}"
                            Println "$(eval_gettext "\$info \$directive_name 指令修改成功")\n"
                            continue 2
                        elif [ "$level_3_action" == "$msg_delete_directive" ]
                        then
                            echo
                            inquirer list_input "$msg_confirm_delete" ny_options yn_option
                            if [ "$yn_option" == "$i18n_yes" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block"]'
                                JQs delete parse_out "$level_3_index"
                                NginxBuildConf parse_out
                                NginxGetConfig
                                local directive_name="${level_3_directive_d2_arr[level_3_index]}"
                                Println "$(eval_gettext "\$info 已删除指令 \$directive_name")\n"
                                continue 2
                            fi
                        fi
                    fi
                done
                break
            done
        ;;
        level_4)
            local msg_back_parent msg_edit_sub
            msg_back_parent=$(gettext "返回三级指令")
            msg_edit_sub=$(gettext "修改五级指令")
            while true
            do
                level_4_options=()

                if [ "$level_4_d1_count" -gt 0 ] && [ -n "${level_4_directive_arr[level_1_index]}" ]
                then
                    level_4_directive_d1=${level_4_directive_arr[level_1_index]}
                    level_4_args_d1=${level_4_args_arr[level_1_index]}

                    IFS="${delimiters[6]}" read -r -a level_4_directive_d1_arr <<< "${level_4_directive_d1}"
                    IFS="${delimiters[6]}" read -r -a level_4_args_d1_arr <<< "${level_4_args_d1}"

                    if [ -n "${level_4_directive_d1_arr[level_2_index]}" ]
                    then
                        level_4_directive_d2=${level_4_directive_d1_arr[level_2_index]}
                        level_4_args_d2=${level_4_args_d1_arr[level_2_index]}

                        IFS="${delimiters[7]}" read -r -a level_4_directive_d2_arr <<< "${level_4_directive_d2}"
                        IFS="${delimiters[7]}" read -r -a level_4_args_d2_arr <<< "${level_4_args_d2}"

                        if [ -n "${level_4_directive_d2_arr[level_3_index]}" ]
                        then
                            level_4_directive_d3=${level_4_directive_d2_arr[level_3_index]}
                            level_4_args_d3=${level_4_args_d2_arr[level_3_index]}

                            IFS="${delimiters[8]}" read -r -a level_4_directive_d3_arr <<< "${level_4_directive_d3}"
                            IFS="${delimiters[8]}" read -r -a level_4_args_d3_arr <<< "${level_4_args_d3}"

                            if [ "$level_5_d1_count" -gt 0 ] && [ -n "${level_5_directive_arr[level_1_index]}" ]
                            then
                                level_5_directive_d1=${level_5_directive_arr[level_1_index]}
                                IFS="${delimiters[7]}" read -r -a level_5_directive_d1_arr <<< "${level_5_directive_d1}"
                                if [ -n "${level_5_directive_d1_arr[level_2_index]}" ]
                                then
                                    level_5_directive_d2=${level_5_directive_d1_arr[level_2_index]}
                                    IFS="${delimiters[8]}" read -r -a level_5_directive_d2_arr <<< "${level_5_directive_d2}"
                                    if [ -n "${level_5_directive_d2_arr[level_3_index]}" ]
                                    then
                                        level_5_directive_d3=${level_5_directive_d2_arr[level_3_index]}
                                        IFS="${delimiters[9]}" read -r -a level_5_directive_d3_arr <<< "${level_5_directive_d3}"
                                    fi
                                fi
                            fi

                            for((level_4_index=0;level_4_index<${#level_4_directive_d3_arr[@]};level_4_index++));
                            do
                                level_4_option="${level_4_directive_d3_arr[level_4_index]:-''}"

                                if [ -n "${level_4_args_d3_arr[level_4_index]}" ]
                                then
                                    IFS="${delimiters[9]}" read -r -a args <<< "${level_4_args_d3_arr[level_4_index]}"
                                    for arg in "${args[@]}"
                                    do
                                        level_4_option="$level_4_option ${arg:-''}"
                                    done
                                fi

                                level_4_option=${level_4_option//\\\\/\\}

                                if [ "$level_5_d1_count" -gt 0 ] && [ -n "${level_5_directive_arr[level_1_index]}" ] && [ -n "${level_5_directive_d1_arr[level_2_index]}" ] && [ -n "${level_5_directive_d2_arr[level_3_index]}" ] && [ -n "${level_5_directive_d3_arr[level_4_index]}" ]
                                then
                                    level_4_option="$level_4_option {...}"
                                fi

                                level_4_options+=("$level_4_option")
                            done
                        fi
                    fi
                fi

                level_4_options+=("$msg_add_directive")

                if [ "${from_level_3:-0}" -eq 1 ]
                then
                    level_4_options+=("$msg_back_parent")
                else
                    level_4_options+=("$i18n_cancel")
                fi

                level_4_options_count=${#level_4_options[@]}

                while true
                do
                    echo
                    inquirer list_input_index "$msg_select_directive" level_4_options level_4_index

                    if [ "$level_4_index" -eq "$((level_4_options_count-1))" ]
                    then
                        if [ "${from_level_3:-0}" -eq 0 ]
                        then
                            Println "$i18n_canceled...\n"
                        fi
                        break
                    elif [ "$level_4_index" -eq "$((level_4_options_count-2))" ]
                    then
                        NginxAddDirective level_4
                        continue 2
                    else
                        level_4_actions=("$msg_edit_sub" "$msg_edit_directive" "$msg_delete_directive" "$msg_back_select")

                        echo
                        inquirer list_input "$i18n_select_action" level_4_actions level_4_action

                        if [ "$level_4_action" == "$msg_edit_sub" ]
                        then
                            from_level_4=1
                            NginxConfigDirective level_5
                            unset from_level_4
                        elif [ "$level_4_action" == "$msg_edit_directive" ]
                        then
                            NginxInputArgs
                            jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"block",'"$level_4_index"',"args"]'
                            JQs replace parse_out "[$new_args]"
                            NginxBuildConf parse_out
                            NginxGetConfig
                            local directive_name="${level_4_directive_d3_arr[level_4_index]}"
                            Println "$(eval_gettext "\$info \$directive_name 指令修改成功")\n"
                            continue 2
                        elif [ "$level_4_action" == "$msg_delete_directive" ]
                        then
                            echo
                            inquirer list_input "$msg_confirm_delete" ny_options yn_option
                            if [ "$yn_option" == "$i18n_yes" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"block"]'
                                JQs delete parse_out "$level_4_index"
                                NginxBuildConf parse_out
                                NginxGetConfig
                                local directive_name="${level_4_directive_d3_arr[level_4_index]}"
                                Println "$(eval_gettext "\$info 已删除指令 \$directive_name")\n"
                                continue 2
                            fi
                        fi
                    fi
                done
                break
            done
        ;;
        level_5)
            local msg_back_parent
            msg_back_parent=$(gettext "返回四级指令")
            while true
            do
                level_5_options=()

                if [ "$level_5_d1_count" -gt 0 ] && [ -n "${level_5_directive_arr[level_1_index]}" ]
                then
                    level_5_directive_d1=${level_5_directive_arr[level_1_index]}
                    level_5_args_d1=${level_5_args_arr[level_1_index]}

                    IFS="${delimiters[7]}" read -r -a level_5_directive_d1_arr <<< "${level_5_directive_d1}"
                    IFS="${delimiters[7]}" read -r -a level_5_args_d1_arr <<< "${level_5_args_d1}"

                    if [ -n "${level_5_directive_d1_arr[level_2_index]}" ]
                    then
                        level_5_directive_d2=${level_5_directive_d1_arr[level_2_index]}
                        level_5_args_d2=${level_5_args_d1_arr[level_2_index]}

                        IFS="${delimiters[8]}" read -r -a level_5_directive_d2_arr <<< "${level_5_directive_d2}"
                        IFS="${delimiters[8]}" read -r -a level_5_args_d2_arr <<< "${level_5_args_d2}"

                        if [ -n "${level_5_directive_d2_arr[level_3_index]}" ]
                        then
                            level_5_directive_d3=${level_5_directive_d2_arr[level_3_index]}
                            level_5_args_d3=${level_5_args_d2_arr[level_3_index]}

                            IFS="${delimiters[9]}" read -r -a level_5_directive_d3_arr <<< "${level_5_directive_d3}"
                            IFS="${delimiters[9]}" read -r -a level_5_args_d3_arr <<< "${level_5_args_d3}"

                            if [ -n "${level_5_directive_d3_arr[level_4_index]}" ]
                            then
                                level_5_directive_d4=${level_5_directive_d3_arr[level_4_index]}
                                level_5_args_d4=${level_5_args_d3_arr[level_4_index]}

                                IFS="${delimiters[10]}" read -r -a level_5_directive_d4_arr <<< "${level_5_directive_d4}"
                                IFS="${delimiters[10]}" read -r -a level_5_args_d4_arr <<< "${level_5_args_d4}"

                                for((level_5_index=0;level_5_index<${#level_5_directive_d4_arr[@]};level_5_index++));
                                do
                                    level_5_option="${level_5_directive_d4_arr[level_5_index]:-''}"

                                    if [ -n "${level_5_args_d4_arr[level_5_index]}" ]
                                    then
                                        IFS="${delimiters[11]}" read -r -a args <<< "${level_5_args_d4_arr[level_5_index]}"
                                        for arg in "${args[@]}"
                                        do
                                            level_5_option="$level_5_option ${arg:-''}"
                                        done
                                    fi

                                    level_5_options+=("${level_5_option//\\\\/\\}")
                                done
                            fi
                        fi
                    fi
                fi

                level_5_options+=("$msg_add_directive")

                if [ "${from_level_4:-0}" -eq 1 ]
                then
                    level_5_options+=("$msg_back_parent")
                else
                    level_5_options+=("$i18n_cancel")
                fi

                level_5_options_count=${#level_5_options[@]}

                while true
                do
                    echo
                    inquirer list_input_index "$msg_select_directive" level_5_options level_5_index

                    if [ "$level_5_index" -eq "$((level_5_options_count-1))" ]
                    then
                        if [ "${from_level_4:-0}" -eq 0 ]
                        then
                            Println "$i18n_canceled...\n"
                        fi
                        break
                    elif [ "$level_5_index" -eq "$((level_5_options_count-2))" ]
                    then
                        NginxAddDirective level_5
                        continue 2
                    else
                        level_5_actions=("$msg_edit_directive" "$msg_delete_directive" "$msg_back_select")

                        echo
                        inquirer list_input "$i18n_select_action" level_5_actions level_5_action

                        if [ "$level_5_action" == "$msg_edit_directive" ]
                        then
                            NginxInputArgs
                            jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"block",'"$level_4_index"',"block",'"$level_5_index"',"args"]'
                            JQs replace parse_out "[$new_args]"
                            NginxBuildConf parse_out
                            NginxGetConfig
                            local directive_name="${level_5_directive_d4_arr[level_5_index]}"
                            Println "$(eval_gettext "\$info \$directive_name 指令修改成功")\n"
                            continue 2
                        elif [ "$level_5_action" == "$msg_delete_directive" ]
                        then
                            echo
                            inquirer list_input "$msg_confirm_delete" ny_options yn_option
                            if [ "$yn_option" == "$i18n_yes" ]
                            then
                                jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"$level_2_index"',"block",'"$level_3_index"',"block",'"$level_4_index"',"block"]'
                                JQs delete parse_out "$level_5_index"
                                NginxBuildConf parse_out
                                NginxGetConfig
                                local directive_name="${level_5_directive_d4_arr[level_5_index]}"
                                Println "$(eval_gettext "\$info 已删除指令 \$directive_name")\n"
                                continue 2
                            fi
                        fi
                    fi
                done
                break
            done
        ;;
    esac
}
NginxConfigLocalhost()
{
    echo
    config_localhost_options=( "$(gettext "修改指令")" "$(gettext "添加 flv 设置")" "$(gettext "添加 nodejs 设置")" "$(gettext "添加 SNI 域名分流")" "$(gettext "添加 SSL 协议分流")" "$(gettext "添加 ALPN 协议分流")" "$(gettext "添加 分流后端")" "$(gettext "删除 SNI 域名分流")" "$(gettext "删除 SSL 协议分流")" "$(gettext "删除 ALPN 协议分流")" "$(gettext "删除 分流后端")" "$i18n_cancel" )
    inquirer list_input_index "$i18n_select_action" config_localhost_options config_localhost_options_index

    if [ "$config_localhost_options_index" -eq 0 ] 
    then
        NginxCheckLocalhost
        NginxConfigDirective level_1
    elif [ "$config_localhost_options_index" -eq 1 ] 
    then
        NginxListLocalhost
        NginxSelectLocalhostServer
        updated=0
        NginxAddFlv
        if [ "$updated" -eq 1 ] 
        then
            NginxBuildConf parse_out
        fi
        Println "$(eval_gettext "\$info flv 配置添加成功")\n"
    elif [ "$config_localhost_options_index" -eq 2 ] 
    then
        if [ ! -s "$NODE_ROOT/index.js" ] 
        then
            Println "$(eval_gettext "\$error 请先安装 nodejs")\n"
            exit 1
        fi
        NginxListLocalhost
        NginxSelectLocalhostServer
        updated=0
        NginxAddNodejs
        if [ "$updated" -eq 1 ] 
        then
            NginxBuildConf parse_out
        fi
        Println "$(eval_gettext "\$info nodejs 配置添加成功")\n"
    elif [ "$config_localhost_options_index" -eq 11 ]
    then
        Println "$i18n_canceled...\n"
    else
        NginxCheckLocalhost
        NginxGetStream

        if [ "$nginx_stream_server_name_count" -eq 0 ] 
        then
            echo
            inquirer list_input "$(gettext "是否启用分流")" ny_options yn_option
            if [ "$yn_option" == "$i18n_no" ] 
            then
                Println "$i18n_canceled...\n"
                exit 1
            fi
            echo
            inquirer text_input "$(gettext "输入默认分流后端地址: ")" upstream_localhost_server "127.0.0.1:8884"
        fi

        updated=0
        NginxAddStream

        if [ "$updated" -eq 1 ] 
        then
            NginxGetStream
            updated=0
        fi

        case $config_localhost_options_index in
            3) 
                Println "$(gettext "SNI 域名分流:")\n\n${nginx_stream_server_name_list:-$i18n_none}\n\n"
                ExitOnText "$(gettext "输入指令(分流域名)")" server_name_directive

                echo
                inquirer text_input "$(gettext "输入指令值(分流后端名称)")" server_name_args "$server_name_directive"

                directive_map='{"directive":"map","args":["$ssl_preread_server_name","$upstream"],"block":[]}'

                directives=( map )
                directives_val=()
                check_directives=()
                check_args=( '["$ssl_preread_server_name","$upstream"]' )

                NginxAddDirective 2

                directive_server_name='{"directive":"'"$server_name_directive"'","args":["'"$server_name_args"'"]}'

                directives=( "$server_name_directive" )
                directives_val=( server_name )
                check_directives=()
                check_args=()

                NginxAddDirective 3

                if [ "$updated" -eq 1 ] 
                then
                    NginxBuildConf parse_out
                fi
                Println "$(eval_gettext "\$info SNI 域名分流添加成功")\n"
            ;;
            4) 
                Println "$(gettext "SSL 协议分流"):\n\n${nginx_stream_protocol_list:-$i18n_none}\n"
                Println "$(eval_gettext "\$tip 空字符用 '' 表示")"
                ExitOnText "$(gettext "输入指令(分流 SSL 协议)")" protocol_directive

                if [ "$protocol_directive" == "''" ] 
                then
                    protocol_directive=""
                fi

                echo
                ExitOnText "$(gettext "输入指令值(分流后端名称)")" protocol_args

                directive_map='{"directive":"map","args":["$ssl_preread_protocol","$ssl_proxy"],"block":[]}'

                directives=( map )
                directives_val=()
                check_directives=()
                check_args=( '["$ssl_preread_protocol","$ssl_proxy"]' )

                NginxAddDirective 2

                directive_protocol='{"directive":"'"$protocol_directive"'","args":["'"$protocol_args"'"]}'

                directives=( "$protocol_directive" )
                directives_val=( protocol )
                check_directives=()
                check_args=()

                NginxAddDirective 3

                if [ "$updated" -eq 1 ] 
                then
                    NginxBuildConf parse_out
                fi
                Println "$(eval_gettext "\$info SSL 协议分流添加成功")\n"
            ;;
            5) 
                Println "$(gettext "ALPN 协议分流:")\n\n${nginx_stream_alpn_protocols_list:-$i18n_none}\n\n"
                ExitOnText "$(gettext "输入指令(分流 ALPN 协议)")" alpn_protocols_directive

                alpn_protocols_directive=${alpn_protocols_directive//\\/\\\\}

                echo
                ExitOnText "$(gettext "输入指令值(分流后端名称)")" alpn_protocols_args

                directive_map='{"directive":"map","args":["$ssl_preread_alpn_protocols","$proxy_pass"],"block":[]}'

                directives=( map )
                directives_val=()
                check_directives=()
                check_args=( '["$ssl_preread_alpn_protocols","$proxy_pass"]' )

                NginxAddDirective 2

                directive_alpn_protocols='{"directive":"'"$alpn_protocols_directive"'","args":["'"$alpn_protocols_args"'"]}'

                directives=( "$alpn_protocols_directive" )
                directives_val=( alpn_protocols )
                check_directives=()
                check_args=()

                NginxAddDirective 3

                if [ "$updated" -eq 1 ] 
                then
                    NginxBuildConf parse_out
                fi
                Println "$(eval_gettext "\$info ALPN 协议分流添加成功")\n"
            ;;
            6) 
                Println "$(gettext "分流后端"):\n\n${nginx_stream_upstream_list:-$i18n_none}\n\n"
                ExitOnText "$(gettext "输入指令(分流后端名称)")" upstream_args

                Println "$(eval_gettext "\$tip 比如: 127.0.0.1:8888")"
                ExitOnText "$(gettext "输入指令值(分流后端地址)")" upstream_server_args

                directive_upstream='{"directive":"upstream","args":["'"$upstream_args"'"],"block":[]}'

                directives=( upstream )
                directives_val=()
                check_directives=()
                check_args=( '["'"$upstream_args"'"]' )

                NginxAddDirective 2

                if [ "$updated" -eq 0 ] 
                then
                    Println "$(eval_gettext "\$error 分流后端已经存在")\n"
                    exit 1
                fi

                directive_upstream_server='{"directive":"server","args":["'"$upstream_server_args"'"]}'

                directives=( upstream_server )
                directives_val=()
                check_directives=()
                check_args=()

                NginxAddDirective 3
                NginxBuildConf parse_out

                Println "$(eval_gettext "\$info 分流后端添加成功")\n"
            ;;
            7) 
                echo
                inquirer checkbox_input_indices "$(gettext "选择删除的 SNI 域名分流: ")" nginx_stream_server_name server_name_selected

                if [ -z "${server_name_selected:-}" ] 
                then
                    Println "$i18n_canceled...\n"
                    exit 1
                fi

                directive_map='{"directive":"map","args":["$ssl_preread_server_name","$upstream"],"block":[]}'

                directives=( map )
                directives_val=()
                check_directives=()
                check_args=( '["$ssl_preread_server_name","$upstream"]' )

                NginxAddDirective 2

                for((i=0;i<${#server_name_selected[@]};i++));
                do
                    jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"${level_2_add_indices[0]}"',"block"]'
                    level_3_index=${server_name_selected[i]}
                    JQs delete parse_out $((level_3_index-i))
                    NginxGetConfig
                done

                NginxBuildConf parse_out
                Println "$(eval_gettext "\$info SNI 域名分流删除成功")\n"
            ;;
            8) 
                echo
                inquirer checkbox_input_indices "$(gettext "选择删除的 SSL 协议分流: ")" nginx_stream_protocol protocol_selected

                if [ -z "${protocol_selected:-}" ] 
                then
                    Println "$i18n_canceled...\n"
                    exit 1
                fi

                directive_map='{"directive":"map","args":["$ssl_preread_protocol","$ssl_proxy"],"block":[]}'

                directives=( map )
                directives_val=()
                check_directives=()
                check_args=( '["$ssl_preread_protocol","$ssl_proxy"]' )

                NginxAddDirective 2

                for((i=0;i<${#protocol_selected[@]};i++));
                do
                    jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"${level_2_add_indices[0]}"',"block"]'
                    level_3_index=${protocol_selected[i]}
                    JQs delete parse_out $((level_3_index-i))
                    NginxGetConfig
                done

                NginxBuildConf parse_out
                Println "$(eval_gettext "\$info SSL 协议分流删除成功")\n"
            ;;
            9) 
                echo
                inquirer checkbox_input_indices "$(gettext "选择删除的 ALPN 协议分流: ")" nginx_stream_alpn_protocols alpn_protocols_selected

                if [ -z "${alpn_protocols_selected:-}" ] 
                then
                    Println "$i18n_canceled...\n"
                    exit 1
                fi

                directive_map='{"directive":"map","args":["$ssl_preread_alpn_protocols","$proxy_pass"],"block":[]}'

                directives=( map )
                directives_val=()
                check_directives=()
                check_args=( '["$ssl_preread_alpn_protocols","$proxy_pass"]' )

                NginxAddDirective 2

                for((i=0;i<${#alpn_protocols_selected[@]};i++));
                do
                    jq_path='["config",0,"parsed",'"$level_1_index"',"block",'"${level_2_add_indices[0]}"',"block"]'
                    level_3_index=${alpn_protocols_selected[i]}
                    JQs delete parse_out $((level_3_index-i))
                    NginxGetConfig
                done

                NginxBuildConf parse_out
                Println "$(eval_gettext "\$info ALPN 协议分流删除成功")\n"
            ;;
            10) 
                echo
                inquirer checkbox_input_indices "$(gettext "选择删除的分流后端: ")" nginx_stream_upstream upstream_selected

                if [ -z "${upstream_selected:-}" ] 
                then
                    Println "$i18n_canceled...\n"
                    exit 1
                fi

                for((i=0;i<${#upstream_selected[@]};i++));
                do
                    jq_path='["config",0,"parsed",'"$level_1_index"',"block"]'
                    level_2_index=${upstream_selected[i]}
                    level_2_index=${nginx_stream_upstream_indices[level_2_index]}
                    JQs delete parse_out $((level_2_index-i))
                    NginxGetConfig
                done

                NginxBuildConf parse_out
                Println "$(eval_gettext "\$info 后端分流删除成功")\n"
            ;;
        esac
    fi
}
NginxConfigServerHttpPort()
{
    echo
    inquirer text_input "$(gettext "输入 http 端口: ")" server_http_port 80
}

NginxConfigServerHttpsPort()
{
    echo
    inquirer text_input "$(gettext "输入 https 端口: ")" server_https_port 443
}

NginxConfigServerRoot()
{
    while true 
    do
        echo
        inquirer text_input "$(gettext "设置公开的根目录")" server_root "$nginx_prefix/html"

        if [ "${server_root:0:1}" != "/" ] 
        then
            Println "$(eval_gettext "\$error 输入错误")\n"
        else
            server_root="${server_root%/}"

            mkdir -p "$server_root"
            break
        fi
    done
}

NginxConfigServerLiveRoot()
{
    while true 
    do
        echo
        inquirer text_input "$(gettext "设置公开目录下的(live目录 - HLS输出目录)位置")" server_live_root "$server_root"

        if [ "${server_live_root:0:1}" != "/" ] 
        then
            Println "$(eval_gettext "\$error 输入错误")\n"
        else
            server_live_root="${server_live_root%/}"

            mkdir -p "$server_live_root"

            if [ -d "$LIVE_ROOT" ] 
            then
                ln -sf "$LIVE_ROOT" "$server_live_root"/
            fi

            break
        fi
    done
}
NginxDomainUpdateCrt()
{
    local domain=$1 quiet=${2:-0}

    [ "$quiet" -eq 0 ] && Println "$(eval_gettext "\$info 更新 \$domain 证书...")"

    if [ "$ca_server" == "letsencrypt" ] && [ -f /etc/systemd/system/mmproxy-acme.service ] && [[ $(systemctl is-active mmproxy-acme) == "active" ]]
    then
        if [ -z "${tls_port:-}" ]
        then
            tls_port=$(grep ^ExecStart= < /etc/systemd/system/mmproxy-acme.service)
            if [[ $tls_port =~ -4\ 127.0.0.1:([^ ]+) ]]
            then
                tls_port=${BASH_REMATCH[1]}
            else
                tls_port=${tls_port#*-4 }
                tls_port=${tls_port#*:}
                tls_port=${tls_port%% *}
            fi
        fi

        ~/.acme.sh/acme.sh --force --issue --alpn --tlsport "$tls_port" -d "$domain" --standalone -k ec-256 --server "$ca_server" > /dev/null
        ~/.acme.sh/acme.sh --force --installcert -d "$domain" --fullchainpath "$nginx_prefix/conf/sites_crt/$domain.crt" --keypath "$nginx_prefix/conf/sites_crt/$domain.key" --ecc > /dev/null
    else
        stopped=0

        if [[ $(systemctl is-active $nginx_name) == "active" ]]
        then
            if [[ $(echo $SSH_CONNECTION | cut -d' ' -f3) == "127.0.0.1" ]]
            then
                Println "$(eval_gettext "\$error 请使用非 \$nginx_name 监听端口连接 ssh 后重试")\n"
                exit 1
            fi
            systemctl stop $nginx_name
            stopped=1
        fi

        sleep 1

        ~/.acme.sh/acme.sh --force --issue -d "$domain" --standalone -k ec-256 --server "$ca_server" > /dev/null
        ~/.acme.sh/acme.sh --force --installcert -d "$domain" --fullchainpath "$nginx_prefix/conf/sites_crt/$domain.crt" --keypath "$nginx_prefix/conf/sites_crt/$domain.key" --ecc > /dev/null

        [ "$stopped" -eq 1 ] && systemctl start $nginx_name
    fi

    if [ -e "$AIOS_PREFIX/share/v2ray/$domain.crt" ]
    then
        cp -f "$nginx_prefix/conf/sites_crt/$domain.crt" "$AIOS_PREFIX/share/v2ray/$domain.crt"
        cp -f "$nginx_prefix/conf/sites_crt/$domain.key" "$AIOS_PREFIX/share/v2ray/$domain.key"
    fi

    if [ -e "$AIOS_PREFIX/share/xray/$domain.crt" ]
    then
        cp -f "$nginx_prefix/conf/sites_crt/$domain.crt" "$AIOS_PREFIX/share/xray/$domain.crt"
        cp -f "$nginx_prefix/conf/sites_crt/$domain.key" "$AIOS_PREFIX/share/xray/$domain.key"
    fi

    [ "$quiet" -eq 0 ] && Println "$(eval_gettext "\$info \$domain 证书更新成功")\n"

    return 0
}

NginxDomainServerUpdateCrt()
{
    nginx_domain_server_name=${nginx_domain_servers_name[nginx_domain_servers_index]}

    if [[ $nginx_domain_server_name =~ , ]]
    then
        IFS="," read -r -a domains <<< "$nginx_domain_server_name"

        echo
        inquirer checkbox_input "$(gettext "选择域名"): " domains domains_selected

        for domain in "${domains_selected[@]}"
        do
            NginxDomainUpdateCrt "$domain"
        done

        return 0
    fi

    NginxDomainUpdateCrt "$nginx_domain_server_name"
}
NginxToggleDomain()
{
    NginxListDomains

    [ "$nginx_domains_count" -eq 0 ] && Println "$(eval_gettext "\$error 没有域名")\n" && exit 1

    echo "$i18n_input_no"
    while read -p "$i18n_default_cancel" nginx_domains_index
    do
        case "$nginx_domains_index" in
            "")
                Println "$i18n_canceled...\n" && exit 1
            ;;
            *[!0-9]*)
                Println "$error $i18n_input_correct_no\n"
            ;;
            *)
                if [ "$nginx_domains_index" -gt 0 ] && [ "$nginx_domains_index" -le "$nginx_domains_count" ]
                then
                    nginx_domains_index=$((nginx_domains_index-1))
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done

    server_domain=${nginx_domains[nginx_domains_index]}
    if [ "${nginx_domains_status[nginx_domains_index]}" -eq 1 ] 
    then
        NginxDisableDomain
        Println "$(eval_gettext "\$info \$server_domain 关闭成功")\n"
    else
        NginxEnableDomain
        Println "$(eval_gettext "\$info \$server_domain 开启成功")\n"
    fi
}
NginxDeleteDomain()
{
    NginxListDomains

    [ "$nginx_domains_count" -eq 0 ] && Println "$(eval_gettext "\$error 没有域名")\n" && exit 1

    echo "$i18n_input_no"
    while read -p "$i18n_default_cancel" nginx_domains_index
    do
        case "$nginx_domains_index" in
            "")
                Println "$i18n_canceled...\n" && exit 1
            ;;
            *[!0-9]*)
                Println "$error $i18n_input_correct_no\n"
            ;;
            *)
                if [ "$nginx_domains_index" -gt 0 ] && [ "$nginx_domains_index" -le "$nginx_domains_count" ]
                then
                    nginx_domains_index=$((nginx_domains_index-1))
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done

    server_domain=${nginx_domains[nginx_domains_index]}
    if [ "${nginx_domains_status[nginx_domains_index]}" -eq 1 ] 
    then
        NginxDisableDomain
    fi
    rm -f "$nginx_prefix/conf/sites_available/$server_domain.conf"
    Println "$(eval_gettext "\$info \$server_domain 删除成功")\n"
}
NginxLogRotate()
{
    if [ ! -d "$IPTV_ROOT" ] 
    then
        Println "$(eval_gettext "\$error 请先安装脚本 !")\n" && exit 1
    fi

    if ! ls -A $nginx_prefix/logs/*.log > /dev/null 2>&1
    then
        Println "$(eval_gettext "\$error 没有日志 !")\n" && exit 1
    fi

    if [ -d "$nginx_prefix" ] 
    then
        chown $nginx_name:root $nginx_prefix/logs/*.log
        chmod 660 $nginx_prefix/logs/*.log
    fi

    if crontab -l | grep -q "$LOGROTATE_CONFIG" 2> /dev/null
    then
        if grep -q "$nginx_prefix" < "$LOGROTATE_CONFIG"
        then
            Println "$(eval_gettext "\$error 日志切割定时任务已存在 !")\n"
        else
            logrotate='
'"$nginx_prefix"'/logs/*.log {
  daily
  missingok
  rotate 14
  compress
  delaycompress
  notifempty
  create 660 '"$nginx_name"' root
  sharedscripts
  postrotate
    [ ! -f '"$nginx_prefix"'/logs/nginx.pid ] || /bin/kill -USR1 `cat '"$nginx_prefix"'/logs/nginx.pid`
  endscript
}
'
            printf '%s\n' "$logrotate" >> "$LOGROTATE_CONFIG"
            Println "$(eval_gettext "\$error 日志切割定时任务设置成功 !")\n"
        fi
    else
        LOGROTATE_FILE=$(command -v logrotate) || LOGROTATE_FILE=""

        if [ ! -x "$LOGROTATE_FILE" ] 
        then
            Println "$(eval_gettext "\$error 请先安装 logrotate !")\n" && exit 1
        fi

        logrotate=""

        if [ -d "$nginx_prefix" ] 
        then
            logrotate='
'"$nginx_prefix"'/logs/*.log {
  daily
  missingok
  rotate 14
  compress
  delaycompress
  notifempty
  create 660 '"$nginx_name"' root
  sharedscripts
  postrotate
    [ ! -f '"$nginx_prefix"'/logs/nginx.pid ] || /bin/kill -USR1 `cat '"$nginx_prefix"'/logs/nginx.pid`
  endscript
}
'
        fi

        logrotate="$logrotate
$IPTV_ROOT/*.log {
  monthly
  missingok
  rotate 3
  compress
  nodelaycompress
  notifempty
  sharedscripts
}
"
        printf '%s' "$logrotate" > "$LOGROTATE_CONFIG"

        crontab -l > "$IPTV_ROOT/cron_tmp" 2> /dev/null || true
        printf '%s\n' "0 0 * * * $LOGROTATE_FILE $LOGROTATE_CONFIG" >> "$IPTV_ROOT/cron_tmp"
        crontab "$IPTV_ROOT/cron_tmp" > /dev/null
        rm -f "$IPTV_ROOT/cron_tmp"
        Println "$(eval_gettext "\$info 日志切割定时任务开启成功 !")\n"
    fi
}
NginxUpdateIp()
{
    if [ ! -f $nginx_prefix/conf/nginx.conf ] 
    then
        Println "$(eval_gettext "\$error 请先安装 \$nginx_name")\n"
        exit 1
    fi

    if ! grep -q "include cloudflare_ip.conf;" < $nginx_prefix/conf/nginx.conf
    then
        sed -i '/http {/a\    include cloudflare_ip.conf;' $nginx_prefix/conf/nginx.conf
    else
        Println "$(eval_gettext "\$error \$nginx_name 配置已经存在")\n"
    fi

    Println "$(eval_gettext "\$info 更新 ip ...")"

cat > "$HOME"/update_cf_ibm_ip.sh <<EOF
#!/bin/bash
echo -e 'set_real_ip_from 127.0.0.0/24;\n#Cloudflare' > $nginx_prefix/conf/cloudflare_ip.conf;
ibm_ips=(
  50.22.0.0/16
  50.23.0.0/16
  66.228.118.0/23
  67.228.66.0/24
  75.126.0.0/16
  108.168.157.0/24
  173.192.0.0/16
  174.35.17.0/24
  184.172.0.0/16
  192.255.0.0/16
  198.23.0.0/16
  208.43.15.0/24
  169.45.0.0/16
  169.46.0.0/16
  169.47.0.0/16
  169.48.0.0/16
  169.61.0.0/16
  169.62.0.0/16
)
for i in "\${ibm_ips[@]}"; do
        echo "set_real_ip_from \$i;" >> $nginx_prefix/conf/cloudflare_ip.conf;
done
for i in \$(curl https://www.cloudflare.com/ips-v4); do
        echo "set_real_ip_from \$i;" >> $nginx_prefix/conf/cloudflare_ip.conf;
done
for i in \$(curl https://www.cloudflare.com/ips-v6); do
        echo "set_real_ip_from \$i;" >> $nginx_prefix/conf/cloudflare_ip.conf;
done
echo >> $nginx_prefix/conf/cloudflare_ip.conf;
echo '# use any of the following two' >> $nginx_prefix/conf/cloudflare_ip.conf;
echo 'real_ip_header CF-Connecting-IP;' >> $nginx_prefix/conf/cloudflare_ip.conf;
echo '#real_ip_header X-Forwarded-For;' >> $nginx_prefix/conf/cloudflare_ip.conf;
EOF

    bash ~/update_cf_ibm_ip.sh

    Println "$(eval_gettext "\$info IP 更新成功")\n"
}
NginxEnableDomain()
{
    ln -sf "$nginx_prefix/conf/sites_available/$server_domain.conf" "$nginx_prefix/conf/sites_enabled/$server_domain.conf"
    NginxRestart
}
NginxDisableDomain()
{
    rm -f "$nginx_prefix/conf/sites_enabled/$server_domain.conf"
    NginxRestart
}
NginxAppendHttpConf()
{
cat >> "$nginx_prefix/conf/sites_available/$server_domain.conf" <<EOF
    server {
        listen      $server_http_port;
        server_name $server_domain;

        access_log logs/access.log;

        add_header Access-Control-Allow-Origin \$cors_host;
        add_header Vary Origin;
        add_header X-Frame-Options SAMEORIGIN;
        add_header Access-Control-Allow-Credentials true;
        add_header Cache-Control no-cache;

        location / {${deny_aliyun:-}
            root   ${server_root#*$nginx_prefix/};
            index  index.html index.htm;
        }
    }

EOF
}

NginxAppendHttpRedirectConf()
{
    echo && read -p "$(gettext "输入网址: ")" http_redirect_address
cat >> "$nginx_prefix/conf/sites_available/$server_domain.conf" <<EOF
    server {
        listen      $server_http_port;
        server_name $server_domain;

        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header Connection "";

        location / {
            return 301 $http_redirect_address\$request_uri;
        }
    }

EOF
}

NginxAppendHttpRedirectToHttpsConf()
{
cat >> "$nginx_prefix/conf/sites_available/$server_domain.conf" <<EOF
    server {
        listen      $server_http_port;
        server_name $server_domain;

        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header Connection "";

        location / {
            return 301 https://\$server_domain\$request_uri;
        }
    }

EOF
}

NginxAppendHttpsConf()
{
cat >> "$nginx_prefix/conf/sites_available/$server_domain.conf" <<EOF
    server {
        listen      $server_https_port ssl;
        server_name $server_domain;

        access_log logs/access.log;

        ssl_certificate      $nginx_prefix/conf/sites_crt/$server_domain.crt;
        ssl_certificate_key  $nginx_prefix/conf/sites_crt/$server_domain.key;

        add_header Access-Control-Allow-Origin \$cors_host;
        add_header Vary Origin;
        add_header X-Frame-Options SAMEORIGIN;
        add_header Access-Control-Allow-Credentials true;
        add_header Cache-Control no-cache;

        location / {${deny_aliyun:-}
            root   ${server_root#*$nginx_prefix/};
            index  index.html index.htm;
        }
    }

EOF
}

NginxAppendHttpsRedirectConf()
{
    echo && read -p "$(gettext "输入网址: ")" https_redirect_address
cat >> "$nginx_prefix/conf/sites_available/$server_domain.conf" <<EOF
    server {
        listen      $server_https_port ssl;
        server_name $server_domain;

        access_log off;

        ssl_certificate      $nginx_prefix/conf/sites_crt/$server_domain.crt;
        ssl_certificate_key  $nginx_prefix/conf/sites_crt/$server_domain.key;

        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header Connection "";

        location / {
            return 301 $https_redirect_address\$request_uri;
        }
    }

EOF
}

