NginxAddDomain()
{
    NginxListDomains

    Println "$(eval_gettext "\$tip 多个域名用空格分隔")"
    ExitOnText "$(gettext "输入指向本机的IP或域名")" domains

    NginxCheckLocalhost
    NginxAddHttp

    new_domains=( $domains )
    domain_options=( http 'http => https' 'http + https' )

    for server_domain in "${new_domains[@]}"
    do
        if [ -e "$nginx_prefix/conf/sites_available/$server_domain.conf" ] 
        then
            Println "$(eval_gettext "\$error \$server_domain 已存在")"
            continue
        fi

        if [[ $server_domain =~ ^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$ ]] || [[ ! $server_domain =~ ^([a-zA-Z0-9](([a-zA-Z0-9-]){0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$ ]]
        then
            domain_options_index=0
        else
            echo
            inquirer list_input_index "$(eval_gettext "选择网站 \$server_domain 类型")" domain_options domain_options_index
        fi

        case $domain_options_index in
            0) 
                NginxConfigServerHttpPort
                echo
                inquirer list_input "$(gettext "是否设置跳转到其他网址")" ny_options http_redirect_yn

                if [ "$http_redirect_yn" == "$i18n_yes" ] 
                then
                    NginxAppendHttpRedirectConf
                else
                    NginxConfigServerRoot
                    NginxConfigServerLiveRoot
                    NginxAppendHttpConf
                fi

                updated=0
                NginxAddCorsHost
                [ "$updated" -eq 1 ] && NginxBuildConf parse_out

                NginxEnableDomain
                Println "$(eval_gettext "\$info \$server_domain 配置成功")\n"
            ;;
            1) 
                NginxSitesCrtInstall "$server_domain"
                inquirer list_input "$(gettext "是否设置 http 跳转 https")" yn_options http_to_https_yn

                if [ "$http_to_https_yn" == "$i18n_yes" ] 
                then
                    Println "$(eval_gettext "\$info 设置 \$server_domain http 配置")"
                    NginxConfigServerHttpPort
                    NginxAppendHttpRedirectToHttpsConf
                fi

                NginxConfigServerHttpsPort
                echo
                inquirer list_input "$(gettext "是否设置 https 跳转到其他网址")" ny_options https_redirect_yn

                if [ "$https_redirect_yn" == "$i18n_yes" ] 
                then
                    NginxAppendHttpsRedirectConf
                else
                    NginxConfigServerRoot
                    NginxConfigServerLiveRoot
                    NginxAppendHttpsConf
                fi

                updated=0
                NginxAddCorsHost
                [ "$updated" -eq 1 ] && NginxBuildConf parse_out

                NginxEnableDomain
                Println "$(eval_gettext "\$info \$server_domain 配置成功")\n"
            ;;
            2) 
                NginxSitesCrtInstall "$server_domain"
                inquirer list_input "$(gettext "http 和 https 是否使用相同的目录")" yn_options http_https_same_dir_yn

                if [ "$http_https_same_dir_yn" == "$i18n_yes" ] 
                then
                    NginxConfigServerHttpPort
                    NginxConfigServerHttpsPort
                    echo
                    inquirer list_input "$(gettext "是否设置跳转到其他网址")" ny_options http_https_redirect_yn
                    if [ "$http_https_redirect_yn" == "$i18n_yes" ] 
                    then
                        NginxAppendHttpHttpsRedirectConf
                    else
                        NginxConfigServerRoot
                        NginxConfigServerLiveRoot
                        NginxAppendHttpHttpsConf
                    fi
                else
                    NginxConfigServerHttpPort
                    echo
                    inquirer list_input "$(gettext "是否设置 http 跳转到其他网址")" ny_options http_redirect_yn
                    if [ "$http_redirect_yn" == "$i18n_yes" ] 
                    then
                        NginxAppendHttpRedirectConf
                        NginxConfigServerHttpsPort

                        echo
                        inquirer list_input "$(gettext "是否设置 https 跳转到其他网址")" yn_options https_redirect_yn

                        if [ "$https_redirect_yn" == "$i18n_yes" ] 
                        then
                            NginxAppendHttpsRedirectConf
                        else
                            NginxConfigServerRoot
                            NginxConfigServerLiveRoot
                            NginxAppendHttpsConf
                        fi
                    else
                        NginxConfigServerRoot
                        NginxConfigServerLiveRoot

                        server_http_root="$server_root"
                        server_http_live_root="$server_live_root"
                        server_http_deny="$deny_aliyun"

                        NginxConfigServerHttpsPort

                        echo
                        inquirer list_input "$(gettext "是否设置 https 跳转到其他网址")" yn_options https_redirect_yn

                        if [ "$https_redirect_yn" == "$i18n_yes" ] 
                        then
                            NginxAppendHttpConf
                            NginxAppendHttpsRedirectConf
                        else
                            server_root=""
                            server_live_root=""
                            deny_aliyun=""
                            NginxConfigServerRoot
                            NginxConfigServerLiveRoot

                            server_https_root="$server_root"
                            server_https_live_root="$server_live_root"
                            server_https_deny="$deny_aliyun"

                            if [ "$server_http_root" == "$server_https_root" ] && [ "$server_http_live_root" == "$server_https_live_root" ] && [ "$server_http_deny" == "$server_https_deny" ]
                            then
                                NginxAppendHttpHttpsConf
                            else
                                NginxAppendHttpConf
                                NginxAppendHttpsConf
                            fi
                        fi
                    fi
                fi

                updated=0
                NginxAddCorsHost
                [ "$updated" -eq 1 ] && NginxBuildConf parse_out

                NginxEnableDomain
                Println "$(eval_gettext "\$info \$server_domain 配置成功")\n"
            ;;
        esac
    done
}
NodejsConfig()
{
    echo
    nodejs_options=( "$i18n_domain" "$(gettext "本地")" )
    inquirer list_input "$(gettext "选择使用 nodejs 的对象")" nodejs_options nodejs_option

    if [ "$nodejs_option" == "$i18n_domain" ] 
    then
        NginxListDomain
        NginxSelectDomainServer

        server_name=${nginx_domain_servers_name[nginx_domain_servers_index]}

        if [[ $server_name =~ , ]] 
        then
            IFS="," read -r -a domains <<< "$server_name"

            echo
            inquirer list_input "$(gettext "选择域名"): " domains server_name
        fi
    else
        NginxListLocalhost
        NginxSelectLocalhostServer
    fi

    NginxConfigServerLiveRoot

    updated=0

    NginxAddFlv

    NginxAddNodejs

    if [ "$updated" -eq 1 ] 
    then
        NginxBuildConf parse_out
        Println "$(eval_gettext "\$info nodejs 配置添加成功")"
    fi

    if [ "$nodejs_option" == "$i18n_domain" ] 
    then
        NginxCheckLocalhost
        NginxAddHttp
    fi

    updated=0

    NginxAddCorsHost

    NginxAddSameSiteNone

    nodejs_port=$(GetFreePort)

    NginxAddUpstreamNodejs

    if [ "$updated" -eq 1 ] 
    then
        NginxBuildConf parse_out
    fi

    username=$(RandStr)
    password=$(RandStr)

    mongosh admin --eval "db.getSiblingDB('admin').createUser({user: '${username}', pwd: '${password}', roles: ['root']})"

    if [[ $(ps --no-headers -o comm 1) == "systemd" ]] 
    then
        systemctl restart mongod
    else
        service mongod restart
    fi

    mkdir -p "$NODE_ROOT"

    cat > "$NODE_ROOT/index.js" <<EOF
const express = require('express');
const session = require('express-session');
const MongoStore = require('connect-mongo');
const mongoose = require('mongoose');
const path = require('path');

const app = express();
const port = $nodejs_port;

const clientP = mongoose.connect(
    'mongodb://$username:$password@127.0.0.1/admin',
    { useNewUrlParser: true, useUnifiedTopology: true }
).then(m => m.connection.getClient())

app.set('trust proxy', 1);
app.use(session({
    name: '$(RandStr)',
    secret: '$(RandStr)',
    resave: false,
    saveUninitialized: false,
    store: MongoStore.create({
        clientPromise: clientP,
        dbName: 'encrypt',
        stringify: false,
        collectionName: 'sessions',
        autoRemove: 'interval',
        autoRemoveInterval: 120
    }),
    cookie: {
        domain: 'localhost',
        maxAge: 60 * 60 * 2000,
        httpOnly: true
    }
}));

app.get('/keys', (req, res) => {
    const { key, channel } = req.query;
    if (!req.session.websiteUser || !key || !channel){
        res.status(400).end();
    } esle {
        res.sendFile(channel + '/' + key + '.key', {root: path.join(__dirname, '../${LIVE_ROOT##*/}')});
    }
});

app.get('/', (req, res) => {
    req.session.websiteUser = true;
    res.sendFile('$server_root/index.html');
});

app.get('/remote', (req, res) => {
    req.session.websiteUser = true;
    res.sendFile('$server_root/channels.json');
});

app.get('/channels', (req, res) => {
    if (!req.session.websiteUser){
        res.status(403).end();
    } else {
        res.sendFile('$server_root/channels.json');
    }
});

app.listen(port, () => console.log(\`App listening on port \${port}!\`))

EOF

    cat > "$NODE_ROOT/package.json" <<EOF
{
  "name": "node",
  "version": "1.0.0",
  "description": "",
  "main": "index.js",
  "scripts": {
    "test": "echo \"Error: no test specified\" && exit 1",
    "start": "node index.js"
  },
  "author": "",
  "license": "ISC",
  "dependencies": {
    "express": "^4.17.1",
    "express-session": "^1.17.0",
    "mongodb": "^4.1.2",
    "connect-mongo": "^4.6.0",
    "mongoose": "^6.0.8",
    "path": "^0.12.7"
  }
}
EOF

    GitInstall

    cd "$NODE_ROOT"
    npm install
    npm install -g pm2
    pm2 start "$NODE_ROOT/index.js"
    pm2 startup
    Println "$(eval_gettext "\$info nodejs 配置完成")"
}
NodejsMenu()
{
    [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 请先输入 tv 安装 !")\n" && exit 1

    echo
    nodejs_options=( "$i18n_install" "$(gettext "升级")" "$(gettext "运行 iptv node")" )
    inquirer list_input_index "$i18n_select_action" nodejs_options nodejs_options_index

    if [ "$nodejs_options_index" -eq 0 ] 
    then
        if [[ -x $(command -v node) ]] && [[ -x $(command -v npm) ]] 
        then
            Println "$(eval_gettext "\$error nodejs 已存在")\n"
            exit 1
        fi

        NodejsInstall
    elif [ "$nodejs_options_index" -eq 1 ] 
    then
        if [[ ! -x $(command -v node) ]] || [[ ! -x $(command -v npm) ]] 
        then
            Println "$(eval_gettext "\$error 请先安装 nodejs")\n"
            exit 1
        fi

        NodejsInstall
    else
        if [ -f "$NODE_ROOT/index.js" ] 
        then
            Println "$(eval_gettext "\$error iptv node 已存在")\n"
            exit 1
        fi

        if [[ ! -x $(command -v node) ]] || [[ ! -x $(command -v npm) ]] 
        then
            Println "$(eval_gettext "\$error 请先安装 nodejs")\n"
            exit 1
        fi

        if [[ ! -x $(command -v mongod) ]] 
        then
            Println "$(eval_gettext "\$error 请先安装 mongodb")\n"
            exit 1
        fi

        NodejsConfig
    fi
}
MongodbMenu()
{
    echo
    mongodb_options=( "$i18n_view" "$i18n_install" "$(gettext "升级")" )
    inquirer list_input_index "$i18n_select_action" mongodb_options mongodb_options_index

    if [ "$mongodb_options_index" -eq 0 ] 
    then
        if [[ ! -x $(command -v mongod) ]] 
        then
            Println "$(eval_gettext "\$error 请先安装 mongodb")\n"
            return 1
        fi

        systemctl --no-pager -l status mongod
    elif [ "$mongodb_options_index" -eq 1 ] 
    then
        if [[ -x $(command -v mongod) ]]
        then
            Println "$(eval_gettext "\$error mongodb 已存在")\n"
            return 1
        fi

        MongodbInstall
    else
        if [[ ! -x $(command -v mongod) ]] 
        then
            Println "$(eval_gettext "\$error 请先安装 mongodb")\n"
            return 1
        fi

        echo
        ExitOnList n "$(gettext "升级会清除现有 mongodb 配置, 是否继续")"

        service mongod stop

        if [ "$dist" == "rpm" ] 
        then
            yum -y erase mongodb-org*

            rm -f /etc/yum.repos.d/mongodb-org-*.repo
        else
            apt-get -y --purge remove mongodb-org*
            apt-get -y autoremove

            rm -f /etc/apt/sources.list.d/mongodb-org-*.list
        fi

        MongodbInstall
    fi
}
NginxSitesCrtInstall()
{
    local domain=$1

    if [ -e "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.crt" ] && [ -d "$AIOS_PREFIX"/openresty/nginx/conf ] && [ ! -e "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.crt" ]
    then
        mkdir -p "$AIOS_PREFIX"/openresty/nginx/conf/sites_crt
        ln "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.crt" "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.crt"
        ln "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.key" "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.key"
    elif [ -e "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.crt" ] && [ -d "$AIOS_PREFIX"/nginx/conf ] && [ ! -e "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.crt" ] 
    then
        mkdir -p "$AIOS_PREFIX"/nginx/conf/sites_crt
        ln "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.crt" "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.crt"
        ln "$AIOS_PREFIX/openresty/nginx/conf/sites_crt/$domain.key" "$AIOS_PREFIX/nginx/conf/sites_crt/$domain.key"
    fi

    if [ -e "$nginx_prefix/conf/sites_crt/$domain.crt" ] && [ -e "$nginx_prefix/conf/sites_crt/$domain.key" ]
    then
        echo
        inquirer list_input "$(gettext "检测到证书已存在, 是否重新安装证书")" ny_options reinstall_crt_yn
        if [ "$reinstall_crt_yn" == "$i18n_no" ] 
        then
            return 0
        fi
    fi

    AcmeCheck

    Println "$(eval_gettext "\$info 安装 \$domain 证书...")"

    NginxDomainUpdateCrt "$domain" 1

    Println "$(eval_gettext "\$info \$domain 证书安装成功")\n"
}

NginxSitesCrtSelfSignValid()
{
    local domain=$1

    if [ -e "$cert_root/$domain".crt ] && [ -e "$cert_root/$domain".key ]
    then
        return 1
    fi
}

NginxSitesCrtManage()
{
    if [ ! -d "$nginx_prefix"/conf/sites_crt ] 
    then
        Println "$(eval_gettext "\$error 请先安装 \$nginx_name")\n"
        return 1
    fi

    echo
    crt_options=( "$(gettext "浏览证书")" "$(gettext "安装自签名证书")" "$(gettext "安装ACME证书")" )
    inquirer list_input_index "$i18n_select_action" crt_options crt_options_index

    case $crt_options_index in
        0) ServiceBrowse "$nginx_prefix"/conf/sites_crt
        ;;
        1) 
            cd "$nginx_prefix"/conf/sites_crt

            if [ ! -f "$nginx_prefix"/conf/sites_crt/openssl.cnf ] 
            then
                if ! curl -Lm 20 -o "$nginx_prefix"/conf/sites_crt/openssl.cnf "$FFMPEG_MIRROR_LINK"/openssl.cnf 
                then
                    Println "$(eval_gettext "\$error 下载 openssl.cnf 失败, 请稍后再试")\n"
                    return 1
                fi
            fi

            if [ ! -f "$nginx_prefix"/conf/sites_crt/root.crt ] 
            then
                echo
                inquirer text_input "$(gettext "请输入你想设置的根证书公用名CN (Common Name)")" root_cn root.yourdomain.com
                openssl req -new -nodes -text -out root.csr -newkey rsa:4096 -keyout root.key -subj "/CN=$root_cn"
                chmod og-rwx root.key
                openssl x509 -req -in root.csr -text -days 3650 -extfile "$nginx_prefix"/conf/sites_crt/openssl.cnf -extensions v3_ca -signkey root.key -out root.crt
                Println "$(eval_gettext "\$info \$nginx_prefix/conf/root.crt 可以添加到用户端系统用来验证之后自签名的证书")\n"
            fi

            cert_root="$nginx_prefix"/conf/sites_crt

            mkdir -p newcerts

            echo
            inquirer text_input "$(gettext "请输入自签名证书公用名CN (Common Name)")" server_cn localhost NginxSitesCrtSelfSignValid "$(gettext "证书已存在")"

            ny_index=0

            if ! [[ "$server_cn" =~ \* ]] 
            then
                echo
                inquirer list_input_index "$(eval_gettext "是否将子域名 *.\$server_cn 加到 SAN")" ny_options ny_index
            fi

            if [ "$ny_index" -eq 1 ] 
            then
                root_domain="${server_cn#\*.}"
                san="DNS:$root_domain,DNS:*.$root_domain,IP:127.0.0.1,IP:::1"
            else
                san="DNS:$server_cn,IP:127.0.0.1,IP:::1"
            fi

            openssl req -new -nodes -text -out "$cert_root/${server_cn}".csr -newkey rsa:4096 -keyout "$cert_root/${server_cn}".key -subj "/CN=$server_cn" -addext "subjectAltName=$san"

            chmod og-rwx "$cert_root/${server_cn}".key

            if openssl help x509 2>&1 | grep -q "copy_extensions"
            then
                openssl_cmds=(openssl x509 -req -copy_extensions copy -in "$cert_root/${server_cn}".csr -text -days 365 -CA root.crt -CAkey root.key -CAcreateserial -out "$cert_root/${server_cn}".crt)
            else
                openssl_cmds=(openssl ca -batch -config "$nginx_prefix"/conf/sites_crt/openssl.cnf -policy signing_policy -extensions signing_req -out "$cert_root/${server_cn}".crt -infiles "$cert_root/${server_cn}".csr)
            fi

            if [ ! -f ./index.txt ] 
            then
                touch index.txt
            fi

            if [ ! -f ./serial ] 
            then
                echo 01 > serial
            fi

            "${openssl_cmds[@]}"

            openssl x509 -in "$cert_root/${server_cn}".crt -outform PEM -out "$cert_root/${server_cn}".pem

            if [ "$ny_index" -eq 1 ] 
            then
                openssl req -new -nodes -text -out "$cert_root/*.${server_cn}".csr -newkey rsa:4096 -keyout "$cert_root/*.${server_cn}".key -subj "/CN=*.$server_cn" -addext "subjectAltName=$san"
                chmod og-rwx '*'.${server_cn}.key
                if openssl help x509 2>&1 | grep -q "copy_extensions"
                then
                    openssl_cmds=(openssl x509 -req -copy_extensions copy -in "$cert_root/*.${server_cn}".csr -text -days 365 -CA ../root.crt -CAkey ../root.key -CAcreateserial -out "$cert_root/*.${server_cn}".crt)
                else
                    openssl_cmds=(openssl ca -batch -config "$nginx_prefix"/conf/sites_crt/openssl.cnf -policy signing_policy -extensions signing_req -out "$cert_root/*.${server_cn}".crt -infiles "$cert_root/*.${server_cn}".csr)
                fi
                "${openssl_cmds[@]}"
                openssl x509 -in "$cert_root/*.${server_cn}".crt -outform PEM -out "$cert_root/*.${server_cn}".pem
                cat "$cert_root/${server_cn}".pem "$cert_root/*.${server_cn}".pem > "$cert_root/${server_cn}".pem.tmp
                mv "$cert_root/${server_cn}".pem.tmp "$cert_root/${server_cn}".pem
            fi

            Println "$(eval_gettext "\$info 自签名证书安装成功")\n"
        ;;
        2) NginxConfigDomain
        ;;
    esac

    return 0
}
OpenrestyPackageInstall()
{
    # nc -vz 127.0.0.1 80
    DepInstall lsof
    if lsof -Pi :80 -sTCP:LISTEN -t &>/dev/null
    then
        Println "$(eval_gettext "\$error 80 端口被占用, 请先关闭占用端口的程序")\n"
        return 1
    fi

    DepInstall curl
    DepInstall ca-certificates

    ArchCheck

    if [ "$arch" == "arm64" ]
    then
        arch_path="/arm64"
    else
        arch_path=""
    fi

    . /etc/os-release

    case $dist in
        ubu)
            local or_codename or_repo_base or_key_url
            or_codename=$(AptGetCodename)

            if [ ! -f /etc/apt/sources.list.d/openresty.list ]
            then
                if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                then
                    or_repo_base="https://${USTC_MIRROR_HOST}/openresty${arch_path}/ubuntu"
                    or_key_url="https://${USTC_MIRROR_HOST}/openresty/pubkey.gpg"
                else
                    or_repo_base="${OPENRESTY_LINK}/package${arch_path}/ubuntu"
                    or_key_url="${OPENRESTY_LINK}/package/pubkey.gpg"
                fi

                if ! AptRepoCheck "$or_repo_base" "$or_codename"
                then
                    local or_codename_display="${or_codename:-unknown}"
                    Println "$(eval_gettext "\$error OpenResty 官方源暂不支持当前系统 (\$or_codename_display), 未写入失效源")\n"
                    return 1
                fi

                DepInstall ubuntu-keyring
                DepInstall gpg
                curl -fsSL "$or_key_url" | gpg --batch --yes --dearmor -o /usr/share/keyrings/openresty.gpg
                echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/openresty.gpg] ${or_repo_base} \
                ${or_codename} main" | tee /etc/apt/sources.list.d/openresty.list
                AptUpdate force
            fi

            AptInstall openresty --no-install-recommends
        ;;
        deb)
            local or_codename or_repo_base or_key_url
            or_codename=$(AptGetCodename)

            if [ ! -f /etc/apt/sources.list.d/openresty.list ]
            then
                if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                then
                    or_repo_base="https://${USTC_MIRROR_HOST}/openresty${arch_path}/debian"
                    or_key_url="https://${USTC_MIRROR_HOST}/openresty/pubkey.gpg"
                else
                    or_repo_base="${OPENRESTY_LINK}/package${arch_path}/debian"
                    or_key_url="${OPENRESTY_LINK}/package/pubkey.gpg"
                fi

                if ! AptRepoCheck "$or_repo_base" "$or_codename"
                then
                    local or_codename_display="${or_codename:-unknown}"
                    Println "$(eval_gettext "\$error OpenResty 官方源暂不支持当前系统 (\$or_codename_display), 未写入失效源")\n"
                    return 1
                fi

                DepInstall debian-archive-keyring
                DepInstall gpg
                curl -fsSL "$or_key_url" | gpg --batch --yes --dearmor -o /usr/share/keyrings/openresty.gpg
                echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/openresty.gpg] ${or_repo_base} \
                ${or_codename} openresty" | sudo tee /etc/apt/sources.list.d/openresty.list
                AptUpdate force
            fi

            AptInstall openresty --no-install-recommends
        ;;
        rpm)
            DepInstall yum-utils

            if [ ! -f /etc/yum.repos.d/openresty.repo ]
            then
                dist_names=( amazon alinux tlinux oracle rocky fedora centos rhel )

                for dist_name in "${dist_names[@]}"
                do
                    if grep -qi "$dist_name" <<< "$ID" || grep -qi "$dist_name" <<< "$NAME"
                    then
                        case $dist_name in
                            amazon|alinux|tlinux|oracle|fedora)
                                curl -s -L https://openresty.org/package/$dist_name/openresty.repo -o /etc/yum.repos.d/openresty.repo
                            ;;
                            rocky|centos|rhel)
                                if [ "${VERSION_ID%%.*}" -gt 8 ]
                                then
                                    curl -s -L https://openresty.org/package/$dist_name/openresty2.repo -o /etc/yum.repos.d/openresty.repo
                                else
                                    curl -s -L https://openresty.org/package/$dist_name/openresty.repo -o /etc/yum.repos.d/openresty.repo
                                fi
                            ;;
                        esac
                        break
                    fi
                done
            fi
            sudo yum check-update
            sudo yum install -y openresty openresty-opm openresty-doc
        ;;
        *)
            Println "$(eval_gettext "\$error 不支持的系统")\n"
            return 1
        ;;
    esac

    if ! grep -q "$nginx_name:" < "/etc/passwd"
    then
        if grep -q '\--group ' < <(adduser --help)
        then
            adduser "$nginx_name" --system --group --no-create-home > /dev/null
        else
            adduser "$nginx_name" --system --no-create-home > /dev/null
        fi
        usermod -s /usr/sbin/nologin "$nginx_name"
    fi

    sed -i "s/#user  nobody;/user $nginx_name $nginx_name;/" "$nginx_prefix/conf/nginx.conf"
    sed -i "s/worker_connections  1024;/worker_connections  51200;/" "$nginx_prefix/conf/nginx.conf"

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"
    mkdir -p "$nginx_prefix/html/localhost/"

    CrossplaneInstall

    Println "$(eval_gettext "\$info \$nginx_name 安装成功")\n"
}

OpenrestySourceInstall()
{
    local install="$i18n_update"

    if [ -z "${1:-}" ]
    then
        if [[ -x $(command -v $nginx_name) ]]
        then
            return 0
        fi
        install="$i18n_install"
    elif [[ ! -x $(command -v $nginx_name) ]]
    then
        install="$i18n_install"
    fi

    DepsCheck

    echo
    pcre_options=( pcre pcre2 )
    inquirer list_input_index "$(gettext "选择 pcre 版本")" pcre_options pcre_options_index

    Println "$(eval_gettext "\$tip 如果选择 openssl, \$nginx_name 将不支持 ssl_early_data (0-RTT)")"
    openssl_options=( openssl@1.1 quictls )
    inquirer list_input_index "$(gettext "选择 openssl 版本")" openssl_options openssl_options_index

    echo
    inquirer list_input_index "$(gettext "额外添加编译选项")" ny_options ny_index
    install_options_selected=()
    if [ "$ny_index" -eq 1 ]
    then
        echo
        install_options=( --with-http_iconv_module --with-http_postgres_module --with-http_slice_module )
        inquirer checkbox_input "$(gettext "选择编译选项")" install_options install_options_selected
    fi

    if [ "$dist" == "mac" ]
    then
        Println "$(eval_gettext "\$tip 如果选择官方编译, \$nginx_name 将缺少 nginx-http-flv-module 和 quictls 选择")"
        inquirer list_input_index "$(gettext "使用官方编译")" yn_options yn_index
        if [ "$yn_index" -eq 0 ]
        then
            brew tap openresty/brew
            brew install openresty ${install_options_selected[@]+"${install_options_selected[@]}"}
            if [ ! -d "$nginx_prefix" ]
            then
                Println "$(eval_gettext "\$info 建立目录 \$nginx_prefix, 可能需要输入密码")\n"
                sudo mkdir -p "$nginx_prefix"/html/localhost/
                sudo chown "$USER" "$nginx_prefix"
                ln -s "$HOMEBREW_PREFIX"/etc/openresty "$nginx_prefix"/conf
                ln -s "$HOMEBREW_PREFIX"/var/log/nginx "$nginx_prefix"/logs
            fi
            return
        fi
        if [ ! -d "$nginx_prefix" ]
        then
            Println "$(eval_gettext "\$info 建立目录 \$nginx_prefix, 可能需要输入密码")\n"
            sudo mkdir "$nginx_prefix"
            sudo chown $USER "$nginx_prefix"
            sudo chown $USER "${nginx_prefix%/*}"
            if [ ! -f /etc/paths.d/openresty ]
            then
                sudo mkdir -p /etc/paths.d
                echo "$HOMEBREW_PREFIX"/openresty/bin | sudo tee /etc/paths.d/openresty
            fi
        fi
    fi

    mkdir -p "$DEPENDS_ROOT"
    cd "$DEPENDS_ROOT"

    rm -rf nginx-http-flv-module-master
    curl -L "$FFMPEG_MIRROR_LINK/nginx-http-flv-module.zip" -o nginx-http-flv-module.zip
    Println "$(eval_gettext "\$info 解压 nginx-http-flv-module ...")"
    unzip nginx-http-flv-module.zip >/dev/null 2>&1

    #cd nginx-http-flv-module-master
    #curl -L "$FFMPEG_MIRROR_LINK/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch" -o Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch
    #patch -p1 < Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch
    #cd "$DEPENDS_ROOT"

    latest_release=0
    while IFS= read -r line
    do
        if [[ $line == *"Lastest release"* ]]
        then
            latest_release=1
        elif [ "$latest_release" -eq 1 ] && [[ $line == *"<a "* ]]
        then
            openresty_package_name=${line#*/download/}
            openresty_package_name=${openresty_package_name%%.tar.gz*}
            break
        fi
    done < <(curl -s -L -H "User-Agent: $USER_AGENT_BROWSER" https://openresty.org/en/download.html 2> /dev/null)

    curl -L "https://openresty.org/download/$openresty_package_name.tar.gz" -o "$openresty_package_name.tar.gz"
    Println "$(eval_gettext "\$info 解压 \$openresty_package_name ...")"
    tar xzf "$openresty_package_name.tar.gz"

    if [ "$dist" == "mac" ]
    then
        SourceInstallReady "${pcre_options[pcre_options_index]}" zlib geoip

        cc_opt="-I$HOMEBREW_PREFIX/opt/geoip/include -I$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/include -I$HOMEBREW_PREFIX/opt/zlib/include"
        ld_opt="-L$HOMEBREW_PREFIX/opt/geoip/lib -I$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/lib -L$HOMEBREW_PREFIX/opt/zlib/lib"

        for install_option in "${install_options_selected[@]}"
        do
            if [ "$install_option" == "--with-http_postgres_module" ]
            then
                DepInstall "$POSTGRESQL_MAC_PKG"
                cc_opt="$cc_opt -I$HOMEBREW_PREFIX/opt/$POSTGRESQL_MAC_PKG/include"
                ld_opt="$ld_opt -L$HOMEBREW_PREFIX/opt/$POSTGRESQL_MAC_PKG/lib"
                break
            fi
        done

        if [ "$openssl_options_index" -eq 1 ]
        then
            QuictlsInstall
            cc_opt="$cc_opt -I$DEPENDS_ROOT/quictls/build/include"
            ld_opt="$ld_opt -L$DEPENDS_ROOT/quictls/build/lib"
        else
            DepInstall "$OPENRESTY_OPENSSL_MAC_PKG"
            cc_opt="$cc_opt -I$HOMEBREW_PREFIX/opt/${OPENRESTY_OPENSSL_MAC_PKG##*/}/include"
            ld_opt="$ld_opt -L$HOMEBREW_PREFIX/opt/${OPENRESTY_OPENSSL_MAC_PKG##*/}/lib"
        fi

        cd "$openresty_package_name/bundle/ngx_lua-"*

        curl -L "$FFMPEG_MIRROR_LINK/fix_ngx_lua_resp_get_headers_key_whitespace.patch" -o fix_ngx_lua_resp_get_headers_key_whitespace.patch
        patch -p1 < fix_ngx_lua_resp_get_headers_key_whitespace.patch || true

        cd ../../

        ./configure \
        --add-module=../nginx-http-flv-module-master \
        --with-cc-opt="$cc_opt" \
        --with-ld-opt="$ld_opt" \
        --with-debug \
        --with-http_addition_module \
        --with-http_auth_request_module \
        --with-http_dav_module \
        --with-http_degradation_module \
        --with-http_gunzip_module \
        --with-http_geoip_module \
        --with-http_gzip_static_module \
        --with-http_mp4_module \
        --with-http_random_index_module \
        --with-http_realip_module \
        --with-http_secure_link_module \
        --with-http_slice_module \
        --with-http_ssl_module \
        --with-http_stub_status_module \
        --with-http_sub_module \
        --with-http_v2_module \
        --with-http_v3_module \
        --with-http_flv_module \
        --without-mail_pop3_module \
        --without-mail_imap_module \
        --without-mail_smtp_module \
        --with-pcre-jit \
        --without-http_rds_json_module \
        --without-http_rds_csv_module \
        --without-lua_rds_parser \
        --with-stream \
        --with-stream_realip_module \
        --with-stream_ssl_module \
        --with-stream_ssl_preread_module \
        --with-threads \
        --with-luajit-xcflags=-DLUAJIT_NUMMODE=2\ -DLUAJIT_ENABLE_LUA52COMPAT\ -fno-stack-check ${install_options_selected[@]+"${install_options_selected[@]}"}
    else
        if [ "$dist" == "rpm" ]
        then
            SourceInstallReady openssl-devel gcc libpq-devel
        else
            SourceInstallReady perl software-properties-common pkg-config libssl-dev libghc-zlib-dev libcurl4-gnutls-dev libexpat1-dev unzip gettext libpq-dev
        fi

        while IFS= read -r line
        do
            if [[ $line =~ \<A\ HREF=\"(.+)\.tar\.gz ]]
            then
                zlib_name=${BASH_REMATCH[1]}
                break
            fi
        done < <(curl -s -L -H "User-Agent: $USER_AGENT_BROWSER" https://www.zlib.net 2> /dev/null)

        if [ ! -d $zlib_name ]
        then
            curl -L https://www.zlib.net/$zlib_name.tar.gz -o $zlib_name.tar.gz
            Println "$(eval_gettext "\$info 解压 \$zlib_name ...")"
            tar xzf $zlib_name.tar.gz
        fi

        if [ "$pcre_options_index" -eq 0 ]
        then
            pcre_name="pcre-${PCRE_LEGACY_VER}"
            if [ ! -d $pcre_name ]
            then
                curl -L https://downloads.sourceforge.net/pcre/pcre/${pcre_name#*-}/$pcre_name.zip -o $pcre_name.zip
                Println "$(eval_gettext "\$info 解压 \$pcre_name ...")"
                unzip $pcre_name.zip > /dev/null 2>&1
            fi
        else
            pcre_name=$(curl -Lm 20 "$FFMPEG_MIRROR_LINK/pcre2.json" | $JQ_FILE -r '.tag_name')
            if [ ! -d $pcre_name ]
            then
                curl -L $FFMPEG_MIRROR_LINK/pcre2/$pcre_name/$pcre_name.zip -o $pcre_name.zip
                Println "$(eval_gettext "\$info 解压 \$pcre_name ...")"
                unzip $pcre_name.zip > /dev/null 2>&1
            fi
        fi

        local openssl_pack_url=""
        openssl_url="${OPENSSL_SOURCE_LINK}/old/1.1.1"
        openssl_pack_url=$(OpensslFetchPackUrl "$openssl_url" "1")

        if [ -z "$openssl_pack_url" ]
        then
            Println "$(eval_gettext "\$error 无法从 \$openssl_url 获取 OpenSSL 源码包地址")\n"
            return 1
        fi

        openssl_pack="${openssl_pack_url##*/}"
        openssl_name="${openssl_pack%.tar*}"

        if [ "$openssl_options_index" -eq 1 ]
        then
            openssl_ver=${openssl_name#*-}
            openssl_name=openssl-OpenSSL_${openssl_ver//./_}-quic1
        fi

        if [ ! -d "${openssl_name}-patched" ] || [ ! -s "${openssl_name}-patched/${OPENRESTY_OPENSSL_PATCH}" ]
        then
            rm -rf "${openssl_name}-patched"

            if [ "$openssl_options_index" -eq 1 ]
            then
                local openssl_short_name="${openssl_name#*-}"
                Println "$(eval_gettext "\$info 下载 \$openssl_short_name ...")"
                if ! curl -Lm 30 "${QUICTLS_REPO_LINK}/${openssl_name#*-}.tar.gz" -o "$openssl_name".tar.gz
                then
                    curl -L "$FFMPEG_MIRROR_LINK/${openssl_name#*-}".tar.gz -o "$openssl_name".tar.gz
                fi
                Println "$(eval_gettext "\$info 解压 \$openssl_short_name ...")"
                tar xzf ${openssl_name}.tar.gz
            else
                curl -L "$openssl_pack_url" -o "$openssl_pack"
                Println "$(eval_gettext "\$info 解压 \$openssl_name ...")"
                tar xzf "$openssl_pack"
            fi

            cp -r ${openssl_name} "${openssl_name}-patched"
            cd "${openssl_name}-patched"

            curl -L "$FFMPEG_MIRROR_LINK/${OPENRESTY_OPENSSL_PATCH}" -o "$OPENRESTY_OPENSSL_PATCH"
            patch -p1 < "$OPENRESTY_OPENSSL_PATCH" || true
            cd "$DEPENDS_ROOT"
        fi

        cd "$openresty_package_name/bundle/ngx_lua-"*

        curl -L "$FFMPEG_MIRROR_LINK/fix_ngx_lua_resp_get_headers_key_whitespace.patch" -o fix_ngx_lua_resp_get_headers_key_whitespace.patch
        patch -p1 < fix_ngx_lua_resp_get_headers_key_whitespace.patch || true

        cd ../..

        ./configure \
        --add-module=../nginx-http-flv-module-master \
        --with-pcre=../$pcre_name \
        --with-pcre-jit \
        --with-zlib=../$zlib_name \
        --with-openssl=../${openssl_name}-patched \
        --with-openssl-opt="no-threads shared zlib -g enable-ssl3 enable-ssl3-method enable-ec_nistp_64_gcc_128" \
        --with-http_ssl_module \
        --with-http_v2_module \
        --with-http_v3_module \
        --without-mail_pop3_module \
        --without-mail_imap_module \
        --without-mail_smtp_module \
        --without-http_rds_json_module \
        --without-http_rds_csv_module \
        --without-lua_rds_parser \
        --with-http_stub_status_module \
        --with-http_realip_module \
        --with-debug \
        --with-http_addition_module \
        --with-http_auth_request_module \
        --with-http_secure_link_module \
        --with-http_slice_module \
        --with-http_random_index_module \
        --with-http_gzip_static_module \
        --with-http_sub_module \
        --with-http_dav_module \
        --with-http_degradation_module \
        --with-http_flv_module \
        --with-http_mp4_module \
        --with-http_gunzip_module \
        --with-stream \
        --with-stream_ssl_preread_module \
        --with-stream_ssl_module \
        --with-stream_realip_module \
        --with-threads \
        --with-luajit-xcflags=-DLUAJIT_NUMMODE=2\ -DLUAJIT_ENABLE_LUA52COMPAT\ -fno-stack-check ${install_options_selected[@]+"${install_options_selected[@]}"}
    fi

    nproc="-j$(nproc 2> /dev/null)" || nproc="-j1"

    make $nproc
    make install

    ln -sf "$nginx_prefix"/sbin/nginx "$AIOS_PREFIX"/bin/

    if [ "$dist" != "mac" ]
    then
        if ! grep -q "$nginx_name:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser "$nginx_name" --system --group --no-create-home > /dev/null
            else
                adduser "$nginx_name" --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin "$nginx_name"
        fi

        sed -i "s/#user  nobody;/user $nginx_name $nginx_name;/" "$nginx_prefix/conf/nginx.conf"
    fi

    sed -i "s/worker_processes .*/worker_processes  ${nproc:2};/" "$nginx_prefix/conf/nginx.conf"
    sed -i "s/worker_connections  1024;/worker_connections  51200;/" "$nginx_prefix/conf/nginx.conf"

    mkdir -p "$nginx_prefix/conf/sites_crt/"
    mkdir -p "$nginx_prefix/conf/sites_available/"
    mkdir -p "$nginx_prefix/conf/sites_enabled/"
    mkdir -p "$nginx_prefix/html/localhost/"

    CrossplaneInstall

    Println "$(eval_gettext "\$info \$nginx_name \${install}成功")\n"
}

OpenrestyInstall()
{
    if [ -d "$nginx_prefix" ]
    then
        Println "$(eval_gettext "\$error \$nginx_name 已经存在 \$nginx_prefix !")\n"
        return 1
    elif [[ -x $(command -v $nginx_name) ]]
    then
        local nginx_cmd_path="$(command -v $nginx_name)"
        Println "$(eval_gettext "\$error \$nginx_name 已经存在 \$nginx_cmd_path, 请先卸载!")\n"
        return 1
    fi

    if [ "$dist" != "mac" ]
    then
        Println "$(eval_gettext "\$tip 选择快速安装将缺少 nginx-http-flv-module 和 quictls 选择")"
        openresty_install_options=( "$(eval_gettext "\${nginx_name}官方包 (快速安装)")" "$(gettext "编译安装")" )
        inquirer list_input_index "$(gettext "选择安装方式")" openresty_install_options openresty_install_options_index

        if [ "$openresty_install_options_index" -eq 0 ]
        then
            OpenrestyPackageInstall
            return
        fi
    fi

    OpenrestySourceInstall
}

OpenrestyUninstall()
{
    if [ ! -d "$nginx_prefix" ]
    then
        Println "$(eval_gettext "\$error \$nginx_name 未安装 !")\n"
        return 1
    fi

    echo
    ExitOnList n "`eval_gettext \"确定删除 \\\$nginx_name 包括所有配置文件, 操作不可恢复\"`"

    ServiceControl disable "$nginx_name"

    case $dist in
        mac)
            if brew list "$nginx_name" &>/dev/null
            then
                brew uninstall "$nginx_name"
            fi
        ;;
        rpm)
            if rpm -q "$nginx_name" &> /dev/null
            then
                yum remove -y "$nginx_name"* || true
            fi
        ;;
        *)
            if dpkg -s "$nginx_name" &> /dev/null
            then
                apt-get -y --purge remove "$nginx_name"* || true
            fi
        ;;
    esac

    rm -rf "${nginx_prefix%/*}"

    Println "$(eval_gettext "\$info \$nginx_name 卸载完成")\n"
}

OpenrestyUpdate()
{
    ShFileUpdate "$nginx_name"

    if [ ! -d "$nginx_prefix" ]
    then
        Println "$(eval_gettext "\$error \$nginx_name 未安装 !")\n"
        return 1
    fi

    if [ "$dist" == "rpm" ] && rpm -q "$nginx_name" &> /dev/null
    then
        yum update -y "$nginx_name"
    elif { [ "$dist" == "deb" ] || [ "$dist" == "ubu" ]; } && dpkg -s "$nginx_name" &> /dev/null
    then
        apt-get -y install --only-upgrade "$nginx_name"
    else
        OpenrestySourceInstall update
    fi
}
