}
AptSetSources()
{
    echo
    apt_sources_options=( "$(gettext "国内")" "$(gettext "国外")" )
    inquirer list_input_index "$(gettext "选择源")" apt_sources_options apt_sources_options_index
    if [ "$apt_sources_options_index" -eq 0 ]
    then
        sed -i "s/deb.debian.org/${USTC_MIRROR_HOST}/g" /etc/apt/sources.list
        sed -i "s/ftp.debian.org/${USTC_MIRROR_HOST}/g" /etc/apt/sources.list
        sed -i "s|security.debian.org|${USTC_MIRROR_HOST}/debian-security|g" /etc/apt/sources.list
        if [ -f "/etc/apt/sources.list.d/armbian.list" ]
        then
            sed -i "s|http[s]*://apt.armbian.com|http://${USTC_MIRROR_HOST}/armbian|g" /etc/apt/sources.list.d/armbian.list
            sed -i "s|http://mirrors.nju.edu.cn/armbian|http://${USTC_MIRROR_HOST}/armbian|g" /etc/apt/sources.list.d/armbian.list
        fi
        if [ -f "/etc/apt/sources.list.d/docker.list" ] 
        then
            DepInstall gpg
            curl -fsSL "http://${USTC_MIRROR_HOST}/docker-ce/linux/debian/gpg" | gpg --batch --yes --dearmor -o /usr/share/keyrings/docker-archive-keyring.gpg
            echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] http://${USTC_MIRROR_HOST}/docker-ce/linux/debian \
            $(AptGetCodename) stable" | tee /etc/apt/sources.list.d/docker.list > /dev/null
        fi
    else
        sed -i "s/${USTC_MIRROR_HOST}/deb.debian.org/g" /etc/apt/sources.list
        sed -i "s|${USTC_MIRROR_HOST}/debian-security|security.debian.org|g" /etc/apt/sources.list
        if [ -f "/etc/apt/sources.list.d/armbian.list" ]
        then
            sed -i 's|http://mirrors.nju.edu.cn/armbian|http://apt.armbian.com|g' /etc/apt/sources.list.d/armbian.list
            sed -i "s|http://${USTC_MIRROR_HOST}/armbian|http://apt.armbian.com|g" /etc/apt/sources.list.d/armbian.list
            sed -i 's/https:/http:/g' /etc/apt/sources.list.d/armbian.list
        fi
        if [ -f "/etc/apt/sources.list.d/docker.list" ] 
        then
            DepInstall gpg
            curl -fsSL "${DOCKER_REPO_LINK}/debian/gpg" | gpg --batch --yes --dearmor -o /usr/share/keyrings/docker-archive-keyring.gpg
            echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] ${DOCKER_REPO_LINK}/debian \
            $(AptGetCodename) stable" | tee /etc/apt/sources.list.d/docker.list > /dev/null
        fi
    fi
    Println "$(eval_gettext "\$info 源更改成功")\n"
}
CloudflareDisableWorkersMonitor()
{
    # deprecated
    if [ -s "/tmp/cf_workers.pid" ]
    then
        cf_workers_pid=$(< /tmp/cf_workers.pid)

        if kill -0 "$cf_workers_pid" 2> /dev/null
        then
            kill "$cf_workers_pid" 2> /dev/null
            [ ! -d "${MONITOR_LOG%/*}" ] && MONITOR_LOG="$HOME/monitor.log"
            MonitorLog "$(eval_gettext "关闭 workers 监控 PID \$cf_workers_pid !")"
            Println "$(eval_gettext "\$info workers 监控 关闭成功")\n"
        else
            Println "$(eval_gettext "\$error workers 监控 未开启")\n"
        fi
    elif [ -s "$CF_WORKERS_ROOT/cf_workers.pid" ]
    then
        PID=$(< "$CF_WORKERS_ROOT/cf_workers.pid")

        if kill -0 "$PID" 2> /dev/null
        then
            Println "$(eval_gettext "\$info 关闭 workers 监控, 稍等...")"
            kill "$PID" 2> /dev/null

            if flock -E 1 -w 20 -x "$CF_WORKERS_ROOT/cf_workers.pid" rm -f "$CF_WORKERS_ROOT/cf_workers.pid"
            then
                MonitorLog "$(eval_gettext "关闭 workers 监控 PID \$PID !")"
                Println "$(eval_gettext "\$info workers 监控 关闭成功")\n"
            else
                Println "$(eval_gettext "\$error workers 监控 关闭超时, 请重试")\n"
                exit 1
            fi
        else
            rm -f "$CF_WORKERS_ROOT/cf_workers.pid"
            Println "$(eval_gettext "\$error workers 监控 未开启")\n"
        fi
    else
        [ -e "$CF_WORKERS_ROOT/cf_workers.pid" ] && rm -f "$CF_WORKERS_ROOT/cf_workers.pid"
        Println "$(eval_gettext "\$error workers 监控 未开启")\n"
    fi
}
XtreamCodesGetDomains()
{
    [ -n "${xtream_codes_domains:-}" ] && return 0

    if [ ! -s "$XTREAM_CODES" ] 
    then
        ShFallback
        curl -s -L "$SH_FALLBACK/$XTREAM_CODES_CHANNELS" -o "$XTREAM_CODES"
    fi

    IFS="," read -ra xtream_codes_domains <<< $(awk -v ORS=, '$1 { gsub(/\|/, ",", $2); print $2 }' "$XTREAM_CODES")
}
XtreamCodesGetChnls()
{
    xc_chnls=()
    xc_chnls_mac=()
    if [ -n "${xtream_codes_domains:-}" ] 
    then
        GetChannels
        if [ "$chnls_count" -gt 0 ] 
        then
            for((xc_i=0;xc_i<chnls_count;xc_i++));
            do
                if { [ "${chnls_status[xc_i]}" == "on" ] && [ "${chnls_output_dir_name[xc_i]}" != "${chnl_output_dir_name:-}" ]; } || { [ "${chnls_flv_status[xc_i]}" == "on" ] && [ "${chnls_flv_push_link[xc_i]}" != "${chnl_flv_push_link:-}" ]; } 
                then
                    if [[ ${chnls_stream_link[xc_i]##*|} =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
                    then
                        f_domain=${chnls_stream_link[xc_i]%%|*}
                        for xc_domain in "${xtream_codes_domains[@]}"
                        do
                            if [ "$f_domain" == "$xc_domain" ] 
                            then
                                xc_chnls_mac+=("$f_domain/${BASH_REMATCH[0]}")
                                break
                            fi
                        done
                    elif [[ ${chnls_stream_link[xc_i]} =~ ^http://([^/]+)/([^/]+)/([^/]+)/ ]]
                    then
                        if [ "${BASH_REMATCH[2]}" != "live" ] || [[ ${chnls_stream_link[xc_i]} =~ ^http://([^/]+)/live/([^/]+)/([^/]+)/ ]]
                        then
                            f_domain=${BASH_REMATCH[1]}
                            for xc_domain in "${xtream_codes_domains[@]}"
                            do
                                if [ "$f_domain" == "$xc_domain" ] 
                                then
                                    xc_chnls+=("$f_domain/${BASH_REMATCH[2]}:${BASH_REMATCH[3]}")
                                    break
                                fi
                            done
                        fi
                    fi
                fi
            done
        fi
    fi
}
XtreamCodesAddAccount()
{
    echo && read -p "$(gettext "请输入账号(需包含服务器地址): ")" xtream_codes_input
    [ -z "$xtream_codes_input" ] && Println "$i18n_canceled...\n" && exit 1

    if [[ $xtream_codes_input == *"username="* ]] 
    then
        domain=${xtream_codes_input#*http://}
        domain=${domain%%/*}
        username=${xtream_codes_input#*username=}
        username=${username%%&*}
        password=${xtream_codes_input#*password=}
        password=${password%%&*}
        ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
    elif [[ $xtream_codes_input =~ ^http://([^/]+)/([^/]+)/([^/]+)/ ]] 
    then
        if [ "${BASH_REMATCH[2]}" == "live" ] 
        then
            if [[ $line =~ ^http://([^/]+)/live/([^/]+)/([^/]+)/ ]] 
            then
                domain=${BASH_REMATCH[1]}
                username=${BASH_REMATCH[2]}
                password=${BASH_REMATCH[3]}
            else
                Println "$(eval_gettext "\$error 输入错误")\n" && exit 1
            fi
        else
            domain=${BASH_REMATCH[1]}
            username=${BASH_REMATCH[2]}
            password=${BASH_REMATCH[3]}
        fi
        ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
    else
        Println "$(eval_gettext "\$error 输入错误")\n" && exit 1
    fi

    [ -z "${ip:-}" ] && Println "$(eval_gettext "\$error 无法解析域名 !")\n" && exit 1
    printf '%s\n' "$ip $domain $username:$password" >> "$XTREAM_CODES_EXAM"

    Println "$(eval_gettext "\$info 账号添加成功")\n"
}
VerifyXtreamCodesMac()
{
    to_continue=0

    if [ "${test_mac_domain:-}" != "$domain" ] 
    then
        test_mac_domain=$domain

        if [ "${skip_ip_check:-0}" -eq 0 ] 
        then
            ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
        fi

        if [ "$verify_mac" -eq 0 ] 
        then
            return 0
        fi

        Println "$(eval_gettext "\$info 验证 \$domain ...")"

        server="http://$domain"
        token_url="$server/portal.php?type=stb&action=handshake&token=&prehash=0&JsHttpRequest=1-xml"
        profile_url="$server/portal.php?type=stb&action=get_profile"
        account_info_url="$server/portal.php?type=account_info&action=get_main_info"
        [ -z "${timezone:-}" ] && timezone=$(UrlencodeUpper "Europe/Amsterdam")
    fi

    if [ -z "$ip" ] 
    then
        to_continue=1
        return 0
    fi

    if [ "$verify_mac" -eq 0 ] 
    then
        return 0
    fi

    mac_address="$account"
    access_token=""
    profile=""
    exp_date=""
    mac=$(UrlencodeUpper "$mac_address")

    access_token=$(CurlFake xtream_codes -s -Lm 10 \
        -H "User-Agent: $USER_AGENT_TV" \
        --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$token_url" \
        | $JQ_FILE -r '.js.token' 2> /dev/null) || true

    if [ -z "$access_token" ] 
    then
        Println "$error $domain $mac_address"
        to_continue=1
        return 0
    fi

    profile=$(CurlFake xtream_codes -s -Lm 10 \
        -H "User-Agent: $USER_AGENT_TV" \
        -H "Authorization: Bearer $access_token" \
        --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$profile_url" | $JQ_FILE -r '.js.id // ""' 2> /dev/null) || true

    exp_date=$(CurlFake xtream_codes -s -Lm 10 \
        -H "User-Agent: $USER_AGENT_TV" \
        -H "Authorization: Bearer $access_token" \
        --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$account_info_url" | $JQ_FILE -r '.js.phone' 2> /dev/null) || true

    if [ -z "$exp_date" ] 
    then
        if [ -z "$profile" ] 
        then
            Println "$error $domain $mac_address profile"
        else
            Println "$error $domain $mac_address exp_date"
        fi
        to_continue=1
        return 0
    fi

    account="$mac_address"
}
XtreamCodesList()
{
    if [ -s "$XTREAM_CODES_EXAM" ] && [ ! -f "$XTREAM_CODES" ]
    then
        printf '%s' "" > "$XTREAM_CODES"
    elif [ ! -s "$XTREAM_CODES" ] 
    then
        Println "$(eval_gettext "\$error 没有账号")\n"
        exit 1
    fi

    ips=()
    new_domains=()
    new_accounts=()
    verify_mac=${verify_mac:-0}

    if [ "$verify_mac" -eq 0 ] 
    then
        IFS=" " read -r m_ip m_domains m_accounts < <(awk '$1 {a=a $1",";b=b $2",";$1=$2="";c=c substr($0,3)","} END {print a,b,c}' "$XTREAM_CODES")
        IFS="," read -r -a ips <<< "$m_ip"
        IFS="," read -r -a new_domains <<< "$m_domains"
        IFS="," read -r -a new_accounts <<< "$m_accounts"
    fi

    if [ -s "$XTREAM_CODES_EXAM" ] 
    then
        while IFS= read -r line 
        do
            if [[ $line =~ ^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3} ]] 
            then
                if [[ $line =~ ([^ ]+)\ ([^ ]+)\ ([^ ]+) ]] 
                then
                    skip_ip_check=1
                    ip=${BASH_REMATCH[1]}
                    domain=${BASH_REMATCH[2]}
                    account=${BASH_REMATCH[3]}

                    if [[ $account =~ (([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})) ]] 
                    then
                        VerifyXtreamCodesMac 2> /dev/null
                        if [ "$to_continue" -eq 1 ] 
                        then
                            skip_ip_check=0
                            continue
                        fi
                    fi

                    skip_ip_check=0
                else
                    continue
                fi
            elif [[ $line == *"username="* ]] 
            then
                domain=${line#*http://}
                if [ "${test_mac_domain:-}" != "$domain" ] 
                then
                    test_mac_domain=$domain
                    ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
                fi
                [ -z "$ip" ] && continue
                domain=${domain%%/*}
                username=${line#*username=}
                username=${username%%&*}
                password=${line#*password=}
                password=${password%%&*}
                account="$username:$password"
            elif [[ $line =~ http://([^/]+)/([^/]+)/([^/]+)/ ]] 
            then
                if [ "${BASH_REMATCH[2]}" == "live" ] 
                then
                    if ! [[ $line =~ http://([^/]+)/live/([^/]+)/([^/]+)/ ]] 
                    then
                        continue
                    fi
                fi

                domain=${BASH_REMATCH[1]}
                if [ "${test_mac_domain:-}" != "$domain" ] 
                then
                    test_mac_domain=$domain
                    ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true
                fi
                [ -z "$ip" ] && continue
                username=${BASH_REMATCH[2]}
                password=${BASH_REMATCH[3]}
                account="$username:$password"
            elif [[ $line =~ http://([^/]+)/ ]] 
            then
                stb_domain=${BASH_REMATCH[1]}

                if [[ ! $line =~ (([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})) ]] 
                then
                    continue
                fi

                domain="$stb_domain"
                account=${BASH_REMATCH[1]}

                VerifyXtreamCodesMac 2> /dev/null

                if [ "$to_continue" -eq 1 ] 
                then
                    continue
                fi
            elif [ -n "${stb_domain:-}" ] && [[ $line =~ (([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})) ]] 
            then
                domain="$stb_domain"
                account=${BASH_REMATCH[1]}

                VerifyXtreamCodesMac 2> /dev/null

                if [ "$to_continue" -eq 1 ] 
                then
                    continue
                fi
            else
                continue
            fi

            for((i=0;i<${#ips[@]};i++));
            do
                if [[ ${ips[i]} == *"$ip"* ]] 
                then
                    if ! [[ ${new_domains[i]} == *"$domain"* ]] 
                    then
                        new_domains[i]="${new_domains[i]}|$domain"
                    fi

                    if ! [[ ${new_accounts[i]} == *"$account"* ]] 
                    then
                        new_accounts[i]="${new_accounts[i]} $account"
                    fi
                    continue 2
                fi
            done

            for((i=0;i<${#new_domains[@]};i++));
            do
                if [[ ${new_domains[i]} == *"$domain"* ]] 
                then
                    if ! [[ ${ips[i]} == *"$ip"* ]] 
                    then
                        ips[i]="${ips[i]}|$ip"
                    fi

                    if ! [[ ${new_accounts[i]} == *"$account"* ]] 
                    then
                        new_accounts[i]="${new_accounts[i]} $account"
                    fi
                    continue 2
                fi
            done

            ips+=("$ip")
            new_domains+=("$domain")
            new_accounts+=("$account")
        done < <(awk '$1=$1' "$XTREAM_CODES_EXAM")
    fi

    if [ -n "${ips:-}" ] 
    then
        ips_count=${#ips[@]}
        print_list=""
        xtream_codes_list=""
        ips_acc_count=0
        ips_acc=()
        ips_mac_count=0
        ips_mac=()

        for((i=0;i<ips_count;i++));
        do
            print_list="$print_list${ips[i]} ${new_domains[i]} ${new_accounts[i]}\n"
            IFS=" " read -ra accounts <<< "${new_accounts[i]}"
            accounts_list=""
            macs_num=0
            accs_num=0
            for account in "${accounts[@]}"
            do
                if [ "${1:-}" == "mac" ] 
                then
                    if [[ $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
                    then
                        macs_num=$((macs_num+1))
                        accounts_list="$accounts_list${account}\n"
                    fi
                elif [[ ! $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
                then
                    accs_num=$((accs_num+1))
                    accounts_list="$accounts_list${account%:*}${indent_20}${account#*:}\n"
                fi
            done
            if [ -n "$accounts_list" ] 
            then
                if [ "${1:-}" == "mac" ] 
                then
                    ips_mac+=("$i")
                    ips_mac_count=$((ips_mac_count+1))
                    xtream_codes_list="$xtream_codes_list ${green}$ips_mac_count.${normal} IP: ${green}${ips[i]//|/, }${normal} $i18n_domain: ${green}${new_domains[i]//|/, }${normal} $(gettext "mac 地址个数"): ${green}$macs_num${normal}\n\n"
                else
                    ips_acc+=("$i")
                    ips_acc_count=$((ips_acc_count+1))
                    xtream_codes_list="$xtream_codes_list ${green}$ips_acc_count.${normal} IP: ${green}${ips[i]//|/, }${normal} $i18n_domain: ${green}${new_domains[i]//|/, }${normal} $(gettext "账号个数"): ${green}$accs_num${normal}\n\n"
                fi
            fi
        done

        if [ -s "$XTREAM_CODES_EXAM" ] 
        then
            printf '%b' "$print_list" > "$XTREAM_CODES"
            printf '%s' "" > "$XTREAM_CODES_EXAM"
        fi

        if [ "${1:-}" == "mac" ] && [ "$ips_mac_count" -eq 0 ]
        then
            Println "$(eval_gettext "\$error 请先添加 mac 地址!")\n" && exit 1
        else
            Println "$xtream_codes_list"
        fi
    else
        Println "$(eval_gettext "\$error 没有账号")\n" && exit 1
    fi
}
XtreamCodesListAcc()
{
    XtreamCodesList

    Println "$(gettext "请输入服务器的序号")"
    while read -p "$i18n_default_cancel" server_num
    do
        case $server_num in
            "") Println "$i18n_canceled...\n" && exit 1
            ;;
            *[!0-9]*) Println "$error $i18n_input_correct_number\n"
            ;;
            *) 
                if [ "$server_num" -gt 0 ] && [ "$server_num" -le "$ips_acc_count" ]
                then
                    ips_index=${ips_acc[server_num-1]}
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done

    domain=${new_domains[ips_index]}

    if [[ $domain == *"|"* ]] 
    then
        IFS="|" read -ra domains <<< "$domain"
        domains_list=""
        domains_count=${#domains[@]}
        for((i=0;i<domains_count;i++));
        do
            domains_list="$domains_list ${green}$((i+1)).${normal}${indent_6}${domains[i]}\n\n"
        done
        Println "$domains_list"

        Println "$(gettext "选择域名")"
        while read -p "$i18n_default_cancel" domains_num
        do
            case $domains_num in
                "") Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                ;;
                *) 
                    if [ "$domains_num" -gt 0 ] && [ "$domains_num" -le "$domains_count" ]
                    then
                        domain=${domains[domains_num-1]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done
    fi

    account=${new_accounts[ips_index]}
    IFS=" " read -ra accounts <<< "$account"

    accs=()
    for account in "${accounts[@]}"
    do
        if [[ ! $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
        then
            accs+=("$account")
        fi
    done

    XtreamCodesGetDomains
    XtreamCodesGetChnls

    accs_count=${#accs[@]}
    if [ "$accs_count" -gt 1 ] 
    then
        accs_list="$i18n_account: \n\n"
        for((i=0;i<accs_count;i++));
        do
            using=""
            for xc_chnl in ${xc_chnls[@]+"${xc_chnls[@]}"}
            do
                if [ "$xc_chnl" == "$domain/${accs[i]}" ] 
                then
                    using="${red}[$(gettext "使用中")]${normal}"
                    break
                fi
            done
            accs_list="$accs_list ${green}$((i+1)).${normal}${indent_6}${accs[i]%:*}${indent_20}${accs[i]#*:} $using\n\n"
        done
        Println "$accs_list"
    else
        using=""
        for xc_chnl in ${xc_chnls[@]+"${xc_chnls[@]}"}
        do
            if [ "$xc_chnl" == "$domain/${accs[i]}" ] 
            then
                using="${red}[$(gettext "使用中")]${normal}"
                break
            fi
        done
        Println "$i18n_account: \n\n${green}1.${normal} ${accs[0]%:*}${indent_20}${accs[0]#*:} $using\n"
    fi
}
XtreamCodesTestAcc()
{
    XtreamCodesList

    Println "$(gettext "请输入服务器的序号")"
    while read -p "$i18n_default_cancel" server_num
    do
        case $server_num in
            "") Println "$i18n_canceled...\n" && exit 1
            ;;
            *[!0-9]*) Println "$error $i18n_input_correct_number\n"
            ;;
            *)
                if [ "$server_num" -gt 0 ] && [ "$server_num" -le "$ips_acc_count" ]
                then
                    ips_index=${ips_acc[server_num-1]}
                    break
                else
                    Println "$error $i18n_input_correct_no\n"
                fi
            ;;
        esac
    done

    Println "$(gettext "请输入测试的频道ID")"
    while read -p "$i18n_default_cancel" channel_id
    do
        case $channel_id in
            "") Println "$i18n_canceled...\n" && exit 1
            ;;
            *[!0-9]*) Println "$error $i18n_input_correct_number\n"
            ;;
            *)
                if [ "$channel_id" -gt 0 ]
                then
                    break
                else
                    Println "$(eval_gettext "\$error 请输入正确的频道ID(大于0)")\n"
                fi
            ;;
        esac
    done

    chnls=()

    Println "$(gettext "比如 http://username:password@127.0.0.1:5555")"
    inquirer text_input "$(gettext "输入 FFmpeg 代理: ")" proxy "$i18n_blank"

    if [ -z "$proxy" ]
    then
        proxy_command=""
    else
        proxy_command="-http_proxy $proxy"
        Println "$(gettext "代理服务器如果有正在使用的账号需要排除, 输入代理服务器的 channels.json 链接或本地路径")"
        read -p "$(gettext "(默认: 无): ")" proxy_channels_json
        if [ -n "$proxy_channels_json" ]
        then
            if [ "${proxy_channels_json:0:1}" == "/" ]
            then
                proxy_channels=$(< "$proxy_channels_json")
            else
                proxy_channels=$(curl -s -Lm 10 "$proxy_channels_json")
            fi
            while IFS= read -r line
            do
                if [[ $line == *\"status\":* ]]
                then
                    line=${line#*: \"}
                    status=${line%\",*}
                elif [[ $line == *\"stream_link\":* ]] && [[ $line == *http://*/*/*/* ]]
                then
                    line=${line#*: \"http://}
                    chnl_domain=${line%%/*}
                    line=${line#*/}
                    chnl_username=${line%%/*}
                    if [ "$chnl_username" == "live" ]
                    then
                        line=${line#*/}
                        chnl_username=${line%%/*}
                    fi
                    line=${line#*/}
                    chnl_password=${line%%/*}
                elif [[ $line == *\"flv_status\":* ]]
                then
                    line=${line#*: \"}
                    flv_status=${line%\",*}
                    if [ -n "${chnl_domain:-}" ]
                    then
                        if [ "$status" == "on" ] || [ "$flv_status" == "on" ]
                        then
                            chnls+=("$chnl_domain/$chnl_username/$chnl_password")
                        fi
                    fi
                    chnl_domain=""
                fi
            done <<< "$proxy_channels"
        fi
    fi

    if [ -e "$CHANNELS_FILE" ]
    then
        GetChannels
        if [ "$chnls_count" -gt 0 ]
        then
            for((xc_i=0;xc_i<chnls_count;xc_i++));
            do
                if [ "${chnls_status[xc_i]}" == "on" ] || [ "${chnls_flv_status[xc_i]}" == "on" ]
                then
                    if [[ ${chnls_stream_link[xc_i]} =~ ^http://([^/]+)/([^/]+)/([^/]+)/ ]]
                    then
                        if [ "${BASH_REMATCH[2]}" != "live" ] || [[ ${chnls_stream_link[xc_i]} =~ ^http://([^/]+)/live/([^/]+)/([^/]+)/ ]]
                        then
                            chnls+=("${BASH_REMATCH[1]}/${BASH_REMATCH[2]}:${BASH_REMATCH[3]}")
                        fi
                    fi
                fi
            done
        fi
    fi

    IFS="|" read -ra domains <<< "${new_domains[ips_index]}"
    IFS=" " read -ra accounts <<< "${new_accounts[ips_index]}"
    Println "IP: ${green}${ips[ips_index]}${normal} $i18n_domain: ${green}${new_domains[ips_index]//|/ }${normal}"
    Println "${green}$i18n_account:${normal}"

    FFmpegInstall

    for account in "${accounts[@]}"
    do
        if [[ $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]]
        then
            continue
        fi
        username=${account%%:*}
        account=${account#*:}
        password=${account%%:*}

        for domain in "${domains[@]}"
        do
            for chnl in ${chnls[@]+"${chnls[@]}"}
            do
                if [ "$domain/$username/$password" == "$chnl" ]
                then
                    # https://f-hauri.ch/vrac/diffU8test.sh
                    printf "${green}%s${normal}\r\033[12C%-21s%-21s\n" "[$(gettext "使用中")]" "$username" "$password"
                    continue 2
                fi
            done

            # curl --output /dev/null -m 3 -s --fail -r 0-0
            if $FFPROBE_FILE $proxy_command -rw_timeout 5000000 -i "http://$domain/$username/$password/$channel_id" -show_streams -select_streams a -loglevel quiet > /dev/null
            then
                printf "${green}%s${normal}\r\033[12C%-21s%-21s${green}%s${normal}\n%s\n\n" "[$(gettext "成功")]" "$username" "$password" "$domain" "http://$domain/$username/$password/$channel_id"
            elif $FFPROBE_FILE $proxy_command -rw_timeout 5000000 -i "http://$domain/live/$username/$password/$channel_id.ts" -show_streams -select_streams a -loglevel quiet > /dev/null
            then
                printf "${green}%s${normal}\r\033[12C%-21s%-21s${green}%s${normal}\n%s\n\n" "[$(gettext "成功")]" "$username" "$password" "$domain" "http://$domain/live/$username/$password/$channel_id.ts"
            else
                printf "${red}%s${normal}\r\033[12C%-21s%-21s${red}%s${normal}\n%s" "[$(gettext "失败")]" "$username" "$password" "$domain"
            fi
        done
    done
    echo
}
