SearchXtreamCodesChnls()
{
    search_result=""

    for((i=1;i<=pages;i++));
    do
        if [ "$i" -gt 1 ] 
        then
            echo -en "\r$((i*100/pages))%"
        else
            Println "$(eval_gettext "\$info 搜索进度")"
            echo -n "$((i*100/pages))%"
        fi
        sleep 1
        page_index=$((i-1))
        if [ -n "${ordered_list_pages[page_index]:-}" ] 
        then
            ordered_list_page=${ordered_list_pages[page_index]}
        else
            if [ "$i" -gt 1 ] 
            then
                ordered_list_url="$server/portal.php?type=itv&action=get_ordered_list&genre=${genres_id[genres_index]}&force_ch_link_check=&fav=0&sortby=number&hd=0&p=$i"
                ordered_list_page=$(CurlFake xtream_codes -s -Lm 10 \
                    -H "User-Agent: $user_agent" \
                    -H "${headers:0:-4}" \
                    --cookie "$cookies" "$ordered_list_url" | $JQ_FILE -r -c '.' 2> /dev/null) || ordered_list_page=""
            fi
            ordered_list_pages[page_index]="$ordered_list_page"
        fi

        while IFS= read -r name
        do
            name=${name#\"}
            name=${name%\"}
            name_lower=$(tr '[:upper:]' '[:lower:]' <<< "$name")
            if [[ $name_lower == *"$search_phrase"* ]] 
            then
                search_result="$search_result$(gettext "页数"): ${green}$i${normal} $(gettext "频道名称"): ${green}$name${normal}\n\n"
            fi
        done < <($JQ_FILE '.js.data[].name' <<< "$ordered_list_page")
    done
}
XtreamCodesListChnls()
{
    FFmpegInstall

    local lbl_input_server_no lbl_select_domain lbl_default_back lbl_mac_addr lbl_in_use lbl_select_mac lbl_acc_expire lbl_genre_prompt lbl_input_chnl_no lbl_search_result lbl_return lbl_err_retry lbl_screenshot lbl_input_ss_pos lbl_return_err lbl_retry lbl_add_chnl lbl_add_replace_src lbl_replace lbl_select_replace_src lbl_push_flv
    lbl_input_server_no=$(gettext "请输入服务器的序号")
    lbl_select_domain=$(gettext "选择域名")
    lbl_default_back=$(gettext "(默认: 回到上级): ")
    lbl_mac_addr=$(gettext "mac 地址")
    lbl_in_use=$(gettext "使用中")
    lbl_select_mac=$(gettext "请选择 mac")
    lbl_acc_expire=$(gettext "账号到期时间")
    lbl_genre_prompt=$(gettext "输入分类序号, 输入 a 返回上级页面, 输入 b 使用下个 mac 地址")
    lbl_input_chnl_no=$(gettext "输入频道序号: ")
    lbl_search_result=$(gettext "搜索结果")
    lbl_return=$(gettext "返回")
    lbl_err_retry=$(gettext "错误, 请重试")
    lbl_screenshot=$(gettext "截图")
    lbl_input_ss_pos=$(gettext "输入截图位置")
    lbl_return_err=$(gettext "返回错误")
    lbl_retry=$(gettext "请重试")
    lbl_add_chnl=$(gettext "是否添加此频道")
    lbl_add_replace_src=$(gettext "是否 添加/替换 现有频道直播源")
    lbl_replace=$(gettext "替换")
    lbl_select_replace_src=$(gettext "选择替换的直播源")
    lbl_push_flv=$(gettext "是否推流 flv")

    while true
    do
        if [ -n "${xtream_codes_list:-}" ]
        then
            Println "$xtream_codes_list"
        else
            XtreamCodesList mac
        fi

        Println "$lbl_input_server_no"
        while read -p "$i18n_default_cancel" server_num
        do
            case $server_num in
                "") Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                ;;
                *)
                    if [ "$server_num" -gt 0 ] && [ "$server_num" -le "$ips_mac_count" ]
                    then
                        ips_index=${ips_mac[server_num-1]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        domain=${new_domains[ips_index]}

        if [[ $domain == *"|"* ]]
        then
            IFS="|" read -ra domains <<< "$domain"
            domains_list=""
            domains_count=${#domains[@]}
            for((i=0;i<domains_count;i++));
            do
                domains_list="$domains_list ${green}$((i+1)).${normal}${indent_6}${domains[i]}\n\n"
            done
            Println "$domains_list"

            Println "$lbl_select_domain"
            while read -p "$lbl_default_back" domains_num
            do
                case $domains_num in
                    ""|a) continue 2
                    ;;
                    *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                    ;;
                    *)
                        if [ "$domains_num" -gt 0 ] && [ "$domains_num" -le "$domains_count" ]
                        then
                            domain=${domains[domains_num-1]}
                            break
                        else
                            Println "$error $i18n_input_correct_no\n"
                        fi
                    ;;
                esac
            done
        fi

        account=${new_accounts[ips_index]}
        IFS=" " read -ra accounts <<< "$account"

        macs=()
        for account in ${accounts[@]+"${accounts[@]}"}
        do
            if [[ $account =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]]
            then
                macs+=("$account")
            fi
        done

        XtreamCodesGetDomains
        XtreamCodesGetChnls

        macs_count=${#macs[@]}
        if [ "$macs_count" -gt 1 ]
        then
            macs_list="$lbl_mac_addr: \n\n"
            for((i=0;i<macs_count;i++));
            do
                using=""
                for xc_chnl_mac in ${xc_chnls_mac[@]+"${xc_chnls_mac[@]}"}
                do
                    if [ "$xc_chnl_mac" == "$domain/${macs[i]}" ]
                    then
                        using="${red}[$lbl_in_use]${normal}"
                        break
                    fi
                done
                macs_list="$macs_list ${green}$((i+1)).${normal}${indent_6}${macs[i]} $using\n\n"
            done
            Println "$macs_list"

            Println "$lbl_select_mac"
            while read -p "$lbl_default_back" macs_num
            do
                case $macs_num in
                    ""|a) continue 2
                    ;;
                    *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                    ;;
                    *) 
                        if [ "$macs_num" -gt 0 ] && [ "$macs_num" -le "$macs_count" ]
                        then
                            mac_address=${macs[macs_num-1]}
                            for xc_chnl_mac in ${xc_chnls_mac[@]+"${xc_chnls_mac[@]}"}
                            do
                                if [ "$xc_chnl_mac" == "$domain/$mac_address" ] 
                                then
                                    Println "$(eval_gettext "\$error 此账号已经在使用!")\n"
                                    continue 2
                                fi
                            done
                            break
                        else
                            Println "$error $i18n_input_correct_no\n"
                        fi
                    ;;
                esac
            done
        else
            mac_address=${macs[0]}
        fi

        user_agent="$USER_AGENT_TV"
        timezone=$(UrlencodeUpper "Europe/Amsterdam")
        mac_addresses_failed=()
        GetDefault

        if [ -n "${d_xc_proxy:-}" ] 
        then
            echo
            inquirer list_input "$(eval_gettext "是否使用代理 \$d_xc_proxy: ")" yn_options use_proxy_yn
            if [ "$use_proxy_yn" == "$i18n_yes" ]
            then
                server="${d_xc_proxy%\/}/http://$domain"
            else
                server="http://$domain"
            fi
        else
            server="http://$domain"
            use_proxy_yn="$i18n_no"
        fi

        token_url="$server/portal.php?type=stb&action=handshake&token=&prehash=0&JsHttpRequest=1-xml"
        profile_url="$server/portal.php?type=stb&action=get_profile"
        genres_url="$server/portal.php?type=itv&action=get_genres"
        account_info_url="$server/portal.php?type=account_info&action=get_main_info"

        while true 
        do
            mac=$(UrlencodeUpper "$mac_address")
            cookies="mac=$mac; stb_lang=en; timezone=$timezone"

            access_token=$(CurlFake xtream_codes -s -Lm 10 \
                -H "User-Agent: $user_agent" \
                --cookie "$cookies" "$token_url" \
                | $JQ_FILE -r '.js.token' 2> /dev/null) || true

            if [ -z "$access_token" ] 
            then
                Println "$error $domain $mac_address access\n"

                mac_addresses_failed+=("$mac_address")

                for mac in "${macs[@]}"
                do
                    if [ "$mac_address" != "$mac" ] 
                    then
                        for mac_address_failed in "${mac_addresses_failed[@]}"
                        do
                            if [ "$mac_address_failed" == "$mac" ] 
                            then
                                continue 2
                            fi
                        done
                        for xc_chnl_mac in ${xc_chnls_mac[@]+"${xc_chnls_mac[@]}"}
                        do
                            if [ "$xc_chnl_mac" == "$domain/$mac" ] 
                            then
                                continue 2
                            fi
                        done
                        Println "$(eval_gettext "\$info 测试 \$mac")\n"
                        mac_address="$mac"
                        continue 2
                    fi
                done
                exit 1
            fi

            headers="Authorization: Bearer $access_token\r\n"
            printf -v headers_command '%b' "$headers"

            profile=$(CurlFake xtream_codes -s -Lm 10 \
                -H "User-Agent: $user_agent" \
                -H "${headers:0:-4}" \
                --cookie "$cookies" "$profile_url" | $JQ_FILE -r '.js.id // ""' 2> /dev/null) || true

            exp_date=$(CurlFake xtream_codes -s -Lm 10 \
                -H "User-Agent: $user_agent" \
                -H "${headers:0:-4}" \
                --cookie "$cookies" "$account_info_url" | $JQ_FILE -r '.js.phone' 2> /dev/null) || true

            if [ -z "$exp_date" ] 
            then
                if [ -z "$profile" ] 
                then
                    Println "$error $domain $mac_address profile\n"
                else
                    Println "$error $domain $mac_address exp_date\n"
                fi

                mac_addresses_failed+=("$mac_address")

                for mac in "${macs[@]}"
                do
                    if [ "$mac_address" != "$mac" ] 
                    then
                        for mac_address_failed in "${mac_addresses_failed[@]}"
                        do
                            if [ "$mac_address_failed" == "$mac" ] 
                            then
                                continue 2
                            fi
                        done
                        for xc_chnl_mac in ${xc_chnls_mac[@]+"${xc_chnls_mac[@]}"}
                        do
                            if [ "$xc_chnl_mac" == "$domain/$mac" ] 
                            then
                                continue 2
                            fi
                        done
                        Println "$(eval_gettext "\$info 测试 \$mac")\n"
                        mac_address="$mac"
                        continue 2
                    fi
                done
                exit 1
            fi

            genres_list=""
            genres_count=0
            genres_id=()
            while IFS="=" read -r map_id map_title
            do
                map_id=${map_id#\"}
                map_title=${map_title%\"}
                genres_count=$((genres_count+1))
                genres_id+=("$map_id")
                genres_list="$genres_list ${green}$genres_count.${normal}${indent_6}$map_title\n\n"
            done < <(CurlFake xtream_codes -s -Lm 10 \
                -H "User-Agent: $user_agent" \
                -H "${headers:0:-4}" \
                --cookie "$cookies" "$genres_url" \
                | $JQ_FILE '.js[] | [.id,.title] | join("=")')

            if [ -n "$genres_list" ] 
            then
                genres_list_pages=()

                while true
                do
                    Println "$genres_list\n\n${green}$lbl_acc_expire:${normal} $exp_date\n"

                    if [ "${return_err:-0}" -eq 1 ]
                    then
                        return_err=0
                        Println "$(eval_gettext "\$error 返回错误, 请重试")"
                    fi

                    Println "$lbl_genre_prompt"
                    while read -p "$i18n_default_cancel" genres_num 
                    do
                        case "$genres_num" in
                            "")
                                Println "$i18n_canceled...\n" && exit
                            ;;
                            a)
                                continue 4
                            ;;
                            b)
                                mac_addresses_failed+=("$mac_address")

                                for mac in "${macs[@]}"
                                do
                                    if [ "$mac_address" != "$mac" ] 
                                    then
                                        for mac_address_failed in "${mac_addresses_failed[@]}"
                                        do
                                            if [ "$mac_address_failed" == "$mac" ] 
                                            then
                                                continue 2
                                            fi
                                        done
                                        for xc_chnl_mac in ${xc_chnls_mac[@]+"${xc_chnls_mac[@]}"}
                                        do
                                            if [ "$xc_chnl_mac" == "$domain/$mac" ] 
                                            then
                                                continue 2
                                            fi
                                        done
                                        Println "$(eval_gettext "\$info 测试 \$mac")\n"
                                        mac_address="$mac"
                                        continue 4
                                    fi
                                done
                                Println "$(eval_gettext "\$error 没有剩余 mac 地址")\n"
                                exit 1
                            ;;
                            *[!0-9]*)
                                Println "$error $i18n_input_correct_no\n"
                            ;;
                            *)
                                if [ "$genres_num" -gt 0 ] && [ "$genres_num" -le "$genres_count" ]
                                then
                                    genres_index=$((genres_num-1))
                                    break
                                else
                                    Println "$error $i18n_input_correct_no\n"
                                fi
                            ;;
                        esac
                    done

                    if [ -n "${genres_list_pages[genres_index]:-}" ] 
                    then
                        ordered_list_page=${genres_list_pages[genres_index]}
                    else
                        ordered_list_url="$server/portal.php?type=itv&action=get_ordered_list&genre=${genres_id[genres_index]}&force_ch_link_check=&fav=0&sortby=number&hd=0&p=1"
                        ordered_list_page=$(CurlFake xtream_codes -s -Lm 10 \
                            -H "User-Agent: $user_agent" \
                            -H "${headers:0:-4}" \
                            --cookie "$cookies" "$ordered_list_url" | $JQ_FILE -r -c '.' 2> /dev/null) || ordered_list_page=""
                        [ -z "$ordered_list_page" ] && return_err=1 && continue 2
                        genres_list_pages[genres_index]="$ordered_list_page"
                    fi

                    exec 100< <($JQ_FILE -r '.js.total_items, .js.max_page_items' <<< "$ordered_list_page")
                    read total_items <&100
                    read max_page_items <&100
                    exec 100<&-

                    if [ "$total_items" == null ] || [ "${total_items:-0}" -eq 0 ] 
                    then
                        Println "$(eval_gettext "\$error 此分类没有频道!")\n"
                        continue
                    fi

                    if [ "$total_items" -le "$max_page_items" ] 
                    then
                        pages=1
                    else
                        pages=$((total_items / max_page_items))
                        if [ "$total_items" -gt $((pages * max_page_items)) ] 
                        then
                            pages=$((pages+1))
                        fi
                    fi

                    page=1
                    ordered_list_pages=()

                    while true 
                    do
                        page_index=$((page-1))
                        if [ -n "${ordered_list_pages[page_index]:-}" ] 
                        then
                            ordered_list_page=${ordered_list_pages[page_index]}
                        else
                            if [ "$page" -gt 1 ] 
                            then
                                ordered_list_url="$server/portal.php?type=itv&action=get_ordered_list&genre=${genres_id[genres_index]}&force_ch_link_check=&fav=0&sortby=number&hd=0&p=$page"
                                ordered_list_page=$(CurlFake xtream_codes -s -Lm 10 \
                                    -H "User-Agent: $user_agent" \
                                    -H "${headers:0:-4}" \
                                    --cookie "$cookies" "$ordered_list_url" | $JQ_FILE -r -c '.' 2> /dev/null) || ordered_list_page=""
                                [ -z "$ordered_list_page" ] && return_err=1 && continue 3
                            fi
                            ordered_list_pages[page_index]="$ordered_list_page"
                        fi

                        xc_chnls_id=()
                        xc_chnls_name=()
                        xc_chnls_cmd=()
                        xc_chnls_list=""
                        xc_chnls_count=0
                        while IFS="^" read -r map_id map_cmd map_name
                        do
                            xc_chnls_count=$((xc_chnls_count+1))
                            map_id=${map_id#\"}
                            map_name=${map_name%\"}
                            map_cmd=${map_cmd#* }
                            map_cmd=${map_cmd%\_}
                            map_cmd="http://localhost/ch/${map_cmd##*/}_"
                            xc_chnls_id+=("$map_id")
                            xc_chnls_name+=("$map_name")
                            xc_chnls_cmd+=("$map_cmd")
                            xc_chnls_list="$xc_chnls_list# ${green}$xc_chnls_count${normal} $map_name\n\n"
                        done < <($JQ_FILE '.js.data[] | [.id,.cmd,.name] | join("^")' <<< "$ordered_list_page")

                        Println "$xc_chnls_list"
                        echo -e "$(eval_gettext "\$tip 输入 a 返回上级页面")"
                        echo -e "$(eval_gettext "\$tip 输入 s 频道名称 搜索频道")"
                        echo -e "$(eval_gettext "\$tip 输入 p 页数 跳转页面")"
                        if [ "$pages" -gt 1 ] 
                        then
                            Println "$(eval_gettext "当前第 \$page 页, 共 \$pages 页")"
                            if [ "$page" -eq 1 ] 
                            then
                                echo -e "$(eval_gettext "\$tip 输入 x 转到下一页")"
                            elif [ "$page" -eq "$pages" ] 
                            then
                                echo -e "$(eval_gettext "\$tip 输入 z 转到上一页")"
                            else
                                echo -e "$(eval_gettext "\$tip 输入 z 转到上一页, 输入 x 转到下一页")"
                            fi
                        fi

                        echo && while read -p "$lbl_input_chnl_no" xc_chnls_num
                        do
                            if [[ $xc_chnls_num =~ ^s\ * ]]
                            then
                                search_phrase=${xc_chnls_num#*s }
                                Trim search_phrase
                                if [ -z "$search_phrase" ]
                                then
                                    Println "$(eval_gettext "\$error 搜索内容不能为空")\n"
                                else
                                    SearchXtreamCodesChnls
                                fi

                                if [ -n "$search_result" ]
                                then
                                    Println "$lbl_search_result:\n\n$search_result"
                                else
                                    Println "$(eval_gettext "\$error 没有搜索结果")\n"
                                fi
                                continue
                            elif [[ $xc_chnls_num =~ ^p\ [0-9]+ ]]
                            then
                                if [ "${xc_chnls_num#* }" -le "$pages" ]
                                then
                                    page=${xc_chnls_num#* }
                                    continue 2
                                else
                                    Println "$(eval_gettext "\$error 页数错误")\n"
                                    continue
                                fi
                            fi
                            case "$xc_chnls_num" in
                                a)
                                    continue 3
                                ;;
                                z)
                                    if [ "$page" -gt 1 ]
                                    then
                                        page=$((page-1))
                                        continue 2
                                    else
                                        Println "$(eval_gettext "\$error 没有上一页")\n"
                                    fi
                                ;;
                                x)
                                    if [ "$page" -lt "$pages" ]
                                    then
                                        page=$((page+1))
                                        continue 2
                                    else
                                        Println "$(eval_gettext "\$error 没有下一页")\n"
                                    fi
                                ;;
                                ""|*[!0-9]*)
                                    Println "$error $i18n_input_correct_no\n"
                                ;;
                                *)
                                    if [ "$xc_chnls_num" -gt 0 ] && [ "$xc_chnls_num" -le "$xc_chnls_count" ]
                                    then
                                        xc_chnls_index=$((xc_chnls_num-1))
                                        break
                                    else
                                        Println "$error $i18n_input_correct_no\n"
                                    fi
                                ;;
                            esac
                        done

                        if [ "$use_proxy_yn" == "$i18n_yes" ]
                        then
                            stream_link="$server/?cmd=${xc_chnls_cmd[xc_chnls_index]}"
                            Println "${green}${xc_chnls_name[xc_chnls_index]}:${normal} $stream_link\n"
                        else
                            create_link_url="$server/portal.php?type=itv&action=create_link&cmd=${xc_chnls_cmd[xc_chnls_index]}&series=&forced_storage=undefined&disable_ad=0&download=0"

                            cmd=$(CurlFake xtream_codes -s -Lm 10 \
                                -H "User-Agent: $user_agent" \
                                -H "${headers:0:-4}" \
                                --cookie "$cookies" "$create_link_url" \
                                | $JQ_FILE -r '.js.cmd') || true

                            if [[ ${cmd#* } =~ ([^/]+)//([^/]+)/(.+) ]]
                            then
                                stream_link="http://localhost:3000/$(XtreamCodesDomainFilter ${BASH_REMATCH[2]})/${BASH_REMATCH[3]}"
                            else
                                Println "$error $lbl_return cmd: ${cmd:-$i18n_none} $lbl_err_retry"
                                continue
                            fi
                            stream_link=${stream_link// /}
                            stream_link=${stream_link//.ts.ts/.ts}
                            Println "${green}${xc_chnls_name[xc_chnls_index]}:${normal} $stream_link\n"
                        fi

                        EXIT_STATUS=0

                        printf -v headers_command '%b' "$headers"
                        printf -v cookies_command '%b' "${cookies//;/; path=\/;\\r\\n}; path=/;"

                        echo
                        inquirer list_input_index "$lbl_screenshot" ny_options ny_index

                        if [[ $ny_index -eq 1 ]]
                        then
                            Println "$(eval_gettext "\$tip 格式如 HH:MM:SS")"
                            inquirer text_input "$lbl_input_ss_pos" ss 00:00:03

                            if TMP_FILE=$(mktemp -q)
                            then
                                chmod +r "$TMP_FILE"
                            else
                                PrintfTime TMP_FILE '%m-%d-%H:%M:%S' -1
                            fi

                            trap '
                                rm -f "$TMP_FILE"
                                rm -f "${TMP_FILE}.jpeg"
                            ' EXIT

                            $FFMPEG_FILE -hide_banner -loglevel debug -user_agent "$user_agent" \
                                -headers "$headers_command" -cookies "$cookies_command" -i "$stream_link" -ss "$ss" -frames:v 1 "${TMP_FILE}.jpeg" || EXIT_STATUS=$?

                            if [ ! -x "$IMGCAT_FILE" ]
                            then
                                ImgcatInstall
                            fi

                            "$IMGCAT_FILE" --half-height "${TMP_FILE}.jpeg" 2> /dev/null || EXIT_STATUS=$?

                            rm -f "$TMP_FILE"
                            rm -f "${TMP_FILE}.jpeg"

                            trap - EXIT
                        else
                            $FFPROBE_FILE -hide_banner -loglevel debug -show_streams -user_agent "$user_agent" \
                                -headers "$headers_command" -cookies "$cookies_command" -i "$stream_link" || EXIT_STATUS=$?
                        fi

                        if [ "$EXIT_STATUS" -ne 0 ] && [ "$use_proxy_yn" == "$i18n_yes" ]
                        then
                            Println "$(eval_gettext "\$info 尝试直连 ...")"
                            # curl -k -s -o /dev/null -w '%{redirect_url}'
                            IFS=" " read -r stream_link new_access_token new_cookies < <(CurlFake xtream_codes -sL \
                                -H "User-Agent: $user_agent" \
                                --cookie "$cookies" \
                                "$server/?cmd=${xc_chnls_cmd[xc_chnls_index]}&check=1" | $JQ_FILE -r '.|join(" ")' 2> /dev/null) || true
                            if [[ ! $stream_link =~ ([^/]+)//([^/]+)/(.+) ]]
                            then
                                Println "$error curl -sL '$server/?cmd=${xc_chnls_cmd[xc_chnls_index]}&check=1' -H 'User-Agent: $user_agent' -H '$(StripSuffix "$headers" 4)' --cookie '$cookies'"
                                Println "$error $lbl_return_err[ stream_link: ${stream_link:-$i18n_none} ], $lbl_retry"
                                continue
                            fi

                            EXIT_STATUS=0
                            access_token="$new_access_token"
                            cookies="$new_cookies"

                            printf -v headers_command '%b' "$Authorization: Bearer $access_token"
                            printf -v cookies_command '%b' "${cookies//;/; path=\/;\\r\\n}; path=/;"

                            if [[ $ny_index -eq 1 ]]
                            then
                                if TMP_FILE=$(mktemp -q)
                                then
                                    chmod +r "$TMP_FILE"
                                else
                                    TMP_FILE=$(date '+%m-%d-%H:%M:%S')
                                fi

                                trap '
                                    rm -f "$TMP_FILE"
                                    rm -f "${TMP_FILE}.jpeg"
                                ' EXIT

                                $FFMPEG_FILE -hide_banner -loglevel debug -user_agent "$user_agent" \
                                    -headers "$headers_command" -cookies "$cookies_command" -i "$stream_link" -ss "$ss" -frames:v 1 "${TMP_FILE}.jpeg" || EXIT_STATUS=$?

                                "$IMGCAT_FILE" --half-height "${TMP_FILE}.jpeg" 2> /dev/null || EXIT_STATUS=$?

                                rm -f "$TMP_FILE"
                                rm -f "${TMP_FILE}.jpeg"

                                trap - EXIT
                            else
                                $FFPROBE_FILE -hide_banner -loglevel debug -show_streams -user_agent "$user_agent" \
                                    -headers "$headers_command" -cookies "$cookies_command" -i "$stream_link" || EXIT_STATUS=$?
                            fi
                        fi

                        if [ "$EXIT_STATUS" -eq 0 ]
                        then
                            echo
                            inquirer list_input "$lbl_add_chnl" ny_options add_channel_yn
                            if [ "$add_channel_yn" == "$i18n_yes" ]
                            then
                                if [ "$use_proxy_yn" == "$i18n_yes" ]
                                then
                                    if [[ $stream_link =~ cmd= ]]
                                    then
                                        headers=""
                                        headers_command=""
                                    else
                                        headers="Authorization: Bearer $access_token\r\n"
                                        printf -v headers_command '%b' "$headers"
                                    fi
                                fi

                                stream_links=("$domain|$stream_link|${xc_chnls_cmd[xc_chnls_index]}|$mac_address")

                                echo
                                inquirer list_input "$lbl_add_replace_src" ny_options add_channel_yn

                                if [ "$add_channel_yn" == "$i18n_yes" ]
                                then
                                    ListChannels
                                    InputChannelsIndex

                                    for((i=0;i<${#chnls_pid_chosen[@]};i++));
                                    do
                                        chnl_pid=${chnls_pid_chosen[i]}
                                        chnls_index=${chnls_indices[i]}

                                        ListChannel

                                        echo
                                        change_options=( "$i18n_add" "$lbl_replace" )
                                        inquirer list_input_index "$(eval_gettext "如何修改频道 [ \$chnl_channel_name ]")" change_options change_options_index

                                        if [ "$change_options_index" -eq 0 ]
                                        then
                                            jq_pre=true
                                            jq_path='["channels",'"$chnls_index"',"stream_link"]'
                                            JQ add "$CHANNELS_FILE" ["\"${stream_links[0]}\""]
                                        else
                                            echo
                                            inquirer list_input_index "$lbl_select_replace_src" chnl_stream_links chnl_stream_links_index

                                            jq_path='["channels",'"$chnls_index"',"stream_link",'"$chnl_stream_links_index"']'
                                            JQ update "$CHANNELS_FILE" "${stream_links[0]}"
                                        fi

                                        Println "$(eval_gettext "\$info 频道 [ \$chnl_channel_name ] 修改成功 !")\n"
                                    done
                                else
                                    echo
                                    inquirer list_input "$lbl_push_flv" ny_options add_channel_flv_yn

                                    if [[ $add_channel_flv_yn == "$i18n_yes" ]] 
                                    then
                                        kind="flv"
                                    fi

                                    if [ "$use_proxy_yn" == "$i18n_yes" ] 
                                    then
                                        xtream_codes_proxy="$server"
                                    fi

                                    stream_link_parsed=true
                                    AddChannel
                                fi
                            else
                                continue
                            fi
                        else
                            Println "$(eval_gettext "\$error 频道不可用或账号权限不够")\n"
                            continue
                        fi
                        break
                    done
                    break
                done
            else
                Println "$(eval_gettext "\$error \$mac_address 错误, 找不到分类! 账号到期时间: \$exp_date")\n"

                mac_addresses_failed+=("$mac_address")

                for mac in "${macs[@]}"
                do
                    if [ "$mac_address" != "$mac" ] 
                    then
                        for mac_address_failed in "${mac_addresses_failed[@]}"
                        do
                            if [ "$mac_address_failed" == "$mac" ] 
                            then
                                continue 2
                            fi
                        done
                        for xc_chnl_mac in ${xc_chnls_mac[@]+"${xc_chnls_mac[@]}"}
                        do
                            if [ "$xc_chnl_mac" == "$domain/$mac" ] 
                            then
                                continue 2
                            fi
                        done
                        Println "$(eval_gettext "\$info 测试 \$mac")\n"
                        mac_address="$mac"
                        continue 2
                    fi
                done
                exit 1
            fi
            break
        done
        break
    done
}
XtreamCodesAddMac()
{
    echo && read -p "$(gettext "输入服务器地址"): " server
    [ -z "$server" ] && Println "$i18n_canceled...\n" && exit 1

    domain=${server#*http://}
    domain=${domain%%/*}
    ip=$(getent ahosts "${domain%%:*}" | awk '{ print $1 ; exit }') || true

    [ -z "${ip:-}" ] && Println "$(eval_gettext "\$error 无法解析域名 !")\n" && exit 1

    echo && read -p "$(gettext "请输入 mac 地址(多个地址空格分隔): ")" mac_address
    [ -z "$mac_address" ] && Println "$i18n_canceled...\n" && exit 1

    IFS=" " read -ra macs <<< "$mac_address"

    GetDefault

    if [ -n "${d_xc_proxy:-}" ] 
    then
        echo
        inquirer list_input "$(eval_gettext "是否使用代理 \$d_xc_proxy 验证: ")" yn_options use_proxy_yn
        if [ "$use_proxy_yn" == "$i18n_yes" ]
        then
            server="${d_xc_proxy%\/}/http://$domain"
        else
            server="http://$domain"
        fi
    else
        server="http://$domain"
    fi

    timezone=$(UrlencodeUpper "Europe/Amsterdam")
    token_url="$server/portal.php?type=stb&action=handshake&token=&prehash=0&JsHttpRequest=1-xml"
    profile_url="$server/portal.php?type=stb&action=get_profile"
    account_info_url="$server/portal.php?type=account_info&action=get_main_info"

    Println "$(eval_gettext "\$info 验证中...")"
    add_mac_success=false

    for mac_address in "${macs[@]}"
    do
        access_token=""
        exp_date=""
        mac=$(UrlencodeUpper "$mac_address")

        access_token=$(CurlFake xtream_codes -s -Lm 10 \
            -H "User-Agent: $USER_AGENT_TV" \
            --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$token_url" \
            | $JQ_FILE -r '.js.token' 2> /dev/null) || true

        if [ -z "$access_token" ] 
        then
            Println "$error $domain $mac_address access_token"
            continue
        fi

        profile=$(CurlFake xtream_codes -s -Lm 10 \
            -H "User-Agent: $USER_AGENT_TV" \
            -H "Authorization: Bearer $access_token" \
            --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$profile_url" | $JQ_FILE -r '.js.id // ""' 2> /dev/null) || true

        exp_date=$(CurlFake xtream_codes -s -Lm 10 \
            -H "User-Agent: $USER_AGENT_TV" \
            -H "Authorization: Bearer $access_token" \
            --cookie "mac=$mac; stb_lang=en; timezone=$timezone" "$account_info_url" | $JQ_FILE -r '.js.phone' 2> /dev/null) || true

        if [ -z "$exp_date" ] 
        then
            Println "$error $domain $mac_address exp_date"
            continue
        fi

        add_mac_success=true

        printf '%s\n' "$ip $domain $mac_address" >> "$XTREAM_CODES_EXAM"
    done
}
FFmpegResolveBin()
{
    local cfg_bin=""
    if [ -n "${IPTV_CONFIG:-}" ] && [ -s "$IPTV_CONFIG" ] && [ -n "${JQ_FILE:-}" ] && [ -x "$JQ_FILE" ]
    then
        cfg_bin=$("$JQ_FILE" -r 'if type == "object" and (.ffmpeg_bin | type) == "string" then .ffmpeg_bin else "" end' "$IPTV_CONFIG" 2> /dev/null || true)
    fi

    if [ -n "$cfg_bin" ] && [ -x "$cfg_bin" ]
    then
        FFMPEG_FILE="$cfg_bin"
        local cfg_probe="${cfg_bin%/*}/ffprobe"
        if [ -x "$cfg_probe" ]
        then
            FFPROBE_FILE="$cfg_probe"
        fi
        return 0
    fi

    if [ -n "${FFMPEG_FILE:-}" ] && [ -x "$FFMPEG_FILE" ]
    then
        if [ -z "${FFPROBE_FILE:-}" ] || [ ! -x "$FFPROBE_FILE" ]
        then
            local sibling_probe="${FFMPEG_FILE%/*}/ffprobe"
            if [ -x "$sibling_probe" ]
            then
                FFPROBE_FILE="$sibling_probe"
            fi
        fi
        return 0
    fi

    local cand
    for cand in \
        "${AIOS_PREFIX:-/usr/local}/bin/ffmpeg" \
        "/opt/homebrew/opt/ffmpeg-full/bin/ffmpeg" \
        "/opt/homebrew/bin/ffmpeg" \
        "/usr/local/opt/ffmpeg-full/bin/ffmpeg" \
        "/usr/local/bin/ffmpeg" \
        "/usr/bin/ffmpeg"
    do
        if [ -x "$cand" ]
        then
            FFMPEG_FILE="$cand"

            if [ -x "${cand%/*}/ffprobe" ]
            then
                FFPROBE_FILE="${cand%/*}/ffprobe"
            fi
            return 0
        fi
    done

    local path_bin
    if path_bin=$(command -v ffmpeg 2> /dev/null) && [ -n "$path_bin" ] && [ -x "$path_bin" ]
    then
        FFMPEG_FILE="$path_bin"

        if [ -x "${path_bin%/*}/ffprobe" ]
        then
            FFPROBE_FILE="${path_bin%/*}/ffprobe"
        elif path_bin=$(command -v ffprobe 2> /dev/null) && [ -n "$path_bin" ]
        then
            FFPROBE_FILE="$path_bin"
        fi
        return 0
    fi

    return 1
}

FFmpegDetectCaps()
{
    local target_bin="${1:-${FFMPEG_FILE:-}}"
    if [ -z "$target_bin" ] || [ ! -x "$target_bin" ]
    then
        FFmpegResolveBin || return 1
        target_bin="$FFMPEG_FILE"
    fi

    if [ "${FFMPEG_CAPS_BIN:-}" == "$target_bin" ] && [ -n "${FFMPEG_MAJOR:-}" ]
    then
        return 0
    fi

    local ver_line
    ver_line=$("$target_bin" -version 2> /dev/null | head -n 1 || true)
    if [[ $ver_line =~ version[[:space:]]+n?([0-9]+)\.([0-9]+) ]]
    then
        FFMPEG_MAJOR="${BASH_REMATCH[1]}"
        FFMPEG_MINOR="${BASH_REMATCH[2]}"
        FFMPEG_IS_GIT=false
    else
        FFMPEG_MAJOR=99
        FFMPEG_MINOR=0
        FFMPEG_IS_GIT=true
    fi

    FFMPEG_HAS_FPS_MODE=false

    if [ "$FFMPEG_MAJOR" -gt 5 ] || { [ "$FFMPEG_MAJOR" -eq 5 ] && [ "$FFMPEG_MINOR" -ge 1 ]; }
    then
        FFMPEG_HAS_FPS_MODE=true
    fi

    FFMPEG_HAS_ENHANCED_FLV_HEVC=false

    if [ "$FFMPEG_MAJOR" -gt 6 ] || { [ "$FFMPEG_MAJOR" -eq 6 ] && [ "$FFMPEG_MINOR" -ge 1 ]; }
    then
        FFMPEG_HAS_ENHANCED_FLV_HEVC=true
    fi

    FFMPEG_HAS_FILTER_SLASH_SYNTAX=false

    if [ "$FFMPEG_MAJOR" -ge 9 ]
    then
        FFMPEG_HAS_FILTER_SLASH_SYNTAX=true
    fi

    FFMPEG_HAS_DRAWTEXT=false

    if "$target_bin" -hide_banner -filters 2> /dev/null | grep -qE '[[:space:]]drawtext[[:space:]]'
    then
        FFMPEG_HAS_DRAWTEXT=true
    fi

    FFMPEG_CAPS_BIN="$target_bin"
    return 0
}

FFmpegSyncFlag()
{
    local mode="${1:-0}"
    FFmpegDetectCaps 2> /dev/null || true

    if [ "${FFMPEG_HAS_FPS_MODE:-true}" = true ]
    then
        case "$mode" in
            0|passthrough) printf '%s\n' "-fps_mode passthrough" ;;
            1|cfr) printf '%s\n' "-fps_mode cfr" ;;
            2|vfr) printf '%s\n' "-fps_mode vfr" ;;
            drop) printf '%s\n' "-fps_mode drop" ;;
            *) printf '%s\n' "-fps_mode $mode" ;;
        esac
    else
        printf '%s\n' "-vsync $mode"
    fi
}

FFmpegNormalizeFlags()
{
    local flags_str="${1:-}"
    local stream_url="${2:-}"
    FFmpegDetectCaps 2> /dev/null || true

    local tokens=()
    local out_tokens=()
    local tok i=0 n=0
    local is_http=true

    if [ -n "$stream_url" ] && [[ ! $stream_url =~ ^https?:// ]]
    then
        is_http=false
    fi

    # shellcheck disable=SC2206
    tokens=( $flags_str )
    n=${#tokens[@]}

    while [ "$i" -lt "$n" ]
    do
        tok="${tokens[$i]}"
        case "$tok" in
            -vsync)
                local val="${tokens[$((i + 1))]:-0}"
                if [ "${FFMPEG_HAS_FPS_MODE:-true}" = true ]
                then
                    out_tokens+=( "-fps_mode" )
                    case "$val" in
                        0) out_tokens+=( "passthrough" ) ;;
                        1) out_tokens+=( "cfr" ) ;;
                        2) out_tokens+=( "vfr" ) ;;
                        *) out_tokens+=( "$val" ) ;;
                    esac
                else
                    out_tokens+=( "-vsync" "$val" )
                fi
                i=$((i + 2))
                continue
            ;;
            -qphist)
                if [ "${FFMPEG_MAJOR:-8}" -ge 8 ]
                then
                    i=$((i + 1))
                    continue
                fi
                out_tokens+=( "$tok" )
            ;;
            -filter_complex_script)
                if [ "${FFMPEG_HAS_FILTER_SLASH_SYNTAX:-false}" = true ]
                then
                    out_tokens+=( "-/filter_complex" )
                else
                    out_tokens+=( "$tok" )
                fi
            ;;
            -reconnect|-reconnect_at_eof|-reconnect_streamed|-reconnect_delay_max|-reconnect_on_network_error|-reconnect_on_http_error|-seekable)
                if [ "$is_http" = false ]
                then
                    i=$((i + 2))
                    continue
                fi
                out_tokens+=( "$tok" )
                if [ $((i + 1)) -lt "$n" ]
                then
                    out_tokens+=( "${tokens[$((i + 1))]}" )
                    i=$((i + 2))
                    continue
                fi
            ;;
            *)
                out_tokens+=( "$tok" )
            ;;
        esac
        i=$((i + 1))
    done

    printf '%s\n' "${out_tokens[*]}"
}

FFmpegSaveConfig()
{
    FFMPEG_CAPS_BIN=""
    FFmpegDetectCaps "$FFMPEG_FILE" 2> /dev/null || true

    if [ -n "${IPTV_CONFIG:-}" ] && [ -s "$IPTV_CONFIG" ]
    then
        jq_path='["ffmpeg_bin"]'
        JQ update "$IPTV_CONFIG" "$FFMPEG_FILE"
    fi
}

FFmpegInstall()
{
    local mode="${1:-}"

    if [ "$mode" != "select" ] && [ "$mode" != "switch" ] && [ "$mode" != "force" ]
    then
        if FFmpegResolveBin && [ -x "${FFMPEG_FILE:-}" ] && [ -x "${FFPROBE_FILE:-}" ]
        then
            return 0
        fi

        if FFMPEG_FILE_ROOT=$(find "$FFMPEG_ROOT"/ffmpeg-* -maxdepth 0 -type d 2> /dev/null | head -1) && [ -n "$FFMPEG_FILE_ROOT" ]
        then
            if [ -x "$FFMPEG_FILE_ROOT/bin/ffmpeg" ]
            then
                FFMPEG_FILE="$FFMPEG_FILE_ROOT/bin/ffmpeg"
                FFPROBE_FILE="$FFMPEG_FILE_ROOT/bin/ffprobe"
            else
                FFMPEG_FILE="$FFMPEG_FILE_ROOT/ffmpeg"
                FFPROBE_FILE="$FFMPEG_FILE_ROOT/ffprobe"
            fi
        elif FFMPEG_FILE_ROOT=$(find "$IPTV_ROOT"/ffmpeg-* -maxdepth 0 -type d 2> /dev/null | head -1) && [ -n "$FFMPEG_FILE_ROOT" ]
        then
            FFMPEG_ROOT="$IPTV_ROOT"

            if [ -x "$FFMPEG_FILE_ROOT/bin/ffmpeg" ]
            then
                FFMPEG_FILE="$FFMPEG_FILE_ROOT/bin/ffmpeg"
                FFPROBE_FILE="$FFMPEG_FILE_ROOT/bin/ffprobe"
            else
                FFMPEG_FILE="$FFMPEG_FILE_ROOT/ffmpeg"
                FFPROBE_FILE="$FFMPEG_FILE_ROOT/ffprobe"
            fi
        fi

        if [ -x "${FFMPEG_FILE:-}" ] && [ -x "${FFPROBE_FILE:-}" ]
        then
            return 0
        fi
    fi

    if [ "$dist" == "mac" ]
    then
        local menu_options=()
        local menu_actions=()
        local bin ver formula drawtext_tag

        for bin in /opt/homebrew/Cellar/ffmpeg*/*/bin/ffmpeg /usr/local/Cellar/ffmpeg*/*/bin/ffmpeg
        do
            if [ -x "$bin" ]
            then
                ver=$("$bin" -version 2> /dev/null | head -n 1 | awk '{print $3}')
                formula="${bin#*/Cellar/}"
                formula="${formula%%/*}"

                if "$bin" -hide_banner -filters 2> /dev/null | grep -qE '[[:space:]]drawtext[[:space:]]'
                then
                    drawtext_tag="$(gettext "含 drawtext")"
                else
                    drawtext_tag="$(gettext "无 drawtext")"
                fi
                local ver_text="${ver:-unknown}"
                menu_options+=("$(eval_gettext "切换至已安装: \${formula} (\${ver_text}, \${drawtext_tag}) [\${bin}]")")
                menu_actions+=("use:${bin}")
            fi
        done

        menu_options+=(
            "$(gettext "安装 ffmpeg-full (含 drawtext 水印滤镜, 推荐)")"
            "$(gettext "安装 ffmpeg (9.x 最新主线)")"
            "$(gettext "安装 ffmpeg@8")"
            "$(gettext "安装 ffmpeg@7")"
            "$(gettext "安装 ffmpeg@6")"
        )
        menu_actions+=(
            "install:ffmpeg-full"
            "install:ffmpeg"
            "install:ffmpeg@8"
            "install:ffmpeg@7"
            "install:ffmpeg@6"
        )

        echo
        inquirer list_input_index "$(gettext "选择或切换 macOS FFmpeg 版本")" menu_options ffmpeg_mac_index

        local selected_action="${menu_actions[$ffmpeg_mac_index]}"
        if [[ $selected_action == use:* ]]
        then
            FFMPEG_FILE="${selected_action#use:}"
            FFPROBE_FILE="${FFMPEG_FILE%/*}/ffprobe"
        else
            local brew_formula="${selected_action#install:}"
            Println "`eval_gettext \"\\\$info 开始下载/安装 FFmpeg...\"`"

            if ! brew install "$brew_formula"
            then
                Println "`eval_gettext \"\\\$error FFmpeg 安装失败 !\"`\n"
                exit 1
            fi

            local brew_prefix
            brew_prefix=$(brew --prefix "$brew_formula" 2> /dev/null || true)
            if [ -n "$brew_prefix" ] && [ -x "$brew_prefix/bin/ffmpeg" ]
            then
                FFMPEG_FILE="$brew_prefix/bin/ffmpeg"
                FFPROBE_FILE="$brew_prefix/bin/ffprobe"
            else
                for bin in "/opt/homebrew/Cellar/$brew_formula"/*/bin/ffmpeg "/usr/local/Cellar/$brew_formula"/*/bin/ffmpeg
                do
                    if [ -x "$bin" ]
                    then
                        FFMPEG_FILE="$bin"
                        FFPROBE_FILE="${bin%/*}/ffprobe"
                    fi
                done
            fi
        fi

        if [ ! -x "${FFMPEG_FILE:-}" ] || [ ! -x "${FFPROBE_FILE:-}" ]
        then
            FFmpegResolveBin || true
        fi

        if [ ! -x "${FFMPEG_FILE:-}" ] || [ ! -x "${FFPROBE_FILE:-}" ]
        then
            Println "`eval_gettext \"\\\$error FFmpeg 安装或切换失败 !\"`\n"
            exit 1
        fi

        FFmpegSaveConfig
        Println "`eval_gettext \"\\\$info FFmpeg 安装成功\"`"
        return 0
    fi

    local linux_ver_options=(
        "6.1 LTS"
        "7.1 LTS"
        "8.x"
        "9.x / latest"
        "git-master"
        "$(gettext "系统包管理器")"
    )
    echo
    inquirer list_input_index "$(gettext "选择 Linux FFmpeg 版本")" linux_ver_options ffmpeg_linux_index

    if [ "$ffmpeg_linux_index" -eq 5 ]
    then
        Println "`eval_gettext \"\\\$info 开始下载/安装 FFmpeg...\"`"

        if [ "$dist" == "rpm" ]
        then
            yum -y install ffmpeg || dnf -y install ffmpeg
        elif [ "$dist" == "alpine" ]
        then
            apk add --no-cache ffmpeg
        else
            AptUpdate force && AptInstall ffmpeg
        fi

        FFMPEG_FILE=$(command -v ffmpeg 2> /dev/null || true)
        FFPROBE_FILE=$(command -v ffprobe 2> /dev/null || true)
        if [ ! -x "${FFMPEG_FILE:-}" ] || [ ! -x "${FFPROBE_FILE:-}" ]
        then
            Println "`eval_gettext \"\\\$error FFmpeg 安装失败 !\"`"
            exit 1
        fi

        FFmpegSaveConfig
        Println "`eval_gettext \"\\\$info FFmpeg 安装成功\"`"
        return 0
    fi

    Println "`eval_gettext \"\\\$info 开始下载/安装 FFmpeg...\"`"
    mkdir -p "$FFMPEG_ROOT"
    rm -rf "$FFMPEG_ROOT"/ffmpeg-*

    ArchCheck

    local btbn_arch="" jvs_arch=""
    if [ "$arch" == "x86_64" ] || [ "$arch" == "amd64" ]
    then
        btbn_arch="linux64"
        jvs_arch="amd64"
    elif [ "$arch" == "aarch64" ] || [ "$arch" == "arm64" ]
    then
        btbn_arch="linuxarm64"
        jvs_arch="arm64"
    elif [ "$arch" == "i386" ] || [ "$arch" == "i686" ]
    then
        jvs_arch="i686"
    elif [ "$arch" == "armv6l" ]
    then
        jvs_arch="armel"
    elif grep -q "arm" <<< "$arch"
    then
        jvs_arch="$arch"
    else
        Println "$(eval_gettext "\$error FFmpeg 不支持当前系统")\n"
        exit 1
    fi

    local download_urls=()
    local btbn_base="$BTBN_FFMPEG_LINK"
    if [ -n "$btbn_arch" ]
    then
        case "$ffmpeg_linux_index" in
            0)
                download_urls+=( "${btbn_base}/ffmpeg-n6.1-latest-${btbn_arch}-gpl-6.1.tar.xz" )
            ;;
            1)
                download_urls+=( "${btbn_base}/ffmpeg-n7.1-latest-${btbn_arch}-gpl-7.1.tar.xz" )
            ;;
            2)
                download_urls+=(
                    "${btbn_base}/ffmpeg-n8.1-latest-${btbn_arch}-gpl-8.1.tar.xz"
                    "${btbn_base}/ffmpeg-n8.0-latest-${btbn_arch}-gpl-8.0.tar.xz"
                )
            ;;
            3)
                download_urls+=(
                    "${btbn_base}/ffmpeg-n9.0-latest-${btbn_arch}-gpl-9.0.tar.xz"
                    "${btbn_base}/ffmpeg-master-latest-${btbn_arch}-gpl.tar.xz"
                )
            ;;
            4)
                download_urls+=( "${btbn_base}/ffmpeg-master-latest-${btbn_arch}-gpl.tar.xz" )
            ;;
        esac
    fi

    if [ "$ffmpeg_linux_index" -eq 4 ]
    then
        download_urls+=( "${JVS_FFMPEG_LINK}/builds/ffmpeg-git-${jvs_arch}-static.tar.xz" )
    else
        download_urls+=(
            "${JVS_FFMPEG_LINK}/releases/ffmpeg-release-${jvs_arch}-static.tar.xz"
            "${JVS_FFMPEG_LINK}/builds/ffmpeg-git-${jvs_arch}-static.tar.xz"
        )
    fi
    download_urls+=( "$FFMPEG_MIRROR_LINK/builds/ffmpeg-git-${jvs_arch}-static.tar.xz" )

    local FFMPEG_PACKAGE_FILE="$FFMPEG_ROOT/ffmpeg-static.tar.xz"
    local dl_url="" dl_ok=false
    for dl_url in "${download_urls[@]}"
    do
        if curl -fL "$dl_url" -o "$FFMPEG_PACKAGE_FILE"
        then
            dl_ok=true
            break
        fi
    done

    if [ "$dl_ok" = false ]
    then
        rm -f "$FFMPEG_PACKAGE_FILE"
        Println "`eval_gettext \"\\\$error FFmpeg 下载失败 !\"`"
        exit 1
    fi

    tar xJf "$FFMPEG_PACKAGE_FILE" -C "$FFMPEG_ROOT" && rm -f "${FFMPEG_PACKAGE_FILE:-notfound}"

    FFMPEG_FILE=$(find "$FFMPEG_ROOT"/ffmpeg-* -type f -name ffmpeg 2> /dev/null | head -1) || true
    FFPROBE_FILE=$(find "$FFMPEG_ROOT"/ffmpeg-* -type f -name ffprobe 2> /dev/null | head -1) || true

    if [ ! -x "${FFMPEG_FILE:-}" ] || [ ! -x "${FFPROBE_FILE:-}" ]
    then
        Println "`eval_gettext \"\\\$error FFmpeg 解压失败 !\"`"
        exit 1
    fi

    FFmpegSaveConfig
    Println "`eval_gettext \"\\\$info FFmpeg 安装成功\"`"
}

FFmpegCompile()
{
    DepsCheck

    if [ "$dist" == "rpm" ] 
    then
        Println "`eval_gettext \"\\\$error 不支持 centos\"`\n"
        exit 1
    fi

    tls_options=( 'gnutls' 'openssl' )
    inquirer list_input "`gettext \"选择 tls\"`" tls_options tls_option

    nproc="-j$(nproc 2> /dev/null)" || nproc=""

    if ! grep -q "swapfile" /etc/fstab 
    then
        fallocate -l 1024M /opt/swapfile > /dev/null 2>&1 || dd if=/dev/zero of=/opt/swapfile bs=1M count=1024 > /dev/null 2>&1
        chmod 600 /opt/swapfile
        mkswap /opt/swapfile
        swapon /opt/swapfile
        echo "/opt/swapfile none swap defaults 0 0" >> /etc/fstab
    fi

    mkdir -p ~/ffmpeg_sources

    apt-get -y install autoconf automake build-essential cmake zlib1g-dev \
        libtool pkg-config texinfo frei0r-plugins-dev libopencore-amrnb-dev \
        libopencore-amrwb-dev libtheora-dev libvo-amrwbenc-dev libxvidcore-dev \
        libssl-dev libva-dev libvdpau-dev libxcb1-dev libxcb-shm0-dev \
        libxcb-xfixes0-dev flex bison libharfbuzz-dev \
        libfontconfig-dev libfreetype6-dev python3 python3-pip \
        python3-setuptools python3-wheel ninja-build doxygen git libxext-dev \
        libsndfile1-dev libasound2-dev graphviz

    export CMAKE_PREFIX_PATH="$HOME/ffmpeg_build"
    export PATH="$HOME/ffmpeg_build/bin:$PATH"
    export LDFLAGS="-L$HOME/ffmpeg_build/lib"
    # -Wl,-z,relro,-z,now
    export DYLD_LIBRARY_PATH="$HOME/ffmpeg_build/lib"
    export PKG_CONFIG_PATH="$HOME/ffmpeg_build/lib/pkgconfig"
    export CFLAGS="-I$HOME/ffmpeg_build/include $LDFLAGS"
    # -O3 -static-libgcc -fno-strict-overflow -fstack-protector-all -fPIE
    # export CXXFLAGS="-O3 -static-libgcc -fno-strict-overflow -fstack-protector-all -fPIE"

    # zlib
    cd ~/ffmpeg_sources
    if [ ! -d zlib-1.2.11 ] 
    then
        [ ! -f zlib-1.2.11.tar.gz ] && curl -L "https://www.zlib.net/zlib-1.2.11.tar.gz" -o zlib-1.2.11.tar.gz
        tar xzf zlib-1.2.11.tar.gz
    fi
    cd zlib-1.2.11
    if [ -f Makefile ] 
    then
        make distclean || true
    fi
    ./configure --prefix="$HOME/ffmpeg_build" --static
    make $nproc
    make install

    # CMake
    cmake_install=1
    if [[ -x $(command -v cmake) ]] 
    then
        cmake_ver=$(cmake --version | awk '{print $3}' | head -1)
        if [[ $cmake_ver =~ ^([0-9]+)\.([0-9]+)\.([0-9]+) ]] && { [ "${BASH_REMATCH[1]}" -lt 3 ] || { [ "${BASH_REMATCH[1]}" -eq 3 ] && [ "${BASH_REMATCH[2]}" -lt 14 ]; }; }
        then
            apt-get -y remove cmake
            hash -r
        else
            cmake_install=0
        fi
    fi

    if [ "$cmake_install" -eq 1 ] 
    then
        cd ~/ffmpeg_sources
        if [ ! -d CMake-3.18.4 ] 
        then
            [ ! -f cmake-3.18.4.tar.gz ] && curl -L "https://github.com/Kitware/CMake/archive/v3.18.4.tar.gz" -o cmake-3.18.4.tar.gz
            tar xzf cmake-3.18.4.tar.gz
        fi
        cd CMake-3.18.4
        if [ -f Makefile ] 
        then
            make distclean || true
        fi
        ./bootstrap
        make $nproc
        make install
    fi

    # libbz2
    cd ~/ffmpeg_sources
    if [ ! -d bzip2-1.0.6 ] 
    then
        [ ! -f bzip2-1.0.6.tar.gz ] && curl -L "https://downloads.sourceforge.net/bzip2/bzip2-1.0.6.tar.gz" -o bzip2-1.0.6.tar.gz
        tar xzf bzip2-1.0.6.tar.gz
    fi
    cd bzip2-1.0.6
    if [ -f Makefile ] 
    then
        make distclean || true
    fi
    make
    make install PREFIX="$HOME/ffmpeg_build"
    echo "prefix=$HOME/ffmpeg_build
exec_prefix=\${prefix}
libdir=\${prefix}/lib
includedir=\${prefix}/include

Name: bzip2
Description: bzip2
Version: 1.0.6
Requires:
Libs: -L\${libdir} -lbz2
Cflags: -I\${includedir}
" > "$HOME/ffmpeg_build/lib/pkgconfig/bzip2.pc"

    # yasm
    cd ~/ffmpeg_sources
    if [ ! -d yasm-1.3.0 ] 
    then
        [ ! -f yasm-1.3.0.tar.gz ] && curl -L "http://www.tortall.net/projects/yasm/releases/yasm-1.3.0.tar.gz" -o yasm-1.3.0.tar.gz
        tar xzf yasm-1.3.0.tar.gz
    fi
    cd yasm-1.3.0
    if [ -f Makefile ] 
    then
        make distclean || true
    fi
    ./configure --prefix="$HOME/ffmpeg_build"
    make $nproc
    make install

    # nasm
    # uname -mpi | grep -qE 'x86|i386|i686'
    if [ "$dist" != "arm" ] 
    then
        cd ~/ffmpeg_sources
        if [ ! -d nasm-2.15.05 ] 
        then
            [ ! -f nasm-2.15.05.tar.gz ] && curl -L "https://www.nasm.us/pub/nasm/releasebuilds/2.15.05/nasm-2.15.05.tar.gz" -o nasm-2.15.05.tar.gz
            tar xzf nasm-2.15.05.tar.gz
        fi
        cd nasm-2.15.05
        if [ -f Makefile ] 
        then
            make distclean || true
        fi
        ./autogen.sh
        ./configure --prefix="$HOME/ffmpeg_build"
        make $nproc
        make install
    fi

    # x264
    cd ~/ffmpeg_sources
    git -C x264 pull 2> /dev/null || git clone --depth 1 https://code.videolan.org/videolan/x264.git
    cd x264
    if [ -f Makefile ] 
    then
        make distclean || true
    fi
    ./configure --prefix="$HOME/ffmpeg_build" --enable-static --enable-pic
    make $nproc
    make install

    # libnuma (for x265)
    cd ~/ffmpeg_sources
    git -C numactl pull 2> /dev/null || git clone --depth 1 https://github.com/numactl/numactl.git
    cd numactl
    if [ -f Makefile ] 
    then
        make distclean || true
    fi
    ./autogen.sh
    ./configure --prefix="$HOME/ffmpeg_build" --disable-shared
    make $nproc
    make install

    # x265
    cd ~/ffmpeg_sources
    rm -rf x265_git
    git clone https://bitbucket.org/multicoreware/x265_git
    cd x265_git/build/linux
    cmake -G "Unix Makefiles" -DCMAKE_INSTALL_PREFIX="$HOME/ffmpeg_build" -DENABLE_SHARED=OFF -DSTATIC_LINK_CRT=ON -DENABLE_CLI=OFF ../../source
    make $nproc
    sed -i 's/-lgcc_s/-lgcc_eh/g' x265.pc
    make install

    # liblzma (for libxml2, ffmpeg)
    cd ~/ffmpeg_sources
    if [ ! -d xz-5.2.5 ] 
    then
        [ ! -f xz-5.2.5.tar.xz ] && curl -L "https://downloads.sourceforge.net/lzmautils/xz-5.2.5.tar.xz" -o xz-5.2.5.tar.xz
        tar xJf xz-5.2.5.tar.xz
    fi
    cd xz-5.2.5
    if [ -f Makefile ] 
    then
        make distclean || true
    fi
    ./configure --prefix="$HOME/ffmpeg_build" --disable-shared --enable-static
    make $nproc
    make install

    # libiconv (for libxml2)
    cd ~/ffmpeg_sources
    if [ ! -d libiconv-1.16 ] 
    then
        [ ! -f libiconv-1.16.tar.gz ] && curl -L "https://ftp.gnu.org/pub/gnu/libiconv/libiconv-1.16.tar.gz" -o libiconv-1.16.tar.gz
        tar xzf libiconv-1.16.tar.gz
    fi
    cd libiconv-1.16
    if [ -f Makefile ] 
    then
        make distclean || true
    fi
    ./configure --prefix="$HOME/ffmpeg_build" --disable-shared --enable-static
    make $nproc
    make install

    # libxml2
    cd ~/ffmpeg_sources
    rm -rf libxml2
    git clone https://github.com/GNOME/libxml2.git
    mkdir -p libxml2/build
    cd libxml2/build
    cmake -G "Unix Makefiles" -DCMAKE_INSTALL_PREFIX="$HOME/ffmpeg_build" -DBUILD_SHARED_LIBS=OFF ..
    make $nproc
    make install
cat > "$HOME"/ffmpeg_build/lib/pkgconfig/libxml-2.0.pc <<EOF
prefix=$HOME/ffmpeg_build
exec_prefix=\${prefix}
libdir=\${prefix}/lib
includedir=\${prefix}/include

Name: libxml2
Description: libxml2
Version: 2.9.10
Requires:
Libs: -L\${libdir} -lxml2
Cflags: -I\${includedir}
EOF

    # libpng (for openjpeg)
    cd ~/ffmpeg_sources
    if [ ! -d libpng-1.6.37 ] 
    then
        [ ! -f libpng-1.6.37.tar.gz ] && curl -L "https://downloads.sourceforge.net/libpng/libpng-1.6.37.tar.gz" -o libpng-1.6.37.tar.gz
        tar xzf libpng-1.6.37.tar.gz
    fi
    cd libpng-1.6.37
    if [ -f Makefile ] 
    then
        make distclean || true
    fi
    ./configure --prefix="$HOME/ffmpeg_build" --enable-static=yes --enable-shared=no
    make $nproc
    make install

    # c2man (for fribidi)
    cd ~/ffmpeg_sources
    rm -rf c2man
    git clone --depth 1 https://github.com/fribidi/c2man.git
    cd c2man
    rm -rf "$HOME/ffmpeg_sources/c2man_build"
    rm -f "$HOME/ffmpeg_build/bin/c2man"
    mkdir "$HOME/ffmpeg_sources/c2man_build"
    ./Configure -dE
    echo "binexp=$HOME/ffmpeg_build/bin" >> config.sh
    echo "installprivlib=$HOME/ffmpeg_sources/c2man_build" >> config.sh
    echo "mansrc=$HOME/ffmpeg_sources/c2man_build" >> config.sh
    sh config_h.SH
    sh flatten.SH
    sh Makefile.SH
    make depend
    make
    make install

    # fribidi (for libass)
    cd ~/ffmpeg_sources
    if [ ! -d fribidi-1.0.10 ] 
    then
        [ ! -f fribidi-1.0.10.tar.gz ] && curl -L "https://github.com/fribidi/fribidi/archive/v1.0.10.tar.gz" -o fribidi-1.0.10.tar.gz
        tar xzf fribidi-1.0.10.tar.gz
    fi
    cd fribidi-1.0.10
    if [ -f Makefile ] 
    then
