            Println "$(eval_gettext "\$error 无法安装 youtube-dl, 请稍后再试")\n"
            exit 1
        fi

        mv /usr/local/bin/youtube-dl_tmp /usr/local/bin/youtube-dl
        chmod a+rx /usr/local/bin/youtube-dl
