    SyncFile()
    {
        if [ "$action" == "add" ]
        then
            chnl_pid=$pid
            i18nGetMsg get_channel
            GetChannel
        else
            GetDefault
        fi

        chnl_sync_file=${chnl_sync_file:-$d_sync_file}
        chnl_sync_index=${chnl_sync_index:-$d_sync_index}
        chnl_sync_pairs=${chnl_sync_pairs:-$d_sync_pairs}

        if [ "${chnl_sync:-false}" = true ] && [ -n "$chnl_sync_file" ] && [ -n "$chnl_sync_index" ] && [ -n "$chnl_sync_pairs" ]
        then
            IFS=" " read -ra chnl_sync_files <<< "$chnl_sync_file"
            IFS=" " read -ra chnl_sync_indices <<< "$chnl_sync_index"

            chnl_pid_key=${chnl_sync_pairs%%:pid*}
            chnl_pid_key=${chnl_pid_key##*,}
            sync_count=${#chnl_sync_files[@]}
            [ "${#chnl_sync_indices[@]}" -lt "$sync_count" ] && sync_count=${#chnl_sync_indices[@]}

            for((sync_i=0;sync_i<sync_count;sync_i++));
            do
                if [ ! -s "${chnl_sync_files[sync_i]}" ]
                then
                    $JQ_FILE -n --arg name "$(RandStr)" \
                    '{
                        "ret": 0,
                        "data": [
                            {
                                "name": $name,
                                "channels": []
                            }
                        ]
                    }' > "${chnl_sync_files[sync_i]}"
                fi

                jq_index=""
                jq_path="["

                while IFS=':' read -ra index_arr
                do
                    for a in "${index_arr[@]}"
                    do
                        [ "$jq_path" != "[" ] && jq_path="$jq_path,"
                        case $a in
                            '')
                                Println "`eval_gettext \"\\\$error sync设置错误...\"`\n" && exit 1
                            ;;
                            *[!0-9]*)
                                jq_index="$jq_index.$a"
                                jq_path="$jq_path\"$a\""
                            ;;
                            *)
                                jq_index="${jq_index}[$a]"
                                jq_path="${jq_path}$a"
                            ;;
                        esac
                    done
                done <<< "${chnl_sync_indices[sync_i]}"

                jq_path="$jq_path]"

                if [ "$action" == "stop" ]
                then
                    if [[ -n $($JQ_FILE --arg k "$chnl_pid_key" --arg p "$chnl_pid" "(${jq_index} // [])[] | select(.[\$k] == (\$p | tonumber))" "${chnl_sync_files[sync_i]}" 2> /dev/null) ]]
                    then
                        JQ delete "${chnl_sync_files[sync_i]}" "$chnl_pid_key" "$chnl_pid"
                    fi
                else
                    jq_channel_new=$($JQ_FILE -n -c '{}')

                    while IFS=',' read -ra index_arr
                    do
                        for b in "${index_arr[@]}"
                        do
                            case $b in
                                '')
                                    Println "`eval_gettext \"\\\$error sync设置错误...\"`\n" && exit 1
                                ;;
                                *)
                                    if [[ $b == *"="* ]]
                                    then
                                        key=${b%=*}
                                        value=${b#*=}

                                        if [[ $value =~ ^http ]]
                                        then
                                            if [ -n "${kind:-}" ]
                                            then
                                                if [ "$kind" == "flv" ]
                                                then
                                                    value="${chnl_flv_pull_link:-}"
                                                else
                                                    value=""
                                                fi
                                            elif [ -z "${master:-}" ] || [ "$master" -eq 1 ]
                                            then
                                                value="$value/$chnl_output_dir_name/${chnl_playlist_name}_master.m3u8"
                                            else
                                                value="$value/$chnl_output_dir_name/${chnl_playlist_name}.m3u8"
                                            fi
                                        fi
                                    else
                                        key=${b%:*}
                                        value=${b#*:}
                                        value="chnl_$value"

                                        if [ "$value" == "chnl_pid" ]
                                        then
                                            if [ -n "${new_pid:-}" ]
                                            then
                                                value=$new_pid
                                            else
                                                value=${!value:-}
                                            fi
                                        else
                                            value=${!value:-}
                                        fi
                                    fi

                                    if [[ -n "$value" ]] && [[ "$value" =~ ^[0-9]+$ ]]
                                    then
                                        jq_channel_new=$($JQ_FILE -c --arg k "$key" --arg v "$value" '.[$k] = ($v | tonumber)' <<< "$jq_channel_new")
                                    else
                                        jq_channel_new=$($JQ_FILE -c --arg k "$key" --arg v "$value" '.[$k] = $v' <<< "$jq_channel_new")
                                    fi
                                ;;
                            esac
                        done
                    done <<< "$chnl_sync_pairs"

                    if [ "$action" == "add" ] || [[ -z $($JQ_FILE --arg k "$chnl_pid_key" --arg p "$chnl_pid" "(${jq_index} // [])[] | select(.[\$k] == (\$p | tonumber))" "${chnl_sync_files[sync_i]}" 2> /dev/null) ]]
                    then
                        JQ add "${chnl_sync_files[sync_i]}" "[$jq_channel_new]"
                    else
                        jq_merge=true
                        JQ update "${chnl_sync_files[sync_i]}" "$chnl_pid_key" "$chnl_pid" "$jq_channel_new"
                    fi
                fi

                jq_path=""
            done

            Println "`eval_gettext \"\\\$info 频道 [ \\\$chnl_channel_name ] sync 执行成功...\"`"
        fi
        action=""
    }
    ParseIndexRange()
    {
        local _pir_input="${1:-}"
        local _pir_max="${2:-0}"
        local _pir_out_name="${3:-}"

        if [ -z "$_pir_input" ] || [[ ! $_pir_max =~ ^[0-9]+$ ]] || [ "$_pir_max" -lt 1 ]
        then
            return 1
        fi

        if [[ ! $_pir_out_name =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]]
        then
            return 1
        fi

        local -a _pir_tokens=()
        local -a _pir_res=()
        IFS=" " read -r -a _pir_tokens <<< "$_pir_input"

        if [ "${#_pir_tokens[@]}" -eq 0 ]
        then
            return 1
        fi

        local _pir_tok _pir_start _pir_end _pir_num _pir_i
        for _pir_tok in "${_pir_tokens[@]}"
        do
            if [[ $_pir_tok == *-* ]]
            then
                if [[ ! $_pir_tok =~ ^[0-9]+-[0-9]+$ ]]
                then
                    return 1
                fi

                _pir_start=$((10#${_pir_tok%-*}))
                _pir_end=$((10#${_pir_tok#*-}))

                if [ "$_pir_start" -lt 1 ] || [ "$_pir_end" -gt "$_pir_max" ] || [ "$_pir_start" -ge "$_pir_end" ]
                then
                    return 1
                fi

                for((_pir_i=_pir_start-1;_pir_i<_pir_end;_pir_i++));
                do
                    _pir_res+=("$_pir_i")
                done
            else
                if [[ ! $_pir_tok =~ ^[0-9]+$ ]]
                then
                    return 1
                fi

                _pir_num=$((10#$_pir_tok))

                if [ "$_pir_num" -lt 1 ] || [ "$_pir_num" -gt "$_pir_max" ]
                then
                    return 1
                fi

                _pir_res+=("$((_pir_num-1))")
            fi
        done

        if ! [[ $_pir_out_name =~ ^[a-zA-Z_][a-zA-Z0-9_]*$ ]]
        then
            return 1
        fi

        eval "$_pir_out_name=( \"\${_pir_res[@]+\"\${_pir_res[@]}\"}\" )"
        return 0
    }
    FFmpegResolvePidCollision()
    {
        local target_pid="$1"

        if [[ -n $($JQ_FILE '.channels[]|select(.pid=='"$target_pid"')' "$CHANNELS_FILE") ]]
        then
            true &
            local rand_pid=$!
            while [[ -n $($JQ_FILE '.channels[]|select(.pid=='"$rand_pid"')' "$CHANNELS_FILE") ]]
            do
                true &
                rand_pid=$!
            done

            jq_number=true
            jq_path='["channels"]'
            jq_path2='["pid"]'
            JQ update "$CHANNELS_FILE" pid "$target_pid" "$rand_pid"
        fi
    }

