    SetEncrypt()
    {
        echo
        if [ "$d_encrypt" = true ]
        then
            inquirer list_input "$(gettext "是否加密分片: ")" yn_options encrypt_yn
        else
            inquirer list_input "$(gettext "是否加密分片: ")" ny_options encrypt_yn
        fi

        if [ "$encrypt_yn" == "$i18n_yes" ]
        then
            encrypt=true
            OpensslInstall

            if [[ -x $(command -v openssl) ]]
            then
                Println "$(eval_gettext "\$tip 加密后只能通过网页浏览")"

                if [ "$d_encrypt_session" = false ]
                then
                    inquirer list_input "$(gettext "是否加密 session: ")" ny_options encrypt_session_text
                else
                    inquirer list_input "$(gettext "是否加密 session: ")" yn_options encrypt_session_text
                fi

                if [ "$encrypt_session_text" == "$i18n_yes" ]
                then
                    encrypt_session=true

                    if [ ! -d "$NGINX_PREFIX_DEFAULT" ] && [ ! -d "$OPENRESTY_PREFIX_DEFAULT" ]
                    then
                        echo
                        nginx_openresty_options=( 'nginx' 'openresty' "$(gettext "不安装")" )
                        inquirer list_input_index "$(gettext "选择安装 nginx 或 openresty, 耗时会很长: ")" nginx_openresty_options nginx_openresty_options_index

                        if [ "$nginx_openresty_options_index" -eq 0 ]
                        then
                            nginx_prefix="$NGINX_PREFIX_DEFAULT"
                            nginx_name="nginx"
                            nginx_ctl="nx"
                            NGINX_FILE="$nginx_prefix/sbin/nginx"
                            NginxInstall
                        elif [ "$nginx_openresty_options_index" -eq 1 ]
                        then
                            nginx_prefix="$OPENRESTY_PREFIX_DEFAULT/nginx"
                            nginx_name="openresty"
                            nginx_ctl="or"
                            NGINX_FILE="$nginx_prefix/sbin/nginx"
                            OpenrestyInstall
                        else
                            encrypt_session=false
                            encrypt_session_text="$i18n_no"
                        fi
                    fi

                    if [ -d "$NGINX_PREFIX_DEFAULT" ] || [ -d "$OPENRESTY_PREFIX_DEFAULT" ]
                    then
                        if [ -z "${nginx_name:-}" ]
                        then
                            if [ -d "$NGINX_PREFIX_DEFAULT" ] && [ -d "$OPENRESTY_PREFIX_DEFAULT" ]
                            then
                                echo
                                if [ -s "$OPENRESTY_PREFIX_DEFAULT/nginx/logs/nginx.pid" ] && kill -0 "$(< "$OPENRESTY_PREFIX_DEFAULT/nginx/logs/nginx.pid")" 2> /dev/null
                                then
                                    nginx_openresty_options=( 'openresty' 'nginx' )
                                else
                                    nginx_openresty_options=( 'nginx' 'openresty' )
                                fi
                                inquirer list_input "$(gettext "选择使用 nginx 或 openresty: ")" nginx_openresty_options nginx_openresty_selected
                                if [ "$nginx_openresty_selected" == "nginx" ]
                                then
                                    nginx_prefix="$NGINX_PREFIX_DEFAULT"
                                    nginx_name="nginx"
                                    nginx_ctl="nx"
                                else
                                    nginx_prefix="$OPENRESTY_PREFIX_DEFAULT/nginx"
                                    nginx_name="openresty"
                                    nginx_ctl="or"
                                fi
                            elif [ -d "$NGINX_PREFIX_DEFAULT" ]
                            then
                                nginx_prefix="$NGINX_PREFIX_DEFAULT"
                                nginx_name="nginx"
                                nginx_ctl="nx"
                            else
                                nginx_prefix="$OPENRESTY_PREFIX_DEFAULT/nginx"
                                nginx_name="openresty"
                                nginx_ctl="or"
                            fi
                            NGINX_FILE="$nginx_prefix/sbin/nginx"
                        fi

                        if [[ ! -x $(command -v node) ]] || [[ ! -x $(command -v npm) ]]
                        then
                            echo
                            inquirer list_input "$(gettext "需安装配置 nodejs, 是否继续: ")" yn_options encrypt_session_text
                            if [ "$encrypt_session_text" == "$i18n_yes" ]
                            then
                                NodejsInstall
                                if [[ -x $(command -v node) ]] && [[ -x $(command -v npm) ]]
                                then
                                    if [ ! -f "$NODE_ROOT/index.js" ]
                                    then
                                        MongodbInstall
                                        NodejsConfig
                                    fi
                                else
                                    encrypt_session=false
                                    encrypt_session_text="$i18n_no"
                                    Println "$(eval_gettext "\$error nodejs 安装发生错误")"
                                    Println "  $(gettext "加密 session"): ${green} $encrypt_session_text ${normal}"
                                fi
                            else
                                encrypt_session=false
                            fi
                        elif [ ! -f "$NODE_ROOT/index.js" ]
                        then
                            MongodbInstall
                            NodejsConfig
                        fi
                    fi
                else
                    encrypt_session=false
                fi
            fi
        else
            encrypt=false
            encrypt_session=false
        fi
    }

