    SetAntiDDosPort()
    {
        Println "$(gettext "设置封禁端口")"
        echo -e "$(eval_gettext "\$tip 多个端口用空格分隔 比如 22 80 443 12480-12489")"
        while read -p "$(eval_gettext "(默认: \$d_anti_ddos_port_text): ")" anti_ddos_ports
        do
            anti_ddos_ports=${anti_ddos_ports:-$d_anti_ddos_port_text}
            if [ -z "$anti_ddos_ports" ]
            then
                Println "$error $i18n_input_correct_number\n"
                continue
            fi

            IFS=" " read -ra anti_ddos_ports_arr <<< "$anti_ddos_ports"

            error_no=0
            for anti_ddos_port in "${anti_ddos_ports_arr[@]}"
            do
                case "$anti_ddos_port" in
                    *"-"*)
                        anti_ddos_ports_start=${anti_ddos_port%-*}
                        anti_ddos_ports_end=${anti_ddos_port#*-}
                        if [[ $anti_ddos_ports_start == *[!0-9]* ]] || [[ $anti_ddos_ports_end == *[!0-9]* ]] || [ "$anti_ddos_ports_start" -eq 0 ] || [ "$anti_ddos_ports_end" -eq 0 ] || [ "$anti_ddos_ports_start" -ge "$anti_ddos_ports_end" ]
                        then
                            error_no=3
                            break
                        fi
                    ;;
                    *[!0-9]*)
                        error_no=1
                        break
                    ;;
                    *)
                        if [ "$anti_ddos_port" -lt 1 ]
                        then
                            error_no=2
                            break
                        fi
                    ;;
                esac
            done

            case "$error_no" in
                1|2|3)
                    Println "$error $i18n_input_correct_number\n"
                ;;
                *)
                    anti_ddos_ports_command=""
                    anti_ddos_ports_range_command=""
                    for anti_ddos_port in "${anti_ddos_ports_arr[@]}"
                    do
                        if [[ $anti_ddos_port -eq 80 ]]
                        then
                            anti_ddos_port="http"
                        elif [[ $anti_ddos_port -eq 443 ]]
                        then
                            anti_ddos_port="https"
                        elif [[ $anti_ddos_port -eq 22 ]]
                        then
                            anti_ddos_port="ssh"
                        elif [[ $anti_ddos_port =~ - ]]
                        then
                            anti_ddos_ports_start=${anti_ddos_port%-*}
                            anti_ddos_ports_end=${anti_ddos_port#*-}
                            if [[ anti_ddos_ports_start -le 22 && $anti_ddos_ports_end -ge 22 ]]
                            then
                                [ -n "$anti_ddos_ports_command" ] && anti_ddos_ports_command="$anti_ddos_ports_command|"
                                anti_ddos_ports_command="${anti_ddos_ports_command}ssh"
                            elif [[ anti_ddos_ports_start -le 80 && $anti_ddos_ports_end -ge 80 ]]
                            then
                                [ -n "$anti_ddos_ports_command" ] && anti_ddos_ports_command="$anti_ddos_ports_command|"
                                anti_ddos_ports_command="${anti_ddos_ports_command}http"
                            elif [[ anti_ddos_ports_start -le 443 && $anti_ddos_ports_end -ge 443 ]]
                            then
                                [ -n "$anti_ddos_ports_command" ] && anti_ddos_ports_command="$anti_ddos_ports_command|"
                                anti_ddos_ports_command="${anti_ddos_ports_command}https"
                            fi
                            [ -n "$anti_ddos_ports_range_command" ] && anti_ddos_ports_range_command="$anti_ddos_ports_range_command || "
                            anti_ddos_ports_range_command=$anti_ddos_ports_range_command'($4 >= '"$anti_ddos_ports_start"' && $4 <= '"$anti_ddos_ports_end"')'
                            continue
                        fi

                        [ -n "$anti_ddos_ports_command" ] && anti_ddos_ports_command="$anti_ddos_ports_command|"
                        anti_ddos_ports_command="$anti_ddos_ports_command$anti_ddos_port"
                    done

                    [ -n "$anti_ddos_ports_command" ] && anti_ddos_ports_command='$4 ~ /^('"$anti_ddos_ports_command"')$/'
                    if [ -n "$anti_ddos_ports_range_command" ]
                    then
                        anti_ddos_ports_range_command='$4 ~ /^[0-9]+$/ && ('"$anti_ddos_ports_range_command"')'
                        [ -n "$anti_ddos_ports_command" ] && anti_ddos_ports_range_command=' || ('"$anti_ddos_ports_range_command"')'
                    fi
                    if [[ $anti_ddos_ports == *" "* ]] || [[ $anti_ddos_ports =~ - ]]
                    then
                        anti_ddos_port=${anti_ddos_ports// /,}
                        anti_ddos_port=${anti_ddos_port//-/:}
                        anti_ddos_port="$anti_ddos_port proto tcp"
                    else
                        anti_ddos_port=$anti_ddos_ports
                    fi
                    break
                ;;
            esac
        done
    }

    SetAntiDDosSynFlood()
    {
        echo
        if [ "$d_anti_ddos_syn_flood" = true ]
        then
            inquirer list_input "$(gettext "是否开启 SYN Flood attack 防御")" yn_options anti_ddos_syn_flood_yn
        else
            inquirer list_input "$(gettext "是否开启 SYN Flood attack 防御")" ny_options anti_ddos_syn_flood_yn
        fi

        if [ "$anti_ddos_syn_flood_yn" == "$i18n_yes" ]
        then
            anti_ddos_syn_flood=true
            sysctl -w net.ipv4.tcp_syn_retries=6 > /dev/null
            sysctl -w net.ipv4.tcp_synack_retries=2 > /dev/null
            sysctl -w net.ipv4.tcp_syncookies=1 > /dev/null
            sysctl -w net.ipv4.tcp_max_syn_backlog=1024 > /dev/null
            #iptables -A INPUT -p tcp --syn -m limit --limit 1/s -j ACCEPT --limit 1/s

            Println "$(gettext "设置判断为 SYN Flood attack 的时间 (秒)")"
            while read -p "$(eval_gettext "(默认: \$d_anti_ddos_syn_flood_delay_seconds 秒): ")" anti_ddos_syn_flood_delay_seconds
            do
                case $anti_ddos_syn_flood_delay_seconds in
                    "") anti_ddos_syn_flood_delay_seconds="$d_anti_ddos_syn_flood_delay_seconds" && break
                    ;;
                    *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                    ;;
                    *)
                        if [ "$anti_ddos_syn_flood_delay_seconds" -gt 0 ]
                        then
                            break
                        else
                            Println "$error $i18n_input_correct_number [>0]\n"
                        fi
                    ;;
                esac
            done

            Println "$(gettext "设置封禁 SYN Flood attack ip 多少秒")"
            while read -p "$(eval_gettext "(默认: \$d_anti_ddos_syn_flood_seconds 秒): ")" anti_ddos_syn_flood_seconds
            do
                case $anti_ddos_syn_flood_seconds in
                    "") anti_ddos_syn_flood_seconds="$d_anti_ddos_syn_flood_seconds" && break
                    ;;
                    *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                    ;;
                    *)
                        if [ "$anti_ddos_syn_flood_seconds" -gt 0 ]
                        then
                            break
                        else
                            Println "$error $i18n_input_correct_number  [>0]\n"
                        fi
                    ;;
                esac
            done
        else
            anti_ddos_syn_flood=false
        fi
    }

    SetAntiDDos()
    {
        echo
        if [ "$d_anti_ddos" = true ]
        then
            inquirer list_input "$(gettext "是否开启 iptv 防御")" yn_options anti_ddos_yn
        else
            inquirer list_input "$(gettext "是否开启 iptv 防御")" ny_options anti_ddos_yn
        fi

        if [ "$anti_ddos_yn" == "$i18n_yes" ]
        then
            anti_ddos=true

            Println "$(gettext "设置封禁用户 ip 多少秒")"
            while read -p "$(eval_gettext "(默认: \$d_anti_ddos_seconds 秒): ")" anti_ddos_seconds
            do
                case $anti_ddos_seconds in
                    "") anti_ddos_seconds="$d_anti_ddos_seconds" && break
                    ;;
                    *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                    ;;
                    *)
                        if [ "$anti_ddos_seconds" -gt 0 ]
                        then
                            break
                        else
                            Println "$error $i18n_input_correct_number  [>0]\n"
                        fi
                    ;;
                esac
            done

            Println "$(gettext "设置封禁等级(1-9)")"
            echo -e "$(eval_gettext "\$tip 数值越低越严格, 也越容易误伤, 很多情况是网络问题导致重复请求并非 DDoS")\n"
            while read -p "$(eval_gettext "(默认: \$d_anti_ddos_level): ")" anti_ddos_level
            do
                case $anti_ddos_level in
                    "")
                        anti_ddos_level="$d_anti_ddos_level"
                        break
                    ;;
                    *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                    ;;
                    *)
                        if [ "$anti_ddos_level" -gt 0 ] && [ "$anti_ddos_level" -lt 10 ]
                        then
                            break
                        else
                            Println "$error $i18n_input_correct_number [1-9]\n"
                        fi
                    ;;
                esac
            done
        else
            anti_ddos=false
        fi
    }

    SetAntiLeech()
    {
        echo
        if [ "$d_anti_leech" = true ]
        then
            inquirer list_input "$(gettext "是否开启防盗链")" yn_options anti_leech_yn
        else
            inquirer list_input "$(gettext "是否开启防盗链")" ny_options anti_leech_yn
        fi

        if [ "$anti_leech_yn" == "$i18n_yes" ]
        then
            anti_leech=true

            Println "$(gettext "请输入每小时随机重启次数 (大于等于0)")"
            while read -p "$(eval_gettext "(默认: \$d_anti_leech_restart_nums): ")" anti_leech_restart_nums
            do
                case $anti_leech_restart_nums in
                    "") anti_leech_restart_nums="$d_anti_leech_restart_nums" && break
                    ;;
                    *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                    ;;
                    *)
                        if [ "$anti_leech_restart_nums" -ge 0 ]
                        then
                            break
                        else
                            Println "$error $i18n_input_correct_number [>=0]\n"
                        fi
                    ;;
                esac
            done

            if [ "$anti_leech_restart_nums" -gt 0 ]
            then
                echo
                inquirer list_input "$(gettext "是否下个小时开始随机重启")" ny_options anti_leech_restart_next_hour_yn
                if [ "$anti_leech_restart_next_hour_yn" == "$i18n_yes" ]
                then
                    PrintfTime current_hour '%-H' -1
                    skip_hour=$current_hour
                    minutes=()
                fi
            fi

            echo
            if [ "$d_anti_leech_restart_flv_changes" = true ]
            then
                inquirer list_input "$(gettext "是否每当重启 FLV 频道更改成随机的推流和拉流地址")" yn_options anti_leech_restart_flv_changes_yn
            else
                inquirer list_input "$(gettext "是否每当重启 FLV 频道更改成随机的推流和拉流地址")" ny_options anti_leech_restart_flv_changes_yn
            fi

            if [ "$anti_leech_restart_flv_changes_yn" == "$i18n_yes" ]
            then
                anti_leech_restart_flv_changes=true
            else
                anti_leech_restart_flv_changes=false
            fi

            echo
            if [ "$d_anti_leech_restart_hls_changes" = true ]
            then
                inquirer list_input "$(gettext "是否每当重启 HLS 频道更改成随机的 m3u8 名称, 分片名称, key 名称")" yn_options anti_leech_restart_hls_changes_yn
            else
                inquirer list_input "$(gettext "是否每当重启 HLS 频道更改成随机的 m3u8 名称, 分片名称, key 名称")" ny_options anti_leech_restart_hls_changes_yn
            fi

            if [ "$anti_leech_restart_hls_changes_yn" == "$i18n_yes" ]
            then
                anti_leech_restart_hls_changes=true
            else
                anti_leech_restart_hls_changes=false
            fi

            SetHlsKeyPeriod
            hls_key_expire_seconds=$((hls_key_period+hls_delay_seconds))
        else
            anti_leech=false
            anti_leech_restart_nums="$d_anti_leech_restart_nums"
            anti_leech_restart_flv_changes="$d_anti_leech_restart_flv_changes"
            anti_leech_restart_hls_changes="$d_anti_leech_restart_hls_changes"
        fi
    }

    SetRecheckPeriod()
    {
        Println "$(gettext "设置重启频道失败后定时检查直播源(如可用即开启频道)的间隔时间(秒)")"
        echo -e "$(eval_gettext "\$tip 输入 0 关闭检查")"
        while read -p "$(eval_gettext "(默认: \$d_recheck_period_text): ")" recheck_period
        do
            case $recheck_period in
                "") recheck_period="$d_recheck_period" && break
                ;;
                *[!0-9]*) Println "$error $i18n_input_correct_number\n"
                ;;
                *)
                    if [ "$recheck_period" -ge 0 ]
                    then
                        break
                    else
                        Println "$error $i18n_input_correct_number [>=0]\n"
                    fi
                ;;
            esac
        done
    }

    SetFlvH265()
    {
        echo
        inquirer list_input_index "$(gettext "是否推流 h265")" ny_options ny_index
        if [ "$ny_index" -eq 0 ]
        then
            flv_h265=false
        else
            flv_h265=true
            FFmpegResolveBin 2> /dev/null || true
            FFmpegDetectCaps 2> /dev/null || true

            if [ "${FFMPEG_HAS_ENHANCED_FLV_HEVC:-false}" = false ] && [[ ! -x $(command -v ffmpeg_c) ]]
            then
                echo
                ffmpeg_c_options=( "$(gettext "快速安装")" "$(gettext "编译 FFmpeg (耗时非常非常久)")" )
                inquirer list_input_index "$(gettext "选择 FFmpeg (h265版本) 安装方式")" ffmpeg_c_options ffmpeg_c_options_index
                if [ "$ffmpeg_c_options_index" -eq 0 ]
                then
                    if curl -L "$FFMPEG_MIRROR_LINK/ffmpeg_c" -o "$AIOS_PREFIX"/bin/ffmpeg_c
                    then
                        chmod +x "$AIOS_PREFIX"/bin/ffmpeg_c
                    else
                        Println "$(eval_gettext "\$error 暂时无法连接服务器, 请稍后再试 !")\n"
                        exit 1
                    fi
                else
                    FFmpegCompile
                fi
            fi
        fi
    }

    SetFlvPushLink()
    {
        Println "$(eval_gettext "\$tip 比如 rtmp://127.0.0.1/flv/xxx , 如指向本机请确保已经安装 nginx 或 openresty")"
        local lbl_input_flv_push lbl_local_rand_addr lbl_flv_push_addr
        lbl_input_flv_push=$(gettext "请输入推流地址: ")
        lbl_local_rand_addr=$(gettext "本地随机地址")
        lbl_flv_push_addr=$(gettext "推流地址")
        while true
        do
            inquirer text_input "$lbl_input_flv_push" flv_push_link "$lbl_local_rand_addr"
            if [ "$flv_push_link" == "$lbl_local_rand_addr" ]
            then
                flv_push_link="rtmp://127.0.0.1/flv/$(RandStr)"
                until [[ -z $($JQ_FILE '.channels[] | select(.flv_push_link=="'"$flv_push_link"'")' "$CHANNELS_FILE") ]]
                do
                    flv_push_link=$(RandStr)
                done
                Println "  $lbl_flv_push_addr: ${green} $flv_push_link ${normal}\n"
                break
            elif [[ -z $($JQ_FILE '.channels[] | select(.flv_push_link=="'"$flv_push_link"'")' "$CHANNELS_FILE") ]]
            then
                break
            else
                Println "$(eval_gettext "\$error 推流地址已存在!请重新输入")\n"
            fi
        done
    }

    SetFlvPullLink()
    {
        if [ -n "${flv_push_link:-}" ]
        then
            d_flv_pull_link="http://127.0.0.1/flv?app=flv&stream=${flv_push_link##*/}"
        elif [ -n "${chnl_flv_push_link:-}" ]
        then
            d_flv_pull_link="http://127.0.0.1/flv?app=flv&stream=${chnl_flv_push_link##*/}"
        fi
        Println "$(eval_gettext "\$tip 比如 http://domain.com/flv?app=flv&stream=xxx 监控会验证此链接来确定是否重启频道, 如果不确定可以先留空, 可以输入 omit 省略此选项")"
        inquirer text_input "$(gettext "请输入拉流(播放)地址: ")" flv_pull_link "${d_flv_pull_link:-$i18n_blank}"
        if [ "$flv_pull_link" == "omit" ]
        then
            flv_pull_link=""
        fi
    }
    AddChannel()
    {
        [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请检查 !")\n" && exit 1

        use_primary_playlist=false

        GetDefault

        SetProxy
        SetUserAgent
        SetHeaders
        SetCookies

        SetStreamLink

        SetLive

        xc_proxy=${xc_proxy:-}
        if [[ $stream_link =~ ^http://([^/]+) ]] 
        then
            XtreamCodesGetDomains

            for xc_domain in "${xtream_codes_domains[@]}"
            do
                if [ "$xc_domain" == "${BASH_REMATCH[1]}" ] 
                then
                    SetXtreamCodesProxy
                    break
                fi
            done
        fi

        SetVideoCodec
        SetAudioCodec
        SetVideoAudioShift

        quality=""
        bitrate=""
        const=false
        const_cbr=false

        if [ "$video_codec" != "copy" ] 
        then
            SetQuality
            SetBitrate
        fi

        SetResolution

        if [ -n "$bitrate" ] 
        then
            SetConst
        fi

        draw_text=""

        if [ "${kind:-}" == "flv" ] 
        then
            if [ "$video_codec" != "copy" ] 
            then
                SetDrawtext
            fi

            SetFlvH265
            SetFlvPushLink
            SetFlvPullLink
            output_dir_name=$(RandOutputDirName)
            playlist_name=$(RandPlaylistName)
            seg_dir_name="$d_seg_dir_name"
            seg_name="$playlist_name"
            seg_length="$d_seg_length"
            seg_count="$d_seg_count"
            hls_end_list=false
            encrypt=false
            encrypt_session=false
            keyinfo_name=$(RandStr)
            key_name=$(RandStr)
            subtitle="[]"
        else
            SetSubtitle

            if [ "$video_codec" != "copy" ] 
            then
                SetDrawtext
            fi

            flv_h265=false
            flv_push_link=""
            flv_pull_link=""
            SetOutputDirName
            SetPlaylistName
            SetSegDirName
            SetSegName
            SetSegLength

            if [ "$live" = true ]
            then
                SetSegCount
            else
                seg_count="$d_seg_count"
            fi

            SetHlsEndList
            SetEncrypt

            if [ "$encrypt" = true ] 
            then
                SetKeyInfoName
                SetKeyName
            else
                keyinfo_name=$(RandStr)
                key_name=$(RandStr)
            fi
        fi

        output_dir_root="$LIVE_ROOT/$output_dir_name"

        if [ -n "$seg_dir_name" ] 
        then
            seg_dir_path="$seg_dir_name/"
        else
            seg_dir_path=""
        fi

        master=0
        if [ "${stream_url_qualities_count:-0}" -gt 0 ] 
        then
            if [[ $bitrate =~ , ]] || [[ $quality =~ , ]] || [[ $resolution =~ , ]] || [ "${stream_url_qualities_count:-0}" -gt 1 ] || [ "${stream_url_audio_count:-0}" -gt 0 ] || [ "${stream_url_subtitles_count:-0}" -gt 0 ] 
            then
                master=1
            fi
        elif [[ $bitrate =~ , ]] || [[ $quality =~ , ]] || [[ $resolution =~ , ]] || [ "$subtitle" != "[]" ]
        then
            master=1
        fi

        SetInputFlags
        SetOutputFlags
        SetChannelName
        SetSync

        sync_file=""
        sync_index=""
        sync_pairs=""

        if [ "$sync" = true ]
        then
            SetSyncFile
            SetSyncIndex
            SetSyncPairs
        fi

        FFmpegInstall

        if [[ ${input_flags:0:1} == "'" ]] 
        then
            input_flags=${input_flags%\'}
            input_flags=${input_flags#\'}
        fi
        if [[ ${output_flags:0:1} == "'" ]] 
        then
            output_flags=${output_flags%\'}
            output_flags=${output_flags#\'}
        fi

        [ ! -e "$FFMPEG_LOG_ROOT" ] && mkdir -p "$FFMPEG_LOG_ROOT"

        extra_filters=""
        if [ "$video_codec" != "copy" ] && [ -n "$draw_text" ] 
        then
            filters=( vf filter:v )
            for filter in "${filters[@]}"
            do
                if [[ $output_flags =~ (.*)"-$filter "([^ ]+)(.*) ]] 
                then
                    extra_filters="${BASH_REMATCH[2]},"
                    output_flags="${BASH_REMATCH[1]} ${BASH_REMATCH[3]}"
                fi
            done
        fi

        flags_command=( -flags )
        if [[ $output_flags =~ (.*)"-flags "([^ ]+)(.*) ]] 
        then
            flags="${BASH_REMATCH[2]}"

            if [[ $flags =~ global_header ]] 
            then
                flags_command=( -flags "$flags" )
            else
                flags_command+=("-global_header$flags")
            fi

            output_flags="${BASH_REMATCH[1]} ${BASH_REMATCH[3]}"
        else
            flags_command+=(-global_header)
        fi

        FilterString input_flags output_flags

        from="AddChannel"

        if [ -n "${kind:-}" ] 
        then
            if [ "$kind" == "flv" ] 
            then
                if [ "$sh_debug" = true ] 
                then
                    ( FlvStreamCreator ) 
                else
                    ( FlvStreamCreator ) > /dev/null 2> /dev/null < /dev/null &
                fi
            else
                Println "$(eval_gettext "\$error 暂不支持输出 \$kind ...")\n" && exit 1
            fi
        else
            if [ "$sh_debug" = true ] 
            then
                ( HlsStreamCreatorPlus ) 
            else
                ( HlsStreamCreatorPlus ) > /dev/null 2> /dev/null < /dev/null &
            fi
        fi

        stream_audio_url=()
        stream_subtitles_url=()
        stream_url_qualities_count=0
        stream_url_audio_count=0
        stream_url_subtitles_count=0
        stream_url_quality=""
        stream_url_cdn=""
        stream_link_parsed=false
        xc_proxy=""

        Println "$(eval_gettext "\$info 频道添加成功 !")\n"
    }
    EditStreamLink()
    {
        chnl_stream_links_list=""
        chnl_stream_links_options=()
        for((list_i=0;list_i<chnl_stream_links_count;list_i++));
        do
            chnl_stream_links_list="$chnl_stream_links_list ${green}$(gettext "源")$((list_i+1)).${normal}${indent_6}${chnl_stream_links[list_i]}\n\n"
            chnl_stream_links_options+=("$(gettext "源")$((list_i+1))")
        done

        Println "$chnl_stream_links_list"

        chnl_stream_links_actions=( "$i18n_add" )

        if [ "$chnl_stream_links_count" -gt 0 ] 
        then
            chnl_stream_links_actions+=( "$i18n_edit" "$i18n_delete" )

            if [ "$chnl_stream_links_count" -gt 1 ] 
            then
                chnl_stream_links_actions+=( "$(gettext "排序")" )
            fi
        fi

        inquirer list_input_index "$i18n_select_action" chnl_stream_links_actions chnl_stream_links_actions_index

        if [ "$chnl_stream_links_actions_index" -eq 0 ] 
        then
            Println "`eval_gettext \"\\\$tip 可以是视频路径, 可以输入不同链接地址(监控按顺序尝试使用), 用空格分隔\"`"
            ExitOnText "`gettext \"请输入直播源( mpegts / hls / flv / youtube ...): \"`" stream_links_input

            IFS=" " read -ra stream_links_add <<< "$stream_links_input"

            stream_link_parsed=true

            for stream_link in "${stream_links_add[@]}"
            do
                stream_links=("$stream_link")

                SetStreamLink

                chnl_stream_links+=("${stream_links[0]}")
            done

            stream_links=("${chnl_stream_links[@]}")
        elif [ "$chnl_stream_links_actions_index" -eq 1 ] 
        then
            echo
            inquirer checkbox_input_indices "$(gettext "选择修改的直播源")" chnl_stream_links_options chnl_stream_links_indices

            stream_link_parsed=true

            if [ -s "$XTREAM_CODES" ] 
            then
                IFS=" " read -r m_ip m_domains m_accounts < <(awk '$1 {a=a $1",";b=b $2",";$1=$2="";c=c substr($0,3)","} END {print a,b,c}' "$XTREAM_CODES")
                IFS="," read -r -a new_domains <<< "$m_domains"
                IFS="," read -r -a new_accounts <<< "$m_accounts"
                xc_count=${#new_domains[@]}
            fi

            for chnl_stream_links_index in "${chnl_stream_links_indices[@]}"
            do
                Println "$info $(gettext "修改源")$((chnl_stream_links_index+1)): ${chnl_stream_links[chnl_stream_links_index]}"

                xc_select=false

                if [ -s "$XTREAM_CODES" ] && [[ ${chnl_stream_links[chnl_stream_links_index]##*|} =~ ^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$ ]] 
                then
                    chnl_domain=${chnl_stream_links[chnl_stream_links_index]%%|*}
                    for((xc_i=0;xc_i<xc_count;xc_i++));
                    do
                        if [[ ${new_domains[xc_i]} =~ $chnl_domain ]] 
                        then
                            xc_macs=(${new_accounts[xc_i]} "$(gettext "输入mac")" "$(gettext "输入新的直播源")")
                            xc_macs_count=$((${#xc_macs[@]} - 2))
                            inquirer list_input_index "$i18n_select_action" xc_macs xc_macs_index

                            if [ "$xc_macs_index" -eq "$xc_macs_count" ]
                            then
                                ExitOnText "$(gettext "请输入mac: ")" new_mac
                                xc_select=true
                            elif [ "$xc_macs_index" -lt "$xc_macs_count" ]
                            then
                                new_mac="${xc_macs[xc_macs_index]}"
                                xc_select=true
                            fi
                            break
                        fi
                    done
                    
                fi

                if [ "$xc_select" = false ] 
                then
                    inquirer text_input "$(gettext "输入新的直播源( mpegts / hls / flv / youtube ...): ")" stream_link "$i18n_blank"
                else
                    stream_link="${chnl_stream_links[chnl_stream_links_index]//${chnl_stream_links[chnl_stream_links_index]##*|}/$new_mac}"
                fi

                if [ -z "$stream_link" ] 
                then
                    continue
                fi

                stream_links=("$stream_link")

                SetStreamLink

                chnl_stream_links[chnl_stream_links_index]="${stream_links[0]}"
            done

            stream_links=("${chnl_stream_links[@]}")
        elif [ "$chnl_stream_links_actions_index" -eq 2 ]
        then
            echo
            inquirer checkbox_input_indices "$(gettext "选择删除的直播源")" chnl_stream_links_options chnl_stream_links_indices

            for chnl_stream_links_index in "${chnl_stream_links_indices[@]}"
            do
                unset 'chnl_stream_links[chnl_stream_links_index]'
            done

            stream_links=("${chnl_stream_links[@]}")
        elif [ "$chnl_stream_links_actions_index" -eq 3 ] 
        then
            echo
            inquirer sort_input_indices "$(gettext "排序直播源")" chnl_stream_links_options chnl_stream_links_indices

            declare -a new_array
            for chnl_stream_links_index in "${chnl_stream_links_indices[@]}"
            do
                new_array+=("${chnl_stream_links[chnl_stream_links_index]}")
            done

            stream_links=("${new_array[@]}")

            unset new_array
        fi

        jq_file=true
        jq_path='["channels",'"$chnls_index"',"stream_link"]'
        JQ update "$CHANNELS_FILE" stream_links
        Println "$(eval_gettext "\$info 直播源修改成功 !")\n"
    }

    EditLive()
    {
        SetLive
        jq_bool=true
        jq_path='["channels",'"$chnls_index"',"live"]'
        JQ update "$CHANNELS_FILE" "$live"
        Println "$(eval_gettext "\$info 无限时长直播修改成功 !")\n"
    }

