        done

        PrintfTime today '%Y%m%d' -1
        yesterday=$(date --date="yesterday" +"%Y%m%d")
        tomorrow=$(date --date="tomorrow" +"%Y%m%d")

        chnls_sid=""

        for chnl in "${sky_chnls[@]}"
        do
            sk_sid="${chnl#*:}"
            sk_sid="${sk_sid%%:*}"
            [ -n "$chnls_sid" ] && chnls_sid="$chnls_sid,"
            chnls_sid="$chnls_sid$sk_sid"
        done

        sk_yesterday_schedule=$(curl -s -Lm 20 -H "User-Agent: $USER_AGENT_BROWSER" "https://awk.epgsky.com/hawk/linear/schedule/$yesterday/$chnls_sid")
        sk_today_schedule=$(curl -s -Lm 20 -H "User-Agent: $USER_AGENT_BROWSER" "https://awk.epgsky.com/hawk/linear/schedule/$today/$chnls_sid")

        if [ "$search_options_index" -eq 2 ] 
        then
            sk_tomorrow_schedule=$(curl -s -Lm 20 -H "User-Agent: $USER_AGENT_BROWSER" "https://awk.epgsky.com/hawk/linear/schedule/$tomorrow/$chnls_sid")
        fi

        for chnl in "${sky_chnls[@]}"
        do
            chnl_id=${chnl%%:*}
            sk_sid="${chnl#*:}"
            chnl_name="${sk_sid#*:}"
            sk_sid=${sk_sid%%:*}

            yesterday_schedule=$($JQ_FILE --arg sid "$sk_sid" --arg min "$min_start_time" --arg max "$max_start_time" --argjson keys '["title","time","start_time","end_time"]' '.schedule | map(select(.sid == $sid).events[] | select((.st|tonumber) > ($min|tonumber) and (.st|tonumber) < ($max|tonumber) and (.t|test(" v ";"i"))) | .["time"] = (.st|strflocaltime("%Y-%m-%d %H:%M %p")) | .["start_time"] = .st | .["end_time"] = (.st + .d) | .["title"] = .t | with_entries(select(.key as $k | $keys | index($k))))' <<< "$sk_yesterday_schedule")
            today_schedule=$($JQ_FILE --arg sid "$sk_sid" --arg min "$min_start_time" --arg max "$max_start_time" --argjson keys '["title","time","start_time","end_time"]' '.schedule | map(select(.sid == $sid).events[] | select((.st|tonumber) > ($min|tonumber) and (.st|tonumber) < ($max|tonumber) and (.t|test(" v ";"i"))) | .["time"] = (.st|strflocaltime("%Y-%m-%d %H:%M %p")) | .["start_time"] = .st | .["end_time"] = (.st + .d) | .["title"] = .t | with_entries(select(.key as $k | $keys | index($k))))' <<< "$sk_today_schedule")

            if [ "$search_options_index" -lt 2 ] 
            then
                schedule=$($JQ_FILE --argjson today "$today_schedule" '.+=$today' <<< "$yesterday_schedule")
            else
                tomorrow_schedule=$($JQ_FILE --arg sid "$sk_sid" --arg max "$max_start_time" --argjson keys '["title","time","start_time","end_time"]' '.schedule | map(select(.sid == $sid).events[] | select((.st|tonumber) < ($max|tonumber) and (.t|test(" v ";"i"))) | .["time"] = (.st|strflocaltime("%Y-%m-%d %H:%M %p")) | .["start_time"] = .st | .["end_time"] = (.st + .d) | .["title"] = .t | with_entries(select(.key as $k | $keys | index($k))))' <<< "$sk_tomorrow_schedule")

                schedule=$($JQ_FILE --argjson today "$today_schedule" --argjson tomorrow "$tomorrow_schedule" '.+=$today|.+=$tomorrow' <<< "$yesterday_schedule")
            fi

            if [ "$schedule" == "[]" ]
            then
                continue
            fi

            ParseSchedule
        done
    }
    AddChannelsSchedule()
    {
        echo
        add_options=( "$(gettext "手动添加")" "$(gettext "足球比赛")" )
        inquirer list_input_index "$i18n_select_action" add_options add_options_index

        if [ "$add_options_index" -eq 1 ] 
        then
            echo
            search_options=( "$(gettext "12小时内")" "$(gettext "今天")" "$(gettext "今明两天")" )
            inquirer list_input_index "$(gettext "搜索范围")" search_options search_options_index

            Progress "$(gettext "搜索足球节目表")" &
            progress_pid=$!

            trap '
                kill $progress_pid
                wait $progress_pid 2> /dev/null
            ' EXIT

            SearchSoccerSchedules

            schedules_count=${#schedules_chnl_id[@]}

            for((i=0;i<schedules_count;i++));
            do
                flag=0

                for((j=0;j<schedules_count-i-1;j++));
                do
                    if [ "${schedules_start_time[j]}" -gt "${schedules_start_time[j+1]}" ] 
                    then
                        temp="${schedules_start_time[j]}"
                        schedules_start_time[j]="${schedules_start_time[j+1]}"
                        schedules_start_time[j+1]="$temp"
                        temp="${schedules_end_time[j]}"
                        schedules_end_time[j]="${schedules_end_time[j+1]}"
                        schedules_end_time[j+1]="$temp"
                        temp="${schedules_chnl_id[j]}"
                        schedules_chnl_id[j]="${schedules_chnl_id[j+1]}"
                        schedules_chnl_id[j+1]="$temp"
                        temp="${schedules_title[j]}"
                        schedules_title[j]="${schedules_title[j+1]}"
                        schedules_title[j+1]="$temp"
                        temp="${schedules_list[j]}"
                        schedules_list[j]="${schedules_list[j+1]}"
                        schedules_list[j+1]="$temp"
                        flag=1
                    fi
                done

                if [ "$flag" -eq 0 ] 
                then
                    break
                fi
            done

            kill $progress_pid
            wait $progress_pid 2> /dev/null || true
            trap - EXIT
            echo "...100%"

            echo
            inquirer checkbox_input_indices "$(gettext "选择比赛")" schedules_list schedules_indices

            GetChannels
            chnls_indices=("${!chnls_pid[@]}")

            local lbl_schedule lbl_start_date lbl_end_date lbl_daily_loop lbl_auto_remove lbl_anti_leech lbl_anti_leech_once lbl_input_chnl_name
            lbl_schedule=$(gettext "计划")
            lbl_start_date=$(gettext "设置开始日期")
            lbl_end_date=$(gettext "设置结束日期")
            lbl_daily_loop=$(gettext "每日循环")
            lbl_auto_remove=$(gettext "结束后自动清除")
            lbl_anti_leech=$(gettext "防盗链")
            lbl_anti_leech_once=$(gettext "防盗链一次")
            lbl_input_chnl_name=$(gettext "输入频道名称")

            for schedules_index in "${schedules_indices[@]}"
            do
                Println "$info $i18n_add ${schedules_list[schedules_index]} $lbl_schedule"

                schedule_chnl_id="${schedules_chnl_id[schedules_index]}"
                schedule_start_time="${schedules_start_time[schedules_index]}"
                schedule_end_time="${schedules_end_time[schedules_index]}"
                schedule_title="${schedules_title[schedules_index]}"

                for chnls_index in "${chnls_indices[@]}"
                do
                    if [ "${chnls_output_dir_name[chnls_index]}" == "$schedule_chnl_id" ]
                    then
                        ListChannelSchedules

                        inquirer date_pick "$lbl_start_date" schedule_start_time

                        echo
                        inquirer date_pick "$lbl_end_date" schedule_end_time

                        echo
                        inquirer list_input_index "$lbl_daily_loop" ny_options ny_index

                        if [ "$ny_index" -eq 0 ]
                        then
                            schedule_loop=false

                            echo
                            inquirer list_input_index "$lbl_auto_remove" ny_options ny_index

                            if [ "$ny_index" -eq 0 ]
                            then
                                schedule_auto_remove=false
                            else
                                schedule_auto_remove=true
                            fi
                        else
                            schedule_loop=true
                            schedule_auto_remove=false
                        fi

                        echo
                        inquirer list_input_index "$lbl_anti_leech" yn_options yn_index

                        if [ "$yn_index" -eq 0 ]
                        then
                            schedule_hls_change=true

                            echo
                            inquirer list_input_index "$lbl_anti_leech_once" ny_options yn_index

                            if [ "$yn_index" -eq 0 ]
                            then
                                schedule_hls_change_once=false
                            else
                                schedule_hls_change_once=true
                            fi
                        else
                            schedule_hls_change=false
                            schedule_hls_change_once=false
                        fi

                        echo
                        inquirer text_input "$lbl_input_chnl_name" schedule_channel_name "$schedule_title"

                        chnl_schedule=$(
                            $JQ_FILE -n --arg start_time "$schedule_start_time" \
                                --arg end_time "$schedule_end_time" \
                                --arg loop "$schedule_loop" \
                                --arg auto_remove "$schedule_auto_remove" \
                                --arg hls_change "$schedule_hls_change" \
                                --arg hls_change_once "$schedule_hls_change_once" \
                                --arg channel_name "$schedule_channel_name" \
                                --arg status 0 \
                            '{
                                start_time: $start_time | tonumber,
                                end_time: $end_time | tonumber,
                                loop: $loop | test("true"),
                                auto_remove: $auto_remove | test("true"),
                                hls_change: $hls_change | test("true"),
                                hls_change_once: $hls_change_once | test("true"),
                                channel_name: $channel_name,
                                status: $status | tonumber
                            }'
                        )

                        jq_path='["channels",'"$chnls_index"',"schedule"]'
                        JQ add "$CHANNELS_FILE" "[$chnl_schedule]"

                        Println "$(eval_gettext "\$info 频道 [ \$schedule_channel_name ] 计划添加成功")\n"

                        continue 2
                    fi
                done

                Println "$(eval_gettext "\$error 未找到输出目录为 [ \$schedule_chnl_id ] 的频道, 请添加频道")"
            done

            return 0
        fi

        ListChannels
        InputChannelsIndex

        local lbl_start_date lbl_end_date lbl_daily_loop lbl_auto_remove lbl_anti_leech lbl_anti_leech_once lbl_input_chnl_name lbl_channel lbl_sched_added lbl_continue_add
        lbl_start_date=$(gettext "设置开始日期")
        lbl_end_date=$(gettext "设置结束日期")
        lbl_daily_loop=$(gettext "每日循环")
        lbl_auto_remove=$(gettext "结束后自动清除")
        lbl_anti_leech=$(gettext "防盗链")
        lbl_anti_leech_once=$(gettext "防盗链一次")
        lbl_input_chnl_name=$(gettext "输入频道名称")
        lbl_channel=$(gettext "频道")
        lbl_sched_added=$(gettext "计划添加成功")
        lbl_continue_add=$(gettext "是否继续添加此频道计划")

        for chnls_index in "${chnls_indices[@]}"
        do
            ListChannelSchedules

            while true
            do
                inquirer date_pick "$lbl_start_date" schedule_start_time

                echo
                inquirer date_pick "$lbl_end_date" schedule_end_time

                echo
                inquirer list_input_index "$lbl_daily_loop" ny_options ny_index

                if [ "$ny_index" -eq 0 ]
                then
                    schedule_loop=false

                    echo
                    inquirer list_input_index "$lbl_auto_remove" ny_options ny_index

                    if [ "$ny_index" -eq 0 ]
                    then
                        schedule_auto_remove=false
                    else
                        schedule_auto_remove=true
                    fi
                else
                    schedule_loop=true
                    schedule_auto_remove=false
                fi

                echo
                inquirer list_input_index "$lbl_anti_leech" yn_options yn_index

                if [ "$yn_index" -eq 0 ]
                then
                    schedule_hls_change=true

                    echo
                    inquirer list_input_index "$lbl_anti_leech_once" ny_options yn_index

                    if [ "$yn_index" -eq 0 ]
                    then
                        schedule_hls_change_once=false
                    else
                        schedule_hls_change_once=true
                    fi
                else
                    schedule_hls_change=false
                    schedule_hls_change_once=false
                fi

                echo
                inquirer text_input "$lbl_input_chnl_name" schedule_channel_name "$i18n_blank"

                chnl_schedule=$(
                    $JQ_FILE -n --arg start_time "$schedule_start_time" \
                        --arg end_time "$schedule_end_time" \
                        --arg loop "$schedule_loop" \
                        --arg auto_remove "$schedule_auto_remove" \
                        --arg hls_change "$schedule_hls_change" \
                        --arg hls_change_once "$schedule_hls_change_once" \
                        --arg channel_name "$schedule_channel_name" \
                        --arg status 0 \
                    '{
                        start_time: $start_time | tonumber,
                        end_time: $end_time | tonumber,
                        loop: $loop | test("true"),
                        auto_remove: $auto_remove | test("true"),
                        hls_change: $hls_change | test("true"),
                        hls_change_once: $hls_change_once | test("true"),
                        channel_name: $channel_name,
                        status: $status | tonumber
                    }'
                )

                jq_path='["channels",'"$chnls_index"',"schedule"]'
                JQ add "$CHANNELS_FILE" "[$chnl_schedule]"

                Println "$info $lbl_channel [ ${schedule_channel_name:-${chnls_channel_name[chnls_index]}} ] $lbl_sched_added\n"

                echo
                inquirer list_input_index "$lbl_continue_add" ny_options ny_index

                if [ "$ny_index" -eq 0 ]
                then
                    break
                fi

                echo
            done
        done

        echo
    }
    EditChannelSchedule()
    {
        echo
        channel_schedule_options=( "$(gettext "开始日期")" "$(gettext "结束日期")" "$(gettext "循环")" "$(gettext "自动清除")" "$(gettext "防盗链")" "$(gettext "频道名称")" "$i18n_status" )
        inquirer checkbox_input_indices "$i18n_select_edit [ ${chnl_schedules_channel_name[chnl_schedules_index]:-${chnls_channel_name[chnls_index]}} ] $(gettext "计划") $((chnl_schedules_index+1))" channel_schedule_options channel_schedule_options_indices

        for channel_schedule_options_index in "${channel_schedule_options_indices[@]}"
        do
            echo
            if [ "$channel_schedule_options_index" -eq 0 ] 
            then
                inquirer date_pick "$(gettext "设置开始日期")" schedule_start_time

                jq_number=true
                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"start_time"]'
                JQ update "$CHANNELS_FILE" "$schedule_start_time"
            elif [ "$channel_schedule_options_index" -eq 1 ] 
            then
                inquirer date_pick "$(gettext "设置结束日期")" schedule_end_time

                jq_number=true
                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"end_time"]'
                JQ update "$CHANNELS_FILE" "$schedule_end_time"
            elif [ "$channel_schedule_options_index" -eq 2 ] 
            then
                inquirer list_input_index "$(gettext "每日循环")" ny_options ny_index

                if [ "$ny_index" -eq 0 ] 
                then
                    schedule_loop=false
                else
                    schedule_loop=true
                fi

                jq_bool=true
                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"loop"]'
                JQ update "$CHANNELS_FILE" "$schedule_loop"
            elif [ "$channel_schedule_options_index" -eq 3 ] 
            then
                inquirer list_input_index "$(gettext "自动清除")" ny_options ny_index

                if [ "$ny_index" -eq 0 ] 
                then
                    schedule_auto_remove=false
                else
                    schedule_auto_remove=true
                fi

                jq_bool=true
                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"auto_remove"]'
                JQ update "$CHANNELS_FILE" "$schedule_auto_remove"
            elif [ "$channel_schedule_options_index" -eq 4 ] 
            then
                inquirer list_input_index "$(gettext "防盗链")" yn_options yn_index

                if [ "$yn_index" -eq 0 ] 
                then
                    schedule_hls_change=true

                    echo
                    inquirer list_input_index "$(gettext "防盗链一次")" ny_options yn_index

                    if [ "$yn_index" -eq 0 ] 
                    then
                        schedule_hls_change_once=false
                    else
                        schedule_hls_change_once=true
                    fi
                else
                    schedule_hls_change=false
                    schedule_hls_change_once=false
                fi

                jq_bool=true
                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"hls_change"]'
                JQ update "$CHANNELS_FILE" "$schedule_hls_change"

                jq_bool=true
                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"hls_change_once"]'
                JQ update "$CHANNELS_FILE" "$schedule_hls_change_once"
            elif [ "$channel_schedule_options_index" -eq 5 ] 
            then
                inquirer text_input "$(gettext "输入频道名称")" schedule_channel_name "$i18n_blank"

                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"channel_name"]'
                JQ update "$CHANNELS_FILE" "$schedule_channel_name"

                if [ -n "$schedule_channel_name" ] && [ "${chnl_schedules_status[chnl_schedules_index]}" -eq 1 ] && [ "$schedule_channel_name" != "${chnls_channel_name[chnls_index]}" ]
                then
                    echo
                    inquirer list_input_index "$(gettext "同步频道名称")" ny_options ny_index

                    if [ "$ny_index" -eq 1 ] 
                    then
                        jq_path='["channels",'"$chnls_index"',"channel_name"]'
                        JQ update "$CHANNELS_FILE" "$schedule_channel_name"

                        chnl_pid="${chnls_pid[chnls_index]}"
                        GetChannel

                        if [ -f "$chnl_output_dir_root/${chnl_playlist_name}_master.m3u8" ]
                        then
                            master=1
                        else
                            master=0
                        fi

                        action="start"
                        SyncFile
                    fi
                fi
            elif [ "$channel_schedule_options_index" -eq 6 ] 
            then
                schedule_status_options=( "$(gettext "等待")" "$(gettext "进行")" "$(gettext "结束")" )
                inquirer list_input_index "$(gettext "设置状态")" schedule_status_options schedule_status

                jq_number=true
                jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"',"status"]'
                JQ update "$CHANNELS_FILE" "$schedule_status"
            fi
        done

        Println "$info $(gettext "频道") [ ${chnl_schedules_channel_name[chnl_schedules_index]:-${chnls_channel_name[chnls_index]}} ] $(gettext "计划") $((chnl_schedules_index+1)) $(gettext "修改成功")\n"
    }

    EditChannelSchedules()
    {
        ListChannelSchedules

        echo -e "  ${green}$((chnl_schedules_count+1)).${normal}${indent_6}$i18n_all\n\n"

        echo "$(gettext "输入计划序号(多个计划用空格分隔 比如: 1 2 4-5)")"
        while read -p "$i18n_default_cancel" chnl_schedules_num
        do
            if [ -z "$chnl_schedules_num" ] 
            then
                Println "$i18n_canceled...\n" && break
            fi

            if [ "$chnl_schedules_num" == $((chnl_schedules_count+1)) ] 
            then
                for chnl_schedules_index in "${chnl_schedules_indices[@]}"
                do
                    EditChannelSchedule
                done
                break
            fi

            IFS=" " read -ra chnl_schedules_num_arr <<< "$chnl_schedules_num"

            error_no=0
            for chnl_schedule_num in "${chnl_schedules_num_arr[@]}"
            do
                case "$chnl_schedule_num" in
                    *"-"*)
                        chnl_schedule_num_start=${chnl_schedule_num%-*}
                        chnl_schedule_num_end=${chnl_schedule_num#*-}
                        if [[ $chnl_schedule_num_start == *[!0-9]* ]] || [[ $chnl_schedule_num_end == *[!0-9]* ]] || [ "$chnl_schedule_num_start" -eq 0 ] || [ "$chnl_schedule_num_end" -eq 0 ] || [ "$chnl_schedule_num_end" -gt "$chnl_schedules_count" ] || [ "$chnl_schedule_num_start" -ge "$chnl_schedule_num_end" ]
                        then
                            error_no=3
                            break
                        fi
                    ;;
                    *[!0-9]*)
                        error_no=1
                        break
                    ;;
                    *)
                        if [ "$chnl_schedule_num" -lt 1 ] || [ "$chnl_schedule_num" -gt "$chnl_schedules_count" ] 
                        then
                            error_no=2
                            break
                        fi
                    ;;
                esac
            done

            case "$error_no" in
                1|2|3)
                    Println "$error $i18n_input_correct_number\n"
                ;;
                *)
                    for chnl_schedule_num in "${chnl_schedules_num_arr[@]}"
                    do
                        if [[ $chnl_schedule_num =~ - ]] 
                        then
                            chnl_schedules_start=${chnl_schedule_num%-*}
                            chnl_schedules_end=${chnl_schedule_num#*-}
                            for((chnl_schedules_index=chnl_schedules_start-1;chnl_schedules_index<chnl_schedules_end;chnl_schedules_index++));
                            do
                                EditChannelSchedule
                            done
                        else
                            chnl_schedules_index=$((chnl_schedule_num-1))
                            EditChannelSchedule
                        fi
                    done
                    break
                ;;
            esac
        done
    }

    EditChannelsSchedule()
    {
        ListChannelsSchedule

        if [ -z "$chnls_schedule_list" ] 
        then
            Println "$(eval_gettext "\$error 请先添加频道计划")\n"
            exit 1
        fi

        echo -e "  ${green}$((chnls_count+1)).${normal}${indent_6}$i18n_all\n\n"

        echo "$(gettext "输入频道序号(多个频道用空格分隔 比如: 1 2 4-5)")"
        while read -p "$i18n_default_cancel" chnls_num
        do
            if [ -z "$chnls_num" ] 
            then
                Println "$i18n_canceled...\n" && exit 1
            fi

            if [ "$chnls_num" == $((chnls_count+1)) ] 
            then
                for chnls_index in "${chnls_schedule_indices[@]}"
                do
                    EditChannelSchedules
                done
                break
            fi

            IFS=" " read -ra chnls_num_arr <<< "$chnls_num"

            error_no=0
            for chnl_num in "${chnls_num_arr[@]}"
            do
                case "$chnl_num" in
                    *"-"*)
                        chnl_num_start=${chnl_num%-*}
                        chnl_num_end=${chnl_num#*-}
                        if [[ $chnl_num_start == *[!0-9]* ]] || [[ $chnl_num_end == *[!0-9]* ]] || [ "$chnl_num_start" -eq 0 ] || [ "$chnl_num_end" -eq 0 ] || [ "$chnl_num_end" -gt "$chnls_count" ] || [ "$chnl_num_start" -ge "$chnl_num_end" ]
                        then
                            error_no=3
                            break
                        else
                            for((i=chnl_num_start-1;i<chnl_num_end;i++));
                            do
                                if [ -z "${chnls_schedule_status[i]}" ] 
                                then
                                    error_no=3
                                    break 2
                                fi
                            done
                        fi
                    ;;
                    *[!0-9]*)
                        error_no=1
                        break
                    ;;
                    *)
                        if [ "$chnl_num" -lt 1 ] || [ "$chnl_num" -gt "$chnls_count" ] || [ -z "${chnls_schedule_status[chnl_num-1]}" ]
                        then
                            error_no=2
                            break
                        fi
                    ;;
                esac
            done

            case "$error_no" in
                1|2|3)
                    Println "$error $i18n_input_correct_number\n"
                ;;
                *)
                    for chnl_num in "${chnls_num_arr[@]}"
                    do
                        if [[ $chnl_num =~ - ]] 
                        then
                            chnls_start=${chnl_num%-*}
                            chnls_end=${chnl_num#*-}
                            for((chnls_index=chnls_start-1;chnls_index<chnls_end;chnls_index++));
                            do
                                EditChannelSchedules
                            done
                        else
                            chnls_index=$((chnl_num-1))
                            EditChannelSchedules
                        fi
                    done
                    break
                ;;
            esac
        done
    }
    SortChannelSchedules()
    {
        IFS="${delimiters[4]}" read -ra chnl_schedules_start_time <<< "${chnls_schedule_start_time[chnls_index]}"
        IFS="${delimiters[4]}" read -ra chnl_schedules_end_time <<< "${chnls_schedule_end_time[chnls_index]}"
        IFS="${delimiters[4]}" read -ra chnl_schedules_loop <<< "${chnls_schedule_loop[chnls_index]}"
        IFS="${delimiters[4]}" read -ra chnl_schedules_auto_remove <<< "${chnls_schedule_auto_remove[chnls_index]}"
        IFS="${delimiters[4]}" read -ra chnl_schedules_hls_change <<< "${chnls_schedule_hls_change[chnls_index]}"
        IFS="${delimiters[4]}" read -ra chnl_schedules_hls_change_once <<< "${chnls_schedule_hls_change_once[chnls_index]}"
        IFS="${delimiters[4]}" read -ra chnl_schedules_status <<< "${chnls_schedule_status[chnls_index]}"

        chnl_schedules_count=${#chnl_schedules_status[@]}

        if [ "$chnl_schedules_count" -eq 1 ] 
        then
            Println "$error $(gettext "频道") [ ${chnls_channel_name[chnls_index]} ] $(gettext "计划只有一个")"
            return 0
        fi

        IFS="${delimiters[4]}" read -ra chnl_schedules_channel_name <<< "${chnls_schedule_channel_name[chnls_index]}"

        chnl_schedules_indices=("${!chnl_schedules_status[@]}")
        chnl_schedules_list="${indent_6}${dim_underlined}${chnls_channel_name[chnls_index]}${normal}\n\n"
        chnl_schedules_options=()

        local lbl_wait lbl_running lbl_ended lbl_once lbl_channel_name lbl_schedule lbl_anti_leech lbl_loop lbl_auto_remove lbl_start_time lbl_end_time
        lbl_wait=$(gettext "等待")
        lbl_running=$(gettext "进行")
        lbl_ended=$(gettext "结束")
        lbl_once=$(gettext "一次")
        lbl_channel_name=$(gettext "频道名称")
        lbl_schedule=$(gettext "计划")
        lbl_anti_leech=$(gettext "防盗链")
        lbl_loop=$(gettext "循环")
        lbl_auto_remove=$(gettext "自动清除")
        lbl_start_time=$(gettext "开始时间")
        lbl_end_time=$(gettext "结束时间")

        for chnl_schedules_index in "${chnl_schedules_indices[@]}"
        do
            if [ "${chnl_schedules_status[chnl_schedules_index]}" -eq 0 ]
            then
                chnl_schedule_status_list="${green}$lbl_wait${normal}"
            elif [ "${chnl_schedules_status[chnl_schedules_index]}" -eq 1 ]
            then
                chnl_schedule_status_list="${blue}$lbl_running${normal}"
            else
                chnl_schedule_status_list="${red}$lbl_ended${normal}"
            fi

            if [ "${chnl_schedules_hls_change_once[chnl_schedules_index]}" = true ]
            then
                chnl_schedule_hls_change_list="${green}$lbl_once${normal}"
            elif [ "${chnl_schedules_hls_change[chnl_schedules_index]}" = true ]
            then
                chnl_schedule_hls_change_list="${green}$i18n_yes${normal}"
            else
                chnl_schedule_hls_change_list="${red}$i18n_no${normal}"
            fi

            if [ "${chnl_schedules_loop[chnl_schedules_index]}" = true ]
            then
                chnl_schedule_loop_list="${green}$i18n_yes${normal}"
            else
                chnl_schedule_loop_list="${red}$i18n_no${normal}"
            fi

            if [ "${chnl_schedules_auto_remove[chnl_schedules_index]}" = true ]
            then
                chnl_schedule_auto_remove_list="${green}$i18n_yes${normal}"
            else
                chnl_schedule_auto_remove_list="${red}$i18n_no${normal}"
            fi

            if [ -n "${chnl_schedules_channel_name[chnl_schedules_index]}" ]
            then
                chnl_schedule_channel_name_list="${indent_6}$lbl_channel_name: ${blue}${chnl_schedules_channel_name[chnl_schedules_index]}${normal}\n"
            else
                chnl_schedule_channel_name_list=""
            fi
            chnl_schedules_options+=("$lbl_schedule$((chnl_schedules_index+1))")
            chnl_schedules_list="$chnl_schedules_list  ${green}$((chnl_schedules_index+1)).${normal}${indent_6}$i18n_status: $chnl_schedule_status_list${indent_20}$lbl_anti_leech: $chnl_schedule_hls_change_list\n${indent_6}$lbl_loop: $chnl_schedule_loop_list${indent_20}$lbl_auto_remove: $chnl_schedule_auto_remove_list\n$chnl_schedule_channel_name_list${indent_6}$lbl_start_time: $(FormatEpoch "${chnl_schedules_start_time[chnl_schedules_index]}" '+%c')\n${indent_6}$lbl_end_time: $(FormatEpoch "${chnl_schedules_end_time[chnl_schedules_index]}" '+%c')\n\n"
        done

        Println "$chnl_schedules_list"

        echo
        inquirer sort_input_indices "$(gettext "排序计划")" chnl_schedules_options chnl_schedules_indices

        new_schedules=()

        for chnl_schedules_index in "${chnl_schedules_indices[@]}"
        do
            new_schedule=$(
                $JQ_FILE -n --arg start_time "${chnl_schedules_start_time[chnl_schedules_index]}" \
                    --arg end_time "${chnl_schedules_end_time[chnl_schedules_index]}" \
                    --arg loop "${chnl_schedules_loop[chnl_schedules_index]}" \
                    --arg auto_remove "${chnl_schedules_auto_remove[chnl_schedules_index]}" \
                    --arg hls_change "${chnl_schedules_hls_change[chnl_schedules_index]}" \
                    --arg hls_change_once "${chnl_schedules_hls_change_once[chnl_schedules_index]}" \
                    --arg channel_name "${chnl_schedules_channel_name[chnl_schedules_index]}" \
                    --arg status "${chnl_schedules_status[chnl_schedules_index]}" \
                '{
                    start_time: $start_time | tonumber,
                    end_time: $end_time | tonumber,
                    loop: $loop | test("true"),
                    auto_remove: $auto_remove | test("true"),
                    hls_change: $hls_change | test("true"),
                    hls_change_once: $hls_change_once | test("true"),
                    channel_name: $channel_name,
                    status: $status | tonumber
                }'
            )
            new_schedules+=("$new_schedule")
        done

        jq_file=true
        jq_file_json=true
        jq_path='["channels",'"$chnls_index"',"schedule"]'
        JQ update "$CHANNELS_FILE" new_schedules

        Println "$info $(gettext "频道") [ ${chnls_channel_name[chnls_index]} ] $(gettext "计划排序成功")\n"
    }

    SortChannelsSchedule()
    {
        ListChannelsSchedule

        if [ -z "$chnls_schedule_list" ] 
        then
            Println "$(eval_gettext "\$error 请先添加频道计划")\n"
            exit 1
        fi

        echo -e "  ${green}$((chnls_count+1)).${normal}${indent_6}$i18n_all\n\n"

        echo "$(gettext "输入频道序号(多个频道用空格分隔 比如: 1 2 4-5)")"
        while read -p "$i18n_default_cancel" chnls_num
        do
            if [ -z "$chnls_num" ] 
            then
                Println "$i18n_canceled...\n" && exit 1
            fi

            if [ "$chnls_num" == $((chnls_count+1)) ] 
            then
                for chnls_index in "${chnls_schedule_indices[@]}"
                do
                    SortChannelSchedules
                done
                break
            fi

            IFS=" " read -ra chnls_num_arr <<< "$chnls_num"

            error_no=0
            for chnl_num in "${chnls_num_arr[@]}"
            do
                case "$chnl_num" in
                    *"-"*)
                        chnl_num_start=${chnl_num%-*}
                        chnl_num_end=${chnl_num#*-}
                        if [[ $chnl_num_start == *[!0-9]* ]] || [[ $chnl_num_end == *[!0-9]* ]] || [ "$chnl_num_start" -eq 0 ] || [ "$chnl_num_end" -eq 0 ] || [ "$chnl_num_end" -gt "$chnls_count" ] || [ "$chnl_num_start" -ge "$chnl_num_end" ]
                        then
                            error_no=3
                            break
                        else
                            for((i=chnl_num_start-1;i<chnl_num_end;i++));
                            do
                                if [ -z "${chnls_schedule_status[i]}" ] 
                                then
                                    error_no=3
                                    break 2
                                fi
                            done
                        fi
                    ;;
                    *[!0-9]*)
                        error_no=1
                        break
                    ;;
                    *)
                        if [ "$chnl_num" -lt 1 ] || [ "$chnl_num" -gt "$chnls_count" ] || [ -z "${chnls_schedule_status[chnl_num-1]}" ]
                        then
                            error_no=2
                            break
                        fi
                    ;;
                esac
            done

            case "$error_no" in
                1|2|3)
                    Println "$error $i18n_input_correct_number\n"
                ;;
                *)
                    for chnl_num in "${chnls_num_arr[@]}"
                    do
                        if [[ $chnl_num =~ - ]] 
                        then
                            chnls_start=${chnl_num%-*}
                            chnls_end=${chnl_num#*-}
                            for((chnls_index=chnls_start-1;chnls_index<chnls_end;chnls_index++));
                            do
                                SortChannelSchedules
                            done
                        else
                            chnls_index=$((chnl_num-1))
                            SortChannelSchedules
                        fi
                    done
                    break
                ;;
            esac
        done
    }
    DelChannelSchedule()
    {
        jq_path='["channels",'"$chnls_index"',"schedule",'"$chnl_schedules_index"']'
        JQ delete "$CHANNELS_FILE"

        Println "$info $(gettext "频道") [ ${chnl_schedules_channel_name[chnl_schedules_index]:-${chnls_channel_name[chnls_index]}} ] $(gettext "计划") $((chnl_schedules_index+1)) $(gettext "删除成功")\n"
    }

    DelChannelSchedules()
    {
        ListChannelSchedules

        echo -e "  ${green}$((chnl_schedules_count+1)).${normal}${indent_6}$i18n_all\n\n"

        echo "$(gettext "输入计划序号(多个计划用空格分隔 比如: 1 2 4-5)")"
        while read -p "$i18n_default_cancel" chnl_schedules_num
        do
            if [ -z "$chnl_schedules_num" ] 
            then
                Println "$i18n_canceled...\n" && break
            fi

            if [ "$chnl_schedules_num" == $((chnl_schedules_count+1)) ] 
            then
                chnl_schedules_indices=($(printf '%s\n' "${chnl_schedules_indices[@]}" | sort -nr))

                for chnl_schedules_index in "${chnl_schedules_indices[@]}"
                do
                    DelChannelSchedule
                done
                break
            fi

            IFS=" " read -ra chnl_schedules_num_arr <<< "$chnl_schedules_num"

            error_no=0
            for chnl_schedule_num in "${chnl_schedules_num_arr[@]}"
            do
                case "$chnl_schedule_num" in
                    *"-"*)
                        chnl_schedule_num_start=${chnl_schedule_num%-*}
                        chnl_schedule_num_end=${chnl_schedule_num#*-}
                        if [[ $chnl_schedule_num_start == *[!0-9]* ]] || [[ $chnl_schedule_num_end == *[!0-9]* ]] || [ "$chnl_schedule_num_start" -eq 0 ] || [ "$chnl_schedule_num_end" -eq 0 ] || [ "$chnl_schedule_num_end" -gt "$chnl_schedules_count" ] || [ "$chnl_schedule_num_start" -ge "$chnl_schedule_num_end" ]
                        then
                            error_no=3
                            break
                        fi
                    ;;
                    *[!0-9]*)
                        error_no=1
                        break
                    ;;
                    *)
                        if [ "$chnl_schedule_num" -lt 1 ] || [ "$chnl_schedule_num" -gt "$chnl_schedules_count" ] 
                        then
                            error_no=2
                            break
                        fi
                    ;;
                esac
            done

            case "$error_no" in
                1|2|3)
                    Println "$error $i18n_input_correct_number\n"
                ;;
                *)
                    declare -a new_array
                    for chnl_schedule_num in "${chnl_schedules_num_arr[@]}"
                    do
                        if [[ $chnl_schedule_num =~ - ]] 
                        then
                            chnl_schedules_start=${chnl_schedule_num%-*}
                            chnl_schedules_end=${chnl_schedule_num#*-}
                            for((chnl_schedules_index=chnl_schedules_start-1;chnl_schedules_index<chnl_schedules_end;chnl_schedules_index++));
                            do
                                new_array+=("$chnl_schedules_index")
                            done
                        else
                            new_array+=("$((chnl_schedule_num-1))")
                        fi
                    done

                    new_array=($(printf '%s\n' "${new_array[@]}" | sort -nru))

                    for chnl_schedules_index in "${new_array[@]}"
                    do
                        DelChannelSchedule
                    done

                    unset new_array
                    break
                ;;
            esac
        done
    }

