                    jq_bool=true
                    EditDefault const_cbr "$const_cbr"
                ;;
                18)
                    SetEncrypt
                    jq_bool=true
                    EditDefault encrypt "$encrypt"
                    jq_bool=true
                    EditDefault encrypt_session "$encrypt_session"
                ;;
                19)
                    SetKeyInfoName
                    EditDefault keyinfo_name
                ;;
                20)
                    SetKeyName
                    EditDefault key_name
                ;;
                21)
                    SetInputFlags
                    EditDefault input_flags
                ;;
                22)
                    SetOutputFlags
                    EditDefault output_flags
                ;;
                23)
                    SetSync
                    jq_bool=true
                    EditDefault sync "$sync"
                ;;
                24)
                    SetSyncFile
                    EditDefault sync_file
                ;;
                25)
                    SetSyncIndex
                    EditDefault sync_index
                ;;
                26)
                    SetSyncPairs
                    EditDefault sync_pairs
                ;;
                27)
                    SetScheduleFile
                    EditDefault schedule_file
                ;;
                28)
                    SetFlvDelaySeconds
                    jq_number=true
                    EditDefault flv_delay_seconds
                ;;
                29)
                    SetFlvRestartNums
                    jq_number=true
                    EditDefault flv_restart_nums
                ;;
                30)
                    SetHlsDelaySeconds
                    jq_number=true
                    EditDefault hls_delay_seconds
                ;;
                31)
                    SetHlsMinBitrate
                    jq_number=true
                    EditDefault hls_min_bitrate
                ;;
                32)
                    SetHlsMaxSegSize
                    jq_number=true
                    EditDefault hls_max_seg_size
                ;;
                33)
                    SetHlsRestartNums
                    jq_number=true
                    EditDefault hls_restart_nums
                ;;
                34)
                    SetHlsKeyPeriod
                    jq_number=true
                    EditDefault hls_key_period
                ;;
                35)
                    SetHlsEndList
                    jq_bool=true
                    EditDefault hls_end_list
                ;;
                36)
                    SetAntiDDosPort
                    EditDefault anti_ddos_port
                ;;
                37)
                    SetAntiDDosSynFlood
                    jq_bool=true
                    EditDefault anti_ddos_syn_flood "$anti_ddos_syn_flood"
                    if [ "$anti_ddos_syn_flood" = true ] 
                    then
                        jq_number=true
                        EditDefault anti_ddos_syn_flood_delay_seconds
                        jq_number=true
                        EditDefault anti_ddos_syn_flood_seconds
                    fi
                ;;
                38)
                    SetAntiDDos
                    jq_bool=true
                    EditDefault anti_ddos "$anti_ddos"
                    if [ "$anti_ddos" = true ] 
                    then
                        jq_number=true
                        EditDefault anti_ddos_seconds
                        jq_number=true
                        EditDefault anti_ddos_level
                    fi
                ;;
                39)
                    SetAntiLeech
                    jq_bool=true
                    EditDefault anti_leech "$anti_leech"
                    if [ "$anti_leech" = true ] 
                    then
                        jq_number=true
                        EditDefault anti_leech_restart_nums
                        jq_bool=true
                        EditDefault anti_leech_restart_flv_changes "$anti_leech_restart_flv_changes"
                        jq_bool=true
                        EditDefault anti_leech_restart_hls_changes "$anti_leech_restart_hls_changes"
                    fi
                ;;
                40)
                    SetRecheckPeriod
                    jq_number=true
                    EditDefault recheck_period
                ;;
            esac
        done
    }
    Set4gtvAccEmail()
    {
        Println "$(gettext "输入新账号邮箱")"
        while read -r -p "$(gettext "(默认: 随机): ")" _4gtv_acc_email
        do
            [ -z "$_4gtv_acc_email" ] && _4gtv_acc_email="$(RandStr)_$(DateEpoch)@gmail.com"

            if [[ $_4gtv_acc_email =~ ^[A-Za-z0-9]([a-zA-Z0-9_\.\-]*)@([A-Za-z0-9]+)([a-zA-Z0-9\.\-]*)\.([A-Za-z]{2,})$ ]]
            then
                break
            else
                Println "$(eval_gettext "\$error 邮箱格式错误, 请重新输入")\n"
            fi
        done
        Println "  $(gettext "4gtv 账号邮箱"): ${green} $_4gtv_acc_email ${normal}\n"
    }

    Set4gtvAccPass()
    {
        Println "$(gettext "输入新账号密码(字母或数字 8-12 位)")"
        while read -r -p "$(gettext "(默认: 随机): ")" _4gtv_acc_pass
        do
            [ -z "$_4gtv_acc_pass" ] && _4gtv_acc_pass=$(RandStr)
            if [[ $_4gtv_acc_pass =~ ^[A-Za-z0-9]{8,12}$ ]]
            then
                break
            else
                Println "$(eval_gettext "\$error 账号密码格式错误, 请重新输入")\n"
            fi
        done
        Println "  $(gettext "4gtv 账号密码"): ${green} $_4gtv_acc_pass ${normal}\n"
    }
    Reg4gtvAcc()
    {
        JQInstall
        Set4gtvAccEmail
        Set4gtvAccPass
        IFS=" " read -r result msg < <(CurlFake -s -Lm 10 \
            -H 'Origin: https://www.4gtv.tv' \
            -H 'Referer: https://www.4gtv.tv/signup.html' \
            --data-urlencode "fnREGISTER_TYPE=1" \
            --data-urlencode "fsLOGIN_TYPE=" \
            --data-urlencode "fsLINK_ID=" \
            --data-urlencode "fsUSER=$_4gtv_acc_email" \
            --data-urlencode "fsPASSWORD=$_4gtv_acc_pass" \
            --data-urlencode "fsPASSWORD1=$_4gtv_acc_pass" \
            --data-urlencode "fnBIRTH_YEAR=$((RANDOM%20+1980))" \
            --data-urlencode "fsSEX=male" \
            https://api2.4gtv.tv/Account/Register \
            | $JQ_FILE -r '[.Success,.ErrMessage]|join(" ")'
        ) || true

        if [ "$result" = true ] || [ "$msg" = "String was not recognized as a valid DateTime." ]
        then
            mkdir -p "$SERVICES_ROOT"

            if [ ! -s "$SERVICES_CONFIG" ]
            then
                printf '{"%s":{"%s":[]}}' "4gtv" "accounts" > "$SERVICES_CONFIG"
            fi
            new_acc=$(
            $JQ_FILE -n --arg email "$_4gtv_acc_email" --arg password "$_4gtv_acc_pass" \
                '{
                    email: $email,
                    password: $password
                }'
            )
            jq_path='["4gtv","accounts"]'

            if JQ add "$SERVICES_CONFIG" "[$new_acc]"
            then
                Println "$(eval_gettext "\$info 账号注册成功")\n"
            else
                Println "$(eval_gettext "\$error 账号保存失败")\n"
                return 1
            fi
        else
            Println "$(eval_gettext "\$error 账号注册失败, 请重试")\n\n$msg\n"
        fi
    }
    List4gtvAccs()
    {
        ServiceGet 4gtv
        _4gtv_accs_list=""

        local i
        for((i=0;i<_4gtv_accs_count;i++));
        do
            if [ -n "${_4gtv_accs_token[i]:-}" ]
            then
                is_login="${green} [ $(gettext "已登录") ] ${normal}"
            else
                is_login=""
            fi
            _4gtv_accs_list="$_4gtv_accs_list ${green}$((i+1)).${normal}${indent_6}$(gettext "邮箱"): ${green}${_4gtv_accs_email[i]}${normal}$is_login\n${indent_6}$i18n_password: ${green}${_4gtv_accs_pass[i]}${normal}\n\n"
        done

        if [ -n "$_4gtv_accs_list" ]
        then
            Println "$_4gtv_accs_list"
        else
            Println "$(eval_gettext "\$error 没有账号")\n"
        fi
    }
    Select4gtvAcc()
    {
        List4gtvAccs

        if [ "$_4gtv_accs_count" -eq 0 ]
        then
            exit 1
        fi

        echo -e "$(gettext "选择账号")"
        while read -r -p "$i18n_default_cancel" _4gtv_accs_num
        do
            case "$_4gtv_accs_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$_4gtv_accs_num" -gt 0 ] && [ "$_4gtv_accs_num" -le "$_4gtv_accs_count" ]
                    then
                        _4gtv_accs_index=$((_4gtv_accs_num-1))
                        return 0
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        return 1
    }
    Login4gtvAcc()
    {
        if [ ! -e "$IMGCAT_FILE" ]
        then
            ImgcatInstall
        fi

        List4gtvAccs

        _4gtv_input_acc_num=$((_4gtv_accs_count+1))
        echo -e " ${green}$_4gtv_input_acc_num.${normal}${indent_6}$(gettext "手动输入")\n"

        echo -e "$(gettext "选择账号")"
        while read -r -p "$i18n_default_cancel" _4gtv_accs_num
        do
            case "$_4gtv_accs_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                $_4gtv_input_acc_num)
                    _4gtv_accs_index=$((_4gtv_accs_num-1))
                    Set4gtvAccEmail
                    Set4gtvAccPass
                    mkdir -p "$SERVICES_ROOT"

                    if [ ! -s "$SERVICES_CONFIG" ]
                    then
                        printf '{"%s":{"%s":[]}}' "4gtv" "accounts" > "$SERVICES_CONFIG"
                    fi
                    new_acc=$(
                    $JQ_FILE -n --arg email "$_4gtv_acc_email" --arg password "$_4gtv_acc_pass" \
                        '{
                            email: $email,
                            password: $password
                        }'
                    )
                    jq_path='["4gtv","accounts"]'

                    if JQ add "$SERVICES_CONFIG" "[$new_acc]"
                    then
                        Println "$(eval_gettext "\$info 账号添加成功")\n"
                    else
                        Println "$(eval_gettext "\$error 账号保存失败")\n"
                        return 1
                    fi
                    break
                ;;
                *)
                    if [ "$_4gtv_accs_num" -gt 0 ] && [ "$_4gtv_accs_num" -le "$_4gtv_accs_count" ]
                    then
                        _4gtv_accs_index=$((_4gtv_accs_num-1))
                        _4gtv_acc_email=${_4gtv_accs_email[_4gtv_accs_index]}
                        _4gtv_acc_pass=${_4gtv_accs_pass[_4gtv_accs_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        ImageMagickInstall

        local img_file
        while true
        do
            img_file=$(mktemp "${TMPDIR:-/tmp}/aios-4gtv.XXXXXX")
            if ! CurlFake -s -Lm 20 \
                -H 'authority: www.4gtv.tv' \
                -H 'referer: https://www.4gtv.tv/channel.html' \
                "https://www.4gtv.tv/validatecode?t=$(DateMs)" -o "$img_file" || [ ! -s "$img_file" ]
            then
                rm -f "$img_file"
                Println "$(eval_gettext "\$error 获取验证码图片失败, 请重试")\n"
                exit 1
            fi

            if ! "$IMGCAT_FILE" --half-height "$img_file"
            then
                ImageMagickInstall

                if ! "$IMGCAT_FILE" --half-height "$img_file"
                then
                    rm -f "$img_file"
                    Println "$(eval_gettext "\$error 显示验证码图片失败, 请重试")\n"
                    exit 1
                fi
            fi

            rm -f "$img_file"
            Println "$(eval_gettext "\$info 输入图片验证码: ")"
            read -r -p "$(gettext "(默认: 刷新验证码, 输入 q 退出): ")" validatecode

            if [ "$validatecode" == "q" ] || [ "$validatecode" == "Q" ]
            then
                Println "$i18n_canceled...\n"
                return 1
            fi
            [ -z "$validatecode" ] && continue

            Println "$(eval_gettext "\$info 登录账号...")"
            IFS="^" read -r result msg token < <(CurlFake -s -Lm 20 \
                -H 'Origin: https://www.4gtv.tv' \
                -H 'Referer: https://www.4gtv.tv/channel.html' \
                --data-urlencode "fsUSER=$_4gtv_acc_email" \
                --data-urlencode "fsPASSWORD=$_4gtv_acc_pass" \
                --data-urlencode "fsVALIDATE_CODE=$validatecode" \
                https://api2.4gtv.tv/Account/SignIn \
                | $JQ_FILE -r '[.Success,.ErrMessage,.Data]|join("^")'
            ) || true

            if [ "$result" = true ]
            then
                break
            else
                Println "$(eval_gettext "\$error 账号登录失败, 请重试")\n\n$msg\n"
            fi
        done

        jq_path='["4gtv","accounts",'"$_4gtv_accs_index"',"token"]'

        if ! JQ update "$SERVICES_CONFIG" "$token"
        then
            Println "$(eval_gettext "\$error 保存登录令牌失败")\n"
            return 1
        fi
        Println "$(eval_gettext "\$info 账号登录成功")"
        Println "$(eval_gettext "\$info 验证账号...")"

        local i
        result=""
        for((i=0;i<3;i++));
        do
            random_number=$(od -An -N8 -t u8 < /dev/urandom | tr -d '[:space:]')
            if [ "${#random_number}" -gt 12 ]
            then
                random_number=${random_number:$(( ${#random_number} - 12 ))}
            fi
            fsLINK_ID="$random_number${random_number:0:9}"
            IFS="^" read -r result < <(CurlFake -s -Lm 20 \
                -H 'Origin: https://www.4gtv.tv' \
                -H 'Referer: https://www.4gtv.tv/channel_sub.html?channelSet_id=1&asset_id=4gtv-4gtv003&channel_id=1' \
                -d "fsLOGIN_TYPE=03&fsLINK_ID=$fsLINK_ID&clsIDENTITY_VALIDATE_ARUS%5BfsVALUE%5D=$(UrlencodeUpper "$token")" \
                https://api2.4gtv.tv/Account/SignIn \
                | $JQ_FILE -r '.Success'
            ) || true

            if [ "$result" = true ]
            then
                break
            fi
        done

        if [ "$result" = true ]
        then
            Println "$(eval_gettext "\$info 账号验证成功")"
        else
            Println "$(eval_gettext "\$error 账号验证失败, 请重试")\n"
            return 1
        fi

        Println "$(eval_gettext "\$info 开启 30 天豪华套餐")"

        IFS="^" read -r result msg < <(CurlFake -s -Lm 20 \
            -H 'Origin: https://www.4gtv.tv' \
            -H 'Referer: https://www.4gtv.tv/channel_sub.html?channelSet_id=1&asset_id=4gtv-4gtv003&channel_id=1' \
            -d "fsVALUE=$(UrlencodeUpper "$token")" \
            https://api2.4gtv.tv/Account/AccountPromo \
            | $JQ_FILE -r '[.Success,.ErrMessage]|join("^")'
        ) || true

        if [ "$result" = true ]
        then
            Println "$(eval_gettext "\$info 30 天豪华套餐开启成功")\n"
        else
            Println "$(eval_gettext "\$error 开启 30 天豪华套餐发生错误, 请重试")\n\n$msg\n"
        fi
    }
    List4gtvAcc()
    {
        Select4gtvAcc || return 1

        fsVALUE=${_4gtv_accs_token[_4gtv_accs_index]:-}

        if [ -z "$fsVALUE" ]
        then
            Println "$(eval_gettext "\$error 请先登录此账号")\n"
            exit 1
        else
            Println "$(eval_gettext "\$info 查询中...")"
            IFS="^" read -r result msg fnLEFT_PROMO_DAYS < <(CurlFake -s -Lm 20 \
                -H 'Origin: https://www.4gtv.tv' \
                -H 'Referer: https://www.4gtv.tv/channel.html' \
                -d "clsIDENTITY_VALIDATE_ARUS%5BfsVALUE%5D=$(UrlencodeUpper "$fsVALUE")" \
                https://api2.4gtv.tv/Account/GetAccountInfo \
                | $JQ_FILE -r '[.Success,.ErrMessage,.Data.fnLEFT_PROMO_DAYS]|join("^")'
            ) || true

            if [ "$result" = true ]
            then
                if [[ $fnLEFT_PROMO_DAYS =~ ^-?[0-9]+$ ]] && [ "$fnLEFT_PROMO_DAYS" -eq -1 ]
                then
                    days_left="${red}$(gettext "未开通")${normal}"
                elif [[ $fnLEFT_PROMO_DAYS =~ ^-?[0-9]+$ ]]
                then
                    days_left="$(eval_gettext "还剩 \${green}\$fnLEFT_PROMO_DAYS\${normal} 天")"
                else
                    days_left="${red}$(gettext "未知")${normal}"
                fi

                Println "$(eval_gettext "\$info 豪华套餐: \$days_left")\n"
            else
                Println "$(eval_gettext "\$error 查询遇到错误")\n\n$msg\n"
            fi
        fi
    }
    Edit4gtvAcc()
    {
        Select4gtvAcc || return 1

        Set4gtvAccEmail
        Set4gtvAccPass
        new_acc=$(
            $JQ_FILE -n --arg email "$_4gtv_acc_email" --arg password "$_4gtv_acc_pass" \
                '{
                    email: $email,
                    password: $password
                }'
        )
        jq_merge=true
        jq_path='["4gtv","accounts",'"$_4gtv_accs_index"']'

        if JQ update "$SERVICES_CONFIG" "$new_acc"
        then
            Println "$(eval_gettext "\$info 账号修改成功")\n"
        else
            Println "$(eval_gettext "\$error 账号修改失败")\n"
            return 1
        fi
    }
    Del4gtvAcc()
    {
        Select4gtvAcc || return 1

        jq_path='["4gtv","accounts",'"$_4gtv_accs_index"']'

        if JQ delete "$SERVICES_CONFIG"
        then
            Println "$(eval_gettext "\$info 账号删除成功")\n"
        else
            Println "$(eval_gettext "\$error 账号删除失败")\n"
            return 1
        fi
    }
    Get4gtvAccToken()
    {
        Select4gtvAcc || return 1

        fsVALUE=${_4gtv_accs_token[_4gtv_accs_index]:-}

        if [ -z "$fsVALUE" ]
        then
            Println "$(eval_gettext "\$error 请先登录此账号")\n"
            exit 1
        fi
    }
    Use4gtvProxy()
    {
        GetDefault
        d_4gtv_proxy=${d_4gtv_proxy:-${d_proxy:-}}

        if [ -z "$d_4gtv_proxy" ]
        then
            ServiceGet 4gtv
            d_4gtv_proxy=${d_4gtv_proxy:-${d_proxy:-}}
        fi
        Println "$(eval_gettext "\$tip 可以使用脚本自带的 v2ray 管理面板添加代理, 可以输入 omit 省略此选项")"
        inquirer text_input "$(gettext "请输入 4gtv 代理, 比如 http://username:password@127.0.0.1:5555 : ")" _4gtv_proxy "${d_4gtv_proxy:-$i18n_blank}"
        if [ -z "$_4gtv_proxy" ] || [ "$_4gtv_proxy" == "omit" ]
        then
            _4gtv_proxy=""
            _4gtv_proxy_command=()
        else
            _4gtv_proxy_command=( -x "$_4gtv_proxy" )
        fi
    }
    _4gtvCron()
    {
        JQInstall
        _4gtv_acc_email="$(RandStr)_$(DateEpoch)@gmail.com"
        _4gtv_acc_pass=$(RandStr)
        IFS=" " read -r result msg < <(CurlFake -s -Lm 10 \
            -H 'Origin: https://www.4gtv.tv' \
            -H 'Referer: https://www.4gtv.tv/signup.html' \
            --data-urlencode "fnREGISTER_TYPE=1" \
            --data-urlencode "fsLOGIN_TYPE=" \
            --data-urlencode "fsLINK_ID=" \
            --data-urlencode "fsUSER=$_4gtv_acc_email" \
            --data-urlencode "fsPASSWORD=$_4gtv_acc_pass" \
            --data-urlencode "fsPASSWORD1=$_4gtv_acc_pass" \
            --data-urlencode "fnBIRTH_YEAR=$((RANDOM%20+1980))" \
            --data-urlencode "fsSEX=male" \
            https://api2.4gtv.tv/Account/Register \
            | $JQ_FILE -r '[.Success,.ErrMessage]|join(" ")'
        ) || true

        if [ "$result" = true ]
        then
            mkdir -p "$SERVICES_ROOT"

            if [ ! -s "$SERVICES_CONFIG" ]
            then
                printf '{"%s":{"%s":[]}}' "4gtv" "accounts" > "$SERVICES_CONFIG"
            fi
            new_acc=$(
            $JQ_FILE -n --arg email "$_4gtv_acc_email" --arg password "$_4gtv_acc_pass" \
                '{
                    email: $email,
                    password: $password
                }'
            )
            jq_path='["4gtv","accounts"]'

            if JQ add "$SERVICES_CONFIG" "[$new_acc]"
            then
                Println "$(eval_gettext "\$info 账号注册成功")\n"
            else
                Println "$(eval_gettext "\$error 账号保存失败")\n"
                exit 1
            fi
        else
            Println "$(eval_gettext "\$error 账号注册失败, 请重试")\n\n$msg\n"
        fi

        exit 0
    }
    Enable4gtvCron()
    {
        if crontab -l 2> /dev/null | grep -Fq -- "$AIOS_PREFIX/bin/tv 4g -"
        then
            Println "$(eval_gettext "\$error 定时任务 (每5天注册账号) 已开启 !")\n"
        else
            local cron_tmp
            cron_tmp=$(mktemp "${TMPDIR:-/tmp}/aios-cron.XXXXXX")
            crontab -l > "$cron_tmp" 2> /dev/null || true
            printf '%s\n' "0 0 */5 * * $AIOS_PREFIX/bin/tv 4g -" >> "$cron_tmp"
            crontab "$cron_tmp" > /dev/null
            rm -f "$cron_tmp"
            Println "$(eval_gettext "\$info 定时任务 (每5天注册账号) 开启成功")\n"
        fi
    }
    Disable4gtvCron()
    {
        if crontab -l 2> /dev/null | grep -Fq -- "$AIOS_PREFIX/bin/tv 4g -"
        then
            local cron_tmp
            cron_tmp=$(mktemp "${TMPDIR:-/tmp}/aios-cron.XXXXXX")
            crontab -l > "$cron_tmp" 2> /dev/null || true
            FilterFileLines "$AIOS_PREFIX/bin/tv 4g -" "$cron_tmp"
            crontab "$cron_tmp" > /dev/null
            rm -f "$cron_tmp"
            Println "$(eval_gettext "\$info 定时任务 (每5天注册账号) 关闭成功")\n"
        else
            Println "$(eval_gettext "\$error 定时任务 (每5天注册账号) 未开启 !")\n"
        fi
    }
    Add4gtvLink()
    {
        if [[ $stream_link_url =~ \.m3u8$ ]]
        then
            Println "$(eval_gettext "\$error 你的 IP 可能已被禁")\n"
            return 1
        fi

        stream_urls=()
        stream_urls_bitrate=()
        stream_urls_resolution=()
        stream_urls_list=""
        stream_urls_count=0

        local header_clean=${headers%\\r\\n}
        header_clean=${header_clean%$'\r\n'}
        header_clean=${header_clean%$'\n'}
        header_clean=${header_clean%$'\r'}

        local line
        while IFS= read -r line
        do
            if [[ $line =~ RESOLUTION=([^ ]+) ]]
            then
                stream_url_resolution=${BASH_REMATCH[1]%%,*}
                stream_urls_resolution+=("$stream_url_resolution")
                if [[ $line =~ BANDWIDTH=([^ ]+) ]]
                then
                    stream_url_bitrate=${BASH_REMATCH[1]%%,*}
                    stream_url_bitrate=$((stream_url_bitrate/1000))
                else
                    stream_url_bitrate=""
                fi
                stream_urls_bitrate+=("$stream_url_bitrate")
                if [ -n "$stream_url_bitrate" ]
                then
                    stream_url_bitrate_text=" [ $stream_url_bitrate k ]"
                else
                    stream_url_bitrate_text=""
                fi
                stream_urls_count=$((stream_urls_count+1))
                stream_urls_list="$stream_urls_list ${green}$stream_urls_count.${normal}${indent_6}$stream_url_resolution$stream_url_bitrate_text\n\n"
            elif [[ $line =~ m3u8 ]]
            then
                stream_urls+=("$stream_link_url_path/$line")
            fi
        done < <(curl -s -Lm 20 ${_4gtv_proxy_command[@]+"${_4gtv_proxy_command[@]}"} -H "User-Agent: $user_agent" -H "$header_clean" "$stream_link_url")

        if [ -n "$stream_urls_list" ]
        then
            stream_url_root=${stream_link%%|*}

            local i j stream_url_num start end
            if [[ $stream_link =~ \|([^|]+)$ ]]
            then
                choose=0
                stream_url_quality=${BASH_REMATCH[1]}

                IFS="," read -r -a stream_url_qualities <<< "$stream_url_quality"
                stream_url_qualities_count=${#stream_url_qualities[@]}

                stream_url_video_indices=()

                for((i=0;i<stream_url_qualities_count;i++));
                do
                    for((j=0;j<stream_urls_count;j++));
                    do
                        if { ! [[ ${stream_url_qualities[i]} =~ - ]] || [ "${stream_urls_bitrate[j]}" == "${stream_url_qualities[i]%-*}" ]; } && [ "${stream_urls_resolution[j]}" == "${stream_url_qualities[i]#*-}" ]
                        then
                            stream_url_qualities[i]="${stream_urls_bitrate[j]}-${stream_urls_resolution[j]}"
                            stream_url_video_indices+=("$j")
                            continue 2
                        fi
                    done
                    Println "$error ${stream_url_qualities[i]} $(gettext "不存在") !"
                    choose=1
                    Println "$(eval_gettext "\$error 请重新选择 \$channel_name 分辨率")"
                    break
                done
            else
                choose=1
            fi

            if [ "$choose" -eq 1 ]
            then
                if [ -z "${kind:-}" ]
                then
                    stream_urls_select_all=$((stream_urls_count+1))
                    stream_urls_list="$stream_urls_list ${green}$stream_urls_select_all.${normal}${indent_6}$i18n_all\n"
                    Println "$stream_urls_list"
                    echo "$(gettext "选择分辨率 (多个分辨率用空格分隔 比如: 1 2 4-5)")"
                else
                    stream_urls_select_all=""
                    Println "$stream_urls_list"
                    echo "$(gettext "选择分辨率")"
                fi

                while read -r -p "$(eval_gettext "(默认: \$stream_urls_count): ")" stream_urls_num
                do
                    stream_urls_num=${stream_urls_num:-$stream_urls_count}

                    if [ "$stream_urls_num" == "$stream_urls_select_all" ]
                    then
                        stream_url_qualities=()
                        stream_url_video_indices=()

                        for((i=0;i<stream_urls_count;i++));
                        do
                            stream_url_qualities+=("${stream_urls_bitrate[i]}-${stream_urls_resolution[i]}")
                            stream_url_video_indices+=("$i")
                        done

                        stream_url_qualities_count=$stream_urls_count
                        break
                    fi

                    IFS=" " read -ra stream_urls_num_arr <<< "$stream_urls_num"

                    error_no=0
                    for stream_url_num in "${stream_urls_num_arr[@]}"
                    do
                        case "$stream_url_num" in
                            *"-"*)
                                if [[ ! $stream_url_num =~ ^[1-9][0-9]*-[1-9][0-9]*$ ]]
                                then
                                    error_no=3
                                    break
                                fi
                                stream_url_num_start=${stream_url_num%-*}
                                stream_url_num_end=${stream_url_num#*-}

                                if [ "$stream_url_num_end" -gt "$stream_urls_count" ] || [ "$stream_url_num_start" -ge "$stream_url_num_end" ]
                                then
                                    error_no=3
                                    break
                                fi
                            ;;
                            *[!0-9]*)
                                error_no=1
                                break
                            ;;
                            *)
                                if [ "$stream_url_num" -lt 1 ] || [ "$stream_url_num" -gt "$stream_urls_count" ]
                                then
                                    error_no=2
                                    break
                                fi
                            ;;
                        esac
                    done

                    case "$error_no" in
                        1|2|3)
                            Println "$error $i18n_input_correct_no\n"
                        ;;
                        *)
                            stream_url_qualities=()
                            stream_url_video_indices=()

                            for stream_url_num in "${stream_urls_num_arr[@]}"
                            do
                                if [[ $stream_url_num =~ - ]]
                                then
                                    start=${stream_url_num%-*}
                                    end=${stream_url_num#*-}
                                    for((i=start-1;i<end;i++));
                                    do
                                        stream_url_qualities+=("${stream_urls_bitrate[i]}-${stream_urls_resolution[i]}")
                                        stream_url_video_indices+=("$i")
                                    done
                                else
                                    stream_urls_index=$((stream_url_num-1))
                                    stream_url_qualities+=("${stream_urls_bitrate[stream_urls_index]}-${stream_urls_resolution[stream_urls_index]}")
                                    stream_url_video_indices+=("$stream_urls_index")
                                fi
                            done

                            stream_url_qualities_count=${#stream_url_qualities[@]}
                            break
                        ;;
                    esac
                done
            fi

            printf -v stream_url_quality ',%s' "${stream_url_qualities[@]}"
            stream_url_quality=${stream_url_quality:1}
            stream_links[0]="$stream_url_root|$stream_url_quality"

            if [ -n "${_4gtv_proxy_command[*]:-}" ] && [ "${#_4gtv_proxy_command[@]}" -gt 0 ] && [[ $stream_link == https://* ]]
            then
                stream_link="http://${stream_link#https://}"
            fi
        else
            Println "$(eval_gettext "\$error 频道 [ \$channel_name ] 不可用")\n"
            return 1
        fi
    }
    Start4gtvLink()
    {
        if [[ $chnl_stream_link_url =~ \.m3u8$ ]]
        then
            Println "$(eval_gettext "\$error 你的 IP 可能已被禁")\n"
            return 1
        fi

        chnl_stream_urls=()
        chnl_stream_urls_bitrate=()
        chnl_stream_urls_resolution=()
        chnl_stream_urls_list=""
        chnl_stream_urls_count=0

        local chnl_header_clean=${chnl_headers%\\r\\n}
        chnl_header_clean=${chnl_header_clean%$'\r\n'}
        chnl_header_clean=${chnl_header_clean%$'\n'}
        chnl_header_clean=${chnl_header_clean%$'\r'}

        local line
        while IFS= read -r line
        do
            if [[ $line =~ RESOLUTION=([^ ]+) ]]
            then
                chnl_stream_url_resolution=${BASH_REMATCH[1]%%,*}
                chnl_stream_urls_resolution+=("$chnl_stream_url_resolution")
                if [[ $line =~ BANDWIDTH=([^ ]+) ]]
                then
                    chnl_stream_url_bitrate=${BASH_REMATCH[1]%%,*}
                    chnl_stream_url_bitrate=$((chnl_stream_url_bitrate/1000))
                else
                    chnl_stream_url_bitrate=""
                fi
                chnl_stream_urls_bitrate+=("$chnl_stream_url_bitrate")
                if [ -n "$chnl_stream_url_bitrate" ]
                then
                    chnl_stream_url_bitrate_text=" [ $chnl_stream_url_bitrate k ]"
                else
                    chnl_stream_url_bitrate_text=""
                fi
                chnl_stream_urls_count=$((chnl_stream_urls_count+1))
                chnl_stream_urls_list="$chnl_stream_urls_list ${green}$chnl_stream_urls_count.${normal}${indent_6}$chnl_stream_url_resolution$chnl_stream_url_bitrate_text\n\n"
            elif [[ $line =~ m3u8 ]]
            then
                chnl_stream_urls+=("$chnl_stream_link_url_path/$line")
            fi
        done < <(curl -s -Lm 20 ${_4gtv_proxy_command[@]+"${_4gtv_proxy_command[@]}"} -H "User-Agent: $chnl_user_agent" -H "$chnl_header_clean" "$chnl_stream_link_url")

        if [ -n "$chnl_stream_urls_list" ]
        then
            chnl_stream_url_root=${chnl_stream_link%%|*}
            chnl_stream_url_qualities_count=0

            local i j chnl_stream_url_num start end
            if [[ $chnl_stream_link =~ \|([^|]+)$ ]]
            then
                choose=0
                chnl_stream_url_quality=${BASH_REMATCH[1]}

                IFS="," read -r -a chnl_stream_url_qualities <<< "$chnl_stream_url_quality"
                chnl_stream_url_qualities_count=${#chnl_stream_url_qualities[@]}

                chnl_stream_url_video_indices=()

                if [ "$monitor" = true ]
                then
                    auto_select=true
                else
                    auto_select=false
                fi

                choose_asked=false
                local matched_qualities=()

                for((i=0;i<chnl_stream_url_qualities_count;i++));
                do
                    for((j=0;j<chnl_stream_urls_count;j++));
                    do
                        if { [ "$auto_select" = true ] || ! [[ ${chnl_stream_url_qualities[i]} =~ - ]] || [ "${chnl_stream_urls_bitrate[j]}" == "${chnl_stream_url_qualities[i]%-*}" ]; } && [ "${chnl_stream_urls_resolution[j]}" == "${chnl_stream_url_qualities[i]#*-}" ]
                        then
                            matched_qualities+=("${chnl_stream_urls_bitrate[j]}-${chnl_stream_urls_resolution[j]}")
                            chnl_stream_url_video_indices+=("$j")
                            continue 2
                        fi
                    done

                    Println "$error ${chnl_stream_url_qualities[i]} $(gettext "不存在") !"

                    if [ "$monitor" = true ]
                    then
                        continue
                    elif [ "$choose_asked" = false ]
                    then
                        choose_asked=true
                        echo
                        inquirer list_input_index "$(gettext "是否按分辨率自动选择")" yn_options yn_index

                        if [ "$yn_index" -eq 0 ]
                        then
                            auto_select=true
                            i=$((i-1))
                            continue
                        fi
                    fi

                    choose=1
                    Println "$(eval_gettext "\$error 请重新选择 \$chnl_channel_name 分辨率")"
                    break
                done

                if [ "$choose" -eq 0 ]
                then
                    chnl_stream_url_qualities=(${matched_qualities[@]+"${matched_qualities[@]}"})
                    chnl_stream_url_qualities_count=${#chnl_stream_url_qualities[@]}

                    if [ "$chnl_stream_url_qualities_count" -eq 0 ]
                    then
                        Println "$(eval_gettext "\$error 请重新选择 \$chnl_channel_name 分辨率")"
                        return 1
                    fi
                fi
            elif [ "$monitor" = true ]
            then
                Println "$(eval_gettext "\$error 请重新选择 \$chnl_channel_name 分辨率")"
                return 1
            else
                choose=1
            fi

            if [ "$choose" -eq 1 ]
            then
                if [ -z "${kind:-}" ]
                then
                    chnl_stream_urls_select_all=$((chnl_stream_urls_count+1))
                    chnl_stream_urls_list="$chnl_stream_urls_list ${green}$chnl_stream_urls_select_all.${normal}${indent_6}$i18n_all\n"
                    Println "$chnl_stream_urls_list"
                    echo "$(gettext "选择分辨率 (多个分辨率用空格分隔 比如: 1 2 4-5)")"
                else
                    chnl_stream_urls_select_all=""
                    Println "$chnl_stream_urls_list"
                    echo "$(gettext "选择分辨率")"
                fi

                while read -r -p "$(eval_gettext "(默认: \$chnl_stream_urls_count): ")" chnl_stream_urls_num
                do
                    chnl_stream_urls_num=${chnl_stream_urls_num:-$chnl_stream_urls_count}

                    if [ "$chnl_stream_urls_num" == "$chnl_stream_urls_select_all" ]
                    then
                        chnl_stream_url_qualities=()
                        chnl_stream_url_video_indices=()

                        for((i=0;i<chnl_stream_urls_count;i++));
                        do
                            chnl_stream_url_qualities+=("${chnl_stream_urls_bitrate[i]}-${chnl_stream_urls_resolution[i]}")
                            chnl_stream_url_video_indices+=("$i")
                        done

                        chnl_stream_url_qualities_count=$chnl_stream_urls_count
                        break
                    fi

                    IFS=" " read -ra chnl_stream_urls_num_arr <<< "$chnl_stream_urls_num"

                    error_no=0
                    for chnl_stream_url_num in "${chnl_stream_urls_num_arr[@]}"
                    do
                        case "$chnl_stream_url_num" in
                            *"-"*)
                                if [[ ! $chnl_stream_url_num =~ ^[1-9][0-9]*-[1-9][0-9]*$ ]]
                                then
                                    error_no=3
                                    break
                                fi
                                chnl_stream_url_num_start=${chnl_stream_url_num%-*}
                                chnl_stream_url_num_end=${chnl_stream_url_num#*-}

                                if [ "$chnl_stream_url_num_end" -gt "$chnl_stream_urls_count" ] || [ "$chnl_stream_url_num_start" -ge "$chnl_stream_url_num_end" ]
                                then
                                    error_no=3
                                    break
                                fi
                            ;;
                            *[!0-9]*)
                                error_no=1
                                break
                            ;;
                            *)
                                if [ "$chnl_stream_url_num" -lt 1 ] || [ "$chnl_stream_url_num" -gt "$chnl_stream_urls_count" ]
                                then
                                    error_no=2
                                    break
                                fi
                            ;;
                        esac
                    done

                    case "$error_no" in
                        1|2|3)
                            Println "$error $i18n_input_correct_no\n"
                        ;;
                        *)
                            chnl_stream_url_qualities=()
                            chnl_stream_url_video_indices=()

                            for chnl_stream_url_num in "${chnl_stream_urls_num_arr[@]}"
                            do
                                if [[ $chnl_stream_url_num =~ - ]]
