                                    start=${chnl_stream_url_num%-*}
                                    end=${chnl_stream_url_num#*-}
                                    for((i=start-1;i<end;i++));
                                    do
                                        chnl_stream_url_qualities+=("${chnl_stream_urls_bitrate[i]}-${chnl_stream_urls_resolution[i]}")
                                        chnl_stream_url_video_indices+=("$i")
                                    done
                                else
                                    chnl_stream_urls_index=$((chnl_stream_url_num-1))
                                    chnl_stream_url_qualities+=("${chnl_stream_urls_bitrate[chnl_stream_urls_index]}-${chnl_stream_urls_resolution[chnl_stream_urls_index]}")
                                    chnl_stream_url_video_indices+=("$chnl_stream_urls_index")
                                fi
                            done

                            chnl_stream_url_qualities_count=${#chnl_stream_url_qualities[@]}
                            break
                        ;;
                    esac
                done
            fi

            printf -v chnl_stream_url_quality ',%s' "${chnl_stream_url_qualities[@]}"
            chnl_stream_url_quality=${chnl_stream_url_quality:1}

            chnl_stream_links[0]="$chnl_stream_url_root|$chnl_stream_url_quality"

            if [ -n "${_4gtv_proxy_command[*]:-}" ] && [ "${#_4gtv_proxy_command[@]}" -gt 0 ] && [[ $chnl_stream_link == https://* ]]
            then
                chnl_stream_link="http://${chnl_stream_link#https://}"
            fi
        else
            Println "$(eval_gettext "\$error 频道 [ \$chnl_channel_name ] 不可用")\n"
            return 1
        fi
    }
    VipSetHostIp()
    {
        Println "$(gettext "请输入 VIP 频道所在服务器 IP/域名")"
        read -p "$i18n_default_cancel" vip_host_ip
        [ -z "$vip_host_ip" ] && Println "$i18n_canceled...\n" && exit 1
        Println "  $(eval_gettext "VIP 服务器 IP/域名: \${green} \$vip_host_ip \${normal}")\n"
    }

    VipSetHostPort()
    {
        Println "$(gettext "请输入 VIP 频道所在服务器端口")"
        read -p "$i18n_default_cancel" vip_host_port
        [ -z "$vip_host_port" ] && Println "$i18n_canceled...\n" && exit 1
        Println "  $(eval_gettext "VIP 服务器端口: \${green} \$vip_host_port \${normal}")\n"
    }

    VipSetHostSeed()
    {
        Println "$(gettext "请输入 VIP 频道所在服务器的 seed")"
        read -p "$i18n_default_cancel" vip_host_seed
        [ -z "$vip_host_seed" ] && Println "$i18n_canceled...\n" && exit 1
        Println "  $(eval_gettext "VIP 服务器 seed: \${green} \$vip_host_seed \${normal}")\n"
    }

    VipSetHostToken()
    {
        echo
        inquirer text_input "$(gettext "请输入 VIP 频道所在服务器的 token"): " vip_host_token "$i18n_blank"
    }

    VipSetHostStatus()
    {
        echo
        inquirer list_input "$(gettext "是否启用此 VIP 服务器")" yn_options vip_host_status

        if [[ $vip_host_status == "$i18n_yes" ]] 
        then
            vip_host_status="on"
            vip_host_status_text="${green}$i18n_enabled${normal}"
        else
            vip_host_status="off"
            vip_host_status_text="${red}$i18n_disabled${normal}"
        fi
        Println "  $(eval_gettext "VIP 服务器状态: \$vip_host_status_text")\n"
    }
    VipAddHost()
    {
        VipSetHostIp
        VipSetHostPort
        VipSetHostSeed
        VipSetHostToken
        VipSetHostStatus

        if [ ! -s "$VIP_FILE" ] 
        then
            printf '{"%s":{},"%s":[],"%s":[]}' "config" "users" "hosts" > "$VIP_FILE"
        fi

        new_host=$(
        $JQ_FILE -n --arg ip "$vip_host_ip" --arg port "$vip_host_port" \
            --arg seed "$vip_host_seed" --arg token "$vip_host_token" \
            --arg status "$vip_host_status" \
            '{
                ip: $ip,
                port: $port | tonumber,
                seed: $seed,
                token: $token,
                status: $status,
                channels: []
            }'
        )

        jq_path='["hosts"]'
        JQ add "$VIP_FILE" "[$new_host]"
        Println "$(eval_gettext "\$info VIP 服务器添加成功")\n"
    }
    VipEditHost()
    {
        VipListHosts
        echo -e "$(gettext "选择 VIP 服务器")"
        while read -p "$i18n_default_cancel" vip_hosts_num
        do
            case "$vip_hosts_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$vip_hosts_num" -gt 0 ] && [ "$vip_hosts_num" -le "$vip_hosts_count" ]
                    then
                        vip_hosts_index=$((vip_hosts_num-1))
                        vip_host_ip=${vip_hosts_ip[vip_hosts_index]}
                        vip_host_port=${vip_hosts_port[vip_hosts_index]}
                        vip_host_seed=${vip_hosts_seed[vip_hosts_index]}
                        vip_host_token=${vip_hosts_token[vip_hosts_index]}
                        vip_host_status=${vip_hosts_status[vip_hosts_index]}
                        if [ "$vip_host_status" == "on" ] 
                        then
                            vip_host_status_text="${green}$i18n_enabled${normal}"
                        else
                            vip_host_status_text="${red}$i18n_disabled${normal}"
                        fi
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        Println "
    $i18n_select_edit

    ${green}1.${normal} $(gettext "修改 IP/域名")
    ${green}2.${normal} $(gettext "修改 端口")
    ${green}3.${normal} $(gettext "修改 seed")
    ${green}4.${normal} $(gettext "修改 token")
    ${green}5.${normal} $(gettext "修改 状态")

    "
        read -p "$i18n_default_cancel" edit_vip_host_num

        case $edit_vip_host_num in
            1) 
                Println "$(eval_gettext "原 IP/域名: \${red}\$vip_host_ip\${normal}")"
                VipSetHostIp
                jq_path='["hosts",'"$vip_hosts_index"',"ip"]'
                JQ update "$VIP_FILE" "$vip_host_ip"
                Println "$(eval_gettext "\$info IP/域名 修改成功")\n"
            ;;
            2) 
                Println "$(eval_gettext "原端口: \${red}\$vip_host_port\${normal}")"
                VipSetHostPort
                jq_number=true
                jq_path='["hosts",'"$vip_hosts_index"',"port"]'
                JQ update "$VIP_FILE" "$vip_host_port"
                Println "$(eval_gettext "\$info 端口 修改成功")\n"
            ;;
            3) 
                Println "$(eval_gettext "原 seed: \${red}\$vip_host_seed\${normal}")"
                VipSetHostSeed
                jq_path='["hosts",'"$vip_hosts_index"',"seed"]'
                JQ update "$VIP_FILE" "$vip_host_seed"
                Println "$(eval_gettext "\$info seed 修改成功")\n"
            ;;
            4) 
                Println "$(eval_gettext "原 token: \${red}\$vip_host_token\${normal}")"
                VipSetHostToken
                jq_path='["hosts",'"$vip_hosts_index"',"token"]'
                JQ update "$VIP_FILE" "$vip_host_token"
                Println "$(eval_gettext "\$info token 修改成功")\n"
            ;;
            5) 
                Println "$(eval_gettext "原状态: \$vip_host_status_text")"
                VipSetHostStatus
                jq_path='["hosts",'"$vip_hosts_index"',"status"]'
                JQ update "$VIP_FILE" "$vip_host_status"
                Println "$(eval_gettext "\$info 状态修改成功")\n"
            ;;
            *) Println "$i18n_canceled...\n" && exit 1
            ;;
        esac
    }
    VipGetHosts()
    {
        vip_hosts_list=""
        vip_hosts_count=0
        vip_hosts_ip=()
        vip_hosts_port=()
        vip_hosts_seed=()
        vip_hosts_token=()
        vip_hosts_status=()
        vip_hosts_channel_count=()
        vip_hosts_channel_id=()
        vip_hosts_channel_name=()
        vip_hosts_channel_epg_id=()
        while IFS="^" read -r ip port seed token status channels_count channels_id channels_name channels_epg_id
        do
            vip_hosts_count=$((vip_hosts_count+1))
            ip=${ip#\"}
            vip_hosts_ip+=("$ip")
            vip_hosts_port+=("$port")
            vip_hosts_seed+=("$seed")
            vip_hosts_token+=("$token")
            vip_hosts_status+=("$status")
            if [ "$status" == "on" ] 
            then
                status_text="${green} [$i18n_enabled] ${normal}"
            else
                status_text="${red} [$i18n_disabled] ${normal}"
            fi
            vip_hosts_channel_count+=("$channels_count")
            vip_hosts_channel_id+=("$channels_id")
            vip_hosts_channel_name+=("$channels_name")
            channels_epg_id=${channels_epg_id%\"}
            vip_hosts_channel_epg_id+=("$channels_epg_id")
            vip_hosts_list="$vip_hosts_list ${green}$vip_hosts_count.${normal}${indent_6}$(gettext "服务器"): ${green}$ip${normal}  $i18n_port: ${green}$port${normal}  $(gettext "频道数"): ${green}$channels_count${normal}$status_text\n${indent_6}seed: ${green}$seed${normal}  token: ${green}${token:-$i18n_none}${normal}\n\n"
        done < <($JQ_FILE '.hosts[]|[.ip,.port,.seed,.token,.status,(.channels|length),([.channels[].id]|join("|")),([.channels[].name]|join("|")),([.channels[].epg_id]|join("|"))]|join("^")' "$VIP_FILE")
        return 0
    }
    VipListHosts()
    {
        if [ ! -s "$VIP_FILE" ] 
        then
            Println "$(eval_gettext "\$error 请先添加 VIP 服务器")\n" && exit 1
        fi

        VipGetHosts

        if [ "$vip_hosts_count" -gt 0 ] 
        then
            Println "$vip_hosts_list"
        else
            Println "$(eval_gettext "\$error 请先添加 VIP 服务器")\n" && exit 1
        fi
    }
    VipDelHost()
    {
        VipListHosts
        echo -e "$(gettext "选择 VIP 服务器")"
        while read -p "$i18n_default_cancel" vip_hosts_num
        do
            case "$vip_hosts_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$vip_hosts_num" -gt 0 ] && [ "$vip_hosts_num" -le "$vip_hosts_count" ]
                    then
                        vip_hosts_index=$((vip_hosts_num-1))
                        vip_host_ip=${vip_hosts_ip[vip_hosts_index]}
                        vip_host_port=${vip_hosts_port[vip_hosts_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        jq_path='["hosts",'"$vip_hosts_index"']'
        JQ delete "$VIP_FILE"

        Println "$(eval_gettext "服务器 \${green}[ \$vip_host_ip ]\${normal} 删除成功")\n"
    }
    VipSetUserIp()
    {
        Println "$(gettext "请输入用户的 IP")"
        read -p "($(gettext "默认: 本机 IP")): " vip_user_ip
        [ -z "$vip_user_ip" ] && vip_user_ip=$(GetServerIp)
        if [[ -n $($JQ_FILE '.users[]|select(.ip=="'"$vip_user_ip"'")' "$VIP_FILE") ]] 
        then
            Println "$(eval_gettext "\$error 此 IP 已存在")\n" && exit 1
        fi
        Println "  $(eval_gettext "用户 IP: \${green} \$vip_user_ip \${normal}")\n"
    }

    VipSetUserLicense()
    {
        Println "$(gettext "请输入用户的授权码")"
        read -p "($(gettext "默认: 自动生成")): " vip_user_license
        if [ -z "$vip_user_license" ] 
        then
            random_number=$(od -An -N6 -t u8 < /dev/urandom)
            vip_user_license="m${random_number: -12}"
            while [[ -n $($JQ_FILE '.users[]|select(.license=="'"$vip_user_license"'")' "$VIP_FILE") ]] 
            do
                random_number=$(od -An -N6 -t u8 < /dev/urandom)
                vip_user_license="m${random_number: -12}"
            done
        elif [[ -n $($JQ_FILE '.users[]|select(.license=="'"$vip_user_license"'")' "$VIP_FILE") ]] 
        then
            Println "$(eval_gettext "\$error 此授权码已存在")\n" && exit 1
        fi
        Println "  $(eval_gettext "用户 license: \${green} \$vip_user_license \${normal}")\n"
    }

    VipSetUserSum()
    {
        Println "$(gettext "选择验证类型")

  ${green}1.${normal} $(gettext "ssum (一天)")
  ${green}2.${normal} $(gettext "tsum (可控制天数)")
  ${green}3.${normal} $(gettext "isum (永久)")

    "

        while read -p "($i18n_default: 2): " vip_user_sum_num 
        do
            case $vip_user_sum_num in
                1) 
                    vip_user_expire_days=1
                    vip_user_sum="ssum"
                    PrintfTime now '%s' -1
                    vip_user_expire=$((now+86400))
                    break
                ;;
                2|"") 
                    vip_user_sum="tsum"
                    Println "$(gettext "请输入天数")"
                    while read -p "($i18n_default: 1): " vip_user_expire_days 
                    do
                        case $vip_user_expire_days in
                            ""|1) 
                                vip_user_expire_days=1
                                PrintfTime now '%s' -1
                                vip_user_expire=$((now+86400))
                                break 2
                            ;;
                            *[!0-9]*) 
                                Println "$(eval_gettext "\$error 输入错误")\n"
                            ;;
                            *) 
                                if [[ $vip_user_expire_days -gt 1 ]]
                                then
                                    PrintfTime now '%s' -1
                                    vip_user_expire=$((now+86400*vip_user_expire_days))
                                    break 2
                                else
                                    Println "$(eval_gettext "\$error 输入错误")\n"
                                fi
                            ;;
                        esac
                    done
                ;;
                3) 
                    vip_user_expire_days=""
                    vip_user_sum="isum"
                    vip_user_expire=0
                    break
                ;;
                *) Println "$(eval_gettext "\$error 输入错误")\n"
                ;;
            esac
        done
        Println "  $(gettext "验证类型"): ${green} $vip_user_sum ${normal}\n  $(gettext "到期天数"): ${green} ${vip_user_expire_days:-$i18n_none} ${normal}\n"
    }

    VipSetUserName()
    {
        Println "$(gettext "请输入用户名称(可以是中文)")"
        read -p "($(gettext "默认: 随机")): " vip_user_name
        if [ -z "$vip_user_name" ] 
        then
            vip_user_name=$(RandStr)
            while [[ -n $($JQ_FILE '.users[]|select(.name=="'"$vip_user_name"'")' "$VIP_FILE") ]] 
            do
                vip_user_name=$(RandStr)
            done
        elif [[ -n $($JQ_FILE '.users[]|select(.name=="'"$vip_user_name"'")' "$VIP_FILE") ]] 
        then
            Println "$(eval_gettext "\$error 此用户名已存在")\n" && exit 1
        fi
        Println "  $(eval_gettext "用户名称: \${green} \$vip_user_name \${normal}")\n"
    }
    VipAddUser()
    {
        if [ ! -s "$VIP_FILE" ] 
        then
            printf '{"%s":{},"%s":[],"%s":[]}' "config" "users" "hosts" > "$VIP_FILE"
        fi

        VipSetUserIp
        VipSetUserLicense
        VipSetUserSum
        VipSetUserName

        new_user=$(
        $JQ_FILE -n --arg ip "$vip_user_ip" --arg license "$vip_user_license" \
            --arg sum "$vip_user_sum" --arg expire "$vip_user_expire" \
            --arg name "$vip_user_name" \
            '{
                ip: $ip,
                license: $license,
                sum: $sum,
                expire: $expire | tonumber,
                name: $name
            }'
        )

        jq_path='["users"]'
        JQ add "$VIP_FILE" "[$new_user]"

        Println "$(eval_gettext "\$info 添加成功")\n"
    }
    VipEditUser()
    {
        VipListUsers

        while read -p "$(gettext "选择用户"): " vip_users_num
        do
            case "$vip_users_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$vip_users_num" -gt 0 ] && [ "$vip_users_num" -le "$vip_users_count" ]
                    then
                        vip_users_index=$((vip_users_num-1))
                        vip_user_ip=${vip_users_ip[vip_users_index]}
                        vip_user_license=${vip_users_license[vip_users_index]}
                        vip_user_sum=${vip_users_sum[vip_users_index]}
                        vip_user_expire=${vip_users_expire[vip_users_index]}
                        if [ "$vip_user_expire" -gt 0 ] 
                        then
                            vip_user_expire_text=$(date +%c --date=@"$vip_user_expire")
                        else
                            vip_user_expire_text="$i18n_none"
                        fi
                        vip_user_name=${vip_users_name[vip_users_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        Println "
    $i18n_select_edit

    ${green}1.${normal} $(gettext "修改 用户名")
    ${green}2.${normal} $(gettext "修改 IP")
    ${green}3.${normal} $(gettext "修改 授权码")
    ${green}4.${normal} $(gettext "修改 验证类型/到期日")

    "
        read -p "$i18n_default_cancel" edit_vip_user_num

        case $edit_vip_user_num in
            1) 
                Println "$(eval_gettext "原用户名: \${red}\$vip_user_name\${normal}")"
                VipSetUserName
                jq_path='["users",'"$vip_users_index"',"name"]'
                JQ update "$VIP_FILE" "$vip_user_name"
                Println "$(eval_gettext "\$info 用户名修改成功")\n"
            ;;
            2) 
                Println "$(eval_gettext "原 IP: \${red}\$vip_user_ip\${normal}")"
                VipSetUserIp
                jq_path='["users",'"$vip_users_index"',"ip"]'
                JQ update "$VIP_FILE" "$vip_user_ip"
                Println "$(eval_gettext "\$info IP 更新成功")\n"
            ;;
            3) 
                Println "$(eval_gettext "原授权码: \${red}\$vip_user_license\${normal}")"
                VipSetUserLicense
                jq_path='["users",'"$vip_users_index"',"license"]'
                JQ update "$VIP_FILE" "$vip_user_license"
                Println "$(eval_gettext "\$info 授权码修改成功")\n"
            ;;
            4) 
                Println "$(eval_gettext "原验证类型: \${red}\$vip_user_sum\${normal}")\n$(eval_gettext "原到期日: \${red}\$vip_user_expire_text\${normal}")"
                VipSetUserSum
                jq_path='["users",'"$vip_users_index"',"sum"]'
                JQ update "$VIP_FILE" "$vip_user_sum"
                jq_number=true
                jq_path='["users",'"$vip_users_index"',"expire"]'
                JQ update "$VIP_FILE" "$vip_user_expire"
                Println "$(eval_gettext "\$info 验证类型/到期日修改成功")\n"
            ;;
            *) Println "$i18n_canceled...\n" && exit 1
            ;;
        esac
    }
    VipGetUsers()
    {
        VipGetConfig
        vip_users_list=""
        vip_users_count=0
        vip_users_ip=()
        vip_users_license=()
        vip_users_sum=()
        vip_users_expire=()
        vip_users_name=()
        while IFS=":" read -r ip license sum expire name
        do
            vip_users_count=$((vip_users_count+1))
            ip=${ip#\"}
            vip_users_ip+=("$ip")
            vip_users_license+=("$license")
            vip_users_sum+=("$sum")
            vip_users_expire+=("$expire")
            name=${name%\"}
            vip_users_name+=("$name")
            if [ "$expire" -gt 0 ] 
            then
                expire_text=$(date +%c --date=@"$expire")
            else
                expire_text="$i18n_none"
            fi
            if [ -n "${vip_public_host:-}" ] 
            then
                m3u_link="$vip_public_host/vip/$license/playlist.m3u"
            else
                m3u_link="${FFMPEG_MIRROR_LINK%/*}/vip/$license/playlist.m3u"
            fi
            vip_users_list="$vip_users_list ${green}$vip_users_count.${normal}${indent_6}$(gettext "用户名"): ${green}$name${normal}  ip: ${green}$ip${normal}  $(gettext "到期日"): ${green}$expire_text${normal}\n${indent_6}$(gettext "授权码"): ${green}$license${normal}  $(gettext "认证方式"): ${green}$sum${normal}\n${indent_6}$(gettext "m3u 播放链接"): ${green}$m3u_link${normal}\n\n"
        done < <($JQ_FILE '.users[]|[.ip,.license,.sum,.expire,.name]|join(":")' "$VIP_FILE")
        return 0
    }
    VipListUsers()
    {
        if [ ! -s "$VIP_FILE" ] 
        then
