                            _4gtv_chnl_id=${_4gtv_chnls_id[_4gtv_chnl_index]}
                            _4gtv_chnl_name=${_4gtv_chnls_name[_4gtv_chnl_index]}
                            _4gtv_chnl_aid=${_4gtv_chnls_aid[_4gtv_chnl_index]}
