                    yesterday=$(date --date="yesterday" +"%Y-%m-%d")
                    min_start_time=$(date -d "yesterday 22:00:00" +%s)
                    max_start_time=$(date -d "today 23:59:59" +%s)
                    schedule=$(curl -s -Lm 20 -H "User-Agent: $USER_AGENT_BROWSER" "https://apps.foxnews.com/schedule_new/feed/fox-news.jn" |
                        $JQ_FILE --arg today "$today" --arg yesterday "$yesterday" --arg min "$min_start_time" --arg max "$max_start_time" --argjson keys '["title","time","sys_time"]' '.day
                        | map(select(.["@attributes"].value == $yesterday or .["@attributes"].value == $today).show[]
                        | .["sys_time"] = (."start-utc"|fromdate)
                        | select(.sys_time > ($min|tonumber) and .sys_time < ($max|tonumber))
                        | .["time"] = (.sys_time|strflocaltime("%-H:%M%p"))
                        | with_entries(select(.key as $k | $keys | index($k))))[]')

                    if [ -n "$schedule" ]
                    then
                        jq_file=true
                        jq_file_json=true
                        jq_path='["'"$chnl_id"'"]'
                        JQ update "$SCHEDULE_JSON" schedule
                        Println "$(eval_gettext "\$info \$chnl_name [\$chnl_id] 节目表更新成功")"
                    else
                        Println "$(eval_gettext "\$error \$chnl_name [\$chnl_id] 节目表更新失败")"
                    fi
                }

                ScheduleOther()
                {
                    if [ ! -s "$SCHEDULE_JSON" ]
                    then
                        printf '{"%s":[]}' "amlh" > "$SCHEDULE_JSON"
                    fi

                    for chnl in "${other_chnls[@]}"
                    do
                        chnl_id=${chnl%%:*}
                        chnl_name=${chnl#*:}
                        chnl_id_upper=$(tr '[:lower:]' '[:upper:]' <<< "${chnl_id:0:1}")"${chnl_id:1}"
                        Schedule"$chnl_id_upper"
                    done
                }
                GetCronChnls()
                {
                    cron_providers=()
                    cron_chnls=()
                    cron_providers_list=""
                    cron_providers_count=0
                    while IFS= read -r line
                    do
                        if [[ $line == *"|"* ]]
                        then
                            cron_providers_count=$((cron_providers_count+1))
                            cron_provider=${line%%|*}
                            for provider in "${providers[@]}"
                            do
                                if [ "${provider%:*}" == "$cron_provider" ]
                                then
                                    cron_provider_name="${provider#*:}"
                                    break
                                fi
                            done

                            cron_providers+=("$cron_provider")
                            cron_chnls+=("${line#*|}")
                            cron_providers_list="$cron_providers_list ${green}$cron_providers_count.${normal}${indent_6}$cron_provider_name\n\n"
                        fi
                    done < <($JQ_FILE -r '.schedule[]|[.provider,.chnls[]]|join("|")' "$CRON_FILE")
                }

                ScheduleView()
                {
                    GetCronChnls

                    providers_list=""
                    providers_count=0

                    for provider in "${providers[@]}"
                    do
                        providers_count=$((providers_count+1))
                        providers_list="$providers_list ${green}$providers_count.${normal}${indent_6}${provider#*:} [${provider%%:*}]\n\n"
                    done

                    Println "$(gettext "节目表来源")\n\n$providers_list"

                    while read -p "$i18n_default_cancel" provider_num
                    do
                        case "$provider_num" in
                            "")
                                Println "$i18n_canceled...\n" && exit 1
                            ;;
                            *[!0-9]*)
                                Println "$error $i18n_input_correct_number\n"
                            ;;
                            *)
                                if [ "$provider_num" -gt 0 ] && [ "$provider_num" -le "$providers_count" ]
                                then
                                    provider="${providers[$((provider_num-1))]%:*}"
                                    break
                                else
                                    Println "$error $i18n_input_correct_number\n"
                                fi
                            ;;
                        esac
                    done

                    var=("$provider"_chnls[@])

                    for((i=0;i<cron_providers_count;i++));
                    do
                        if [ "${cron_providers[i]}" == "$provider" ]
                        then
                            IFS="|" read -r -a cron_chnls <<< "${cron_chnls[i]}|"
                            break
                        fi
                    done

                    chnls_list=""
                    chnls_count=0

                    for chnl in "${!var}"
                    do
                        using=""
                        for cron_chnl in "${cron_chnls[@]}"
                        do
                            if [ "$cron_chnl" == "$chnl" ]
                            then
                                using="${green}[$(gettext "已添加")]${normal}"
                                break
                            fi
                        done
                        chnl_name=${chnl##*:}
                        if [ "$provider" == "ontvtonight" ]
                        then
                            chnl_id=${chnl%%@*}
                        else
                            chnl_id=${chnl%%:*}
                        fi
                        chnls_count=$((chnls_count+1))
                        chnls_list="$chnls_list ${green}$chnls_count.${normal}${indent_6}$chnl_name [$chnl_id] $using\n\n"
                    done

                    chnls=("${!var}")

                    echo -e "\n$chnls_list"
                }

                ScheduleAddChannel()
                {
                    for cron_chnl in "${cron_chnls[@]}"
                    do
                        if [ "$cron_chnl" == "$chnl" ]
                        then
                            return 0
                        fi
                    done
                    if [ "${add_provider:-1}" -eq 1 ] && [[ -z $($JQ_FILE '.schedule[] | select(.provider=="'"$provider"'")' "$CRON_FILE") ]]
                    then
                        add_provider=0
                        new_provider=$(
                        $JQ_FILE -n --arg provider "$provider" --arg chnl "$chnl" \
                        '{
                            "provider": $provider,
                            "chnls": [
                                $chnl
                            ]
                        }')
                        jq_path='["schedule"]'
                        JQ add "$CRON_FILE" "[$new_provider]"
                    else
                        jq_map_string=true
                        jq_path='["schedule"]'
                        jq_path2='["chnls"]'
                        JQ add "$CRON_FILE" provider "$provider" "[\"$chnl\"]"
                        add_provider=0
                    fi
                    Println "$info $(gettext "频道") [ ${chnl##*:} ] $(gettext "添加成功")"
                }

                ScheduleAdd()
                {
                    ScheduleView
                    echo -e " ${green}$((chnls_count+1)).${normal}${indent_6}$i18n_all"

                    Println "$(gettext "多个频道用空格分隔 比如: 5 7 9-11")"
                    while read -p "$i18n_default_cancel" chnls_num
                    do
                        if [ -z "$chnls_num" ]
                        then
                            Println "$i18n_canceled...\n" && exit 1
                        fi

                        if [ "$chnls_num" == $((chnls_count+1)) ]
                        then
                            for chnl in "${chnls[@]}"
                            do
                                ScheduleAddChannel
                            done
                            break
                        fi

                        IFS=" " read -ra chnls_num_arr <<< "$chnls_num"

                        error_no=0
                        for chnl_num in "${chnls_num_arr[@]}"
                        do
                            case "$chnl_num" in
                                *"-"*)
                                    chnl_num_start=${chnl_num%-*}
                                    chnl_num_end=${chnl_num#*-}
                                    if [[ $chnl_num_start == *[!0-9]* ]] || [[ $chnl_num_end == *[!0-9]* ]] || [ "$chnl_num_start" -eq 0 ] || [ "$chnl_num_end" -eq 0 ] || [ "$chnl_num_end" -gt "$chnls_count" ] || [ "$chnl_num_start" -ge "$chnl_num_end" ]
                                    then
                                        error_no=3
                                        break
                                    fi
                                ;;
                                *[!0-9]*)
                                    error_no=1
                                    break
                                ;;
                                *)
                                    if [ "$chnl_num" -lt 1 ] || [ "$chnl_num" -gt "$chnls_count" ]
                                    then
                                        error_no=2
                                        break
                                    fi
                                ;;
                            esac
                        done

                        case "$error_no" in
                            1|2|3)
                                Println "$error $i18n_input_correct_number\n"
                            ;;
                            *)
                                for chnl_num in "${chnls_num_arr[@]}"
                                do
                                    if [[ $chnl_num =~ - ]]
                                    then
                                        start=${chnl_num%-*}
                                        end=${chnl_num#*-}
                                        for((i=start-1;i<end;i++));
                                        do
                                            chnl="${chnls[i]}"
                                            ScheduleAddChannel
                                        done
                                    else
                                        chnl="${chnls[chnl_num-1]}"
                                        ScheduleAddChannel
                                    fi
                                done
                                break
                            ;;
                        esac
                    done
                }

                ScheduleDelChannel()
                {
                    jq_map_string=true
                    jq_path='["schedule"]'
                    jq_path2='["chnls"]'
                    JQ delete "$CRON_FILE" provider "$provider" "[\"$chnl\"]"
                }

                ScheduleViewCron()
                {
                    GetCronChnls

                    [ -z "$cron_providers_list" ] && Println "$(eval_gettext "\$error 没有计划任务")\n" && exit 1

                    Println "$(gettext "计划任务节目表")\n\n$cron_providers_list"

                    while read -p "$i18n_default_cancel" provider_num
                    do
                        case "$provider_num" in
                            "")
                                Println "$i18n_canceled...\n" && exit 1
                            ;;
                            *[!0-9]*)
                                Println "$error $i18n_input_correct_number\n"
                            ;;
                            *)
                                if [ "$provider_num" -gt 0 ] && [ "$provider_num" -le "$cron_providers_count" ]
                                then
                                    provider="${cron_providers[provider_num-1]}"
                                    IFS="|" read -r -a chnls <<< "${cron_chnls[provider_num-1]}|"
                                    break
                                else
                                    Println "$error $i18n_input_correct_number\n"
                                fi
                            ;;
                        esac
                    done

                    chnls_list=""
                    chnls_count=0

                    for chnl in ${chnls[@]+"${chnls[@]}"}
                    do
                        chnl_name=${chnl##*:}
                        chnls_count=$((chnls_count+1))
                        chnls_list="$chnls_list ${green}$chnls_count.${normal}${indent_6}$chnl_name\n\n"
                    done

                    Println "$(gettext "计划任务频道")\n\n$chnls_list"
                }

                ScheduleDel()
                {
                    ScheduleViewCron

                    echo -e " ${green}$((chnls_count+1)).${normal}${indent_6}$i18n_all"

                    Println "$(gettext "选择删除的频道, 多个频道用空格分隔 比如: 5 7 9-11")"
                    while read -p "$i18n_default_cancel" chnls_num
                    do
                        if [ -z "$chnls_num" ]
                        then
                            Println "$i18n_canceled...\n" && exit 1
                        fi

                        if [ "$chnls_num" == $((chnls_count+1)) ]
                        then
                            jq_map_string=true
                            jq_json=true
                            jq_path='["schedule"]'
                            jq_path2='["chnls"]'
                            JQ update "$CRON_FILE" provider "$provider" []
                            break
                        fi

                        IFS=" " read -ra chnls_num_arr <<< "$chnls_num"

                        error_no=0
                        for chnl_num in "${chnls_num_arr[@]}"
                        do
                            case "$chnl_num" in
                                *"-"*)
                                    chnl_num_start=${chnl_num%-*}
                                    chnl_num_end=${chnl_num#*-}
                                    if [[ $chnl_num_start == *[!0-9]* ]] || [[ $chnl_num_end == *[!0-9]* ]] || [ "$chnl_num_start" -eq 0 ] || [ "$chnl_num_end" -eq 0 ] || [ "$chnl_num_end" -gt "$chnls_count" ] || [ "$chnl_num_start" -ge "$chnl_num_end" ]
                                    then
                                        error_no=3
                                        break
                                    fi
                                ;;
                                *[!0-9]*)
                                    error_no=1
                                    break
                                ;;
                                *)
                                    if [ "$chnl_num" -lt 1 ] || [ "$chnl_num" -gt "$chnls_count" ]
                                    then
                                        error_no=2
                                        break
                                    fi
                                ;;
                            esac
                        done

                        case "$error_no" in
                            1|2|3)
                                Println "$error $i18n_input_correct_number\n"
                            ;;
                            *)
                                for chnl_num in "${chnls_num_arr[@]}"
                                do
                                    if [[ $chnl_num =~ - ]]
                                    then
                                        start=${chnl_num%-*}
                                        end=${chnl_num#*-}
                                        for((i=start-1;i<end;i++));
                                        do
                                            chnl="${chnls[i]}"
                                            ScheduleDelChannel
                                        done
                                    else
                                        chnl="${chnls[chnl_num-1]}"
                                        ScheduleDelChannel
                                    fi
                                done
                                break
                            ;;
                        esac
                    done
                    Println "$(eval_gettext "\$info 删除成功")\n"
                }

                ScheduleExec()
                {
                    if [ -s "$CRON_FILE" ] && [[ $($JQ_FILE '.schedule' "$CRON_FILE") != null ]]
                    then
                        printf '{"%s":[]}' "hbo" > "$SCHEDULE_JSON"
                        while IFS="=" read -r provider_id chnls option
                        do
                            if [ "$chnls" != null ]
                            then
                                var=("$provider_id"_chnls[@])
                                if [[ -n ${!var:-} ]]
                                then
                                    unset "$provider_id"_chnls
                                    IFS="|" read -r -a "$provider_id"_chnls <<< "${chnls}|"
                                fi
                                if [ "$provider_id" == "other" ]
                                then
                                    for chnl in "${other_chnls[@]}"
                                    do
                                        chnl_id=${chnl%%:*}
                                        chnl_name=${chnl#*:}
                                        chnl_id_upper=$(tr '[:lower:]' '[:upper:]' <<< "${chnl_id:0:1}")"${chnl_id:1}"

                                        if ! Schedule"$chnl_id_upper"
                                        then
                                            Println "$(eval_gettext "\$error \$chnl_name 再次尝试...")"
                                            Schedule"$chnl_id_upper" || Println "$(eval_gettext "\$error \$chnl_id_upper 失败")"
                                        fi
                                    done
                                else
                                    provider_id_upper=$(tr '[:lower:]' '[:upper:]' <<< "${provider_id:0:1}")"${provider_id:1}"

                                    if ! Schedule"$provider_id_upper" "$option"
                                    then
                                        for provider in "${providers[@]}"
                                        do
                                            if [ "${provider%%:*}" == "$provider_id" ]
                                            then
                                                provider_name="${#*:}"
                                                break
                                            fi
                                        done

                                        Println "$(eval_gettext "\$error \$provider_name 再次尝试...")"
                                        Schedule"$provider_id_upper" "$option" || Println "$(eval_gettext "\$error \$provider_name 失败")"
                                    fi
                                fi
                            fi
                        done < <($JQ_FILE -r '.schedule[]|[.provider,(.chnls|sort|join("|")| if .=="" then "null" else . end),.option]|join("=")' "$CRON_FILE")
                        if [ -e "$IPTV_ROOT/vip.pid" ]
                        then
                            printf '%s' "" > "$VIP_USERS_ROOT/epg.update"
                        fi
                    else
                        Println "$(eval_gettext "\$error 计划任务为空, 请先添加频道 !")\n"
                    fi
                }

                ScheduleBackup()
                {
                    if [ ! -s "$CRON_FILE" ]
                    then
                        Println "$(eval_gettext "\$error 请先添加频道")\n"
                        exit 1
                    fi
                    echo
                    inquirer text_input "$(gettext "输入备份名称: ")" backup_name "$i18n_none"
                    backup_schedule=""
                    while IFS="=" read -r provider chnls option
                    do
                        if [ "$chnls" != null ]
                        then
                            [ -n "$backup_schedule" ] && backup_schedule="$backup_schedule,"
                            backup_schedule=$backup_schedule'{
                                "provider":"'"$provider"'",
                                "chnls":"'"$chnls"'"
                            }'
                        fi
                    done < <($JQ_FILE -r '.schedule[]|[.provider,(.chnls|sort|join("|")| if .=="" then "null" else . end),.option]|join("=")' "$CRON_FILE")
                    if [ -z "$backup_schedule" ]
                    then
                        Println "$(eval_gettext "\$error 请先添加频道")\n"
                        exit 1
                    fi
                    new_backup=$(
                    $JQ_FILE -n --arg name "$backup_name" --argjson schedule "[$backup_schedule]" \
                        '{
                            name: $name,
                            date: now|strflocaltime("%s")|tonumber,
                            schedule: $schedule
                        }'
                    )
                    jq_path='["schedule_backup"]'
                    JQ add "$CRON_FILE" "[$new_backup]"
                    Println "$(eval_gettext "\$info 任务备份成功")\n"
                }

                ScheduleListBackup()
                {
                    schedule_backup_names=()
                    schedule_backup_dates=()
                    schedule_backup_schedules=()
                    schedule_backup_count=0
                    schedule_backup_list=""
                    while IFS="^" read -r backup_name backup_date backup_schedule
                    do
                        schedule_backup_count=$((schedule_backup_count+1))
                        schedule_backup_names+=("$backup_name")
                        schedule_backup_dates+=("$backup_date")
                        schedule_backup_schedules+=("$backup_schedule")
                        PrintfTime date '%m-%d %H:%M:%S' "$backup_date"
                        schedule_backup_list="$schedule_backup_list $schedule_backup_count. $(gettext "备份名称"): ${green}$backup_name${normal} $(gettext "备份日期"): ${green}$date${normal}\n\n"
                    done < <($JQ_FILE -r '(.schedule_backup| if .== null then [] else . end)[]|([.name,.date,(.schedule|to_entries|map([.value.provider,.value.chnls]|join("="))|join(","))]|join("^"))' "$CRON_FILE")

                    if [ "$schedule_backup_count" -eq 0 ]
                    then
                        Println "$(eval_gettext "\$error 没有备份")\n"
                        exit 1
                    fi

                    Println "$schedule_backup_list"
                }

                ScheduleViewBackup()
                {
                    ScheduleListBackup

                    while read -p "$i18n_default_cancel" backup_num
                    do
                        case "$backup_num" in
                            "")
                                Println "$i18n_canceled...\n" && exit 1
                            ;;
                            *[!0-9]*)
                                Println "$error $i18n_input_correct_number\n"
                            ;;
                            *)
                                if [ "$backup_num" -gt 0 ] && [ "$backup_num" -le "$schedule_backup_count" ]
                                then
                                    schedule="${schedule_backup_schedules[backup_num-1]}"
                                    IFS="," read -r -a schedules <<< "$schedule"
                                    break
                                else
                                    Println "$error $i18n_input_correct_number\n"
                                fi
                            ;;
                        esac
                    done

                    schedules_list=""

                    for((i=0;i<${#schedules[@]};i++));
                    do
                        schedule_provider=${schedules[i]%=*}
                        for provider in "${providers[@]}"
                        do
                            if [ "${provider%:*}" == "$schedule_provider" ]
                            then
                                schedule_provider_name="${provider#*:}"
                                break
                            fi
                        done
                        schedule_chnl=${schedules[i]#*=}
                        IFS="|" read -r -a schedule_chnls <<< "$schedule_chnl"
                        schedule_chnls_list=""
                        for schedule_chnl in "${schedule_chnls[@]}"
                        do
                            if [ "$schedule_provider" == "ontvtonight" ]
                            then
                                schedule_chnl_id=${schedule_chnl%%@*}
                            else
                                schedule_chnl_id=${schedule_chnl%%:*}
                            fi
                            schedule_chnls_list="$schedule_chnls_list${indent_6}${schedule_chnl##*:} ($schedule_chnl_id)\n"
                        done
                        schedules_list="$schedules_list ${green}$((i+1)).${normal}${indent_6}$schedule_provider_name\n\n$schedule_chnls_list\n"
                    done

                    Println "$schedules_list"
                }

                ScheduleEditBackup()
                {
                    ScheduleListBackup

                    while read -p "$i18n_default_cancel" backup_num
                    do
                        case "$backup_num" in
                            "")
                                Println "$i18n_canceled...\n" && exit 1
                            ;;
                            *[!0-9]*)
                                Println "$error $i18n_input_correct_number\n"
                            ;;
                            *)
                                if [ "$backup_num" -gt 0 ] && [ "$backup_num" -le "$schedule_backup_count" ]
                                then
                                    backup_index=$((backup_num-1))
                                    backup_name_old=${schedule_backup_names[backup_index]}
                                    break
                                else
                                    Println "$error $i18n_input_correct_number\n"
                                fi
                            ;;
                        esac
                    done

                    echo
                    inquirer text_input "$(gettext "输入新的备份名称: ")" backup_name "$backup_name_old"

                    jq_path='["schedule_backup",'"$backup_index"',"name"]'
                    JQ update "$CRON_FILE" "$backup_name"
                    Println "$(eval_gettext "\$info 备份修改成功")\n"
                }

                ScheduleDelBackup()
                {
                    ScheduleListBackup

                    while read -p "$i18n_default_cancel" backup_num
                    do
                        case "$backup_num" in
                            "")
                                Println "$i18n_canceled...\n" && exit 1
                            ;;
                            *[!0-9]*)
                                Println "$error $i18n_input_correct_number\n"
                            ;;
                            *)
                                if [ "$backup_num" -gt 0 ] && [ "$backup_num" -le "$schedule_backup_count" ]
                                then
                                    backup_index=$((backup_num-1))
                                    backup_name=${schedule_backup_names[backup_index]}
                                    break
                                else
                                    Println "$error $i18n_input_correct_number\n"
                                fi
                            ;;
                        esac
                    done

                    jq_path='["schedule_backup",'"$backup_index"']'
                    JQ delete "$CRON_FILE"
                    Println "$(eval_gettext "\$info 备份 \$backup_name 删除成功")\n"
                }

                ScheduleRestoreBackup()
                {
                    ScheduleListBackup

                    while read -p "$i18n_default_cancel" backup_num
                    do
                        case "$backup_num" in
                            "")
                                Println "$i18n_canceled...\n" && exit 1
                            ;;
                            *[!0-9]*)
                                Println "$error $i18n_input_correct_number\n"
                            ;;
                            *)
                                if [ "$backup_num" -gt 0 ] && [ "$backup_num" -le "$schedule_backup_count" ]
                                then
                                    backup_index=$((backup_num-1))
                                    backup_name=${schedule_backup_names[backup_index]}
                                    backup_schedule="${schedule_backup_schedules[backup_index]}"
                                    IFS="," read -r -a backup_schedules <<< "$backup_schedule"
                                    break
                                else
                                    Println "$error $i18n_input_correct_number\n"
                                fi
                            ;;
                        esac
                    done

                    schedules_list=""
                    for((i=0;i<${#backup_schedules[@]};i++));
                    do
                        schedule_provider=${backup_schedules[i]%=*}
                        schedule_chnl=${backup_schedules[i]#*=}
                        IFS="|" read -r -a schedule_chnls <<< "$schedule_chnl"
                        schedule_chnls_list=""
                        for schedule_chnl in "${schedule_chnls[@]}"
                        do
                            [ -n "$schedule_chnls_list" ] && schedule_chnls_list="$schedule_chnls_list,"
                            schedule_chnls_list=$schedule_chnls_list'"'$schedule_chnl'"'
                        done
                        [ -n "$schedules_list" ] && schedules_list="$schedules_list,"
                        schedules_list=$schedules_list'{
                            "provider":"'"$schedule_provider"'",
                            "chnls":['"$schedule_chnls_list"']
                        }'
                    done

                    jq_json=true
                    jq_path='["schedule"]'
                    JQ update "$CRON_FILE" "[$schedules_list]"
                    Println "$(eval_gettext "\$info 备份 \$backup_name 恢复成功")\n"
                }

                ScheduleEnableCron()
                {
                    if crontab -l | grep -q "$AIOS_PREFIX/bin/tv s" 2> /dev/null
                    then
                        Println "$(eval_gettext "\$error 计划任务已开启 !")\n"
                    else
                        crontab -l > "$IPTV_ROOT/cron_tmp" 2> /dev/null || true
                        printf '%s\n' "0 0 * * * $AIOS_PREFIX/bin/tv s -" >> "$IPTV_ROOT/cron_tmp"
                        crontab "$IPTV_ROOT/cron_tmp" > /dev/null
                        rm -f "$IPTV_ROOT/cron_tmp"
                        Println "$(eval_gettext "\$info 计划任务开启成功 !")\n"
                    fi
                }

                ScheduleDisableCron()
                {
                    if crontab -l | grep -q "$AIOS_PREFIX/bin/tv s" 2> /dev/null
                    then
                        crontab -l > "$IPTV_ROOT/cron_tmp" 2> /dev/null || true
                        FilterFileLines "$AIOS_PREFIX/bin/tv s" "$IPTV_ROOT/cron_tmp"
                        crontab "$IPTV_ROOT/cron_tmp" > /dev/null
                        rm -f "$IPTV_ROOT/cron_tmp"
                        Println "$(eval_gettext "\$info 计划任务已关闭")\n"
                    else
                        Println "$(eval_gettext "\$error 计划任务未开启 !")\n"
                    fi
                }

                Schedule()
                {
                    if [ ! -d "$IPTV_ROOT" ]
                    then
                        Println "$(eval_gettext "\$error 尚未安装, 请先安装 !")" && exit 1
                    fi

                    GetDefault

                    if [ -n "$d_schedule_file" ]
                    then
                        SCHEDULE_JSON="$d_schedule_file"
                    else
                        Println "$(eval_gettext "\$error 请先设置 schedule_file 位置!")\n" && exit 1
                    fi

                    if [ ! -s "$CRON_FILE" ]
                    then
                        printf '{"%s":[]}' "schedule" > "$CRON_FILE"
                    fi

                    LoadListingsCatalog

                    if [ "${2:-}" == "4gtv" ]
                    then
                        provider_id="_4gtv"
                    elif [ "${2:-}" == "hbo" ]
                    then
                        provider_id="hboasia"
                    elif [ "${2:-}" == "si" ]
                    then
                        provider_id="singteltv"
                    elif [ "${2:-}" == "be" ]
                    then
                        provider_id="beinsports"
                    elif [ "${2:-}" == "beau" ]
                    then
                        provider_id="beinsportsau"
                    elif [ "${2:-}" == "su" ]
                    then
                        provider_id="supersport"
                    elif [ "${2:-}" == "bt" ]
                    then
                        provider_id="btsport"
                    elif [ "${2:-}" == "bton" ]
                    then
                        provider_id="btsporton"
                    elif [ "${2:-}" == "pr" ]
                    then
                        provider_id="premiersports"
                    elif [ "${2:-}" == "sk" ]
                    then
                        provider_id="sky"
                    else
                        provider_id=${2:-}
                    fi

                    if [ -n "${3:-}" ]
                    then
                        # variable indirection
                        var=("$provider_id"_chnls[@])
                        if [[ -n ${!var:-} ]]
                        then
                            provider_found=0
                            for chnl in "${!var}"
                            do
                                chnl_id=${chnl%%@*}
                                chnl_id=${chnl_id%%:*}
                                if [ "$chnl_id" == "$3" ]
                                then
                                    provider_found=1
                                    unset "$provider_id"_chnls
                                    IFS= read -r -a "$provider_id"_chnls <<< "$chnl"
                                    break
                                fi
                            done
                            [ "$provider_found" -eq 0 ] && Println "$(eval_gettext "\$error 没有找到频道")\n" && exit 1
                        fi
                    fi

                    case $provider_id in
                        jiushi)
                            ScheduleJiushi
                        ;;
                        niotv)
                            ScheduleNiotv
                        ;;
                        nowtv)
                            ScheduleNowtv
                        ;;
                        icable)
                            ScheduleIcable
                        ;;
                        hbo|hboasia)
                            ScheduleHboasia
                        ;;
                        hbous)
                            ScheduleHbous "${4:-}"
                        ;;
                        ontvtonight)
                            ScheduleOntvtonight
                        ;;
                        tvbhk)
                            ScheduleTvbhk
                        ;;
                        tvbhd)
                            ScheduleTvbhd
                        ;;
                        si|singteltv)
                            ScheduleSingteltv
                        ;;
                        cntv)
                            ScheduleCntv
                        ;;
                        tvbs)
                            ScheduleTvbs
                        ;;
                        astro)
                            ScheduleAstro
                        ;;
                        nbcsn)
                            ScheduleNbcsn
                        ;;
                        be|beinsports)
                            ScheduleBeinsports
                        ;;
                        beau|beinsportsau)
                            ScheduleBeinsportsau
                        ;;
                        su|supersport)
                            ScheduleSupersport
                        ;;
                        bt|btsport)
                            ScheduleBtsport
                        ;;
                        pr|premiersports)
                            SchedulePremiersports
                        ;;
                        sk|sky)
                            ScheduleSky
                        ;;
                        _4gtv)
                            Schedule_4gtv
                        ;;
                        other)
                            ScheduleOther
                        ;;
                        "")
                            local menu_key="${sh_locale:-zh_CN}"

                            if [ "${_menu_listings_cache_key:-}" != "$menu_key" ]
                            then
                                _menu_listings_cache="$(gettext "节目表计划任务面板")

  ${green}1.${normal} $(gettext "查看频道")
  ${green}2.${normal} $(gettext "添加频道")
  ${green}3.${normal} $(gettext "删除频道")
  ${green}4.${normal} $(gettext "查看任务")
  ${green}5.${normal} $(gettext "执行任务")
  ${green}6.${normal} $(gettext "开启计划任务")
  ${green}7.${normal} $(gettext "关闭计划任务")
  ${green}8.${normal} $(gettext "备份任务")
  ${green}9.${normal} $(gettext "查看备份")
 ${green}10.${normal} $(gettext "修改备份")
 ${green}11.${normal} $(gettext "恢复备份")
 ${green}12.${normal} $(gettext "删除备份")

                "
                                _menu_listings_cache_key="$menu_key"
                            fi

                            Println "$_menu_listings_cache"
                            read -p "$i18n_default_cancel" cron_num
                            [ -z "$cron_num" ] && Println "$i18n_canceled...\n" && exit 1

                            case $cron_num in
                                1) ScheduleView
                                ;;
                                2) ScheduleAdd
                                ;;
                                3) ScheduleDel
                                ;;
                                4) ScheduleViewCron
                                ;;
                                5) ScheduleExec
                                ;;
                                6) ScheduleEnableCron
                                ;;
                                7) ScheduleDisableCron
                                ;;
                                8) ScheduleBackup
                                ;;
                                9) ScheduleViewBackup
                                ;;
                                10) ScheduleEditBackup
                                ;;
                                11) ScheduleRestoreBackup
                                ;;
                                12) ScheduleDelBackup
                                ;;
                                *) Println "$i18n_canceled...\n" && exit 1
                                ;;
                            esac
                        ;;
                        "-")
                            local lbl_err_tag lbl_err_word
                            lbl_err_tag=$(gettext "[错误]")
                            lbl_err_word=$(gettext "错误")
                            while IFS= read -r line
                            do
                                if [[ $line == *"$lbl_err_tag"* ]] || [[ $line == *"$lbl_err_word"* ]] || [[ $line == *"错误"* ]]
                                then
                                    Println "$lbl_err_word: ${line#* }"
                                fi
                            done < <(ScheduleExec)
                        ;;
                        *)
                            for provider in "${providers[@]}"
                            do
                                provider_id=${provider%%:*}
                                provider_name=${provider#*:}
                                provider_chnls=("$provider_id"_chnls[@])
                                schedule=""
                                for provider_chnl in "${!provider_chnls}"
                                do
                                    if [ "$provider_id" == "ontvtonight" ]
                                    then
                                        chnl_id=${provider_chnl%%@*}
                                        chnl_name=${provider_chnl##@:}
                                    else
                                        chnl_id=${provider_chnl%%:*}
                                        chnl_name=${provider_chnl##*:}
                                    fi
                                    if [ "$chnl_id" == "$2" ]
                                    then
                                        unset "${provider_id}_chnls"
                                        IFS="|" read -r -a "${provider_id}_chnls" <<< "${provider_chnl}|"
                                        if [ "$provider_id" == "other" ]
                                        then
                                            chnl_id_upper=$(tr '[:lower:]' '[:upper:]' <<< "${chnl_id:0:1}")"${chnl_id:1}"
                                            Schedule"$chnl_id_upper" "${3:-}"
                                        else
                                            provider_id_upper=$(tr '[:lower:]' '[:upper:]' <<< "${provider_id:0:1}")"${provider_id:1}"
                                            Schedule"$provider_id_upper" "${3:-}"
                                        fi
                                        break
                                    fi
                                done

                                if [ -z "${schedule:-}" ]
                                then
                                    Println "$(eval_gettext "\$error \$provider_name 没有找到"): $2"
                                else
                                    if [ -e "$IPTV_ROOT/vip.pid" ]
                                    then
                                        printf '%s' "" > "$VIP_USERS_ROOT/epg.update"
                                    fi
                                    break
                                fi
                            done
                        ;;
                    esac
                }
                Schedule "$@"
                exit 0
            ;;
            singtel) 
                Println "$(eval_gettext "\$info 检测 singteltv ...")"
                while IFS= read -r line 
                do
                    if [[ $line =~ epgEndPoint ]] 
                    then
                        line=${line#*epgEndPoint&#34;:&#34;}
                        epg_end_point=${line%%&#34*}
                        line=${line#*tvChannelLists&#34;:}
                        tv_channel_lists=${line%%,&#34;errorMessage*}
                        tv_channel_lists=${tv_channel_lists//&#34;/\"}
                        $JQ_FILE -r --arg empty "$(gettext "空")" '.[]|[
                            (.title // $empty),
                            (.channelId // $empty),
                            (.language // []|join(","))
                        ]|@tsv' <<< "$tv_channel_lists"
                        break
                    fi
                done < <(curl -s -L "https://www.singtel.com/personal/products-services/tv/tv-programme-guide" 2> /dev/null)
                exit 0
            ;;
            astro)
                Println "$(eval_gettext "\$info 检测 astro ...")"

                SetDelimiters

                response=$(
                    curl -s -Lm 20 -H 'User-Agent: '"$USER_AGENT_BROWSER"'' https://contenthub-api.eco.astro.com.my/channel/all.json
                )

                jq_payload=$(JQs flat "$response")

                jq_path='[
                    ["response","id"],
                    ["response","title"],
                    ["response","description"],
                    ["response","isHd"],
                    ["response","language"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                IFS="${delimiters[2]}" read -ra chnls_id <<< "$jq_response_id"
                IFS="${delimiters[2]}" read -ra chnls_title <<< "$jq_response_title"
                IFS="${delimiters[2]}" read -ra chnls_description <<< "$jq_response_description"
                IFS="${delimiters[2]}" read -ra chnls_is_hd <<< "$jq_response_isHd"
                IFS="${delimiters[2]}" read -ra chnls_language <<< "$jq_response_language"

                chnls_list=""
                for((i=0;i<${#chnls_id[@]};i++));
                do
                    if [ "${chnls_is_hd[i]}" = true ] 
                    then
                        is_hd="${green}$i18n_yes${normal}"
                    else
                        is_hd="${red}$i18n_no${normal}"
                    fi
                    chnls_list="$chnls_list ${green}$((i+1)).${normal}${indent_6}$(gettext "频道ID"): ${green}${chnls_id[i]}${normal} $(gettext "频道名称"): ${green}${chnls_title[i]}${normal}\n${indent_6}$(gettext "高清"): ${green}$is_hd${normal} $(gettext "语言"): ${green}${chnls_language[i]}${normal}\n${indent_6}${chnls_description[i]}\n\n"
                done

                Println "$chnls_list"
                exit 0
            ;;
            m) 
                [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请先安装 !")" && exit 1
                [ ! -d "${MONITOR_LOG%/*}" ] && MONITOR_LOG="$HOME/monitor.log"

                cmd=${2:-}

                case $cmd in
                    "s"|"stop") 
                        MonitorStop
                    ;;
                    "l"|"log")
                        MonitorList "${3:-}"
                    ;;
                    *) 
                        MonitorStart
                    ;;
                esac
                exit 0
            ;;
            e) 
                [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请检查 !")\n" && exit 1
                RunEditor "$CHANNELS_FILE" && exit 0
            ;;
            ee) 
                [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请检查 !")\n" && exit 1
                GetDefault
                [ -z "$d_sync_file" ] && Println "$(eval_gettext "\$error sync_file 未设置, 请检查 !")\n" && exit 1
                echo
                edit_options=($d_sync_file)
                inquirer list_input "$(gettext "选择修改的文件")" edit_options edit_option
                RunEditor "$edit_option"
                exit 0
            ;;
            d)
                [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请检查 !")\n" && exit 1

                echo
                ExitOnList n "$(gettext "请确保已经升级到最新脚本, 是否继续")"

                ShFallback

                channels=""
                while IFS= read -r line
                do
                    if [[ $line == *\"pid\":* ]]
                    then
                        pid=${line#*:}
                        pid=${pid%,*}
                        rand_pid=$pid
                        while [[ -n $($JQ_FILE '.channels[]|select(.pid=='"$rand_pid"')' "$CHANNELS_FILE") ]]
                        do
                            true &
                            rand_pid=$!
                        done
                        line=${line//$pid/$rand_pid}
                    fi
                    channels="$channels$line"
                done < <(curl -s -Lm 20 "$SH_FALLBACK/$DEFAULT_DEMOS")

                [ -z "$channels" ] && Println "$(eval_gettext "\$error 暂时无法连接服务器, 请稍后再试 !")\n" && exit 1

                SetDelimiters

                jq_payload=$(JQs flat "$channels")

                jq_path='["channel_name"]'

                channel_name=$(JQs get jq_payload)

                IFS="${delimiters[1]}" read -r -a channels_name <<< "$channel_name"

                echo
                channels_name+=("$i18n_all")
                inquirer list_input "$(gettext "选择添加的频道")" channels_name channel_name

                if [ "$channel_name" != "$i18n_all" ]
                then
                    channels=$($JQ_FILE '[.[]|select(.channel_name=="'"$channel_name"'")]' <<< "$channels")
                fi

                jq_path='["channels"]'
                JQ add "$CHANNELS_FILE" "$channels"
                Println "$(eval_gettext "\$info 频道添加成功 !")\n"

                exit 0
            ;;
            ffmpeg|FFmpeg|mirror) 
                if [[ ! -x $(command -v curl) ]]
                then
                    DepsCheck
                fi

                JQInstall

                mkdir -p "$FFMPEG_MIRROR_ROOT/builds"
                mkdir -p "$FFMPEG_MIRROR_ROOT/releases"

                git_download=0
                release_download=0
                git_version_old=""
                release_version_old=""

                if [ -e "$FFMPEG_MIRROR_ROOT/index.html" ]
                then
                    while IFS= read -r line
                    do
                        if [[ $line == *"<th>"* ]]
                        then
                            if [[ $line == *"git"* ]]
                            then
                                git_version_old="$line"
                            else
                                release_version_old="$line"
                            fi
                        fi
                    done < "$FFMPEG_MIRROR_ROOT/index.html"
                fi

                if curl -s -L "https://www.johnvansickle.com/ffmpeg/index.html" -o "$FFMPEG_MIRROR_ROOT/index.html_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/index.html_tmp" "$FFMPEG_MIRROR_ROOT/index.html"
                    curl -s -L "https://www.johnvansickle.com/ffmpeg/style.css" -o "$FFMPEG_MIRROR_ROOT/style.css"
                else
                    Println "$(eval_gettext "\$error FFmpeg 查询新版本出错, 无法连接 johnvansickle.com ?")"
                fi

                if [ -e "$FFMPEG_MIRROR_ROOT/index.html" ]
                then
                    while IFS= read -r line
                    do
                        if [[ $line == *"<th>"* ]]
                        then
                            if [[ $line == *"git"* ]]
                            then
                                git_version_new="$line"
                                if [ "$git_version_new" != "$git_version_old" ] || [ ! -e "$FFMPEG_MIRROR_ROOT/builds/ffmpeg-git-amd64-static.tar.xz" ]
                                then
                                    git_download=1
                                fi
                            else
                                release_version_new="$line"
                                [ "$release_version_new" != "$release_version_old" ] && release_download=1
                            fi
                        fi

                        if [[ $line == *"tar.xz"* ]]
                        then
                            if [[ $line == *"git"* ]] && [ "$git_download" -eq 1 ]
                            then
                                line=${line#*<td><a href=\"}
                                git_link=${line%%\" style*}
                                build_file_name=${git_link##*/}
                                if [ "$git_version_new" != "$git_version_old" ] || [ ! -e "$FFMPEG_MIRROR_ROOT/builds/${build_file_name}" ]
                                then
                                    Println "$(eval_gettext "\$info 下载 \$build_file_name ...")"
                                    if curl -s -L "$git_link" -o "$FFMPEG_MIRROR_ROOT/builds/${build_file_name}_tmp"
                                    then
                                        mv "$FFMPEG_MIRROR_ROOT/builds/${build_file_name}_tmp" "$FFMPEG_MIRROR_ROOT/builds/${build_file_name}"
                                    else
                                        Println "$(eval_gettext "\$error FFmpeg git build 下载出错, 无法连接 github ?")"
                                    fi
                                fi
                            else
                                if [ "$release_download" -eq 1 ]
                                then
                                    line=${line#*<td><a href=\"}
                                    release_link=${line%%\" style*}
                                    release_file_name=${release_link##*/}
                                    if [ "$release_version_new" != "$release_version_old" ] || [ ! -e "$FFMPEG_MIRROR_ROOT/releases/${release_file_name}" ]
                                    then
                                        Println "$(eval_gettext "\$info 下载 \$release_file_name ...")"
                                        if curl -s -L "$release_link" -o "$FFMPEG_MIRROR_ROOT/releases/${release_file_name}_tmp"
                                        then
                                            mv "$FFMPEG_MIRROR_ROOT/releases/${release_file_name}_tmp" "$FFMPEG_MIRROR_ROOT/releases/${release_file_name}"
                                        else
                                            Println "$(eval_gettext "\$error FFmpeg release build 下载出错, 无法连接 github ?")"
                                        fi
                                    fi
                                fi
                            fi
                        fi
                    done < "$FFMPEG_MIRROR_ROOT/index.html"

                    #Println "输入镜像网站链接(比如: $FFMPEG_MIRROR_LINK)"
                    #read -p "$i18n_default_cancel" FFMPEG_LINK
                    #[ -z "$FFMPEG_LINK" ] && Println "$i18n_canceled...\n" && exit 1
                    #sed -i "s+https://johnvansickle.com/ffmpeg/\(builds\|releases\)/\(.*\).tar.xz\"+$FFMPEG_LINK/\1/\2.tar.xz\"+g" "$FFMPEG_MIRROR_ROOT/index.html"

                    sed -i "s+https://johnvansickle.com/ffmpeg/\(builds\|releases\)/\(.*\).tar.xz\"+\1/\2.tar.xz\"+g" "$FFMPEG_MIRROR_ROOT/index.html"
                fi

                while IFS= read -r line
                do
                    if [[ $line == *"latest stable release is"* ]]
                    then
                        line=${line#*<a href=\"}
                        poppler_name=${line%%.tar.xz*}
                        poppler_name="poppler-${POPPLER_VER}"
                        if [ ! -e "$FFMPEG_MIRROR_ROOT/$poppler_name.tar.xz" ]
                        then
                            Println "$(eval_gettext "\$info 下载 poppler ...")"
                            rm -f "$FFMPEG_MIRROR_ROOT/poppler-"*.tar.xz
                            if curl -s -L "https://poppler.freedesktop.org/$poppler_name.tar.xz" -o "$FFMPEG_MIRROR_ROOT/$poppler_name.tar.xz_tmp"
                            then
                                mv "$FFMPEG_MIRROR_ROOT/$poppler_name.tar.xz_tmp" "$FFMPEG_MIRROR_ROOT/$poppler_name.tar.xz"
                            else
                                Println "$(eval_gettext "\$error poppler 下载出错")"
                            fi
                        fi
                    elif [[ $line == *"poppler encoding data"* ]]
                    then
                        line=${line#*<a href=\"}
                        poppler_data_name=${line%%.tar.gz*}
                        if [ ! -e "$FFMPEG_MIRROR_ROOT/$poppler_data_name.tar.gz" ]
                        then
                            Println "$(eval_gettext "\$info 下载 poppler-data ...")"
                            rm -f "$FFMPEG_MIRROR_ROOT/poppler-data-"*.tar.gz
                            if curl -s -L "https://poppler.freedesktop.org/$poppler_data_name.tar.gz" -o "$FFMPEG_MIRROR_ROOT/$poppler_data_name.tar.gz_tmp"
                            then
                                mv "$FFMPEG_MIRROR_ROOT/$poppler_data_name.tar.gz_tmp" "$FFMPEG_MIRROR_ROOT/$poppler_data_name.tar.gz"
                            else
                                Println "$(eval_gettext "\$error poppler-data 下载出错")"
                            fi
                        fi
                        break
                    fi
                done < <(curl -s -Lm 20 "https://poppler.freedesktop.org/" 2> /dev/null)

                if jq_ver=$(curl -s -Lm 20 "$JQ_API_LINK" | $JQ_FILE -r '.tag_name')
                then
                    if [ ! -e "$FFMPEG_MIRROR_ROOT/$jq_ver/jq-linux64" ] || [ ! -e "$FFMPEG_MIRROR_ROOT/$jq_ver/jq-linux32" ]
                    then
                        Println "$(eval_gettext "\$info 下载 jq ...")"
                        rm -rf "$FFMPEG_MIRROR_ROOT/jq-"*
                        mkdir -p "$FFMPEG_MIRROR_ROOT/$jq_ver/"
                        if curl -s -L "${JQ_REPO_LINK}/releases/download/$jq_ver/jq-linux64" -o "$FFMPEG_MIRROR_ROOT/$jq_ver/jq-linux64_tmp" && curl -s -L "${JQ_REPO_LINK}/releases/download/$jq_ver/jq-linux32" -o "$FFMPEG_MIRROR_ROOT/$jq_ver/jq-linux32_tmp"
                        then
                            mv "$FFMPEG_MIRROR_ROOT/$jq_ver/jq-linux64_tmp" "$FFMPEG_MIRROR_ROOT/$jq_ver/jq-linux64"
                            mv "$FFMPEG_MIRROR_ROOT/$jq_ver/jq-linux32_tmp" "$FFMPEG_MIRROR_ROOT/$jq_ver/jq-linux32"
                        else
                            Println "$(eval_gettext "\$error jq 下载出错, 无法连接 github ?")"
                        fi
                    fi
                else
                    Println "$(eval_gettext "\$error jq 下载出错, 无法连接 github ?")"
                fi

                MirrorVerifySha256()
                {
                    local target_file="$1"
                    local dgst_file="$2"
                    if [ ! -s "$target_file" ] || [ ! -s "$dgst_file" ]
                    then
                        return 1
                    fi

                    local expected="" actual=""
                    expected=$(awk 'toupper($0) ~ /SHA2-?256/ {print tolower($NF); exit}' "$dgst_file" 2> /dev/null || true)
                    if [ -z "$expected" ]
                    then
                        expected=$(awk '{print tolower($1); exit}' "$dgst_file" 2> /dev/null || true)
                    fi

                    if [[ ! "$expected" =~ ^[0-9a-f]{64}$ ]]
                    then
                        return 1
                    fi

                    if command -v sha256sum > /dev/null 2>&1
                    then
                        actual=$(sha256sum "$target_file" | awk '{print tolower($1)}')
                    elif command -v shasum > /dev/null 2>&1
                    then
                        actual=$(shasum -a 256 "$target_file" | awk '{print tolower($1)}')
                    else
                        return 1
                    fi

                    [ "$actual" == "$expected" ]
                }

                MirrorSyncCoreReleases()
                {
                    local core="$1"
                    local repo="$2"
                    local asset_prefix="$3"
                    local pinned_vers="$4"
                    shift 4
                    local core_archs=("$@")
                    local recent_count="${PROXY_MIRROR_RECENT_COUNT:-5}"
                    local releases_json=""

                    if releases_json=$(curl -fsSL -m 30 "https://api.github.com/repos/${repo}/releases?per_page=${recent_count}" 2> /dev/null) && printf '%s' "$releases_json" | $JQ_FILE -e 'type == "array" and length > 0' > /dev/null 2>&1
                    then
                        printf '%s\n' "$releases_json" | $JQ_FILE '[.[] | select(.draft == false and .prerelease == false) | {tag_name, published_at, prerelease}]' > "$FFMPEG_MIRROR_ROOT/${core}_versions.json_tmp" \
                            && mv -f "$FFMPEG_MIRROR_ROOT/${core}_versions.json_tmp" "$FFMPEG_MIRROR_ROOT/${core}_versions.json"
                        printf '%s\n' "$releases_json" | $JQ_FILE 'first(.[] | select(.draft == false and .prerelease == false)) // .[0]' > "$FFMPEG_MIRROR_ROOT/${core}.json_tmp" \
                            && mv -f "$FFMPEG_MIRROR_ROOT/${core}.json_tmp" "$FFMPEG_MIRROR_ROOT/${core}.json"
                    else
                        Println "$(eval_gettext "\$error \$core 版本列表获取失败, 无法连接 github ?")"
                        return 1
                    fi

                    local all_tags=()
                    local t=""
                    while IFS= read -r t
                    do
                        [ -n "$t" ] && all_tags+=("$t")
                    done < <(printf '%s\n' "$releases_json" | $JQ_FILE -r '.[] | select(.draft == false and .prerelease == false) | .tag_name')

                    for t in $pinned_vers
                    do
                        local exists=0 x=""
                        for x in "${all_tags[@]+"${all_tags[@]}"}"
                        do
                            [ "$x" == "$t" ] && exists=1 && break
                        done
                        [ "$exists" -eq 0 ] && all_tags+=("$t")
                    done

                    local tag="" arch=""
                    for tag in "${all_tags[@]+"${all_tags[@]}"}"
                    do
                        mkdir -p "$FFMPEG_MIRROR_ROOT/${core}/${tag}/"
                        for arch in "${core_archs[@]+"${core_archs[@]}"}"
                        do
                            local zip_path="$FFMPEG_MIRROR_ROOT/${core}/${tag}/${asset_prefix}-${arch}.zip"
                            local dgst_path="${zip_path}.dgst"
                            if MirrorVerifySha256 "$zip_path" "$dgst_path"
                            then
                                continue
                            fi

                            Println "$(eval_gettext "\$info 下载 \${asset_prefix}-\${arch} \$tag ...")"
                            if curl -fsSL -m 120 "https://github.com/${repo}/releases/download/${tag}/${asset_prefix}-${arch}.zip" -o "${zip_path}_tmp" \
                            && curl -fsSL -m 30 "https://github.com/${repo}/releases/download/${tag}/${asset_prefix}-${arch}.zip.dgst" -o "${dgst_path}_tmp" \
                            && MirrorVerifySha256 "${zip_path}_tmp" "${dgst_path}_tmp"
                            then
                                mv -f "${zip_path}_tmp" "$zip_path"
                                mv -f "${dgst_path}_tmp" "$dgst_path"
                            else
                                rm -f "${zip_path}_tmp" "${dgst_path}_tmp"
                                Println "$(eval_gettext "\$error \${asset_prefix}-\${arch} \$tag 下载或校验出错")"
                            fi
                        done
                    done
                }

                v2ray_archs=( linux-32 linux-64 linux-arm32-v5 linux-arm32-v6 linux-arm32-v7a linux-arm64-v8a macos-64 macos-arm64-v8a )
                xray_archs=( linux-32 linux-64 linux-arm32-v5 linux-arm32-v6 linux-arm32-v7a linux-arm64-v8a linux-s390x macos-64 macos-arm64-v8a )

                MirrorSyncCoreReleases "v2ray" "$V2RAY_REPO" "v2ray" "${V2RAY_MIRROR_PINNED_VERSIONS:-v5.18.0}" "${v2ray_archs[@]+"${v2ray_archs[@]}"}"
                MirrorSyncCoreReleases "xray" "$XRAY_REPO" "Xray" "${XRAY_MIRROR_PINNED_VERSIONS:-v25.9.11 v26.5.3 v26.5.9 v26.6.22 v26.6.27}" "${xray_archs[@]+"${xray_archs[@]}"}"

                if geodata_json=$(curl -fsSL -m 30 "$PROXY_GEODATA_API" 2> /dev/null) && geodata_ver=$(printf '%s' "$geodata_json" | $JQ_FILE -r '.tag_name // empty') && [ -n "$geodata_ver" ]
                then
                    mkdir -p "$FFMPEG_MIRROR_ROOT/geodata/${geodata_ver}/"
                    printf '%s\n' "$geodata_json" > "$FFMPEG_MIRROR_ROOT/geodata/geodata.json_tmp" \
                        && mv -f "$FFMPEG_MIRROR_ROOT/geodata/geodata.json_tmp" "$FFMPEG_MIRROR_ROOT/geodata/geodata.json"
                    for geo_file in geoip.dat geosite.dat
                    do
                        geo_dst="$FFMPEG_MIRROR_ROOT/geodata/${geodata_ver}/${geo_file}"
                        geo_sum="${geo_dst}.sha256sum"
                        if MirrorVerifySha256 "$geo_dst" "$geo_sum"
                        then
                            continue
                        fi

                        Println "$(eval_gettext "\$info 下载 geodata \$geo_file \$geodata_ver ...")"
                        if curl -fsSL -m 60 "${PROXY_GEODATA_LINK}/${geodata_ver}/${geo_file}" -o "${geo_dst}_tmp" \
                        && curl -fsSL -m 30 "${PROXY_GEODATA_LINK}/${geodata_ver}/${geo_file}.sha256sum" -o "${geo_sum}_tmp" \
                        && MirrorVerifySha256 "${geo_dst}_tmp" "${geo_sum}_tmp"
                        then
                            mv -f "${geo_dst}_tmp" "$geo_dst"
                            mv -f "${geo_sum}_tmp" "$geo_sum"
                        else
                            rm -f "${geo_dst}_tmp" "${geo_sum}_tmp"
                            Println "$(eval_gettext "\$error geodata \$geo_file \$geodata_ver 下载或校验出错")"
                        fi
                    done
                else
                    Println "$(eval_gettext "\$error geodata 下载出错, 无法连接 github ?")"
                fi

                if openwrt_aios_assets=$(curl -fsSL -m 30 "https://api.github.com/repos/${OPENWRT_AIOS_LINK#https://github.com/}/releases/latest" | $JQ_FILE -r '.assets[]? | select((.name | test("^aios-(xray|v2ray)[_-].*[_-](x86_64|aarch64_generic|aarch64_cortex-a53)\\.(ipk|apk)$")) or (.name | test("^aios-geodata[_-].*[_-]all\\.(ipk|apk)$"))) | "\(.name)\t\(.browser_download_url)"') && [ -n "$openwrt_aios_assets" ]
                then
                    while IFS=$'\t' read -r asset_name asset_url
                    do
                        if [ -z "$asset_name" ] || [ -z "$asset_url" ]
                        then
                            continue
                        fi

                        if [ ! -e "$FFMPEG_MIRROR_ROOT/$asset_name" ]
                        then
                            Println "$(eval_gettext "\$info 下载 \$asset_name ...")"
                            if curl -fsSL "$asset_url" -o "$FFMPEG_MIRROR_ROOT/${asset_name}_tmp"
                            then
                                mv "$FFMPEG_MIRROR_ROOT/${asset_name}_tmp" "$FFMPEG_MIRROR_ROOT/$asset_name"
                            else
                                rm -f "$FFMPEG_MIRROR_ROOT/${asset_name}_tmp"
                                Println "$(eval_gettext "\$error \$asset_name 下载出错, 无法连接 github ?")"
                            fi
                        fi
                    done <<< "$openwrt_aios_assets"
                else
                    Println "$(eval_gettext "\$error openwrt-aios 下载出错, 无法连接 github ?")"
                fi

                if luci_app_aios_assets=$(curl -fsSL -m 30 "https://api.github.com/repos/${LUCI_APP_AIOS_LINK#https://github.com/}/releases/latest" | $JQ_FILE -r '.assets[]? | select(.name | test("^luci-app-aios[_-].*\\.(ipk|apk)$")) | "\(.name)\t\(.browser_download_url)"') && [ -n "$luci_app_aios_assets" ]
                then
                    while IFS=$'\t' read -r asset_name asset_url
                    do
                        if [ -z "$asset_name" ] || [ -z "$asset_url" ]
                        then
                            continue
                        fi

                        if [ ! -e "$FFMPEG_MIRROR_ROOT/$asset_name" ]
                        then
                            Println "$(eval_gettext "\$info 下载 \$asset_name ...")"
                            if curl -fsSL "$asset_url" -o "$FFMPEG_MIRROR_ROOT/${asset_name}_tmp"
                            then
                                mv "$FFMPEG_MIRROR_ROOT/${asset_name}_tmp" "$FFMPEG_MIRROR_ROOT/$asset_name"
                            else
                                rm -f "$FFMPEG_MIRROR_ROOT/${asset_name}_tmp"
                                Println "$(eval_gettext "\$error \$asset_name 下载出错, 无法连接 github ?")"
                            fi
                        fi
                    done <<< "$luci_app_aios_assets"
                else
                    Println "$(eval_gettext "\$error luci-app-aios 下载出错, 无法连接 github ?")"
                fi

                if dnscrypt_ver=$(curl -s -m 30 "https://api.github.com/repos/DNSCrypt/dnscrypt-proxy/releases/latest" | $JQ_FILE -r '.tag_name')
                then
                    archs=( arm arm64 i386 x86_64 )

                    for arch in "${archs[@]}"
                    do
                        if [ ! -e "$FFMPEG_MIRROR_ROOT/dnscrypt/dnscrypt-proxy-linux_$arch-$dnscrypt_ver.tar.gz" ]
                        then
                            Println "$(eval_gettext "\$info 下载 dnscrypt proxy \$arch ...")"
                            mkdir -p "$FFMPEG_MIRROR_ROOT/dnscrypt/"
                            if curl -s -L "https://github.com/DNSCrypt/dnscrypt-proxy/releases/download/$dnscrypt_ver/dnscrypt-proxy-linux_$arch-$dnscrypt_ver.tar.gz" -o "$FFMPEG_MIRROR_ROOT/dnscrypt/dnscrypt-proxy-linux_$arch-$dnscrypt_ver.tar.gz_tmp"
                            then
                                mv "$FFMPEG_MIRROR_ROOT/dnscrypt/dnscrypt-proxy-linux_$arch-$dnscrypt_ver.tar.gz_tmp" "$FFMPEG_MIRROR_ROOT/dnscrypt/dnscrypt-proxy-linux_$arch-$dnscrypt_ver.tar.gz"
                            else
                                Println "$(eval_gettext "\$error dnscrypt \$arch 下载出错, 无法连接 github ?")"
                            fi
                        fi
                    done
                else
                    Println "$(eval_gettext "\$error dnscrypt 下载出错, 无法连接 github ?")"
                fi

                Println "$(eval_gettext "\$info 下载 nginx-http-flv-module ...")"
                if curl -s -L "https://github.com/winshining/nginx-http-flv-module/archive/master.zip" -o "$FFMPEG_MIRROR_ROOT/nginx-http-flv-module.zip_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/nginx-http-flv-module.zip_tmp" "$FFMPEG_MIRROR_ROOT/nginx-http-flv-module.zip"
                else
                    Println "$(eval_gettext "\$error nginx-http-flv-module 下载出错, 无法连接 github ?")"
                fi

                Println "$(eval_gettext "\$info 下载 imgcat ...")"
                if curl -s -L "https://github.com/eddieantonio/imgcat/archive/master.zip" -o "$FFMPEG_MIRROR_ROOT/imgcat.zip_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/imgcat.zip_tmp" "$FFMPEG_MIRROR_ROOT/imgcat.zip"
                else
                    Println "$(eval_gettext "\$error imgcat 下载出错, 无法连接 github ?")"
                fi

                Println "$(eval_gettext "\$info 下载 CImg ...")"
                if curl -s -L "https://github.com/dtschump/CImg/archive/master.zip" -o "$FFMPEG_MIRROR_ROOT/CImg.zip_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/CImg.zip_tmp" "$FFMPEG_MIRROR_ROOT/CImg.zip"
                else
                    Println "$(eval_gettext "\$error CImg 下载出错, 无法连接 github ?")"
                fi

                if curl -s -L "$JQ_API_LINK" -o "$FFMPEG_MIRROR_ROOT/jq.json_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/jq.json_tmp" "$FFMPEG_MIRROR_ROOT/jq.json"
                else
                    Println "$(eval_gettext "\$error jq.json 下载出错, 无法连接 github ?")"
                fi

                if curl -s -L "https://api.github.com/repos/OpenListTeam/OpenList/releases/latest" -o "$FFMPEG_MIRROR_ROOT/openlist.json_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/openlist.json_tmp" "$FFMPEG_MIRROR_ROOT/openlist.json"
                else
                    Println "$(eval_gettext "\$error openlist.json 下载出错, 无法连接 github ?")"
                fi

                if curl -s -L "https://api.github.com/repos/${OPENWRT_AIOS_LINK#https://github.com/}/releases/latest" -o "$FFMPEG_MIRROR_ROOT/openwrt-aios.json_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/openwrt-aios.json_tmp" "$FFMPEG_MIRROR_ROOT/openwrt-aios.json"
                else
                    Println "$(eval_gettext "\$error openwrt-aios.json 下载出错, 无法连接 github ?")"
                fi

                if curl -s -L "https://api.github.com/repos/${LUCI_APP_AIOS_LINK#https://github.com/}/releases/latest" -o "$FFMPEG_MIRROR_ROOT/luci-app-aios.json_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/luci-app-aios.json_tmp" "$FFMPEG_MIRROR_ROOT/luci-app-aios.json"
                else
                    Println "$(eval_gettext "\$error luci-app-aios.json 下载出错, 无法连接 github ?")"
                fi

                if curl -s -L "https://api.github.com/repos/DNSCrypt/dnscrypt-proxy/releases/latest" -o "$FFMPEG_MIRROR_ROOT/dnscrypt.json_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/dnscrypt.json_tmp" "$FFMPEG_MIRROR_ROOT/dnscrypt.json"
                else
                    Println "$(eval_gettext "\$error dnscrypt.json 下载出错, 无法连接 github ?")"
                fi

                if curl -s -L "https://api.github.com/repos/PCRE2Project/pcre2/releases/latest" -o "$FFMPEG_MIRROR_ROOT/pcre2.json_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/pcre2.json_tmp" "$FFMPEG_MIRROR_ROOT/pcre2.json"
                else
                    Println "$(eval_gettext "\$error pcre2.json 下载出错, 无法连接 github ?")"
                fi

                if curl -s -L "https://raw.githubusercontent.com/junegunn/vim-plug/master/plug.vim" -o "$FFMPEG_MIRROR_ROOT/vim-plug.vim_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/vim-plug.vim_tmp" "$FFMPEG_MIRROR_ROOT/vim-plug.vim"
                else
                    Println "$(eval_gettext "\$error vim-plug.vim 下载出错, 无法连接 github ?")"
                fi

                if [ ! -e "$FFMPEG_MIRROR_ROOT/${OPENRESTY_OPENSSL_PATCH}" ]
                then
                    if curl -s -L "https://raw.githubusercontent.com/openresty/openresty/master/patches/${OPENRESTY_OPENSSL_PATCH}" -o "$FFMPEG_MIRROR_ROOT/${OPENRESTY_OPENSSL_PATCH}_tmp"
                    then
                        mv "$FFMPEG_MIRROR_ROOT/${OPENRESTY_OPENSSL_PATCH}_tmp" "$FFMPEG_MIRROR_ROOT/${OPENRESTY_OPENSSL_PATCH}"
                    else
                        Println "$(eval_gettext "\$error openssl patch 下载出错, 无法连接 github ?")"
                    fi
                fi

                if [ ! -e "$FFMPEG_MIRROR_ROOT/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch" ]
                then
                    if curl -s -L "https://raw.githubusercontent.com/woniuzfb/aios/main/scripts/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch" -o "$FFMPEG_MIRROR_ROOT/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch_tmp"
                    then
                        mv "$FFMPEG_MIRROR_ROOT/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch_tmp" "$FFMPEG_MIRROR_ROOT/Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch"
                    else
                        Println "$(eval_gettext "\$error Add-SVT-HEVC-support-for-RTMP-and-HLS-on-Nginx-HTTP-FLV.patch 下载出错, 无法连接 github ?")"
                    fi
                fi

                if curl -s -L "https://raw.githubusercontent.com/woniuzfb/aios/main/scripts/fix_ngx_lua_resp_get_headers_key_whitespace.patch" -o "$FFMPEG_MIRROR_ROOT/fix_ngx_lua_resp_get_headers_key_whitespace.patch_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/fix_ngx_lua_resp_get_headers_key_whitespace.patch_tmp" "$FFMPEG_MIRROR_ROOT/fix_ngx_lua_resp_get_headers_key_whitespace.patch"
                else
                    Println "$(eval_gettext "\$error fix_ngx_lua_resp_get_headers_key_whitespace.patch 下载出错, 无法连接 github ?")"
                fi

                if [ ! -e "$FFMPEG_MIRROR_ROOT/fontforge-${FONTFORGE_VER}.tar.gz" ]
                then
                    if curl -s -L "https://github.com/fontforge/fontforge/releases/download/${FONTFORGE_VER}/fontforge-${FONTFORGE_VER}.tar.gz" -o "$FFMPEG_MIRROR_ROOT/fontforge-${FONTFORGE_VER}.tar.gz_tmp"
                    then
                        mv "$FFMPEG_MIRROR_ROOT/fontforge-${FONTFORGE_VER}.tar.gz_tmp" "$FFMPEG_MIRROR_ROOT/fontforge-${FONTFORGE_VER}.tar.gz"
                    else
                        Println "$(eval_gettext "\$error fontforge 下载出错, 无法连接 github ?")"
                    fi
                fi

                if [ ! -e "$FFMPEG_MIRROR_ROOT/pdf2htmlEX-${PDF2HTMLEX_VER}.zip" ]
                then
                    Println "$(eval_gettext "\$info 下载 pdf2htmlEX ...")"
                    if curl -s -L "https://github.com/pdf2htmlEX/pdf2htmlEX/archive/v${PDF2HTMLEX_VER}.zip" -o "$FFMPEG_MIRROR_ROOT/pdf2htmlEX-${PDF2HTMLEX_VER}.zip_tmp"
                    then
                        mv "$FFMPEG_MIRROR_ROOT/pdf2htmlEX-${PDF2HTMLEX_VER}.zip_tmp" "$FFMPEG_MIRROR_ROOT/pdf2htmlEX-${PDF2HTMLEX_VER}.zip"
                    else
                        Println "$(eval_gettext "\$error pdf2htmlEX 下载出错, 无法连接 github ?")"
                    fi
                fi

                if [ ! -e "$FFMPEG_MIRROR_ROOT/nbfc.zip" ]
                then
                    Println "$(eval_gettext "\$info 下载 nbfc ...")"
                    if curl -s -L "https://github.com/hirschmann/nbfc/archive/master.zip" -o "$FFMPEG_MIRROR_ROOT/nbfc.zip_tmp"
                    then
                        mv "$FFMPEG_MIRROR_ROOT/nbfc.zip_tmp" "$FFMPEG_MIRROR_ROOT/nbfc.zip"
                    else
                        Println "$(eval_gettext "\$error nbfc 下载出错, 无法连接 github ?")"
                    fi
                fi

                if [ ! -e "$FFMPEG_MIRROR_ROOT/${QUICTLS_TAG}.tar.gz" ]
                then
                    Println "$(eval_gettext "\$info 下载 \${QUICTLS_TAG} ...")"
                    if curl -s -L "${QUICTLS_REPO_LINK}/${QUICTLS_TAG}.tar.gz" -o "$FFMPEG_MIRROR_ROOT/${QUICTLS_TAG}.tar.gz_tmp"
                    then
                        mv "$FFMPEG_MIRROR_ROOT/${QUICTLS_TAG}.tar.gz_tmp" "$FFMPEG_MIRROR_ROOT/${QUICTLS_TAG}.tar.gz"
                    else
                        Println "$(eval_gettext "\$error \${QUICTLS_TAG} 下载出错, 无法连接 github ?")"
                    fi
                fi

                Println "$(eval_gettext "\$info 下载 acme.sh ...")"
                if curl -s -L https://raw.githubusercontent.com/acmesh-official/acme.sh/master/acme.sh -o "$FFMPEG_MIRROR_ROOT/acme.sh_tmp"
                then
                    mv "$FFMPEG_MIRROR_ROOT/acme.sh_tmp" "$FFMPEG_MIRROR_ROOT/acme.sh"
                else
                    Println "$(eval_gettext "\$error acme.sh 下载出错, 无法连接 github ?")"
                fi

                locale_options=( en )
                mkdir -p "$FFMPEG_MIRROR_ROOT/locale/po/"

                for locale in "${locale_options[@]}"
                do
                    Println "$(eval_gettext "\$info 下载 \$locale 语言文件 ...")"
                    if curl -s -L "https://raw.githubusercontent.com/woniuzfb/aios/main/i18n/po/${TEXTDOMAIN}.sh-$locale.mo" -o "$FFMPEG_MIRROR_ROOT/locale/po/${TEXTDOMAIN}.sh-$locale.mo_tmp"
                    then
                        mv "$FFMPEG_MIRROR_ROOT/locale/po/${TEXTDOMAIN}.sh-$locale.mo_tmp" "$FFMPEG_MIRROR_ROOT/locale/po/${TEXTDOMAIN}.sh-$locale.mo"
                    else
                        Println "$(eval_gettext "\$error \${TEXTDOMAIN}.sh-\$locale.mo 下载出错, 无法连接 github ?")"
                    fi
                done

                exit 0
            ;;
            ts)
                TsGetToken()
                {
                    if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: application/json' --data '{"role":"guest","deviceno":"'"$device_no"'","deviceType":"yuj"}' "$access_token_url") 
                    then
                        Println "$(eval_gettext "\$error 无法连接服务器, 请重试")"
                        return 1
                    fi

                    IFS=" " read -r ret access_token refresh_token refresh_time < <($JQ_FILE -r '[.ret,.accessToken,.refreshToken,.refreshTime]|join(" ")' <<< "$res")

                    if [ "$ret" != 0 ] || [ -z "$access_token" ] || [ -z "$refresh_token" ] || [ -z "$refresh_time" ]
                    then
                        echo "$res"
                        Println "$(eval_gettext "\$error 获取 token 错误, 请重试")"
                        return 2
                    fi

                    Println "$(eval_gettext "\$info 请等待 \$refresh_time 秒...")"

                    sleep $refresh_time

                    if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: application/json' --data '{"accessToken":"'"$access_token"'","refreshToken":"'"$refresh_token"'"}' "$refresh_access_token_url") 
                    then
                        Println "$(eval_gettext "\$error 无法连接服务器, 请重试")"
                        return 3
                    fi

                    IFS=" " read -r ret access_token refresh_token refresh_time < <($JQ_FILE -r '[.ret,.accessToken,.refreshToken,.refreshTime]|join(" ")' <<< "$res")

                    if [ "$ret" != 0 ] || [ -z "$access_token" ] || [ -z "$refresh_token" ] || [ -z "$refresh_time" ]
                    then
                        echo "$res"
                        Println "$(eval_gettext "\$error 获取 token 错误, 请重试")"
                        return 4
                    fi

                    now=$(DateEpoch)

                    refresh=$((now+refresh_time))
                }

                TsValidateLogin()
                {
                    if [ "$1" == "$i18n_cancel" ] || [[ $1 =~ ^[0-9]{11}$ ]] || [[ $1 =~ ^[A-Za-z][A-Za-z0-9_]{3,13}$ ]]
                    then
                        return 0
                    fi

                    return 1
                }

                TsValidateUserName()
                {
                    if [ "$1" == "$i18n_cancel" ] || [[ $1 =~ ^[A-Za-z][A-Za-z0-9_]{3,13}$ ]] 
                    then
                        return 0
                    fi

                    return 1
                }

                TsValidatePhoneNumber()
                {
                    if [ "$1" == "$i18n_cancel" ] || [[ $1 =~ ^[0-9]{11}$ ]] 
                    then
                        return 0
                    fi

                    return 1
                }

                TsMenu()
                {
                    [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请检查 !")\n" && exit 1

                    GetDefault
                    ShFallback
                    ts_options=("$SH_FALLBACK/$TS_CHANNELS")

                    if [ -n "$d_sync_file" ] 
                    then
                        ts_options+=($d_sync_file)
                    fi

                    ts_options+=("$(gettext "手动输入")")

                    echo
                    inquirer list_input_index "$(gettext "选择使用的频道文件")" ts_options ts_options_index

                    if [ "$ts_options_index" -eq $((${#ts_options[@]}-1)) ]
                    then
                        echo
                        ExitOnText "$(gettext "请输入使用的频道文件链接或本地路径")" ts_option
                    else
                        ts_option="${ts_options[ts_options_index]}"
                    fi

                    if [[ $ts_option =~ ^https?:// ]] 
                    then
                        if ! ts_source=$(curl -s -Lm 10 "$ts_option") 
                        then
                            Println "$(eval_gettext "\$error 无法连接 \$ts_option")\n"
                            exit 1
                        fi
                    else
                        if [ ! -f "$ts_option" ] 
                        then
                            Println "$(eval_gettext "\$error \$ts_option 不存在")\n"
                            exit 1
                        fi
                        ts_source=$(< "$ts_option")
                    fi

                    SetDelimiters

                    EXIT_STATUS=0

                    ts_source=$($JQ_FILE '{data: ((if type == "array" then .[0].data else .data end) // [] | map(select(.reg_url != null)))}' <<< "$ts_source")
                    jq_payload=$(JQs flat "$ts_source")

                    jq_path='[
                        ["data","id"],
                        ["data","name"],
                        ["data","user_agent"],
                        ["data","verify_type"],
                        ["data","verify_acc_type"],
                        ["data","reg_type"],
                        ["data","server_version"],
                        ["data","unique_url"],
                        ["data","access_token_url"],
                        ["data","refresh_access_token_url"],
                        ["data","third_token_url"],
                        ["data","img_url"],
                        ["data","sms_url"],
                        ["data","verify_url"],
                        ["data","reg_url"],
                        ["data","login_url"],
                        ["data","user_info_url"],
                        ["data","auth_info_url"],
                        ["data","auth_verify_url"],
                        ["data","play_url"],
                        ["data","playback_url"],
                        ["data","list_url"],
                        ["data","schedule_url"],
                        ["data","event_info_url"],
                        ["data","extend_info","operatingsystem"],
                        ["data","extend_info","systemversion"],
                        ["data","extend_info","model"],
                        ["data","extend_info","appversion"]
                    ]'

                    while IFS=": " read -r path_name value; do
                        var_name=${path_name}
                        read -r ${var_name?} <<< "$value"
                    done < <(JQs gets jq_payload)

                    if [ -z "${jq_data_name:-}" ]
                    then
                        Println "$(eval_gettext "\$error 没有找到频道")\n"
                        exit 1
                    fi

                    IFS="${delimiters[2]}" read -ra ts_id <<< "$jq_data_id"
                    IFS="${delimiters[2]}" read -ra ts_name <<< "$jq_data_name"
                    IFS="${delimiters[2]}" read -ra ts_user_agent <<< "$jq_data_user_agent"
                    IFS="${delimiters[2]}" read -ra ts_verify_type <<< "$jq_data_verify_type"
                    IFS="${delimiters[2]}" read -ra ts_verify_acc_type <<< "$jq_data_verify_acc_type"
                    IFS="${delimiters[2]}" read -ra ts_reg_type <<< "$jq_data_reg_type"
                    IFS="${delimiters[2]}" read -ra ts_server_version <<< "$jq_data_server_version"
                    IFS="${delimiters[2]}" read -ra ts_unique_url <<< "$jq_data_unique_url"
                    IFS="${delimiters[2]}" read -ra ts_access_token_url <<< "$jq_data_access_token_url"
                    IFS="${delimiters[2]}" read -ra ts_refresh_access_token_url <<< "$jq_data_refresh_access_token_url"
                    IFS="${delimiters[2]}" read -ra ts_third_token_url <<< "$jq_data_third_token_url"
                    IFS="${delimiters[2]}" read -ra ts_img_url <<< "$jq_data_img_url"
                    IFS="${delimiters[2]}" read -ra ts_sms_url <<< "$jq_data_sms_url"
                    IFS="${delimiters[2]}" read -ra ts_verify_url <<< "$jq_data_verify_url"
                    IFS="${delimiters[2]}" read -ra ts_reg_url <<< "$jq_data_reg_url"
                    IFS="${delimiters[2]}" read -ra ts_login_url <<< "$jq_data_login_url"
                    IFS="${delimiters[2]}" read -ra ts_user_info_url <<< "$jq_data_user_info_url"
                    IFS="${delimiters[2]}" read -ra ts_auth_info_url <<< "$jq_data_auth_info_url"
                    IFS="${delimiters[2]}" read -ra ts_auth_verify_url <<< "$jq_data_auth_verify_url"
                    IFS="${delimiters[2]}" read -ra ts_play_url <<< "$jq_data_play_url"
                    IFS="${delimiters[2]}" read -ra ts_playback_url <<< "$jq_data_playback_url"
                    IFS="${delimiters[2]}" read -ra ts_list_url <<< "$jq_data_list_url"
                    IFS="${delimiters[2]}" read -ra ts_schedule_url <<< "$jq_data_schedule_url"
                    IFS="${delimiters[2]}" read -ra ts_event_info_url <<< "$jq_data_event_info_url"
                    IFS="${delimiters[3]}" read -ra ts_operating_system <<< "$jq_data_extend_info_operatingsystem"
                    IFS="${delimiters[3]}" read -ra ts_system_version <<< "$jq_data_extend_info_systemversion"
                    IFS="${delimiters[3]}" read -ra ts_model <<< "$jq_data_extend_info_model"
                    IFS="${delimiters[3]}" read -ra ts_app_version <<< "$jq_data_extend_info_appversion"

                    cookie_jar_dir=$(mktemp -d "${TMPDIR:-/tmp}/aios-cookie.XXXXXX")
                    trap 'rm -rf "$cookie_jar_dir"' EXIT

                    local menu_key="${sh_locale:-zh_CN}"

                    if [ "${_menu_ts_cache_key:-}" != "$menu_key" ]
                    then
                        _menu_ts_lan_options=( "$(gettext "不选择")" "$(gettext "电信")" "$(gettext "联通")" )
                        _menu_ts_acc_extra_options=( "$(gettext "添加账号")" "$(gettext "注册账号")" )
                        _menu_ts_acc_actions=( "$(gettext "登录")" "$i18n_delete" )
                        _menu_ts_change_options=( "$i18n_add" "$(gettext "替换")" )
                        _menu_ts_select_source=$(gettext "选择直播源")
                        _menu_ts_select_line=$(gettext "选择线路")
                        _menu_ts_select_acc=$(gettext "选择账号")
                        _menu_ts_input_login=$(gettext "输入用户名或手机号")
                        _menu_ts_input_user=$(gettext "输入用户名")
                        _menu_ts_user_rule=$(gettext "用户名以字母开头, 4到14位字母、数字、下划线组成")
                        _menu_ts_input_phone=$(gettext "输入绑定的手机号")
                        _menu_ts_phone_rule=$(gettext "请输入正确的手机号")
                        _menu_ts_input_pic=$(gettext "输入图片验证码")
                        _menu_ts_refresh=$(gettext "刷新")
                        _menu_ts_input_sms=$(gettext "输入短信验证码")
                        _menu_ts_resend=$(gettext "再次发送")
                        _menu_ts_cache_key="$menu_key"
                    fi

                    while true
                    do
                        unset phone_number

                        echo
                        inquirer list_input_index "$_menu_ts_select_source" ts_name ts_index

                        if [ "${ts_id[ts_index]}" == "jxtvnet" ]
                        then
                            lan_options=( "${_menu_ts_lan_options[@]}" )
                            Println "$(eval_gettext "\$tip 部分地区不选择线路可能无法连接")"
                            inquirer list_input_index "$_menu_ts_select_line" lan_options lan_options_index

                            FilterFileLines ".jxtvnet.tv" /etc/hosts

                            if [ "$lan_options_index" -eq 1 ]
                            then
                                echo -e "59.63.205.33 access.jxtvnet.tv\n59.63.205.33 stream.slave.jxtvnet.tv\n59.63.205.33 slave.jxtvnet.tv" >> /etc/hosts
                            elif [ "$lan_options_index" -eq 2 ]
                            then
                                echo -e "58.17.42.129 access.jxtvnet.tv\n58.17.42.129 stream.slave.jxtvnet.tv\n58.17.42.129 slave.jxtvnet.tv" >> /etc/hosts
                            fi
                        fi

                        id="${ts_id[ts_index]}"
                        name="${ts_name[ts_index]}"
                        user_agent="${ts_user_agent[ts_index]:-$USER_AGENT_PHONE}"
                        verify_type="${ts_verify_type[ts_index]}"
                        verify_acc_type="${ts_verify_acc_type[ts_index]}"
                        reg_type="${ts_reg_type[ts_index]}"
                        server_version="${ts_server_version[ts_index]}"
                        unique_url="${ts_unique_url[ts_index]}"
                        access_token_url="${ts_access_token_url[ts_index]}"
                        refresh_access_token_url="${ts_refresh_access_token_url[ts_index]}"
                        third_token_url="${ts_third_token_url[ts_index]}"
                        img_url="${ts_img_url[ts_index]}"
                        sms_url="${ts_sms_url[ts_index]}"
                        verify_url="${ts_verify_url[ts_index]}"
                        reg_url="${ts_reg_url[ts_index]}"
                        login_url="${ts_login_url[ts_index]}"
                        user_info_url="${ts_user_info_url[ts_index]}"
                        auth_info_url="${ts_auth_info_url[ts_index]}"
                        auth_verify_url="${ts_auth_verify_url[ts_index]}"
                        play_url="${ts_play_url[ts_index]}"
                        playback_url="${ts_playback_url[ts_index]}"
                        list_url="${ts_list_url[ts_index]}"
                        schedule_url="${ts_schedule_url[ts_index]}"
                        event_info_url="${ts_event_info_url[ts_index]}"
                        operating_system="${ts_operating_system[ts_index]}"
                        system_version="${ts_system_version[ts_index]}"
                        model="${ts_model[ts_index]}"
                        app_version="${ts_app_version[ts_index]}"

                        ServiceGet "$id"

                        accs_options=()

                        for((ts_accs_index=0;ts_accs_index<ts_accs_count;ts_accs_index++));
                        do
                            if [[ ${ts_accs_user_name[ts_accs_index]} =~ ^[A-Za-z] ]]
                            then
                                accs_options+=("${ts_accs_user_name[ts_accs_index]} ${ts_accs_phone_number[ts_accs_index]}")
                            else
                                accs_options+=("${ts_accs_phone_number[ts_accs_index]}")
                            fi
                        done

                        accs_options+=( "${_menu_ts_acc_extra_options[@]}" )

                        echo
                        inquirer list_input_index "$_menu_ts_select_acc" accs_options accs_options_index

                        if [ "$accs_options_index" -eq "$ts_accs_count" ]
                        then
                            echo
                            ExitOnText "$_menu_ts_input_login" login TsValidateLogin "$_menu_ts_user_rule"

                            if [[ $login =~ ^[0-9]{11}$ ]]
                            then
                                phone_number="$login"
                                user_name="$phone_number"
                            else
                                user_name="$login"
                            fi

                            echo
                            ExitOnText "$i18n_input_password" password

                            device_no=$(GenUuid)
                            str=$(printf '%s' "$device_no" | Md5Hex)
                            str=${str%% *}
                            str=${str:7:1}
                            device_no="$device_no$str"

                            if ! TsGetToken
                            then
                                continue
                            fi

                            if [ -s "$cookie_jar_dir/$id" ]
                            then
                                cookie_jar=( -b "$cookie_jar_dir/$id" )
                            else
                                cookie_jar=()
                            fi
                        elif [ "$accs_options_index" -eq "$((ts_accs_count+1))" ]
                        then
                            while true
                            do
                                if [ -z "$img_url" ]
                                then
                                    echo
                                    ExitOnText "$_menu_ts_input_user" login TsValidateUserName "$_menu_ts_user_rule"

                                    user_name="$login"
                                    reg_acc_type=1

                                    if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' ${cookie_jar[@]+"${cookie_jar[@]}"} "$unique_url?username=$login&accounttype=$reg_acc_type") || [ $($JQ_FILE -r '.ret' <<< "$res") != 0 ]
                                    then
                                        echo "$res"
                                        Println "$(eval_gettext "\$error 账号已经存在, 请登录或重新输入!")"
                                        continue
                                    fi
                                else
                                    echo
                                    ExitOnText "$_menu_ts_input_login" login TsValidateLogin "$_menu_ts_user_rule"

                                    if [ -z "$third_token_url" ]
                                    then
                                        if [ -s "$cookie_jar_dir/$id" ]
                                        then
                                            cookie_jar=( -b "$cookie_jar_dir/$id" )
                                        else
                                            cookie_jar=( -c "$cookie_jar_dir/$id" )
                                        fi
                                    else
                                        cookie_jar=()
                                    fi

                                    if [[ $login =~ ^[0-9]{11}$ ]]
                                    then
                                        phone_number="$login"
                                        user_name="$login"
                                        reg_acc_type=2

                                        if [ -n "$unique_url" ]
                                        then
                                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' ${cookie_jar[@]+"${cookie_jar[@]}"} "$unique_url?username=$login&accounttype=$reg_acc_type") || [ $($JQ_FILE -r '.ret' <<< "$res") != 0 ]
                                            then
                                                echo "$res"
                                                Println "$(eval_gettext "\$error 账号已经存在, 请登录或重新输入!")"
                                                unset phone_number
                                                continue
                                            fi
                                        fi
                                    else
                                        user_name="$login"
                                        reg_acc_type=1

                                        if [ -n "$unique_url" ]
                                        then
                                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' ${cookie_jar[@]+"${cookie_jar[@]}"} "$unique_url?username=$login&accounttype=$reg_acc_type") || [ $($JQ_FILE -r '.ret' <<< "$res") != 0 ]
                                            then
                                                echo "$res"
                                                Println "$(eval_gettext "\$error 账号已经存在, 请登录或重新输入!")"
                                                continue
                                            fi
                                        fi

                                        echo
                                        ExitOnText "$_menu_ts_input_phone" phone_number TsValidatePhoneNumber "$_menu_ts_phone_rule"
                                    fi
                                fi

                                break
                            done

                            echo
                            ExitOnText "$i18n_input_password" password

                            device_no=$(GenUuid)
                            str=$(printf '%s' "$device_no" | Md5Hex)
                            str=${str%% *}
                            str=${str:7:1}
                            device_no="$device_no$str"

                            if ! TsGetToken 
                            then
                                continue
                            fi

                            if [ -z "$img_url" ] 
                            then
                                md5_password=$(printf '%s' "$password" | Md5Hex)
                                md5_password=${md5_password%% *}

                                if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' "$reg_url?username=$user_name&iconid=1&pwd=$md5_password&birthday=1970-1-1&type=$reg_type&accounttype=$reg_acc_type") || [ $($JQ_FILE -r '.ret' <<< "$res") != 0 ]
                                then
                                    echo "$res"
                                    Println "$(eval_gettext "\$error 注册失败, 请重试")"
                                    continue
                                fi

                                Println "$(eval_gettext "\$info 注册成功, 请稍等...")"
                                sleep 3
                            else
                                if [ ! -e "$IMGCAT_FILE" ] 
                                then
                                    ImgcatInstall
                                fi

                                while true 
                                do
                                    if [ -n "$third_token_url" ] 
                                    then
                                        if [ -s "$cookie_jar_dir/$id" ] 
                                        then
                                            cookie_jar=( -b "$cookie_jar_dir/$id" )
                                        else
                                            cookie_jar=( -c "$cookie_jar_dir/$id" )
                                        fi

                                        if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: application/json' ${cookie_jar[@]+"${cookie_jar[@]}"} --data '{"usagescen":1}' "$third_token_url") 
                                        then
                                            Println "$(eval_gettext "\$error 获取 token 错误, 请重试")"
                                            continue 2
                                        fi

                                        IFS=" " read -r ret third_token < <($JQ_FILE -r '[.ret,.access_token]|join(" ")' <<< "$res")
                                    else
                                        if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: application/json' --data '{"role":"guest","deviceno":"'"$device_no"'","deviceType":"yuj"}' "$access_token_url") 
                                        then
                                            Println "$(eval_gettext "\$error 获取 token 错误, 请重试")"
                                            continue 2
                                        fi

                                        IFS=" " read -r ret third_token < <($JQ_FILE -r '[.ret,.accessToken]|join(" ")' <<< "$res")
                                    fi

                                    if [ "$ret" != 0 ] || [ -z "$third_token" ]
                                    then
                                        echo "$res"
                                        Println "$(eval_gettext "\$error 获取 token 错误, 请重试")"
                                        continue 2
                                    fi

                                    if [ ! -s "$cookie_jar_dir/$id" ] 
                                    then
                                        cookie_jar=()
                                    fi

                                    if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' ${cookie_jar[@]+"${cookie_jar[@]}"} "$img_url?accesstoken=$third_token") 
                                    then
                                        Println "$(eval_gettext "\$error 无法获取图形验证码, 请重试")"
                                        continue 2
                                    fi

                                    IFS=" " read -r ret picid image < <($JQ_FILE -r '[.ret,.picid,.image]|join(" ")' <<< "$res")

                                    if [ "$ret" != 0 ] || [ -z "$picid" ] || [ -z "$image" ]
                                    then
                                        echo "$res"
                                        Println "$(eval_gettext "\$error 无法获取图形验证码, 请重试")"
                                        continue 2
                                    fi

                                    if TMP_FILE=$(mktemp -q) 
                                    then
                                        chmod +r "$TMP_FILE"
                                    else
                                        TMP_FILE=$(date '+%m-%d-%H:%M:%S')
                                    fi

                                    trap '
                                        rm -f "$TMP_FILE"
                                        rm -rf "$cookie_jar_dir"
                                    ' EXIT

                                    base64 -d <<< "${image#*,}" > "$TMP_FILE"

                                    "$IMGCAT_FILE" --half-height "$TMP_FILE"

                                    rm -f "$TMP_FILE"

                                    trap 'rm -rf "$cookie_jar_dir"' EXIT

                                    echo
                                    inquirer text_input "$_menu_ts_input_pic" pincode "$_menu_ts_refresh"

                                    if [ "$pincode" != "$_menu_ts_refresh" ]
                                    then
                                        while true
                                        do
                                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' ${cookie_jar[@]+"${cookie_jar[@]}"} "$sms_url?pincode=$pincode&picid=$picid&verifytype=$verify_type&account=$phone_number&accounttype=$verify_acc_type") || [ $($JQ_FILE -r '.ret' <<< "$res") != 0 ]
                                            then
                                                echo "$res"
                                                Println "$(eval_gettext "\$error 无法获取短信验证码, 请重试")"
                                                continue 2
                                            fi

                                            now=$(DateEpoch)
                                            next=$((now+120))

                                            echo
                                            inquirer text_input "$_menu_ts_input_sms" smscode "$_menu_ts_resend"

                                            if [ "$smscode" == "$_menu_ts_resend" ]
                                            then
                                                now=$(DateEpoch)
                                                if [ "$now" -lt "$next" ]
                                                then
                                                    for((secs=next-now;secs>0;secs--));
                                                    do
                                                        echo -en "\r$(eval_gettext "\$secs 秒后重试")"
                                                        sleep 1
                                                    done
                                                fi
                                                continue 2
                                            fi

                                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' ${cookie_jar[@]+"${cookie_jar[@]}"} "$verify_url?verifycode=$smscode&verifytype=$verify_type&username=$user_name&account=$phone_number")
                                            then
                                                Println "$(eval_gettext "\$error 无法连接服务器, 请重试")"
                                                continue 3
                                            fi

                                            IFS=" " read -r ret code < <($JQ_FILE -r '[.ret,.code]|join(" ")' <<< "$res")

                                            if [ "$ret" != 0 ] || [ -z "$code" ]
                                            then
                                                echo "$res"
                                                Println "$(eval_gettext "\$error 短信验证码错误, 请重试")"
                                                continue 2
                                            fi

                                            md5_password=$(printf '%s' "$password" | Md5Hex)
                                            md5_password=${md5_password%% *}
                                            timestamp=$(DateEpoch)
                                            timestamp=$((timestamp * 1000))
                                            signature="$login|$md5_password|$device_no|yuj|$timestamp"
                                            signature=$(printf '%s' "$signature" | Md5Hex)
                                            signature=${signature%% *}

                                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: application/json' ${cookie_jar[@]+"${cookie_jar[@]}"} --data '{"account":"'"$phone_number"'","deviceno":"'"$device_no"'","devicetype":"yuj","code":"'"$code"'","signature":"'"$signature"'","birthday":"1970-1-1","username":"'"$user_name"'","type":'"$reg_type"',"timestamp":"'"$timestamp"'","pwd":"'"$md5_password"'","accounttype":'"$reg_acc_type"'}' "$reg_url") || [ $($JQ_FILE -r '.ret' <<< "$res") != 0 ]
                                            then
                                                echo "$res"
                                                Println "$(eval_gettext "\$error 注册失败, 请重试")"
                                                continue 3
                                            fi

                                            Println "$(eval_gettext "\$info 注册成功, 请稍等...")"
                                            sleep 3
                                            break 2
                                        done
                                    fi
                                done
                            fi
                        else
                            echo
                            acc_options=( "${_menu_ts_acc_actions[@]}" )
                            inquirer list_input_index "$i18n_select_action" acc_options acc_options_index

                            if [ "$acc_options_index" -eq 1 ] 
                            then
                                jq_path='["'"$id"'","accounts",'"$accs_options_index"']'
                                JQ delete "$SERVICES_CONFIG"
                                Println "$(eval_gettext "\$info 账号删除成功")"
                                continue
                            fi

                            user_name="${ts_accs_user_name[accs_options_index]}"
                            phone_number="${ts_accs_phone_number[accs_options_index]}"
                            password="${ts_accs_password[accs_options_index]}"
                            access_token="${ts_accs_access_token[accs_options_index]}"
                            device_no="${ts_accs_device_no[accs_options_index]}"
                            device_id="${ts_accs_device_id[accs_options_index]}"
                            refresh="${ts_accs_refresh[accs_options_index]}"

                            if [ -n "$refresh" ] 
                            then
                                now=$(DateEpoch)

                                if [ "$now" -lt "$refresh" ] 
                                then
                                    break
                                fi
                            fi

                            if [ -z "$device_no" ] 
                            then
                                device_no=$(GenUuid)
                                str=$(printf '%s' "$device_no" | Md5Hex)
                                str=${str%% *}
                                str=${str:7:1}
                                device_no="$device_no$str"
                            fi

                            if ! TsGetToken 
                            then
                                continue
                            fi

                            if [ -s "$cookie_jar_dir/$id" ] 
                            then
                                cookie_jar=( -b "$cookie_jar_dir/$id" )
                            else
                                cookie_jar=()
                            fi
                        fi

                        md5_password=$(printf '%s' "$password" | Md5Hex)
                        md5_password=${md5_password%% *}

                        if [ -z "$img_url" ] 
                        then
                            login_acc_type=2
                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' ${cookie_jar[@]+"${cookie_jar[@]}"} "$login_url?deviceno=$device_no&devicetype=3&accounttype=$login_acc_type&accesstoken=(null)&account=$user_name&pwd=$md5_password&isforce=1&businessplatform=1")
                            then
                                Println "$(eval_gettext "\$error 无法登录直播源, 请重试")"
                                continue
                            fi
                        else
                            timestamp=$(DateEpoch)
                            timestamp=$((timestamp * 1000))

                            if [[ $user_name =~ ^[A-Za-z][A-Za-z0-9_]{3,13}$ ]] 
                            then
                                login_acc_type=2
                                login="$user_name"
                            else
                                login_acc_type=3
                                login="$phone_number"
                            fi

                            signature="$device_no|yuj|$login_acc_type|$login|$timestamp"
                            signature=$(printf '%s' "$signature" | Md5Hex)
                            signature=${signature%% *}

                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: application/json' ${cookie_jar[@]+"${cookie_jar[@]}"} --data '{"account":"'"$login"'","deviceno":"'"$device_no"'","pwd":"'"$md5_password"'","devicetype":"yuj","businessplatform":1,"signature":"'"$signature"'","isforce":1,"extendinfo":{"operatingsystem":"'"$operating_system"'","systemversion":"'"$system_version"'","model":"'"$model"'","appversion":"'"$app_version"'"},"serverVersion":"'"$server_version"'","timestamp":"'"$timestamp"'","accounttype":'"$login_acc_type"'}' "$login_url")
                            then
                                Println "$(eval_gettext "\$error 无法登录直播源, 请重试")"
                                continue
                            fi
                        fi

                        IFS=" " read -r ret access_token device_id user_name < <($JQ_FILE -r '[.ret,.access_token,.device_id,.user_name]|join(" ")' <<< "$res")

                        if [ "$ret" != 0 ] || [ -z "$access_token" ] || [ -z "$device_id" ] || [ -z "$user_name" ]
                        then
                            echo "$res"
                            Println "$(eval_gettext "\$error 登录错误, 请重试")"
                            continue
                        fi

                        if [ "$accs_options_index" -lt "$ts_accs_count" ] 
                        then
                            update=$(
                            $JQ_FILE -n --arg access_token "$access_token" --arg device_no "$device_no" \
                                --arg device_id "$device_id" --arg refresh "$refresh" \
                                '{
                                    access_token: $access_token,
                                    device_no: $device_no,
                                    device_id: $device_id | tonumber,
                                    refresh: $refresh | tonumber
                                }'
                            )

                            jq_merge=true
                            jq_path='["'"$id"'","accounts",'"$accs_options_index"']'
                            JQ update "$SERVICES_CONFIG" "$update"
                        else
                            if [ -n "$img_url" ] 
                            then
                                if [ -z "${phone_number:-}" ] 
                                then
                                    if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' ${cookie_jar[@]+"${cookie_jar[@]}"} "$user_info_url?accesstoken=$access_token")
                                    then
                                        Println "$(eval_gettext "\$error 无法获取用户信息, 请重试")"
                                        continue
                                    fi

                                    IFS=" " read -r phone_number < <($JQ_FILE -r '.telephone' <<< "$res")

                                    if [ -z "$phone_number" ] 
                                    then
                                        Println "$(eval_gettext "\$error 无法获取用户手机号, 请重新注册")"
                                        continue
                                    fi
                                fi

                                new_acc=$(
                                $JQ_FILE -n --arg user_name "$user_name" --arg phone_number "$phone_number" \
                                    --arg password "$password" --arg access_token "$access_token" \
                                    --arg device_no "$device_no" --arg device_id "$device_id" \
                                    --arg refresh "$refresh" \
                                    '{
                                        user_name: $user_name,
                                        phone_number: $phone_number | tonumber,
                                        password: $password,
                                        access_token: $access_token,
                                        device_no: $device_no,
                                        device_id: $device_id | tonumber,
                                        refresh: $refresh | tonumber
                                    }'
                                )
                            else
                                new_acc=$(
                                $JQ_FILE -n --arg user_name "$user_name" --arg password "$password" \
                                    --arg access_token "$access_token" --arg device_no "$device_no" \
                                    --arg device_id "$device_id" --arg refresh "$refresh" \
                                    '{
                                        user_name: $user_name,
                                        password: $password,
                                        access_token: $access_token,
                                        device_no: $device_no,
                                        device_id: $device_id | tonumber,
                                        refresh: $refresh | tonumber
                                    }'
                                )
                            fi

                            if [[ $($JQ_FILE --argjson path '["'"$id"'","accounts"]' --arg user_name "$user_name" 'getpath($path) // []|map(select(.user_name==$user_name))' "$SERVICES_CONFIG") != "[]" ]] 
                            then
                                jq_merge=true
                                jq_map_string=true
                                jq_path='["'"$id"'","accounts"]'
                                JQ update "$SERVICES_CONFIG" user_name "$user_name" "$new_acc"
                            else
                                jq_path='["'"$id"'","accounts"]'
                                JQ add "$SERVICES_CONFIG" "[$new_acc]"
                            fi
                        fi

                        break
                    done

                    Println "$(eval_gettext "\$info 获取频道...")"

                    if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' "$list_url?pageidx=1&pagenum=500&accesstoken=$access_token") 
                    then
                        echo "$res"
                        Println "$(eval_gettext "\$error 无法获取频道")\n"
                        exit 1
                    fi

                    IFS=" " read -r ret total < <($JQ_FILE -r '[.ret,.total]|join(" ")' <<< "$res")

                    if [ "$ret" != 0 ] 
                    then
                        echo "$res"
                        Println "$(eval_gettext "\$error 无法获取频道")\n"
                        exit 1
                    elif [ "$total" -eq 0 ] 
                    then
                        echo "$res"
                        Println "$(eval_gettext "\$error 没有频道")\n"
                        exit 1
                    fi

                    EXIT_STATUS=0

                    jq_payload=$(JQs flat "$res")

                    jq_path='[
                        ["chnl_list","chnl_id"],
                        ["chnl_list","str_chnl_id"],
                        ["chnl_list","chnl_name"],
                        ["chnl_list","chnl_type"],
                        ["chnl_list","chnl_num"],
                        ["chnl_list","logic_num"],
                        ["chnl_list","definition"],
                        ["chnl_list","is_favorite"],
                        ["chnl_list","is_free"],
                        ["chnl_list","is_hide"],
                        ["chnl_list","is_livetv"],
                        ["chnl_list","is_tstv"],
                        ["chnl_list","is_lock"],
                        ["chnl_list","is_purchased"],
                        ["chnl_list","is_public"],
                        ["chnl_list","is_boot"],
                        ["chnl_list","is_fast_channel_change"],
                        ["chnl_list","stream_type"],
                        ["chnl_list","times"],
                        ["chnl_list","comment_num"],
                        ["chnl_list","score"],
                        ["chnl_list","praise_num"],
                        ["chnl_list","degrade_num"],
                        ["chnl_list","score_num"],
                        ["chnl_list","iframe_url"],
                        ["chnl_list","device_type"],
                        ["chnl_list","providerid"],
                        ["chnl_list","provider_icon_font"],
                        ["chnl_list","ts_id"],
                        ["chnl_list","content_type"],
                        ["chnl_list","sub_type"],
                        ["chnl_list","subtype_name"],
                        ["chnl_list","label_name"],
                        ["chnl_list","support_playback"],
                        ["chnl_list","rate_list"],
                        ["chnl_list","tstv_url"],
                        ["chnl_list","livetv_url"],
                        ["chnl_list","video_code"],
                        ["chnl_list","trial_short"],
                        ["chnl_list","trial_longest"],
                        ["chnl_list","trial_times"],
                        ["chnl_list","play_type"],
                        ["chnl_list","codec_info"],
                        ["chnl_list","logo_info"]
                    ]'

                    while IFS=": " read -r path_name value; do
                        var_name=${path_name}
                        read -r ${var_name?} <<< "$value"
                    done < <(JQs gets jq_payload)

                    IFS="${delimiters[2]}" read -ra chnl_id <<< "$jq_chnl_list_chnl_id"
                    IFS="${delimiters[2]}" read -ra chnl_name <<< "$jq_chnl_list_chnl_name"
                    IFS="${delimiters[2]}" read -ra rate_list <<< "$jq_chnl_list_rate_list"
                    IFS="${delimiters[2]}" read -ra livetv_url <<< "$jq_chnl_list_livetv_url"

                    echo
                    inquirer checkbox_input_indices "$(gettext "选择添加的频道")" chnl_name chnl_indices

                    FFmpegInstall

                    headers=""
                    cookies=""

                    local lbl_select_chnl lbl_res lbl_proto lbl_cant_verify lbl_cant_connect lbl_add_chnl lbl_add_replace_src lbl_select_replace_src lbl_push_flv
                    lbl_select_chnl=$(gettext "选择频道")
                    lbl_res=$(gettext "分辨率")
                    lbl_proto=$(gettext "协议")
                    lbl_cant_verify=$(gettext "无法验证")
                    lbl_cant_connect=$(gettext "无法连接")
                    lbl_add_chnl=$(gettext "添加频道")
                    lbl_add_replace_src=$(gettext "是否 添加/替换 现有频道直播源")
                    lbl_select_replace_src=$(gettext "选择替换的直播源")
                    lbl_push_flv=$(gettext "是否推流 flv")

                    for chnl_index in "${chnl_indices[@]}"
                    do
                        IFS="${delimiters[3]}" read -ra rates <<< "${rate_list[chnl_index]}"

                        echo
                        inquirer list_input "$lbl_select_chnl ${chnl_name[chnl_index]} $lbl_res" rates rate

                        chnl_play_url="$play_url"

                        if [ -z "$chnl_play_url" ]
                        then
                            IFS="${delimiters[3]}" read -ra play_urls <<< "${livetv_url[chnl_index]}"

                            echo
                            inquirer list_input "$lbl_select_chnl ${chnl_name[chnl_index]} $i18n_address" play_urls chnl_play_url
                        fi

                        echo
                        protocol_options=( http hls )
                        inquirer list_input "$lbl_select_chnl ${chnl_name[chnl_index]} $lbl_proto" protocol_options protocol

                        if [ -z "$auth_info_url" ]
                        then
                            stream_link="$chnl_play_url?protocol=$protocol&accesstoken=$access_token&programid=${chnl_id[chnl_index]}&playtoken=ABCDEFGH&verifycode=$device_id&rate=$rate&playtype=live"
                        else
                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' "$auth_info_url?accesstoken=$access_token&programid=${chnl_id[chnl_index]}&playtype=live&protocol=$protocol&verifycode=$device_id")
                            then
                                Println "$error $lbl_cant_verify ${chnl_name[chnl_index]}"
                                continue
                            fi

                            IFS=" " read -r ret auth_random_sn play_token < <($JQ_FILE -r '[.ret,.auth_random_sn,.play_token]|join(" ")' <<< "$res")

                            if [ "$ret" != 0 ] || [ -z "$auth_random_sn" ] || [ -z "$play_token" ]
                            then
                                echo "$res"
                                Println "$error $lbl_cant_verify ${chnl_name[chnl_index]}"
                                continue
                            fi

                            authtoken="ipanel123#%#&*(&(*#*&^*@#&*%()#*()$)#@&%(*@#()*%321ipanel$auth_random_sn"
                            authtoken=$(printf '%s' "$authtoken" | Md5Hex)
                            authtoken=${authtoken%% *}

                            if ! res=$(curl -s -Lm 10 -H "User-Agent: $user_agent" -H 'Content-Type: ' "$auth_verify_url?programid=${chnl_id[chnl_index]}&playtype=live&protocol=$protocol&accesstoken=$access_token&verifycode=$device_id&authtoken=$authtoken") || [ $($JQ_FILE -r '.ret' <<< "$res") != 0 ]
                            then
                                Println "$error $lbl_cant_verify ${chnl_name[chnl_index]}"
                                continue
                            fi

                            stream_link="$chnl_play_url?protocol=$protocol&accesstoken=$access_token&programid=${chnl_id[chnl_index]}&playtoken=$play_token&verifycode=$device_id&rate=$rate&playtype=live"
                        fi

                        stream_link_parsed=true
                        stream_links=("$stream_link")

                        if ! ParseStream
                        then
                            Println "$error $lbl_cant_connect ${chnl_name[chnl_index]}"
                            continue
                        fi

                        echo
                        inquirer list_input_index "$lbl_add_chnl ${chnl_name[chnl_index]}" yn_options yn_index

                        if [ "$yn_index" -eq 0 ]
                        then
                            stream_links=("$stream_link|$id|$user_name")

                            echo
                            inquirer list_input_index "$lbl_add_replace_src" ny_options ny_index

                            if [ "$ny_index" -eq 1 ]
                            then
                                ListChannels
                                InputChannelsIndex

                                for((i=0;i<${#chnls_pid_chosen[@]};i++));
                                do
                                    chnl_pid=${chnls_pid_chosen[i]}
                                    chnls_index=${chnls_indices[i]}

                                    ListChannel

                                    echo
                                    change_options=( "${_menu_ts_change_options[@]}" )
                                    inquirer list_input_index "$(eval_gettext "如何修改频道 [ \$chnl_channel_name ]")" change_options change_options_index

                                    if [ "$change_options_index" -eq 0 ]
                                    then
                                        jq_pre=true
                                        jq_path='["channels",'"$chnls_index"',"stream_link"]'
                                        JQ add "$CHANNELS_FILE" ["\"${stream_links[0]}\""]
                                    else
                                        echo
                                        inquirer list_input_index "$lbl_select_replace_src" chnl_stream_links chnl_stream_links_index

                                        jq_path='["channels",'"$chnls_index"',"stream_link",'"$chnl_stream_links_index"']'
                                        JQ update "$CHANNELS_FILE" "${stream_links[0]}"
                                    fi

                                    Println "$(eval_gettext "\$info 频道 [ \$chnl_channel_name ] 修改成功 !")\n"
                                done
                            else
                                echo
                                inquirer list_input_index "$lbl_push_flv" ny_options ny_index

                                if [ "$ny_index" -eq 1 ]
                                then
                                    kind="flv"
                                else
                                    kind=""
                                fi

                                AddChannel
                            fi
                        fi
                    done

                    exit 0
                }
                TsMenu "$@"
            ;;
            f|flv) 
                [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请检查 !")\n" && exit 1
                kind="flv"
                color="$blue"
                shift
            ;;
            v|vip) 
                [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请检查 !")\n" && exit 1
                vip=true
                shift
            ;;
            l|ll) 
                shift

                GetChannels

                if [ "$chnls_count" -gt 0 ] 
                then
                    hls_indices=()
                    hls_stream_links_list=()
                    flv_list=""
                    hls_list=""

                    indices=()

                    if [ -n "${1:-}" ] 
                    then
                        for num in "${@}"
                        do
                            indices+=("$((num-1))")
                        done
                    else
                        indices=("${!chnls_pid[@]}")
                    fi

                    for i in "${indices[@]}"
                    do
                        if [ "${chnls_flv_status[i]:-}" == "on" ]
                        then
                            IFS="${delimiters[3]}" read -ra chnl_stream_links <<< "${chnls_stream_links[i]:-}"

                            chnl_stream_links_list=""

                            for((j=0;j<${#chnl_stream_links[@]};j++));
                            do
                                chnl_stream_links_list="$chnl_stream_links_list${indent_6}$(gettext "源")$((j+1)): ${chnl_stream_links[j]}\n"
                            done

                            flv_list="$flv_list  ${green}$((i+1)).${normal}${indent_6}${chnls_channel_name[i]}\n\n$chnl_stream_links_list\n${indent_6}$(gettext "拉"): ${chnls_flv_pull_link[i]:-$i18n_none}\n\n"
                        elif [ "${chnls_status[i]:-}" == "on" ]
                        then
                            IFS="${delimiters[3]}" read -ra chnl_stream_links <<< "${chnls_stream_links[i]:-}"

                            chnl_stream_links_list=""

                            for((j=0;j<${#chnl_stream_links[@]};j++));
                            do
                                chnl_stream_links_list="$chnl_stream_links_list${indent_6}$(gettext "源")$((j+1)): ${chnl_stream_links[j]}\n"
                            done

                            hls_indices+=("$i")
                            hls_stream_links_list+=("$chnl_stream_links_list")

                            hls_list="$hls_list  ${green}$((i+1)).${normal}${indent_6}${chnls_channel_name[i]}\n\n$chnl_stream_links_list\n\n"
                        fi
                    done
                fi

                echo

                if [ -n "${hls_indices:-}" ] 
                then
                    for((i=0;i<${#hls_indices[@]};i++));
                    do
                        hls_index=${hls_indices[i]}
                        echo -e "  ${green}$((i+1)).${normal}${indent_6}${chnls_channel_name[hls_index]}\n\n${hls_stream_links_list[i]}"
                        if [ -d "$LIVE_ROOT/${chnls_output_dir_name[hls_index]}" ] 
                        then
                            if ls -A "$LIVE_ROOT/${chnls_output_dir_name[hls_index]}"/* > /dev/null 2>&1
                            then
                                ls -lght "$LIVE_ROOT/${chnls_output_dir_name[hls_index]}"/* && echo
                            else
                                Println "$(eval_gettext "\$error 无")\n"
                            fi
                        else
                            Println "$(eval_gettext "\$error 目录不存在")\n"
                        fi
                    done
                fi

                if [ -n "${flv_list:-}" ] 
                then
                    Println "${green}$(gettext "FLV 频道")${normal}\n\n$flv_list"
                fi

                if [ -n "${hls_list:-}" ] 
                then
                    Println "${green}$(gettext "HLS 频道")${normal}\n\n$hls_list"
                fi

                if [ -z "${1:-}" ] && ls -A $LIVE_ROOT/* > /dev/null 2>&1 
                then
                    for output_dir_root in "$LIVE_ROOT"/*
                    do
                        output_dir_name=${output_dir_root#*$LIVE_ROOT/}

                        if [ -n "${hls_indices:-}" ] 
                        then
                            for hls_index in "${hls_indices[@]}"
                            do
                                if [ "$output_dir_name" == "${chnls_output_dir_name[hls_index]}" ] 
                                then
                                    continue 2
                                fi
                            done
                        fi

                        Println "$(eval_gettext "\$error 未知目录 \$output_dir_name")\n"

                        if ls -A "$output_dir_root"/* > /dev/null 2>&1
                        then
                            ls -lght "$output_dir_root"/*
                        fi
                    done
                fi

                if [ -z "${flv_list:-}" ] && [ -z "${hls_list:-}" ]
                then
                    Println "$(eval_gettext "\$error 没有开启的频道 !")\n"
                    exit 1
                fi

                exit 0
            ;;
            debug)
                if [[ ${2:-1} == "1" ]]
                then
                    flag=true
                else
                    flag=false
                fi

                debug_tmp=$(mktemp "${TMPDIR:-/tmp}/aios-dbg.XXXXXX")
                if awk -v f="$flag" '!done && sub(/sh_debug=.*/, "sh_debug=" f) { done=1 } 1' "$SH_FILE" > "$debug_tmp" && [ -s "$debug_tmp" ]
                then
                    cat "$debug_tmp" > "$SH_FILE"
                fi
                rm -f "$debug_tmp"

                exit 0
            ;;
            ed|editor)
                [ ! -d "$IPTV_ROOT" ] && Println "$(eval_gettext "\$error 尚未安装, 请检查 !")\n" && exit 1
                RunEditor "$IPTV_CONFIG" && exit 0
            ;;
            a)
                if [[ ! -x $(command -v readlink) ]] 
                then
                    Println "$(eval_gettext "\$error 系统不支持 readlink")\n"
                    exit 1
                fi
                echo
                ExitOnText "$(gettext "输入自定义命令名称")" name

                if command -v "$name" > /dev/null
                then
                    Println "$(eval_gettext "\$error 命令已经存在")\n"
                    exit 1
                fi
                echo
                alternative_options=( nginx openresty xray v2ray armbian "proxmox ve" 
                "ibm cloud foundry" "cloudflare partner,workers" ffmpeg )
                inquirer list_input_index "$(gettext "选择执行的脚本")" alternative_options alternative_options_index
                commands=( NX_FILE OR_FILE X_FILE V2_FILE ARM_FILE PVE_FILE IBM_FILE CF_FILE SH_FILE )
                ln -s "${!commands[alternative_options_index]}" "$AIOS_PREFIX/bin/$name"
                Println "$(eval_gettext "\$info 自定义命令 \$name 添加成功")\n"
                exit 0
            ;;
            c)
                to_locale=${2:-}
                new_locale=""

                if [ -n "$to_locale" ] 
                then
                    new_locale=${to_locale%.*}

                    if [[ $new_locale =~ ^(.+)[-|_](.+)$ ]] 
                    then
                        new_locale=$(tr '[:upper:]' '[:lower:]' <<< "${BASH_REMATCH[1]}")_$(tr '[:lower:]' '[:upper:]' <<< "${BASH_REMATCH[2]}")
                    else
                        new_locale=$(tr '[:upper:]' '[:lower:]' <<< "$new_locale")
                    fi

                    if [[ $to_locale =~ \. ]] 
                    then
                        new_locale="$new_locale.${to_locale#*.}"
                    fi
                fi

                if [ -n "${3:-}" ] 
                then
                    locale_fix=1
                fi

                i18nInstall "$new_locale"

                i18nCheck

                exit 0
            ;;
            color)
                ColorMenu()
                {
                    echo
                    color_options=( "$(gettext "设置颜色")" "$(gettext "恢复默认")" )
                    inquirer list_input_index "$i18n_select_action" color_options color_options_index

                    if [ "$color_options_index" -eq 1 ]
                    then
                        FilterFileLines "bg_black=" "$i18n_FILE"
                        FilterFileLines "red=" "$i18n_FILE"
                        FilterFileLines "green=" "$i18n_FILE"
                        FilterFileLines "yellow=" "$i18n_FILE"
                        FilterFileLines "blue=" "$i18n_FILE"
                        FilterFileLines "cyan=" "$i18n_FILE"
                        FilterFileLines "white=" "$i18n_FILE"
                        Println "$(eval_gettext "\$info 颜色重置成功")\n"
                        exit 0
                    fi

                    echo
                    color_options=( "${red}$(gettext "默认红色文字")${normal}" "${green}$(gettext "默认绿色文字")${normal}" "${yellow}$(gettext "默认黄色文字")${normal}"
                        "${blue}$(gettext "默认蓝色文字")${normal}" "${cyan}$(gettext "默认青色文字")${normal}" "${white}$(gettext "默认白色文字")${normal}" "$(gettext "默认黑色背景")" )
                    inquirer list_input_index "$i18n_select_edit" color_options color_options_index

                    echo
                    inquirer color_pick "$(gettext "设置") ${color_options[color_options_index]}" color_pick

                    if [ "$color_options_index" -eq 0 ]
                    then
                        FilterFileLines "red=" "$i18n_FILE"
                        printf "red='%s'\n" "$color_pick" >> "$i18n_FILE"
                    elif [ "$color_options_index" -eq 1 ]
                    then
                        FilterFileLines "green=" "$i18n_FILE"
                        printf "green='%s'\n" "$color_pick" >> "$i18n_FILE"
                    elif [ "$color_options_index" -eq 2 ]
                    then
                        FilterFileLines "yellow=" "$i18n_FILE"
                        printf "yellow='%s'\n" "$color_pick" >> "$i18n_FILE"
                    elif [ "$color_options_index" -eq 3 ]
                    then
                        FilterFileLines "blue=" "$i18n_FILE"
                        printf "blue='%s'\n" "$color_pick" >> "$i18n_FILE"
                    elif [ "$color_options_index" -eq 4 ]
                    then
                        FilterFileLines "cyan=" "$i18n_FILE"
                        printf "cyan='%s'\n" "$color_pick" >> "$i18n_FILE"
                    elif [ "$color_options_index" -eq 5 ]
                    then
                        FilterFileLines "white=" "$i18n_FILE"
                        printf "white='%s'\n" "$color_pick" >> "$i18n_FILE"
                    else
                        FilterFileLines "bg_black=" "$i18n_FILE"
                        printf "bg_black='%s'\n" "$color_pick" >> "$i18n_FILE"
                    fi

                    Println "$(eval_gettext "\$info 颜色设置成功")\n"

                    exit 0
                }
                ColorMenu "$@"
            ;;
            curl)


                echo
                curl_options=( "$(gettext "安装/设置 curl impersonate")" "$(gettext "编译 curl impersonate")" "$(gettext "编译 node-libcurl (使用 curl impersonate)")" )
                inquirer list_input_index "$i18n_select_action" curl_options curl_options_index

                if [ "$curl_options_index" -eq 0 ] 
                then
                    CurlImpersonateUpdate

                    echo
                elif [ "$curl_options_index" -eq 1 ] 
                then
                    CurlImpersonateCompile
                else
                    NodeLibcurlImpersonateCompile
                fi

                exit 0
            ;;
            b|backup)
                # --exclude=exclude_before --include=src/ --include=src/xxx/*** --exclude=src/*** --exclude=exclude_after

                IPTV_ROOT="${IPTV_ROOT%/}"
                FFMPEG_MIRROR_ROOT="${FFMPEG_MIRROR_ROOT%/}"
                LIVE_ROOT="${LIVE_ROOT%/}"
                NODE_ROOT="${NODE_ROOT%/}"

                iptv_source="$IPTV_ROOT"

                iptv_excludes_before=(
                    /c/
                    /ffmpeg-git-'*'
                    /vip/
                    node_modules/
                )

                ffmpeg_excludes_before=(
                    /Amlogic_s905-kernel-master.zip
                    /builds/
                    /calibre/
                    /dnscrypt/
                    /ffmpeg_c
                    /fontforge-20190413.tar.gz
                    /imgcat.zip
                    /jq-'*'
                    /releases/
                    /v2ray/
                    /xray/
                    '*'.ipk
                    '*'.err
                    '*'.log
                    '*'.pid
                )

                if [[ "$FFMPEG_MIRROR_ROOT" =~ "$iptv_source"(.*) ]]
                then
                    relative_path="${BASH_REMATCH[1]:-}"
                    relative_path="${relative_path#/}"
                    if [ -n "$relative_path" ] 
                    then
                        for i in "${!ffmpeg_excludes_before[@]}"
                        do
                            if [[ "${ffmpeg_excludes_before[i]}" == /* ]] 
                            then
                                ffmpeg_excludes_before[i]="/${relative_path}${ffmpeg_excludes_before[i]}"
                            else
                                ffmpeg_excludes_before[i]="/$relative_path/${ffmpeg_excludes_before[i]}"
                            fi
                        done
                    fi
                    iptv_excludes_before+=("${ffmpeg_excludes_before[@]}")
                else
                    ffmpeg_source="$FFMPEG_MIRROR_ROOT"
                fi

                if [[ "$LIVE_ROOT" =~ "$IPTV_ROOT"(.+) ]]
                then
                    iptv_excludes_before+=("${BASH_REMATCH[1]}")
                fi

                node_excludes_before=(
                    node_modules/
                )

                if ! [[ "$NODE_ROOT" =~ "$IPTV_ROOT"(.*) ]]
                then
                    node_source="$NODE_ROOT"
                fi

                nginx_source="${NGINX_PREFIX_DEFAULT}"

                nginx_excludes_before=(
                    /logs/'*'.gz
                    node_modules/
                )

                nginx_includes=(
                    /conf/'***'
                    /html/'***'
                    /logs/'***'
                )

                nginx_excludes_after=(
                    /'***'
                )

                openresty_source="${OPENRESTY_PREFIX_DEFAULT}"

                openresty_excludes_before=(
                    /nginx/logs/'*'.gz
                    node_modules/
                )

                openresty_includes=(
                    /nginx/
                    /nginx/conf/'***'
                    /nginx/html/'***'
                    /nginx/logs/'***'
                    /nginx/lua/'***'
                )

                openresty_excludes_after=(
                    /'***'
                )

                v2ray_source="${V2_CONFIG%/*}"

                xray_source="${X_CONFIG%/*}"

                if [ "$dist" == "mac" ] 
                then
                    systemd_source="$HOME"/Library/LaunchAgents
                else
                    systemd_source=/etc/systemd/system
                fi

                systemd_includes=(
                    /openlist.service
                    /aria2.service
                    /dnscrypt-proxy.service
                    /mmproxy-'*'.service
                    /nginx.service
                    /openresty.service
                    /v2ray.service
                    /xray.service
                    /aios.'*'.service
                    /com.aios.'*'.plist
                )

                systemd_excludes_after=(
                    /'***'
                )

                services_source="$SERVICES_ROOT"

                services_excludes_before=(
                    venv/
                    node_modules/
                    .git/
                    /depends/
                    /calibre/bin/
                    /calibre/kcc/
                )

                home_source="$HOME"

                home_includes=(
                    /.bash_history
                )

                home_excludes_after=(
                    /'***'
                )

                DepInstall rsync

                mkdir -p "$BACKUP_ROOT"

                for backup in iptv nginx openresty v2ray xray ffmpeg node systemd services home
                do
                    rsync_commands=()
                    source="${backup}_source"

                    if [[ -z "${!source:-}" ]] 
                    then
                        continue
                    fi

                    source="${!source}"

                    if [ ! -d "$source" ] 
                    then
                        continue
                    fi

                    excludes_before=("${backup}_excludes_before"[@])

                    if [[ -n "${!excludes_before:-}" ]] 
                    then
                        excludes_before=("${!excludes_before}")
                        for exclude in "${excludes_before[@]}"
                        do
                            rsync_commands+=( --exclude="$exclude" )
                        done
                    fi

                    includes=("${backup}_includes"[@])

                    if [[ -n "${!includes:-}" ]] 
                    then
                        includes_arr=("${!includes}")
                        for include in "${includes_arr[@]}"
                        do
                            rsync_commands+=( --include="$include" )
                        done
                    fi

                    excludes_after=("${backup}_excludes_after"[@])

                    if [[ -n "${!excludes_after:-}" ]] 
                    then
                        excludes_after=("${!excludes_after}")
                        for exclude in "${excludes_after[@]}"
                        do
                            rsync_commands+=( --exclude="$exclude" )
                        done
                    fi

                    rsync -avP --safe-links --delete --delete-excluded ${rsync_commands[@]+"${rsync_commands[@]}"} "$source/" "$BACKUP_ROOT/$backup/"
                done

                Println "$(eval_gettext "\$info 已创建备份 \$BACKUP_ROOT")\n"

                exit 0
            ;;
            *)
            ;;
        esac
    fi

    if [ -z "$*" ]
    then
        ShFileCheck
        if [ "${vip:-false}" = true ] 
        then
            VipMenu
        else
            Menu
        fi
    else
        while getopts "i:l:P:o:p:S:t:s:c:v:a:f:q:b:r:k:K:m:n:z:H:T:L:CReh" flag
        do
            case "$flag" in
                i) stream_link="$OPTARG";;
                l) live=false;;
                P) proxy="$OPTARG";;
                o) output_dir_name="$OPTARG";;
                p) playlist_name="$OPTARG";;
                S) seg_dir_name="$OPTARG";;
                t) seg_name="$OPTARG";;
                s) seg_length="$OPTARG";;
                c) seg_count="$OPTARG";;
                v) video_codec="$OPTARG";;
                a) audio_codec="$OPTARG";;
                f) video_audio_shift="$OPTARG";;
                q) quality="$OPTARG";;
                b) bitrate="$OPTARG";;
                r) resolution="$OPTARG";;
                C) const=true;;
                R) const_cbr=true;;
                e) encrypt=true;;
                k) kind="$OPTARG";;
                K) key_name="$OPTARG";;
                m) input_flags="$OPTARG";;
                n) output_flags="$OPTARG";;
                z) channel_name="$OPTARG";;
                H) flv_h265=true;;
                T) flv_push_link="$OPTARG";;
                L) flv_pull_link="$OPTARG";;
                h|*) Usage;
            esac
        done

        if [ -z "${stream_link:-}" ]
        then
            Usage
        fi

        if [ ! -d "$IPTV_ROOT" ]
        then
            echo
            ExitOnList n "`gettext \"尚未安装, 是否现在安装\"`"
            Install
        else
            FFmpegInstall

            GetDefault

            stream_links=("$stream_link")
            stream_link="${stream_links[0]}"

            if [ -z "${proxy:-}" ] 
            then
                if [[ $stream_link =~ ^https?:// ]] && [ -n "$d_proxy" ] 
                then
                    echo
                    inquirer list_input "`eval_gettext \"是否使用代理 \\\$d_proxy: \"`" yn_options use_proxy_yn
                    if [ "$use_proxy_yn" == "$i18n_yes" ]
                    then
                        proxy="$d_proxy"
                    else
                        proxy=""
                    fi
                else
                    proxy=""
                fi
            fi

            if [ -z "${xc_proxy:-}" ] 
            then
                if [ -n "$d_xc_proxy" ] 
                then
                    if [[ $stream_link =~ ^http://([^/]+) ]] 
                    then
                        XtreamCodesGetDomains

                        xc_proxy=""
                        for xc_domain in "${xtream_codes_domains[@]}"
                        do
                            if [ "$xc_domain" == "${BASH_REMATCH[1]}" ] 
                            then
                                echo
                                inquirer list_input "`eval_gettext \"是否使用 xtream codes 代理 \\\$d_xc_proxy: \"`" yn_options use_proxy_yn
                                if [ "$use_proxy_yn" == "$i18n_yes" ]
                                then
                                    xc_proxy="$d_xc_proxy"
                                else
                                    xc_proxy=""
                                fi
                                break
                            fi
                        done
                    else
                        xc_proxy=""
                    fi
                else
                    xc_proxy=""
                fi
            fi

            user_agent="$d_user_agent"
            headers="$d_headers"

            while [[ $headers =~ \\\\ ]]
            do
                headers=${headers//\\\\/\\}
            done

            if [ -n "$headers" ] && [[ ! $headers =~ \\r\\n$ ]]
            then
                headers="$headers\r\n"
            fi

            cookies="$d_cookies"
            output_dir_name="${output_dir_name:-$(RandOutputDirName)}"
            output_dir_root="$LIVE_ROOT/$output_dir_name"
            playlist_name="${playlist_name:-$(RandPlaylistName)}"
            seg_dir_name="${seg_dir_name:-$d_seg_dir_name}"

            if [ -n "$seg_dir_name" ] 
            then
                seg_dir_path="$seg_dir_name/"
            else
                seg_dir_path=""
            fi

            seg_name="${seg_name:-$playlist_name}"
            seg_length="${seg_length:-$d_seg_length}"
            seg_count="${seg_count:-$d_seg_count}"
            audio_codec="${audio_codec:-$d_audio_codec}"
            video_codec="${video_codec:-$d_video_codec}"
            use_primary_playlist=false
            hboasia_host="hbogoasia.com:8443"

            const=${const:-$d_const}
            const_cbr=${const_cbr:-$d_const_cbr}

            live=${live:-true}

            video_audio_shift="${video_audio_shift:-}"
            v_or_a="${video_audio_shift%_*}"

            if [ "$v_or_a" == "v" ] 
            then
                video_shift="${video_audio_shift#*_}"
            elif [ "$v_or_a" == "a" ] 
            then
                audio_shift="${video_audio_shift#*_}"
            fi

            draw_text="${draw_text:-$d_draw_text}"
            quality="${quality:-$d_quality}"
            bitrate="${bitrate:-$d_bitrate}"
            resolution="${resolution:-$d_resolution}"

            master=0
            if [[ $bitrate =~ , ]] || [[ $quality =~ , ]] || [[ $resolution =~ , ]] 
            then
                master=1
            fi

            if [ -z "${encrypt:-}" ]  
            then
                if [ "$d_encrypt" = true ] 
                then
                    encrypt=true
                    encrypt_session="$d_encrypt_session"
                else
                    encrypt=false
                    encrypt_session=false
                fi
            else
                encrypt=true
                encrypt_session="$d_encrypt_session"
            fi

            keyinfo_name="${keyinfo_name:-$d_keyinfo_name}"
            keyinfo_name="${keyinfo_name:-$(RandStr)}"
            key_name="${key_name:-$d_key_name}"
            key_name="${key_name:-$(RandStr)}"

            if [ "${stream_link:0:4}" == "rtmp" ] || [ "${stream_link:0:1}" == "/" ]
            then
                d_input_flags="${d_input_flags//-timeout 2000000000/}"
                d_input_flags="${d_input_flags//-reconnect 1/}"
                d_input_flags="${d_input_flags//-reconnect_at_eof 1/}"
                d_input_flags="${d_input_flags//-reconnect_streamed 1/}"
                d_input_flags="${d_input_flags//-reconnect_delay_max 2000/}"
                Trim d_input_flags
            elif [[ $stream_link == *".m3u8"* ]] || [[ $stream_link =~ \|(origin|parse)\| ]]
            then
                d_input_flags="${d_input_flags//-reconnect_at_eof 1/}"
            fi

            input_flags="${input_flags:-$d_input_flags}"
            if [[ ${input_flags:0:1} == "'" ]] 
            then
                input_flags="${input_flags%\'}"
                input_flags="${input_flags#\'}"
            fi

            if [ "${output_flags:-}" == "omit" ] 
            then
                output_flags=""
            else
                output_flags="${output_flags:-$d_output_flags}"
            fi

            if [[ ${output_flags:0:1} == "'" ]] 
            then
                output_flags="${output_flags%\'}"
                output_flags="${output_flags#\'}"
            fi

            channel_name="${channel_name:-$playlist_name}"
            sync="$d_sync"
            sync_file="${sync_file:-}"
            sync_index="${sync_index:-}"
            sync_pairs="${sync_pairs:-}"
            hls_end_list="${d_hls_end_list:-false}"

            mkdir -p "$FFMPEG_LOG_ROOT"

            flv_h265="${flv_h265:-false}"
            flv_push_link="${flv_push_link:-}"
            flv_pull_link="${flv_pull_link:-}"

            extra_filters=""
            if [ "$video_codec" != "copy" ] && [ -n "$draw_text" ] 
            then
                filters=( vf filter:v )
                for filter in "${filters[@]}"
                do
                    if [[ $output_flags =~ (.*)"-$filter "([^ ]+)(.*) ]] 
                    then
                        extra_filters="${BASH_REMATCH[2]},"
                        output_flags="${BASH_REMATCH[1]} ${BASH_REMATCH[3]}"
                    fi
                done
            fi

            flags_command=( -flags )
            if [[ $output_flags =~ (.*)"-flags "([^ ]+)(.*) ]] 
            then
                flags="${BASH_REMATCH[2]}"

                if [[ $flags =~ global_header ]] 
                then
                    flags_command=( -flags "$flags" )
                else
                    flags_command+=("-global_header$flags")
                fi

                output_flags="${BASH_REMATCH[1]} ${BASH_REMATCH[3]}"
            else
                flags_command+=(-global_header)
            fi

            FilterString input_flags output_flags

            from="AddChannel"

            if [ -n "${kind:-}" ] 
            then
                if [ "$kind" == "flv" ] 
                then
                    if [ -z "${flv_push_link:-}" ] 
                    then
                        Println "`eval_gettext \"\\\$error 未设置推流地址...\"`\n" && exit 1
                    else
                        if [ "$sh_debug" = true ] 
                        then
                            ( FlvStreamCreator ) 
                        else
                            ( FlvStreamCreator ) > /dev/null 2> /dev/null < /dev/null &
                        fi
                    fi
                else
                    Println "`eval_gettext \"\\\$error 暂不支持输出 \$kind ...\"`\n" && exit 1
                fi
            else
                if [ "$sh_debug" = true ] 
                then
                    ( HlsStreamCreatorPlus ) 
                else
                    ( HlsStreamCreatorPlus ) > /dev/null 2> /dev/null < /dev/null &
                fi
            fi

            Println "`eval_gettext \"\\\$info 添加频道成功\"`\n"
        fi
    fi
elif [ "$self" == "v2" ]
then
    V2rayGetFreeTag()
    {
        local prefix="${1:-}"
        local tag_val=""
        tag_val=$(ProxyGetFreeTag "$V2_CONFIG" "$prefix")
        if [ -z "$prefix" ]
        then
            tag_val="${tag_val//nginx-/}"
        fi
        printf '%s' "$tag_val"
    }

    V2raySetListen()
    {
        echo
        inquirer text_input "$(gettext "输入监听地址"): " listen "0.0.0.0"
    }

    V2raySetFollowRedirect()
    {
        Println "$(eval_gettext "\$tip 如果选 是, 安全起见需要你自己设置透明代理的防火墙 详见: https://www.v2fly.org/config/protocols/dokodemo.html")"
        inquirer list_input "$(gettext "识别出由 iptables 转发而来的数据, 并转发到相应的目标地址")" ny_options follow_redirect

        if [ "$follow_redirect" == "$i18n_no" ]
        then
            follow_redirect=false
        else
            follow_redirect=true
        fi
    }

    V2raySetAddress()
    {
        echo
        ExitOnText "$(gettext "输入目标服务器地址(ip或域名): ")" address
    }

    V2raySetDnsAddress()
    {
        Println "$(eval_gettext "\$tip 当不指定时, 保持来源中指定的地址不变")"
        inquirer text_input "$(gettext "修改 DNS 服务器地址: ")" dns_address "$(gettext "不指定")"

        if [ "$dns_address" == "$(gettext "不指定")" ]
        then
            dns_address=""
        fi
    }

    V2raySetLocalPort()
    {
        local prompt_default_random
        prompt_default_random=$(gettext "默认: 随机生成")
        Println "$(gettext "请输入端口, 可以是 整型数值, 环境变量, 端口范围")"
        while read -r -p "($prompt_default_random): " port
        do
            case "$port" in
                "")
                    port=$(GetFreePort)
                    break
                ;;
                *[!0-9]*)
                    if [[ $port =~ ^([0-9]+)-([0-9]+)$ ]]
                    then
                        break
                    else
                        Println "$(eval_gettext "\$error 输入错误")\n"
                    fi
                ;;
                *)
                    if [ "$port" -ge 1 ] && [ "$port" -le 65535 ]
                    then
                        if ( echo -n "" > /dev/tcp/127.0.0.1/"$port" ) > /dev/null 2>&1
                        then
                            Println "$(eval_gettext "\$error 端口已被其他程序占用! 请重新输入!")\n"
                        else
                            break
                        fi
                    else
                        Println "$error $i18n_input_correct_number [1-65535]\n"
                    fi
                ;;
            esac
        done
        Println "  $i18n_port: ${green} $port ${normal}"
    }

    V2raySetAddressPort()
    {
        Println "$(gettext "请输入端口")"
        while read -r -p "$i18n_default_cancel" address_port
        do
            case "$address_port" in
                "")
                    Println "$i18n_canceled...\n"
                    return 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_number\n"
                ;;
                *)
                    if [ "$address_port" -gt 0 ] && [ "$address_port" -le 65535 ]
                    then
                        break
                    else
                        Println "$error $i18n_input_correct_number\n"
                    fi
                ;;
            esac
        done
        Println "  $i18n_port: ${green} $address_port ${normal}"
    }

    V2raySetSocksVersion()
    {
        echo
        socks_version_options=( '5' '4a' '4' )
        inquirer list_input "$(gettext "选择 Socks 协议版本")" socks_version_options socks_version
    }

    V2raySetDnsPort()
    {
        Println "$(eval_gettext "\$tip 当不指定时, 保持来源中指定的端口不变")"
        inquirer text_input "$(gettext "修改 DNS 服务器端口: ")" dns_port "$(gettext "不指定")"

        if [ "$dns_port" == "$(gettext "不指定")" ]
        then
            dns_port=""
        fi
    }

    V2raySetSettingsNetwork()
    {
        Println "$(eval_gettext "\$tip 比如当指定为 tcp 时, 仅会接收 TCP 流量")"
        settings_network_options=( 'tcp' 'udp' 'tcp,udp' )
        inquirer list_input "$(gettext "可接收的网络协议类型")" settings_network_options settings_network
    }

    V2raySetIvCheck()
    {
        echo
        inquirer list_input_index "$(gettext "启用 IV 检查功能")" ny_options ny_index

        if [ "$ny_index" -eq 0 ]
        then
            iv_check=false
        else
            iv_check=true
        fi
    }

    V2raySetDnsNetwork()
    {
        Println "$(eval_gettext "\$tip 当不指定时, 保持来源的传输方式不变")"
        dns_network_options=( 'tcp' 'udp' "$(gettext "不指定")" )
        inquirer list_input "$(gettext "DNS 流量的传输层协议")" dns_network_options dns_network

        if [ "$dns_network" == "$(gettext "不指定")" ]
        then
            dns_network=""
        fi
    }

    V2raySetInboundProtocol()
    {
        local v2_ver="${1:-$(ProxyGetTargetVersion "v2ray")}"
        local v2_fmt="${2:-$(ProxyGetV2rayFormat)}"

        echo
        protocol_options=( 'vmess' 'vless' 'http' 'socks' 'shadowsocks' 'dokodemo-door' 'trojan' )

        if ProxyCoreHasFeature "v2ray" "$v2_ver" "$v2_fmt" "shadowsocks2022"
        then
            protocol_options+=('shadowsocks2022')
        fi

        if ProxyCoreHasFeature "v2ray" "$v2_ver" "$v2_fmt" "hysteria2"
        then
            protocol_options+=('hysteria2')
        fi

        inquirer list_input "$(gettext "选择传输协议")" protocol_options protocol
    }

    V2raySetOutboundProtocol()
    {
        local v2_ver="${1:-$(ProxyGetTargetVersion "v2ray")}"
        local v2_fmt="${2:-$(ProxyGetV2rayFormat)}"

        echo
        protocol_options=( 'vmess' 'vless' 'http' 'socks' 'shadowsocks' 'trojan' 'blackhole' 'dns' 'freedom' 'loopback' )

        if ProxyCoreHasFeature "v2ray" "$v2_ver" "$v2_fmt" "shadowsocks2022"
        then
            protocol_options+=('shadowsocks2022')
        fi

        if ProxyCoreHasFeature "v2ray" "$v2_ver" "$v2_fmt" "hysteria2"
        then
            protocol_options+=('hysteria2')
        fi

        inquirer list_input "$(gettext "选择传输协议")" protocol_options protocol
    }

    V2raySetInboundNetwork()
    {
        local v2_ver="${1:-$(ProxyGetTargetVersion "v2ray")}"
        local v2_fmt="${2:-$(ProxyGetV2rayFormat)}"

        echo
        network_options=( 'ws' 'tcp' 'kcp' 'http/2' 'quic' 'domainsocket' 'grpc' 'httpupgrade' )

        if ProxyCoreHasFeature "v2ray" "$v2_ver" "$v2_fmt" "hysteria2"
        then
            network_options+=('hy2')
        fi

        inquirer list_input "$(gettext "选择传输方式")" network_options network

        if [ "$network" == "http/2" ]
        then
            network="http"
        fi
    }

    V2raySetOutboundNetwork()
    {
        local v2_ver="${1:-$(ProxyGetTargetVersion "v2ray")}"
        local v2_fmt="${2:-$(ProxyGetV2rayFormat)}"

        echo
        network_options=( 'ws' 'tcp' 'kcp' 'http/2' 'quic' 'grpc' 'httpupgrade' )

        if ProxyCoreHasFeature "v2ray" "$v2_ver" "$v2_fmt" "hysteria2"
        then
            network_options+=('hy2')
        fi

        inquirer list_input "$(gettext "选择传输方式")" network_options network

        if [ "$network" == "http/2" ]
        then
            network="http"
        fi
    }

    V2raySetSecurity()
    {
        echo
        security_options=( 'none' 'tls' )
        inquirer list_input "$(gettext "选择传输加密")" security_options security
    }

    V2raySetTlsServerName()
    {
        Println "$(eval_gettext "\$tip 在连接由 IP 建立时有用")"
        inquirer text_input "$(gettext "指定服务器端证书的域名")" tls_server_name "$i18n_blank"

        if [ "$tls_server_name" == "$i18n_blank" ]
        then
            tls_server_name=""
        fi
    }

    V2raySetTlsAllowInsecure()
    {
        Println "$(eval_gettext "\$tip 在自定义证书的情况下可以选 否")"
        inquirer list_input_index "$(gettext "是否检测证书有效性")" yn_options yn_index

        if [ "$yn_index" -eq 0 ]
        then
            tls_allow_insecure=false
        else
            tls_allow_insecure=true
        fi
    }

    V2raySetTlsAlpn()
    {
        if [ "${1:-}" == "inbound" ] && { [ "$protocol" == "vless" ] || [ "$protocol" == "trojan" ]; } && [ "$network" == "tcp" ]
        then
            Println "$(eval_gettext "\$tip 多个 ALPN 值用空格分隔, 如果要设置 \$protocol 协议回落这里至少需要 http/1.1")"
        else
            Println "$(eval_gettext "\$tip 多个 ALPN 值用空格分隔")"
        fi

        inquirer text_input "$(gettext "指定 ALPN 值")" tls_alpn_raw "h2 http/1.1"
        tls_alpn_json="[]"

        if [ -n "$tls_alpn_raw" ]
        then
            tls_alpn_json=$($JQ_FILE -n -c --arg s "$tls_alpn_raw" '$s | split(" ") | map(select(length > 0))')
        fi
    }

    V2raySetTlsDisableSystemRoot()
    {
        Println "$(eval_gettext "\$tip 不禁用时只会使用操作系统自带的 CA 证书进行 TLS 握手")"

        if [ "${1:-}" == "inbound" ]
        then
            inquirer list_input "$(gettext "是否禁用操作系统自带的 CA 证书")" yn_options tls_disable_system_root_yn
        else
            inquirer list_input "$(gettext "是否禁用操作系统自带的 CA 证书")" ny_options tls_disable_system_root_yn
        fi

        if [ "$tls_disable_system_root_yn" == "$i18n_no" ]
        then
            tls_disable_system_root=false
        else
            tls_disable_system_root=true
        fi
    }

    V2raySetTlsVerifyClientCertificate()
    {
        echo
        inquirer list_input "$(gettext "在连接时进行客户端证书认证")" ny_options tls_verify_client_certificate_yn

        if [ "$tls_verify_client_certificate_yn" == "$i18n_no" ]
        then
            tls_verify_client_certificate=false
        else
            tls_verify_client_certificate=true
        fi
    }

    V2raySetTlsPinnedPeerCertificateChainSha256()
    {
        local prompt_pinned
        prompt_pinned=$(gettext "证书链的 SHA256 散列值 (Base64, 多个用逗号分隔, 留空跳过)")
        tls_pinned_sha256_json="[]"

        while true
        do
            echo
            inquirer text_input "$prompt_pinned" tls_pinned_raw ""

            if [ -z "$tls_pinned_raw" ]
            then
                tls_pinned_sha256_json="[]"
                return 0
            fi

            local items=()
            local item="" trimmed="" valid=1
            local valid_items=()
            IFS="," read -r -a items <<< "$tls_pinned_raw"

            for item in "${items[@]}"
            do
                trimmed=$(printf '%s' "$item" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')
                [ -z "$trimmed" ] && continue
                if [[ ! "$trimmed" =~ ^[A-Za-z0-9+/]+={0,2}$ ]]
                then
                    Println "$(eval_gettext "\$error 散列值格式无效 (必须为合法 Base64 字符串): \$trimmed")\n"
                    valid=0
                    break
                fi
                valid_items+=("$trimmed")
            done

            if [ "$valid" -eq 1 ]
            then
                if [ "${#valid_items[@]}" -eq 0 ]
                then
                    tls_pinned_sha256_json="[]"
                else
                    tls_pinned_sha256_json=$(printf '%s\n' "${valid_items[@]}" | $JQ_FILE -R -s -c 'split("\n") | map(select(length > 0))')
                fi
                return 0
            fi
        done
    }

    V2raySetCertificateFile()
    {
        Println "$(eval_gettext "\$tip 如使用 OpenSSL 生成, 后缀名为 .crt, 文件必须存在")"
        inquirer text_input "$(gettext "输入证书文件路径: ")" certificate_file

        local cert_dir="$V2_ROOT/certs"
        if ! mkdir -p "$cert_dir"
        then
            Println "$(eval_gettext "\$error 创建证书目录失败: \$cert_dir")\n"
            return 1
        fi

        if [ -s "$certificate_file" ]
        then
            cp -f "$certificate_file" "$cert_dir/"
            certificate_file="$cert_dir/${certificate_file##*/}"
            ProxySyncCertPerms "v2ray" "$certificate_file" ""
            Println "$(eval_gettext "\$info 已复制证书到 \$certificate_file 并同步 aios-v2ray 读权限")"
        else
            Println "$(eval_gettext "\$error 证书不存在: \$certificate_file")"
            return 1
        fi
    }

    V2raySetKeyFile()
    {
        Println "$(eval_gettext "\$tip 如使用 OpenSSL 生成, 后缀名为 .key, 密钥必须存在")"
