            V2rayDeleteOutboundAccount
        ;;
        25)
            ProxyToggleService aios-v2ray "$V2_CONFIG"
        ;;
        26)
            ProxyRestartService aios-v2ray "$V2_CONFIG"
        ;;
        27)
            ProxyCoreMenu "v2ray"
        ;;
        28)
            V2raySetAdvanced
        ;;
        29)
            ProxyImportUrisInteractive "v2ray"
        ;;
        30)
            ProxyApplyPresetInteractive "v2ray"
        ;;
        *) Println "$error $i18n_input_correct_number [1-30]\n"
        ;;
    esac

    exit 0
elif [ "$self" == "x" ]
then
    XrayInstall()
    {
        local req_tag="${1:-v${XRAY_LATEST_TESTED_VER}}"
        DepsCheck
        JQInstall
        ProxyEnsureDirs

        if [ -x "$AIOS_XRAY_BIN" ] && [ -t 0 ] && [ -z "${1:-}" ]
        then
            Println "$(eval_gettext "\$info aios-xray 已存在, 可继续安装其他版本到隔离槽位")\n"
        fi

        Println "$(eval_gettext "\$info 安装隔离版 aios-xray (\$req_tag)...")"
        if ProxyCoreInstall "xray" "$req_tag"
        then
            if [ ! -s "$X_CONFIG" ]
            then
                local default_cfg='{"log":{"logLevel":"warning"},"inbounds":[],"outbounds":[{"tag":"direct","protocol":"freedom"}]}'
                if ! ProxyConfigTx "xray" "$default_cfg" 1
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 初始化 Xray 默认配置失败: \$err_detail")\n"
                    return 1
                fi
            fi

            local svc_err=""
            if ! svc_err=$(ServiceControl start aios-xray 2>&1)
            then
                Println "$(eval_gettext "\$error 启动 aios-xray 服务失败: \$svc_err")\n"
                return 1
            fi

            Println "$(eval_gettext "\$info aios-xray 安装完成")\n"
        else
            Println "$(eval_gettext "\$error aios-xray 安装失败")\n"
            return 1
        fi
    }

    XrayUpdate()
    {
        local req_tag="${1:-v${XRAY_LATEST_TESTED_VER}}"
        DepsCheck
        JQInstall
        ShFileUpdate xray
        ProxyEnsureDirs

        if ProxyCoreInstall "xray" "$req_tag"
        then
            if ProxyCoreSwitch "xray" "$req_tag"
            then
                Println "$(eval_gettext "\$info aios-xray 已安全切换至 \$req_tag")\n"
            else
                local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                Println "$(eval_gettext "\$error aios-xray 切换失败: \$err_detail")\n"
                return 1
            fi
        else
            return 1
        fi
    }
    XrayConfigDomain()
    {
        if [ ! -e "$X_CONFIG" ]
        then
            Println "$(eval_gettext "\$error 尚未安装 xray, 请检查 !")\n"
            return 1
        fi

        ProxyDetectNginx

        local target_mode="xray"
        if [ -x "$NGINX_FILE" ]
        then
            echo
            local target_opts=( "$(gettext "xray 直连 TLS 证书")" "$(eval_gettext "\${nginx_name} 反代站点管理")" )
            local target_idx=""
            inquirer list_input_index "$(gettext "选择配置目标")" target_opts target_idx
            if [ "$target_idx" -eq 1 ]
            then
                target_mode="nginx"
            fi
        fi

        if [ "$target_mode" == "nginx" ]
        then
            Println "$(eval_gettext "\$info 检测到 \${green}\${nginx_name}\${normal}, 可通过 \${green}\${nginx_ctl}\${normal} 管理站点反代与 TLS 证书")\n"
            return 0
        fi

        if ! ProxySelectBound "$X_CONFIG" "inbounds" "$(gettext "选择要管理证书的直连入站")"
        then
            return 1
        fi

        local ib_idx="$selected_bound_index"
        local ib_tag="${inbounds_tag[$ib_idx]}"
        local sec_type
        sec_type=$(JQs query "$X_CONFIG" '
            (if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object" and (.inbounds[$i].streamSettings | type) == "object"
             then .inbounds[$i].streamSettings.security
             else null end) // "none"
        ' --argjson i "$ib_idx")
        sec_type="${sec_type:-none}"

        if [ "$sec_type" != "tls" ]
        then
            Println "$(eval_gettext "\$error 入站 \${green}\${ib_tag}\${normal} 当前安全类型为 \${green}\${sec_type}\${normal} (非 tls), 无需配置 TLS 证书")\n"
            return 1
        fi

        local certs_info
        certs_info=$(JQs query "$X_CONFIG" '
            (if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                and (.inbounds[$i].streamSettings | type) == "object"
                and (.inbounds[$i].streamSettings.tlsSettings | type) == "object"
                and (.inbounds[$i].streamSettings.tlsSettings.certificates | type) == "array"
             then .inbounds[$i].streamSettings.tlsSettings.certificates
             else [] end)
            | to_entries[]
            | select(.value | type == "object")
            | "\(.key)\t\(.value.usage // "encipherment")\t\(.value.certificateFile // "")\t\(.value.keyFile // "")\t\(.value.ocspStapling // "")"
        ' --argjson i "$ib_idx")

        local action_opts=( "$(gettext "修改证书文件路径")" "$(gettext "修改密钥文件路径")" "$(gettext "修改证书用途 / OCSP")" "$(gettext "添加新证书条目")" "$(gettext "删除证书条目")" )
        local cert_indices=()
        local cert_labels=()

        if [ -n "$certs_info" ]
        then
            Println "$(eval_gettext "\${green}入站 \${ib_tag} 当前 TLS 证书:\${normal}")\n"
            local line c_idx c_usage c_file k_file c_ocsp
            while IFS=$'\t' read -r c_idx c_usage c_file k_file c_ocsp
            do
                [ -z "$c_idx" ] && continue
                cert_indices+=("$c_idx")
                cert_labels+=("#$((c_idx + 1)) [${c_usage}] ${c_file:-<inline>}")
                Println "  $((c_idx + 1)). $(gettext "用途"): ${green}${c_usage}${normal}  $(gettext "证书"): ${green}${c_file:-<inline>}${normal}  $(gettext "密钥"): ${green}${k_file:-<inline>}${normal}"
                if [ -n "$c_ocsp" ]
                then
                    Println "     OCSP Stapling: ${green}${c_ocsp}s${normal}"
                fi
            done <<< "$certs_info"
            echo
        else
            Println "$(eval_gettext "\$tip 当前入站尚未配置证书条目")\n"
        fi

        local action_idx=""
        inquirer list_input_index "$(gettext "选择证书操作")" action_opts action_idx

        case "$action_idx" in
            0)
                if [ ${#cert_indices[@]} -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可修改的证书条目")\n"
                    return 1
                fi
                local sel_c=0
                if [ ${#cert_indices[@]} -gt 1 ]
                then
                    inquirer list_input_index "$(gettext "选择证书条目")" cert_labels sel_c
                fi
                local target_c="${cert_indices[$sel_c]}"
                local new_crt=""
                inquirer text_input "$(gettext "输入新的证书文件路径 (certificateFile): ")" new_crt
                [ -z "$new_crt" ] && return 1
                ProxySyncCertPerms "xray" "$new_crt" ""
                if ! ProxyMutateConfigTx "xray" '.inbounds[$i].streamSettings.tlsSettings.certificates[$c].certificateFile = $v' \
                    --argjson i "$ib_idx" --argjson c "$target_c" --arg v "$new_crt"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 证书路径修改失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 证书路径修改成功")\n"
            ;;
            1)
                if [ ${#cert_indices[@]} -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可修改的证书条目")\n"
                    return 1
                fi
                local sel_c=0
                if [ ${#cert_indices[@]} -gt 1 ]
                then
                    inquirer list_input_index "$(gettext "选择证书条目")" cert_labels sel_c
                fi
                local target_c="${cert_indices[$sel_c]}"
                local new_key=""
                inquirer text_input "$(gettext "输入新的密钥文件路径 (keyFile): ")" new_key
                [ -z "$new_key" ] && return 1
                ProxySyncCertPerms "xray" "" "$new_key"
                if ! ProxyMutateConfigTx "xray" '.inbounds[$i].streamSettings.tlsSettings.certificates[$c].keyFile = $v' \
                    --argjson i "$ib_idx" --argjson c "$target_c" --arg v "$new_key"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 密钥路径修改失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 密钥路径修改成功")\n"
            ;;
            2)
                if [ ${#cert_indices[@]} -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可修改的证书条目")\n"
                    return 1
                fi
                local sel_c=0
                if [ ${#cert_indices[@]} -gt 1 ]
                then
                    inquirer list_input_index "$(gettext "选择证书条目")" cert_labels sel_c
                fi
                local target_c="${cert_indices[$sel_c]}"
                local usage_opts=( "encipherment" "verify" "issue" )
                local usage_idx=""
                inquirer list_input_index "$(gettext "选择证书用途")" usage_opts usage_idx
                local new_usage="${usage_opts[$usage_idx]}"
                local new_ocsp="" cert_patch=""
                inquirer text_input "$(gettext "OCSP Stapling 间隔秒数 (默认 0 不启用, 留空不修改): ")" new_ocsp
                if [ -n "$new_ocsp" ] && [[ ! $new_ocsp =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error ocspStapling 必须为非负整数")\n"
                    return 1
                fi
                JQs build cert_patch '{"usage": $u, "ocspStapling": (if $o != "" then ($o | tonumber) else null end)}' \
                    --arg u "$new_usage" --arg o "$new_ocsp"
                if ! ProxyMutateConfigTx "xray" '.inbounds[$i].streamSettings.tlsSettings.certificates[$c] = ((.inbounds[$i].streamSettings.tlsSettings.certificates[$c] // {}) + $patch)' \
                    --argjson i "$ib_idx" --argjson c "$target_c" --argjson patch "$cert_patch"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 证书用途 / OCSP 更新失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 证书用途 / OCSP 更新成功")\n"
            ;;
            3)
                local usage_opts=( "encipherment" "verify" "issue" )
                local usage_idx=""
                inquirer list_input_index "$(gettext "选择证书用途")" usage_opts usage_idx
                local new_usage="${usage_opts[$usage_idx]}"
                local new_crt="" new_key="" new_ocsp="" cert_json=""
                inquirer text_input "$(gettext "证书文件路径 (certificateFile): ")" new_crt
                inquirer text_input "$(gettext "密钥文件路径 (keyFile, verify 用途可留空): ")" new_key
                inquirer text_input "$(gettext "OCSP Stapling 间隔秒数 (默认 0 不启用, 留空跳过): ")" new_ocsp
                if [ -z "$new_crt" ]
                then
                    Println "$(eval_gettext "\$error 证书文件路径不能为空")\n"
                    return 1
                fi
                if [ "$new_usage" != "verify" ] && [ -z "$new_key" ]
                then
                    Println "$(eval_gettext "\$error 非 verify 用途必须填写密钥文件路径 (keyFile)")\n"
                    return 1
                fi
                if [ -n "$new_ocsp" ] && [[ ! $new_ocsp =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error ocspStapling 必须为非负整数")\n"
                    return 1
                fi
                JQs build cert_json '{
                    "usage": $u,
                    "certificateFile": $c,
                    "keyFile": $k,
                    "ocspStapling": (if $o != "" then ($o | tonumber) else null end)
                }' --arg u "$new_usage" --arg c "$new_crt" --arg k "$new_key" --arg o "$new_ocsp"
                ProxySyncCertPerms "xray" "$new_crt" "$new_key"
                if ! ProxyMutateConfigTx "xray" '.inbounds[$i].streamSettings.tlsSettings.certificates = ((.inbounds[$i].streamSettings.tlsSettings.certificates // []) + [$item])' \
                    --argjson i "$ib_idx" --argjson item "$cert_json"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 添加证书条目失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已添加证书条目")\n"
            ;;
            4)
                if [ ${#cert_indices[@]} -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可删除的证书条目")\n"
                    return 1
                fi
                local sel_c=0
                if [ ${#cert_indices[@]} -gt 1 ]
                then
                    inquirer list_input_index "$(gettext "选择要删除的证书条目")" cert_labels sel_c
                fi
                local target_c="${cert_indices[$sel_c]}"
                if ! ProxyMutateConfigTx "xray" 'del(.inbounds[$i].streamSettings.tlsSettings.certificates[$c])' \
                    --argjson i "$ib_idx" --argjson c "$target_c"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 删除证书条目失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已删除证书条目")\n"
            ;;
        esac
    }
    XrayGetInbounds()
    {
        ProxyLoadInboundsIndex "$X_CONFIG"
    }
    XrayListInbounds()
    {
        XrayGetInbounds

        local list_inbounds_options=( "$(gettext "全部入站")" "$(gettext "本地 nginx 入站")" "$(gettext "直连 xray 入站")" )
        local filter_mode="all"
        local count=0

        if [ "${1:-}" == "nginx" ]
        then
            list_inbounds_options_index=1
            filter_mode="nginx"
            count=$inbounds_nginx_count
        elif [ "${1:-}" == "direct" ]
        then
            list_inbounds_options_index=2
            filter_mode="direct"
            count=$inbounds_other_count
        else
            echo
            inquirer list_input_index "$(gettext "选择显示的范围")" list_inbounds_options list_inbounds_options_index

            if [ "$list_inbounds_options_index" -eq 0 ]
            then
                filter_mode="all"
                count=$inbounds_count
            elif [ "$list_inbounds_options_index" -eq 1 ]
            then
                filter_mode="nginx"
                count=$inbounds_nginx_count
            else
                filter_mode="direct"
                count=$inbounds_other_count
            fi
        fi

        local scope_label="${list_inbounds_options[list_inbounds_options_index]}"

        if [ "$count" -eq 0 ]
        then
            if [ "$list_inbounds_options_index" -eq 0 ]
            then
                Println "$(eval_gettext "\$error 请先添加入站")\n"
            else
                Println "$(eval_gettext "\$error 请先添加 \${scope_label}")\n"
            fi
            return 1
        fi

        Println "\n$(eval_gettext "=== \${scope_label}数 \${green} \$count \${normal}")"
        inbounds_list=$(ProxyRenderInbounds "$X_CONFIG" xray "$filter_mode")
        Println "$inbounds_list"
    }
    XrayListInboundAccounts()
    {
        XrayListInbounds "${1:-}" || return 1

        if ! ProxySelectBound "$X_CONFIG" inbounds "$(gettext "选择查看账号明细的入站")"
        then
            inbounds_index=""
            return 1
        fi

        local idx="$selected_bound_index"
        local bound_tag="${inbounds_tag[idx]}"
        inbounds_index="$idx"
        local accounts_out
        accounts_out=$(ProxyRenderInboundAccounts "$X_CONFIG" "$idx")

        if [ -z "$accounts_out" ]
        then
            Println "$(eval_gettext "\$info 入站 \${green}\${bound_tag}\${normal} 没有多账号配置")\n"
            return 0
        fi

        Println "\n$(eval_gettext "=== 入站 \${green}\${bound_tag}\${normal} 账号明细 ===")\n$accounts_out\n"
    }
    XrayListInboundShare()
    {
        local host="${1:-}"
        local only_idx="${2:-${inbounds_index:-}}"
        if [ "$only_idx" == "all" ]
        then
            only_idx=""
        fi

        local links
        links=$(ProxyRenderShareLinks "$X_CONFIG" "$host" "$only_idx" "xray")

        if [ -n "$links" ]
        then
            Println "\n$(gettext "=== Xray 分享链接 ===")\n$links\n"
            if [ "${3:-}" == "qr" ]
            then
                local link_arr=()
                local link_labels=()
                local line idx_num=0 remark
                while IFS= read -r line
                do
                    [ -z "$line" ] && continue
                    link_arr+=("$line")
                    idx_num=$((idx_num + 1))
                    remark=""
                    if [[ "$line" == *"#"* ]]
                    then
                        remark="${line##*#}"
                    fi
                    if [ -n "$remark" ]
                    then
                        link_labels+=("${idx_num}. ${remark} (${line:0:32}...)")
                    else
                        link_labels+=("${idx_num}. ${line:0:48}...")
                    fi
                done <<< "$links"

                local target_link=""
                if [ "${#link_arr[@]}" -eq 1 ]
                then
                    target_link="${link_arr[0]}"
                elif [ "${#link_arr[@]}" -gt 1 ]
                then
                    local qr_idx=0
                    inquirer list_input_index "$(gettext "选择要打印二维码的账号链接")" link_labels qr_idx
                    target_link="${link_arr[$qr_idx]}"
                fi

                if [ -n "$target_link" ]
                then
                    ProxyPrintQrCode "$target_link"
                fi
            fi
        fi
    }
    XrayGetBin()
    {
        if [ -n "${AIOS_XRAY_BIN:-}" ] && [ -x "$AIOS_XRAY_BIN" ]
        then
            printf '%s' "$AIOS_XRAY_BIN"
        fi
    }

    XrayAddInbound()
    {
        local mode_options=( "$(gettext "直连 xray 入站")" "$(gettext "本地 nginx 反代入站")" )
        local mode_idx=0
        echo
        inquirer list_input_index "$(gettext "选择入站模式")" mode_options mode_idx

        local proto_options=( 'vless' 'vmess' 'trojan' 'shadowsocks' 'socks' 'http' 'tunnel' 'hysteria' 'wireguard' 'tun' 'masque' 'vless-reverse' )
        local proto_idx=0
        inquirer list_input_index "$(gettext "选择入站协议")" proto_options proto_idx
        local protocol="${proto_options[$proto_idx]}"
        local vless_reverse_mode=0
        if [ "$protocol" == "vless-reverse" ]
        then
            protocol="vless"
            vless_reverse_mode=1
        fi

        local cur_ver=""
        cur_ver=$(ProxyGetTargetVersion "xray")
        if [ "$protocol" == "tun" ] && ! ProxyCoreHasFeature "xray" "$cur_ver" "json" "tunInbound"
        then
            Println "$(eval_gettext "\$error Xray \${cur_ver} 不支持 tun 入站 (需要 >= 26.1.13)")\n"
            return 1
        elif [ "$protocol" == "hysteria" ] && ! ProxyCoreHasFeature "xray" "$cur_ver" "json" "hysteriaInbound"
        then
            Println "$(eval_gettext "\$error Xray \${cur_ver} 不支持 hysteria 入站 (需要 >= 26.3.23)")\n"
            return 1
        elif [ "$protocol" == "masque" ] && ! ProxyCoreHasFeature "xray" "$cur_ver" "json" "masque"
        then
            Println "$(eval_gettext "\$error Xray \${cur_ver} 不支持 masque 入站 (需要 >= 26.9.30)")\n"
            return 1
        fi

        local default_listen="0.0.0.0"
        local tag_prefix="${protocol}-"
        if [ "$mode_idx" -eq 1 ]
        then
            default_listen="127.0.0.1"
            tag_prefix="nginx-${protocol}-"
        fi

        local listen="" port="" tag=""
        if [ "$protocol" != "tun" ]
        then
            inquirer text_input "$(gettext "输入监听地址")" listen "$default_listen"
            inquirer text_input "$(gettext "输入监听端口 (留空随机)")" port ""
            if [ -z "$port" ]
            then
                port=$(GetFreePort)
            fi
            if [[ $port =~ ^[0-9]+$ ]]
            then
                if [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 监听端口必须在 1-65535 之间")\n"
                    return 1
                fi
            elif [[ ! $port =~ ^[0-9]+-[0-9]+$ ]]
            then
                Println "$(eval_gettext "\$error 监听端口格式无效 (应为端口或端口范围, 如 443 或 10000-20000)")\n"
                return 1
            fi
        fi
        inquirer text_input "$(gettext "输入入站标识 (留空随机)")" tag ""
        if [ -z "$tag" ]
        then
            tag=$(ProxyGetFreeTag "$X_CONFIG" "$tag_prefix")
        elif [ "$mode_idx" -eq 1 ] && [ "${tag:0:6}" != "nginx-" ]
        then
            tag="nginx-${tag}"
        fi

        local xray_bin
        xray_bin=$(XrayGetBin)

        local settings_json='{}'
        case "$protocol" in
            vless)
                local uuid flow email decryption
                inquirer text_input "$(gettext "输入用户 UUID (留空自动生成)")" uuid ""
                if [ -z "$uuid" ]
                then
                    if [ -n "$xray_bin" ]
                    then
                        uuid=$("$xray_bin" uuid 2> /dev/null | head -n 1 | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ] && command -v uuidgen > /dev/null 2>&1
                    then
                        uuid=$(uuidgen 2> /dev/null | tr '[:upper:]' '[:lower:]' | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ] && [ -r /proc/sys/kernel/random/uuid ]
                    then
                        uuid=$(cat /proc/sys/kernel/random/uuid | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ]
                    then
                        Println "$(eval_gettext "\$error 自动生成 UUID 失败, 请手动输入")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已自动生成 UUID: \${green}\${uuid}\${normal}")\n"
                fi
                inquirer text_input "$(gettext "输入流控 flow (如 xtls-rprx-vision, 可留空)")" flow ""
                inquirer text_input "$(gettext "输入用户 email (可留空)")" email ""
                inquirer text_input "$(gettext "输入 decryption")" decryption "none"
                local rev_tag="${XRAY_VLESS_REVERSE_TAG:-}"
                if [ "$vless_reverse_mode" -eq 1 ]
                then
                    inquirer text_input "$(gettext "输入 VLESS 内联反向代理 reverse.tag (可留空)")" rev_tag ""
                fi
                JQs build settings_json '{
                    "decryption": $decryption,
                    "users": [{"id": $id, "flow": $flow, "email": $email, "level": 0}]
                } + (if $rev_tag != "" then {"reverse": {"tag": $rev_tag}} else {} end)' \
                    --arg decryption "$decryption" --arg id "$uuid" --arg flow "$flow" --arg email "$email" --arg rev_tag "$rev_tag"
            ;;
            vmess)
                local uuid email
                inquirer text_input "$(gettext "输入用户 UUID (留空自动生成)")" uuid ""
                if [ -z "$uuid" ]
                then
                    if [ -n "$xray_bin" ]
                    then
                        uuid=$("$xray_bin" uuid 2> /dev/null | head -n 1 | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ] && command -v uuidgen > /dev/null 2>&1
                    then
                        uuid=$(uuidgen 2> /dev/null | tr '[:upper:]' '[:lower:]' | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ] && [ -r /proc/sys/kernel/random/uuid ]
                    then
                        uuid=$(cat /proc/sys/kernel/random/uuid | tr -d '\r\n')
                    fi
                    if [ -z "$uuid" ]
                    then
                        Println "$(eval_gettext "\$error 自动生成 UUID 失败, 请手动输入")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已自动生成 UUID: \${green}\${uuid}\${normal}")\n"
                fi
                inquirer text_input "$(gettext "输入用户 email (可留空)")" email ""
                JQs build settings_json '{
                    "users": [{"id": $id, "email": $email, "level": 0}]
                }' --arg id "$uuid" --arg email "$email"
            ;;
            trojan)
                local password email
                inquirer text_input "$i18n_input_password" password ""
                inquirer text_input "$(gettext "输入用户 email (可留空)")" email ""
                JQs build settings_json '{
                    "users": [{"password": $password, "email": $email, "level": 0}]
                }' --arg password "$password" --arg email "$email"
            ;;
            shadowsocks)
                local method password network email
                inquirer text_input "$(gettext "输入加密方式")" method "2022-blake3-aes-256-gcm"
                method=$(ProxyNormalizeSsMethod "$method")
                inquirer text_input "$(gettext "输入密钥 (SS2022 留空自动生成)")" password ""
                if [ -z "$password" ] && [[ "$method" == 2022-* ]]
                then
                    local ss_bytes=""
                    if ! ss_bytes=$(ProxySs2022KeyBytes "$method")
                    then
                        ss_bytes=32
                    fi
                    password=$(openssl rand -base64 "$ss_bytes" 2> /dev/null | tr -d '\r\n')
                    if [ -z "$password" ]
                    then
                        Println "$(eval_gettext "\$error 自动生成 SS2022 密钥失败, 请手动输入")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已自动生成 SS2022 密钥: \${green}\${password}\${normal}")\n"
                fi
                inquirer text_input "$(gettext "输入监听网络 (tcp/udp/tcp,udp)")" network "tcp,udp"
                inquirer text_input "$(gettext "输入用户 email (可留空)")" email ""
                JQs build settings_json '{
                    "method": $method,
                    "password": $password,
                    "network": $network,
                    "email": $email
                }' --arg method "$method" --arg password "$password" --arg network "$network" --arg email "$email"
            ;;
            socks)
                local auth_opts=( 'noauth' 'password' )
                local auth="" udp_idx=1 user="" pass=""
                local yn_opts=( "$i18n_no" "$i18n_yes" )
                inquirer list_input "$(gettext "选择认证方式 auth")" auth_opts auth
                inquirer list_input_index "$(gettext "开启 UDP 转发")" yn_opts udp_idx
                if [ "$auth" == "password" ]
                then
                    inquirer text_input "$(gettext "输入用户名")" user ""
                    inquirer text_input "$i18n_input_password" pass ""
                    JQs build settings_json '{
                        "auth": $auth,
                        "udp": ($udp == "1"),
                        "users": [{"user": $user, "pass": $pass}]
                    }' --arg auth "$auth" --arg udp "$udp_idx" --arg user "$user" --arg pass "$pass"
                else
                    JQs build settings_json '{
                        "auth": $auth,
                        "udp": ($udp == "1")
                    }' --arg auth "$auth" --arg udp "$udp_idx"
                fi
            ;;
            http)
                local user pass
                inquirer text_input "$(gettext "输入用户名 (留空无认证)")" user ""
                if [ -n "$user" ]
                then
                    inquirer text_input "$i18n_input_password" pass ""
                    JQs build settings_json '{
                        "users": [{"user": $user, "pass": $pass}]
                    }' --arg user "$user" --arg pass "$pass"
                fi
            ;;
            tunnel)
                local rw_addr rw_port allowed_net fr_idx=0
                local yn_opts=( "$i18n_no" "$i18n_yes" )
                inquirer text_input "$(gettext "输入目标转发地址")" rw_addr "127.0.0.1"
                inquirer text_input "$(gettext "输入目标转发端口")" rw_port "8080"
                if [[ ! $rw_port =~ ^[0-9]+$ ]] || [ "$rw_port" -lt 1 ] || [ "$rw_port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 目标转发端口必须为 1-65535 的整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "输入允许网络 (tcp/udp/tcp,udp)")" allowed_net "tcp"
                inquirer list_input_index "$(gettext "启用 followRedirect")" yn_opts fr_idx
                JQs build settings_json '{
                    "rewriteAddress": $addr,
                    "rewritePort": ($port | tonumber),
                    "allowedNetwork": $net,
                    "followRedirect": ($fr == "1")
                }' --arg addr "$rw_addr" --arg port "$rw_port" --arg net "$allowed_net" --arg fr "$fr_idx"
            ;;
            hysteria)
                local auth email
                inquirer text_input "$(gettext "输入认证密钥 auth")" auth ""
                inquirer text_input "$(gettext "输入用户 email (可留空)")" email ""
                JQs build settings_json '{
                    "version": 2,
                    "users": [{"auth": $auth, "email": $email, "level": 0}]
                }' --arg auth "$auth" --arg email "$email"
            ;;
            wireguard)
                local secret_key peer_pub allowed_ip mtu
                inquirer text_input "$(gettext "输入服务端 secretKey (留空自动生成)")" secret_key ""
                if [ -z "$secret_key" ]
                then
                    if [ -n "$xray_bin" ]
                    then
                        local wg_out wg_pub=""
                        wg_out=$("$xray_bin" wg 2> /dev/null)
                        secret_key=$(printf '%s\n' "$wg_out" | ProxyExtractXrayPrivKey | tr -d '\r\n ')
                        wg_pub=$(printf '%s\n' "$wg_out" | ProxyExtractXrayPubKey | tr -d '\r\n ')
                        if [ -n "$secret_key" ]
                        then
                            Println "$(eval_gettext "\$info 已自动生成 WireGuard secretKey: \${green}\${secret_key}\${normal}")\n"
                            if [ -n "$wg_pub" ]
                            then
                                Println "$(eval_gettext "\$info 对应服务端 publicKey: \${green}\${wg_pub}\${normal}")\n"
                            fi
                        fi
                    fi
                    if [ -z "$secret_key" ]
                    then
                        Println "$(eval_gettext "\$error 自动生成 WireGuard secretKey 失败, 请手动输入")\n"
                        return 1
                    fi
                fi
                inquirer text_input "$(gettext "输入对端 publicKey")" peer_pub ""
                inquirer text_input "$(gettext "输入 allowedIPs (逗号分隔)")" allowed_ip "10.0.0.2/32"
                inquirer text_input "$(gettext "输入 MTU")" mtu "1420"
                if [[ ! $mtu =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error MTU 必须为正整数")\n"
                    return 1
                fi
                JQs build settings_json '{
                    "secretKey": $sk,
                    "mtu": ($mtu | tonumber),
                    "peers": [{"publicKey": $pk, "allowedIPs": ($ips | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0)))}]
                }' --arg sk "$secret_key" --arg mtu "$mtu" --arg pk "$peer_pub" --arg ips "$allowed_ip"
            ;;
            tun)
                local tun_name tun_mtu tun_gw tun_dns tun_auto_iface tun_auto_table
                inquirer text_input "$(gettext "TUN 网卡名称")" tun_name "xray0"
                inquirer text_input "MTU" tun_mtu "1500"
                if [[ ! $tun_mtu =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error MTU 必须为正整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "gateway (逗号分隔, 可留空)")" tun_gw ""
                inquirer text_input "$(gettext "dns (逗号分隔, 可留空)")" tun_dns ""
                inquirer text_input "$(gettext "autoOutboundsInterface (如 auto 或网卡名, 可留空)")" tun_auto_iface ""
                inquirer text_input "$(gettext "autoSystemRoutingTable (路由表编号, 可留空)")" tun_auto_table ""
                if [ -n "$tun_auto_table" ] && [[ ! $tun_auto_table =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error autoSystemRoutingTable 必须为非负整数")\n"
                    return 1
                fi
                JQs build settings_json '{
                    "name": $name,
                    "mtu": ($mtu | tonumber),
                    "gateway": (if $gw != "" then ($gw | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                    "dns": (if $dns != "" then ($dns | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                    "autoOutboundsInterface": (if $iface != "" then $iface else null end),
                    "autoSystemRoutingTable": (if $rt != "" then ($rt | tonumber) else null end)
                }' --arg name "$tun_name" --arg mtu "$tun_mtu" --arg gw "$tun_gw" --arg dns "$tun_dns" --arg iface "$tun_auto_iface" --arg rt "$tun_auto_table"
            ;;
            masque)
                local m_addr m_mtu m_pass m_email
                inquirer text_input "$(gettext "MASQUE address (逗号分隔)")" m_addr "10.0.0.1/24"
                inquirer text_input "MTU" m_mtu "1280"
                if [[ ! $m_mtu =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error MTU 必须为正整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "用户 pass")" m_pass ""
                inquirer text_input "$(gettext "用户 email (必填, 不能包含 :)")" m_email ""
                if [ -z "$m_email" ] || [[ "$m_email" == *:* ]]
                then
                    Println "$(eval_gettext "\$error MASQUE 用户 email 必填且不能包含 :")\n"
                    return 1
                fi
                JQs build settings_json '{
                    "address": ($addr | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                    "mtu": ($mtu | tonumber),
                    "users": [{"pass": $pass, "email": $email, "level": 0}]
                }' --arg addr "$m_addr" --arg mtu "$m_mtu" --arg pass "$m_pass" --arg email "$m_email"
            ;;
        esac

        local network="" security=""
        if [ "$protocol" == "tun" ] || [ "$protocol" == "wireguard" ]
        then
            network=""
            security=""
        elif [ "$protocol" == "masque" ]
        then
            network="masque"
            security="tls"
        elif [ "$protocol" == "hysteria" ]
        then
            network="hysteria"
            security="tls"
        else
            local net_options=( 'raw' 'xhttp' 'ws' 'grpc' 'httpupgrade' 'kcp' 'hysteria' )
            local net_idx=0
            inquirer list_input_index "$(gettext "选择传输方式")" net_options net_idx
            network="${net_options[$net_idx]}"

            if [ "$network" == "hysteria" ]
            then
                security="tls"
            elif [ "$network" == "raw" ] || [ "$network" == "xhttp" ] || [ "$network" == "grpc" ]
            then
                local sec_options=( 'none' 'tls' 'reality' )
                local sec_idx=0
                inquirer list_input_index "$(gettext "选择传输安全")" sec_options sec_idx
                security="${sec_options[$sec_idx]}"
            else
                local sec_options=( 'none' 'tls' )
                local sec_idx=0
                inquirer list_input_index "$(gettext "选择传输安全")" sec_options sec_idx
                security="${sec_options[$sec_idx]}"
            fi
        fi

        if [ "$security" == "reality" ] && [ "$network" != "raw" ] && [ "$network" != "xhttp" ] && [ "$network" != "grpc" ]
        then
            Println "$(eval_gettext "\$tip REALITY 仅支持 raw/xhttp/grpc, 已自动回退为 tls")\n"
            security="tls"
        fi

        local xhttp_host="" xhttp_path="" xhttp_mode=""
        local ws_path="" ws_host="" grpc_svc="" hu_path="" hu_host=""
        local tls_sni="" tls_cert="" tls_key=""
        local r_target="" r_sni="" r_pk="" r_sid=""

        case "$network" in
            xhttp)
                inquirer text_input "$(gettext "XHTTP host (可留空)")" xhttp_host ""
                inquirer text_input "XHTTP path" xhttp_path "/"
                local xm_opts=( 'auto' 'packet-up' 'stream-up' 'stream-one' )
                inquirer list_input "$(gettext "选择 XHTTP mode")" xm_opts xhttp_mode
            ;;
            ws)
                inquirer text_input "WebSocket path" ws_path "/"
                inquirer text_input "$(gettext "WebSocket host (可留空)")" ws_host ""
            ;;
            grpc)
                inquirer text_input "gRPC serviceName" grpc_svc ""
            ;;
            httpupgrade)
                inquirer text_input "HTTPUpgrade path" hu_path "/"
                inquirer text_input "$(gettext "HTTPUpgrade host (可留空)")" hu_host ""
            ;;
        esac

        if [ "$security" == "tls" ]
        then
            inquirer text_input "$(gettext "TLS serverName (可留空)")" tls_sni ""
            inquirer text_input "$(gettext "证书文件路径 certificateFile")" tls_cert ""
            inquirer text_input "$(gettext "私钥文件路径 keyFile")" tls_key ""
        elif [ "$security" == "reality" ]
        then
            inquirer text_input "$(gettext "REALITY target (如 www.example.com:443)")" r_target ""
            inquirer text_input "$(gettext "REALITY serverNames (逗号分隔)")" r_sni ""
            inquirer text_input "$(gettext "REALITY privateKey (留空自动生成)")" r_pk ""
            if [ -z "$r_pk" ]
            then
                if [ -n "$xray_bin" ]
                then
                    local x25519_out r_pub=""
                    x25519_out=$("$xray_bin" x25519 2> /dev/null)
                    r_pk=$(printf '%s\n' "$x25519_out" | ProxyExtractXrayPrivKey | tr -d '\r\n ')
                    r_pub=$(printf '%s\n' "$x25519_out" | ProxyExtractXrayPubKey | tr -d '\r\n ')
                    if [ -n "$r_pk" ]
                    then
                        Println "$(eval_gettext "\$info 已自动生成 REALITY privateKey: \${green}\${r_pk}\${normal}")\n"
                        if [ -n "$r_pub" ]
                        then
                            Println "$(eval_gettext "\$info 对应客户端公钥 (Password/PublicKey): \${green}\${r_pub}\${normal}")\n"
                        fi
                    fi
                fi
                if [ -z "$r_pk" ]
                then
                    Println "$(eval_gettext "\$error 自动生成 REALITY privateKey 失败, 请手动输入")\n"
                    return 1
                fi
            fi
            inquirer text_input "$(gettext "REALITY shortIds (逗号分隔, 留空默认为 [\"\"])")" r_sid ""
        fi

        local yn_opts=( "$i18n_no" "$i18n_yes" )
        local sniff_idx=1 route_only_idx=0
        inquirer list_input_index "$(gettext "开启流量探测 sniffing")" yn_opts sniff_idx
        if [ "$sniff_idx" -eq 1 ]
        then
            inquirer list_input_index "$(gettext "嗅探域名仅用于路由 routeOnly")" yn_opts route_only_idx
        fi

        local inbound_json=""
        JQs build inbound_json '{
            "listen": $listen,
            "port": (if ($port | test("^[0-9]+$")) then ($port | tonumber) else $port end),
            "protocol": $protocol,
            "tag": $tag,
            "settings": $settings,
            "streamSettings": {
                "network": $network,
                "security": $security,
                "xhttpSettings": (if $network == "xhttp" then {"host": $xh_host, "path": $xh_path, "mode": $xh_mode} else null end),
                "wsSettings": (if $network == "ws" then {"path": $ws_path, "host": $ws_host} else null end),
                "grpcSettings": (if $network == "grpc" then {"serviceName": $grpc_svc} else null end),
                "httpupgradeSettings": (if $network == "httpupgrade" then {"path": $hu_path, "host": $hu_host} else null end),
                "hysteriaSettings": (if $network == "hysteria" then {"version": 2} else null end),
                "tlsSettings": (if $security == "tls" then {
                    "serverName": $tls_sni,
                    "certificates": (if $tls_cert != "" then [{"certificateFile": $tls_cert, "keyFile": $tls_key}] else [] end)
                } else null end),
                "realitySettings": (if $security == "reality" then {
                    "target": $r_target,
                    "serverNames": (if $r_sni != "" then ($r_sni | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else [] end),
                    "privateKey": $r_pk
                } else null end)
            },
            "sniffing": {
                "enabled": ($sniff == "1"),
                "destOverride": (if $sniff == "1" then ["http", "tls", "quic"] else [] end),
                "routeOnly": ($route_only == "1")
            }
        }' \
            --arg listen "$listen" \
            --arg port "$port" \
            --arg protocol "$protocol" \
            --arg tag "$tag" \
            --argjson settings "$settings_json" \
            --arg network "$network" \
            --arg security "$security" \
            --arg xh_host "$xhttp_host" \
            --arg xh_path "$xhttp_path" \
            --arg xh_mode "$xhttp_mode" \
            --arg ws_path "$ws_path" \
            --arg ws_host "$ws_host" \
            --arg grpc_svc "$grpc_svc" \
            --arg hu_path "$hu_path" \
            --arg hu_host "$hu_host" \
            --arg tls_sni "$tls_sni" \
            --arg tls_cert "$tls_cert" \
            --arg tls_key "$tls_key" \
            --arg r_target "$r_target" \
            --arg r_sni "$r_sni" \
            --arg r_pk "$r_pk" \
            --arg sniff "$sniff_idx" \
            --arg route_only "$route_only_idx"

        if [ "$security" == "reality" ]
        then
            inbound_json=$($JQ_FILE -c --arg r_sid "$r_sid" '
                .streamSettings.realitySettings = (.streamSettings.realitySettings // {})
                | .streamSettings.realitySettings.shortIds = (
                    if $r_sid == "" then
                        [""]
                    else
                        ($r_sid | split(",") | map(gsub("^\\s+|\\s+$"; "")))
                    end
                )
            ' <<< "$inbound_json")
        fi

        if [ "$network" == "masque" ]
        then
            inbound_json=$($JQ_FILE -c '
                .streamSettings.masqueSettings = (.streamSettings.masqueSettings // {})
            ' <<< "$inbound_json")
        fi

        local target_ver=""
        target_ver=$(ProxyGetTargetVersion "xray")
        local has_users=0 has_method=0 has_rewrite=0
        ProxyCoreHasFeature "xray" "$target_ver" "json" "inboundUsersKey" && has_users=1
        ProxyCoreHasFeature "xray" "$target_ver" "json" "streamMethodKey" && has_method=1
        ProxyCoreHasFeature "xray" "$target_ver" "json" "dnsRewriteKeys" && has_rewrite=1

        inbound_json=$($JQ_FILE -c \
            --arg proto "$protocol" \
            --argjson has_users "$has_users" \
            --argjson has_method "$has_method" \
            --argjson has_rewrite "$has_rewrite" '
            if $proto == "tun" then
                del(.listen, .port, .streamSettings)
            elif $proto == "wireguard" then
                del(.streamSettings)
            else . end
            | if (.settings | type) == "object" and ($proto == "vless" or $proto == "vmess" or $proto == "trojan" or $proto == "hysteria" or $proto == "shadowsocks") then
                ((.settings.users // .settings.clients) // null) as $u
                | if $u == null then .
                  elif $has_users == 1 then .settings |= (del(.clients) | .users = $u)
                  else .settings |= (del(.users) | .clients = $u) end
              elif (.settings | type) == "object" and ($proto == "socks" or $proto == "http") then
                ((.settings.users // .settings.accounts) // null) as $u
                | if $u == null then .
                  elif $has_users == 1 then .settings |= (del(.accounts) | .users = $u)
                  else .settings |= (del(.users) | .accounts = $u) end
              elif (.settings | type) == "object" and ($proto == "tunnel" or $proto == "dokodemo-door") then
                if $has_rewrite == 1 then
                    .settings |= (
                        (if has("address") then (if has("rewriteAddress") | not then .rewriteAddress = .address else . end) | del(.address) else . end)
                        | (if has("port") then (if has("rewritePort") | not then .rewritePort = .port else . end) | del(.port) else . end)
                        | (if has("network") then (if has("allowedNetwork") | not then .allowedNetwork = .network else . end) | del(.network) else . end)
                    )
                else
                    .settings |= (
                        (if has("rewriteAddress") then .address = .rewriteAddress | del(.rewriteAddress) else . end)
                        | (if has("rewritePort") then .port = .rewritePort | del(.rewritePort) else . end)
                        | (if has("allowedNetwork") then .network = .allowedNetwork | del(.allowedNetwork) else . end)
                    )
                end
              else . end
            | if (.streamSettings | type) == "object" then
                (.streamSettings.method // .streamSettings.network // null) as $m
                | if $m == null then .
                  elif $has_method == 1 then .streamSettings |= (del(.network) | .method = $m)
                  else .streamSettings |= (del(.method) | .network = $m) end
              else . end
        ' <<< "$inbound_json")

        if ! ProxyAddBound "$X_CONFIG" inbounds "$inbound_json"
        then
            local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
            Println "$(eval_gettext "\$error 添加 Xray 入站 \${tag} 失败: \$err_detail")\n"
            return 1
        fi
        Println "$(eval_gettext "\$info 已添加 Xray 入站 \${green}\${tag}\${normal} (\${protocol})")\n"
    }
    XrayDeleteInbound()
    {
        ProxySelectBound "$X_CONFIG" inbounds "$(gettext "选择要删除的入站")" || return 1
        local target_tag="${inbounds_tag[selected_bound_index]}"

        if ! ProxyDeleteBound "$X_CONFIG" inbounds "$selected_bound_index"
        then
            local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
            Println "$(eval_gettext "\$error 删除入站 \${target_tag} 失败: \$err_detail")\n"
            return 1
        fi

        Println "$(eval_gettext "\$info 已删除入站 \${green}\${target_tag}\${normal}")\n"
    }
    XrayGenUuid()
    {
        local xray_bin=""
        xray_bin=$(ProxyDetectCoreBin "xray")

        local gen=""
        if [ -n "$xray_bin" ] && [ -x "$xray_bin" ]
        then
            gen=$("$xray_bin" uuid 2> /dev/null | head -n 1 | tr -d '\r\n')
        fi
        if [ -z "$gen" ] && command -v uuidgen > /dev/null 2>&1
        then
            gen=$(uuidgen 2> /dev/null | tr '[:upper:]' '[:lower:]' | tr -d '\r\n')
        fi
        if [ -z "$gen" ] && [ -r /proc/sys/kernel/random/uuid ]
        then
            gen=$(cat /proc/sys/kernel/random/uuid | tr -d '\r\n')
        fi
        printf '%s' "$gen"
    }

    XrayGenSs2022Key()
    {
        local method="$1"
        local bytes=""
        if ! bytes=$(ProxySs2022KeyBytes "$method")
        then
            return 1
        fi

        openssl rand -base64 "$bytes" 2> /dev/null | tr -d '\r\n'
    }

    XrayAddInboundAccount()
    {
        ProxySelectBound "$X_CONFIG" inbounds "$(gettext "选择要添加账号的入站")" || return 1
        local idx="$selected_bound_index"
        local bound_tag="${inbounds_tag[idx]}"
        local protocol="${inbounds_protocol[idx]}"
        local user_json=""
        local target_ver=""
        target_ver=$(ProxyGetTargetVersion "xray")
        local acc_key=""

        if [ "$protocol" == "wireguard" ]
        then
            acc_key="peers"
        else
            acc_key=$(ProxyXrayInboundUserKey "$protocol" "$target_ver")
        fi

        case "$protocol" in
            vless)
                local uuid flow email
                inquirer text_input "$(gettext "输入用户 UUID (留空自动生成)")" uuid ""
                if [ -z "$uuid" ]
                then
                    uuid=$(XrayGenUuid)
                    if [ -z "$uuid" ]
                    then
                        Println "$(eval_gettext "\$error 自动生成 UUID 失败, 请手动输入")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已自动生成 UUID: \${green}\${uuid}\${normal}")\n"
                fi
                inquirer text_input "$(gettext "输入 flow (可留空)")" flow ""
                inquirer text_input "$(gettext "输入 email (可留空)")" email ""
                JQs build user_json '{"id": $id, "flow": $flow, "email": $email, "level": 0}' \
                    --arg id "$uuid" --arg flow "$flow" --arg email "$email"
            ;;
            vmess)
                local uuid email
                inquirer text_input "$(gettext "输入用户 UUID (留空自动生成)")" uuid ""
                if [ -z "$uuid" ]
                then
                    uuid=$(XrayGenUuid)
                    if [ -z "$uuid" ]
                    then
                        Println "$(eval_gettext "\$error 自动生成 UUID 失败, 请手动输入")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已自动生成 UUID: \${green}\${uuid}\${normal}")\n"
                fi
                inquirer text_input "$(gettext "输入 email (可留空)")" email ""
                JQs build user_json '{"id": $id, "email": $email, "level": 0}' \
                    --arg id "$uuid" --arg email "$email"
            ;;
            trojan)
                local password email
                inquirer text_input "$i18n_input_password" password ""
                inquirer text_input "$(gettext "输入 email (可留空)")" email ""
                JQs build user_json '{"password": $pw, "email": $email, "level": 0}' \
                    --arg pw "$password" --arg email "$email"
            ;;
            shadowsocks)
                local inb_method="" inb_psk=""
                SetDelimiters
                IFS="$field_sep" read -r inb_method inb_psk < <(JQs query "$X_CONFIG" '
                    if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                        and (.inbounds[$i].settings | type) == "object"
                    then [(.inbounds[$i].settings.method // "" | tostring), (.inbounds[$i].settings.password // "" | tostring)] | join($sep)
                    else $sep end
                ' --argjson i "$idx" --arg sep "$field_sep")
                inb_method=$(ProxyNormalizeSsMethod "$inb_method")
                local ss_rc=0
                ProxyValidateXraySsMultiUser "$inb_method" "$inb_psk" || ss_rc=$?
                if [ "$ss_rc" -eq 2 ]
                then
                    Println "$(eval_gettext "\$error 2022-blake3-chacha20-poly1305 不支持多用户入站")\n"
                    return 1
                elif [ "$ss_rc" -eq 3 ]
                then
                    Println "$(eval_gettext "\$error SS-2022 多用户入站缺少顶层服务端 password PSK")\n"
                    return 1
                fi
                local password email user_method=""
                if [[ "$inb_method" == 2022-* ]]
                then
                    inquirer text_input "$(gettext "输入密钥 (SS2022 留空自动生成)")" password ""
                    if [ -z "$password" ]
                    then
                        password=$(XrayGenSs2022Key "$inb_method")
                        if [ -z "$password" ]
                        then
                            Println "$(eval_gettext "\$error 自动生成 SS2022 密钥失败, 请手动输入")\n"
                            return 1
                        fi
                        Println "$(eval_gettext "\$info 已自动生成 SS2022 密钥: \${green}\${password}\${normal}")\n"
                    fi
                    inquirer text_input "$(gettext "输入 email (可留空)")" email ""
                    JQs build user_json '{"password": $pw, "email": $email, "level": 0}' \
                        --arg pw "$password" --arg email "$email"
                else
                    inquirer text_input "$(gettext "输入用户加密方式 method")" user_method "${inb_method:-aes-256-gcm}"
                    user_method=$(ProxyNormalizeSsMethod "$user_method")
                    inquirer text_input "$i18n_input_password" password ""
                    inquirer text_input "$(gettext "输入 email (可留空)")" email ""
                    JQs build user_json '{"method": $method, "password": $pw, "email": $email, "level": 0}' \
                        --arg method "$user_method" --arg pw "$password" --arg email "$email"
                fi
            ;;
            socks|http)
                local user pass
                inquirer text_input "$(gettext "输入用户名")" user ""
                inquirer text_input "$i18n_input_password" pass ""
                JQs build user_json '{"user": $user, "pass": $pass}' \
                    --arg user "$user" --arg pass "$pass"
            ;;
            hysteria)
                local auth email
                inquirer text_input "$(gettext "输入认证密钥 auth")" auth ""
                inquirer text_input "$(gettext "输入 email (可留空)")" email ""
                JQs build user_json '{"auth": $auth, "email": $email, "level": 0}' \
                    --arg auth "$auth" --arg email "$email"
            ;;
            masque)
                local pass email
                inquirer text_input "$(gettext "输入用户 pass")" pass ""
                inquirer text_input "$(gettext "输入用户 email (必填, 不能包含 :)")" email ""
                if [ -z "$email" ] || [[ "$email" == *:* ]]
                then
                    Println "$(eval_gettext "\$error MASQUE 用户 email 必填且不能包含 :")\n"
                    return 1
                fi
                JQs build user_json '{"pass": $pass, "email": $email, "level": 0}' \
                    --arg pass "$pass" --arg email "$email"
            ;;
            wireguard)
                local pk allowed_ips psk
                inquirer text_input "$(gettext "输入对端 publicKey")" pk ""
                inquirer text_input "$(gettext "输入 allowedIPs (逗号分隔)")" allowed_ips "10.0.0.2/32"
                inquirer text_input "$(gettext "输入 preSharedKey (可留空)")" psk ""
                JQs build user_json '{
                    "publicKey": $pk,
                    "allowedIPs": ($ips | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                    "preSharedKey": $psk
                }' --arg pk "$pk" --arg ips "$allowed_ips" --arg psk "$psk"
            ;;
            *)
                Println "$(eval_gettext "\$error 协议 \${protocol} 不支持多账号管理")\n"
                return 1
            ;;
        esac

        if ! ProxyMutateConfigTx "xray" '
            def arr($x): if ($x | type) == "array" then $x else [] end;
            def pick_list($a; $b; $c):
                if (arr($a) | length) > 0 then arr($a)
                elif (arr($b) | length) > 0 then arr($b)
                elif (arr($c) | length) > 0 then arr($c)
                else [] end;
            .inbounds[$i].settings |= (
                (if $proto == "shadowsocks" and ((.method // "") | ascii_downcase | startswith("2022-") | not)
                    and ((.password // "") != "")
                    and ((pick_list(.users; .clients; .accounts) | length) == 0)
                 then
                    .[$k] = [{method: ((.method // "aes-256-gcm") | ascii_downcase), password: .password, email: (.email // ""), level: (.level // 0)}]
                    | del(.password, .email)
                 else . end)
                | (if $k == "users" then
                    .users = (pick_list(.users; .clients; .accounts) + [$u])
                    | del(.clients, .accounts)
                   elif $k == "clients" then
                    .clients = (pick_list(.clients; .users; null) + [$u])
                    | del(.users)
                   elif $k == "accounts" then
                    .accounts = (pick_list(.accounts; .users; null) + [$u])
                    | del(.users)
                   else
                    .[$k] = (arr(.[$k]) + [$u])
                   end)
            )
        ' --argjson i "$idx" --arg k "$acc_key" --arg proto "$protocol" --argjson u "$user_json"
        then
            local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
            Println "$(eval_gettext "\$error 向入站 \${bound_tag} 添加账号失败: \$err_detail")\n"
            return 1
        fi
        Println "$(eval_gettext "\$info 已向入站 \${green}\${bound_tag}\${normal} 添加账号")\n"
    }

    XrayDeleteInboundAccount()
    {
        ProxySelectBound "$X_CONFIG" inbounds "$(gettext "选择要删除账号的入站")" || return 1
        local idx="$selected_bound_index"
        local acc_key
        acc_key=$(JQs query "$X_CONFIG" '
            if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                and (.inbounds[$i].settings | type) == "object"
            then
                if (.inbounds[$i].settings.peers | type) == "array" and (.inbounds[$i].settings.peers | length) > 0 then "peers"
                elif (.inbounds[$i].settings.users | type) == "array" and (.inbounds[$i].settings.users | length) > 0 then "users"
                elif (.inbounds[$i].settings.clients | type) == "array" and (.inbounds[$i].settings.clients | length) > 0 then "clients"
                elif (.inbounds[$i].settings.accounts | type) == "array" and (.inbounds[$i].settings.accounts | length) > 0 then "accounts"
                else "" end
            else "" end
        ' --argjson i "$idx")

        if [ -z "$acc_key" ]
        then
            Println "$(eval_gettext "\$error 该入站没有可删除的账号")\n"
            return 1
        fi

        local user_options=()
        local line
        while IFS= read -r line
        do
            [ -n "$line" ] && user_options+=("$line")
        done < <(JQs query "$X_CONFIG" '
            (if (.inbounds | type) == "array" and (.inbounds[$i] | type) == "object"
                and (.inbounds[$i].settings | type) == "object"
                and (.inbounds[$i].settings[$k] | type) == "array"
             then .inbounds[$i].settings[$k]
             else [] end)
            | to_entries[]
            | select(.value | type == "object")
            | "\(.key + 1). \(.value.email // .value.id // .value.user // .value.publicKey // .value.password // .value.pass // .value.auth // "user")"
        ' --argjson i "$idx" --arg k "$acc_key")

        if [ "${#user_options[@]}" -eq 0 ]
        then
            Println "$(eval_gettext "\$error 该入站没有可删除的账号")\n"
            return 1
        fi

        local user_idx=0
        echo
        inquirer list_input_index "$(gettext "选择要删除的账号")" user_options user_idx
        if ! ProxyMutateConfigTx "xray" 'del(.inbounds[$i].settings[$k][$u])' \
            --argjson i "$idx" --arg k "$acc_key" --argjson u "$user_idx"
        then
            local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
            Println "$(eval_gettext "\$error 删除账号失败: \$err_detail")\n"
            return 1
        fi
        local del_user="${user_options[user_idx]}"
        Println "$(eval_gettext "\$info 已删除账号 \${green}\${del_user}\${normal}")\n"
    }
    XrayGetOutbounds()
    {
        ProxyLoadOutboundsIndex "$X_CONFIG"
    }
    XrayListOutbounds()
    {
        XrayGetOutbounds

        if [ "$outbounds_count" -eq 0 ]
        then
            Println "$(eval_gettext "\$error 没有出站")\n"
            return 1
        fi

        Println "\n$(eval_gettext "=== 出站数 \${green} \$outbounds_count \${normal}")"
        outbounds_list=$(ProxyRenderOutbounds "$X_CONFIG" xray)
        Println "$outbounds_list"
    }
    XrayListOutboundAccounts()
    {
        XrayListOutbounds || return 1

        ProxySelectBound "$X_CONFIG" outbounds "$(gettext "选择查看账号/服务端明细的出站")" || return 0
        local idx="$selected_bound_index"
        local bound_tag="${outbounds_tag[idx]}"
        local accounts_out
        accounts_out=$(ProxyRenderOutboundAccounts "$X_CONFIG" "$idx")

        if [ -z "$accounts_out" ]
        then
            Println "$(eval_gettext "\$info 出站 \${green}\${bound_tag}\${normal} 没有账号/服务端明细")\n"
            return 0
        fi

        Println "\n$(eval_gettext "=== 出站 \${green}\${bound_tag}\${normal} 账号/服务端明细 ===")\n$accounts_out\n"
    }
    XrayAddOutbound()
    {
        local proto_options=( 'freedom' 'blackhole' 'dns' 'vless' 'vmess' 'trojan' 'shadowsocks' 'socks' 'http' 'loopback' 'hysteria' 'wireguard' 'masque' 'vless-reverse' )
        local proto_idx=0
        echo
        inquirer list_input_index "$(gettext "选择出站协议")" proto_options proto_idx
        local protocol="${proto_options[$proto_idx]}"
        local vless_reverse_mode=0
        if [ "$protocol" == "vless-reverse" ]
        then
            protocol="vless"
            vless_reverse_mode=1
        fi

        local cur_ver=""
        cur_ver=$(ProxyGetTargetVersion "xray")
        if [ "$protocol" == "hysteria" ] && ! ProxyCoreHasFeature "xray" "$cur_ver" "json" "hysteriaOutbound"
        then
            Println "$(eval_gettext "\$error Xray \${cur_ver} 不支持 hysteria 出站 (需要 >= 26.1.13)")\n"
            return 1
        elif [ "$protocol" == "masque" ] && ! ProxyCoreHasFeature "xray" "$cur_ver" "json" "masque"
        then
            Println "$(eval_gettext "\$error Xray \${cur_ver} 不支持 masque 出站 (需要 >= 26.9.30)")\n"
            return 1
        fi

        local tag send_through target_strategy="" dialer_proxy
        inquirer text_input "$(gettext "输入出站标识 (留空随机)")" tag ""
        if [ -z "$tag" ]
        then
            tag=$(ProxyGetFreeTag "$X_CONFIG" "${protocol}-out-")
        fi
        inquirer text_input "$(gettext "输入 sendThrough (可留空)")" send_through ""
        if [ "$protocol" != "freedom" ]
        then
            inquirer text_input "$(gettext "输入 targetStrategy (AsIs/UseIP/UseIPv4/UseIPv6, 可留空)")" target_strategy ""
        fi
        inquirer text_input "$(gettext "输入前置代理 sockopt.dialerProxy (可留空)")" dialer_proxy ""

        local settings_json='{}'
        local hy_auth=""
        case "$protocol" in
            freedom)
                local redirect proxy_proto final_rules_raw="" final_rules_json="null"
                inquirer text_input "$(gettext "输入 redirect (可留空)")" redirect ""
                inquirer text_input "$(gettext "输入 proxyProtocol (0/1/2, 可留空)")" proxy_proto ""
                if [ -n "$proxy_proto" ] && [[ ! $proxy_proto =~ ^[0-2]$ ]]
                then
                    Println "$(eval_gettext "\$error proxyProtocol 必须为 0、1 或 2")\n"
                    return 1
                fi
                if ProxyCoreHasFeature "xray" "$cur_ver" "json" "freedomFinalRules"
                then
                    inquirer text_input "$(gettext "输入 finalRules JSON 数组 (可留空)")" final_rules_raw ""
                    if [ -n "$final_rules_raw" ]
                    then
                        if ! final_rules_json=$(printf '%s\n' "$final_rules_raw" | $JQ_FILE -ce 'if type == "array" then . else error("not array") end' 2> /dev/null)
                        then
                            Println "$(eval_gettext "\$error finalRules 必须为合法的 JSON 数组")\n"
                            return 1
                        fi
                    fi
                fi
                JQs build settings_json '{
                    "redirect": $redirect,
                    "proxyProtocol": (if $pp != "" then ($pp | tonumber) else null end),
                    "finalRules": $fr
                }' --arg redirect "$redirect" --arg pp "$proxy_proto" --argjson fr "$final_rules_json"
            ;;
            blackhole)
                local resp_type
                inquirer text_input "$(gettext "响应类型 (none/http)")" resp_type "none"
                JQs build settings_json '{"response": {"type": $rt}}' --arg rt "$resp_type"
            ;;
            dns)
                local rw_net rw_addr rw_port
                inquirer text_input "$(gettext "rewriteNetwork (tcp/udp, 可留空)")" rw_net ""
                inquirer text_input "$(gettext "rewriteAddress (可留空)")" rw_addr ""
                inquirer text_input "$(gettext "rewritePort (可留空)")" rw_port ""
                if [ -n "$rw_port" ] && ([[ ! $rw_port =~ ^[0-9]+$ ]] || [ "$rw_port" -lt 1 ] || [ "$rw_port" -gt 65535 ])
                then
                    Println "$(eval_gettext "\$error rewritePort 必须为 1-65535 的整数")\n"
                    return 1
                fi
                JQs build settings_json '{
                    "rewriteNetwork": $net,
                    "rewriteAddress": $addr,
                    "rewritePort": (if $port != "" then ($port | tonumber) else null end)
                }' --arg net "$rw_net" --arg addr "$rw_addr" --arg port "$rw_port"
            ;;
            vless)
                local addr port uuid encryption flow
                inquirer text_input "$(gettext "服务端地址 address")" addr ""
                inquirer text_input "$(gettext "服务端端口 port")" port "443"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 服务端端口必须为 1-65535 的整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "用户 UUID")" uuid ""
                inquirer text_input "encryption" encryption "none"
                inquirer text_input "$(gettext "flow (可留空)")" flow ""
                local rev_tag="${XRAY_VLESS_REVERSE_TAG:-}"
                if [ "$vless_reverse_mode" -eq 1 ]
                then
                    inquirer text_input "$(gettext "输入 VLESS 内联反向代理 reverse.tag (可留空)")" rev_tag ""
                fi
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "id": $id,
                    "encryption": $enc,
                    "flow": $flow
                } + (if $rev_tag != "" then {"reverse": {"tag": $rev_tag}} else {} end)' \
                    --arg addr "$addr" --arg port "$port" --arg id "$uuid" --arg enc "$encryption" --arg flow "$flow" --arg rev_tag "$rev_tag"
            ;;
            vmess)
                local addr port uuid sec
                inquirer text_input "$(gettext "服务端地址 address")" addr ""
                inquirer text_input "$(gettext "服务端端口 port")" port "443"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 服务端端口必须为 1-65535 的整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "用户 UUID")" uuid ""
                inquirer text_input "security (auto/aes-128-gcm/chacha20-poly1305)" sec "auto"
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "id": $id,
                    "security": $sec
                }' --arg addr "$addr" --arg port "$port" --arg id "$uuid" --arg sec "$sec"
            ;;
            trojan)
                local addr port password
                inquirer text_input "$(gettext "服务端地址 address")" addr ""
                inquirer text_input "$(gettext "服务端端口 port")" port "443"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 服务端端口必须为 1-65535 的整数")\n"
                    return 1
                fi
                inquirer text_input "$i18n_password" password ""
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "password": $pw
                }' --arg addr "$addr" --arg port "$port" --arg pw "$password"
            ;;
            shadowsocks)
                local addr port method password
                inquirer text_input "$(gettext "服务端地址 address")" addr ""
                inquirer text_input "$(gettext "服务端端口 port")" port "8388"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 服务端端口必须为 1-65535 的整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "加密方式 method")" method "2022-blake3-aes-256-gcm"
                method=$(ProxyNormalizeSsMethod "$method")
                inquirer text_input "$(gettext "密钥 password")" password ""
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "method": $method,
                    "password": $pw
                }' --arg addr "$addr" --arg port "$port" --arg method "$method" --arg pw "$password"
            ;;
            socks|http)
                local addr port user pass
                inquirer text_input "$(gettext "服务端地址 address")" addr "127.0.0.1"
                inquirer text_input "$(gettext "服务端端口 port")" port "1080"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 服务端端口必须为 1-65535 的整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "用户名 (可留空)")" user ""
                inquirer text_input "$(gettext "密码 (可留空)")" pass ""
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber),
                    "user": $user,
                    "pass": $pass
                }' --arg addr "$addr" --arg port "$port" --arg user "$user" --arg pass "$pass"
            ;;
            loopback)
                local inb_tag
                inquirer text_input "$(gettext "目标 inboundTag")" inb_tag ""
                JQs build settings_json '{"inboundTag": $t}' --arg t "$inb_tag"
            ;;
            hysteria)
                local addr port
                inquirer text_input "$(gettext "服务端地址 address")" addr ""
                inquirer text_input "$(gettext "服务端端口 port")" port "443"
                if [[ ! $port =~ ^[0-9]+$ ]] || [ "$port" -lt 1 ] || [ "$port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 服务端端口必须为 1-65535 的整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "认证密钥 auth")" hy_auth ""
                JQs build settings_json '{"version": 2, "address": $addr, "port": ($port | tonumber)}' --arg addr "$addr" --arg port "$port"
            ;;
            wireguard)
                local sk addr endpoint pk
                inquirer text_input "$(gettext "本地 secretKey")" sk ""
                inquirer text_input "$(gettext "本地接口地址 (逗号分隔)")" addr "10.0.0.2/32"
                inquirer text_input "$(gettext "对端 endpoint")" endpoint ""
                inquirer text_input "$(gettext "对端 publicKey")" pk ""
                JQs build settings_json '{
                    "secretKey": $sk,
                    "address": ($addr | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                    "peers": [{"endpoint": $ep, "publicKey": $pk}]
                }' --arg sk "$sk" --arg addr "$addr" --arg ep "$endpoint" --arg pk "$pk"
            ;;
            masque)
                local m_addr m_port m_host="" m_path="" m_user="" m_pass=""
                inquirer text_input "$(gettext "服务端地址 address")" m_addr ""
                inquirer text_input "$(gettext "服务端端口 port")" m_port "443"
                if [[ ! $m_port =~ ^[0-9]+$ ]] || [ "$m_port" -lt 1 ] || [ "$m_port" -gt 65535 ]
                then
                    Println "$(eval_gettext "\$error 服务端端口必须为 1-65535 的整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "MASQUE host (可留空)")" m_host ""
                inquirer text_input "$(gettext "MASQUE path (如 /.well-known/masque/ip/{target}/{ipproto}/)")" m_path ""
                inquirer text_input "$(gettext "认证 user (可留空)")" m_user ""
                inquirer text_input "$(gettext "认证 pass (可留空)")" m_pass ""
                JQs build settings_json '{
                    "address": $addr,
                    "port": ($port | tonumber)
                }' --arg addr "$m_addr" --arg port "$m_port"
            ;;
        esac

        local network="" security=""
        local xhttp_host="" xhttp_path="" xhttp_mode=""
        local ws_path="" ws_host="" grpc_svc="" hu_path="" hu_host=""
        local tls_sni="" tls_fp=""
        local r_sni="" r_fp="" r_pw="" r_sid="" r_spx=""

        case "$protocol" in
            hysteria)
                network="hysteria"
                security="tls"
                inquirer text_input "$(gettext "TLS serverName (可留空)")" tls_sni ""
                inquirer text_input "$(gettext "TLS fingerprint (如 chrome, 可留空)")" tls_fp ""
            ;;
            masque)
                network="masque"
                security="tls"
                inquirer text_input "$(gettext "TLS serverName (可留空)")" tls_sni ""
                inquirer text_input "$(gettext "TLS fingerprint (如 chrome, 可留空)")" tls_fp ""
            ;;
            vless|vmess|trojan|shadowsocks)
                local net_options=( 'raw' 'xhttp' 'ws' 'grpc' 'httpupgrade' 'kcp' )
                local net_idx=0
                inquirer list_input_index "$(gettext "选择传输方式")" net_options net_idx
                network="${net_options[$net_idx]}"

                if [ "$network" == "raw" ] || [ "$network" == "xhttp" ] || [ "$network" == "grpc" ]
                then
                    local sec_options=( 'none' 'tls' 'reality' )
                    local sec_idx=0
                    inquirer list_input_index "$(gettext "选择传输安全")" sec_options sec_idx
                    security="${sec_options[$sec_idx]}"
                else
                    local sec_options=( 'none' 'tls' )
                    local sec_idx=0
                    inquirer list_input_index "$(gettext "选择传输安全")" sec_options sec_idx
                    security="${sec_options[$sec_idx]}"
                fi

                case "$network" in
                    xhttp)
                        inquirer text_input "$(gettext "XHTTP host (可留空)")" xhttp_host ""
                        inquirer text_input "XHTTP path" xhttp_path "/"
                        local xm_opts=( 'auto' 'packet-up' 'stream-up' 'stream-one' )
                        inquirer list_input "$(gettext "选择 XHTTP mode")" xm_opts xhttp_mode
                    ;;
                    ws)
                        inquirer text_input "WebSocket path" ws_path "/"
                        inquirer text_input "$(gettext "WebSocket host (可留空)")" ws_host ""
                    ;;
                    grpc)
                        inquirer text_input "gRPC serviceName" grpc_svc ""
                    ;;
                    httpupgrade)
                        inquirer text_input "HTTPUpgrade path" hu_path "/"
                        inquirer text_input "$(gettext "HTTPUpgrade host (可留空)")" hu_host ""
                    ;;
                esac

                if [ "$security" == "tls" ]
                then
                    inquirer text_input "$(gettext "TLS serverName (可留空)")" tls_sni ""
                    inquirer text_input "$(gettext "TLS fingerprint (如 chrome, 可留空)")" tls_fp ""
                elif [ "$security" == "reality" ]
                then
                    inquirer text_input "REALITY serverName" r_sni ""
                    inquirer text_input "REALITY fingerprint" r_fp "chrome"
                    inquirer text_input "$(gettext "REALITY 公钥 password")" r_pw ""
                    inquirer text_input "$(gettext "REALITY shortId (可留空)")" r_sid ""
                    inquirer text_input "$(gettext "REALITY spiderX (可留空)")" r_spx ""
                fi
            ;;
        esac

        local outbound_json=""
        JQs build outbound_json '{
            "sendThrough": $st,
            "protocol": $protocol,
            "tag": $tag,
            "targetStrategy": $ts,
            "settings": $settings,
            "streamSettings": (
                if $network != "" or $dp != "" then {
                    "network": $network,
                    "security": $security,
                    "xhttpSettings": (if $network == "xhttp" then {"host": $xh_host, "path": $xh_path, "mode": $xh_mode} else null end),
                    "wsSettings": (if $network == "ws" then {"path": $ws_path, "host": $ws_host} else null end),
                    "grpcSettings": (if $network == "grpc" then {"serviceName": $grpc_svc} else null end),
                    "httpupgradeSettings": (if $network == "httpupgrade" then {"path": $hu_path, "host": $hu_host} else null end),
                    "hysteriaSettings": (if $network == "hysteria" then {"version": 2, "auth": $hy_auth} else null end),
                    "tlsSettings": (if $security == "tls" then {"serverName": $tls_sni, "fingerprint": $tls_fp} else null end),
                    "realitySettings": (if $security == "reality" then {
                        "serverName": $r_sni,
                        "fingerprint": $r_fp,
                        "password": $r_pw,
                        "shortId": $r_sid,
                        "spiderX": $r_spx
                    } else null end),
                    "sockopt": (if $dp != "" then {"dialerProxy": $dp} else null end)
                } else null end
            )
        }' \
            --arg st "$send_through" \
            --arg protocol "$protocol" \
            --arg tag "$tag" \
            --arg ts "$target_strategy" \
            --argjson settings "$settings_json" \
            --arg network "$network" \
            --arg security "$security" \
            --arg xh_host "$xhttp_host" \
            --arg xh_path "$xhttp_path" \
            --arg xh_mode "$xhttp_mode" \
            --arg ws_path "$ws_path" \
            --arg ws_host "$ws_host" \
            --arg grpc_svc "$grpc_svc" \
            --arg hu_path "$hu_path" \
            --arg hu_host "$hu_host" \
            --arg hy_auth "$hy_auth" \
            --arg tls_sni "$tls_sni" \
            --arg tls_fp "$tls_fp" \
            --arg r_sni "$r_sni" \
            --arg r_fp "$r_fp" \
            --arg r_pw "$r_pw" \
            --arg r_sid "$r_sid" \
            --arg r_spx "$r_spx" \
            --arg dp "$dialer_proxy"

        if [ "$network" == "masque" ]
        then
            outbound_json=$($JQ_FILE -c \
                --arg mh "${m_host:-}" --arg mp "${m_path:-}" --arg mu "${m_user:-}" --arg mpass "${m_pass:-}" '
                .streamSettings = (.streamSettings // {})
                | .streamSettings.masqueSettings = (
                    {}
                    + (if $mh != "" then {host: $mh} else {} end)
                    + (if $mp != "" then {path: $mp} else {} end)
                    + (if $mu != "" then {user: $mu} else {} end)
                    + (if $mpass != "" then {pass: $mpass} else {} end)
                )
            ' <<< "$outbound_json")
        fi

        local target_ver=""
        target_ver=$(ProxyGetTargetVersion "xray")
        local has_flat=0 has_method=0 has_rewrite=0
        ProxyCoreHasFeature "xray" "$target_ver" "json" "flatOutbounds" && has_flat=1
        ProxyCoreHasFeature "xray" "$target_ver" "json" "streamMethodKey" && has_method=1
        ProxyCoreHasFeature "xray" "$target_ver" "json" "dnsRewriteKeys" && has_rewrite=1

        if ProxyCoreHasFeature "xray" "$target_ver" "json" "requireTlsPublicVlessTrojan"
        then
            if { [ "$protocol" == "vless" ] || [ "$protocol" == "trojan" ]; } && { [ -z "$security" ] || [ "$security" == "none" ]; }
            then
                local out_addr="" out_enc=""
                SetDelimiters
                IFS="$field_sep" read -r out_addr out_enc < <($JQ_FILE -r --arg sep "$field_sep" '
                    [
                        (.settings.address // .settings.vnext[0].address // .settings.servers[0].address // "" | tostring),
                        (.settings.encryption // .settings.vnext[0].users[0].encryption // "none" | tostring)
                    ] | join($sep)
                ' <<< "$outbound_json")
                if [ -n "$out_addr" ] && { [ "$protocol" == "trojan" ] || [ "$out_enc" == "none" ]; } && ProxyIsPublicTargetAddress "$out_addr"
                then
                    Println "$(eval_gettext "\$error Xray \${target_ver} 禁止公网明文 \${protocol} 出站 (\$out_addr), 请启用 TLS/REALITY 或 VLESS Encryption")\n"
                    return 1
                fi
            fi
        fi

        outbound_json=$($JQ_FILE -c \
            --arg proto "$protocol" \
            --argjson has_flat "$has_flat" \
            --argjson has_method "$has_method" \
            --argjson has_rewrite "$has_rewrite" '
            if $has_flat == 0 and (.settings | type) == "object" and (.settings | has("address")) then
                if ($proto == "vless" or $proto == "vmess") and (.settings | has("vnext") | not) then
                    .settings as $s | .settings = ({vnext: [{address: $s.address, port: $s.port, users: [($s | del(.address, .port, .reverse))]}]} + (if ($s.reverse | type) == "object" then {reverse: $s.reverse} else {} end))
                elif ($proto == "trojan" or $proto == "shadowsocks") and (.settings | has("servers") | not) then
                    .settings = {servers: [.settings]}
                elif ($proto == "socks" or $proto == "http") and (.settings | has("servers") | not) then
                    .settings as $s | .settings = {servers: ([{address: $s.address, port: $s.port} + (if ($s.user // "") != "" then {users: [{user: $s.user, pass: ($s.pass // "")}]} else {} end)])}
                else . end
            else . end
            | if $proto == "dns" and (.settings | type) == "object" then
                if $has_rewrite == 1 then
                    .settings |= (
                        (if has("network") then (if has("rewriteNetwork") | not then .rewriteNetwork = .network else . end) | del(.network) else . end)
                        | (if has("address") then (if has("rewriteAddress") | not then .rewriteAddress = .address else . end) | del(.address) else . end)
                        | (if has("port") then (if has("rewritePort") | not then .rewritePort = .port else . end) | del(.port) else . end)
                    )
                else
                    .settings |= (
                        (if has("rewriteNetwork") then .network = .rewriteNetwork | del(.rewriteNetwork) else . end)
                        | (if has("rewriteAddress") then .address = .rewriteAddress | del(.rewriteAddress) else . end)
                        | (if has("rewritePort") then .port = .rewritePort | del(.rewritePort) else . end)
                    )
                end
              else . end
            | if (.streamSettings | type) == "object" then
                (.streamSettings.method // .streamSettings.network // null) as $m
                | if $m == null then .
                  elif $has_method == 1 then .streamSettings |= (del(.network) | .method = $m)
                  else .streamSettings |= (del(.method) | .network = $m) end
              else . end
        ' <<< "$outbound_json")

        if ! ProxyAddBound "$X_CONFIG" outbounds "$outbound_json"
        then
            local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
            Println "$(eval_gettext "\$error 添加 Xray 出站 \${tag} 失败: \$err_detail")\n"
            return 1
        fi
        Println "$(eval_gettext "\$info 已添加 Xray 出站 \${green}\${tag}\${normal} (\${protocol})")\n"
    }
    XrayDeleteOutbound()
    {
        ProxySelectBound "$X_CONFIG" outbounds "$(gettext "选择要删除的出站")" || return 1
        local target_tag="${outbounds_tag[selected_bound_index]}"

        if ! ProxyDeleteBound "$X_CONFIG" outbounds "$selected_bound_index"
        then
            local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
            Println "$(eval_gettext "\$error 删除出站 \${target_tag} 失败: \$err_detail")\n"
            return 1
        fi

        Println "$(eval_gettext "\$info 已删除出站 \${green}\${target_tag}\${normal}")\n"
    }
    XrayAddOutboundAccount()
    {
        ProxySelectBound "$X_CONFIG" outbounds "$(gettext "选择要更新凭据/对端的出站")" || return 1
        local idx="$selected_bound_index"
        local bound_tag="${outbounds_tag[idx]}"
        local protocol="${outbounds_protocol[idx]}"

        case "$protocol" in
            wireguard)
                local ep pk psk ka
                inquirer text_input "$(gettext "输入对端 endpoint")" ep ""
                inquirer text_input "$(gettext "输入对端 publicKey")" pk ""
                inquirer text_input "$(gettext "输入 preSharedKey (可留空)")" psk ""
                inquirer text_input "$(gettext "输入 keepAlive (可留空)")" ka ""
                if [ -n "$ka" ] && [[ ! $ka =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error keepAlive 必须为非负整数")\n"
                    return 1
                fi
                local peer_json=""
                JQs build peer_json '{
                    "endpoint": $ep,
                    "publicKey": $pk,
                    "preSharedKey": $psk,
                    "keepAlive": (if $ka != "" then ($ka | tonumber) else null end)
                }' --arg ep "$ep" --arg pk "$pk" --arg psk "$psk" --arg ka "$ka"
                if ! ProxyMutateConfigTx "xray" '.outbounds[$i].settings.peers = ((.outbounds[$i].settings.peers // []) + [$item])' \
                    --argjson i "$idx" --argjson item "$peer_json"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 添加 WireGuard peer 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已向出站 \${green}\${bound_tag}\${normal} 添加 WireGuard peer")\n"
            ;;
            vless|vmess)
                local uuid has_vnext
                inquirer text_input "$(gettext "输入新的用户 UUID")" uuid ""
                has_vnext=$(JQs query "$X_CONFIG" '
                    if (.outbounds[$i].settings | type) == "object"
                        and (.outbounds[$i].settings.vnext | type) == "array"
                        and (.outbounds[$i].settings.vnext | length) > 0
                    then "1" else "0" end
                ' --argjson i "$idx")
                if [ "$has_vnext" == "1" ]
                then
                    if ! ProxyMutateConfigTx "xray" '.outbounds[$i].settings.vnext[0].users = (if (.outbounds[$i].settings.vnext[0].users | type) == "array" and (.outbounds[$i].settings.vnext[0].users | length) > 0 then (.outbounds[$i].settings.vnext[0].users | .[0].id = $id) else [{"id": $id}] end)' --argjson i "$idx" --arg id "$uuid"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 更新出站 \${bound_tag} 的 UUID 失败: \$err_detail")\n"
                        return 1
                    fi
                else
                    if ! ProxyMutateConfigTx "xray" '.outbounds[$i].settings.id = $id' --argjson i "$idx" --arg id "$uuid"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 更新出站 \${bound_tag} 的 UUID 失败: \$err_detail")\n"
                        return 1
                    fi
                fi
                Println "$(eval_gettext "\$info 已更新出站 \${green}\${bound_tag}\${normal} 的 UUID")\n"
            ;;
            trojan|shadowsocks)
                local pw has_servers
                inquirer text_input "$(gettext "输入新密码")" pw ""
                has_servers=$(JQs query "$X_CONFIG" '
                    if (.outbounds[$i].settings | type) == "object"
                        and (.outbounds[$i].settings.servers | type) == "array"
                        and (.outbounds[$i].settings.servers | length) > 0
                    then "1" else "0" end
                ' --argjson i "$idx")
                if [ "$has_servers" == "1" ]
                then
                    if ! ProxyMutateConfigTx "xray" '.outbounds[$i].settings.servers[0].password = $pw' --argjson i "$idx" --arg pw "$pw"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 更新出站 \${bound_tag} 的密码失败: \$err_detail")\n"
                        return 1
                    fi
                else
                    if ! ProxyMutateConfigTx "xray" '.outbounds[$i].settings.password = $pw' --argjson i "$idx" --arg pw "$pw"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 更新出站 \${bound_tag} 的密码失败: \$err_detail")\n"
                        return 1
                    fi
                fi
                Println "$(eval_gettext "\$info 已更新出站 \${green}\${bound_tag}\${normal} 的密码")\n"
            ;;
            socks|http)
                local user pass has_servers
                inquirer text_input "$(gettext "输入用户名")" user ""
                inquirer text_input "$i18n_input_password" pass ""
                has_servers=$(JQs query "$X_CONFIG" '
                    if (.outbounds[$i].settings | type) == "object"
                        and (.outbounds[$i].settings.servers | type) == "array"
                        and (.outbounds[$i].settings.servers | length) > 0
                    then "1" else "0" end
                ' --argjson i "$idx")
                if [ "$has_servers" == "1" ]
                then
                    if ! ProxyMutateConfigTx "xray" '.outbounds[$i].settings.servers[0].users = [{"user": $u, "pass": $p}]' --argjson i "$idx" --arg u "$user" --arg p "$pass"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 更新出站 \${bound_tag} 的账号密码失败: \$err_detail")\n"
                        return 1
                    fi
                else
                    if ! ProxyMutateConfigTx "xray" '.outbounds[$i].settings |= (. + {"user": $u, "pass": $p})' --argjson i "$idx" --arg u "$user" --arg p "$pass"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 更新出站 \${bound_tag} 的账号密码失败: \$err_detail")\n"
                        return 1
                    fi
                fi
                Println "$(eval_gettext "\$info 已更新出站 \${green}\${bound_tag}\${normal} 的账号密码")\n"
            ;;
            *)
                Println "$(eval_gettext "\$error 出站协议 \${protocol} 不支持账号/凭据更新")\n"
                return 1
            ;;
        esac
    }

    XrayDeleteOutboundAccount()
    {
        ProxySelectBound "$X_CONFIG" outbounds "$(gettext "选择要清理凭据/对端的出站")" || return 1
        local idx="$selected_bound_index"
        local bound_tag="${outbounds_tag[idx]}"
        local protocol="${outbounds_protocol[idx]}"

        case "$protocol" in
            wireguard)
                local peer_options=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && peer_options+=("$line")
                done < <(JQs query "$X_CONFIG" '
                    (if (.outbounds | type) == "array" and (.outbounds[$i] | type) == "object"
                        and (.outbounds[$i].settings | type) == "object"
                        and (.outbounds[$i].settings.peers | type) == "array"
                     then .outbounds[$i].settings.peers
                     else [] end)
                    | to_entries[]
                    | select(.value | type == "object")
                    | "\(.key + 1). \(.value.endpoint // .value.publicKey // "peer")"
                ' --argjson i "$idx")
                if [ "${#peer_options[@]}" -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 该出站没有可删除的 peer")\n"
                    return 1
                fi
                local peer_idx=0
                inquirer list_input_index "$(gettext "选择要删除的 peer")" peer_options peer_idx
                if ! ProxyMutateConfigTx "xray" 'del(.outbounds[$i].settings.peers[$p])' --argjson i "$idx" --argjson p "$peer_idx"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 删除 peer 失败: \$err_detail")\n"
                    return 1
                fi
                local del_peer="${peer_options[peer_idx]}"
                Println "$(eval_gettext "\$info 已删除 peer \${green}\${del_peer}\${normal}")\n"
            ;;
            socks|http)
                if ! ProxyMutateConfigTx "xray" '
                    del(.outbounds[$i].settings.user, .outbounds[$i].settings.pass)
                    | if (.outbounds[$i].settings.servers | type) == "array" and (.outbounds[$i].settings.servers | length) > 0 then
                        del(.outbounds[$i].settings.servers[0].users)
                      else . end
                ' --argjson i "$idx"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 清除出站 \${bound_tag} 的认证账号失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已清除出站 \${green}\${bound_tag}\${normal} 的认证账号")\n"
            ;;
            *)
                Println "$(eval_gettext "\$error 出站协议 \${protocol} 请直接删除或重建出站")\n"
                return 1
            ;;
        esac
    }
    XrayGetDns()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.dns')

        jq_path='["hosts"]'

        dns_hosts_domain=()
        dns_hosts_address=()

        while IFS="^" read -r dns_host_domain dns_host_address; do
            dns_hosts_domain+=("$dns_host_domain")
            dns_hosts_address+=("$dns_host_address")
        done < <(JQs get jq_payload '. // {} | to_entries[] | "\(.key)^\(.value)"')

        dns_hosts_count="${#dns_hosts_domain[@]}"

        jq_path='[
            ["servers"],
            ["clientIp"],
            ["queryStrategy"],
            ["disableCache"],
            ["serveStale"],
            ["serveExpiredTTL"],
            ["disableFallback"],
            ["disableFallbackIfMatch"],
            ["enableParallelQuery"],
            ["useSystemHosts"],
            ["tag"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="jq_dns_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        dns_clientIp="${jq_dns_clientIp:-}"
        dns_queryStrategy="${jq_dns_queryStrategy:-UseIP}"
        dns_disableCache="${jq_dns_disableCache:-false}"
        dns_serveStale="${jq_dns_serveStale:-false}"
        dns_serveExpiredTTL="${jq_dns_serveExpiredTTL:-0}"
        dns_disableFallback="${jq_dns_disableFallback:-false}"
        dns_disableFallbackIfMatch="${jq_dns_disableFallbackIfMatch:-false}"
        dns_enableParallelQuery="${jq_dns_enableParallelQuery:-false}"
        dns_useSystemHosts="${jq_dns_useSystemHosts:-false}"
        dns_tag="${jq_dns_tag:-dns_inbound}"

        if [ -z "${jq_dns_servers:-}" ]
        then
            dns_servers_count=0
            return 0
        fi

        IFS="${delimiters[1]}" read -r -a dns_servers <<< "$jq_dns_servers"

        dns_servers_count=${#dns_servers[@]}
    }
    XrayListDns()
    {
        local out
        out=$(ProxyRenderDns "$X_CONFIG" xray)
        if [ -z "$out" ]
        then
            Println "$(eval_gettext "\$error 未配置 DNS")\n"
            return 1
        fi
        Println "\n$(gettext "=== Xray DNS 配置 ===")\n$out\n"
    }
    XraySetDns()
    {
        local actions=(
            "$(gettext "添加静态 IP (hosts)")"
            "$(gettext "添加 DNS 服务器")"
            "$(gettext "设置 clientIp")"
            "$(gettext "设置 DNS 标识 tag")"
            "$(gettext "设置 queryStrategy")"
            "$(gettext "设置缓存与回退开关")"
            "$(gettext "删除静态 IP (hosts)")"
            "$(gettext "删除 DNS 服务器")"
        )
        local action_idx=0
        echo
        inquirer list_input_index "$(gettext "选择 Xray DNS 操作")" actions action_idx

        case "$action_idx" in
            0)
                local domain ips
                Println "$(eval_gettext "\$tip 格式如 example.com, domain:example.com, geosite:cn")"
                inquirer text_input "$(gettext "输入域名或规则")" domain ""
                inquirer text_input "$(gettext "输入目标 IP/域名 (逗号分隔)")" ips ""
                if [ -z "$domain" ] || [ -z "$ips" ]
                then
                    Println "$(eval_gettext "\$error 域名和目标 IP/域名不能为空")\n"
                    return 1
                fi
                if ! ProxyMutateConfigTx "xray" '.dns.hosts = ((.dns.hosts // {}) + {($d): (if ($v | contains(",")) then ($v | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else ($v | gsub("^\\s+|\\s+$"; "")) end)})' \
                    --arg d "$domain" --arg v "$ips"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 添加静态 IP 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 静态 IP 添加成功: \${green}\${domain}\${normal}")\n"
            ;;
            1)
                local addr port client_ip domains expected_ips unexpected_ips timeout_ms
                local skip_fb_opts=( "$i18n_no" "$i18n_yes" )
                local skip_fb_idx=0 final_q_idx=0
                inquirer text_input "$(gettext "输入 DNS 地址 (如 1.1.1.1, https://...)")" addr "1.1.1.1"
                inquirer text_input "$(gettext "输入端口 (留空默认)")" port ""
                if [ -n "$port" ] && [[ ! $port =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error DNS 端口必须为非负整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "输入服务器级 clientIP (可留空)")" client_ip ""
                inquirer text_input "$(gettext "输入匹配 domains (逗号分隔, 可留空)")" domains ""
                inquirer text_input "$(gettext "输入 expectedIPs (逗号分隔, 可留空)")" expected_ips ""
                inquirer text_input "$(gettext "输入 unexpectedIPs (逗号分隔, 可留空)")" unexpected_ips ""
                inquirer text_input "$(gettext "输入 timeoutMs (可留空)")" timeout_ms ""
                if [ -n "$timeout_ms" ] && [[ ! $timeout_ms =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error timeoutMs 必须为非负整数")\n"
                    return 1
                fi
                inquirer list_input_index "$(gettext "跳过回退 skipFallback")" skip_fb_opts skip_fb_idx
                inquirer list_input_index "$(gettext "终止后续查询 finalQuery")" skip_fb_opts final_q_idx

                local srv_json=""
                if [ -z "$port" ] && [ -z "$client_ip" ] && [ -z "$domains" ] && [ -z "$expected_ips" ] && [ -z "$unexpected_ips" ] && [ -z "$timeout_ms" ] && [ "$skip_fb_idx" -eq 0 ] && [ "$final_q_idx" -eq 0 ]
                then
                    JQs build srv_json '$addr' --arg addr "$addr"
                else
                    JQs build srv_json '{
                        "address": $addr,
                        "port": (if $port != "" then ($port | tonumber) else null end),
                        "clientIP": (if $cip != "" then $cip else null end),
                        "domains": (if $dom != "" then ($dom | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                        "expectedIPs": (if $eip != "" then ($eip | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                        "unexpectedIPs": (if $uip != "" then ($uip | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))) else null end),
                        "timeoutMs": (if $tms != "" then ($tms | tonumber) else null end),
                        "skipFallback": (if $sf == "1" then true else null end),
                        "finalQuery": (if $fq == "1" then true else null end)
                    }' --arg addr "$addr" --arg port "$port" --arg cip "$client_ip" --arg dom "$domains" \
                        --arg eip "$expected_ips" --arg uip "$unexpected_ips" --arg tms "$timeout_ms" \
                        --arg sf "$skip_fb_idx" --arg fq "$final_q_idx"
                fi
                if ! ProxyMutateConfigTx "xray" '.dns.servers = ((.dns.servers // []) + [$item])' --argjson item "$srv_json"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 添加 DNS 服务器失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info DNS 服务器添加成功: \${green}\${addr}\${normal}")\n"
            ;;
            2)
                local cip
                inquirer text_input "$(gettext "输入全局 clientIp (留空清除)")" cip ""
                if [ -z "$cip" ]
                then
                    if ! ProxyMutateConfigTx "xray" 'del(.dns.clientIp)'
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 清除 DNS clientIp 失败: \$err_detail")\n"
                        return 1
                    fi
                else
                    if ! ProxyMutateConfigTx "xray" '.dns.clientIp = $cip' --arg cip "$cip"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 设置 DNS clientIp 失败: \$err_detail")\n"
                        return 1
                    fi
                fi
                Println "$(eval_gettext "\$info DNS clientIp 设置成功")\n"
            ;;
            3)
                local dtag
                inquirer text_input "$(gettext "输入 DNS 标识 tag")" dtag "dns_inbound"
                if ! ProxyMutateConfigTx "xray" '.dns.tag = $t' --arg t "$dtag"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 设置 DNS tag 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info DNS tag 设置成功: \${green}\${dtag}\${normal}")\n"
            ;;
            4)
                local qs_options=( 'UseIP' 'UseIPv4' 'UseIPv6' 'UseSystem' )
                local qs=""
                inquirer list_input "$(gettext "选择 DNS 查询策略 queryStrategy")" qs_options qs
                if ! ProxyMutateConfigTx "xray" '.dns.queryStrategy = $qs' --arg qs "$qs"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 设置 queryStrategy 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info queryStrategy 已设置为 \${green}\${qs}\${normal}")\n"
            ;;
            5)
                local yn_opts=( "$i18n_no" "$i18n_yes" )
                local dc_idx=0 df_idx=0 dfm_idx=0 ss_idx=0 pq_idx=0 sh_idx=0 ttl=""
                inquirer list_input_index "$(gettext "禁用缓存 disableCache")" yn_opts dc_idx
                inquirer list_input_index "$(gettext "禁用回退 disableFallback")" yn_opts df_idx
                inquirer list_input_index "$(gettext "匹配时不回退 disableFallbackIfMatch")" yn_opts dfm_idx
                inquirer list_input_index "$(gettext "启用过期缓存 serveStale")" yn_opts ss_idx
                if [ "$ss_idx" -eq 1 ]
                then
                    inquirer text_input "$(gettext "过期缓存 TTL (秒, 0 不限)")" ttl "0"
                    if [ -n "$ttl" ] && [[ ! $ttl =~ ^[0-9]+$ ]]
                    then
                        Println "$(eval_gettext "\$error serveExpiredTTL 必须为非负整数")\n"
                        return 1
                    fi
                fi
                inquirer list_input_index "$(gettext "启用并行查询 enableParallelQuery")" yn_opts pq_idx
                inquirer list_input_index "$(gettext "使用系统 Hosts useSystemHosts")" yn_opts sh_idx

                if ! ProxyMutateConfigTx "xray" '.dns = ((.dns // {}) * {
                    "disableCache": ($dc == "1"),
                    "disableFallback": ($df == "1"),
                    "disableFallbackIfMatch": ($dfm == "1"),
                    "serveStale": ($ss == "1"),
                    "enableParallelQuery": ($pq == "1"),
                    "useSystemHosts": ($sh == "1")
                } + (if $ttl != "" then {"serveExpiredTTL": ($ttl | tonumber)} else {} end))' \
                    --arg dc "$dc_idx" --arg df "$df_idx" --arg dfm "$dfm_idx" \
                    --arg ss "$ss_idx" --arg pq "$pq_idx" --arg sh "$sh_idx" --arg ttl "$ttl"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 更新 Xray DNS 全局开关失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info Xray DNS 全局开关已更新")\n"
            ;;
            6)
                local host_keys=()
                local k
                while IFS= read -r k
                do
                    [ -n "$k" ] && host_keys+=("$k")
                done < <(JQs query "$X_CONFIG" 'if (.dns | type) == "object" and (.dns.hosts | type) == "object" then (.dns.hosts | keys[]) else empty end')
                if [ "${#host_keys[@]}" -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可删除的静态 IP")\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "$(gettext "选择要删除的静态 IP")" host_keys del_idx
                local del_key="${host_keys[$del_idx]}"
                if ! ProxyMutateConfigTx "xray" 'del(.dns.hosts[$k])' --arg k "$del_key"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 删除静态 IP 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已删除静态 IP: \${green}\${del_key}\${normal}")\n"
            ;;
            7)
                local srv_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && srv_opts+=("$line")
                done < <(JQs query "$X_CONFIG" 'if (.dns | type) == "object" and (.dns.servers | type) == "array" then (.dns.servers | to_entries[] | "\(.key + 1). \(if (.value | type) == "string" then .value elif (.value | type) == "object" then (.value.address // "server") else "server" end)") else empty end')
                if [ "${#srv_opts[@]}" -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可删除的 DNS 服务器")\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "$(gettext "选择要删除的 DNS 服务器")" srv_opts del_idx
                if ! ProxyMutateConfigTx "xray" 'del(.dns.servers[$i])' --argjson i "$del_idx"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 删除 DNS 服务器失败: \$err_detail")\n"
                    return 1
                fi
                local del_srv="${srv_opts[$del_idx]}"
                Println "$(eval_gettext "\$info 已删除 DNS 服务器: \${green}\${del_srv}\${normal}")\n"
            ;;
        esac
    }
    XrayGetRouting()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.routing')

        jq_path='[
            ["domainStrategy"],
            ["rules","domain"],
            ["rules","ip"],
            ["rules","port"],
            ["rules","sourcePort"],
            ["rules","localPort"],
            ["rules","network"],
            ["rules","sourceIP"],
            ["rules","localIP"],
            ["rules","user"],
            ["rules","vlessRoute"],
            ["rules","inboundTag"],
            ["rules","protocol"],
            ["rules","attrs"],
            ["rules","process"],
            ["rules","outboundTag"],
            ["rules","balancerTag"],
            ["rules","ruleTag"],
            ["rules","webhook","url"],
            ["rules","webhook","deduplication"],
            ["rules","webhook","headers"],
            ["balancers","tag"],
            ["balancers","selector"],
            ["balancers","fallbackTag"],
            ["balancers","strategy","type"],
            ["balancers","strategy","settings","expected"],
            ["balancers","strategy","settings","maxRTT"],
            ["balancers","strategy","settings","tolerance"],
            ["balancers","strategy","settings","baselines"],
            ["balancers","strategy","settings","costs","regexp"],
            ["balancers","strategy","settings","costs","match"],
            ["balancers","strategy","settings","costs","value"]
        ]'

        while IFS=": " read -r path_name value
        do
            var_name="jq_routing_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        routing_domainStrategy="${jq_routing_domainStrategy:-AsIs}"

        if [ -z "${jq_routing_balancers_tag:-}" ]
        then
            routing_balancers_count=0
        else
            IFS="${delimiters[2]}" read -r -a routing_balancers_tag <<< "$jq_routing_balancers_tag"
            IFS="${delimiters[2]}" read -r -a routing_balancers_selector <<< "$jq_routing_balancers_selector"
            IFS="${delimiters[2]}" read -r -a routing_balancers_fallbackTag <<< "$jq_routing_balancers_fallbackTag"
            IFS="${delimiters[3]}" read -r -a routing_balancers_strategy_type <<< "$jq_routing_balancers_strategy_type"
            IFS="${delimiters[4]}" read -r -a routing_balancers_strategy_settings_expected <<< "$jq_routing_balancers_strategy_settings_expected"
            IFS="${delimiters[4]}" read -r -a routing_balancers_strategy_settings_maxRTT <<< "$jq_routing_balancers_strategy_settings_maxRTT"
            IFS="${delimiters[4]}" read -r -a routing_balancers_strategy_settings_tolerance <<< "$jq_routing_balancers_strategy_settings_tolerance"
            IFS="${delimiters[4]}" read -r -a routing_balancers_strategy_settings_baselines <<< "$jq_routing_balancers_strategy_settings_baselines"
            IFS="${delimiters[5]}" read -r -a routing_balancers_strategy_settings_costs_regexp <<< "$jq_routing_balancers_strategy_settings_costs_regexp"
            IFS="${delimiters[5]}" read -r -a routing_balancers_strategy_settings_costs_match <<< "$jq_routing_balancers_strategy_settings_costs_match"
            IFS="${delimiters[5]}" read -r -a routing_balancers_strategy_settings_costs_value <<< "$jq_routing_balancers_strategy_settings_costs_value"

            routing_balancers_count=${#routing_balancers_tag[@]}
        fi

        routing_rules_count=0
        if [ -s "$X_CONFIG" ]
        then
            routing_rules_count=$($JQ_FILE -r '(.routing.rules // []) | length' "$X_CONFIG" 2> /dev/null)
            routing_rules_count="${routing_rules_count:-0}"
        fi

        if [ "$routing_rules_count" -eq 0 ]
        then
            return 0
        fi

        IFS="${delimiters[2]}" read -r -a routing_rules_domain <<< "${jq_routing_rules_domain:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_ip <<< "${jq_routing_rules_ip:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_port <<< "${jq_routing_rules_port:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_sourcePort <<< "${jq_routing_rules_sourcePort:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_localPort <<< "${jq_routing_rules_localPort:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_network <<< "${jq_routing_rules_network:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_sourceIP <<< "${jq_routing_rules_sourceIP:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_localIP <<< "${jq_routing_rules_localIP:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_user <<< "${jq_routing_rules_user:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_vlessRoute <<< "${jq_routing_rules_vlessRoute:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_inboundTag <<< "${jq_routing_rules_inboundTag:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_protocol <<< "${jq_routing_rules_protocol:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_attrs <<< "${jq_routing_rules_attrs:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_process <<< "${jq_routing_rules_process:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_outboundTag <<< "${jq_routing_rules_outboundTag:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_balancerTag <<< "${jq_routing_rules_balancerTag:-}"
        IFS="${delimiters[2]}" read -r -a routing_rules_ruleTag <<< "${jq_routing_rules_ruleTag:-}"
        IFS="${delimiters[3]}" read -r -a routing_rules_webhook_url <<< "${jq_routing_rules_webhook_url:-}"
        IFS="${delimiters[3]}" read -r -a routing_rules_webhook_deduplication <<< "${jq_routing_rules_webhook_deduplication:-}"
        IFS="${delimiters[3]}" read -r -a routing_rules_webhook_headers <<< "${jq_routing_rules_webhook_headers:-}"
    }
    XrayListRouting()
    {
        local out
        out=$(ProxyRenderRouting "$X_CONFIG" xray)
        if [ -z "$out" ]
        then
            Println "$(eval_gettext "\$error 未配置路由")\n"
            return 1
        fi
        Println "\n$(gettext "=== Xray 路由配置 ===")\n$out\n"
    }
    XraySetRouting()
    {
        local actions=(
            "$(gettext "添加路由规则")"
            "$(gettext "添加负载均衡器")"
            "$(gettext "设置 domainStrategy")"
            "$(gettext "删除路由规则")"
            "$(gettext "删除负载均衡器")"
        )
        local action_idx=0
        echo
        inquirer list_input_index "$(gettext "选择 Xray 路由操作")" actions action_idx

        case "$action_idx" in
            0)
                local mode_opts=( "$(gettext "快捷路由 (选择入站 -> 出站)")" "$(gettext "自定义路由规则")" )
                local mode_idx=0
                inquirer list_input_index "$(gettext "选择添加路由方式")" mode_opts mode_idx

                if [ "$mode_idx" -eq 0 ]
                then
                    ProxySelectBound "$X_CONFIG" inbounds "$(gettext "选择匹配的入站")" || return 1
                    local in_tag="${inbounds_tag[selected_bound_index]}"
                    if [ -z "$in_tag" ]
                    then
                        Println "$(eval_gettext "\$error 此入站没有标签")\n"
                        return 1
                    fi
                    ProxySelectBound "$X_CONFIG" outbounds "$(gettext "选择转发目标出站")" || return 1
                    local out_tag="${outbounds_tag[selected_bound_index]}"
                    if [ -z "$out_tag" ]
                    then
                        Println "$(eval_gettext "\$error 此出站没有标签")\n"
                        return 1
                    fi
                    local rule_json=""
                    JQs build rule_json '{"inboundTag": [$it], "outboundTag": $ot}' --arg it "$in_tag" --arg ot "$out_tag"
                    if ! ProxyMutateConfigTx "xray" '.routing = ((.routing // {}) | .rules = ((.rules // []) + [$item]))' --argjson item "$rule_json"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 快捷路由添加失败: \$err_detail")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 快捷路由添加成功: \${green}\${in_tag} => \${out_tag}\${normal}")\n"
                else
                    local net_any="$(gettext "不限")"
                    local net_opts=( 'tcp,udp' 'tcp' 'udp' "$net_any" )
                    local net_choice=""
                    inquirer list_input "$(gettext "选择匹配的连接方式 network")" net_opts net_choice
                    [ "$net_choice" == "$net_any" ] && net_choice=""

                    local rule_tag domains ips port src_port local_port src_ip local_ip users inb_tag procs vless_route webhook_url out_tag bal_tag
                    inquirer text_input "$(gettext "规则标识 ruleTag (可留空)")" rule_tag ""
                    inquirer text_input "$(gettext "匹配 domain (逗号分隔, 可留空)")" domains ""
                    inquirer text_input "$(gettext "匹配 ip (逗号分隔, 可留空)")" ips ""
                    inquirer text_input "$(gettext "匹配目标 port (可留空)")" port ""
                    inquirer text_input "$(gettext "匹配来源 sourcePort (可留空)")" src_port ""
                    inquirer text_input "$(gettext "匹配本地 localPort (可留空)")" local_port ""
                    inquirer text_input "$(gettext "匹配 sourceIP (逗号分隔, 可留空)")" src_ip ""
                    inquirer text_input "$(gettext "匹配 localIP (逗号分隔, 可留空)")" local_ip ""
                    inquirer text_input "$(gettext "匹配用户 user (逗号分隔, 可留空)")" users ""

                    local proto_opts=( 'http' 'tls' 'quic' 'bittorrent' )
                    local proto_sel=()
                    inquirer checkbox_input "$(gettext "选择匹配的流量协议 protocol (可留空)")" proto_opts proto_sel
                    local proto_csv=""
                    if [ "${#proto_sel[@]}" -gt 0 ] && [ -n "${proto_sel[0]:-}" ]
                    then
                        proto_csv=$(JoinByChar , "${proto_sel[@]}")
                    fi

                    inquirer text_input "$(gettext "匹配 inboundTag (逗号分隔, 可留空)")" inb_tag ""
                    inquirer text_input "$(gettext "匹配进程 process (逗号分隔, 可留空)")" procs ""
                    inquirer text_input "$(gettext "匹配 vlessRoute (可留空)")" vless_route ""
                    inquirer text_input "$(gettext "Webhook URL (可留空)")" webhook_url ""
                    inquirer text_input "$(gettext "目标 outboundTag (与 balancerTag 二选一)")" out_tag ""
                    inquirer text_input "$(gettext "目标 balancerTag (可留空)")" bal_tag ""

                    local rule_json=""
                    JQs build rule_json '
                        def csv_arr($s):
                            if $s != "" then
                                ($s | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0)) | if length > 0 then . else null end)
                            else null end;
                        {
                            "ruleTag": $rtag,
                            "network": $net,
                            "domain": csv_arr($dom),
                            "ip": csv_arr($ip),
                            "port": $port,
                            "sourcePort": $sport,
                            "localPort": $lport,
                            "sourceIP": csv_arr($sip),
                            "localIP": csv_arr($lip),
                            "user": csv_arr($usr),
                            "protocol": csv_arr($proto),
                            "inboundTag": csv_arr($itag),
                            "process": csv_arr($proc),
                            "vlessRoute": $vr,
                            "webhook": (if $wh != "" then {"url": $wh} else null end),
                            "outboundTag": $otag,
                            "balancerTag": $btag
                        }
                    ' --arg rtag "$rule_tag" --arg net "$net_choice" --arg dom "$domains" --arg ip "$ips" \
                        --arg port "$port" --arg sport "$src_port" --arg lport "$local_port" \
                        --arg sip "$src_ip" --arg lip "$local_ip" --arg usr "$users" --arg proto "$proto_csv" \
                        --arg itag "$inb_tag" --arg proc "$procs" --arg vr "$vless_route" --arg wh "$webhook_url" \
                        --arg otag "$out_tag" --arg btag "$bal_tag"

                    if ! ProxyMutateConfigTx "xray" '.routing.rules = ((.routing.rules // []) + [$item])' --argjson item "$rule_json"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 添加 Xray 路由规则失败: \$err_detail")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已添加 Xray 路由规则")\n"
                fi
            ;;
            1)
                local strat_opts=( 'random' 'roundRobin' 'leastPing' 'leastLoad' )
                local b_tag b_sel b_strat b_fb
                inquirer text_input "Balancer tag" b_tag ""
                inquirer text_input "$(gettext "selector (逗号分隔)")" b_sel ""
                inquirer list_input "$(gettext "选择策略 strategy.type")" strat_opts b_strat
                inquirer text_input "$(gettext "fallbackTag (可留空)")" b_fb ""

                local bal_json=""
                JQs build bal_json '{
                    "tag": $tag,
                    "selector": ($sel | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                    "fallbackTag": $fb,
                    "strategy": {"type": $st}
                }' --arg tag "$b_tag" --arg sel "$b_sel" --arg fb "$b_fb" --arg st "$b_strat"

                if ! ProxyMutateConfigTx "xray" '
                    .routing.balancers = ((.routing.balancers // []) + [$item])
                    | if $st == "leastLoad" and (has("burstObservatory") | not) then
                        .burstObservatory = {
                            subjectSelector: $item.selector,
                            pingConfig: {
                                destination: "https://www.gstatic.com/generate_204",
                                interval: "5m"
                            }
                        }
                      elif $st == "leastPing" and ((has("observatory") or has("burstObservatory")) | not) then
                        .observatory = {
                            subjectSelector: $item.selector,
                            probeURL: "https://www.gstatic.com/generate_204",
                            probeInterval: "1m"
                        }
                      else . end
                ' --argjson item "$bal_json" --arg st "$b_strat"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 添加 Xray 负载均衡失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已添加 Xray 负载均衡 \${green}\${b_tag}\${normal}")\n"
            ;;
            2)
                local ds_opts=( 'AsIs' 'IPIfNonMatch' 'IPOnDemand' )
                local ds=""
                inquirer list_input "$(gettext "选择域名解析策略 domainStrategy")" ds_opts ds
                if ! ProxyMutateConfigTx "xray" '.routing.domainStrategy = $ds' --arg ds "$ds"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 设置 domainStrategy 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已设置 domainStrategy 为 \${green}\${ds}\${normal}")\n"
            ;;
            3)
                local rule_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && rule_opts+=("$line")
                done < <(JQs query "$X_CONFIG" 'if (.routing | type) == "object" and (.routing.rules | type) == "array" then (.routing.rules | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.ruleTag // "rule") => \(.value.outboundTag // .value.balancerTag // "")") else empty end')
                if [ "${#rule_opts[@]}" -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可删除的路由规则")\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "$(gettext "选择要删除的路由规则")" rule_opts del_idx
                if ! ProxyMutateConfigTx "xray" 'del(.routing.rules[$i])' --argjson i "$del_idx"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 删除路由规则失败: \$err_detail")\n"
                    return 1
                fi
                local del_rule="${rule_opts[$del_idx]}"
                Println "$(eval_gettext "\$info 已删除路由规则: \${green}\${del_rule}\${normal}")\n"
            ;;
            4)
                local bal_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && bal_opts+=("$line")
                done < <(JQs query "$X_CONFIG" 'if (.routing | type) == "object" and (.routing.balancers | type) == "array" then (.routing.balancers | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.tag // "balancer")") else empty end')
                if [ "${#bal_opts[@]}" -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可删除的负载均衡器")\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "$(gettext "选择要删除的负载均衡器")" bal_opts del_idx
                if ! ProxyMutateConfigTx "xray" 'del(.routing.balancers[$i])' --argjson i "$del_idx"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 删除负载均衡器失败: \$err_detail")\n"
                    return 1
                fi
                local del_bal="${bal_opts[$del_idx]}"
                Println "$(eval_gettext "\$info 已删除负载均衡器: \${green}\${del_bal}\${normal}")\n"
            ;;
        esac
    }
    XrayListPolicy()
    {
        local out
        out=$(ProxyRenderPolicy "$X_CONFIG" xray)
        if [ -z "$out" ]
        then
            Println "$(eval_gettext "\$error 未配置策略")\n"
            return 1
        fi
        Println "\n$(gettext "=== Xray 策略配置 ===")\n$out\n"
    }
    XraySetPolicy()
    {
        local actions=(
            "$(gettext "添加/修改用户等级策略")"
            "$(gettext "删除用户等级策略")"
            "$(gettext "设置入站上行流量统计")"
            "$(gettext "设置入站下行流量统计")"
            "$(gettext "设置出站上行流量统计")"
            "$(gettext "设置出站下行流量统计")"
        )
        local action_idx=0
        echo
        inquirer list_input_index "$(gettext "选择 Xray 策略操作")" actions action_idx

        local sw_opts=( "$i18n_close" "$i18n_open" )

        case "$action_idx" in
            0)
                local lvl hs ci uo do_s buf
                local up_idx=1 dn_idx=1 online_idx=1
                inquirer text_input "$(gettext "用户等级 level (留空自动分配)")" lvl ""
                if [ -z "$lvl" ]
                then
                    lvl=$(JQs query "$X_CONFIG" '((if (.policy | type) == "object" then (if (.policy.levels | type) == "object" then .policy.levels elif (.policy.level | type) == "object" then .policy.level else {} end) else {} end) | keys | map(tonumber?) | max // -1) + 1')
                    lvl="${lvl:-0}"
                fi
                if [[ ! $lvl =~ ^[0-9]+$ ]]
                then
                    Println "$(eval_gettext "\$error 用户等级 level 必须为非负整数")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "handshake (秒)")" hs "60"
                inquirer text_input "$(gettext "connIdle (秒)")" ci "300"
                inquirer text_input "$(gettext "uplinkOnly (秒)")" uo "1"
                inquirer text_input "$(gettext "downlinkOnly (秒)")" do_s "1"
                inquirer text_input "bufferSize (KB, $(gettext "留空使用默认"))" buf ""
                if [[ ! $hs =~ ^[0-9]+$ ]] || [[ ! $ci =~ ^[0-9]+$ ]] || [[ ! $uo =~ ^[0-9]+$ ]] || [[ ! $do_s =~ ^[0-9]+$ ]] || { [ -n "$buf" ] && [[ ! $buf =~ ^[0-9]+$ ]]; }
                then
                    Println "$(eval_gettext "\$error handshake / connIdle / uplinkOnly / downlinkOnly / bufferSize 必须为非负整数")\n"
                    return 1
                fi
                inquirer list_input_index "$(gettext "用户上行流量统计 statsUserUplink")" sw_opts up_idx
                inquirer list_input_index "$(gettext "用户下行流量统计 statsUserDownlink")" sw_opts dn_idx
                inquirer list_input_index "$(gettext "用户在线统计 statsUserOnline")" sw_opts online_idx

                if ! ProxyMutateConfigTx "xray" '.policy.levels = ((.policy.levels // .policy.level // {}) * {
                    ($lvl): ({
                        "handshake": ($hs | tonumber),
                        "connIdle": ($ci | tonumber),
                        "uplinkOnly": ($uo | tonumber),
                        "downlinkOnly": ($do_s | tonumber),
                        "statsUserUplink": ($up == "1"),
                        "statsUserDownlink": ($dn == "1"),
                        "statsUserOnline": ($online == "1")
                    } + (if $buf != "" then {"bufferSize": ($buf | tonumber)} else {} end))
                }) | del(.policy.level)' \
                    --arg lvl "$lvl" --arg hs "$hs" --arg ci "$ci" --arg uo "$uo" --arg do_s "$do_s" \
                    --arg buf "$buf" --arg up "$up_idx" --arg dn "$dn_idx" --arg online "$online_idx"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 更新等级 \${lvl} 策略失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已更新等级 \${green}\${lvl}\${normal} 策略")\n"
            ;;
            1)
                local lvls=()
                local k
                while IFS= read -r k
                do
                    [ -n "$k" ] && lvls+=("$k")
                done < <(JQs query "$X_CONFIG" '(if (.policy | type) == "object" then (if (.policy.levels | type) == "object" then .policy.levels elif (.policy.level | type) == "object" then .policy.level else {} end) else {} end) | keys[]')
                if [ "${#lvls[@]}" -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可删除的用户等级策略")\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "$(gettext "选择要删除的用户等级")" lvls del_idx
                local del_lvl="${lvls[$del_idx]}"
                if ! ProxyMutateConfigTx "xray" 'del(.policy.level[$k], .policy.levels[$k])' --arg k "$del_lvl"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 删除等级 \${del_lvl} 策略失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已删除等级 \${green}\${del_lvl}\${normal} 策略")\n"
            ;;
            2|3|4|5)
                local sys_keys=( '' '' 'statsInboundUplink' 'statsInboundDownlink' 'statsOutboundUplink' 'statsOutboundDownlink' )
                local sys_key="${sys_keys[$action_idx]}"
                local sw_idx=1 sw_bool=false
                inquirer list_input_index "$(eval_gettext "设置 \${sys_key}")" sw_opts sw_idx
                [ "$sw_idx" -eq 1 ] && sw_bool=true
                if ! ProxyMutateConfigTx "xray" '.policy.system = ((.policy.system // {}) + {($k): $v})' --arg k "$sys_key" --argjson v "$sw_bool"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 更新系统策略 \${sys_key} 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已更新系统策略 \${green}\${sys_key}\${normal}")\n"
            ;;
        esac
    }
    XrayGetApiServer()
    {
        local api_server
        api_server=$(JQs query "$X_CONFIG" '
            def normalize_host($h):
                if $h == "" or $h == "0.0.0.0" or $h == "::" or $h == "[::]" then "127.0.0.1" else $h end;
            if (.api | type) == "object" and (.api.listen | type) == "string" and .api.listen != "" then
                (.api.listen | sub("^(0\\.0\\.0\\.0|\\[::\\]|::):"; "127.0.0.1:"))
            else
                ((if (.api | type) == "object" and (.api.tag | type) == "string" then .api.tag else "api" end) as $api_tag
                | first(
                    (if (.inbounds | type) == "array" then .inbounds else [] end)[]
                    | select(type == "object" and .tag == $api_tag)
                    | "\(normalize_host(.listen // "127.0.0.1")):\(.port // 10085)"
                ) // $def_api)
            end
        ' --arg def_api "$XRAY_DEFAULT_API" | head -n 1)
        printf '%s' "${api_server:-$XRAY_DEFAULT_API}"
    }

    XrayListStats()
    {
        local api_server
        api_server=$(XrayGetApiServer)

        local bin
        bin=$(ProxyDetectCoreBin "xray")
        if [ ! -x "$bin" ]
        then
            Println "$(eval_gettext "\$error 未找到隔离版 aios-xray (\$bin)")\n"
            return 1
        fi

        local raw_stats
        if ! raw_stats=$("$bin" api statsquery --server="$api_server" 2>&1)
        then
            Println "$(eval_gettext "\$error 无法连接 Xray API (\$api_server), 请确认已开启 api 与 stats: \${raw_stats}")\n"
            return 1
        fi

        if ! printf '%s' "$raw_stats" | $JQ_FILE -e . > /dev/null 2>&1
        then
            Println "$(eval_gettext "\$error Xray API 返回非合法 JSON (\$api_server): \${raw_stats}")\n"
            return 1
        fi

        local formatted
        formatted=$(ProxyFormatStatsJson "$raw_stats")

        if [ -z "$formatted" ]
        then
            Println "$(eval_gettext "\$info 暂无流量统计数据")\n"
            return 0
        fi

        Println "\n$(gettext "=== Xray 流量统计 ===")\n$formatted\n"
    }

    XrayResetStats()
    {
        if [ "${1:-}" != "-y" ] && [ "${1:-}" != "--yes" ] && [ -t 0 ]
        then
            local confirm_opts=( "$i18n_no" "$i18n_yes" )
            local confirm_idx=0
            echo
            inquirer list_input_index "$(gettext "确认重置 Xray 所有流量统计?")" confirm_opts confirm_idx
            if [ "$confirm_idx" -ne 1 ]
            then
                Println "$(eval_gettext "\$info 已取消重置流量统计")\n"
                return 0
            fi
        fi

        local api_server
        api_server=$(XrayGetApiServer)

        local bin
        bin=$(ProxyDetectCoreBin "xray")
        if [ ! -x "$bin" ]
        then
            Println "$(eval_gettext "\$error 未找到隔离版 aios-xray (\$bin)")\n"
            return 1
        fi

        local err_msg=""
        if err_msg=$("$bin" api statsquery --server="$api_server" --reset 2>&1)
        then
            Println "$(eval_gettext "\$info 已重置 Xray 流量统计")\n"
        else
            Println "$(eval_gettext "\$error 重置 Xray 流量统计失败 (\$api_server): \${err_msg}")\n"
            return 1
        fi
    }
    XrayListReverse()
    {
        Println "$(eval_gettext "\$tip 注意: Xray 顶层 reverse 配置已废弃, 推荐使用 VLESS 反向代理")\n"

        local out
        out=$(ProxyRenderReverse "$X_CONFIG" xray)
        if [ -z "$out" ]
        then
            Println "$(eval_gettext "\$error 未配置反向代理")\n"
            return 1
        fi
        Println "\n$(gettext "=== Xray 反向代理配置 ===")\n$out\n"
    }
    XraySetReverse()
    {
        local cur_ver
        cur_ver=$(ProxyGetTargetVersion "xray")
        if ! ProxyCoreHasFeature "xray" "$cur_ver" "json" "legacyReverse"
        then
            Println "$(eval_gettext "\$error Xray \${cur_ver} 已移除顶层 legacy reverse (>= 26.4.25), 请改用 VLESS 内联反向代理")\n"
            return 1
        fi

        Println "$(eval_gettext "\$tip 注意: Xray 顶层 reverse 配置在 >= 26.4.25 已移除, 推荐使用 VLESS 反向代理")\n"

        local actions=( "$(gettext "添加 Bridge")" "$(gettext "添加 Portal")" "$(gettext "删除 Bridge")" "$(gettext "删除 Portal")" )
        local action_idx=0
        echo
        inquirer list_input_index "$(gettext "选择 Xray 反向代理操作")" actions action_idx

        case "$action_idx" in
            0|1)
                local r_tag r_domain item_json=""
                inquirer text_input "$(gettext "输入 tag")" r_tag ""
                inquirer text_input "$(gettext "输入 domain")" r_domain ""
                JQs build item_json '{"tag": $t, "domain": $d}' --arg t "$r_tag" --arg d "$r_domain"
                if [ "$action_idx" -eq 0 ]
                then
                    if ! ProxyMutateConfigTx "xray" '.reverse.bridges = ((.reverse.bridges // []) + [$item])' --argjson item "$item_json"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 添加 Bridge 失败: \$err_detail")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已添加 Bridge \${green}\${r_tag}\${normal}")\n"
                else
                    if ! ProxyMutateConfigTx "xray" '.reverse.portals = ((.reverse.portals // []) + [$item])' --argjson item "$item_json"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 添加 Portal 失败: \$err_detail")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已添加 Portal \${green}\${r_tag}\${normal}")\n"
                fi
            ;;
            2|3)
                local r_key="bridges"
                [ "$action_idx" -eq 3 ] && r_key="portals"
                local r_opts=()
                local line
                while IFS= read -r line
                do
                    [ -n "$line" ] && r_opts+=("$line")
                done < <(JQs query "$X_CONFIG" 'if (.reverse | type) == "object" and (.reverse[$k] | type) == "array" then (.reverse[$k] | to_entries[] | select(.value | type == "object") | "\(.key + 1). \(.value.tag // "") (\(.value.domain // ""))") else empty end' --arg k "$r_key")
                if [ "${#r_opts[@]}" -eq 0 ]
                then
                    Println "$(eval_gettext "\$error 没有可删除的 \${r_key}")\n"
                    return 1
                fi
                local del_idx=0
                inquirer list_input_index "$(eval_gettext "选择要删除的 \${r_key}")" r_opts del_idx
                if ! ProxyMutateConfigTx "xray" 'del(.reverse[$k][$i])' --arg k "$r_key" --argjson i "$del_idx"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 删除 \${r_key} 失败: \$err_detail")\n"
                    return 1
                fi
                local del_item="${r_opts[$del_idx]}"
                Println "$(eval_gettext "\$info 已删除 \${r_key}: \${green}\${del_item}\${normal}")\n"
            ;;
        esac
    }
    XraySetAdvanced()
    {
        local actions=(
            "$(gettext "设置日志级别 (log)")"
            "$(gettext "配置 Observatory 测速 (observatory)")"
            "$(gettext "配置 BurstObservatory 并发测速 (burstObservatory)")"
            "$(gettext "配置 Metrics 指标 (metrics)")"
            "$(gettext "配置 API 服务 (api)")"
            "$(gettext "配置版本限制 (version)")"
            "$(gettext "配置环境变量 (env)")"
        )
        local act_idx=0
        inquirer list_input_index "$(gettext "选择 Xray 高级配置项")" actions act_idx

        case "$act_idx" in
            0)
                local levels=( "debug" "info" "warning" "error" "none" )
                local lv_idx=2
                inquirer list_input_index "$(gettext "选择日志级别 logLevel")" levels lv_idx
                local lv="${levels[lv_idx]}"
                if ! ProxyMutateConfigTx "xray" '.log = ((.log // {}) + {logLevel: $lv})' --arg lv "$lv"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 更新日志级别失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已更新 Xray logLevel 为 \$lv")\n"
            ;;
            1)
                local probe_url="" probe_interval="" selectors=""
                inquirer text_input "$(gettext "探测 URL probeURL")" probe_url "https://www.gstatic.com/generate_204"
                inquirer text_input "$(gettext "探测间隔 probeInterval (如 1m)")" probe_interval "1m"
                inquirer text_input "$(gettext "目标出站前缀 subjectSelector (逗号分隔)")" selectors "proxy"
                if ! ProxyMutateConfigTx "xray" '
                    .observatory = {
                        subjectSelector: ($sel | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                        probeURL: $url,
                        probeInterval: $intv
                    }
                ' --arg sel "$selectors" --arg url "$probe_url" --arg intv "$probe_interval"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 配置 observatory 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已更新 Xray observatory")\n"
            ;;
            2)
                local dest_url="" interval="" selectors=""
                inquirer text_input "$(gettext "目标 URL destination")" dest_url "https://www.gstatic.com/generate_204"
                inquirer text_input "$(gettext "探测间隔 interval (如 5m)")" interval "5m"
                inquirer text_input "$(gettext "目标出站前缀 subjectSelector (逗号分隔)")" selectors "proxy"
                if ! ProxyMutateConfigTx "xray" '
                    .burstObservatory = {
                        subjectSelector: ($sel | split(",") | map(gsub("^\\s+|\\s+$"; "")) | map(select(length > 0))),
                        pingConfig: {destination: $url, interval: $intv}
                    }
                ' --arg sel "$selectors" --arg url "$dest_url" --arg intv "$interval"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 配置 burstObservatory 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已更新 Xray burstObservatory")\n"
            ;;
            3)
                local m_tag="" m_listen=""
                inquirer text_input "$(gettext "Metrics tag")" m_tag "metrics_out"
                inquirer text_input "$(gettext "Metrics listen (如 127.0.0.1:11111, 可留空)")" m_listen ""
                if ! ProxyMutateConfigTx "xray" '
                    .metrics = ({tag: $tag} + (if $listen != "" then {listen: $listen} else {} end))
                ' --arg tag "$m_tag" --arg listen "$m_listen"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 配置 metrics 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已更新 Xray metrics")\n"
            ;;
            4)
                local api_tag="" api_listen=""
                inquirer text_input "$(gettext "API tag")" api_tag "api"
                inquirer text_input "$(gettext "API listen (如 127.0.0.1:10085)")" api_listen "127.0.0.1:10085"
                if ! ProxyMutateConfigTx "xray" '
                    .api = ({tag: $tag, services: ["StatsService", "HandlerService", "LoggerService"]} + (if $listen != "" then {listen: $listen} else {} end))
                    | .stats = (.stats // {})
                ' --arg tag "$api_tag" --arg listen "$api_listen"
                then
                    local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                    Println "$(eval_gettext "\$error 配置 api 失败: \$err_detail")\n"
                    return 1
                fi
                Println "$(eval_gettext "\$info 已更新 Xray api")\n"
            ;;
            5)
                local ver_min="" ver_max=""
                inquirer text_input "$(gettext "最低版本 version.min (可留空)")" ver_min ""
                inquirer text_input "$(gettext "最高版本 version.max (可留空)")" ver_max ""
                if [ -z "$ver_min" ] && [ -z "$ver_max" ]
                then
                    if ! ProxyMutateConfigTx "xray" 'del(.version)'
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 清除 version 失败: \$err_detail")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已清除 Xray version 限制")\n"
                else
                    if ! ProxyMutateConfigTx "xray" '
                        .version = ({} + (if $min != "" then {min: $min} else {} end) + (if $max != "" then {max: $max} else {} end))
                    ' --arg min "$ver_min" --arg max "$ver_max"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 配置 version 失败: \$err_detail")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已更新 Xray version")\n"
                fi
            ;;
            6)
                local env_key="" env_val=""
                inquirer text_input "$(gettext "环境变量名 (如 XRAY_LOCATION_ASSET)")" env_key ""
                if [ -z "$env_key" ]
                then
                    Println "$(eval_gettext "\$error 环境变量名不能为空")\n"
                    return 1
                fi
                inquirer text_input "$(gettext "环境变量值 (留空则删除该键)")" env_val ""
                if [ -z "$env_val" ]
                then
                    if ! ProxyMutateConfigTx "xray" '
                        if (.env | type) == "object" then
                            del(.env[$k]) | if (.env | length) == 0 then del(.env) else . end
                        else . end
                    ' --arg k "$env_key"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 删除 env 键失败: \$err_detail")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已删除 Xray env 键: \${green}\${env_key}\${normal}")\n"
                else
                    if ! ProxyMutateConfigTx "xray" '
                        .env = ((if (.env | type) == "object" then .env else {} end) + {($k): $v})
                    ' --arg k "$env_key" --arg v "$env_val"
                    then
                        local err_detail="${PROXY_LAST_VALIDATE_ERROR:-unknown}"
                        Println "$(eval_gettext "\$error 配置 env 失败: \$err_detail")\n"
                        return 1
                    fi
                    Println "$(eval_gettext "\$info 已更新 Xray env: \${green}\${env_key}\${normal}")\n"
                fi
            ;;
        esac
    }
    XrayGetLog()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.log')

        jq_path='[
            ["access"],
            ["error"],
            ["loglevel"],
            ["logLevel"],
            ["dnsLog"],
            ["maskAddress"]
        ]'

        while IFS=": " read -r path_name value
        do
            var_name="$path_name"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        log_access="${jq_access:-stdout}"
        log_error="${jq_error:-stdout}"
        log_loglevel="${jq_loglevel:-${jq_logLevel:-warning}}"
        log_dnsLog="${jq_dnsLog:-false}"
        log_maskAddress="${jq_maskAddress:-}"

        return 0
    }
    XrayGetApi()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.api')

        jq_path='[
            ["tag"],
            ["listen"],
            ["services"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="api_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        return 0
    }
    XrayGetMetrics()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.metrics')

        jq_path='[
            ["tag"],
            ["listen"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="metrics_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        return 0
    }
    XrayGetObservatory()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.observatory | if type == "object" then (if has("probeURL") or has("probeUrl") then . + {probeURL: (.probeURL // .probeUrl), probeUrl: (.probeURL // .probeUrl)} else . end) else . end')

        jq_path='[
            ["subjectSelector"],
            ["probeURL"],
            ["probeUrl"],
            ["probeInterval"],
            ["enableConcurrency"]
        ]'

        while IFS=": " read -r path_name value
        do
            var_name="observatory_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        return 0
    }
    XrayGetBurstObservatory()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.burstObservatory')

        jq_path='[
            ["subjectSelector"],
            ["pingConfig","destination"],
            ["pingConfig","connectivity"],
            ["pingConfig","interval"],
            ["pingConfig","sampling"],
            ["pingConfig","timeout"],
            ["pingConfig","httpMethod"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="burstObservatory_${path_name#*_}"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        burstObservatory_pingConfig_destination=${burstObservatory_pingConfig_destination:-https://connectivitycheck.gstatic.com/generate_204}
        burstObservatory_pingConfig_interval=${burstObservatory_pingConfig_interval:-1m}
        burstObservatory_pingConfig_sampling=${burstObservatory_pingConfig_sampling:-10}
        burstObservatory_pingConfig_timeout=${burstObservatory_pingConfig_timeout:-5s}
        burstObservatory_pingConfig_httpMethod=${burstObservatory_pingConfig_httpMethod:-HEAD}

        return 0
    }
    XrayGetGeodata()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.geodata')

        jq_path='[
            ["cron"],
            ["outbound"],
            ["assets","url"],
            ["assets","file"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name="$path_name"
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        geodata_cron=${jq_cron:-}
        geodata_outbound=${jq_outbound:-}

        if [ -z "${jq_assets_url:-}" ]
        then
            geodata_assets_count=0
            return 0
        fi

        IFS="${delimiters[2]}" read -r -a geodata_assets_url <<< "$jq_assets_url"
        IFS="${delimiters[2]}" read -r -a geodata_assets_file <<< "$jq_assets_file"

        geodata_assets_count="${#geodata_assets_url[@]}"

    }
    XrayGetVersion()
    {
        SetDelimiters

        jq_payload=$(JQs flat "$X_CONFIG" '.version')

        jq_path='[
            ["min"],
            ["max"]
        ]'

        while IFS=": " read -r path_name value; do
