then
    SwapValidateSize()
    {
        if [[ $1 =~ ^[0-9]+$ ]]
        then
            return 0
        fi

        return 1
    }

    Swap()
    {
        local swap_options=( "$(gettext "创建")" "$(gettext "移除")" )
        echo
        inquirer list_input_index "$(gettext "请选择")" swap_options swap_options_index

        if [ $swap_options_index -eq 0 ]
        then
            if [ -f "$DEPENDS_ROOT"/swapfile ]
            then
                Println "$(eval_gettext "\$DEPENDS_ROOT/swapfile 已存在")\n"
                return 1
            elif [ -f /swapfile ] 
            then
                Println "$(gettext "/swapfile 已存在")\n"
                return 1
            fi

            echo
            inquirer text_input "$(gettext "请输入 swap 大小(MB)")" swapsize 500 SwapValidateSize "$(gettext "swap 大小必须是数字")"

            mkdir -p "$DEPENDS_ROOT"

            if [ "$dist" == "mac" ] 
            then
                Println "$(eval_gettext "\$tip 可能需要输入密码")"
                sudo mkfile ${swapsize}m "$DEPENDS_ROOT"/swapfile
                sudo chmod 0600 "$DEPENDS_ROOT"/swapfile
                sudo mdutil -a -i -o SWAP="$DEPENDS_ROOT"/swapfile
                sudo mdutil -a -s
            else
                fallocate -l ${swapsize}M "$DEPENDS_ROOT"/swapfile
                chmod 600 "$DEPENDS_ROOT"/swapfile
                mkswap "$DEPENDS_ROOT"/swapfile
                swapon "$DEPENDS_ROOT"/swapfile
                echo "$DEPENDS_ROOT/swapfile none swap defaults 0 0" >> /etc/fstab
            fi

            Println "$(gettext "swap 创建成功")\n"
        else
            if [ ! -f /swapfile ] && [ ! -f "$DEPENDS_ROOT"/swapfile ]
            then
                Println "$(gettext "swapfile 不存在")\n"
                return 1
            fi

            for swapfile in /swapfile "$DEPENDS_ROOT"/swapfile
            do
                if [ ! -f "$swapfile" ] 
                then
                    continue
                fi

                if [ "$dist" == "mac" ] 
                then
                    Println "$(eval_gettext "\$tip 可能需要输入密码")"
                    sudo mdutil -d -i -o SWAP="$swapfile"
                else
                    sed -i '/swapfile/d' /etc/fstab
                    echo 3 > /proc/sys/vm/drop_caches
                    swapoff -a
                fi

                rm -f "$swapfile"
            done

            Println "$(gettext "swap 移除成功")\n"
        fi
    }

    ShFileCheck

