 ${green}13.${normal} $(gettext "删除 APP 路由")
 ${green}14.${normal} $(gettext "设置 v2ray APP")
 ${green}15.${normal} $(gettext "设置 Xray APP")
 ${green}16.${normal} $(gettext "设置 APP 定时重启")
 ${green}17.${normal} $(gettext "开启 APP 定时重启")
 ${green}18.${normal} $(gettext "关闭 APP 定时重启")
 ${green}19.${normal} $(gettext "更新脚本")

 $(eval_gettext "\${tip} 输入: ibm 打开面板")\n\n"
            IBM_CF_MENU_LOCALE="${sh_locale:-zh_CN}"
        fi

