    IbmInstallCfCli()
    {
        if [[ -x $(command -v ibmcloud) ]] 
        then
            Println "$(eval_gettext "\$error IBM CF CLI 已存在")\n"
            exit 1
        fi
        Println "$(eval_gettext "\$info 安装 IBM CF CLI ...")"
        curl -sL https://ibm.biz/idt-installer | bash
        ibmcloud cf install
    }

    IbmUpdateCfCli()
    {
        if [[ ! -x $(command -v ibmcloud) ]] 
        then
            Println "$(eval_gettext "\$error IBM CF CLI 未安装")\n"
            exit 1
        fi
        Println "$(eval_gettext "\$info 更新 IBM CF CLI ...")"
        ibmcloud update -f
        ibmcloud cf install -f
    }

    IbmUninstallCfCli()
    {
        if [[ ! -x $(command -v ibmcloud) ]] 
        then
            Println "$(eval_gettext "\$error IBM CF CLI 未安装")\n"
            exit 1
        fi

        echo
        ExitOnList n "`gettext \"确定删除 IBM CF CLI\"`"

        EXIT_STATUS=0

        rm -Rf /usr/local/ibmcloud || EXIT_STATUS=$?

        rm -f /usr/local/bin/ibmcloud || EXIT_STATUS=$?
        rm -f /usr/local/bin/bluemix || EXIT_STATUS=$?
        rm -f /usr/local/bin/bx || EXIT_STATUS=$?
        rm -f /usr/local/bin/ibmcloud-analytics || true

        if [ $EXIT_STATUS -eq 0 ]
        then
            Println "$(eval_gettext "\$info 删除成功")\n"
        else
            Println "$(eval_gettext "\$error 发生错误")\n"
        fi
    }

    ShFileCheck

    JQInstall

    if [ "${1:-}" == "v2" ] 
    then
        v2ray_name="v2ray"
        v2ray_package_name="v2ray"
        tls_name="TLS"
        V2CTL_FILE="$IBM_APPS_ROOT/ibm_v2ray/v2ctl"
        V2_CONFIG="$IBM_APPS_ROOT/ibm_v2ray/config.json"
        IbmV2rayMenu
    elif [ "${1:-}" == "x" ] 
    then
        v2ray_name="xray"
        v2ray_package_name="Xray"
        tls_name="XTLS"
        V2CTL_FILE="$IBM_APPS_ROOT/ibm_xray/xray"
        V2_CONFIG="$IBM_APPS_ROOT/ibm_xray/config.json"
        IbmV2rayMenu
    elif [ "${1:-}" == "cron" ] 
    then
        IbmCfAppCronExec
    else
        IbmCfMenu
    fi

    exit 0
elif [ "$self" == "cf" ]
then


    WranglerInstall()
    {
        if [[ -x $(command -v cargo) ]] 
        then
            echo
            inquirer list_input "$(gettext "检测到 cargo, 是否使用 cargo 安装 wrangler, 否则使用 npm 安装")" ny_options user_cargo_yn

            if [[ $user_cargo_yn == "$i18n_yes" ]] 
            then
                cargo install wrangler
                Println "$(eval_gettext "\$info wrangler 安装成功")\n"
                exit 0
            fi
        fi
        if [[ ! -x $(command -v node) ]] || [[ ! -x $(command -v npm) ]] 
        then
            NodejsInstall
        fi
        Println "$(eval_gettext "\$info 国内可能会因网络原因安装失败, 可以手动下载 wrangler 覆盖 ~/.wrangler/bin/wrangler ...")\n"
        npm i @cloudflare/wrangler -g --unsafe-perm=true --allow-root
        Println "$(eval_gettext "\$info wrangler 安装成功")\n"
    }

    WranglerUpdate()
    {
        if [[ ! -x $(command -v wrangler) ]] 
        then
            Println "$(eval_gettext "\$error wrangler 未安装")\n"
            exit 1
        fi
        if [[ -x $(command -v cargo) ]] 
        then
            echo
            inquirer list_input "$(gettext "检测到 cargo, 是否使用 cargo 更新 wrangler, 否则使用 npm 更新")" ny_options user_cargo_yn

            if [[ $user_cargo_yn == "$i18n_yes" ]] 
            then
                cargo install wrangler --force
                Println "$(eval_gettext "\$info wrangler 更新成功")\n"
                exit 0
            fi
        fi
        if [[ ! -x $(command -v node) ]] || [[ ! -x $(command -v npm) ]] 
        then
            NodejsInstall
        fi
        npm uninstall -g @cloudflare/wrangler && npm install -g @cloudflare/wrangler --unsafe-perm=true --allow-root
        Println "$(eval_gettext "\$info wrangler 更新成功")\n"
    }

    CloudflareSetHostKey()
    {
        Println "$(gettext "请输入 CFP host key")"
        read -p "$i18n_default_cancel" cf_host_key
        [ -z "$cf_host_key" ] && Println "$i18n_canceled...\n" && exit 1
        Println "$(eval_gettext "\$info 稍等...")"
        IFS=" " read -r result msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
            -d 'act=zone_list' \
            -d "host_key=$cf_host_key" \
            -d 'limit=1' \
            -d 'offset=0' \
            -d 'zone_status=ALL' \
            -d 'sub_status=ALL' \
            | $JQ_FILE '[.result,.msg]|join(" ")'
        ) || true

        result=${result#\"}
        msg=${msg%\"}

        if [ -z "$result" ] || [ "$result" == "error" ]
        then
            Println "$error ${msg:-$(gettext "超时, 请重试")}\n" && exit 1
        fi

        Println "  CFP: ${green} $cf_host_key ${normal}\n"
    }

    CloudflareSetHostName()
    {
        Println "$(gettext "请输入 CFP 邮箱或名称, 便于区分 host key")"
        read -p "$i18n_default_cancel" cf_host_name
        [ -z "$cf_host_name" ] && Println "$i18n_canceled...\n" && exit 1
        Println "$(eval_gettext "  CFP 邮箱或名称: \${green} \$cf_host_name \${normal}")\n"
    }

    CloudflareAddHost()
    {
        CloudflareSetHostKey
        CloudflareSetHostName

        if [ ! -s "$CF_CONFIG" ] 
        then
            printf '{"%s":[],"%s":[]}' "users" "hosts" > "$CF_CONFIG"
        fi

        new_host=$(
        $JQ_FILE -n --arg name "$cf_host_name" --arg key "$cf_host_key" \
            '{
                name: $name,
                key: $key,
                free: 0,
                zones: []
            }'
        )

        jq_path='["hosts"]'
        JQ add "$CF_CONFIG" "[$new_host]"
        Println "$(eval_gettext "\$info CFP 添加成功")\n"
    }

    CloudflareSetUserEmail()
    {
        Println "$(gettext "请输入用户邮箱")"
        while read -p "$i18n_default_cancel" cf_user_email 
        do
            [ -z "$cf_user_email" ] && Println "$i18n_canceled...\n" && exit 1
            if [[ $cf_user_email =~ ^[A-Za-z0-9]([a-zA-Z0-9_\.\-]*)@([A-Za-z0-9]+)([a-zA-Z0-9\.\-]*)\.([A-Za-z]{2,})$ ]] 
            then
                break
            else
                Println "$(eval_gettext "\$error 邮箱格式错误, 请重新输入")\n"
            fi
        done
        Println "$(eval_gettext "  用户邮箱: \${green} \$cf_user_email \${normal}")\n"
    }

    CloudflareSetUserPass()
    {
        Println "$(gettext "输入用户密码")"
        while read -p "$(gettext "(默认: 随机): ")" cf_user_pass 
        do
            [ -z "$cf_user_pass" ] && cf_user_pass=$(RandStr)
            if [[ ${#cf_user_pass} -ge 8 ]] 
            then
                break
            else
                Println "$(eval_gettext "\$error 账号密码至少 8 位")\n"
            fi
        done
        Println "$(eval_gettext "  用户密码: \${green} \$cf_user_pass \${normal}")\n"
    }

    CloudflareSetUserToken()
    {
        Println "$(eval_gettext "\$tip 需要 workers 和 zone(区域) 编辑权限, 以及 zone(区域) 的 Analytics 读取权限")"
        inquirer text_input "$(gettext "请输入用户 Token"): " cf_user_token "$i18n_blank"
        if [ -n "$cf_user_token" ] 
        then
            if [[ $(curl -s -X GET "https://api.cloudflare.com/client/v4/user/tokens/verify" \
                -H "Authorization: Bearer $cf_user_token" \
                -H "Content-Type: application/json" | $JQ_FILE -r '.success') = false ]]
            then
                Println "$(eval_gettext "\$error Token 验证失败")\n"
                exit 1
            fi
        fi
    }

    CloudflareSetUserKey()
    {
        echo
        inquirer text_input "$(gettext "请输入用户 Global API KEY: ")" cf_user_api_key "$i18n_blank"
    }

    CloudflareGetHosts()
    {
        cf_hosts_list=""
        cf_hosts_count=0
        cf_hosts_name=()
        cf_hosts_key=()
        cf_hosts_zones_count=()
        cf_hosts_zone_name=()
        cf_hosts_zone_resolve_to=()
        cf_hosts_zone_user_email=()
        cf_hosts_zone_user_unique_id=()
        cf_hosts_zone_always_use_https=()
        cf_hosts_zone_ssl=()
        cf_hosts_zone_subdomains=()
        while IFS="^" read -r name key zones_count zone_name zone_resolve_to zone_user_email zone_user_unique_id zone_always_use_https zone_ssl zone_subdomains
        do
            cf_hosts_count=$((cf_hosts_count+1))
            name=${name#\"}
            cf_hosts_name+=("$name")
            cf_hosts_key+=("$key")
            cf_hosts_zones_count+=("$zones_count")
            cf_hosts_zone_name+=("$zone_name")
            cf_hosts_zone_resolve_to+=("$zone_resolve_to")
            cf_hosts_zone_user_email+=("$zone_user_email")
            zone_user_unique_id=${zone_user_unique_id%\"}
            cf_hosts_zone_user_unique_id+=("$zone_user_unique_id")
            cf_hosts_zone_always_use_https+=("$zone_always_use_https")
            cf_hosts_zone_ssl+=("$zone_ssl")
            zone_subdomains=${zone_subdomains%\"}
            cf_hosts_zone_subdomains+=("$zone_subdomains")

            cf_hosts_list="$cf_hosts_list ${green}$cf_hosts_count.${normal}${indent_6}CFP: ${green}$name${normal}  host key: ${green}$key${normal}  $(gettext "域名数"): ${green}$zones_count${normal}\n\n"
        done < <($JQ_FILE '.hosts[]|[.name,.key,(.zones|length),([.zones[].name]|join("|")),([.zones[].resolve_to]|join("|")),([.zones[].user_email]|join("|")),([.zones[].user_unique_id]|join("|")),([.zones[].always_use_https]|join("|")),([.zones[].ssl]|join("|")),([.zones[].subdomains]|join("|"))]|join("^")' "$CF_CONFIG")
        return 0
    }

    CloudflareListHosts()
    {
        if [ ! -s "$CF_CONFIG" ] 
        then
            Println "$(eval_gettext "\$error 请先添加 CFP")\n" && exit 1
        fi

        CloudflareGetHosts

        if [ "$cf_hosts_count" -gt 0 ] 
        then
            Println "$cf_hosts_list"
        else
            Println "$(eval_gettext "\$error 请先添加 CFP")\n" && exit 1
        fi
    }

    CloudflareListHost()
    {
        CloudflareListHosts
    }

    CloudflareSetZoneResolve()
    {
        Println "$(gettext "请输入 CNAME 经 cloudflare 中转后默认解析到的地址, 比如 resolve-to-cloudflare.example.com")"
        echo -e "$(eval_gettext "\$tip 此地址应指向源站")\n"
        read -p "$i18n_default_cancel" cf_zone_resolve_to
        [ -z "$cf_zone_resolve_to" ] && Println "$i18n_canceled...\n" && exit 1
        Println "$(eval_gettext "  默认解析地址: \${green} \$cf_zone_resolve_to \${normal}")\n"
    }

    CloudflareSetZoneAlwaysUseHttps()
    {
        echo

        if [[ ${cf_zone_always_use_https:-} == "on" ]] 
        then
            inquirer list_input "$(gettext "始终使用 https 访问域名, 开启后客户端和 cloudflare 之间连接始终为 https")" yn_options cf_zone_always_use_https_yn
        else
            inquirer list_input "$(gettext "始终使用 https 访问域名, 开启后客户端和 cloudflare 之间连接始终为 https")" ny_options cf_zone_always_use_https_yn
        fi

        if [[ $cf_zone_always_use_https_yn == "$i18n_yes" ]] 
        then
            cf_zone_always_use_https='on'
        else
            cf_zone_always_use_https='off'
        fi

        Println "$(eval_gettext "  始终使用 https: \${green} \$cf_zone_always_use_https \${normal}")\n"
    }

    CloudflareSetZoneSsl()
    {
        Println "$(eval_gettext "选择域名 \${green}\$cf_zone_name\${normal} SSL 设置")

  ${green}1.${normal} $(gettext "off ( 客户端 <= http => cloudflare <= http => 源站)")
  ${green}2.${normal} $(gettext "flexible ( 客户端 <= https => cloudflare <= http => 源站)")
  ${green}3.${normal} $(gettext "full ( 客户端 <= https => cloudflare <= https => 源站[ SSL证书/自定义证书 ])")
  ${green}4.${normal} $(gettext "strict ( 客户端 <= https => cloudflare <= https => 源站[ CA SSL证书 ])")
        "
        case ${cf_zone_ssl:-} in
            "off") ssl_num=1
            ;;
            "flexible"|"") ssl_num=2
            ;;
            "full") ssl_num=3
            ;;
            "strict") ssl_num=4
            ;;
        esac
        while read -p "$(eval_gettext "(默认: \$ssl_num): ")" cf_zone_ssl_num
        do
            case $cf_zone_ssl_num in
                ""|2) 
                    cf_zone_ssl='flexible'
                    break
                ;;
                1) 
                    cf_zone_ssl='off'
                    break
                ;;
                3) 
                    cf_zone_ssl='full'
                    break
                ;;
                4) 
                    cf_zone_ssl='strict'
                    break
                ;;
                *) 
                    Println "$error $i18n_input_correct_no\n"
                ;;
            esac
        done
        Println "$(eval_gettext "  SSL 设置: \${green} \$cf_zone_ssl \${normal}")\n"
    }

    CloudflareGetUsers()
    {
        SetDelimiters
        cf_users_list=""
        cf_users_count=0
        cf_users_email=()
        cf_users_pass=()
        cf_users_token=()
        cf_users_api_key=()
        while IFS="$field_sep" read -r email pass token key
        do
            cf_users_count=$((cf_users_count+1))
            cf_users_email+=("$email")
            cf_users_pass+=("$pass")
            cf_users_token+=("$token")
            cf_users_api_key+=("$key")

            cf_users_list="$cf_users_list ${green}$cf_users_count.${normal}${indent_6}$(gettext "邮箱"): ${green}$email${normal}  $i18n_password: ${green}$pass${normal}\n${indent_6}Token: ${green}${token:-$i18n_none}${normal}\n${indent_6}Key: ${green}${key:-$i18n_none}${normal}\n\n"
        done < <(JQs query "$CF_CONFIG" '
            (if type == "object" and (.users | type) == "array" then .users else [] end)
            | map(select(type == "object"))[]
            | [(.email // "" | tostring), (.pass // "" | tostring), (.token // "" | tostring), (.key // "" | tostring)]
            | join($sep)
        ' --arg sep "$field_sep")
        return 0
    }

    CloudflareListUsers()
    {
        if [ ! -s "$CF_CONFIG" ] 
        then
            Println "$(eval_gettext "\$error 请先添加用户")\n" && exit 1
        fi

        CloudflareGetUsers

        if [ "$cf_users_count" -gt 0 ] 
        then
            Println "$cf_users_list"
        else
            Println "$(eval_gettext "\$error 没有用户")\n"
        fi
    }

    CloudflareAddUser()
    {
        CloudflareSetUserEmail
        CloudflareSetUserPass
        CloudflareSetUserToken
        CloudflareSetUserKey

        if [ ! -s "$CF_CONFIG" ] 
        then
            printf '{"%s":[],"%s":[]}' "users" "hosts" > "$CF_CONFIG"
        fi

        new_user=$(
        $JQ_FILE -n --arg email "$cf_user_email" --arg pass "$cf_user_pass" \
            --arg token "$cf_user_token" --arg key "$cf_user_api_key" \
            '{
                email: $email,
                pass: $pass,
                token: $token,
                key: $key
            }'
        )

        jq_path='["users"]'
        JQ add "$CF_CONFIG" "[$new_user]"
        Println "$(eval_gettext "\$info 用户添加成功")\n"
    }

    CloudflareListUser()
    {
        CloudflareListUsers

        if [ "$cf_users_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加用户")\n"
            exit 1
        fi

        echo -e "$(gettext "选择用户")"
        while read -p "$i18n_default_cancel" cf_users_num
        do
            case "$cf_users_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_users_num" -gt 0 ] && [ "$cf_users_num" -le "$cf_users_count" ]
                    then
                        cf_users_index=$((cf_users_num-1))
                        cf_user_email=${cf_users_email[cf_users_index]}
                        cf_user_pass=${cf_users_pass[cf_users_index]}
                        cf_user_token=${cf_users_token[cf_users_index]}
                        cf_user_api_key=${cf_users_api_key[cf_users_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        if [ -n "$cf_user_api_key" ] 
        then
            curl_header_auth_email="X-Auth-Email: $cf_user_email"
            curl_header_auth_key="X-Auth-Key: $cf_user_api_key"
            curl_header_auth_token=""
        else
            curl_header_auth_email=""
            curl_header_auth_key=""
            curl_header_auth_token="Authorization: Bearer $cf_user_token"
        fi

        SetDelimiters

        response=$(
            curl -s -X GET -H ''"$curl_header_auth_email"'' -H ''"$curl_header_auth_key"'' -H ''"$curl_header_auth_token"'' \
            -H 'Content-Type: application/json' https://api.cloudflare.com/client/v4/accounts
        )

        jq_payload=$(JQs flat "$response")

        jq_path='[
            ["success"],
            ["errors","message"],
            ["result","id"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        success="$jq_success"
        error_message="$jq_errors_message"
        CF_ACCOUNT_ID="$jq_result_id"

        if [ "$success" = false ] 
        then
            Println "$error $(gettext "获取账号 ID 失败"): ${error_message//${delimiters[2]}/, }\n"
            exit 1
        fi

        end_epoch=$(date --utc -d 'tomorrow 00:00:00' +%s)
        start_epoch=$(date --utc -d 'today 00:00:00' +%s)
        start_date=$(date --utc --date="@$start_epoch" +'%Y-%m-%dT%H:%m:%SZ')
        end_date=$(date --utc --date="@$end_epoch" +'%Y-%m-%dT%H:%m:%SZ')

        PAYLOAD='{ "query":
        "query {
            viewer {
            accounts(filter: { accountTag: $accountTag }) {
            workersInvocationsAdaptive(
                filter: {
                datetime_geq: $datetimeStart,
                datetime_leq: $datetimeEnd
                }
                limit: 100
            ) {
                sum {
                    requests
                    subrequests
                    errors
                }
                }
            }
            }
        }",'

        PAYLOAD="$PAYLOAD

        \"variables\": {
            \"accountTag\": \"$CF_ACCOUNT_ID\",
            \"datetimeStart\": \"$start_date\",
            \"datetimeEnd\": \"$end_date\"
        }
        }"

        response=$(
            curl -s -H 'Content-Type: application/json' -H ''"$curl_header_auth_email"'' -H ''"$curl_header_auth_key"'' -H ''"$curl_header_auth_token"'' \
            --data "$(echo $PAYLOAD)" https://api.cloudflare.com/client/v4/graphql
        )

        jq_payload=$(JQs flat "$response")

        jq_path='[
            ["data","viewer","accounts","workersInvocationsAdaptive","sum","requests"],
            ["errors","message"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        cf_workers_requests="$jq_data_viewer_accounts_workersInvocationsAdaptive_sum_requests"
        error_message="$jq_errors_message"

        if [ -z "$cf_workers_requests" ] 
        then
            Println "$error $(gettext "获取 workers 访问数失败"): ${error_message//${delimiters[2]}/, }\n"
            exit 1
        fi

        Println "$(eval_gettext "\$info workers 访问总数: \$cf_workers_requests")\n"
    }

    CloudflareAddZone()
    {
        CloudflareListHosts

        echo -e "$(gettext "选择 CFP")"
        while read -p "$i18n_default_cancel" cf_hosts_num
        do
            case "$cf_hosts_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_hosts_num" -gt 0 ] && [ "$cf_hosts_num" -le "$cf_hosts_count" ]
                    then
                        cf_hosts_index=$((cf_hosts_num-1))
                        cf_host_name=${cf_hosts_name[cf_hosts_index]}
                        cf_host_key=${cf_hosts_key[cf_hosts_index]}
                        cf_host_zone_name=${cf_hosts_zone_name[cf_hosts_index]}
                        IFS="|" read -r -a cf_host_zones_name <<< "$cf_host_zone_name"
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        CloudflareListUsers

        if [ "$cf_users_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加用户")\n"
            exit 1
        fi

        echo -e "$(gettext "选择用户")"
        while read -p "$i18n_default_cancel" cf_users_num
        do
            case "$cf_users_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_users_num" -gt 0 ] && [ "$cf_users_num" -le "$cf_users_count" ]
                    then
                        cf_users_index=$((cf_users_num-1))
                        cf_user_email=${cf_users_email[cf_users_index]}
                        cf_user_pass=${cf_users_pass[cf_users_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        Println "$(eval_gettext "\$info 稍等...")"
        result=""
        until [ "$result" == "success" ] 
        do
            random_number=$(od -An -N6 -t u8 < /dev/urandom)
            cf_user_unique_id=${random_number: -12}
            IFS="^" read -r result err_code msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
                -d 'act=user_create' \
                -d "host_key=$cf_host_key" \
                -d "cloudflare_email=$cf_user_email" \
                -d "cloudflare_pass=$cf_user_pass" \
                -d "unique_id=$cf_user_unique_id" \
                | $JQ_FILE '[.result,.err_code,.msg]|join("^")'
            ) || true

            result=${result#\"}
            msg=${msg%\"}
            if [ "$result" == "error" ] 
            then
                Println "$error $msg"
            fi
        done

        Println "$(gettext "请输入根域名")"
        echo -e "$(eval_gettext "\$tip 如果域名已经由 cloudflare 解析, 请先到官方 cloudflare 面板中删除")\n"
        while read -p "$i18n_default_cancel" cf_zone_name
        do
            if [ -z "$cf_zone_name" ] 
            then
                Println "$i18n_canceled...\n"
                exit 1
            elif [[ $cf_zone_name =~ ^([a-zA-Z0-9][\-a-zA-Z0-9]*\.)+[\-a-zA-Z0-9]{2,20}$ ]] 
            then
                Println "$(eval_gettext "  域名: \${green} \$cf_zone_name \${normal}")\n"
                break
            else
                Println "$(eval_gettext "\$error 输入错误, 请输入根域名, 不能是二级域名")"
            fi
        done

        for cf_host_zone_name in ${cf_host_zones_name[@]+"${cf_host_zones_name[@]}"}
        do
            if [ "$cf_host_zone_name" == "$cf_zone_name" ] 
            then
                Println "$(eval_gettext "\$error 域名已经存在")\n"
                exit 1
            fi
        done

        CloudflareSetZoneResolve
        CloudflareSetZoneAlwaysUseHttps
        CloudflareSetZoneSsl

        new_zone=$(
        $JQ_FILE -n --arg name "$cf_zone_name" --arg resolve_to "$cf_zone_resolve_to" \
            --arg user_email "$cf_user_email" --arg user_unique_id "$cf_user_unique_id" \
            --arg always_use_https "$cf_zone_always_use_https" --arg ssl "$cf_zone_ssl" \
            '{
                name: $name,
                resolve_to: $resolve_to,
                user_email: $user_email,
                user_unique_id: $user_unique_id | tonumber,
                always_use_https: $always_use_https,
                ssl: $ssl
            }'
        )

        jq_path='["hosts",'"$cf_hosts_index"',"zones"]'
        JQ add "$CF_CONFIG" "[$new_zone]"
        Println "$(eval_gettext "\$info 源站添加成功")\n"
    }

    CloudflareListZones()
    {
        CloudflareListHosts

        echo -e "$(gettext "选择 CFP")"
        while read -p "$i18n_default_cancel" cf_hosts_num
        do
            case "$cf_hosts_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_hosts_num" -gt 0 ] && [ "$cf_hosts_num" -le "$cf_hosts_count" ]
                    then
                        cf_hosts_index=$((cf_hosts_num-1))
                        cf_host_name=${cf_hosts_name[cf_hosts_index]}
                        cf_host_key=${cf_hosts_key[cf_hosts_index]}
                        cf_zones_count=${cf_hosts_zones_count[cf_hosts_index]}
                        cf_zone_name=${cf_hosts_zone_name[cf_hosts_index]}
                        cf_zone_resolve_to=${cf_hosts_zone_resolve_to[cf_hosts_index]}
                        cf_zone_user_email=${cf_hosts_zone_user_email[cf_hosts_index]}
                        cf_zone_user_unique_id=${cf_hosts_zone_user_unique_id[cf_hosts_index]}
                        cf_zone_always_use_https=${cf_hosts_zone_always_use_https[cf_hosts_index]}
                        cf_zone_ssl=${cf_hosts_zone_ssl[cf_hosts_index]}
                        cf_zone_subdomains=${cf_hosts_zone_subdomains[cf_hosts_index]}
                        IFS="|" read -r -a cf_zones_name <<< "$cf_zone_name"
                        IFS="|" read -r -a cf_zones_resolve_to <<< "$cf_zone_resolve_to"
                        IFS="|" read -r -a cf_zones_user_email <<< "$cf_zone_user_email"
                        IFS="|" read -r -a cf_zones_user_unique_id <<< "$cf_zone_user_unique_id"
                        IFS="|" read -r -a cf_zones_always_use_https <<< "${cf_zone_always_use_https}|"
                        IFS="|" read -r -a cf_zones_ssl <<< "${cf_zone_ssl}|"
                        IFS="|" read -r -a cf_zones_subdomains <<< "${cf_zone_subdomains}|"
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        cf_zones_list=""
        for((i=0;i<cf_zones_count;i++));
        do
            cf_zones_list="$cf_zones_list ${green}$((i+1)).${normal}${indent_6}$(gettext "源站"): ${green}${cf_zones_name[i]}${normal} $(gettext "用户"): ${green}${cf_zones_user_email[i]}${normal}\n${indent_6}$(gettext "始终 https"): ${green}${cf_zones_always_use_https[i]:-off}${normal}  ssl: ${green}${cf_zones_ssl[i]:-flexible}${normal}\n\n"
        done

        [ -z "$cf_zones_list" ] && Println "$(eval_gettext "\$error 请先添加源站")\n" && exit 1

        Println "$cf_zones_list"
    }

    CloudflareListZone()
    {
        CloudflareListZones
    }

    CloudflareGetZone()
    {
        IFS="^" read -r result cf_zone_hosted_cnames cf_zone_forward_tos cf_zone_ssl_status cf_zone_ssl_meta_tag msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
            -d 'act=zone_lookup' \
            -d "host_key=$cf_host_key" \
            -d "user_key=$cf_user_key" \
            -d "zone_name=$cf_zone_name" \
            | $JQ_FILE '[.result,([(.response.hosted_cnames| if .== null then {} else . end)|to_entries[]
            |([.key,.value]|join("="))]
            |join("|")),([(.response.forward_tos| if .== null then {} else . end)|to_entries[]
            |([.key,.value]|join("="))]
            |join("|")),.response.ssl_status,.response.ssl_meta_tag,.msg]|join("^")'
        ) || true

        result=${result#\"}
        msg=${msg%\"}

        if [ -z "$result" ] || [ "$result" == "error" ]
        then
            Println "$error ${msg:-$(gettext "超时, 请重试")}\n" && exit 1
        fi

        IFS="|" read -r -a cf_zone_hosted_cnames_arr <<< "$cf_zone_hosted_cnames"
        IFS="|" read -r -a cf_zone_forward_tos_arr <<< "$cf_zone_forward_tos"

        cf_hosted_cnames=()
        cf_resolve_tos=()
        cf_forward_tos=()

        for cf_zone_hosted_cname in "${cf_zone_hosted_cnames_arr[@]}"
        do
            cf_hosted_cname=${cf_zone_hosted_cname%%=*}
            cf_resolve_to=${cf_zone_hosted_cname#*=}
            cf_hosted_cnames+=("$cf_hosted_cname")
            cf_resolve_tos+=("$cf_resolve_to")
            for cf_zone_forward_to in "${cf_zone_forward_tos_arr[@]}"
            do
                if [ "${cf_zone_forward_to%%=*}" == "$cf_hosted_cname" ] 
                then
                    cf_forward_tos+=("${cf_zone_forward_to#*=}")
                    break
                fi
            done
        done
    }

    CloudflareMoveZone()
    {
        CloudflareListZones

        echo -e "$(gettext "选择源站")"
        while read -p "$i18n_default_cancel" cf_zones_num
        do
            case "$cf_zones_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_zones_num" -gt 0 ] && [ "$cf_zones_num" -le "$cf_zones_count" ]
                    then
                        cf_zones_index=$((cf_zones_num-1))
                        cf_zone_name=${cf_zones_name[cf_zones_index]}
                        cf_zone_resolve_to=${cf_zones_resolve_to[cf_zones_index]}
                        cf_user_email=${cf_zones_user_email[cf_zones_index]}
                        cf_user_unique_id=${cf_zones_user_unique_id[cf_zones_index]}
                        cf_zone_always_use_https=${cf_zones_always_use_https[cf_zones_index]}
                        cf_zone_ssl=${cf_zones_ssl[cf_zones_index]}
                        cf_zone_subdomains=${cf_zones_subdomains[cf_zones_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        CloudflareGetUser

        CloudflareGetZone

        Println "$(eval_gettext "\$info 删除源站 ...")"

        IFS="^" read -r result err_code msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
            -d 'act=zone_delete' \
            -d "host_key=$cf_host_key" \
            -d "user_key=$cf_user_key" \
            -d "zone_name=$cf_zone_name" \
            | $JQ_FILE '[.result,.err_code,.msg]|join("^")'
        ) || true

        result=${result#\"}
        msg=${msg%\"}

        if [ -z "$result" ] || [ "$result" == "error" ]
        then
            if [ "$err_code" -eq 115 ] || [ "$err_code" -eq 703 ]
            then
                Println "$(eval_gettext "\$error 此用户已被 CFP 删除或未添加成功, 可以到 Cloudflare 官网手动删除源站或者重新添加 !")"
            else
                Println "$error ${msg:-$(gettext "超时, 请重试")}\n"
            fi
            exit 1
        else
            jq_path='["hosts",'"$cf_hosts_index"',"zones",'"$cf_zones_index"']'
            JQ delete "$CF_CONFIG"
            Println "$(eval_gettext "\$info \$cf_zone_name 删除成功")"
        fi

        CloudflareListHosts

        echo -e "$(gettext "选择移动到的 CFP")"
        while read -p "$i18n_default_cancel" cf_hosts_num
        do
            case "$cf_hosts_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_hosts_num" -gt 0 ] && [ "$cf_hosts_num" -le "$cf_hosts_count" ]
                    then
                        cf_hosts_index=$((cf_hosts_num-1))
                        cf_host_name=${cf_hosts_name[cf_hosts_index]}
                        cf_host_key=${cf_hosts_key[cf_hosts_index]}
                        cf_host_zone_name=${cf_hosts_zone_name[cf_hosts_index]}
                        IFS="|" read -r -a cf_host_zones_name <<< "$cf_host_zone_name"
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        for cf_host_zone_name in "${cf_host_zones_name[@]}"
        do
            if [ "$cf_host_zone_name" == "$cf_zone_name" ] 
            then
                Println "$(eval_gettext "\$error 域名已经存在")\n"
                return 0
            fi
        done

        CloudflareListUsers

        if [ "$cf_users_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加用户")\n"
            exit 1
        fi

        echo -e "$(gettext "选择移动到的用户")"
        while read -p "$i18n_default_cancel" cf_users_num
        do
            case "$cf_users_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_users_num" -gt 0 ] && [ "$cf_users_num" -le "$cf_users_count" ]
                    then
                        cf_users_index=$((cf_users_num-1))
                        cf_user_email=${cf_users_email[cf_users_index]}
                        cf_user_pass=${cf_users_pass[cf_users_index]}
                        cf_user_api_key=${cf_users_api_key[cf_users_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        Println "$(eval_gettext "\$info 移动中 ...")"
        cf_user_key=""
        until [ -n "$cf_user_key" ] 
        do
            random_number=$(od -An -N6 -t u8 < /dev/urandom)
            cf_user_unique_id=${random_number: -12}
            IFS="^" read -r result cf_user_key cf_user_api_key msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
                -d 'act=user_create' \
                -d "host_key=$cf_host_key" \
                -d "cloudflare_email=$cf_user_email" \
                -d "cloudflare_pass=$cf_user_pass" \
                -d "unique_id=$cf_user_unique_id" \
                | $JQ_FILE '[.result,.response.user_key,.response.user_api_key,.msg]|join("^")'
            ) || true

            result=${result#\"}
            msg=${msg%\"}
            if [ "$result" == "error" ] 
            then
                Println "$error $msg"
                if [[ $msg == *"assword"* ]] 
                then
                    Println "$(eval_gettext "\$error 请检查密码是否正确")\n"
                    exit 1
                fi
            elif [ -z "${cf_users_api_key[cf_users_index]}" ] 
            then
                jq_path='["users",'"$cf_users_index"',"key"]'
                JQ update "$CF_CONFIG" "$cf_user_api_key"
                Println "$(eval_gettext "\$info 用户 \$cf_user_email API Key 添加成功")\n"
            fi
        done

        new_zone=$(
        $JQ_FILE -n --arg name "$cf_zone_name" --arg resolve_to "$cf_zone_resolve_to" \
            --arg user_email "$cf_user_email" --arg user_unique_id "$cf_user_unique_id" \
            --arg always_use_https "$cf_zone_always_use_https" --arg ssl "$cf_zone_ssl" --arg subdomains "$cf_zone_subdomains" \
            '{
                name: $name,
                resolve_to: $resolve_to,
                user_email: $user_email,
                user_unique_id: $user_unique_id | tonumber,
                always_use_https: $always_use_https,
                ssl: $ssl,
                subdomains: $subdomains
            }'
        )

        jq_path='["hosts",'"$cf_hosts_index"',"zones"]'
        JQ add "$CF_CONFIG" "[$new_zone]"

        subdomains=""

        for((i=0;i<${#cf_hosted_cnames[@]};i++));
        do
            if [[ ${cf_hosted_cnames[i]} =~ ^([^.]+).([^.]+)$ ]] 
            then
                continue
            fi
            cf_hosted_cname=${cf_hosted_cnames[i]}
            cf_hosted_cname=${cf_hosted_cname%.*}
            cf_hosted_cname_prefix=${cf_hosted_cname%.*}
            [ -n "$subdomains" ] && subdomains="$subdomains,"
            subdomains="$subdomains$cf_hosted_cname_prefix:${cf_resolve_tos[i]}"
        done

        CloudflareGetUser

        IFS="^" read -r result cf_zone_resolving_to cf_zone_hosted_cnames cf_zone_forward_tos msg < <(curl -s -Lm 20 https://api.cloudflare.com/host-gw.html \
            -d 'act=zone_set' \
            -d "host_key=$cf_host_key" \
            -d "user_key=$cf_user_key" \
            -d "zone_name=$cf_zone_name" \
            -d "resolve_to=$cf_zone_resolve_to" \
            -d "subdomains=$subdomains" \
            | $JQ_FILE '[.result,.response.resolving_to,([(.response.hosted_cnames| if .== null then {} else . end)|to_entries[]
            |([.key,.value]|join("="))]
            |join("|")),([(.response.forward_tos| if .== null then {} else . end)|to_entries[]
            |([.key,.value]|join("="))]
            |join("|")),.msg]|join("^")'
        ) || true

        result=${result#\"}
        msg=${msg%\"}

        if [ -z "$result" ] || [ "$result" == "error" ]
        then
            Println "$error ${msg:-$(gettext "连接超时, 请查看是否已经完成")}\n" && exit 1
        fi

        Println "$(eval_gettext "\$info 源站移动成功")\n"
    }

    CloudflareGetUser()
    {
        cf_user_key=""
        add_subdomains=0
        unset cf_users_i
        until [ -n "$cf_user_key" ] 
        do
            IFS="^" read -r result cf_user_key cf_user_api_key msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
                -d 'act=user_lookup' \
                -d "host_key=$cf_host_key" \
                -d "unique_id=$cf_user_unique_id" \
                | $JQ_FILE '[.result,.response.user_key,.response.user_api_key,.msg]|join("^")'
            ) || true

            if [ -n "$cf_user_api_key" ] && [ -n "${cf_users_i:-}" ] && [ -z "${cf_users_api_key[cf_users_i]}" ]
            then
                jq_path='["users",'"$cf_users_i"',"key"]'
                JQ update "$CF_CONFIG" "$cf_user_api_key"
                local user_email="${cf_users_email[cf_users_i]}"
                Println "$(eval_gettext "\$info 用户 \$user_email API Key 添加成功")\n"
            fi

            result=${result#\"}
            msg=${msg%\"}

            if [ -z "$result" ] || [ "$result" == "error" ]
            then
                Println "$error ${msg:-$(gettext "超时, 请重试")}\n" && exit 1
            fi

            if [ -z "$cf_user_key" ] 
            then
                if [ "$monitor" = true ] 
                then
                    MonitorLog "$(eval_gettext "源站 \$cf_zone_name 的用户已被 CFP 删除或未添加成功, 尝试重新添加 ...")"
                fi

                Println "$(eval_gettext "\$error 源站 \$cf_zone_name 的用户已被 CFP 删除或未添加成功, 尝试重新添加 ...")"

                if [ -z "${cf_user_pass:-}" ] 
                then
                    CloudflareGetUsers
                    for((cf_users_i=0;cf_users_i<cf_users_count;cf_users_i++));
                    do
                        if [ "${cf_users_email[cf_users_i]}" == "$cf_user_email" ] 
                        then
                            cf_user_pass=${cf_users_pass[cf_users_i]}
                            break
                        fi
                    done
                fi

                if [ -z "${cf_user_pass:-}" ] 
                then
                    Println "$(eval_gettext "\$error 请先添加账号 \$cf_user_email")\n"
                    exit 1
                fi

                IFS="^" read -r result err_code msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
                    -d 'act=user_create' \
                    -d "host_key=$cf_host_key" \
                    -d "cloudflare_email=$cf_user_email" \
                    -d "cloudflare_pass=$cf_user_pass" \
                    -d "unique_id=$cf_user_unique_id" \
                    | $JQ_FILE '[.result,.err_code,.msg]|join("^")'
                ) 

                result=${result#\"}
                msg=${msg%\"}
                if [ "$result" == "error" ] 
                then
                    Println "$error $msg"
                fi

                add_subdomains=1
            elif [ "$add_subdomains" -eq 1 ] && [ -n "${cf_zone_subdomains:-}" ]
            then
                IFS="^" read -r result cf_zone_resolving_to cf_zone_hosted_cnames cf_zone_forward_tos msg < <(curl -s -Lm 20 https://api.cloudflare.com/host-gw.html \
                    -d 'act=zone_set' \
                    -d "host_key=$cf_host_key" \
                    -d "user_key=$cf_user_key" \
                    -d "zone_name=$cf_zone_name" \
                    -d "resolve_to=$cf_zone_resolve_to" \
                    -d "subdomains=$cf_zone_subdomains" \
                    | $JQ_FILE '[.result,.response.resolving_to,([(.response.hosted_cnames| if .== null then {} else . end)|to_entries[]
                    |([.key,.value]|join("="))]
                    |join("|")),([(.response.forward_tos| if .== null then {} else . end)|to_entries[]
                    |([.key,.value]|join("="))]
                    |join("|")),.msg]|join("^")'
                ) || true

                result=${result#\"}
                msg=${msg%\"}

                if [ -z "$result" ] || [ "$result" == "error" ]
                then
                    Println "$error ${msg:-$(gettext "连接超时, 请查看是否已经完成")}\n"
                fi
            fi
        done
    }

    CloudflareAddSubdomain()
    {
        CloudflareListZones

        echo -e "$(gettext "选择源站")"
        while read -p "$i18n_default_cancel" cf_zones_num
        do
            case "$cf_zones_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_zones_num" -gt 0 ] && [ "$cf_zones_num" -le "$cf_zones_count" ]
                    then
                        cf_zones_index=$((cf_zones_num-1))
                        cf_zone_name=${cf_zones_name[cf_zones_index]}
                        cf_zone_resolve_to=${cf_zones_resolve_to[cf_zones_index]}
                        cf_user_email=${cf_zones_user_email[cf_zones_index]}
                        cf_user_unique_id=${cf_zones_user_unique_id[cf_zones_index]}
                        cf_zone_always_use_https=${cf_zones_always_use_https[cf_zones_index]}
                        cf_zone_ssl=${cf_zones_ssl[cf_zones_index]}
                        cf_zone_subdomains=${cf_zones_subdomains[cf_zones_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        #cf_user_pass=$($JQ_FILE -r '.users[]|select(.email=="'"$cf_user_email"'") | .pass' $CF_CONFIG)

        #[ -z "$cf_user_pass" ] && Println "$error 用户 $cf_user_email 不存在\n" && exit 1

        CloudflareGetUser

        Println "$(gettext "请输入子域名前缀, 比如 www, 多个前缀用空格分隔")"
        read -p "$i18n_default_cancel" cf_zone_subdomains_prefix_input
        [ -z "$cf_zone_subdomains_prefix_input" ] && Println "$i18n_canceled...\n" && exit 1
        Println "$(eval_gettext "  子域名: \${green} \$cf_zone_subdomains_prefix_input \${normal}")\n"

        IFS=" " read -r -a cf_zone_subdomains_prefix <<< "$cf_zone_subdomains_prefix_input"
        cf_zone_subdomains_resolve_to=()
        for cf_zone_subdomain_prefix in "${cf_zone_subdomains_prefix[@]}"
        do
            Println "$(eval_gettext "请输入子域名 \$cf_zone_subdomain_prefix.\$cf_zone_name 经 cloudflare 中转后解析地址")"
            read -p "$(eval_gettext "(默认: \$cf_zone_resolve_to): ")" cf_zone_subdomain_resolve_to
            cf_zone_subdomain_resolve_to=${cf_zone_subdomain_resolve_to:-$cf_zone_resolve_to}
            cf_zone_subdomains_resolve_to+=("$cf_zone_subdomain_resolve_to")
        done

        CloudflareGetZone
        for((i=0;i<${#cf_hosted_cnames[@]};i++));
        do
            if [[ ${cf_hosted_cnames[i]} =~ ^([^.]+).([^.]+)$ ]] 
            then
                continue
            fi

            for cf_zone_subdomain_prefix in "${cf_zone_subdomains_prefix[@]}"
            do
                if [ "$cf_zone_subdomain_prefix.$cf_zone_name" == "${cf_hosted_cnames[i]}" ] 
                then
                    continue 2
                fi
            done

            cf_hosted_cname=${cf_hosted_cnames[i]}
            cf_hosted_cname=${cf_hosted_cname%.*}
            cf_hosted_cname_prefix=${cf_hosted_cname%.*}
            cf_zone_subdomains_prefix+=("$cf_hosted_cname_prefix")
            cf_zone_subdomains_resolve_to+=("${cf_resolve_tos[i]}")
        done

        subdomains=""

        for((i=0;i<${#cf_zone_subdomains_prefix[@]};i++));
        do
            [ -n "$subdomains" ] && subdomains="$subdomains,"
            if [ "${cf_zone_subdomains_resolve_to[i]}" != "$cf_zone_resolve_to" ] 
            then
                subdomains="$subdomains${cf_zone_subdomains_prefix[i]}:${cf_zone_subdomains_resolve_to[i]}"
            else
                subdomains="$subdomains${cf_zone_subdomains_prefix[i]}"
            fi
        done

        new_zone=$(
        $JQ_FILE -n --arg name "$cf_zone_name" --arg resolve_to "$cf_zone_resolve_to" \
            --arg user_email "$cf_user_email" --arg user_unique_id "$cf_user_unique_id" \
            --arg always_use_https "$cf_zone_always_use_https" --arg ssl "$cf_zone_ssl" --arg subdomains "$subdomains" \
            '{
                name: $name,
                resolve_to: $resolve_to,
                user_email: $user_email,
                user_unique_id: $user_unique_id | tonumber,
                always_use_https: $always_use_https,
                ssl: $ssl,
                subdomains: $subdomains
            }'
        )

        jq_json=true
        jq_path='["hosts",'"$cf_hosts_index"',"zones",'"$cf_zones_index"']'
        JQ update "$CF_CONFIG" "$new_zone"

        Println "$(eval_gettext "\$info 稍等...")"
        IFS="^" read -r result cf_zone_resolving_to cf_zone_hosted_cnames cf_zone_forward_tos msg < <(curl -s -Lm 20 https://api.cloudflare.com/host-gw.html \
            -d 'act=zone_set' \
            -d "host_key=$cf_host_key" \
            -d "user_key=$cf_user_key" \
            -d "zone_name=$cf_zone_name" \
            -d "resolve_to=$cf_zone_resolve_to" \
            -d "subdomains=$subdomains" \
            | $JQ_FILE '[.result,.response.resolving_to,([(.response.hosted_cnames| if .== null then {} else . end)|to_entries[]
            |([.key,.value]|join("="))]
            |join("|")),([(.response.forward_tos| if .== null then {} else . end)|to_entries[]
            |([.key,.value]|join("="))]
            |join("|")),.msg]|join("^")'
        ) || true

        result=${result#\"}
        msg=${msg%\"}

        if [ -z "$result" ] || [ "$result" == "error" ]
        then
            Println "$error ${msg:-$(gettext "连接超时, 请查看是否已经完成")}\n" && exit 1
        fi

        IFS="|" read -r -a cf_zone_hosted_cnames_arr <<< "$cf_zone_hosted_cnames"
        IFS="|" read -r -a cf_zone_forward_tos_arr <<< "$cf_zone_forward_tos"

        cf_hosted_cnames=()
        cf_resolve_tos=()
        cf_forward_tos=()

        for cf_zone_hosted_cname in "${cf_zone_hosted_cnames_arr[@]}"
        do
            cf_hosted_cname=${cf_zone_hosted_cname%%=*}
            cf_resolve_to=${cf_zone_hosted_cname#*=}
            cf_hosted_cnames+=("$cf_hosted_cname")
            cf_resolve_tos+=("$cf_resolve_to")
            for cf_zone_forward_to in "${cf_zone_forward_tos_arr[@]}"
            do
                if [ "${cf_zone_forward_to%%=*}" == "$cf_hosted_cname" ] 
                then
                    cf_forward_tos+=("${cf_zone_forward_to#*=}")
                    break
                fi
            done
        done

        msg=""

        if [ "$cf_zone_resolving_to" != "$cf_zone_name" ] 
        then
            zone_found=0
            for cf_resolve_to in "${cf_resolve_tos[@]}"
            do
                if [ "$cf_resolve_to" == "$cf_zone_name" ] 
                then
                    zone_found=1
                    break
                fi
            done
            if [ "$zone_found" -eq 0 ] && [[ ${cf_forward_tos[0]} =~ ([^.]+).([^.]+).([^.]+)$ ]] 
            then
                cf_zone_name_resolve_to="$cf_zone_name.${BASH_REMATCH[1]}.${BASH_REMATCH[2]}.${BASH_REMATCH[3]}"
                msg="$(eval_gettext "请添加域名 \${green}\$cf_zone_name\${normal} CNAME 记录到 \${green}\$cf_zone_name_resolve_to\${normal}")\n\n"
            fi
        fi

        for((i=0;i<${#cf_hosted_cnames[@]};i++));
        do
            for cf_zone_subdomain_prefix in "${cf_zone_subdomains_prefix[@]}"
            do
                if [ "$cf_zone_subdomain_prefix.$cf_zone_name" == "${cf_hosted_cnames[i]}" ] 
                then
                    local hosted_cname="${cf_hosted_cnames[i]}" forward_to="${cf_forward_tos[i]}"
                    msg="$msg$(eval_gettext "请添加域名 \${green}\$hosted_cname\${normal} CNAME 记录到 \${green}\$forward_to\${normal}")\n\n"
                    break
                fi
            done
        done

        Println "$msg"
        Println "$(eval_gettext "\$info 子域名添加成功")\n"
    }

    CloudflareListSubdomain()
    {
        CloudflareListZones

        echo -e "$(gettext "选择源站")"
        while read -p "$i18n_default_cancel" cf_zones_num
        do
            case "$cf_zones_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_zones_num" -gt 0 ] && [ "$cf_zones_num" -le "$cf_zones_count" ]
                    then
                        cf_zones_index=$((cf_zones_num-1))
                        cf_zone_name=${cf_zones_name[cf_zones_index]}
                        cf_zone_resolve_to=${cf_zones_resolve_to[cf_zones_index]}
                        cf_user_email=${cf_zones_user_email[cf_zones_index]}
                        cf_user_unique_id=${cf_zones_user_unique_id[cf_zones_index]}
                        cf_zone_subdomains=${cf_zones_subdomains[cf_zones_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        #cf_user_pass=$($JQ_FILE -r '.users[]|select(.email=="'"$cf_user_email"'") | .pass' $CF_CONFIG)

        #[ -z "$cf_user_pass" ] && Println "$error 用户 $cf_user_email 不存在\n" && exit 1

        CloudflareGetUser
        CloudflareGetZone

        cf_subdomains_list=""
        for((i=0;i<${#cf_hosted_cnames[@]};i++));
        do
            cf_subdomains_list="$cf_subdomains_list ${green}$((i+1)).${normal}${indent_6}CNAME: ${green}${cf_hosted_cnames[i]}${normal} => ${green}${cf_forward_tos[i]}${normal}\n${indent_6}$(gettext "解析地址"): ${green}${cf_resolve_tos[i]}${normal}\n\n"
        done

        if [ -z "$cf_subdomains_list" ] 
        then
            cf_subdomains_list="$(eval_gettext "\$error 没有子域名")\n\n$(eval_gettext "\$tip 至少添加一个子域名才能激活源站 cloudflare 解析")\n"
            ssl_status=""
            ssl_meta_tag=""
            if [ -n "$cf_zone_subdomains" ] 
            then
                IFS="^" read -r result cf_zone_resolving_to cf_zone_hosted_cnames cf_zone_forward_tos msg < <(curl -s -Lm 20 https://api.cloudflare.com/host-gw.html \
                    -d 'act=zone_set' \
                    -d "host_key=$cf_host_key" \
                    -d "user_key=$cf_user_key" \
                    -d "zone_name=$cf_zone_name" \
                    -d "resolve_to=$cf_zone_resolve_to" \
                    -d "subdomains=$cf_zone_subdomains" \
                    | $JQ_FILE '[.result,.response.resolving_to,([(.response.hosted_cnames| if .== null then {} else . end)|to_entries[]
                    |([.key,.value]|join("="))]
                    |join("|")),([(.response.forward_tos| if .== null then {} else . end)|to_entries[]
                    |([.key,.value]|join("="))]
                    |join("|")),.msg]|join("^")'
                ) || true

                result=${result#\"}
                msg=${msg%\"}

                if [ -z "$result" ] || [ "$result" == "error" ]
                then
                    Println "$error ${msg:-$(gettext "连接超时, 请查看是否已经完成")}\n"
                fi

                CloudflareGetZone

                cf_subdomains_list=""
                for((i=0;i<${#cf_hosted_cnames[@]};i++));
                do
                    cf_subdomains_list="$cf_subdomains_list ${green}$((i+1)).${normal}${indent_6}CNAME: ${green}${cf_hosted_cnames[i]}${normal} => ${green}${cf_forward_tos[i]}${normal}\n${indent_6}$(gettext "解析地址"): ${green}${cf_resolve_tos[i]}${normal}\n\n"
                done

                if [ "$cf_zone_ssl_status" == "ready" ] 
                then
                    ssl_status="$(gettext "SSL 状态"): ${green}$(gettext "激活")${normal}\n"
                    ssl_meta_tag=""
                else
                    ssl_status="$(gettext "SSL 状态"): ${red}$i18n_none${normal}\n"
                    if [ -n "$cf_zone_ssl_meta_tag" ]
                    then
                        ssl_meta_tag="\n$(eval_gettext "请在子域名页面 HEAD 处添加 \${green}\$cf_zone_ssl_meta_tag\${normal} 以激活 ssl")\n"
                    else
                        ssl_meta_tag=""
                    fi
                fi

                Println "${cf_subdomains_list}$ssl_status$ssl_meta_tag"
            fi
        elif [ "$cf_zone_ssl_status" == "ready" ] 
        then
            ssl_status="$(gettext "SSL 状态"): ${green}$(gettext "激活")${normal}\n"
            ssl_meta_tag=""
        else
            ssl_status="$(gettext "SSL 状态"): ${red}$i18n_none${normal}\n"
            if [ -n "$cf_zone_ssl_meta_tag" ]
            then
                ssl_meta_tag="\n$(eval_gettext "请在子域名页面 HEAD 处添加 \${green}\$cf_zone_ssl_meta_tag\${normal} 以激活 ssl")\n"
            else
                ssl_meta_tag=""
            fi
        fi

        Println "${cf_subdomains_list}$ssl_status$ssl_meta_tag"
    }

    CloudflareDelZone()
    {
        CloudflareListZones

        echo -e "$(gettext "选择源站")"
        while read -p "$i18n_default_cancel" cf_zones_num
        do
            case "$cf_zones_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_zones_num" -gt 0 ] && [ "$cf_zones_num" -le "$cf_zones_count" ]
                    then
                        cf_zones_index=$((cf_zones_num-1))
                        cf_zone_name=${cf_zones_name[cf_zones_index]}
                        cf_zone_resolve_to=${cf_zones_resolve_to[cf_zones_index]}
                        cf_user_email=${cf_zones_user_email[cf_zones_index]}
                        cf_user_unique_id=${cf_zones_user_unique_id[cf_zones_index]}
                        cf_zone_subdomains=${cf_zones_subdomains[cf_zones_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        CloudflareGetUser
        Println "$(eval_gettext "\$info 稍等...")"
        IFS="^" read -r result err_code msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
            -d 'act=zone_delete' \
            -d "host_key=$cf_host_key" \
            -d "user_key=$cf_user_key" \
            -d "zone_name=$cf_zone_name" \
            | $JQ_FILE '[.result,.err_code,.msg]|join("^")'
        ) || true

        result=${result#\"}
        msg=${msg%\"}

        if [ -z "$result" ] || [ "$result" == "error" ]
        then
            if [ "$err_code" -eq 115 ] || [ "$err_code" -eq 703 ]
            then
                Println "$(eval_gettext "\$error 此用户已被 CFP 删除或未添加成功, 可以到 Cloudflare 官网手动删除源站或者重新添加 !")"
            else
                Println "$error ${msg:-$(gettext "超时, 请重试")}\n"
            fi
            echo
            ExitOnList n "`gettext \"是否仍要删除此源站, 只有这里和官网都删除才能重新添加此源站\"`"

            jq_path='["hosts",'"$cf_hosts_index"',"zones",'"$cf_zones_index"']'
            JQ delete "$CF_CONFIG"
            Println "$(eval_gettext "\$info \$cf_zone_name 删除成功")\n"
        else
            jq_path='["hosts",'"$cf_hosts_index"',"zones",'"$cf_zones_index"']'
            JQ delete "$CF_CONFIG"
            Println "$(eval_gettext "\$info \$cf_zone_name 删除成功")\n"
        fi
    }

    CloudflareDelHost()
    {
        CloudflareListHosts

        echo -e "$(gettext "选择 CFP")"
        while read -p "$i18n_default_cancel" cf_hosts_num
        do
            case "$cf_hosts_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_hosts_num" -gt 0 ] && [ "$cf_hosts_num" -le "$cf_hosts_count" ]
                    then
                        cf_hosts_index=$((cf_hosts_num-1))
                        cf_host_name=${cf_hosts_name[cf_hosts_index]}
                        cf_host_key=${cf_hosts_key[cf_hosts_index]}
                        cf_zones_count=${cf_hosts_zones_count[cf_hosts_index]}
                        cf_zone_name=${cf_hosts_zone_name[cf_hosts_index]}
                        cf_zone_user_unique_id=${cf_hosts_zone_user_unique_id[cf_hosts_index]}
                        IFS="|" read -r -a cf_zones_name <<< "$cf_zone_name"
                        IFS="|" read -r -a cf_zones_user_unique_id <<< "$cf_zone_user_unique_id"
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        if [ "$cf_zones_count" -gt 0 ] 
        then
            echo
            ExitOnList n "`gettext \"是否删除此 CFP 下所有的源站\"`"

            for((i=0;i<${#cf_zones_name[@]};i++));
            do
                cf_zone_name=${cf_zones_name[i]}
                cf_user_unique_id=${cf_zones_user_unique_id[i]}

                CloudflareGetUser

                IFS="^" read -r result msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
                    -d 'act=zone_delete' \
                    -d "host_key=$cf_host_key" \
                    -d "user_key=$cf_user_key" \
                    -d "zone_name=$cf_zone_name" \
                    | $JQ_FILE '[.result,.msg]|join("^")'
                ) || true

                result=${result#\"}
                msg=${msg%\"}

                if [ -z "$result" ] || [ "$result" == "error" ]
                then
                    local err_msg="${msg:-$(gettext "超时, 请重试")}"
                    Println "$(eval_gettext "\$error 删除 \$cf_zone_name 发送错误: \$err_msg")\n" && exit 1
                fi

                jq_path='["hosts",'"$cf_hosts_index"',"zones",'"$i"']'
                JQ delete "$CF_CONFIG"

                Println "$(eval_gettext "\$info \$cf_zone_name 删除成功")\n"
            done
        fi
    }

    CloudflareEditUser()
    {
        CloudflareListUsers

        if [ "$cf_users_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加用户")\n"
            exit 1
        fi

        echo -e "$(gettext "选择用户")"
        while read -p "$i18n_default_cancel" cf_users_num
        do
            case "$cf_users_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_users_num" -gt 0 ] && [ "$cf_users_num" -le "$cf_users_count" ]
                    then
                        cf_users_index=$((cf_users_num-1))
                        cf_user_email=${cf_users_email[cf_users_index]}
                        cf_user_pass=${cf_users_pass[cf_users_index]}
                        cf_user_token=${cf_users_token[cf_users_index]}
                        cf_user_api_key=${cf_users_api_key[cf_users_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        Println "$(gettext "请输入用户邮箱")"
        read -p "$(eval_gettext "(默认: \$cf_user_email): ")" cf_user_email_new
        cf_user_email_new=${cf_user_email_new:-$cf_user_email}
        Println "$(eval_gettext "  用户邮箱: \${green} \$cf_user_email_new \${normal}")\n"

        Println "$(gettext "输入用户密码")"
        read -p "$(eval_gettext "(默认: \$cf_user_pass): ")" cf_user_pass_new
        cf_user_pass_new=${cf_user_pass_new:-$cf_user_pass}
        Println "$(eval_gettext "  用户密码: \${green} \$cf_user_pass_new \${normal}")\n"

        Println "$(gettext "请输入用户 Token")"
        read -p "($i18n_default: ${cf_user_token:-$i18n_blank}): " cf_user_token_new
        cf_user_token_new=${cf_user_token_new:-$cf_user_token}
        Println "  $(gettext "用户 Token"): ${green} ${cf_user_token_new:-$i18n_blank} ${normal}\n"

        Println "$(gettext "请输入用户 Key")"
        read -p "($i18n_default: ${cf_user_api_key:-$i18n_blank}): " cf_user_api_key_new
        cf_user_api_key_new=${cf_user_api_key_new:-$cf_user_api_key}
        Println "  $(gettext "用户 Token"): ${green} ${cf_user_api_key_new:-$i18n_blank} ${normal}\n"

        new_user=$(
        $JQ_FILE -n --arg email "$cf_user_email_new" --arg pass "$cf_user_pass_new" \
            --arg token "$cf_user_token_new" --arg key "$cf_user_api_key_new" \
            '{
                email: $email,
                pass: $pass,
                token: $token,
                key: $key
            }'
        )

        jq_json=true
        jq_path='["users",'"$cf_users_index"']'
        JQ update "$CF_CONFIG" "$new_user"
        Println "$(eval_gettext "\$info 用户修改成功")\n"
    }

    CloudflareRegenHost()
    {
        CloudflareListHosts

        echo "$(gettext "选择 CFP")"
        echo -e "$(eval_gettext "\$tip 请勿更改公开的 CFP !")\n"
        while read -p "$i18n_default_cancel" cf_hosts_num
        do
            case "$cf_hosts_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_hosts_num" -gt 0 ] && [ "$cf_hosts_num" -le "$cf_hosts_count" ]
                    then
                        cf_hosts_index=$((cf_hosts_num-1))
                        cf_host_name=${cf_hosts_name[cf_hosts_index]}
                        cf_host_key=${cf_hosts_key[cf_hosts_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        Println "$(eval_gettext "\$info 稍等...")"
        IFS="^" read -r result cf_host_key_new msg < <(curl -s -Lm 50 https://api.cloudflare.com/host-gw.html \
            -d 'act=host_key_regen' \
            -d "host_key=$cf_host_key" \
            | $JQ_FILE '[.result,.request."host:key".__host_key,.msg]|join("^")'
        ) || true

        result=${result#\"}
        msg=${msg%\"}

        if [ -z "$result" ] || [ "$result" == "error" ]
        then
            Println "$error ${msg:-$(gettext "超时, 请重试")}\n" && exit 1
        fi

        jq_path='["hosts",'"$cf_hosts_index"',"key"]'
        JQ update "$CF_CONFIG" "$cf_host_key_new"

        Println "$(eval_gettext "\$info \$cf_host_name host key 修改成功")"
    }

    CloudflareListToken()
    {
        CloudflareListUsers

        if [ "$cf_users_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加用户")\n"
            exit 1
        fi

        echo -e "$(gettext "选择用户")"
        while read -p "$i18n_default_cancel" cf_users_num
        do
            case "$cf_users_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_users_num" -gt 0 ] && [ "$cf_users_num" -le "$cf_users_count" ]
                    then
                        cf_users_index=$((cf_users_num-1))
                        cf_user_email=${cf_users_email[cf_users_index]}
                        cf_user_pass=${cf_users_pass[cf_users_index]}
                        cf_user_api_key=${cf_users_api_key[cf_users_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        if [ -z "$cf_user_api_key" ] 
        then
            Println "$(eval_gettext "\$error 此用户没有 Global API Key, 请手动添加")\n"
            exit 1
        fi

        IFS="#" read -r success token < <(curl -s \
            -X GET "https://api.cloudflare.com/client/v4/user/tokens?page=1&per_page=50&direction=desc" \
            -H "X-Auth-Email:$cf_user_email" \
            -H "X-Auth-Key:$cf_user_api_key" \
            -H "Content-Type: application/json" \
            | $JQ_FILE '[.success,(.result|to_entries|map([.value.id,.value.name,.value.status,([.value.policies[].permission_groups[].name]|join(", "))]|join("|"))|join("^"))]|join("#")' 2> /dev/null
        ) || true

        success=${success#\"}
        token=${token%\"}

        if [ "$success" != "true" ] 
        then
            Println "$(eval_gettext "\$error 获取 Token 错误, 必须是 Global API Key 才可以获取用户 Token ")\n"
            exit 1
        fi

        IFS="^" read -r -a tokens <<< "$token"
        tokens_count=${#tokens[@]}
        tokens_list=""
        tokens_id=()

        for((i=0;i<tokens_count;i++));
        do
            IFS="|" read -r token_id token_name token_status token_permission <<< "${tokens[i]}"
            tokens_id+=("$token_id")
            tokens_list="$tokens_list ${green}$((i+1)).${normal}${indent_6}$i18n_name: ${green}$token_name${normal}  $i18n_status: ${green}$token_status${normal}\n${indent_6}$(gettext "权限"): ${green}${token_permission:-$i18n_none}${normal}\n\n"
        done

        Println "$tokens_list"
    }

    CloudflareAddToken()
    {
        CloudflareListToken

        echo -e "$(gettext "选择 Token")"

        while read -p "$i18n_default_cancel" tokens_num
        do
            case $tokens_num in
                "") 
                    Println "$i18n_canceled...\n"
                    exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *) 
                    if [ "$tokens_num" -gt 0 ] && [ "$tokens_num" -le "$tokens_count" ] 
                    then
                        tokens_index=$((tokens_num-1))
                        token_id=${tokens_id[tokens_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        echo
        ExitOnList n "`gettext \"需要更新此 Token 后才能添加到脚本, 是否继续\"`"

        Println "$(eval_gettext "\$info 更新 Token")"
        cf_user_token_new=$(curl -s -X PUT https://api.cloudflare.com/client/v4/user/tokens/$token_id/value \
            -H "X-Auth-Email:$cf_user_email" \
            -H "X-Auth-Key:$cf_user_api_key" \
            -H "Content-Type: application/json" \
            --data '{}' | $JQ_FILE -r '.result'
        ) || true

        if [ -z "$cf_user_token_new" ] || [ "$cf_user_token_new" == null ]
        then
            Println "$(eval_gettext "\$error 更新 Token 失败")\n"
        else
            Println "$(eval_gettext "\$info Token 更新成功: \$cf_user_token_new")"
            jq_path='["users",'"$cf_users_index"',"token"]'
            JQ update "$CF_CONFIG" "$cf_user_token_new"
            Println "$(eval_gettext "\$info 用户 Token 添加成功")\n"
        fi
    }

    CloudflareUpdateToken()
    {
        CloudflareListToken

        echo -e "$(gettext "选择 Token")"

        while read -p "$i18n_default_cancel" tokens_num
        do
            case $tokens_num in
                "") 
                    Println "$i18n_canceled...\n"
                    exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *) 
                    if [ "$tokens_num" -gt 0 ] && [ "$tokens_num" -le "$tokens_count" ] 
                    then
                        tokens_index=$((tokens_num-1))
                        token_id=${tokens_id[tokens_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        Println "$(eval_gettext "\$info 更新 Token")"
        cf_user_token_new=$(curl -s -X PUT https://api.cloudflare.com/client/v4/user/tokens/$token_id/value \
            -H "X-Auth-Email:$cf_user_email" \
            -H "X-Auth-Key:$cf_user_api_key" \
            -H "Content-Type: application/json" \
            --data '{}' | $JQ_FILE -r '.result'
        ) || true
        if [ -z "$cf_user_token_new" ] || [ "$cf_user_token_new" == null ]
        then
            Println "$(eval_gettext "\$error 更新 Token 失败")\n"
        else
            Println "$(eval_gettext "\$info Token 更新成功: \$cf_user_token_new")\n"
        fi
    }

    CloudflareDelUser()
    {
        CloudflareListUsers

        if [ "$cf_users_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加用户")\n"
            exit 1
        fi

        echo -e "$(gettext "选择用户")"
        while read -p "$i18n_default_cancel" cf_users_num
        do
            case "$cf_users_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_users_num" -gt 0 ] && [ "$cf_users_num" -le "$cf_users_count" ]
                    then
                        cf_users_index=$((cf_users_num-1))
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        jq_path='["users",'"$cf_users_index"']'
        JQ delete "$CF_CONFIG"
        Println "$(eval_gettext "\$info 用户删除成功")\n"
    }

    CloudflareEditZone()
    {
        CloudflareListZones

        echo -e "$(gettext "选择源站")"
        while read -p "$i18n_default_cancel" cf_zones_num
        do
            case "$cf_zones_num" in
                "")
                    Println "$i18n_canceled...\n" && exit 1
                ;;
                *[!0-9]*)
                    Println "$error $i18n_input_correct_no\n"
                ;;
                *)
                    if [ "$cf_zones_num" -gt 0 ] && [ "$cf_zones_num" -le "$cf_zones_count" ]
                    then
                        cf_zones_index=$((cf_zones_num-1))
                        cf_zone_name=${cf_zones_name[cf_zones_index]}
                        cf_zone_resolve_to=${cf_zones_resolve_to[cf_zones_index]}
                        cf_user_email=${cf_zones_user_email[cf_zones_index]}
                        cf_user_unique_id=${cf_zones_user_unique_id[cf_zones_index]}
                        cf_zone_always_use_https=${cf_zones_always_use_https[cf_zones_index]}
                        cf_zone_ssl=${cf_zones_ssl[cf_zones_index]}
                        cf_zone_subdomains=${cf_zones_subdomains[cf_zones_index]}
                        break
                    else
                        Println "$error $i18n_input_correct_no\n"
                    fi
                ;;
            esac
        done

        Println "  $(gettext "选择需要修改的设置")

  ${green}1.${normal} Always Use HTTPS
  ${green}2.${normal} SSL

      "
        while read -p "$i18n_default_cancel" zone_edit_num
        do
            case $zone_edit_num in
                "") 
                    Println "$i18n_canceled...\n"
                    exit 1
                ;;
                1) 
                    CloudflareSetZoneAlwaysUseHttps
                    break
                ;;
                2) 
                    CloudflareSetZoneSsl
                    break
                ;;
                *) 
                    Println "$error $i18n_input_correct_no\n"
                ;;
            esac
        done

        new_zone=$(
        $JQ_FILE -n --arg name "$cf_zone_name" --arg resolve_to "$cf_zone_resolve_to" \
            --arg user_email "$cf_user_email" --arg user_unique_id "$cf_user_unique_id" \
            --arg always_use_https "${cf_zone_always_use_https:-off}" --arg ssl "${cf_zone_ssl:-flexible}" --arg subdomains "$cf_zone_subdomains" \
            '{
                name: $name,
                resolve_to: $resolve_to,
                user_email: $user_email,
                user_unique_id: $user_unique_id | tonumber,
                always_use_https: $always_use_https,
                ssl: $ssl,
                subdomains: $subdomains
            }'
        )

        jq_json=true
        jq_path='["hosts",'"$cf_hosts_index"',"zones",'"$cf_zones_index"']'
        JQ update "$CF_CONFIG" "$new_zone"
        Println "$(eval_gettext "\$info 源站修改成功")\n"
    }

