        IFS="${delimiters[3]}" read -r -a books_category_id <<< "$jq_books_zhlhh_category_id"
        IFS="${delimiters[3]}" read -r -a books_cover <<< "$jq_books_zhlhh_cover"
        IFS="${delimiters[3]}" read -r -a books_drawing <<< "$jq_books_zhlhh_drawing"
        IFS="${delimiters[3]}" read -r -a books_m <<< "$jq_books_zhlhh_m"
        IFS="${delimiters[3]}" read -r -a books_muludir <<< "$jq_books_zhlhh_muludir"
        IFS="${delimiters[3]}" read -r -a books_original <<< "$jq_books_zhlhh_original"
        IFS="${delimiters[3]}" read -r -a books_p <<< "$jq_books_zhlhh_p"
        IFS="${delimiters[3]}" read -r -a books_publish <<< "$jq_books_zhlhh_publish"
        IFS="${delimiters[3]}" read -r -a books_yd <<< "$jq_books_zhlhh_yd"
        IFS="${delimiters[3]}" read -r -a books_downloaded <<< "$jq_books_zhlhh_downloaded"
        IFS="${delimiters[3]}" read -r -a books_fav <<< "$jq_books_zhlhh_fav"

        local books_total=${#books_adapter[@]}

        if [ "$books_total" -gt 0 ] 
        then
            search_means=( "$lhh_zhlhh_no_search_cache" "${search_means[@]}" )
        fi

        Println "$(eval_gettext "\$tip 人物只能单独查询")"
        inquirer checkbox_input_indices "$(gettext "选择查询选项")" search_means search_keys_indices 20

        local i18n_downloaded i18n_favorited
        i18n_downloaded=$(gettext "已下载")
        i18n_favorited=$(gettext "已收藏")

        if [ "$books_total" -gt 0 ] && EleInArray 0 search_keys_indices
        then
            result_bookname=()
            for((i=0;i<books_total;i++));
            do
                bookname="${books_bookname[i]}"
                if [ "${books_downloaded[i]}" = true ] 
                then
                    bookname="$bookname ${green}[${i18n_downloaded}]${normal}"
                fi
                if [ "${books_fav[i]}" = true ] 
                then
                    bookname="$bookname ${green}[${i18n_favorited}]${normal}"
                fi
                result_bookname+=("$bookname")
            done
            result_m=("${books_m[@]}")
            result_yd=("${books_yd[@]}")
            result_p=("${books_p[@]}")
            iframe_paths=($(CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: http://www.zhlhh.com/" "http://www.zhlhh.com/web/js/main.js" | grep -oP 'url = "\K[^"]+'))
            books_indices=("${!books_m[@]}")
        else
            if EleInArray $((${#search_means[@]}-1)) search_keys_indices
            then
                echo
                ExitOnText "$(gettext "输入查询的人物")" search_text
                post_data="${search_keys[6]}=$search_text&p=1&s=1000"
                post_url="http://www.zhlhh.com/web/handler/main.ashx/G_P_B"
            else
                colors=( "$i18n_all" "$(gettext "黑白")" "$(gettext "彩色")" )
                colors_values=( '全部' '黑白' '彩色' )
                for search_keys_index in "${search_keys_indices[@]}"
                do
                    if [ "$books_total" -gt 0 ] 
                    then
                        search_keys_index=$((search_keys_index-1))
                    fi
                    case $search_keys_index in
                        0) 
                            echo
                            ExitOnText "$(gettext "输入书名")" book_name
                        ;;
                        1) 
                            echo
                            ExitOnText "$(gettext "输入原著")" book_original
                        ;;
                        2) 
                            echo
                            ExitOnText "$(gettext "输入改编")" book_adapter
                        ;;
                        3) 
                            echo
                            ExitOnText "$(gettext "输入绘画")" book_drawing
                        ;;
                        4) 
                            echo
                            ExitOnText "$(gettext "输入出版社")" book_publish
                        ;;
                        5) 
                            echo
                            inquirer list_input_index "$(gettext "选择颜色")" colors colors_index
                        ;;
                    esac
                done

                post_data="a=${book_name:-}&b=${book_original:-}&c=${book_adapter:-}&d=${book_drawing:-}&e=${book_publish:-}&f=${colors_values[${colors_index:-0}]}&p=1&s=1000"
                post_url="http://www.zhlhh.com/web/handler/main.ashx/G_F_B"
            fi

            response=$(
                CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: http://www.zhlhh.com/" --data ''"$post_data"'' $post_url
            )

            jq_payload=$(JQs flat "$response")

            jq_path='[
                ["AllCount"],
                ["pageInfor","AllCount"],
                ["result","adapter"],
                ["result","addtime"],
                ["result","bookname"],
                ["result","category_id"],
                ["result","cover"],
                ["result","drawing"],
                ["result","m"],
                ["result","muludir"],
                ["result","original"],
                ["result","p"],
                ["result","publish"],
                ["result","yd"]
            ]'

            while IFS=": " read -r path_name value; do
                var_name=${path_name}
                read -r ${var_name?} <<< "$value"
            done < <(JQs gets jq_payload)

            result_count="$jq_result_count"
            result_total="$jq_pageInfor_AllCount"

            if [ "$result_count" -eq 0 ] 
            then
                Println "$(eval_gettext "\$error 没有结果")"
                exit 1
            fi

            iframe_paths=($(CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: http://www.zhlhh.com/" "http://www.zhlhh.com/web/js/main.js" | grep -oP 'url = "\K[^"]+'))

            IFS="${delimiters[2]}" read -r -a result_adapter <<< "$jq_result_adapter"
            IFS="${delimiters[2]}" read -r -a result_addtime <<< "$jq_result_addtime"
            IFS="${delimiters[2]}" read -r -a result_bookname <<< "$jq_result_bookname"
            IFS="${delimiters[2]}" read -r -a result_category_id <<< "$jq_result_category_id"
            IFS="${delimiters[2]}" read -r -a result_cover <<< "$jq_result_cover"
            IFS="${delimiters[2]}" read -r -a result_drawing <<< "$jq_result_drawing"
            IFS="${delimiters[2]}" read -r -a result_m <<< "$jq_result_m"
            IFS="${delimiters[2]}" read -r -a result_muludir <<< "$jq_result_muludir"
            IFS="${delimiters[2]}" read -r -a result_original <<< "$jq_result_original"
            IFS="${delimiters[2]}" read -r -a result_p <<< "$jq_result_p"
            IFS="${delimiters[2]}" read -r -a result_publish <<< "$jq_result_publish"
            IFS="${delimiters[2]}" read -r -a result_yd <<< "$jq_result_yd"

            local i j books new_book books_indices=()

            for((i=0;i<result_count;i++));
            do
                if [ "$books_total" -gt 0 ] && EleInArray "${result_m[i]}" books_m 
                then
                    for((j=0;j<books_total;j++));
                    do
                        if [ "${books_m[j]}" -eq "${result_m[i]}" ] 
                        then
                            if [ "${books_downloaded[j]}" = true ] 
                            then
                                result_bookname[i]="${result_bookname[i]} ${green}[${i18n_downloaded}]${normal}"
                            fi

                            if [ "${books_fav[j]}" = true ] 
                            then
                                result_bookname[i]="${result_bookname[i]} ${green}[${i18n_favorited}]${normal}"
                            fi
                            books_indices+=("$j")
                            break
                        fi
                    done
                else
                    books_adapter+=("${result_adapter[i]}")
                    books_addtime+=("${result_addtime[i]}")
                    books_bookname+=("${result_bookname[i]}")
                    books_category_id+=("${result_category_id[i]}")
                    books_cover+=("${result_cover[i]}")
                    books_drawing+=("${result_drawing[i]}")
                    books_m+=("${result_m[i]}")
                    books_muludir+=("${result_muludir[i]}")
                    books_original+=("${result_original[i]}")
                    books_p+=("${result_p[i]}")
                    books_publish+=("${result_publish[i]}")
                    books_yd+=("${result_yd[i]}")
                    books_downloaded+=("false")
                    books_fav+=("false")
                    new_book=$(
                    $JQ_FILE -n --arg adapter "${result_adapter[i]}" --arg addtime "${result_addtime[i]}" \
                    --arg bookname "${result_bookname[i]}" --arg category_id "${result_category_id[i]}" \
                    --arg cover "${result_cover[i]}" --arg drawing "${result_drawing[i]}" \
                    --arg m "${result_m[i]}" --arg muludir "${result_muludir[i]}" \
                    --arg original "${result_original[i]}" --arg p "${result_p[i]}" \
                    --arg publish "${result_publish[i]}" --arg yd "${result_yd[i]}" \
                        '{
                            adapter: $adapter,
                            addtime: $addtime,
                            bookname: $bookname,
                            category_id: $category_id | tonumber,
                            cover: $cover,
                            drawing: $drawing,
                            m: $m | tonumber,
                            muludir: $muludir,
                            original: $original,
                            p: $p,
                            publish: $publish,
                            yd: $yd,
                            downloaded: false,
                            fav: false
                        }'
                    )

                    [ -n "${books:-}" ] && books="${books},"
                    books="${books}${new_book}"
                    books_indices+=("$books_total")
                    books_total=$((books_total+1))
                fi
            done

            if [ -n "${books:-}" ] 
            then
                jq_path='["books","zhlhh"]'
                JQ add "$LIANHUANHUA_CONFIG" "[$books]"
            fi
        fi

        echo
        inquirer checkbox_input_indices "$(gettext "选择连环画")" result_bookname result_indices 20

        echo
        result_options=( "${lhh_zhlhh_result_options_cache[@]}" )
        inquirer checkbox_input_indices "$i18n_select_action" result_options result_options_indices

        for result_options_index in "${result_options_indices[@]}"
        do
            if [ "$result_options_index" -eq 0 ] 
            then
                echo
                inquirer text_input "$(gettext "输入存储文件夹目录")" save_dir "${default_save_dir}"
                RemoveQuotes save_dir
                if [ -z "$save_dir" ] 
                then
                    Println "$i18n_canceled...\n"
                    exit 1
                fi

                if [ "$save_dir" != "$default_save_dir" ] 
                then
                    jq_path='["default","save_dir"]'
                    JQ update "$LIANHUANHUA_CONFIG" "$save_dir"
                fi

                FFmpegInstall

                for result_index in "${result_indices[@]}"
                do
                    books_index=${books_indices[result_index]}
                    book_url="http://www.zhlhh.com${iframe_paths[result_yd[result_index]]:-iframe_paths[0]}?libcode=$libcode&m=${result_m[result_index]}&p=${result_p[result_index]}&y_l_s="
                    ZhLhhDownload "${book_url}" "${books_bookname[books_index]}"
                    if [ "${books_downloaded[books_index]}" = false ] 
                    then
                        jq_bool=true
                        jq_path='["books","zhlhh",'"$books_index"',"downloaded"]'
                        JQ update "$LIANHUANHUA_CONFIG" true
                    fi
                done

                Println "$(eval_gettext "\$info 下载完成")\n"
            elif [ "$result_options_index" -eq 1 ] 
            then
                for result_index in "${result_indices[@]}"
                do
                    books_index=${books_indices[result_index]}
                    if [ "${books_fav[books_index]}" = false ]
                    then
                        jq_bool=true
                        jq_path='["books","zhlhh",'"$books_index"',"fav"]'
                        JQ update "$LIANHUANHUA_CONFIG" true
                    fi
                done
                Println "$(eval_gettext "\$info 已添加到收藏")\n"
            else
                for result_index in "${result_indices[@]}"
                do
                    books_index=${books_indices[result_index]}
                    if [ "${books_fav[books_index]}" = true ]
                    then
                        jq_bool=true
                        jq_path='["books","zhlhh",'"$books_index"',"fav"]'
                        JQ update "$LIANHUANHUA_CONFIG" false
                    fi
                done
                Println "$(eval_gettext "\$info 已取消收藏")\n"
            fi
        done
    }

    HdlzZhihuDownload()
    {
        local id=$1 title=$2 i j
        local book_path="$save_dir/${title//\//_}"
        shift 2

        i=2
        until [ ! -d "$book_path" ] 
        do
            if [ "$i" -gt 2 ] 
            then
                book_path="${book_path%-*}"
            fi
            book_path="${book_path}-$i"
            i=$((i+1))
        done

        if ! book_images=($(LhhDownload -s -L -A "$USER_AGENT_BROWSER" -b "$COOKIE_FILE" "https://zhuanlan.zhihu.com/p/${id}" | grep -oP 'data-original-token="\K[^"]+' | uniq))
        then
            return 1
        fi

        if [ -z "${1:-}" ] 
        then
            mkdir -p "$book_path"

            for((i=0;i<${#book_images[@]};i++));
            do
                book_image="https://picx.zhimg.com/${book_images[i]}_r.jpg"
                book_image_formated=$(printf '%04d' $((i+1)))

                echo -ne "\r"
                tput el
                echo -n "$(eval_gettext "还剩 \$result_count 本, \$title \${book_image_formated}.jpg")"

                LhhDownload -s -L -A "$USER_AGENT_BROWSER" -b "$COOKIE_FILE" -o "$book_path/${book_image_formated}.jpg" "$book_image"
            done

            echo -ne "\r"
            tput el
        else
            j=0

            while [ -n "${1:-}" ] 
            do
                book_images_count="${1%-*}"
                book_images_name="${1#*-}"

                i=2
                until [ ! -d "$book_path/${book_images_name}" ] 
                do
                    if [ "$i" -gt 2 ] 
                    then
                        book_images_name="${book_images_name%-*}"
                    fi
                    book_images_name="${book_images_name}-$i"
                    i=$((i+1))
                done

                mkdir -p "$book_path/${book_images_name}"

                for((i=j;i<book_images_count+j;i++));
                do
                    book_image="https://picx.zhimg.com/${book_images[i]}_r.jpg"
                    book_image_formated=$(printf '%04d' $((i-j+1)))

                    echo -ne "\r"
                    tput el
                    echo -n "$(eval_gettext "还剩 \$result_count 本, \$title \${book_image_formated}.jpg")"

                    LhhDownload -s -L -A "$USER_AGENT_BROWSER" -b "$COOKIE_FILE" -o "$book_path/${book_images_name}/${book_image_formated}.jpg" "$book_image"
                done

                echo -ne "\r"
                tput el

                shift

                j=$((j+book_images_count))
            done
        fi
    }

    HdlzToutiaoDownload()
    {
        local id=$1 title=$2 i j
        local book_path="$save_dir/${title//\//_}"

        i=2
        until [ ! -d "$book_path" ] 
        do
            if [ "$i" -gt 2 ] 
            then
                book_path="${book_path%-*}"
            fi
            book_path="${book_path}-$i"
            i=$((i+1))
        done

        if ! book_images=($(LhhDownload -s -L -A "$getinfo_useragent" -H "referer: $signed_url" -H "cookie: ${toutiao_cookies[*]}" "https://www.toutiao.com/article/${id}" | grep -oP '<article[^>]*>.*?</article>' | grep -oP '<img[^>]*src="\K[^"]*(?=")'))
        then
            return 1
        fi

        mkdir -p "$book_path"

        book_images_total=${#book_images[@]}

        for((i=0;i<book_images_total;i++));
        do
            book_image="${book_images[i]}"
            book_image_formated=$(printf '%04d' $((i+1)))

            echo -ne "\r"
            tput el
            echo -n "$(eval_gettext "还剩 \$result_count 本, \$title \${book_image_formated}.jpg")"

            while true 
            do
                curl_retry=false
                curl_print_error=false
                if ! LhhDownload -s -Lm 20 -A "$getinfo_useragent" -H "referer: https://www.toutiao.com/article/${id}" -H "cookie: ${toutiao_cookies[*]}" -o "$book_path/${book_image_formated}.jpg" "$book_image" 
                then
                    HdlzGetTouTiaoCookies
                    if ! book_images=($(LhhDownload -s -L -A "$getinfo_useragent" -H "referer: $signed_url" -H "cookie: ${toutiao_cookies[*]}" "https://www.toutiao.com/article/${id}" | grep -oP '<article[^>]*>.*?</article>' | grep -oP '<img[^>]*src="\K[^"]*(?=")'))
                    then
                        Println "$(eval_gettext "\$error 无法获取图片")\n"
                        exit 1
                    fi
                    continue
                fi
                break
            done
        done

        echo -ne "\r"
        tput el
    }

    HdlzGetTouTiaoCookies()
    {
        if ! toutiao_init=$(node "$NODE_ROOT"/toutiao/browser.js)
        then
            Println "$(eval_gettext "\$error 无法使用 头条 node")\n"
            exit 1
        fi

        SetDelimiters

        jq_payload=$(JQs flat "$toutiao_init")

        jq_path='[
            ["data","getinfo","url"],
            ["data","feed","url"],
            ["data","feed","headers","cookie"],
            ["data","feed","headers","referer"],
            ["data","getinfo","headers","referer"],
            ["data","getinfo","headers","user-agent"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        getinfo_url="$jq_data_getinfo_url"
        signed_url="$jq_data_feed_url"
        feed_cookie="$jq_data_feed_headers_cookie"
        feed_referer="$jq_data_feed_headers_referer"
        getinfo_referer="$jq_data_getinfo_headers_referer"
        getinfo_useragent="$jq_data_getinfo_headers_user-agent"

        if [[ "${feed_cookie}" =~ (.*)tt_scid=([^\;]+)\;\ (.*) ]] || [[ "${feed_cookie}" =~ (.*)tt_scid=([^ ]+)(.*) ]] 
        then
            cookie_tt_scid="${BASH_REMATCH[2]}"
            toutiao_cookies=( ${feed_cookie} )
        else
            if [[ "${feed_cookie}" =~ (.*)ttcid=([^\;]+)\;\ (.*) ]] || [[ "${feed_cookie}" =~ (.*)ttcid=([^ ]+)(.*) ]]
            then
                feed_cookie="${BASH_REMATCH[1]}${BASH_REMATCH[3]:-}"
            fi

            cookie_tt_scid=($(CurlFake -s -Lm 20 -A "$getinfo_useragent" -H "cookie: $feed_cookie" -H "referer: $getinfo_referer" -D - -o /dev/null "$getinfo_url" | grep -i 'set-cookie' | awk '{print $2}'))
            toutiao_cookies=( ${cookie_tt_scid[@]} ${feed_cookie} )
        fi

        cookie_mstoken=$(RandStr 64)
        cookie_verify="verify_$(RandStr 8)_$(RandStr 8)_$(RandStr 4)_$(RandStr 4)_$(RandStr 4)_$(RandStr 12)"
        toutiao_cookies=( "msToken=${cookie_mstoken};" "s_v_web_id=${cookie_verify};" ${toutiao_cookies[@]} )
        toutiao_cookies_json="$(CookiesToJson www.toutiao.com ${toutiao_cookies[@]})"
    }

    HdlzLhh()
    {
        if [ ! -s "$LIANHUANHUA_CONFIG" ] 
        then
            mkdir -p "$LIANHUANHUA_ROOT/"
            printf '{"%s":{"%s":[]}}' "books" "hdlz" > "$LIANHUANHUA_CONFIG"
        fi

        SetDelimiters

        jq_payload=$(JQs flat "$LIANHUANHUA_CONFIG")

        jq_path='[
            ["default","save_dir"],
            ["books","hdlz","source"],
            ["books","hdlz","id"],
            ["books","hdlz","title"],
            ["books","hdlz","cover"],
            ["books","hdlz","excerpt"],
            ["books","hdlz","behot_time"],
            ["books","hdlz","downloaded"],
            ["books","hdlz","fav"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        default_save_dir="$jq_default_save_dir"

        IFS="${delimiters[3]}" read -r -a books_source <<< "$jq_books_hdlz_source"
        IFS="${delimiters[3]}" read -r -a books_id <<< "$jq_books_hdlz_id"
        IFS="${delimiters[3]}" read -r -a books_title <<< "$jq_books_hdlz_title"
        IFS="${delimiters[3]}" read -r -a books_cover <<< "$jq_books_hdlz_cover"
        IFS="${delimiters[3]}" read -r -a books_excerpt <<< "$jq_books_hdlz_excerpt"
        IFS="${delimiters[3]}" read -r -a books_behot_time <<< "$jq_books_hdlz_behot_time"
        IFS="${delimiters[3]}" read -r -a books_downloaded <<< "$jq_books_hdlz_downloaded"
        IFS="${delimiters[3]}" read -r -a books_fav <<< "$jq_books_hdlz_fav"

        if [ "${lhh_hdlz_menu_locale:-}" != "${sh_locale:-zh_CN}" ]
        then
            lhh_hdlz_lookup_options_cache=( "$(gettext "不查询")" "$(gettext "查询知乎")" "$(gettext "查询头条")" "$(gettext "查询全部")" )
            lhh_hdlz_result_options_cache=( "$(gettext "下载")" "$(gettext "收藏")" "$(gettext "取消收藏")" )
            lhh_hdlz_menu_locale="${sh_locale:-zh_CN}"
        fi

        local books_total=${#books_source[@]} i j lookup_options_index=0

        if [ "$books_total" -gt 0 ] 
        then
            echo
            lookup_options=( "${lhh_hdlz_lookup_options_cache[@]}" )
            inquirer list_input_index "$(gettext "是否重新查询")" lookup_options lookup_options_index
        fi

        COOKIE_FILE="$LIANHUANHUA_ROOT/cookie_hdlz"

        if [ "$books_total" -eq 0 ] || [ "$lookup_options_index" -eq 1 ] || [ "$lookup_options_index" -eq 3 ]
        then
            if ! CurlFake -s -L -b "$COOKIE_FILE" -c "$COOKIE_FILE" https://www.zhihu.com/column/c_1396234006309003264 > /dev/null
            then
                Println "$(eval_gettext "\$error 无法连接知乎, 请稍后再试")"
                exit 1
            fi

            local loop=0 books new_book i18n_search_zhihu i18n_zhihu_total
            i18n_search_zhihu=$(gettext "搜索知乎")
            i18n_zhihu_total=$(gettext "共 2568 条")

            while true 
            do
                echo -ne "\r"
                tput el

                echo -n "$i18n_search_zhihu $((1+loop*20))~$((20+loop*20)), $i18n_zhihu_total"

                response=$(
                    CurlFake -s -L -b "$COOKIE_FILE" -H "Referer: https://www.zhihu.com/column/c_1396234006309003264" ${paging_next:-'http://www.zhihu.com/api/v4/columns/c_1396234006309003264/items?limit=20&offset=0'}
                )

                jq_payload=$(JQs flat "$response")

                jq_path='[
                    ["paging","is_end"],
                    ["paging","next"],
                    ["paging","previous"],
                    ["data","excerpt"],
                    ["data","id"],
                    ["data","image_url"],
                    ["data","title"]
                ]'

                while IFS=": " read -r path_name value; do
                    var_name=${path_name}
                    read -r ${var_name?} <<< "$value"
                done < <(JQs gets jq_payload)

                paging_is_end="$jq_paging_is_end"
                paging_next="$jq_paging_next"
                paging_previous="$jq_paging_previous"

                IFS="${delimiters[2]}" read -r -a result_excerpt <<< "$jq_data_excerpt"

                if [ -z "${result_excerpt:-}" ] 
                then
                    paging_next="$paging_previous"
                    continue
                fi

                IFS="${delimiters[2]}" read -r -a result_id <<< "$jq_data_id"
                IFS="${delimiters[2]}" read -r -a result_cover <<< "$jq_data_image_url"
                IFS="${delimiters[2]}" read -r -a result_title <<< "$jq_data_title"

                result_total=${#result_id[@]}
                books_total=$((books_total+result_total))
                books=""

                for((i=0;i<result_total;i++));
                do
                    if [ -z "${books_id:-}" ] || ! EleInArray "${result_id[i]}" books_id
                    then
                        books_id+=("${result_id[i]}")
                    else
                        books_total=$((books_total-1))
                        continue
                    fi

                    book_images_command=()
                    book_excerpts=(${result_excerpt[i]} end)
                    book_images_count=0
                    book_images_name=""

                    for((j=0;j<${#book_excerpts[@]};j++));
                    do
                        if [ "${book_excerpts[j]}" == "[图片]" ] 
                        then
                            book_images_count=$((book_images_count+1))
                        elif [ "${book_excerpts[j]}" == "end" ] 
                        then
                            if [ "${book_excerpts[j-1]}" == "[图片]" ] && [ -n "${book_images_command:-}" ] 
                            then
                                if [ "${#book_images_command[@]}" -eq 1 ] 
                                then
                                    if [ "$book_images_count" -eq 1 ] 
                                    then
                                        book_images_command=()
                                        break
                                    fi
                                else
                                    if [ "$book_images_count" -eq 1 ] 
                                    then
                                        book_images_command_count="${#book_images_command[@]}"
                                        book_images_command_last="${book_images_command[book_images_command_count-1]}"
                                        book_images_command_last_num=${book_images_command_last%-*}
                                        book_images_command_last_name=${book_images_command_last#*-}
                                        book_images_command[book_images_command_count-1]="$((book_images_command_last_num+1))-${book_images_command_last_name}"
                                        break
                                    fi
                                fi
                                book_images_command+=( "${book_images_count}-${book_images_name:-未分类}" )
                            else
                                book_images_command=()
                            fi
                        else
                            if [ "$book_images_count" -le 1 ] || [ "${#book_excerpts[j]}" -ge 10 ]
                            then
                                continue
                            fi

                            book_images_command+=( "${book_images_count}-${book_images_name:-未分类}" )
                            book_images_count=0

                            book_images_name="${book_excerpts[j]}"
                        fi
                    done

                    books_source+=("zhihu")
                    books_title+=("${result_title[i]}")
                    books_cover+=("${result_cover[i]}")
                    books_excerpt+=("${book_images_command[*]:-}")
                    books_downloaded+=("false")
                    books_fav+=("false")
                    new_book=$(
                    $JQ_FILE -n --arg source "zhihu" --arg id "${result_id[i]}" \
                    --arg title "${result_title[i]}" --arg cover "${result_cover[i]}" \
                    --arg excerpt "${book_images_command[*]:-}" \
                        '{
                            source: $source,
                            id: $id,
                            title: $title,
                            cover: $cover,
                            excerpt: $excerpt,
                            downloaded: false,
                            fav: false
                        }'
                    )

                    [ -n "${books:-}" ] && books="${books},"
                    books="${books}${new_book}"
                done

                loop=$((loop+1))

                if [ "$paging_is_end" = true ] 
                then
                    echo -ne "\r"
                    tput el
                    break
                fi

                if [ -z "${books:-}" ] 
                then
                    continue
                fi

                jq_path='["books","hdlz"]'
                JQ add "$LIANHUANHUA_CONFIG" "[$books]"
            done
        fi

        if [ "$books_total" -eq 0 ] || [ "$lookup_options_index" -eq 2 ] || [ "$lookup_options_index" -eq 3 ] 
        then
            NodejsInstall
            NodeInstallToutiao

            HdlzGetTouTiaoCookies

            # last_behot_time=$(date +%s)
            # for((i=0;i<books_total;i++));
            # do
            #     if [ "${books_source[i]}" = "toutiao" ] && [ "${books_behot_time[i]}" -lt "$last_behot_time" ]
            #     then
            #         last_behot_time="${books_behot_time[i]}"
            #     fi
            # done

            # if [[ "${feed_cookie}" =~ (.*)__ac_nonce=([^\;]+)\;\ (.*) ]] || [[ "${feed_cookie}" =~ (.*)__ac_nonce=([^ ]+)(.*) ]] 
            # then
            #    cookie_nonce="${BASH_REMATCH[2]}"
            # fi
            # cookie_signature=$(node "$NODE_ROOT"/toutiao/browser.js "$cookie_nonce" "$toutiao_cookies_json" | $JQ_FILE -r '.data.signature')

            signed_url="https://www.toutiao.com/api/pc/list/user/feed?category=profile_all&token=MS4wLjABAAAAB2ev2na9xNHI8py8dnKvLnSYGkxaFKDtOQTqbR7nsEzpNhwVqpCY8ZZz6s7qA8vt&max_behot_time=0&aid=24&app_name=toutiao_web"
            IFS= read -r a_bogus < <(node "$NODE_ROOT"/toutiao/browser.js "$signed_url" "$toutiao_cookies_json" | $JQ_FILE -r '.data."a-bogus"')
            signed_url="${signed_url}&a_bogus=${a_bogus}"

            local toutiao_total=0 i18n_search_toutiao
            i18n_search_toutiao=$(gettext "搜索头条")

            while true 
            do
                if ! jq_input=$(LhhDownload -s -Lm 20 -A "$getinfo_useragent" -H "referer: $feed_referer" -H "cookie: ${toutiao_cookies[*]}" "$signed_url" | $JQ_FILE -c '.data |= map({id, behot_time, title})' 2> /dev/null)
                then
                    result_total=0
                else
                    jq_payload=$(JQs flat "$jq_input")

                    jq_path='[
                        ["has_more"],
                        ["next","max_behot_time"],
                        ["data","id"],
                        ["data","behot_time"],
                        ["data","title"]
                    ]'

                    while IFS=": " read -r path_name value; do
                        var_name=${path_name}
                        read -r ${var_name?} <<< "$value"
                    done < <(JQs gets jq_payload)

                    has_more="$jq_has_more"
                    max_behot_time="$jq_next_max_behot_time"

                    IFS="${delimiters[2]}" read -r -a result_id <<< "$jq_data_id"
                    IFS="${delimiters[2]}" read -r -a result_behot_time <<< "$jq_data_behot_time"
                    IFS="${delimiters[2]}" read -r -a result_title <<< "$jq_data_title"

                    result_total=${#result_id[@]}
                fi

                while true 
                do
                    if [ "$result_total" -gt 0 ] 
                    then
                        max_behot_time=$m_max_behot_time
                    else
                        cookie_mstoken=$(RandStr 64)
                        cookie_verify="verify_$(RandStr 8)_$(RandStr 8)_$(RandStr 4)_$(RandStr 4)_$(RandStr 4)_$(RandStr 12)"
                        toutiao_cookies[0]="msToken=${cookie_mstoken};"
                        toutiao_cookies[1]="s_v_web_id=${cookie_verify};"
                        toutiao_cookies_json="$(CookiesToJson www.toutiao.com ${toutiao_cookies[@]})"
                    fi

                    if ! signed_response=$(node "$NODE_ROOT"/toutiao/browser.js "https://www.toutiao.com/api/pc/list/user/feed?category=profile_all&token=MS4wLjABAAAAB2ev2na9xNHI8py8dnKvLnSYGkxaFKDtOQTqbR7nsEzpNhwVqpCY8ZZz6s7qA8vt&max_behot_time=${max_behot_time:-0}&aid=24&app_name=toutiao_web" "$toutiao_cookies_json")
                    then
                        sleep 12
                        continue
                    fi

                    if ! a_bogus=$($JQ_FILE -r '.data."a-bogus"' <<< "$signed_response" 2> /dev/null) 
                    then
                        Println "$error $signed_response\n"
                        continue
                    fi

                    signed_url="${signed_url%&*}&a_bogus=${a_bogus}"

                    if [ "$result_total" -eq 0 ] 
                    then
                        continue 2
                    fi
                    break
                done

                echo -ne "\r"
                tput el

                echo -n "$i18n_search_toutiao $((toutiao_total+1))~$((toutiao_total+result_total))"

                toutiao_total=$((toutiao_total+result_total))

                # if [ "${result_behot_time[result_total-1]}" -gt "$last_behot_time" ] 
                # then
                #     continue
                # fi

                books_total=$((books_total+result_total))
                books=""

                for((i=0;i<result_total;i++));
                do
                    if [ -n "${result_title[i]}" ] && { [ -z "${books_id:-}" ] || ! EleInArray "${result_id[i]}" books_id ;} 
                    then
                        books_id+=("${result_id[i]}")
                    else
                        books_total=$((books_total-1))
                        continue
                    fi

                    books_source+=("toutiao")
                    books_title+=("${result_title[i]}")
                    books_downloaded+=("false")
                    books_fav+=("false")

                    new_book=$(
                    $JQ_FILE -n --arg source "toutiao" --arg id "${result_id[i]}" \
                    --arg title "${result_title[i]}" --arg behot_time "${result_behot_time[i]}" \
                        '{
                            source: $source,
                            id: $id,
                            title: $title,
                            behot_time: $behot_time | tonumber,
                            downloaded: false,
                            fav: false
                        }'
                    )

                    [ -n "${books:-}" ] && books="${books},"
                    books="${books}${new_book}"
                done

                if [ "$has_more" = false ] 
                then
                    echo -ne "\r"
                    tput el
                    break
                fi

                if [ -z "${books:-}" ] 
                then
                    continue
                fi

                jq_path='["books","hdlz"]'
                JQ add "$LIANHUANHUA_CONFIG" "[$books]"
            done
        fi

        # dy_163_docid=($(CurlFake -s -L -b "$COOKIE_FILE" -c "$COOKIE_FILE" https://www.163.com/dy/media/T1624341866994.html | grep -oP '<a href="https://www.163.com/dy/article/\K[^.]+' | uniq))

        result_title=()
        local i18n_downloaded i18n_favorited
        i18n_downloaded=$(gettext "已下载")
        i18n_favorited=$(gettext "已收藏")

        for((i=0;i<books_total;i++));
        do
            result_title[i]="${books_title[i]#*｜}"
            if [ "${books_downloaded[i]}" = true ] 
            then
                result_title[i]="${result_title[i]} ${green}[${i18n_downloaded}]${normal}"
            fi
            if [ "${books_fav[i]}" = true ] 
            then
                result_title[i]="${result_title[i]} ${green}[${i18n_favorited}]${normal}"
            fi
        done

        echo
        inquirer checkbox_input_indices "$(gettext "选择连环画")" result_title result_indices 20

        echo
        result_options=( "${lhh_hdlz_result_options_cache[@]}" )
        inquirer checkbox_input_indices "$i18n_select_action" result_options result_options_indices

        for result_options_index in "${result_options_indices[@]}"
        do
            if [ "$result_options_index" -eq 0 ] 
            then
                echo
                inquirer text_input "$(gettext "输入存储文件夹目录")" save_dir "${default_save_dir}"
                RemoveQuotes save_dir
                if [ -z "$save_dir" ] 
                then
                    Println "$i18n_canceled...\n"
                    exit 1
                fi

                if [ "$save_dir" != "$default_save_dir" ] 
                then
                    jq_path='["default","save_dir"]'
                    JQ update "$LIANHUANHUA_CONFIG" "$save_dir"
                fi

                local all_success=true all_failed=true i18n_download_failed
                i18n_download_failed=$(gettext "下载失败, 请检查资源是否存在")
                result_count="${#result_indices[@]}"

                for result_index in "${result_indices[@]}"
                do
                    result_count=$((result_count-1))
                    if [ "${books_source[result_index]}" == "zhihu" ] 
                    then
                        if ! HdlzZhihuDownload "${books_id[result_index]}" "${books_title[result_index]#*｜}" ${books_excerpt[result_index]}
                        then
                            Println "$error ${books_title[result_index]#*｜} $i18n_download_failed https://zhuanlan.zhihu.com/p/${books_id[result_index]}\n"
                            all_success=false
                            continue
                        fi
                    else
                        if [ -z "${toutiao_init:-}" ] 
                        then
                            HdlzGetTouTiaoCookies
                        fi
                        if ! HdlzToutiaoDownload "${books_id[result_index]}" "${books_title[result_index]#*｜}"
                        then
                            Println "$error ${books_title[result_index]#*｜} $i18n_download_failed https://www.toutiao.com/article/${books_id[result_index]}\n"
                            all_success=false
                            continue
                        fi
                    fi

                    all_failed=false

                    if [ "${books_downloaded[result_index]}" = false ] 
                    then
                        jq_bool=true
                        jq_path='["books","hdlz",'"$result_index"',"downloaded"]'
                        JQ update "$LIANHUANHUA_CONFIG" true
                    fi
                done

                if [ "$all_failed" = true ] 
                then
                    Println "$(eval_gettext "\$error 所有资源下载失败")\n"
                    exit 1
                elif [ "$all_success" = true ] 
                then
                    Println "$(eval_gettext "\$info 下载完成")\n"
                else
                    Println "$(eval_gettext "\$info 部分下载完成")\n"
                fi
            elif [ "$result_options_index" -eq 1 ] 
            then
                for result_index in "${result_indices[@]}"
                do
                    jq_bool=true
                    jq_path='["books","hdlz",'"$result_index"',"fav"]'
                    JQ update "$LIANHUANHUA_CONFIG" true
                done
                Println "$(eval_gettext "\$info 已添加到收藏")\n"
            else
                for result_index in "${result_indices[@]}"
                do
                    jq_bool=true
                    jq_path='["books","hdlz",'"$result_index"',"fav"]'
                    JQ update "$LIANHUANHUA_CONFIG" false
                done
                Println "$(eval_gettext "\$info 已取消收藏")\n"
            fi
        done
    }

    DangValidateId()
    {
        if [ "$1" == "$i18n_cancel" ]
        then
            return 0
        fi

        book_id=${1##*/}
        book_id=${book_id%%_*}

        if [ "$books_total" -gt 0 ] 
        then
            local id
            for id in "${books_id[@]}"
            do
                if [ "$id" == "$book_id" ] 
                then
                    return 1
                fi
            done
        fi

        return 0
    }

    DangValidateStartPage()
    {
        if [ "$1" == "$i18n_cancel" ] || [[ $1 =~ ^[0-9]+$ ]]
        then
            return 0
        fi

        return 1
    }

    DangValidateEndPage()
    {
        if [ "$1" == "$i18n_cancel" ] || { [[ $1 =~ ^[0-9]+$ ]] && [ "$1" -ge "$book_start" ]; }
        then
            return 0
        fi

        return 1
    }

    DangCloudDownload()
    {
        echo
        inquirer text_input "$(gettext "输入存储文件夹目录")" save_dir "${default_save_dir}"
        RemoveQuotes save_dir

        if [ -z "$save_dir" ] 
        then
            Println "$i18n_canceled...\n"
            return 1
        fi

        if [ "$save_dir" != "$default_save_dir" ] 
        then
            jq_path='["default","save_dir"]'
            JQ update "$LIANHUANHUA_CONFIG" "$save_dir"
        fi

        local book_path="$save_dir/${book_title//\//_}"
        local book_images_count=$((book_end-book_start+1))

        local i=2
        until [ ! -d "$book_path" ] 
        do
            if [ "$i" -gt 2 ] 
            then
                book_path="${book_path%-*}"
            fi
            book_path="${book_path}-$i"
            i=$((i+1))
        done

        mkdir -p "$book_path"

        book_image_format_num=${#book_end}
        book_image_formated=$(printf "%0${book_image_format_num}d" $book_start)
        LhhDownload -s -L -A "$USER_AGENT_BROWSER" -o "$book_path/${book_image_formated}.jpg" "${book_img%/*}/${book_id}_cover_epub.jpg"

        book_image_formated=$(printf "%0${book_image_format_num}d" $((book_start+1)))
        LhhDownload -s -L -A "$USER_AGENT_BROWSER" -o "$book_path/${book_image_formated}.jpg" "${book_img%/*}/${book_id}_F001_epub.jpg"

        book_image_formated=$(printf "%0${book_image_format_num}d" $((book_start+2)))
        LhhDownload -s -L -A "$USER_AGENT_BROWSER" -o "$book_path/${book_image_formated}.jpg" "${book_img%/*}/${book_id}_F002_epub.jpg"

        local i18n_remaining i18n_pages
        i18n_remaining=$(gettext "还剩")
        i18n_pages=$(gettext "张")

        for((i=0;i<book_images_count;i++));
        do
            book_image_formated=$(printf "%0${book_image_format_num}d" $((book_start+i)))
            book_image_save_formated=$(printf "%0${book_image_format_num}d" $((book_start+i+3)))

            echo -ne "\r"
            tput el
            echo -n "$i18n_remaining $((book_images_count-i)) $i18n_pages, $book_title ${book_image_formated}.jpg"

            LhhDownload -s -L -A "$USER_AGENT_BROWSER" -o "$book_path/${book_image_save_formated}.jpg" "${book_img%/*}/${book_id}_P${book_image_formated}_epub.jpg"
        done

        echo -ne "\r"
        tput el
    }

    DangCloud()
    {
        if [ "${lhh_dang_menu_locale:-}" != "${sh_locale:-zh_CN}" ]
        then
            lhh_dang_options_cache=( "$i18n_add" "$(gettext "选择")" )
