        fi

        if [ ! -s "$LIANHUANHUA_CONFIG" ] 
        then
            mkdir -p "$LIANHUANHUA_ROOT/"
            printf '{"%s":{"%s":[]}}' "books" "dang" > "$LIANHUANHUA_CONFIG"
        fi

        SetDelimiters

        jq_payload=$(JQs flat "$LIANHUANHUA_CONFIG")

        jq_path='[
            ["default","save_dir"],
            ["books","dang","id"],
            ["books","dang","title"],
            ["books","dang","cover"],
            ["books","dang","start"],
            ["books","dang","end"],
            ["books","dang","downloaded"],
            ["books","dang","fav"]
        ]'

        while IFS=": " read -r path_name value; do
            var_name=${path_name}
            read -r ${var_name?} <<< "$value"
        done < <(JQs gets jq_payload)

        default_save_dir="$jq_default_save_dir"

        IFS="${delimiters[3]}" read -r -a books_id <<< "$jq_books_dang_id"
        IFS="${delimiters[3]}" read -r -a books_title <<< "$jq_books_dang_title"
        IFS="${delimiters[3]}" read -r -a books_cover <<< "$jq_books_dang_cover"
        IFS="${delimiters[3]}" read -r -a books_start <<< "$jq_books_dang_start"
        IFS="${delimiters[3]}" read -r -a books_end <<< "$jq_books_dang_end"
        IFS="${delimiters[3]}" read -r -a books_downloaded <<< "$jq_books_dang_downloaded"
        IFS="${delimiters[3]}" read -r -a books_fav <<< "$jq_books_dang_fav"

        local books_total=${#books_id[@]}

        dang_options_index=0

        if [ "$books_total" -gt 0 ] 
        then
            echo
            dang_options=( "${lhh_dang_options_cache[@]}" )
            inquirer list_input_index "$i18n_select_action" dang_options dang_options_index
        fi

        if [ "$dang_options_index" -eq 0 ] 
        then
            echo
            ExitOnText "$(gettext "输入书名")" book_title

            Println "$(eval_gettext "\$tip 比如 https://img7x6.ddimg.cn/imgother10/xx/xx/xxxxxxxxxx_cover_epub.jpg")"
            ExitOnText "$(gettext "输入图片链接")" book_img DangValidateId "$(gettext "此书已经存在")"

            book_id=${book_img##*/}
            book_id=${book_id%%_*}

            echo
            ExitOnText "$(gettext "输入起始页码")" book_start DangValidateStartPage "$(gettext "请输入数字")"

            echo
            ExitOnText "$(gettext "输入结束页码")" book_end DangValidateEndPage "$(gettext "请输入数字且不能小于起始页码")"

            echo
            inquirer list_input_index "$(gettext "收藏")" ny_options ny_index

            if [ "$ny_index" -eq 0 ] 
            then
                book_fav=false
            else
                book_fav=true
            fi

            echo
            inquirer list_input_index "$(gettext "下载")" ny_options ny_index

            if [ "$ny_index" -eq 0 ] 
            then
                book_downloaded=false
            else
                DangCloudDownload
                book_downloaded=true
            fi

            new_book=$(
            $JQ_FILE -n --arg id "${book_id}" --arg title "$book_title" \
            --arg cover "${book_img%/*}/${book_id}_cover_epub.jpg" --arg start "$book_start" \
            --arg end "$book_end" --arg downloaded "$book_downloaded" \
            --arg fav "$book_fav" \
                '{
                    id: $id | tonumber,
                    title: $title,
                    cover: $cover,
                    start: $start | tonumber,
                    end: $end | tonumber,
                    downloaded: $downloaded | test("true"),
                    fav: $fav | test("true")
                }'
            )

            jq_path='["books","dang"]'
            JQ add "$LIANHUANHUA_CONFIG" "[$new_book]"

            Println "$(eval_gettext "\$info \${book_title} 添加成功")\n"
        fi

        echo

    }

    if [ "${lhh_menu_locale:-}" != "${sh_locale:-zh_CN}" ]
    then
        lhh_options=( "$(gettext "中华连环画")" "$(gettext "瀚大黎众连环画")" "$(gettext "当当云阅读(漫画)")" )
        lhh_menu_prompt_cache=$(gettext "选择连环画")
        lhh_menu_locale="${sh_locale:-zh_CN}"
    fi

    echo
    inquirer list_input_index "$lhh_menu_prompt_cache" lhh_options lhh_options_index

    case $lhh_options_index in
        0) ZhLhh
        ;;
        1) HdlzLhh
        ;;
        2) DangCloud
        ;;
    esac

    return 0
elif [ "$self" == "rc" ]
then
    Base64urlEncode()
    {
        OpensslInstall

        (if [ -z "${1:-}" ]; then cat -; else echo -n "$1"; fi) |
        openssl base64 -e -A |
        sed s/\\+/-/g |
        sed s/\\//_/g |
        sed -E s/=+$//
    }

    Base64urlDecode()
    {
        OpensslInstall

        local input=$(if [ -z "${1:-}" ]; then echo -n $(cat -); else echo -n "$1"; fi)
        local mod=$(($(echo -n "$input" | wc -c) % 4))
        local padding=$(if [ $mod -eq 2 ]; then echo -n '=='; elif [ $mod -eq 3 ]; then echo -n '=' ; fi)
        echo -n "$input$padding" |
        sed s/-/+/g |
        sed s/_/\\//g |
        openssl base64 -d -A
    }
    Obscure()
    {
        OpensslInstall

        local hexkey="9c935b48730a554d6bfd7c63c886a92bd390198eb8128afbf4de162b8b95f638"
        local hexiv=$(openssl rand -hex 16)
        local buff=$(echo "$1" | openssl enc -aes-256-ctr -K "$hexkey" -iv "$hexiv")
        hexiv=$(echo -n "$hexiv" | xxd -r -p)
        local encrypted=$(echo -n "$hexiv$buff" | Base64urlEncode)

        echo "$encrypted"
    }

    Deobscure()
    {
        OpensslInstall

        local hexkey="9c935b48730a554d6bfd7c63c886a92bd390198eb8128afbf4de162b8b95f638"
        local decoded=$(echo -n "$1" | Base64urlDecode)
        local hexiv=$(echo -n "$decoded" | head -c 16 | hexdump -v -e '/1 "%02x"') # xxd -p
        local buff=$(echo -n "$decoded" | tail -c +17)
        local decrypted=$(echo -n "$buff" | openssl enc -aes-256-ctr -d -K "$hexkey" -iv "$hexiv" -nopad)

        echo "$decrypted"
    }
    RcloneConfigUpdate()
    {
        if [ -z "${rclone_remotes_count:-}" ] 
        then
            ServiceGet rclone remote
        fi

        if [ "$rclone_remotes_count" -gt 0 ] 
        then
            local i rclone_config=""
            for((i=0;i<rclone_remotes_count;i++));
            do
                rclone_config="${rclone_config}[${rclone_remotes_name[i]}]\ntype = ${rclone_remotes_type[i]}\nurl = ${rclone_remotes_url[i]}\nvendor = ${rclone_remotes_vendor[i]}\nuser = ${rclone_remotes_user[i]}\npass = ${rclone_remotes_pass[i]}\n\n"
            done
            mkdir -p "$HOME/.config/rclone"
            echo -ne "$rclone_config" > "$HOME/.config/rclone/rclone.conf"
        fi
    }
    RcloneRemoteView()
    {
        ServiceGet rclone remote

        if [ "$rclone_remotes_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加 rclone 远端")\n"
            return 1
        fi

        rclone_remotes=()
        rclone_remotes_options=()

        local i rclone_remotes_list="" rclone_remote_list=""
        local i18n_type i18n_vendor i18n_user
        i18n_type=$(gettext "类型")
        i18n_vendor=$(gettext "供应")
        i18n_user=$(gettext "用户")

        for((i=0;i<rclone_remotes_count;i++));
        do
            rclone_remote_list="${i18n_name}: ${rclone_remotes_name[i]} ${i18n_type}: ${rclone_remotes_type[i]}\n${i18n_vendor}: ${rclone_remotes_vendor[i]} ${i18n_user}: ${rclone_remotes_user[i]}\n${i18n_address}: ${rclone_remotes_url[i]}\n\n"
            rclone_remotes_list="${rclone_remotes_list}${green}$((i+1)).${normal} $rclone_remote_list"
            rclone_remotes+=("$rclone_remote_list")
            rclone_remotes_options+=("${i18n_name}: ${rclone_remotes_name[i]} ${i18n_address}: ${rclone_remotes_url[i]}")
        done

        Println "$rclone_remotes_list"
    }

    RcloneRemoteAddNameValidator()
    {
        if [ "$1" != "$i18n_cancel" ] && [ "$rclone_remotes_count" -gt 0 ] && EleInArray "$1" rclone_remotes_name
        then
            return 1
        fi

        return 0
    }

    RcloneRemoteAdd()
    {
        ServiceGet rclone remote

        echo
        ExitOnText "$(gettext "输入远端名称")" rclone_remote_name RcloneRemoteAddNameValidator "$(gettext "远端名称已存在")"

        rclone_remote_types=( webdav )
        echo
        inquirer checkbox_input_indices "$(gettext "选择远端类型")" rclone_remote_types rclone_remote_types_index

        Println "$(eval_gettext "\$tip 比如 https://domain.com/dav")"
        ExitOnText "$(gettext "输入远端地址")" rclone_remote_url

        rclone_remote_vendors=( rclone other )
        echo
        inquirer list_input_index "$(gettext "选择远端供应")" rclone_remote_vendors rclone_remote_vendors_index

        echo
        ExitOnText "$(gettext "输入远端用户")" rclone_remote_user

        echo
        ExitOnText "$(gettext "输入远端用户密码")" rclone_remote_pass

        new_remote=$(
        $JQ_FILE -n --arg name "$rclone_remote_name" --arg type "${rclone_remote_types[rclone_remote_types_index]}" \
        --arg url "$rclone_remote_url" --arg vendor "${rclone_remote_vendors[rclone_remote_vendors_index]}" \
        --arg user "$rclone_remote_user" --arg pass "$(rclone obscure ${rclone_remote_pass})" \
            '{
                name: $name,
                type: $type,
                url: $url,
                vendor: $vendor,
                user: $user,
                pass: $pass
            }'
        )

        jq_path='["rclone","remote"]'
        JQ add "$SERVICES_CONFIG" "[$new_remote]"

        Println "$(eval_gettext "\$info 远端添加成功")\n"
    }

    RcloneRemoteEditNameValidator()
    {
        if [ "$1" != "${rclone_remotes_name[rclone_remotes_index]}" ] && EleInArray "$1" rclone_remotes_name
        then
            return 1
        fi

        return 0
    }

    RcloneRemoteEdit()
    {
        RcloneRemoteView

        echo
        inquirer checkbox_input_indices "$(gettext "选择修改的远端")" rclone_remotes_options rclone_remotes_indices

        rclone_remote_edit_options=( "$i18n_name" "$(gettext "类型")" "$i18n_address" "$(gettext "供应")" "$(gettext "用户")" "$i18n_password" )
        rclone_remote_vendors=( rclone other )

        for rclone_remotes_index in "${rclone_remotes_indices[@]}"
        do
            Println "${rclone_remotes[${rclone_remotes_index}]}"
            inquirer checkbox_input_indices "$(gettext "选择修改的内容")" rclone_remote_edit_options rclone_remote_edit_options_indices

            for rclone_remote_edit_options_index in "${rclone_remote_edit_options_indices[@]}"
            do
                case $rclone_remote_edit_options_index in
                    0) 
                        echo
                        inquirer text_input "$(gettext "输入新名称")" rclone_remote_name "${rclone_remotes_name[rclone_remotes_index]}" RcloneRemoteEditNameValidator "$(gettext "远端名称已存在")"
                        if [ "$rclone_remote_name" != "${rclone_remotes_name[rclone_remotes_index]}" ] 
                        then
                            rclone_remotes_name[rclone_remotes_index]="$rclone_remote_name"
                            jq_path='["rclone","remote",'"$rclone_remotes_index"',"name"]'
                            JQ update "$SERVICES_CONFIG" "$rclone_remote_name"
                            Println "$(eval_gettext "\$info 名称修改成功")\n"
                        fi
                    ;;
                    1) 

                    ;;
                    2) 
                        echo
                        inquirer text_input "$(gettext "输入新地址")" rclone_remote_url "${rclone_remotes_url[rclone_remotes_index]}"
                        if [ "$rclone_remote_url" != "${rclone_remotes_url[rclone_remotes_index]}" ] 
                        then
                            jq_path='["rclone","remote",'"$rclone_remotes_index"',"url"]'
                            JQ update "$SERVICES_CONFIG" "$rclone_remote_url"
                            Println "$(eval_gettext "\$info 地址修改成功")\n"
                        fi
                    ;;
                    3) 
                        echo
                        inquirer list_input_index "$(gettext "选择新供应")" rclone_remote_vendors rclone_remote_vendors_index
                        if [ "${rclone_remote_vendors[rclone_remote_vendors_index]}" != "${rclone_remotes_vendor[rclone_remotes_index]}" ] 
                        then
                            jq_path='["rclone","remote",'"$rclone_remotes_index"',"vendor"]'
                            JQ update "$SERVICES_CONFIG" "${rclone_remote_vendors[rclone_remote_vendors_index]}"
                            Println "$(eval_gettext "\$info 供应修改成功")\n"
                        fi
                    ;;
                    4) 
                        echo
                        inquirer text_input "$(gettext "输入新用户")" rclone_remote_user "${rclone_remotes_user[rclone_remotes_index]}"
                        if [ "$rclone_remote_user" != "${rclone_remotes_user[rclone_remotes_index]}" ] 
                        then
                            jq_path='["rclone","remote",'"$rclone_remotes_index"',"user"]'
                            JQ update "$SERVICES_CONFIG" "$rclone_remote_user"
                            Println "$(eval_gettext "\$info 用户修改成功")\n"
                        fi
                    ;;
                    5) 
                        echo
                        rclone_remote_pass_decrypted=$(Deobscure "${rclone_remotes_pass[rclone_remotes_index]}")
                        inquirer text_input "$(gettext "输入新密码")" rclone_remote_pass "$rclone_remote_pass_decrypted"
                        if [ "$rclone_remote_pass" != "$rclone_remote_pass_decrypted" ] 
                        then
                            jq_path='["rclone","remote",'"$rclone_remotes_index"',"pass"]'
                            JQ update "$SERVICES_CONFIG" "$(rclone obscure ${rclone_remote_pass})"
                            Println "$(eval_gettext "\$info 密码修改成功")\n"
                        fi
                    ;;
                esac
            done
        done

        return 0
    }

    RcloneRemoteDel()
    {
        RcloneRemoteView

        echo
        inquirer checkbox_input_indices "$(gettext "选择删除的远端")" rclone_remotes_options rclone_remotes_indices

        local rclone_remotes_index_offset=0

        for rclone_remotes_index in "${rclone_remotes_indices[@]}"
        do
            jq_path='["rclone","remote",'"$((rclone_remotes_index-rclone_remotes_index_offset))"']'
            JQ delete "$SERVICES_CONFIG"
            rclone_remotes_index_offset=$((rclone_remotes_index_offset+1))
        done

        Println "$(eval_gettext "\$info 远端删除成功")\n"
    }
    RcloneMountView()
    {
        RcloneRemoteView

        echo
        inquirer list_input_index "$(gettext "选择远端")" rclone_remotes_options rclone_remotes_index

        if [ -z "${rclone_remotes_path[rclone_remotes_index]:-}" ] 
        then
            Println "$(eval_gettext "\$error 请先添加挂载")\n"
            return 1
        fi

        IFS="${delimiters[5]}" read -r -a rclone_remote_paths <<< "${rclone_remotes_path[rclone_remotes_index]}"
        IFS="${delimiters[5]}" read -r -a rclone_remote_mount_paths <<< "${rclone_remotes_mount_path[rclone_remotes_index]}"
        IFS="${delimiters[5]}" read -r -a rclone_remote_mount_flags <<< "${rclone_remotes_mount_flag[rclone_remotes_index]}"

        rclone_remote_mount_count=${#rclone_remote_paths[@]}

        rclone_remote_mount_options=()
        local i rclone_remote_mount_list=""
        local i18n_remote_path i18n_mount_point i18n_mounted i18n_mount_cmd
        i18n_remote_path=$(gettext "远端路径")
        i18n_mount_point=$(gettext "挂载点")
        i18n_mounted=$(gettext "已挂载")
        i18n_mount_cmd=$(gettext "挂载命令")

        for((i=0;i<rclone_remote_mount_count;i++));
        do
            if ServiceControl is-active "${rclone_remotes_name[rclone_remotes_index]}-$((i+1))"
            then
                rclone_remote_mount_list="${rclone_remote_mount_list}${green}$((i+1)).${normal} ${i18n_remote_path}: ${rclone_remote_paths[i]}\n${i18n_mount_point}: ${rclone_remote_mount_paths[i]} ${green}(${i18n_mounted})${normal}\n${i18n_mount_cmd}: ${rclone_remote_mount_flags[i]:-$i18n_none}\n\n"
                rclone_remote_mount_options+=("${rclone_remotes_name[rclone_remotes_index]}:${rclone_remote_paths[i]} -> ${rclone_remote_mount_paths[i]} ${green}(${i18n_mounted})${normal}")
            else
                rclone_remote_mount_list="${rclone_remote_mount_list}${green}$((i+1)).${normal} ${i18n_remote_path}: ${rclone_remote_paths[i]}\n${i18n_mount_point}: ${rclone_remote_mount_paths[i]}\n${i18n_mount_cmd}: ${rclone_remote_mount_flags[i]:-$i18n_none}\n\n"
                rclone_remote_mount_options+=("${rclone_remotes_name[rclone_remotes_index]}:${rclone_remote_paths[i]} -> ${rclone_remote_mount_paths[i]}")
            fi
        done

        Println "$rclone_remote_mount_list"
    }

    RcloneMountAdd()
    {
        RcloneRemoteView

        echo
        inquirer list_input_index "$(gettext "选择远端")" rclone_remotes_options rclone_remotes_index

        Println "$(eval_gettext "\$tip 比如 /夸克")"
        ExitOnText "$(gettext "输入远端路径")" rclone_remote_path

        echo
        ExitOnText "$(gettext "输入挂载点")" rclone_remote_mount_path
        RemoveQuotes rclone_remote_mount_path

        Println "$(eval_gettext "\$tip 比如 --allow-other --allow-non-empty --vfs-cache-mode writes --vfs-cache-max-size 1G")"
        inquirer text_input "$(gettext "输入额外的挂载命令")" rclone_remote_mount_flag "$i18n_blank"

        new_mount=$(
        $JQ_FILE -n --arg path "$rclone_remote_path" --arg mount_path "$rclone_remote_mount_path" \
        --arg flag "$rclone_remote_mount_flag" \
            '{
                path: $path,
                mount_path: $mount_path,
                flags: $flag
            }'
        )

        jq_path='["rclone","remote",'"$rclone_remotes_index"',"mount"]'
        JQ add "$SERVICES_CONFIG" "[$new_mount]"

        Println "$(eval_gettext "\$info 挂载添加成功")\n"
    }

    RcloneMountEdit()
    {
        RcloneMountView

        inquirer checkbox_input_indices "$(gettext "选择修改的挂载")" rclone_remote_mount_options rclone_remote_mount_indices

        rclone_remote_mount_edit_options=( "$(gettext "远端路径")" "$(gettext "挂载点")" "$(gettext "额外的挂载命令")" )

        for rclone_remote_mount_index in "${rclone_remote_mount_indices[@]}"
        do
            echo "${rclone_remote_mount_options[rclone_remote_mount_index]}"

            echo
            inquirer list_input_index "$i18n_select_edit" rclone_remote_mount_edit_options rclone_remote_mount_edit_options_index

            if [ "$rclone_remote_mount_edit_options_index" == "0" ] 
            then
                echo
                inquirer text_input "$(gettext "输入新远端地址")" rclone_remote_path "${rclone_remote_paths[rclone_remote_mount_index]}"

                if [ "$rclone_remote_path" != "${rclone_remote_paths[rclone_remote_mount_index]}" ] 
                then
                    jq_path='["rclone","remote",'"$rclone_remotes_index"',"mount",'"$rclone_remote_mount_index"',"path"]'
                    JQ update "$SERVICES_CONFIG" "$rclone_remote_path"
                    Println "$(eval_gettext "\$info 远端路径修改成功")\n"
                fi
            elif [ "$rclone_remote_mount_edit_options_index" == "1" ] 
            then
                echo
                inquirer text_input "$(gettext "输入新挂载点")" rclone_remote_mount_path "${rclone_remote_mount_paths[rclone_remote_mount_index]}"
                RemoveQuotes rclone_remote_mount_path
                if [ "$rclone_remote_mount_path" != "${rclone_remote_mount_paths[rclone_remote_mount_index]}" ] 
                then
                    jq_path='["rclone","remote",'"$rclone_remotes_index"',"mount",'"$rclone_remote_mount_index"',"mount_path"]'
                    JQ update "$SERVICES_CONFIG" "$rclone_remote_mount_path"
                    Println "$(eval_gettext "\$info 挂载点修改成功")\n"
                fi
            else
                Println "$(eval_gettext "\$tip 比如 --allow-other --allow-non-empty --vfs-cache-mode writes --vfs-cache-max-size 1G")"
                inquirer text_input "$(gettext "输入额外的挂载命令")" rclone_remote_mount_flag "$i18n_blank"
                if [ "$rclone_remote_mount_flag" != "${rclone_remote_mount_flags[rclone_remote_mount_index]}" ] 
                then
                    jq_path='["rclone","remote",'"$rclone_remotes_index"',"mount",'"$rclone_remote_mount_index"',"flags"]'
                    JQ update "$SERVICES_CONFIG" "$rclone_remote_mount_flag"
                    Println "$(eval_gettext "\$info 挂载命令修改成功")\n"
                fi
            fi
        done

        return 0
    }

    RcloneMountDel()
    {
        RcloneMountView

        Println "$(eval_gettext "\$tip 也将停止挂载")"
        inquirer checkbox_input_indices "$(gettext "选择删除的挂载")" rclone_remote_mount_options rclone_remote_mount_indices

        local rclone_remote_mount_index_offset=0 i active_indices=()
        local i18n_pause_mount i18n_deleting_mount
        i18n_pause_mount=$(gettext "暂停挂载")
        i18n_deleting_mount=$(gettext "正在删除挂载")

        for((i=0;i<rclone_remote_mount_count;i++));
        do
            if ServiceControl is-active "rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$((i+1))"
            then
                active_indices+=("$i")
                Println "$info $i18n_pause_mount ${rclone_remote_mount_options[i]}"
                ServiceControl stop "rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$((i+1))"
            fi
        done

        for rclone_remote_mount_index in "${rclone_remote_mount_indices[@]}"
        do
            service_name="rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$((rclone_remote_mount_index+1))"
            if ServiceControl is-enabled "$service_name"
            then
                Println "$info $i18n_deleting_mount ${rclone_remote_mount_options[rclone_remote_mount_index]}"
                if ! err_msg=$(ServiceControl disable "$service_name")
                then
                    Println "$(eval_gettext "\$error 删除挂载失败, \$err_msg")\n"
                    continue
                fi
            fi

            unset rclone_remote_paths[rclone_remote_mount_index]
            unset rclone_remote_mount_paths[rclone_remote_mount_index]

            for((i=rclone_remote_mount_index+1;i<rclone_remote_mount_count;i++));
            do
                if ServiceControl is-enabled "rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$((i+1))"
                then
                    ServiceControl rename "rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$((i+1))" "rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$i"
                fi
            done

            if [ ${#active_indices[@]} -gt 0 ] 
            then
                for i in "${!active_indices[@]}"
                do
                    if [ "$rclone_remote_mount_index" -lt "${active_indices[i]}" ] 
                    then
                        active_indices[i]=$((active_indices[i]-1))
                    fi
                done
            fi

            jq_path='["rclone","remote",'"$rclone_remotes_index"',"mount",'"$((rclone_remote_mount_index-rclone_remote_mount_index_offset))"']'
            JQ delete "$SERVICES_CONFIG"
            rclone_remote_mount_index_offset=$((rclone_remote_mount_index_offset+1))
        done

        if [ ${#active_indices[@]} -gt 0 ]
        then
            rclone_remote_paths=("${rclone_remote_paths[@]}")
            rclone_remote_mount_paths=("${rclone_remote_mount_paths[@]}")
            local i18n_resume_mount
            i18n_resume_mount=$(gettext "恢复挂载")

            for i in "${active_indices[@]}"
            do
                Println "$info $i18n_resume_mount ${rclone_remotes_name[rclone_remotes_index]}:${rclone_remote_paths[i]} -> ${rclone_remote_mount_paths[i]}"
                ServiceControl start "rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$((i+1))"
            done
        fi

        Println "$(eval_gettext "\$info 挂载删除成功")\n"
    }

    RcloneMountExc()
    {
        RcloneMountView

        if [ "$dist" == "mac" ] && [ ! -f /usr/local/lib/libfuse.dylib ]
        then
            DepInstall macfuse
        fi

        inquirer checkbox_input_indices "$(gettext "选择执行的挂载")" rclone_remote_mount_options rclone_remote_mount_indices

        RcloneConfigUpdate

        for rclone_remote_mount_index in "${rclone_remote_mount_indices[@]}"
        do
            rclone_remote_path="${rclone_remote_paths[rclone_remote_mount_index]}"
            rclone_remote_mount_path="${rclone_remote_mount_paths[rclone_remote_mount_index]}"
            rclone_mount_list="${rclone_remotes_name[rclone_remotes_index]}:$rclone_remote_path -> $rclone_remote_mount_path"
            service_name="rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$((rclone_remote_mount_index+1))"

            if ServiceControl is-active "$service_name"
            then
                Println "$(eval_gettext "\$error \$rclone_mount_list 已挂载")\n"
                continue
            fi

            mkdir -p "$rclone_remote_mount_path"

            service_commands=( $(command -v rclone) mount ${rclone_remotes_name[rclone_remotes_index]}:$rclone_remote_path "$rclone_remote_mount_path" ${rclone_remote_mount_flags[rclone_remote_mount_index]})

            if ! err_msg=$(ServiceControl start "$service_name" service_commands update)
            then
                Println "$(eval_gettext "\$error 挂载 \$rclone_mount_list 失败, \$err_msg")\n"
                continue
            fi

            Println "$(eval_gettext "\$info 挂载 \$rclone_mount_list 成功")\n"
        done
    }

    RcloneMountDeExc()
    {
        RcloneMountView

        inquirer checkbox_input_indices "$(gettext "选择取消的挂载")" rclone_remote_mount_options rclone_remote_mount_indices

        for rclone_remote_mount_index in "${rclone_remote_mount_indices[@]}"
        do
            rclone_remote_path="${rclone_remote_paths[rclone_remote_mount_index]}"
            rclone_remote_mount_path="${rclone_remote_mount_paths[rclone_remote_mount_index]}"
            rclone_mount_list="${rclone_remotes_name[rclone_remotes_index]}:$rclone_remote_path -> $rclone_remote_mount_path"
            service_name="rclone.mount.${rclone_remotes_name[rclone_remotes_index]}-$((rclone_remote_mount_index+1))"

            if ! ServiceControl is-active "$service_name"
            then
                Println "$(eval_gettext "\$error \$rclone_mount_list 未挂载")\n"
                continue
            fi

            Println "$(eval_gettext "\$info 卸载 \$rclone_mount_list")"

            if ! err_msg=$(ServiceControl stop "$service_name")
            then
                Println "$(eval_gettext "\$error 卸载 \$rclone_mount_list 失败, 资源被占用? 请手动卸载")\n$err_msg\n"
                continue
            fi

            Println "$(eval_gettext "\$info 卸载 \$rclone_mount_list 成功")\n"
        done
    }
    RcloneServeView()
    {
        ServiceGet rclone serve

        if [ "$rclone_serves_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加 rclone 服务")\n"
            return 1
        fi

        rclone_serves_options=()
        local i rclone_serves_list="" i18n_service i18n_protocol i18n_listen i18n_args
        i18n_service=$(gettext "服务")
        i18n_protocol=$(gettext "协议")
        i18n_listen=$(gettext "监听")
        i18n_args=$(gettext "参数")

        for((i=0;i<rclone_serves_count;i++));
        do
            IFS="${delimiters[4]}" read -r -a rclone_serve_addrs <<< "${rclone_serves_addr[i]}"

            rclone_serves_options+=( "${rclone_serves_remote[i]} -> ${rclone_serve_addrs[*]}")
            rclone_serves_list="${rclone_serves_list}${green}$((i+1)).${normal} ${i18n_service}: ${rclone_serves_remote[i]}\n${i18n_protocol}: ${rclone_serves_protocol[i]}\n${i18n_listen}: ${rclone_serve_addrs[*]}\n${i18n_args}: ${rclone_serves_args[i]:-$i18n_none}\n\n"
        done

        Println "$rclone_serves_list"
    }

    RcloneServeAddRemoteValidator()
    {
        if [ "$1" == "$i18n_cancel" ] || [ "${1:0:1}" == "/" ] 
        then
            return 0
        fi

        return 1
    }

    RcloneServeAddAddrValidator()
    {
        if [ "${1:0:1}" == "/" ] || [ "${1:0:8}" == "unix:///" ] || [[ "$1" =~ ^[0-9.]*:[0-9]+ ]]
        then
            return 0
        fi

        return 1
    }

    RcloneServeAdd()
    {
        ServiceGet rclone serve

        rclone_serve_options=( "$(gettext "本地")" "$(gettext "远端")" )
        echo
        inquirer list_input_index "$(gettext "选择服务内容")" rclone_serve_options rclone_serve_options_index

        if [ "$rclone_serve_options_index" -eq 0 ] 
        then
            echo
            ExitOnText "$(gettext "输入本地服务路径")" rclone_serve_remote RcloneServeAddRemoteValidator
        else
            RcloneRemoteView
            echo
            inquirer list_input_index "$(gettext "选择服务的远端")" rclone_remotes_options rclone_remotes_index
            rclone_serve_remote="${rclone_remotes_name[rclone_remotes_index]}"
        fi

        rclone_serve_protocol_options=( webdav nfs )
        echo
        inquirer list_input "$(gettext "选择服务协议")" rclone_serve_protocol_options rclone_serve_protocol

        rclone_serve_addrs=()
        local i18n_input_listen_addr i18n_addr_format_err i18n_continue_add_addr
        i18n_input_listen_addr=$(gettext "输入监听地址 IP:PORT/socket/绝对路径")
        i18n_addr_format_err=$(gettext "地址格式错误")
        i18n_continue_add_addr=$(gettext "是否继续添加监听地址")

        while true
        do
            Println "$(eval_gettext "\$tip 比如 1.2.3.4:8000, :8080, :0(自动检测端口), unix:///path/to/socket. 如果使用 socket 或绝对路径, 连接验证将不可用")"
            inquirer text_input "$i18n_input_listen_addr" rclone_serve_addr :0 RcloneServeAddAddrValidator "$i18n_addr_format_err"

            rclone_serve_addrs+=("$rclone_serve_addr")

            echo
            inquirer list_input_index "$i18n_continue_add_addr" ny_options ny_index

            if [ "$ny_index" -eq 0 ] 
            then
                break
            fi
        done

        while true 
        do
            rclone_serve_htpasswd=$(RandStr)
            if [ "$rclone_serves_count" -gt 0 ] && EleInArray "$rclone_serve_htpasswd" rclone_serves_htpasswd 
            then
                continue
            fi
            break
        done

        echo
        inquirer text_input "$(gettext "输入服务参数")" rclone_serve_args "$i18n_blank"

        new_serve=$(
        $JQ_FILE -n --arg remote "$rclone_serve_remote" --arg protocol "$rclone_serve_protocol" \
        --argjson addr "$(ToJsonArray rclone_serve_addrs)" --arg htpasswd "$rclone_serve_htpasswd" \
        --arg args "$rclone_serve_args" \
            '{
                remote: $remote,
                protocol: $protocol,
                addr: $addr,
                htpasswd: $htpasswd,
                args: $args
            }'
        )

        jq_path='["rclone","serve"]'
        JQ add "$SERVICES_CONFIG" "[$new_serve]"

        Println "$(eval_gettext "\$info 服务添加成功")\n"
    }

    RcloneServeEdit()
    {
        RcloneServeView

        inquirer checkbox_input_indices "$(gettext "选择修改的服务")" rclone_serves_options rclone_serves_indices

        rclone_serve_edit_options=( "$(gettext "服务内容")" "$(gettext "服务协议")" "$(gettext "监听地址")" "$(gettext "服务参数")" )
        rclone_serve_options=( "$(gettext "本地")" "$(gettext "远端")" )
        rclone_serve_protocol_options=( webdav nfs )
        rclone_serve_addr_options=( "$i18n_edit" "$i18n_delete" )

        for rclone_serves_index in "${rclone_serves_indices[@]}"
        do
            echo "${rclone_serves_options[rclone_serves_index]}"

            echo
            inquirer checkbox_input_indices "$i18n_select_edit" rclone_serve_edit_options rclone_serve_edit_options_indices

            for rclone_serve_edit_options_index in "${rclone_serve_edit_options_indices[@]}"
            do
                case $rclone_serve_edit_options_index in
                    0) 
                        echo
                        inquirer list_input_index "$(gettext "选择服务内容")" rclone_serve_options rclone_serve_options_index

                        if [ "$rclone_serve_options_index" -eq 0 ] 
                        then
                            echo
                            ExitOnText "$(gettext "输入本地服务路径")" rclone_serve_remote RcloneServeAddRemoteValidator
                        else
                            RcloneRemoteView
                            echo
                            inquirer list_input_index "$(gettext "选择服务的远端")" rclone_remotes_options rclone_remotes_index
                            rclone_serve_remote="${rclone_remotes_name[rclone_remotes_index]}"
                        fi

                        if [ "$rclone_serve_remote" != "${rclone_serves_remote[rclone_serves_index]}" ] 
                        then
                            jq_path='["rclone","serve",'"$rclone_serves_index"',"remote"]'
                            JQ update "$SERVICES_CONFIG" "$rclone_serve_remote"
                            Println "$(eval_gettext "\$info 服务内容修改成功")\n"
                        fi
                    ;;
                    1)
                        echo
                        inquirer list_input "$(gettext "选择服务协议")" rclone_serve_protocol_options rclone_serve_protocol
                        if [ "$rclone_serve_protocol" != "${rclone_serves_protocol[rclone_serves_index]}" ] 
                        then
                            jq_path='["rclone","serve",'"$rclone_serves_index"',"protocol"]'
                            JQ update "$SERVICES_CONFIG" "$rclone_serve_protocol"
                            Println "$(eval_gettext "\$info 服务协议修改成功")\n"
                        fi
                    ;;
                    2) 
                        rclone_serve_addr="${rclone_serves_addr[i]}"
                        IFS="${delimiters[4]}" read -r -a rclone_serve_addrs <<< "$rclone_serve_addr"
                        echo
                        inquirer checkbox_input_indices "$(gettext "选择监听地址")" rclone_serve_addrs rclone_serve_addrs_indices
                        local rclone_serve_addrs_index_offset=0 i18n_input_new_listen_addr i18n_addr_format_err
                        i18n_input_new_listen_addr=$(gettext "输入新监听地址 IP:PORT/socket/绝对路径")
                        i18n_addr_format_err=$(gettext "地址格式错误")
                        for rclone_serve_addrs_index in "${rclone_serve_addrs_indices[@]}"
                        do
                            echo
                            inquirer list_input_index "$i18n_select_action ${rclone_serve_addrs[rclone_serve_addrs_index]}" rclone_serve_addr_options rclone_serve_addr_options_index
                            if [ "$rclone_serve_addr_options_index" -eq 0 ] 
                            then
                                Println "$(eval_gettext "\$tip 比如 1.2.3.4:8000, :8080, :0(自动检测端口), unix:///path/to/socket. 如果使用 socket 或绝对路径, 连接验证将不可用")"
                                inquirer text_input "$i18n_input_new_listen_addr" rclone_serve_addr ${rclone_serve_addrs[rclone_serve_addrs_index]} RcloneServeAddAddrValidator "$i18n_addr_format_err"
                                if [ "$rclone_serve_addr" != "${rclone_serve_addrs[rclone_serve_addrs_index]}" ] 
                                then
                                    jq_path='["rclone","serve",'"$rclone_serves_index"',"addr",'"$((rclone_serve_addrs_index-rclone_serve_addrs_index_offset))"']'
                                    JQ update "$SERVICES_CONFIG" "$rclone_serve_addr"
                                    Println "$(eval_gettext "\$info 监听地址修改成功")\n"
                                fi
                            else
                                jq_path='["rclone","serve",'"$rclone_serves_index"',"addr",'"$((rclone_serve_addrs_index-rclone_serve_addrs_index_offset))"']'
                                JQ delete "$SERVICES_CONFIG" "$rclone_serve_addr"
                                rclone_serve_addrs_index_offset=$((rclone_serve_addrs_index_offset+1))
                                Println "$(eval_gettext "\$info 监听地址删除成功")\n"
                            fi
                        done
                    ;;
                    3)
                        echo
                        inquirer text_input "$(gettext "输入服务参数")" rclone_serve_args "${rclone_serves_args[rclone_serves_index]:-$i18n_blank}"
                        if [ "$rclone_serve_args" == "${rclone_serves_args[rclone_serves_index]:-$i18n_blank}" ] 
                        then
                            continue
                        fi
                        jq_path='["rclone","serve",'"$rclone_serves_index"',"args"]'
                        JQ update "$SERVICES_CONFIG" "$rclone_serve_args"
                        Println "$(eval_gettext "\$info 服务参数修改成功")\n"
                    ;;
                esac
            done
        done

        return 0
    }

    RcloneServeDel()
    {
        RcloneServeView

        Println "$(eval_gettext "\$tip 也将停止服务")"
        inquirer checkbox_input_indices "$(gettext "选择删除的服务")" rclone_serves_options rclone_serves_indices

        local rclone_serves_index_offset=0 i active_indices=()
        local i18n_pause_serve i18n_deleting_serve
        i18n_pause_serve=$(gettext "暂停服务")
        i18n_deleting_serve=$(gettext "正在删除服务")

        for((i=0;i<rclone_serves_count;i++));
        do
            if ServiceControl is-active "rclone.serve-$((i+1))"
            then
                active_indices+=("$i")
                Println "$info $i18n_pause_serve ${rclone_serves_options[i]}"
                ServiceControl stop "rclone.serve-$((i+1))"
            fi
        done

        for rclone_serves_index in "${rclone_serves_indices[@]}"
        do
            service_name="rclone.serve-$((rclone_serves_index+1))"
            if ServiceControl is-enabled "$service_name"
            then
                Println "$info $i18n_deleting_serve ${rclone_serves_options[rclone_serves_index]}"
                if ! err_msg=$(ServiceControl disable "$service_name")
                then
                    Println "$(eval_gettext "\$error 删除服务失败, \$err_msg")\n"
                    continue
                fi
            fi

            unset rclone_serves_remote[rclone_serves_index]
            unset rclone_serves_addr[rclone_serves_index]

            for((i=rclone_serves_index+1;i<rclone_serves_count;i++));
            do
                if ServiceControl is-enabled "rclone.serve-$((i+1))"
                then
                    ServiceControl rename "rclone.serve-$((i+1))" "rclone.serve-$i"
                fi
            done

            if [ ${#active_indices[@]} -gt 0 ] 
            then
                for i in "${!active_indices[@]}"
                do
                    if [ "$rclone_serves_index" -lt "${active_indices[i]}" ] 
                    then
                        active_indices[i]=$((active_indices[i]-1))
                    fi
                done
            fi

            jq_path='["rclone","serve",'"$((rclone_serves_index-rclone_serves_index_offset))"']'
            JQ delete "$SERVICES_CONFIG"
            rclone_serves_index_offset=$((rclone_serves_index_offset+1))
        done

        if [ ${#active_indices[@]} -gt 0 ] 
        then
            rclone_serves_remote=("${rclone_serves_remote[@]}")
            rclone_serves_addr=("${rclone_serves_addr[@]}")
            local i18n_resume_serve
            i18n_resume_serve=$(gettext "恢复服务")

            for i in "${active_indices[@]}"
            do
                IFS="${delimiters[4]}" read -r -a rclone_serve_addrs <<< "${rclone_serves_addr[i]}"
                Println "$info $i18n_resume_serve ${rclone_serves_remote[i]} -> ${rclone_serve_addrs[*]}"
                ServiceControl start "rclone.serve-$((i+1))"
            done
        fi

        Println "$(eval_gettext "\$info 服务删除成功")\n"
    }

    RcloneServeExc()
    {
        RcloneServeView

        inquirer checkbox_input_indices "$(gettext "选择执行的服务")" rclone_serves_options rclone_serves_indices

        RcloneConfigUpdate

        for rclone_serves_index in "${rclone_serves_indices[@]}"
        do
            service_name="rclone.serve-$((rclone_serves_index+1))"
            rclone_serve_addr="${rclone_serves_addr[rclone_serves_index]}"
            IFS="${delimiters[4]}" read -r -a rclone_serve_addrs <<< "$rclone_serve_addr"
            rclone_serve_list="${rclone_serves_remote[rclone_serves_index]} -> ${rclone_serve_addrs[*]}"

            if ServiceControl is-active "$service_name"
            then
                Println "$(eval_gettext "\$error \$rclone_serve_list 已运行")\n"
                continue
            fi

            rclone_serve_accs_count=0

            if [ -n "${rclone_serves_user[rclone_serves_index]:-}" ] 
            then
                IFS="${delimiters[5]}" read -r -a rclone_serve_users <<< "${rclone_serves_user[rclone_serves_index]}"
                IFS="${delimiters[5]}" read -r -a rclone_serve_passwords <<< "${rclone_serves_pass[rclone_serves_index]}"

                rclone_serve_accs_count=${#rclone_serve_users[@]}
            fi

            service_commands=( $(command -v rclone) serve "${rclone_serves_protocol[rclone_serves_index]}" "${rclone_serves_remote[rclone_serves_index]}" )
            rclone_serve_auth=false

            for rclone_serve_addr in "${rclone_serve_addrs[@]}"
            do
                service_commands+=( --addr "$rclone_serve_addr" )

                if [ "$rclone_serve_auth" = false ] && [[ "$rclone_serve_addr" =~ ^[0-9.]*:[0-9]+ ]] 
                then
                    rclone_serve_auth=true
                fi
            done

            if [ "${rclone_serves_protocol[rclone_serves_index]}" != "nfs" ] && [ "$rclone_serve_auth" = true ] && [ "$rclone_serve_accs_count" -gt 0 ] 
            then
                if [ ! -f "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" ] 
                then
                    mkdir -p "$RCLONE_ROOT/serve/htpasswd"
                    htpasswd -Bbc "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" "${rclone_serve_users[0]}" "${rclone_serve_passwords[0]}"
                    for((i=1;i<rclone_serve_accs_count;i++));
                    do
                        htpasswd -Bb "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" "${rclone_serve_users[i]}" "${rclone_serve_passwords[i]}"
                    done
                fi
                service_commands+=( --htpasswd "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" )
            fi

            if [ -n "${rclone_serves_args[rclone_serves_index]:-}" ] 
            then
                service_commands+=( ${rclone_serves_args[rclone_serves_index]} )
            fi

            if ! err_msg=$(ServiceControl start "$service_name" service_commands update)
            then
                Println "$(eval_gettext "\$error 服务 \$rclone_serve_list 失败, \$err_msg")\n"
                continue
            fi

            Println "$(eval_gettext "\$info 服务 \$rclone_serve_list 执行成功")\n"
        done

        return 0
    }

    RcloneServeDeExc()
    {
        RcloneServeView

        inquirer checkbox_input_indices "$(gettext "选择取消的服务")" rclone_serves_options rclone_serves_indices

        for rclone_serves_index in "${rclone_serves_indices[@]}"
        do
            service_name="rclone.serve-$((rclone_serves_index+1))"
            rclone_serve_addr="${rclone_serves_addr[rclone_serves_index]}"
            IFS="${delimiters[4]}" read -r -a rclone_serve_addrs <<< "$rclone_serve_addr"
            rclone_serve_list="${rclone_serves_remote[rclone_serves_index]} -> ${rclone_serve_addrs[*]}"

            if ! ServiceControl is-active "$service_name"
            then
                Println "$(eval_gettext "\$error \$rclone_serve_list 未运行")\n"
                continue
            fi

            if ! err_msg=$(ServiceControl stop "$service_name")
            then
                Println "$(eval_gettext "\$error 取消服务 \$rclone_serve_list 失败, \$err_msg")\n"
                continue
            fi

            Println "$(eval_gettext "\$info 取消服务 \$rclone_serve_list 成功")\n"
        done

        return 0
    }

    RcloneServeAccView()
    {
        RcloneServeView

        inquirer list_input_index "$(gettext "选择服务")" rclone_serves_options rclone_serves_index

        if [ -z "${rclone_serves_user[rclone_serves_index]:-}" ] 
        then
            Println "$(eval_gettext "\$error 请先添加账号")\n"
            return 1
        fi

        IFS="${delimiters[5]}" read -r -a rclone_serve_users <<< "${rclone_serves_user[rclone_serves_index]}"
        IFS="${delimiters[5]}" read -r -a rclone_serve_passwords <<< "${rclone_serves_pass[rclone_serves_index]}"

        rclone_serve_accs_count=${#rclone_serve_users[@]}

        local i rclone_serve_accs_list="" i18n_user
        i18n_user=$(gettext "用户")
        for((i=0;i<rclone_serve_accs_count;i++));
        do
            rclone_serve_accs_list="${rclone_serve_accs_list}${green}$((i+1)).${normal} ${i18n_user}: ${rclone_serve_users[i]} ${i18n_password}: ${rclone_serve_passwords[i]}\n"
        done

        Println "$rclone_serve_accs_list\n"
    }

    RcloneServeAccAddValidator()
    {
        if [ "$1" != "$i18n_cancel" ] && [ "$rclone_serve_accs_count" -gt 0 ] && EleInArray "$1" rclone_serve_users
        then
            return 1
        fi

        return 0
    }

    RcloneServeAccAdd()
    {
        HtpasswdInstall

        RcloneServeView

        inquirer list_input_index "$(gettext "选择服务")" rclone_serves_options rclone_serves_index

        rclone_serve_accs_count=0

        if [ -n "${rclone_serves_user[rclone_serves_index]:-}" ] 
        then
            IFS="${delimiters[5]}" read -r -a rclone_serve_users <<< "${rclone_serves_user[rclone_serves_index]}"
            IFS="${delimiters[5]}" read -r -a rclone_serve_passwords <<< "${rclone_serves_pass[rclone_serves_index]}"

            rclone_serve_accs_count=${#rclone_serve_users[@]}
        fi

        echo
        ExitOnText "$(gettext "输入账号")" rclone_serve_user RcloneServeAccAddValidator "$(gettext "账号已存在")"

        echo
        ExitOnText "$i18n_input_password" rclone_serve_pass

        new_acc=$(
        $JQ_FILE -n --arg user "$rclone_serve_user" --arg pass "$rclone_serve_pass" \
            '{
                user: $user,
                pass: $pass
            }'
        )

        jq_path='["rclone","serve",'"$rclone_serves_index"',"accs"]'
        JQ add "$SERVICES_CONFIG" "[$new_acc]"

        if [ ! -f "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" ] 
        then
            mkdir -p "$RCLONE_ROOT/serve/htpasswd"
            htpasswd -Bbc "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" "$rclone_serve_user" "$rclone_serve_pass"
        else
            htpasswd -Bb "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" "$rclone_serve_user" "$rclone_serve_pass"
        fi

        Println "$(eval_gettext "\$info 账号添加成功")\n"
    }

    RcloneServeAccEditValidator()
    {
        if [ "$rclone_serve_user" == "${rclone_serve_users[rclone_serve_users_index]}" ] 
        then
            return 0
        fi

        if EleInArray "$1" rclone_serve_users
        then
            return 1
        fi

        return 0
    }

    RcloneServeAccEdit()
    {
        RcloneServeAccView

        rclone_serve_acc_edit_options=( "$(gettext "修改账号")" "$(gettext "修改密码")" )

        echo
        inquirer checkbox_input_indices "$(gettext "选择账号")" rclone_serve_users rclone_serve_accs_indices

        for rclone_serve_accs_index in "${rclone_serve_accs_indices[@]}"
        do
            echo
            inquirer checkbox_input_indices "$i18n_select_action ${rclone_serve_users[rclone_serve_accs_index]}" rclone_serve_acc_edit_options rclone_serve_acc_edit_options_indices
            for rclone_serve_acc_edit_options_index in "${rclone_serve_acc_edit_options_indices[@]}"
            do
                if [ "$rclone_serve_acc_edit_options_index" -eq 0 ] 
                then
                    echo
                    inquirer text_input "$(gettext "输入新账号")" rclone_serve_user "${rclone_serve_users[rclone_serve_accs_index]}" RcloneServeAccEditValidator "$(gettext "账号已存在")"
                    if [ "$rclone_serve_user" != "${rclone_serve_users[rclone_serve_accs_index]}" ] 
                    then
                        jq_path='["rclone","serve",'"$rclone_serves_index"',"accs",'"$rclone_serve_accs_index"',"user"]'
                        JQ update "$SERVICES_CONFIG" "$rclone_serve_user"
                        htpasswd -D "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" "${rclone_serve_users[rclone_serve_accs_index]}"
                        htpasswd -Bb "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" "$rclone_serve_user" "${rclone_serve_passwords[rclone_serve_accs_index]}"
                        Println "$(eval_gettext "\$info 账号修改成功")\n"
                    fi
                else
                    echo
                    inquirer text_input "$(gettext "输入新密码")" rclone_serve_pass "${rclone_serve_passwords[rclone_serve_accs_index]}"
                    if [ "$rclone_serve_pass" != "${rclone_serve_passwords[rclone_serve_accs_index]}" ] 
                    then
                        jq_path='["rclone","serve",'"$rclone_serves_index"',"accs",'"$rclone_serve_accs_index"',"pass"]'
                        JQ update "$SERVICES_CONFIG" "$rclone_serve_pass"
                        htpasswd -Bb "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" "${rclone_serve_users[rclone_serve_accs_index]}" "$rclone_serve_pass"
                        Println "$(eval_gettext "\$info 密码修改成功")\n"
                    fi
                fi
            done
        done

        return 0
    }

    RcloneServeAccDel()
    {
        RcloneServeAccView

        echo
        inquirer checkbox_input_indices "$(gettext "选择账号")" rclone_serve_users rclone_serve_accs_indices

        local rclone_serve_accs_index_offset=0

        for rclone_serve_accs_index in "${rclone_serve_accs_indices[@]}"
        do
            jq_path='["rclone","serve",'"$rclone_serves_index"',"accs",'"$((rclone_serve_accs_index-rclone_serve_accs_index_offset))"']'
            JQ delete "$SERVICES_CONFIG"
            htpasswd -D "$RCLONE_ROOT/serve/htpasswd/${rclone_serves_htpasswd[rclone_serves_index]}" "${rclone_serve_users[rclone_serve_accs_index]}"
            rclone_serve_accs_index_offset=$((rclone_serve_accs_index_offset+1))
        done

        Println "$(eval_gettext "\$info 账号删除成功")\n"
    }
    RcloneSyncView()
    {
        ServiceGet rclone sync

        if [ "$rclone_syncs_count" -eq 0 ] 
        then
            Println "$(eval_gettext "\$error 请先添加同步")\n"
            return 1
        fi

        local rclone_syncs_list="" i rclone_sync_include_list rclone_sync_exclude_before_list rclone_sync_exclude_after_list
        local i18n_exclude_before i18n_include i18n_exclude_after i18n_sync_source i18n_sync_target i18n_sync_args i18n_src i18n_dst
        i18n_exclude_before=$(gettext "前排除")
        i18n_include=$(gettext "包含")
        i18n_exclude_after=$(gettext "后排除")
        i18n_sync_source=$(gettext "同步源")
        i18n_sync_target=$(gettext "同步目标")
        i18n_sync_args=$(gettext "同步参数")
        i18n_src=$(gettext "源")
        i18n_dst=$(gettext "目标")
        rclone_syncs_options=()

        for((i=0;i<rclone_syncs_count;i++));
        do
            rclone_syncs_list="${rclone_syncs_list}${green}$((i+1)).${normal} rsync: "
            if [ "${rclone_syncs_rsync[i]}" = true ] 
            then
                rclone_syncs_list="${rclone_syncs_list}${green}${i18n_yes}${normal}\n"
            else
                rclone_syncs_list="${rclone_syncs_list}${red}${i18n_no}${normal}\n"
            fi
            if [[ -z "${rclone_syncs_exclude_before[i]:-}" ]] 
            then
                rclone_sync_exclude_before_list="${i18n_exclude_before}: ${i18n_not_set}\n"
            else
                IFS="${delimiters[4]}" read -r -a rclone_sync_excludes_before <<< "${rclone_syncs_exclude_before[i]}"
                rclone_sync_exclude_before_list="${i18n_exclude_before}:\n$(printf '%s\n' "${rclone_sync_excludes_before[@]}")\n"
            fi
            if [[ -z "${rclone_syncs_include[i]:-}" ]] 
            then
                rclone_sync_include_list="${i18n_include}: ${i18n_not_set}\n"
            else
                IFS="${delimiters[4]}" read -r -a rclone_sync_includes <<< "${rclone_syncs_include[i]}"
                rclone_sync_include_list="${i18n_include}:\n$(printf '%s\n' "${rclone_sync_includes[@]}")"
            fi
            if [[ -z "${rclone_syncs_exclude_after[i]:-}" ]] 
            then
                rclone_sync_exclude_after_list="${i18n_exclude_after}: ${i18n_not_set}\n"
            else
                IFS="${delimiters[4]}" read -r -a rclone_sync_excludes_after <<< "${rclone_syncs_exclude_after[i]}"
                rclone_sync_exclude_after_list="${i18n_exclude_after}:\n$(printf '%s\n' "${rclone_sync_excludes_after[@]}")\n"
            fi
            rclone_syncs_list="${rclone_syncs_list}${i18n_sync_source}: ${rclone_syncs_source[i]}\n${i18n_sync_target}: ${rclone_syncs_target[i]}\n${i18n_sync_args}: ${rclone_syncs_args[i]:-$i18n_none}\n${rclone_sync_exclude_before_list}${rclone_sync_include_list}${rclone_sync_exclude_after_list}\n"
            rclone_syncs_options+=("${i18n_src}: ${rclone_syncs_source[i]} ${i18n_dst}: ${rclone_syncs_target[i]} rsync: ${rclone_syncs_rsync[i]}")
        done

        Println "$rclone_syncs_list"
    }

    RcloneSyncLocalValidator()
    {
        if [[ "$1" == "$i18n_cancel" ]] || [[ "$1" =~ ^[\'\"]?/.*[\'\"]?$ ]]
        then
            return 0
        fi

        return 1
    }

    RcloneSyncRsyncRemoteValidator()
    {
        if [[ "$1" == "$i18n_cancel" ]] || [[ "$1" =~ ^[a-zA-Z0-9]+:.*$ ]] 
        then
            return 0
        fi

        return 1
    }

    RcloneSyncAdd()
    {
        Println "$(eval_gettext "\$tip 如果选否将使用 rsync 同步")"
        inquirer list_input_index "$(gettext "是否使用远端")" ny_options ny_index

        rclone_sync_target_options=( "$(gettext "输入本地目录")" )
        rclone_sync_excludes_before=()
        rclone_sync_includes=()
        rclone_sync_excludes_after=()

        if [ "$ny_index" -eq 0 ] 
        then
            rclone_sync_rsync=true
            rclone_sync_rsync_options=( "$(gettext "输入本地同步源")" "$(gettext "输入远程同步源")" )

            if rclone_sync_rsync_hosts=($(grep "^Host " ~/.ssh/config | grep -v "Host \*" | awk '{print $2}'))
            then
                rclone_sync_rsync_options+=("${rclone_sync_rsync_hosts[@]}")
                rclone_sync_target_options+=("${rclone_sync_rsync_hosts[@]}")
            fi

            echo
            inquirer list_input_index "$(gettext "选择同步源")" rclone_sync_rsync_options rclone_sync_rsync_options_index 20

            case $rclone_sync_rsync_options_index in
                0) 
                    echo
                    ExitOnText "$(gettext "输入本地路径")" rclone_sync_source RcloneSyncLocalValidator "$(gettext "路径错误")"
                    RemoveQuotes rclone_sync_source
                ;;
                1) 
                    echo
                    ExitOnText "$(gettext "输入远程同步源")" rclone_sync_source RcloneSyncRsyncRemoteValidator "$(gettext "远程格式错误")"
                ;;
                *) 
                    rclone_sync_rsync_host="${rclone_sync_rsync_hosts[rclone_sync_rsync_options_index-2]}"
                    echo
                    ExitOnText "$(eval_gettext "输入远程同步源 \$rclone_sync_rsync_host 的路径")" rclone_sync_rsync_host_path
                    rclone_sync_source="$rclone_sync_rsync_host:$rclone_sync_rsync_host_path"
                ;;
            esac
        else
            rclone_sync_rsync=false

            RcloneRemoteView

            echo
            inquirer list_input_index "$(gettext "选择同步源")" rclone_remotes_options rclone_remotes_index 20

            rclone_sync_remote_name="${rclone_remotes_name[rclone_remotes_index]}"
            echo
            ExitOnText "$(eval_gettext "输入远端 \$rclone_sync_remote_name 的路径")" rclone_sync_remote_path
            rclone_sync_source="$rclone_sync_remote_name:$rclone_sync_remote_path"

            rclone_sync_target_options+=("${rclone_remotes_name[@]}")
        fi

        RcloneSyncSetExcludeBefore
        RcloneSyncSetInclude
        RcloneSyncSetExcludeAfter

        echo
        inquirer list_input_index "$(gettext "选择同步目标")" rclone_sync_target_options rclone_sync_target_options_index 20

        if [ "$rclone_sync_target_options_index" -eq 0 ] 
        then
            echo
            ExitOnText "$(gettext "输入同步的本地目录")" rclone_sync_target RcloneSyncLocalValidator "$(gettext "路径错误")"
            RemoveQuotes rclone_sync_target
        else
            rclone_sync_target="${rclone_sync_target_options[rclone_sync_target_options_index]}"
            echo
            ExitOnText "$(eval_gettext "输入同步目标 \$rclone_sync_target 的路径")" rclone_sync_target_path
            rclone_sync_target="$rclone_sync_target:$rclone_sync_target_path"
        fi

        echo
        inquirer text_input "$(gettext "输入同步参数")" rclone_sync_args "$i18n_blank"

        rclone_sync=$(
            $JQ_FILE -c -n --arg rsync "$rclone_sync_rsync" --arg source "$rclone_sync_source" --arg target "$rclone_sync_target" \
            --arg args "$rclone_sync_args" --argjson exclude_before "$(ToJsonArray rclone_sync_excludes_before)" --argjson include "$(ToJsonArray rclone_sync_includes)" --argjson exclude_after "$(ToJsonArray rclone_sync_excludes_after)" \
            '{
                rsync: $rsync | test("true"),
                source: $source,
                target: $target,
                args: $args,
                exclude_before: $exclude_before,
                include: $include,
                exclude_after: $exclude_after
            }'
        )

        jq_path='["rclone","sync"]'
        JQ add "$SERVICES_CONFIG" "[$rclone_sync]"

        Println "$(eval_gettext "\$info 同步添加成功")\n"
    }

    RcloneSyncSetExcludeBefore()
    {
        local i18n_input_exclude
        i18n_input_exclude=$(gettext "输入排除的文件或目录")
        rclone_sync_excludes_before=()
        while true 
        do
            if [ "$rclone_sync_rsync" = true ] 
            then
                Println "$(eval_gettext "\$tip 用于参数 --exclude, 置于所有 --include 之前, 每次输入一项")"
            else
                Println "$(eval_gettext "\$tip 用于参数 --filter - , 置于所有 --filter + 之前, 每次输入一项")"
            fi
            inquirer text_input "$i18n_input_exclude" rclone_sync_exclude_before "$i18n_skip"
            RemoveQuotes rclone_sync_exclude_before
            if [ "$rclone_sync_exclude_before" == "$i18n_skip" ] 
            then
                break
            fi
            rclone_sync_excludes_before+=("$rclone_sync_exclude_before")
        done
        return 0
    }

    RcloneSyncSetInclude()
    {
        local i18n_input_include
        i18n_input_include=$(gettext "输入包含的文件或目录")
        rclone_sync_includes=()
        while true 
        do
            if [ "$rclone_sync_rsync" = true ] 
            then
                Println "$(eval_gettext "\$tip 用于参数 --include, 每次输入一项, 如果设置将排除其他所有文件")"
            else
                Println "$(eval_gettext "\$tip 用于参数 --filter + , 每次输入一项")"
            fi
            inquirer text_input "$i18n_input_include" rclone_sync_include "$i18n_skip"
            RemoveQuotes rclone_sync_include
            if [ "$rclone_sync_include" == "$i18n_skip" ] 
            then
                break
            fi
            rclone_sync_includes+=("$rclone_sync_include")
        done
        return 0
    }

    RcloneSyncSetExcludeAfter()
    {
        local i18n_input_exclude
        i18n_input_exclude=$(gettext "输入排除的文件或目录")
        rclone_sync_excludes_after=()
        while true 
        do
            if [ "$rclone_sync_rsync" = true ] 
            then
                Println "$(eval_gettext "\$tip 用于参数 --exclude, 置于所有 --include 之后, 每次输入一项")"
            else
                Println "$(eval_gettext "\$tip 用于参数 --filter - , 置于所有 --filter + 之后, 每次输入一项")"
            fi
            inquirer text_input "$i18n_input_exclude" rclone_sync_exclude_after "$i18n_skip"
            RemoveQuotes rclone_sync_exclude_after
            if [ "$rclone_sync_exclude_after" == "$i18n_skip" ] 
            then
                break
            fi
            rclone_sync_excludes_after+=("$rclone_sync_exclude_after")
        done
        return 0
    }

    RcloneSyncEdit()
    {
        RcloneSyncView

        inquirer list_input_index "$(gettext "选择同步")" rclone_syncs_options rclone_syncs_index 20

        rclone_sync_rsync=${rclone_syncs_rsync[rclone_syncs_index]}

        rclone_sync_edit_options=( "$(gettext "源")" "$(gettext "目标")" "$(gettext "参数")" "$(gettext "前排除")" "$(gettext "包含")" "$(gettext "后排除")" )

        echo
        inquirer list_input_index "$i18n_select_edit" rclone_sync_edit_options rclone_sync_edit_options_index

        case $rclone_sync_edit_options_index in
            0) 
                Println "$(eval_gettext "\$tip 如果选否将使用 rsync 同步")"
                inquirer list_input_index "$(gettext "是否使用远端")" ny_options ny_index

                if [ "$ny_index" -eq 0 ] 
                then
                    rclone_sync_rsync=true
                    rclone_sync_rsync_options=( "$(gettext "输入本地同步源")" "$(gettext "输入远程同步源")" )

                    if rclone_sync_rsync_hosts=($(grep "^Host " ~/.ssh/config | grep -v "Host \*" | awk '{print $2}'))
                    then
                        rclone_sync_rsync_options+=("${rclone_sync_rsync_hosts[@]}")
                    fi

                    echo
                    inquirer list_input_index "$(gettext "选择同步源")" rclone_sync_rsync_options rclone_sync_rsync_options_index 20

                    case $rclone_sync_rsync_options_index in
                        0) 
                            echo
                            ExitOnText "$(gettext "输入本地路径")" rclone_sync_source RcloneSyncLocalValidator "$(gettext "路径错误")"
                            RemoveQuotes rclone_sync_source
                        ;;
                        1) 
                            echo
                            ExitOnText "$(gettext "输入远程同步源")" rclone_sync_source RcloneSyncRsyncRemoteValidator "$(gettext "远程格式错误")"
                        ;;
                        *) 
                            rclone_sync_rsync_host="${rclone_sync_rsync_hosts[rclone_sync_rsync_options_index-2]}"
                            echo
                            ExitOnText "$(eval_gettext "输入远程同步源 \$rclone_sync_rsync_host 的路径")" rclone_sync_rsync_host_path
                            rclone_sync_source="$rclone_sync_rsync_host:$rclone_sync_rsync_host_path"
                        ;;
                    esac
                else
                    rclone_sync_rsync=false

                    RcloneRemoteView

                    echo
                    inquirer list_input_index "$(gettext "选择同步源")" rclone_remotes_options rclone_remotes_index 20

                    rclone_sync_remote_name="${rclone_remotes_name[rclone_remotes_index]}"
                    echo
                    ExitOnText "$(eval_gettext "输入远端 \$rclone_sync_remote_name 的路径")" rclone_sync_remote_path
                    rclone_sync_source="$rclone_sync_remote_name:$rclone_sync_remote_path"
                fi

                if [ "$rclone_sync_source" != "${rclone_syncs_source[rclone_syncs_index]}" ] 
                then
                    jq_path='["rclone","sync",'"$rclone_syncs_index"',"source"]'
                    JQ update "$SERVICES_CONFIG" "$rclone_sync_source"
                fi

                if [ "$rclone_sync_rsync" != "${rclone_syncs_rsync[rclone_syncs_index]}" ] 
                then
                    jq_bool=true
                    jq_path='["rclone","sync",'"$rclone_syncs_index"',"rsync"]'
                    JQ update "$SERVICES_CONFIG" "$rclone_sync_rsync"
                fi

                Println "$(eval_gettext "\$info 同步源修改成功")\n"
            ;;
            1) 
                rclone_sync_target_options=( "$(gettext "输入本地目录")" )

                if [ "${rclone_syncs_rsync[rclone_syncs_index]}" = true ] 
                then
                    if rclone_sync_rsync_hosts=($(grep "^Host " ~/.ssh/config | grep -v "Host \*" | awk '{print $2}'))
                    then
                        rclone_sync_target_options+=("${rclone_sync_rsync_hosts[@]}")
                    fi
                else
                    RcloneRemoteView
                    rclone_sync_target_options+=("${rclone_remotes_name[@]}")
                fi

                echo
                inquirer list_input_index "$(gettext "选择同步目标")" rclone_sync_target_options rclone_sync_target_options_index 20

                if [ "$rclone_sync_target_options_index" -eq 0 ] 
                then
                    echo
                    ExitOnText "$(gettext "输入同步的本地目录")" rclone_sync_target RcloneSyncLocalValidator "$(gettext "路径错误")"
                    RemoveQuotes rclone_sync_target
                else
                    rclone_sync_target="${rclone_sync_target_options[rclone_sync_target_options_index]}"
                    echo
                    ExitOnText "$(eval_gettext "输入同步目标 \$rclone_sync_target 的路径")" rclone_sync_target_path
                    rclone_sync_target="$rclone_sync_target:$rclone_sync_target_path"
                fi

                if [ "$rclone_sync_target" != "${rclone_syncs_target[rclone_syncs_index]}" ] 
                then
                    jq_path='["rclone","sync",'"$rclone_syncs_index"',"target"]'
                    JQ update "$SERVICES_CONFIG" "$rclone_sync_target"
                    Println "$(eval_gettext "\$info 同步目标修改成功")\n"
                fi
            ;;
            2) 
                echo
                inquirer text_input "$(gettext "输入同步参数")" rclone_sync_args "$i18n_blank"

                if [ "$rclone_sync_args" != "${rclone_syncs_args[rclone_syncs_index]}" ] 
                then
                    jq_path='["rclone","sync",'"$rclone_syncs_index"',"args"]'
                    JQ update "$SERVICES_CONFIG" "$rclone_sync_args"
                    Println "$(eval_gettext "\$info 同步参数修改成功")\n"
                fi
            ;;
            3)
                if [ -z "${rclone_syncs_exclude_before[rclone_syncs_index]:-}" ] 
                then
                    RcloneSyncSetExcludeBefore
                else
                    IFS="${delimiters[4]}" read -r -a rclone_sync_excludes_before <<< "${rclone_syncs_exclude_before[rclone_syncs_index]}"
                    rclone_sync_exclude_options=( "$i18n_add" "$i18n_edit" "$i18n_delete" )
                    echo
                    inquirer list_input_index "$i18n_select_action" rclone_sync_exclude_options rclone_sync_exclude_options_index

                    if [ "$rclone_sync_exclude_options_index" -eq 0 ] 
                    then
                        RcloneSyncSetExcludeBefore
                    else
                        echo
                        inquirer checkbox_input_indices "$(gettext "选择排除的文件或目录")" rclone_sync_excludes_before rclone_sync_excludes_before_indices

                        if [ "$rclone_sync_exclude_options_index" -eq 1 ] 
                        then
                            local i18n_input_new_item
                            i18n_input_new_item=$(gettext "输入新的文件或目录")
                            for rclone_sync_excludes_before_index in "${rclone_sync_excludes_before_indices[@]}"
                            do
                                Println "$info $i18n_edit ${rclone_sync_excludes_before[rclone_sync_excludes_before_index]}"
                                inquirer text_input "$i18n_input_new_item" rclone_sync_exclude_before "$i18n_skip"
                                RemoveQuotes rclone_sync_exclude_before
                                if [ "$rclone_sync_exclude_before" == "$i18n_skip" ] || [ "$rclone_sync_exclude_before" == "${rclone_sync_excludes_before[rclone_sync_excludes_before_index]}" ]
                                then
                                    continue
                                fi
                                jq_path='["rclone","sync",'"$rclone_syncs_index"',"exclude_before",'"$rclone_sync_excludes_before_index"']'
                                JQ update "$SERVICES_CONFIG" "$rclone_sync_exclude_before"
                            done
                            Println "$(eval_gettext "\$info 前排除修改成功")\n"
                        else
                            for rclone_sync_excludes_before_index in "${rclone_sync_excludes_before_indices[@]}"
                            do
                                jq_path='["rclone","sync",'"$rclone_syncs_index"',"exclude_before",'"$rclone_sync_excludes_before_index"']'
                                JQ delete "$SERVICES_CONFIG"
                            done
                            Println "$(eval_gettext "\$info 前排除删除成功")\n"
                        fi
                        return 0
                    fi
                fi

                jq_path='["rclone","sync",'"$rclone_syncs_index"',"exclude_before"]'
                JQ add "$SERVICES_CONFIG" "$(ToJsonArray rclone_sync_excludes_before)"
                Println "$(eval_gettext "\$info 前排除添加成功")\n"
            ;;
            4)
                if [ -z "${rclone_syncs_include[rclone_syncs_index]:-}" ] 
                then
                    RcloneSyncSetInclude
                else
                    IFS="${delimiters[4]}" read -r -a rclone_sync_includes <<< "${rclone_syncs_include[rclone_syncs_index]}"
                    rclone_sync_include_options=( "$i18n_add" "$i18n_edit" "$i18n_delete" )
                    echo
                    inquirer list_input_index "$i18n_select_action" rclone_sync_include_options rclone_sync_include_options_index

                    if [ "$rclone_sync_include_options_index" -eq 0 ] 
                    then
                        RcloneSyncSetInclude
                    else
                        echo
                        inquirer checkbox_input_indices "$(gettext "选择包含的文件或目录")" rclone_sync_includes rclone_sync_includes_indices

                        if [ "$rclone_sync_include_options_index" -eq 1 ] 
                        then
                            local i18n_input_new_item
                            i18n_input_new_item=$(gettext "输入新的文件或目录")
                            for rclone_sync_includes_index in "${rclone_sync_includes_indices[@]}"
                            do
                                Println "$info $i18n_edit ${rclone_sync_includes[rclone_sync_includes_index]}"
                                inquirer text_input "$i18n_input_new_item" rclone_sync_include "$i18n_skip"
                                RemoveQuotes rclone_sync_include
                                if [ "$rclone_sync_include" == "$i18n_skip" ] || [ "$rclone_sync_include" == "${rclone_sync_includes[rclone_sync_includes_index]}" ]
                                then
                                    continue
                                fi
                                jq_path='["rclone","sync",'"$rclone_syncs_index"',"include",'"$rclone_sync_includes_index"']'
                                JQ update "$SERVICES_CONFIG" "$rclone_sync_include"
                            done
                            Println "$(eval_gettext "\$info 包含修改成功")\n"
                        else
                            for rclone_sync_includes_index in "${rclone_sync_includes_indices[@]}"
                            do
                                jq_path='["rclone","sync",'"$rclone_syncs_index"',"include",'"$rclone_sync_includes_index"']'
                                JQ delete "$SERVICES_CONFIG"
                            done
                            Println "$(eval_gettext "\$info 包含删除成功")\n"
                        fi
                        return 0
                    fi
                fi

                jq_path='["rclone","sync",'"$rclone_syncs_index"',"include"]'
                JQ add "$SERVICES_CONFIG" "$(ToJsonArray rclone_sync_includes)"
                Println "$(eval_gettext "\$info 包含添加成功")\n"
            ;;
            5)
                if [ -z "${rclone_syncs_exclude_after[rclone_syncs_index]:-}" ] 
                then
                    RcloneSyncSetExcludeAfter
                else
                    IFS="${delimiters[4]}" read -r -a rclone_sync_excludes_after <<< "${rclone_syncs_exclude_after[rclone_syncs_index]}"
                    rclone_sync_exclude_options=( "$i18n_add" "$i18n_edit" "$i18n_delete" )
                    echo
                    inquirer list_input_index "$i18n_select_action" rclone_sync_exclude_options rclone_sync_exclude_options_index

                    if [ "$rclone_sync_exclude_options_index" -eq 0 ] 
                    then
                        RcloneSyncSetExcludeAfter
                    else
                        echo
                        inquirer checkbox_input_indices "$(gettext "选择排除的文件或目录")" rclone_sync_excludes_after rclone_sync_excludes_after_indices

                        if [ "$rclone_sync_exclude_options_index" -eq 1 ] 
                        then
                            local i18n_input_new_item
                            i18n_input_new_item=$(gettext "输入新的文件或目录")
                            for rclone_sync_excludes_after_index in "${rclone_sync_excludes_after_indices[@]}"
                            do
                                Println "$info $i18n_edit ${rclone_sync_excludes_after[rclone_sync_excludes_after_index]}"
                                inquirer text_input "$i18n_input_new_item" rclone_sync_exclude_after "$i18n_skip"
                                RemoveQuotes rclone_sync_exclude_after
                                if [ "$rclone_sync_exclude_after" == "$i18n_skip" ] || [ "$rclone_sync_exclude_after" == "${rclone_sync_excludes_after[rclone_sync_excludes_after_index]}" ]
                                then
                                    continue
                                fi
                                jq_path='["rclone","sync",'"$rclone_syncs_index"',"exclude_after",'"$rclone_sync_excludes_after_index"']'
                                JQ update "$SERVICES_CONFIG" "$rclone_sync_exclude_after"
                            done
                            Println "$(eval_gettext "\$info 后排除修改成功")\n"
                        else
                            for rclone_sync_excludes_after_index in "${rclone_sync_excludes_after_indices[@]}"
                            do
                                jq_path='["rclone","sync",'"$rclone_syncs_index"',"exclude_after",'"$rclone_sync_excludes_after_index"']'
                                JQ delete "$SERVICES_CONFIG"
                            done
                            Println "$(eval_gettext "\$info 后排除删除成功")\n"
                        fi
                        return 0
                    fi
                fi

                jq_path='["rclone","sync",'"$rclone_syncs_index"',"exclude_after"]'
                JQ add "$SERVICES_CONFIG" "$(ToJsonArray rclone_sync_excludes_after)"
                Println "$(eval_gettext "\$info 后排除添加成功")\n"
            ;;
        esac

        return 0
    }

    RcloneSyncDel()
    {
        RcloneSyncView

        inquirer checkbox_input_index "$(gettext "选择同步")" rclone_syncs_options rclone_syncs_indices 20

        for rclone_syncs_index in "${rclone_syncs_indices[@]}"
        do
            jq_path='["rclone","sync",'"$rclone_syncs_index"']'
            JQ delete "$SERVICES_CONFIG"
        done

        Println "$(eval_gettext "\$info 同步删除成功")\n"
    }

    RcloneSyncExc()
    {
        RcloneSyncView

        inquirer checkbox_input_indices "$(gettext "选择同步")" rclone_syncs_options rclone_syncs_indices 20

        DepInstall rsync

        for rclone_syncs_index in "${rclone_syncs_indices[@]}"
        do
            rclone_sync_args="${rclone_syncs_args[rclone_syncs_index]:-}"
            rclone_sync_source="${rclone_syncs_source[rclone_syncs_index]}"
            if [ "${rclone_syncs_rsync[rclone_syncs_index]}" = true ]
            then
                rsync_commands=()
                if [ -n "${rclone_syncs_exclude_before[rclone_syncs_index]:-}" ] 
                then
                    IFS="${delimiters[4]}" read -r -a rclone_sync_excludes_before <<< "${rclone_syncs_exclude_before[rclone_syncs_index]}"
                    for rclone_sync_exclude_before in "${rclone_sync_excludes_before[@]}"
                    do
                        rsync_commands+=("--exclude=${rclone_sync_exclude_before#"$rclone_sync_source"}")
                    done
                fi
                if [ -n "${rclone_syncs_include[rclone_syncs_index]:-}" ] 
                then
                    IFS="${delimiters[4]}" read -r -a rclone_sync_includes <<< "${rclone_syncs_include[rclone_syncs_index]}"
                    for rclone_sync_include in "${rclone_sync_includes[@]}"
                    do
                        rsync_commands+=("--include=${rclone_sync_include#"$rclone_sync_source"}")
                    done
                fi
                if [ -n "${rclone_syncs_exclude_after[rclone_syncs_index]:-}" ] 
                then
                    IFS="${delimiters[4]}" read -r -a rclone_sync_excludes_after <<< "${rclone_syncs_exclude_after[rclone_syncs_index]}"
                    for rclone_sync_exclude_after in "${rclone_sync_excludes_after[@]}"
                    do
                        rsync_commands+=("--exclude=${rclone_sync_exclude_after#"$rclone_sync_source"}")
                    done
                fi
                rsync -avhP --safe-links --delete --delete-excluded $rclone_sync_args ${rsync_commands[@]+"${rsync_commands[@]}"} "$rclone_sync_source"/ "${rclone_syncs_target[rclone_syncs_index]}/"
            else
                sync_commands=()
                if [ -n "${rclone_syncs_exclude_before[rclone_syncs_index]:-}" ] 
                then
                    IFS="${delimiters[4]}" read -r -a rclone_sync_excludes_before <<< "${rclone_syncs_exclude_before[rclone_syncs_index]}"
                    for rclone_sync_exclude_before in "${rclone_sync_excludes_before[@]}"
                    do
                        sync_commands+=("--filter='- ${rclone_sync_exclude_before#"$rclone_sync_source"}'")
                    done
                fi
                if [ -n "${rclone_syncs_include[rclone_syncs_index]:-}" ] 
                then
                    IFS="${delimiters[4]}" read -r -a rclone_sync_includes <<< "${rclone_syncs_include[rclone_syncs_index]}"
                    for rclone_sync_include in "${rclone_sync_includes[@]}"
                    do
                        sync_commands+=("--filter='+ ${rclone_sync_include#"$rclone_sync_source"}'")
                    done
                fi
                if [ -n "${rclone_syncs_exclude_after[rclone_syncs_index]:-}" ] 
                then
                    IFS="${delimiters[4]}" read -r -a rclone_sync_excludes_after <<< "${rclone_syncs_exclude_after[rclone_syncs_index]}"
                    for rclone_sync_exclude_after in "${rclone_sync_excludes_after[@]}"
                    do
                        sync_commands+=("--filter='- ${rclone_sync_exclude_after#"$rclone_sync_source"}'")
                    done
                fi
                rclone sync "$rclone_sync_source" "${rclone_syncs_target[rclone_syncs_index]}" --delete-excluded $rclone_sync_args ${rsync_commands[@]+"${rsync_commands[@]}"}
            fi
        done

        return 0
    }
    HtpasswdInstall()
    {
        if [[ -x $(command -v htpasswd) ]] 
        then
            return 0
        fi

        if [ "$dist" == "mac" ] 
        then
            DepInstall httpd
        elif [ "$dist" == "rpm" ] 
        then
            DepInstall httpd-tools
        else
            DepInstall apache2-utils
        fi
    }

    if [ "${rc_menu_locale:-}" != "${sh_locale:-zh_CN}" ]
    then
        rclone_options=( "$(gettext "远端")" "$(gettext "挂载")" "$(gettext "服务")" "$(gettext "服务账号")" "$(gettext "同步")" "$(gettext "安装/更新")" )
        rc_menu_locale="${sh_locale:-zh_CN}"
    fi

    echo
    inquirer list_input_index "$i18n_please_select" rclone_options rclone_options_index

    case $rclone_options_index in
        0) 
            echo
            rclone_remote_options=( "$i18n_view" "$i18n_add" "$i18n_edit" "$i18n_delete" )
            inquirer list_input_index "$i18n_select_action" rclone_remote_options rclone_remote_options_index

            case $rclone_remote_options_index in
                0) RcloneRemoteView
                ;;
                1) RcloneRemoteAdd
                ;;
                2) RcloneRemoteEdit
                ;;
                3) RcloneRemoteDel
                ;;
            esac
        ;;
        1) 
            if [ "${rc_mount_menu_locale:-}" != "${sh_locale:-zh_CN}" ]
            then
                rclone_mount_options=( "$i18n_view" "$i18n_add" "$i18n_edit" "$i18n_delete" "$(gettext "执行挂载")" "$(gettext "取消挂载")" )
                rc_mount_menu_locale="${sh_locale:-zh_CN}"
            fi

            echo
            inquirer list_input_index "$i18n_select_action" rclone_mount_options rclone_mount_options_index

            case $rclone_mount_options_index in
                0) RcloneMountView
                ;;
                1) RcloneMountAdd
                ;;
                2) RcloneMountEdit
                ;;
                3) RcloneMountDel
                ;;
                4) RcloneMountExc
                ;;
                5) RcloneMountDeExc
                ;;
            esac
        ;;
        2) 
            if [ "${rc_serve_menu_locale:-}" != "${sh_locale:-zh_CN}" ]
            then
                rclone_serve_options=( "$i18n_view" "$i18n_add" "$i18n_edit" "$i18n_delete" "$(gettext "执行服务")" "$(gettext "取消服务")" )
                rc_serve_menu_locale="${sh_locale:-zh_CN}"
            fi

            echo
            inquirer list_input_index "$i18n_select_action" rclone_serve_options rclone_serve_options_index

            case $rclone_serve_options_index in
                0) RcloneServeView
                ;;
                1) RcloneServeAdd
                ;;
                2) RcloneServeEdit
                ;;
                3) RcloneServeDel
                ;;
                4) RcloneServeExc
                ;;
                5) RcloneServeDeExc
                ;;
            esac
        ;;
        3) 
            echo
            rclone_serve_acc_options=( "$i18n_view" "$i18n_add" "$i18n_edit" "$i18n_delete" )
            inquirer list_input_index "$i18n_select_action" rclone_serve_acc_options rclone_serve_acc_options_index

            case $rclone_serve_acc_options_index in
                0) RcloneServeAccView
                ;;
                1) RcloneServeAccAdd
                ;;
                2) RcloneServeAccEdit
                ;;
                3) RcloneServeAccDel
                ;;
            esac
        ;;
        4)
            if [ "${rc_sync_menu_locale:-}" != "${sh_locale:-zh_CN}" ]
            then
                rclone_sync_options=( "$i18n_view" "$i18n_add" "$i18n_edit" "$i18n_delete" "$(gettext "执行")" )
                rc_sync_menu_locale="${sh_locale:-zh_CN}"
            fi

            echo
            inquirer list_input_index "$i18n_select_action" rclone_sync_options rclone_sync_options_index

            case $rclone_sync_options_index in
                0) RcloneSyncView
                ;;
                1) RcloneSyncAdd
                ;;
                2) RcloneSyncEdit
                ;;
                3) RcloneSyncDel
                ;;
                4) RcloneSyncExc
                ;;
            esac
        ;;
        5) 
            DepInstall rsync
            if [[ -x $(command -v rclone) ]] 
            then
                rclone selfupdate
            else
                if [ "$dist" == "mac" ] 
                then
                    Println "$(eval_gettext "\$tip 可能需要输入密码继续安装")"
                fi
                sudo -v ; curl https://rclone.org/install.sh | grep -v 0555 | sudo bash
            fi
        ;;
    esac
elif [ "$self" == "cw" ]
then
    CalibreWebPatch()
    {
        if [ ! -d "$CALIBRE_ROOT/web" ] 
        then
            Println "$(eval_gettext "\$error 请先安装 Calibre Web")\n"
            return 1
        fi

        local d

        for d in "$CALIBRE_ROOT"/web/cps/translations/*
        do
            if TMP_FILE=$(mktemp -q) 
            then
                chmod +r "$TMP_FILE"
            else
                PrintfTime TMP_FILE '%m-%d-%H:%M:%S' -1
            fi

            trap '
                rm -f "$TMP_FILE"
            ' EXIT

            awk '
                BEGIN {
                    in_relevant_block = 0;
                }

                /#:/ {
                    in_relevant_block = ($0 ~ /helper\.py/) ? 1 : 0;
                }

                /^msgid/ && in_relevant_block {
                    gsub(/Calibre-Web/, "Epub.Fun");
                }

                /^msgstr/ && in_relevant_block {
                    gsub(/Calibre-Web/, "Epub.Fun");
                }

                { print }
            ' "$d"/LC_MESSAGES/messages.po > "$TMP_FILE"

            mv "$TMP_FILE" "$d"/LC_MESSAGES/messages.po

            trap - EXIT

            sed -i 's/please restart Calibre-Web/please restart/g' "$d"/LC_MESSAGES/messages.po
            sed -i 's/to hide it in Calibre-Web/to hide it/g' "$d"/LC_MESSAGES/messages.po
            sed -i 's/Calibre-Web Instance/Instance/g' "$d"/LC_MESSAGES/messages.po
            msgfmt -o "$d"/LC_MESSAGES/messages.mo "$d"/LC_MESSAGES/messages.po
        done

        sed -i '20,$s/Calibre-Web/Epub.Fun/g' "$CALIBRE_ROOT"/web/cps/helper.py
        sed -i '20,$s/ Calibre-Web//g' "$CALIBRE_ROOT"/web/cps/search.py
        sed -i 's/ in Calibre-Web//g' "$CALIBRE_ROOT"/web/cps/templates/detail.html
        sed -i 's/Calibre-Web //g' "$CALIBRE_ROOT"/web/cps/templates/http_error.html

        return 0
    }

    CalibreWebInstall()
    {
        if [ -d "$CALIBRE_ROOT/web" ] 
        then
            cd "$CALIBRE_ROOT/web"
            git stash
            git pull
            git stash pop
            Println "$(eval_gettext "\$info Calibre Web 更新成功")\n"
            return
        fi

        GitInstall
        PythonInstall
        git clone https://github.com/janeczku/calibre-web.git "$CALIBRE_ROOT/web"
        cd "$CALIBRE_ROOT/web"
        if [ "$dist" == "ubu" ] || [ "$dist" == "deb" ]
        then
            python3 -m pip install virtualenv
            virtualenv venv
        else
            python3 -m venv venv
        fi
        ./venv/bin/python3 -m pip install -r requirements.txt
        Println "$(eval_gettext "\$info Calibre Web 安装成功")\n"
    }

    CalibreWebStart()
    {
        service_name="calibre-web"

        if ServiceControl is-active "$service_name"
        then
            Println "$(eval_gettext "\$error \$service_name 已运行")\n"
            return 1
        fi

        service_commands=( "$CALIBRE_ROOT"/web/venv/bin/python3 "$CALIBRE_ROOT"/web/cps.py )

        if ! err_msg=$(ServiceControl start "$service_name" service_commands)
        then
            Println "$(eval_gettext "\$error \$service_name 启动失败, \$err_msg")\n"
            return 1
        fi

        Println "$(eval_gettext "\$info \$service_name 启动成功")\n"
    }

    CalibreWebStop()
    {
        service_name="calibre-web"

        if ! ServiceControl is-active "$service_name"
        then
            Println "$(eval_gettext "\$error \$service_name 未运行")\n"
            return 1
        fi

        if ! err_msg=$(ServiceControl stop "$service_name")
        then
            Println "$(eval_gettext "\$error \$service_name 关闭失败, \$err_msg")\n"
            return 1
        fi

        Println "$(eval_gettext "\$info \$service_name 关闭成功")\n"
    }

    CalibreWebRestart()
    {
        service_name="calibre-web"

        if ServiceControl is-active "$service_name" && ! err_msg=$(ServiceControl stop "$service_name")
        then
            Println "$(eval_gettext "\$error \$service_name 关闭失败, \$err_msg")\n"
            return 1
        fi

        service_commands=( "$CALIBRE_ROOT"/web/venv/bin/python3 "$CALIBRE_ROOT"/web/cps.py )

        if ! err_msg=$(ServiceControl start "$service_name" service_commands)
        then
            Println "$(eval_gettext "\$error \$service_name 重启失败, \$err_msg")\n"
            return 1
        fi

        Println "$(eval_gettext "\$info \$service_name 重启成功")\n"
    }

    CalibreWebView()
    {
        service_name="calibre-web"

        if ! ServiceControl is-active "$service_name"
        then
            Println "$(eval_gettext "\$error \$service_name 未运行")\n"
            return 1
        fi

        Println "$(eval_gettext "\$info 访问 Calibre Web: http://localhost:8083 , 用户名 admin 初始密码 admin123")\n"

        if [ "$dist" == "mac" ] 
        then
            open "http://localhost:8083"
        fi
    }
    KccInstall()
    {
        if [[ -x "$KCC_FILE" ]] 
        then
            cd "$CALIBRE_ROOT/kcc"
            git pull
            Println "$(eval_gettext "\$info KCC 更新成功")\n"
            return 0
        fi
        GitInstall
        PythonInstall
        git clone https://github.com/ciromattia/kcc.git "$KCC_ROOT"
        cd "$KCC_ROOT"
        python3 -m venv venv
        ./venv/bin/python3 -m pip install -r requirements.txt
        Println "$(eval_gettext "\$info KCC 安装成功")\n"
    }

    KccView()
    {
        ServiceGet kcc

        if [ -z "${kcc_output:-}" ] 
        then
            Println "$(eval_gettext "\$error 请先设置 kcc")\n"
            return 1
        fi

        local kcc_list="$(eval_gettext "输出格式: \$kcc_format")\n"

        if [ "$kcc_process" = true ] 
        then
            kcc_list="${kcc_list}$(gettext "处理图片: 是")\n"
        else
            kcc_list="${kcc_list}$(gettext "处理图片: 否")\n"
        fi

        if [ -n "${kcc_sources:-}" ] 
        then
            kcc_source=$(JoinByString ', ' "${kcc_sources[@]}")
        fi

        kcc_list="${kcc_list}$(gettext "额外参数"): ${kcc_args:-$i18n_none}\n$(gettext "输出目录"): $kcc_output\n$(gettext "源图片"): ${kcc_source:-$i18n_none}\n"

        Println "$kcc_list"
    }

    KccBrowse()
    {
        KccView

        kcc_view_options=( "$(gettext "输出目录")" "$(gettext "源图片")" )

        echo
        inquirer list_input_index "$i18n_please_select" kcc_view_options kcc_view_options_index

        if [ "$kcc_view_options_index" -eq 0 ] 
        then
            ServiceBrowse "$kcc_output"
        elif [ "$kcc_view_options_index" -eq 1 ] 
        then
            if [ -z "${kcc_sources:-}" ] 
            then
                Println "$(eval_gettext "\$error 请先添加源图片目录")\n"
                return 1
            fi
            echo
            inquirer list_input_index "$(gettext "请选择源图片目录")" kcc_sources kcc_sources_index
            ServiceBrowse "${kcc_sources[kcc_sources_index]}"
        fi
    }

    KccConfig()
    {
        ServiceGet kcc

        kcc_format_options=( Auto MOBI EPUB CBZ KFX MOBI+EPUB )

        echo
        inquirer list_input "$(gettext "选择输出格式")" kcc_format_options kcc_format

        echo
        inquirer list_input_index "$(gettext "是否处理图片")" ny_options ny_index

        if [ "$ny_index" -eq 0 ] 
        then
            kcc_process=false
            kcc_args=""
        else
            kcc_process=true
            echo
            inquirer text_input "$(gettext "输入额外参数")" kcc_args "$i18n_blank"
        fi

        echo
        ExitOnText "$(gettext "设置输出目录")" kcc_output
        RemoveQuotes kcc_output

        kcc_sources=()

        while true 
        do
            echo
            inquirer text_input "$(gettext "输入源图片目录")" kcc_source
            RemoveQuotes kcc_source
            if [ -z "$kcc_source" ] 
            then
                Println "$(eval_gettext "\$error 源图片目录不能为空")"
            else
                kcc_sources+=("$kcc_source")
                echo
                inquirer list_input_index "$(gettext "继续添加源图片目录")" ny_options ny_index
                if [ "$ny_index" -eq 0 ] 
                then
                    break
                fi
            fi
        done

        kcc_payload=$(
        $JQ_FILE -c -n --arg format "$kcc_format" --arg process "$kcc_process" \
        --arg args "$kcc_args" --arg output "$kcc_output" \
        --argjson source "$(ToJsonArray kcc_sources)" \
            '{
                format: $format,
                process: $process | test("true"),
                args: $args,
                output: $output,
                source: $source
            }'
        )

        jq_json=true
        jq_path='["kcc"]'
        JQ update "$SERVICES_CONFIG" "$kcc_payload"

        Println "$(eval_gettext "\$info kcc 设置成功")\n"
    }

    KccConfigEdit()
    {
        KccView

        kcc_config_edit_options=( "$(gettext "输出格式")" "$(gettext "是否处理图片")" "$(gettext "额外参数")" "$(gettext "输出目录")" "$(gettext "添加源图片目录")" "$(gettext "修改源图片目录")" "$(gettext "删除源图片目录")" )
        kcc_format_options=( Auto MOBI EPUB CBZ KFX MOBI+EPUB )

        echo
        inquirer checkbox_input_indices "$i18n_select_edit" kcc_config_edit_options kcc_config_edit_options_indices

        for kcc_config_edit_options_index in "${kcc_config_edit_options_indices[@]}"
        do
            case $kcc_config_edit_options_index in
                0) 
                    echo
                    inquirer list_input "$(gettext "选择输出格式")" kcc_format_options new_kcc_format
                    if [ "$new_kcc_format" != "$kcc_format" ] 
                    then
                        jq_path='["kcc","format"]'
                        JQ update "$SERVICES_CONFIG" "$new_kcc_format"
                        Println "$(eval_gettext "\$info 输出格式修改成功")\n"
                    fi
                ;;
                1) 
                    echo
                    inquirer list_input_index "$(gettext "是否处理图片")" ny_options ny_index
                    if [ "$ny_index" -eq 0 ] 
                    then
                        new_kcc_process=false
                    else
                        new_kcc_process=true
                    fi

                    if [ "$new_kcc_process" != "$kcc_process" ] 
                    then
                        jq_bool=true
                        jq_path='["kcc","process"]'
                        JQ update "$SERVICES_CONFIG" "$new_kcc_process"
                        Println "$(eval_gettext "\$info 是否处理图片修改成功")\n"
                    fi
                ;;
                2)
                    echo
                    inquirer text_input "$(gettext "输入额外参数")" new_kcc_args "$i18n_blank"

                    if [ "$new_kcc_args" != "$kcc_args" ] 
                    then
                        jq_path='["kcc","args"]'
                        JQ update "$SERVICES_CONFIG" "$new_kcc_args"
                        Println "$(eval_gettext "\$info 额外参数修改成功")\n"
                    fi
                ;;
                3) 
                    echo
                    inquirer text_input "$(gettext "设置输出目录")" new_kcc_output "$kcc_output"
                    RemoveQuotes new_kcc_output
                    if [ "$new_kcc_output" != "$kcc_output" ] 
                    then
                        jq_path='["kcc","output"]'
                        JQ update "$SERVICES_CONFIG" "$new_kcc_output"
                        Println "$(eval_gettext "\$info 输出目录修改成功")\n"
                    fi
                ;;
                4)
                    while true 
                    do
                        echo
                        inquirer text_input "$(gettext "输入源图片目录")" new_kcc_source "$i18n_blank"
                        if [ -z "$new_kcc_source" ] 
                        then
                            break
                        fi
                        RemoveQuotes new_kcc_source
                        if [ -z "$new_kcc_source" ] 
                        then
                            Println "$(eval_gettext "\$error 源图片目录不能为空")"
                        elif EleInArray "$new_kcc_source" kcc_sources
                        then
                            Println "$(eval_gettext "\$error 源图片目录已存在")"
                        else
                            kcc_sources+=("$new_kcc_source")
                            echo
                            inquirer list_input_index "$(gettext "继续添加源图片目录")" ny_options ny_index
                            if [ "$ny_index" -eq 0 ] 
                            then
                                break
                            fi
                        fi
                    done
                    jq_json=true
                    jq_path='["kcc","source"]'
                    JQ update "$SERVICES_CONFIG" "$(ToJsonArray kcc_sources)"
                    Println "$(eval_gettext "\$info 源图片目录添加成功")\n"
                ;;
                5)
                    if [ -z "${kcc_sources:-}" ] 
                    then
                        Println "$(eval_gettext "\$error 请先添加源图片目录")\n"
                        return 1
                    fi

                    echo
                    inquirer checkbox_input_indices "$(gettext "请选择源图片目录")" kcc_sources kcc_sources_indices

                    kcc_source_update=false

                    for kcc_sources_index in "${kcc_sources_indices[@]}"
                    do
                        while true 
                        do
                            echo
                            inquirer text_input "$(gettext "修改源图片目录") ${kcc_sources[kcc_sources_index]}" new_kcc_source "$i18n_blank"
                            if [ -z "$new_kcc_source" ] 
                            then
                                continue 2
                            fi
                            RemoveQuotes new_kcc_source
                            if [ -z "$new_kcc_source" ] 
                            then
                                Println "$(eval_gettext "\$error 源图片目录不能为空")"
                            elif EleInArray "$new_kcc_source" kcc_sources
                            then
                                Println "$(eval_gettext "\$error 源图片目录已存在")"
                            else
                                kcc_sources[$kcc_sources_index]="$new_kcc_source"
                                kcc_source_update=true
                                break
                            fi
                        done
                    done

                    if [ "$kcc_source_update" = true ] 
                    then
                        jq_json=true
                        jq_path='["kcc","source"]'
                        JQ update "$SERVICES_CONFIG" "$(ToJsonArray kcc_sources)"
                        Println "$(eval_gettext "\$info 源图片目录修改成功")\n"
                    fi
                ;;
                6)
                    if [ -z "${kcc_sources:-}" ] 
                    then
                        Println "$(eval_gettext "\$error 请先添加源图片目录")\n"
                        return 1
                    fi

                    echo
                    inquirer checkbox_input_indices "$(gettext "请选择源图片目录")" kcc_sources kcc_sources_indices

                    for kcc_sources_index in "${kcc_sources_indices[@]}"
                    do
                        unset kcc_sources[$kcc_sources_index]
                    done

                    jq_json=true
                    jq_path='["kcc","source"]'

                    if [ "${#kcc_sources[@]}" -eq 0 ]
                    then
                        JQ update "$SERVICES_CONFIG" "[]"
                    else
                        kcc_sources=("${kcc_sources[@]}")
                        JQ update "$SERVICES_CONFIG" "$(ToJsonArray kcc_sources)"
                    fi

                    Println "$(eval_gettext "\$info 源图片目录删除成功")\n"
                ;;
            esac
        done

        return 0
    }

    KccConvert()
    {
        local source="$1"
        shift
        local files_indices=( "$@" ) files_index kcc_commands=() kcc_output_name
        shopt -s nullglob
        local files=("$source"/*)
        shopt -u nullglob

        local kcc_convert_formats=( Auto MOBI EPUB CBZ KFX MOBI+EPUB ) format

        if [ "${kcc_format:-Auto}" != "Auto" ] 
        then
            kcc_convert_formats=( "$kcc_format" )
            for format in Auto MOBI EPUB CBZ KFX MOBI+EPUB
            do
                if [ "$format" != "$kcc_format" ] 
                then
                    kcc_convert_formats+=( "$format" )
                fi
            done
        fi

        if [ "${kcc_format:-Auto}" != "KFX Output" ] 
        then
            kcc_convert_formats+=( 'KFX Output' )
        fi

        kcc_convert_outputs=( "$kcc_output" "$(gettext "当前目录")" "$(gettext "输入新目录")" )

        echo
        inquirer list_input_index "$(gettext "选择输出目录")" kcc_convert_outputs kcc_convert_outputs_index

        case $kcc_convert_outputs_index in
            1) kcc_output="$source"
            ;;
            2) 
                echo
                inquirer text_input "$(gettext "输入转换输出的目录")" kcc_output "$kcc_output"
                RemoveQuotes kcc_output
            ;;
        esac

        echo
        inquirer list_input "$(gettext "选择输出格式")" kcc_convert_formats kcc_format

        if [ "$kcc_format" == "KFX Output" ] 
        then
            for files_index in "${files_indices[@]}"
            do
                if [ -d "${files[files_index]}" ] || [ "${files[files_index]##*.}" != "kpf" ]
                then
                    Println "$(eval_gettext "\$error 请只选择kpf文件")\n"
                    return 1
                fi
            done

            CalibrePluginInstall 'KFX Output'

            for files_index in "${files_indices[@]}"
            do
                kcc_output_name="${files[files_index]##*/}"
                kcc_output_name="${kcc_output_name%.*}.kfx"
                "$CALIBRE_BIN_ROOT"/calibre-debug -r "KFX Output" -- "${files[files_index]}" "${kcc_output}/${kcc_output_name}"
                Println "$info ${files[files_index]##*/} $(gettext "转换成功")\n"
            done

            return 0
        fi

        for files_index in "${files_indices[@]}"
        do
            if [ ! -d "${files[files_index]}" ] 
            then
                Println "$(eval_gettext "\$error 请只选择图片目录")\n"
                return 1
            fi
        done

        if [ "${kcc_process:-false}" = false ] 
        then
            kcc_commands+=( -n )
        elif [ -n "$kcc_args" ] 
        then
            kcc_commands+=($kcc_args)
        fi

        source "${KCC_ROOT}/venv/bin/activate"

        for files_index in "${files_indices[@]}"
        do
            python3 "$KCC_FILE" ${kcc_commands+"${kcc_commands[@]}"} -f "$kcc_format" -o "$kcc_output"/ "${files[files_index]}"
            Println "$info ${files[files_index]##*/} $(gettext "转换成功")\n"
        done

        return 0
    }

    KccMenu()
    {
        kcc_options=( "$(gettext "浏览")" "$(gettext "转换")" "$(gettext "设置")" "$(gettext "修改设置")" "$(gettext "更新/安装")" )
        echo
        inquirer list_input_index "$i18n_please_select" kcc_options kcc_options_index

        case $kcc_options_index in
            0) KccBrowse
            ;;
            1) 
                KccView

                if [ -z "${kcc_sources:-}" ] 
                then
                    Println "$(eval_gettext "\$error 请先添加源图片目录")\n"
                    return 1
                fi

                if [[ ! -x "$KCC_FILE" ]] 
                then
                    Println "$(eval_gettext "\$error 请先安装 kcc")\n"
                    return 1
                fi

                echo
                inquirer list_input_index "$(gettext "请选择源图片目录")" kcc_sources kcc_sources_index

                ServiceBrowse "${kcc_sources[$kcc_sources_index]}" "$(gettext "转换")" KccConvert
            ;;
            2) KccConfig
            ;;
            3) KccConfigEdit
            ;;
            4) KccInstall
            ;;
        esac
    }
    CalibreInstall()
    {
        if [ "$dist" == "mac" ] 
        then
            brew install --cask calibre
        else
            DepInstall wget
            DepInstall xdg-utils
            if [ "$dist" == "rpm" ] 
            then
                DepInstall xz
                DepInstall libglvnd-opengl
                DepInstall libxcb-cursor-devel
                DepInstall nss
                DepInstall libxkbcommon
                DepInstall mesa-libEGL
            else
                DepInstall xz-utils
                DepInstall libopengl0
                DepInstall libxcb-cursor0
                DepInstall libnss3
                DepInstall libxkbcommon-x11-0
                DepInstall libglx0
                DepInstall libegl1
            fi
            ImageMagickInstall
            PythonInstall
            pip3 install pyqt6
            mkdir -p "$CALIBRE_ROOT"/bin
            sudo -v && wget -nv -O- https://download.calibre-ebook.com/linux-installer.sh | sudo sh /dev/stdin install_dir="$CALIBRE_ROOT"/bin version=7.16.0
        fi

        Println "$(eval_gettext "\$info calibre 安装/更新成功")\n"
    }

    CalibrePluginInstall()
    {
        if { [ "$dist" == "mac" ] && [ ! -d /Applications/calibre.app ]; } || { [ "$dist" != "mac" ] && [ ! -d "$CALIBRE_ROOT"/bin ]; }
        then
            CalibreInstall
        fi

        if [ "$dist" == "mac" ] 
        then
            CALIBRE_BIN_ROOT="/Applications/calibre.app/Contents/MacOS"
        else
            CALIBRE_BIN_ROOT="$CALIBRE_ROOT"/bin/calibre
        fi

        local plugin_name="$1" plugin_grep=$("$CALIBRE_BIN_ROOT"/calibre-customize -l)
        if ! grep -q "$plugin_name" <<< "$plugin_grep"
        then
            DepInstall curl
            mkdir -p "$CALIBRE_ROOT"/plugins
            if ! curl -L -o "${CALIBRE_ROOT}/plugins/${plugin_name}.zip" "$FFMPEG_MIRROR_LINK/calibre/plugins/${plugin_name}.zip"
            then
                Println "$(eval_gettext "\$error \$plugin_name 插件不存在")\n"
                return 1
            fi
            "$CALIBRE_BIN_ROOT"/calibre-customize -a "${CALIBRE_ROOT}/plugins/${plugin_name}.zip"
            Println "$(eval_gettext "\$info \$plugin_name 插件安装成功")\n"
        fi
    }

    calibre_options=( 'kcc' "$(gettext "安装/更新 calibre")" "$(gettext "开启 Calibre Web")" "$(gettext "关闭 Calibre Web")" "$(gettext "重启 Calibre Web")" "$(gettext "查看 Calibre Web")" "$(gettext "安装/更新 Calibre Web")" 'Patch Calibre Web' )
    echo
    inquirer list_input_index "$i18n_please_select" calibre_options calibre_options_index

    case $calibre_options_index in
        0) KccMenu
        ;;
        1) CalibreInstall
        ;;
        2) CalibreWebStart
        ;;
        3) CalibreWebStop
        ;;
        4) CalibreWebRestart
        ;;
        5) CalibreWebView
        ;;
        6) CalibreWebInstall
        ;;
        7) CalibreWebPatch
        ;;
    esac
elif [ "$self" == "dr" ]
then
    DockerInstall()
    {
        local install="$i18n_update"

        if [ -z "${1:-}" ]
        then
            if [[ -x $(command -v docker) ]]
            then
                return 0
            fi
            install="$i18n_install"
        elif [[ ! -x $(command -v docker) ]]
        then
            install="$i18n_install"
        fi

        if [ "$dist" == "mac" ]
        then
            brew install --cask docker
            Println "$(eval_gettext "\$info docker \${install}成功, 打开 docker app 完成最后设置!")\n"
            return 0
        fi

        DepInstall curl
        DepInstall ca-certificates
        DepInstall gpg

        case $dist in
            ubu|deb)
                local docker_dist="ubuntu" docker_codename docker_repo_base docker_key_url
                if [ "$dist" == "deb" ]
                then
                    docker_dist="debian"
                fi

                docker_codename=$(AptGetCodename)

                if grep -q "docker-ce" < /etc/apt/sources.list
                then
                    sed -i '/docker-ce/d' /etc/apt/sources.list
                fi

                if [ ! -f "/etc/apt/sources.list.d/docker.list" ]
                then
                    docker_repo_base="${DOCKER_REPO_LINK}/${docker_dist}"
                    if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                    then
                        docker_key_url="http://${USTC_MIRROR_HOST}/docker-ce/linux/${docker_dist}/gpg"
                    else
                        docker_key_url="${DOCKER_REPO_LINK}/${docker_dist}/gpg"
                    fi

                    if ! AptRepoCheck "$docker_repo_base" "$docker_codename"
                    then
                        local docker_codename_display="${docker_codename:-unknown}"
                        Println "$(eval_gettext "\$error Docker 官方源暂不支持当前系统 (\$docker_codename_display), 未写入失效源")\n"
                        return 1
                    fi

                    curl -fsSL "$docker_key_url" | gpg --batch --yes --dearmor -o /usr/share/keyrings/docker-archive-keyring.gpg
                    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] ${docker_repo_base} \
                ${docker_codename} stable" | tee /etc/apt/sources.list.d/docker.list
                    AptUpdate force
                fi

                for pkg in docker.io docker-doc docker-compose podman-docker containerd runc
                do
                    sudo apt-get -y remove $pkg || true
                done

                AptInstall docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
            ;;
            rpm)
                echo
                sudo yum install -y yum-utils
                sudo yum-config-manager --add-repo https://download.docker.com/linux/centos/docker-ce.repo
                sudo yum remove docker \
                    docker-client \
                    docker-client-latest \
                    docker-common \
                    docker-latest \
                    docker-latest-logrotate \
                    docker-logrotate \
                    docker-engine || true
                sudo yum -y install docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
            ;;
            *)
                Println "$(eval_gettext "\$error 不支持的系统")\n"
                return 1
            ;;
        esac

        if [ ! -f /etc/systemd/system/docker.service.d/clear_mount_propagation_flags.conf ]
        then
cat > /etc/systemd/system/docker.service.d/clear_mount_propagation_flags.conf <<EOF
[Service]
MountFlags=shared
EOF
            systemctl daemon-reload
            systemctl restart docker
        fi

        Println "$(eval_gettext "\$info docker 安装成功")\n"
    }
    DockerCrtSelfSignValid()
    {
        local domain=$1

        if [ -e "$service_cert_root/$domain".crt ] && [ -e "$service_cert_root/$domain".key ]
        then
            return 1
        fi
    }

    DockerCrtManage()
    {
        if [ ! -d "$DOCKER_ROOT" ] 
        then
            if [ ! -d "$DEPENDS_ROOT"/aios ] 
            then
                mkdir -p "$DEPENDS_ROOT"
                GitInstall
                git clone "$AIOS_LINK" "$DEPENDS_ROOT"/aios
            else
                cd "$DEPENDS_ROOT"/aios
                git fetch --all && git reset --hard origin/main
            fi
            cp -r "$DEPENDS_ROOT"/aios/scripts/docker "$DOCKER_ROOT"
        fi

        echo
        crt_options=( "$(gettext "浏览证书")" "$(gettext "安装自签名证书")" )
        inquirer list_input_index "$i18n_select_action" crt_options crt_options_index

        case $crt_options_index in
            0) ServiceBrowse "$DOCKER_ROOT"/certs
            ;;
            1) 
                cd "$DOCKER_ROOT"/certs

                if [ ! -f "$DOCKER_ROOT"/certs/root.crt ] 
                then
                    echo
                    inquirer text_input "$(gettext "请输入你想设置的根证书公用名CN (Common Name)")" root_cn root.yourdomain.com
                    openssl req -new -nodes -text -out root.csr -newkey rsa:4096 -keyout root.key -subj "/CN=$root_cn"
                    chmod og-rwx root.key
                    openssl x509 -req -in root.csr -text -days 3650 -extfile "$DOCKER_ROOT"/certs/openssl.cnf -extensions v3_ca -signkey root.key -out root.crt
                    Println "$(eval_gettext "\$info \$DOCKER_ROOT/certs/root.crt 可以添加到用户端系统用来验证之后自签名的证书")\n"
                fi

                docker_certs_services=( 'traefik' )
                echo
                inquirer list_input "$(gettext "选择安装证书的服务")" docker_certs_services docker_certs_service

                service_cert_root="$DOCKER_ROOT/certs/$docker_certs_service"

                mkdir -p newcerts
                mkdir -p "$docker_certs_service"

                echo
                inquirer text_input "$(gettext "请输入自签名证书公用名CN (Common Name)")" server_cn localhost DockerCrtSelfSignValid "$(gettext "证书已存在")"

                ny_index=0

                if ! [[ "$server_cn" =~ \* ]] 
                then
                    echo
                    inquirer list_input_index "$(eval_gettext "是否将子域名 *.\$server_cn 加到 SAN")" ny_options ny_index
                fi

                if [ "$ny_index" -eq 1 ] 
                then
                    root_domain="${server_cn#\*.}"
                    san="DNS:$root_domain,DNS:*.$root_domain,IP:127.0.0.1,IP:::1"
                else
                    san="DNS:$server_cn,IP:127.0.0.1,IP:::1"
                fi

                openssl req -new -nodes -text -out "$service_cert_root/${server_cn}".csr -newkey rsa:4096 -keyout "$service_cert_root/${server_cn}".key -subj "/CN=$server_cn" -addext "subjectAltName=$san"

                chmod og-rwx "$service_cert_root/${server_cn}".key

                if openssl help x509 2>&1 | grep -q "copy_extensions"
                then
                    openssl_cmds=(openssl x509 -req -copy_extensions copy -in "$service_cert_root/${server_cn}".csr -text -days 365 -CA root.crt -CAkey root.key -CAcreateserial -out "$service_cert_root/${server_cn}".crt)
                else
                    openssl_cmds=(openssl ca -batch -config "$DOCKER_ROOT"/certs/openssl.cnf -policy signing_policy -extensions signing_req -out "$service_cert_root/${server_cn}".crt -infiles "$service_cert_root/${server_cn}".csr)
                fi

                if [ ! -f ./index.txt ] 
                then
                    touch index.txt
                fi

                if [ ! -f ./serial ] 
                then
                    echo 01 > serial
                fi

                "${openssl_cmds[@]}"

                openssl x509 -in "$service_cert_root/${server_cn}".crt -outform PEM -out "$service_cert_root/${server_cn}".pem

                if [ "$ny_index" -eq 1 ] 
                then
                    openssl req -new -nodes -text -out "$service_cert_root/*.${server_cn}".csr -newkey rsa:4096 -keyout "$service_cert_root/*.${server_cn}".key -subj "/CN=*.$server_cn" -addext "subjectAltName=$san"
                    chmod og-rwx "$service_cert_root/*.${server_cn}".key
                    if openssl help x509 2>&1 | grep -q "copy_extensions"
                    then
                        openssl_cmds=(openssl x509 -req -copy_extensions copy -in "$service_cert_root/*.${server_cn}".csr -text -days 365 -CA ../root.crt -CAkey ../root.key -CAcreateserial -out "$service_cert_root/*.${server_cn}".crt)
                    else
                        openssl_cmds=(openssl ca -batch -config "$DOCKER_ROOT"/certs/openssl.cnf -policy signing_policy -extensions signing_req -out "$service_cert_root/*.${server_cn}".crt -infiles "$service_cert_root/*.${server_cn}".csr)
                    fi
                    "${openssl_cmds[@]}"
                    openssl x509 -in "$service_cert_root/*.${server_cn}".crt -outform PEM -out "$service_cert_root/*.${server_cn}".pem
                    cat "$service_cert_root/${server_cn}".pem "$service_cert_root/*.${server_cn}".pem > "$service_cert_root/${server_cn}".pem.tmp
                    mv "$service_cert_root/${server_cn}".pem.tmp "$service_cert_root/${server_cn}".pem
                fi

                Println "$(eval_gettext "\$info 自签名证书安装成功")\n"
            ;;
        esac

        return 0
    }
    DockerServiceStart()
    {
        DockerInstall
        PostgresqlInstall
        YqInstall

        . "$DOCKER_ROOT"/.env

        if [ ! -f "$DOCKER_ROOT/certs/traefik/$TRAEFIK_DOMAIN".crt ] || [ ! -f "$DOCKER_ROOT/certs/traefik/$TRAEFIK_DOMAIN".key ]
        then
            Println "$(eval_gettext "\$error \$TRAEFIK_DOMAIN 的证书不存在")\n"
            return 1
        fi

        if [ ! -f "$DOCKER_ROOT"/certs/traefik/hub.docker.com.crt ] || [ ! -f "$DOCKER_ROOT"/certs/traefik/hub.docker.com.key ]
        then
            Println "$(eval_gettext "\$error hub.docker.com 的证书不存在")\n"
            return 1
        fi

        traefik_local_plugins=($(yq '.experimental.localPlugins | map_values(.modulename) | to_entries | .[] | .value' "$DOCKER_ROOT"/data/traefik/config/traefik.yml))

        for traefik_local_plugin in "${traefik_local_plugins[@]}"
        do
            if [ ! -d "$DOCKER_ROOT/data/traefik/plugins-local/src/$traefik_local_plugin" ]
            then
                Println "$(eval_gettext "\$error traefik 本地插件 \$traefik_local_plugin 不存在, 请先设置")\n"
                return 1
            fi
        done

        JWT_SECRET=$(< "$DOCKER_ROOT"/data/authelia/secrets/JWT_SECRET)
        SESSION_REDIS_PASSWORD=$(< "$DOCKER_ROOT"/data/authelia/secrets/SESSION_REDIS_PASSWORD)
        SESSION_SECRET=$(< "$DOCKER_ROOT"/data/authelia/secrets/SESSION_SECRET)
        STORAGE_ENCRYPTION_KEY=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_ENCRYPTION_KEY)
        STORAGE_POSTGRES_PASSWORD=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_POSTGRES_PASSWORD)

        for var in JWT_SECRET SESSION_REDIS_PASSWORD SESSION_SECRET STORAGE_ENCRYPTION_KEY STORAGE_POSTGRES_PASSWORD
        do
            if [[ -z "${!var:-}" ]]
            then
                Println "$(eval_gettext "\$error \$var 为空, 请先设置服务 secrets")\n"
                return 1
            fi
        done

        if ! psql -c "\du" | grep -q authelia || ! psql -c "SELECT datname FROM pg_catalog.pg_database;" | grep -q authelia
        then
            Println "$(eval_gettext "\$error 请先设置服务 postgresql")\n"
            return 1
        fi

        cd "$DOCKER_ROOT"

        mkdir -p "$DOCKER_ROOT/data/redis"
        mkdir -p "$DOCKER_ROOT/data/traefik/logs"
        mkdir -p "$DOCKER_ROOT/data/authelia/logs"

        docker compose up
    }

    DockerServiceStartClean()
    {
        cd "$DOCKER_ROOT"

        docker compose up
    }

    DockerServiceStop()
    {
        DockerInstall

        cd "$DOCKER_ROOT"

        docker compose stop
    }

    DockerServiceConfig()
    {
        echo
        docker_config_options=( 'Traefik' 'Authelia' 'Postgresql' )
        inquirer checkbox_input_indices "$i18n_please_select" docker_config_options docker_config_options_indices

        for docker_config_options_index in "${docker_config_options_indices[@]}"
        do
            echo
            case $docker_config_options_index in
                0)
                    traefik_options=( "$i18n_domain" "$(gettext "本地插件")" )
                    inquirer checkbox_input_indices "$(gettext "选择 traefik 设置选项")" traefik_options traefik_options_indices

                    for traefik_options_index in "${traefik_options_indices[@]}"
                    do
                        if [ $traefik_options_index -eq 0 ]
                        then
                            . "$DOCKER_ROOT"/.env
                            echo
                            inquirer text_input "$(gettext "请输入 traefik 使用的域名")" traefik_domain "$TRAEFIK_DOMAIN"
                            if [ "$traefik_domain" != "$TRAEFIK_DOMAIN" ]
                            then
                                sed -i "/TRAEFIK_DOMAIN=/c\TRAEFIK_DOMAIN=$traefik_domain" "$DOCKER_ROOT"/.env
                                Println "$(eval_gettext "\$info traefik 域名已设置为 \$traefik_domain")\n"
                            fi
                        else
                            traefik_local_plugins=( cors-preflight )
                            traefik_plugins=( github.com/Medzoner/traefik-plugin-cors-preflight )
                            local msg_plugin_updated msg_plugin_installed
                            msg_plugin_updated=$(gettext "插件已更新")
                            msg_plugin_installed=$(gettext "插件已安装")
                            echo
                            inquirer checkbox_input_indices "$(gettext "选择 traefik 本地插件")" traefik_local_plugins traefik_local_plugins_indices
                            for traefik_local_plugins_index in "${traefik_local_plugins_indices[@]}"
                            do
                                if [ -d "$DOCKER_ROOT/data/traefik/plugins-local/src/${traefik_plugins[$traefik_local_plugins_index]}" ]
                                then
                                    cd "$DOCKER_ROOT/data/traefik/plugins-local/src/${traefik_plugins[$traefik_local_plugins_index]}"
                                    git pull
                                    Println "$info ${traefik_local_plugins[$traefik_local_plugins_index]} $msg_plugin_updated\n"
                                    continue
                                fi
                                git clone "https://${traefik_plugins[$traefik_local_plugins_index]}" "$DOCKER_ROOT/data/traefik/plugins-local/src/${traefik_plugins[$traefik_local_plugins_index]}"
                                Println "$info ${traefik_local_plugins[$traefik_local_plugins_index]} $msg_plugin_installed\n"
                            done
                        fi
                    done
                ;;
                1)
                    authelia_options=( "$i18n_domain" "$(gettext "用户名")" "$(gettext "显示名")" "$i18n_password" secrets )
                    inquirer checkbox_input_indices "$(gettext "选择 authelia 设置选项")" authelia_options authelia_options_indices
                    for authelia_options_index in "${authelia_options_indices[@]}"
                    do
                        case $authelia_options_index in
                            0)
                                . "$DOCKER_ROOT"/.env
                                echo
                                inquirer text_input "$(gettext "请输入 authelia 使用的域名")" authelia_domain "$AUTHELIA_DOMAIN"
                                if [ "$authelia_domain" != "$AUTHELIA_DOMAIN" ]
                                then
                                    sed -i "/AUTHELIA_DOMAIN=/c\AUTHELIA_DOMAIN=$traefik_domain" "$DOCKER_ROOT"/.env
                                    echo
                                    inquirer list_input_index "$(gettext "是否添加到 /etc/hosts")" ny_options ny_index
                                    if [ $ny_index -eq 1 ]
                                    then
                                        Println "$(eval_gettext "\$tip 可能需要输入密码")"
                                        echo "\
    127.0.0.1  hub.docker.com
    127.0.0.1  authelia.$DOMAIN
    127.0.0.1  public.$DOMAIN
    127.0.0.1  traefik.$DOMAIN
    127.0.0.1  secure.$DOMAIN" | sudo tee -a /etc/hosts > /dev/null
                                    fi
                                    Println "$(eval_gettext "\$info authelia 域名已设置为 \$authelia_domain")\n"
                                fi
                            ;;
                            1)
                                authelia_usernames=($(yq '.users | keys | join(" ")' "$DOCKER_ROOT"/data/authelia/config/users_database.yml))
                                authelia_default_username="${authelia_usernames[0]}"
                                echo
                                inquirer text_input "$(gettext "请输入 authelia 用户名")" authelia_username "$authelia_default_username"
                                if [ "$authelia_username" != "$authelia_default_username" ]
                                then
                                    yq_path_new=".users.$authelia_username"
                                    yq_path_old=".users.$authelia_default_username"
                                    YQ update_key "$DOCKER_ROOT"/data/authelia/config/users_database.yml
                                    authelia_user_email=$(yq ".users.$authelia_username.email" "$DOCKER_ROOT"/data/authelia/config/users_database.yml)
                                    if [[ "$authelia_user_email" =~ '<USERNAME>' ]]
                                    then
                                        yq_path='["users","'$authelia_username'","email"]'
                                        yq_replace="${authelia_username}@${authelia_user_email#*@}"
                                        YQ update "$DOCKER_ROOT"/data/authelia/config/users_database.yml
                                    fi
                                    Println "$(eval_gettext "\$info authelia 用户名已改为 \$authelia_username")\n"
                                fi
                            ;;
                            2)
                                authelia_usernames=($(yq '.users | keys | join(" ")' "$DOCKER_ROOT"/data/authelia/config/users_database.yml))
                                authelia_default_username="${authelia_usernames[0]}"
                                authelia_default_displayname=$(yq ".users.$authelia_default_username.displayname" "$DOCKER_ROOT"/data/authelia/config/users_database.yml)
                                echo
                                inquirer text_input "$(eval_gettext "请输入 authelia 用户 \$authelia_default_username 的显示名")" authelia_displayname "$authelia_default_displayname"
                                if [ "$authelia_displayname" != "$authelia_default_displayname" ]
                                then
                                    yq_path='["users","'$authelia_default_username'","displayname"]'
                                    yq_replace="$authelia_displayname"
                                    YQ update "$DOCKER_ROOT"/data/authelia/config/users_database.yml
                                    Println "$(eval_gettext "\$info authelia 用户 \$authelia_default_username 的显示名已改为 \$authelia_displayname")\n"
                                fi
                            ;;
                            3)
                                authelia_usernames=($(yq '.users | keys | join(" ")' "$DOCKER_ROOT"/data/authelia/config/users_database.yml))
                                authelia_default_username="${authelia_usernames[0]}"
                                authelia_default_password=$(yq ".users.$authelia_default_username.password" "$DOCKER_ROOT"/data/authelia/config/users_database.yml)
                                DockerInstall
                                if ! docker images | grep -q authelia/authelia
                                then
                                    Println "$(eval_gettext "\$info 下载 authelia 镜像...")"
                                    docker pull authelia/authelia
                                fi
                                echo
                                inquirer text_input "$(eval_gettext "请输入 authelia 用户 \$authelia_default_username 的密码")" authelia_password "$authelia_default_password"
                                authelia_password=$(docker run authelia/authelia authelia crypto hash generate argon2 --password $authelia_password | sed 's/Digest: //g')
                                if [ "$authelia_password" != "$authelia_default_password" ]
                                then
                                    yq_path='["users","'$authelia_default_username'","password"]'
                                    yq_replace="$authelia_password"
                                    YQ update "$DOCKER_ROOT"/data/authelia/config/users_database.yml
                                    Println "$(eval_gettext "\$info authelia 用户 \$authelia_default_username 的密码已改为 \$authelia_password")\n"
                                fi
                            ;;
                            4)
                                authelia_secrets=( JWT_SECRET SESSION_REDIS_PASSWORD SESSION_SECRET STORAGE_ENCRYPTION_KEY STORAGE_POSTGRES_PASSWORD )
                                echo
                                local msg_set_success
                                msg_set_success=$(gettext "设置成功")
                                inquirer checkbox_input_indices "$(gettext "选择设置的 secret")" authelia_secrets authelia_secrets_indices

                                for authelia_secret_index in "${authelia_secrets_indices[@]}"
                                do
                                    echo
                                    case $authelia_secret_index in
                                        0)
                                            default_jwt_secret=$(< "$DOCKER_ROOT"/data/authelia/secrets/JWT_SECRET)
                                            inquirer text_input "$(gettext "请输入 JWT_SECRET")" JWT_SECRET "${default_jwt_secret:-$(openssl rand -hex 32)}"
                                        ;;
                                        1)
                                            default_session_redis_password=$(< "$DOCKER_ROOT"/data/authelia/secrets/SESSION_REDIS_PASSWORD)
                                            inquirer text_input "$(gettext "请输入 SESSION_REDIS_PASSWORD")" SESSION_REDIS_PASSWORD "${default_session_redis_password:-$(openssl rand -hex 64)}"
                                        ;;
                                        2)
                                            default_session_secret=$(< "$DOCKER_ROOT"/data/authelia/secrets/SESSION_SECRET)
                                            inquirer text_input "$(gettext "请输入 SESSION_SECRET")" SESSION_SECRET "${default_session_secret:-$(openssl rand -hex 64)}"
                                        ;;
                                        3)
                                            default_storage_encryption_key=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_ENCRYPTION_KEY)
                                            inquirer text_input "$(gettext "请输入 STORAGE_ENCRYPTION_KEY")" STORAGE_ENCRYPTION_KEY "${default_storage_encryption_key:-$(openssl rand -hex 32)}"
                                        ;;
                                        4)
                                            default_storage_postgres_password=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_POSTGRES_PASSWORD)
                                            inquirer text_input "$(gettext "请输入 STORAGE_POSTGRES_PASSWORD")" STORAGE_POSTGRES_PASSWORD "${default_storage_postgres_password:-$(RandStr 15)}"
                                        ;;
                                    esac
                                    echo -n "${!authelia_secrets[authelia_secret_index]}" > "$DOCKER_ROOT"/data/authelia/secrets/${authelia_secrets[authelia_secret_index]}
                                    Println "$info ${authelia_secrets[authelia_secret_index]} $msg_set_success\n"
                                done
                            ;;
                        esac
                    done
                ;;
                2)
                    postgresql_options=( "$(gettext "添加 role authelia")" "$(gettext "添加 database authelia")" "$(gettext "设置 role authelia 的密码")" )
                    local prompt_pg_pass
                    prompt_pg_pass=$(gettext "请输入 role authelia 的密码")
                    echo
                    inquirer checkbox_input_indices "$(gettext "选择 postgresql 设置选项")" postgresql_options postgresql_options_indices
                    for postgresql_options_index in "${postgresql_options_indices[@]}"
                    do
                        case $postgresql_options_index in
                            0)
                                if psql -c "\du" | grep -q authelia
                                then
                                    Println "$(eval_gettext "\$error role authelia 已存在")\n"
                                    continue
                                fi
                                default_storage_postgres_password=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_POSTGRES_PASSWORD)
                                echo
                                inquirer text_input "$prompt_pg_pass" storage_postgres_password "${default_storage_postgres_password:-$(RandStr 15)}"
                                psql -c "CREATE ROLE authelia PASSWORD '$storage_postgres_password' CREATEDB REPLICATION LOGIN;"
                                Println "$(eval_gettext "\$info role authelia 已添加")\n"
                            ;;
                            1)
                                if ! psql -c "\du" | grep -q authelia
                                then
                                    Println "$(eval_gettext "\$error 请先添加 role authelia")\n"
                                    continue
                                fi
                                if psql -c "SELECT datname FROM pg_catalog.pg_database;" | grep -q authelia
                                then
                                    Println "$(eval_gettext "\$error database authelia 已存在")\n"
                                    continue
                                fi
                                psql -c "CREATE DATABASE authelia OWNER authelia;"
                                Println "$(eval_gettext "\$info database authelia 已添加")\n"
                            ;;
                            2)
                                if ! psql -c "\du" | grep -q authelia
                                then
                                    Println "$(eval_gettext "\$error 请先添加 role authelia")\n"
                                    continue
                                fi
                                default_storage_postgres_password=$(< "$DOCKER_ROOT"/data/authelia/secrets/STORAGE_POSTGRES_PASSWORD)
                                echo
                                inquirer text_input "$prompt_pg_pass" storage_postgres_password "${default_storage_postgres_password:-$(RandStr 15)}"
                                psql -c "ALTER ROLE authelia PASSWORD '$storage_postgres_password';"
                                Println "$(eval_gettext "\$info role authelia 的密码已设置")\n"
                            ;;
                        esac
                    done
                ;;
            esac
        done

        return 0
    }

    DockerService()
    {
        if [ ! -d "$DOCKER_ROOT" ]
        then
            if [ ! -d "$DEPENDS_ROOT"/aios ]
            then
                mkdir -p "$DEPENDS_ROOT"
                GitInstall
                git clone "$AIOS_LINK" "$DEPENDS_ROOT"/aios
            else
                cd "$DEPENDS_ROOT"/aios
                git fetch --all && git reset --hard origin/main
            fi
            cp -r "$DEPENDS_ROOT"/aios/scripts/docker "$DOCKER_ROOT"
        fi

        if [ "$dist" == "mac" ] && [[ ! -x $(command -v psql) ]] && [[ -x /Applications/Postgres.app/Contents/Versions/latest/bin/psql ]]
        then
            export PATH="${PATH}:/Applications/Postgres.app/Contents/Versions/latest/bin"
        fi

        docker_service_options=( "$(gettext "启动")" "$(gettext "启动(原版)")" "$i18n_close" "$(gettext "重启")" "$(gettext "重启(原版)")" "$(gettext "设置")" )
        echo
        inquirer list_input_index "$i18n_please_select" docker_service_options docker_service_options_index

        case $docker_service_options_index in
            0) DockerServiceStart
            ;;
            1) DockerServiceStartClean
            ;;
            2) DockerServiceStop
            ;;
            3)
                DockerServiceStop
                DockerServiceStart
            ;;
            4)
                DockerServiceStop
                DockerServiceStartClean
            ;;
            5)
                YqInstall
                DockerServiceConfig
            ;;
        esac

        return 0
    }
    PostgresqlInstall()
    {
        local install="$(gettext "更新")"

        if [ -z "${1:-}" ]
        then
            if [[ -x $(command -v psql) ]]
            then
                return 0
            fi
            install="$(gettext "安装")"
        elif [[ ! -x $(command -v psql) ]]
        then
            install="$(gettext "安装")"
        fi

        if [ "$dist" == "mac" ]
        then
            if [[ -x /Applications/Postgres.app/Contents/Versions/latest/bin/psql ]]
            then
                return 0
            fi

            brew install --cask postgres-unofficial
            open /Applications/Postgres.app
            if [ ! -f /etc/paths.d/postgresapp ]
            then
                Println "$(eval_gettext "\$info 输入密码配置命令行: ")"
                sudo mkdir -p /etc/paths.d && echo /Applications/Postgres.app/Contents/Versions/latest/bin | sudo tee /etc/paths.d/postgresapp
            fi
            Println "$(eval_gettext "\$info postgresql \${install}成功")\n"
            return 0
        fi

        DepInstall curl
        DepInstall ca-certificates

        . /etc/os-release

        case $dist in
            ubu|deb)
                local pg_codename
                pg_codename=$(AptGetCodename)

                if [ ! -f /etc/apt/sources.list.d/pgdg.list ]
                then
                    local pg_repo_base="$PGDG_APT_LINK"
                    local pg_key_url="https://www.postgresql.org/media/keys/ACCC4CF8.asc"

                    if grep -q "$USTC_MIRROR_HOST" < /etc/apt/sources.list
                    then
                        pg_repo_base="https://${USTC_MIRROR_HOST}/postgresql/repos/apt"
                        pg_key_url="https://${USTC_MIRROR_HOST}/postgresql/repos/apt/ACCC4CF8.asc"
                    fi

                    if ! AptRepoCheck "$pg_repo_base" "${pg_codename}-pgdg"
                    then
                        if AptRepoCheck "$PGDG_ARCHIVE_APT_LINK" "${pg_codename}-pgdg"
                        then
                            pg_repo_base="$PGDG_ARCHIVE_APT_LINK"
                        else
                            local pg_codename_text="${pg_codename:-unknown}"
                            Println "$(eval_gettext "\$tip PostgreSQL 官方源暂不支持当前系统 (\$pg_codename_text), 改用系统默认源安装")"
                            AptInstall postgresql
                            return $?
                        fi
                    fi

                    DepInstall gpg
                    curl -fsSL "$pg_key_url" | gpg --batch --yes --dearmor -o /usr/share/keyrings/postgresql-archive-keyring.gpg
                    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/postgresql-archive-keyring.gpg] ${pg_repo_base} ${pg_codename}-pgdg main" | tee /etc/apt/sources.list.d/pgdg.list > /dev/null
                    AptUpdate force
                fi

                AptInstall postgresql
            ;;
            rpm)
                ArchCheck

                local repo_name=""
                if [ "$arch" == "arm64" ]
                then
                    repo_name="-aarch64"
                else
                    repo_name="-x86_64"
                fi
                if [ "${ID:-}" == "fedora" ]
                then
                    repo_name="F-${VERSION_ID%%.*}${repo_name}/pgdg-fedora-repo-latest.noarch.rpm"
                else
                    repo_name="EL-${VERSION_ID%%.*}${repo_name}/pgdg-redhat-repo-latest.noarch.rpm"
                fi
                if [[ -x $(command -v dnf) ]]
                then
                    sudo dnf install -y https://download.postgresql.org/pub/repos/yum/reporpms/${repo_name}
                    sudo dnf -qy module disable postgresql || true
                    sudo dnf install -y "postgresql${POSTGRESQL_VER}-server"
                    sudo "/usr/pgsql-${POSTGRESQL_VER}/bin/postgresql-${POSTGRESQL_VER}-setup" initdb
                    sudo systemctl enable "postgresql-${POSTGRESQL_VER}"
                    sudo systemctl start "postgresql-${POSTGRESQL_VER}"
                else
                    sudo yum install -y https://download.postgresql.org/pub/repos/yum/reporpms/${repo_name}/pgdg-redhat-repo-latest.noarch.rpm
                    sudo yum install -y "postgresql${POSTGRESQL_VER}-server"
                    if [ "${VERSION_ID%%.*}" -eq 7 ]
                    then
                        sudo "/usr/pgsql-${POSTGRESQL_VER}/bin/postgresql-${POSTGRESQL_VER}-setup" initdb
                        sudo systemctl enable "postgresql-${POSTGRESQL_VER}"
                        sudo systemctl start "postgresql-${POSTGRESQL_VER}"
                    else
                        sudo service "postgresql-${POSTGRESQL_VER}" initdb
                        sudo chkconfig "postgresql-${POSTGRESQL_VER}" on
                        sudo service "postgresql-${POSTGRESQL_VER}" start
                    fi
                fi
            ;;
            opensuse)
                zypper install -l -y "postgresql${POSTGRESQL_VER}-server"
                systemctl enable postgresql.service
                systemctl start postgresql.service
            ;;
            sles)
                if [ "${VERSION_ID%%.*}" -eq 12 ]
                then
                    SUSEConnect -p PackageHub/12/x86_64
                    SUSEConnect -p sle-sdk/12/x86_64
                    zypper addrepo "https://download.postgresql.org/pub/repos/zypp/repo/pgdg-sles-12-pg${POSTGRESQL_SLES12_VER}.repo"
                    zypper refresh
                    zypper install "postgresql${POSTGRESQL_SLES12_VER}-server"
                else
                    zypper addrepo https://download.opensuse.org/repositories/devel:/libraries:/c_c++/${VERSION_ID}/devel:libraries:c_c++.repo
                    zypper addrepo https://download.opensuse.org/repositories/science/${VERSION_ID}/science.repo
                    zypper addrepo https://download.opensuse.org/repositories/Application:/Geo/${VERSION_ID}/Application:Geo.repo
                    SUSEConnect -p sle-module-desktop-applications/${VERSION_ID}/x86_64
                    SUSEConnect -p PackageHub/${VERSION_ID}/x86_64
                    zypper --gpg-auto-import-keys install -y zypper install https://download.postgresql.org/pub/repos/zypp/reporpms/SLES-15-x86_64/pgdg-suse-repo-latest.noarch.rpm
                    zypper refresh
                    zypper install "postgresql${POSTGRESQL_VER}-server"
                fi

                systemctl enable postgresql.service
                systemctl start postgresql.service
            ;;
            *)
                Println "$(eval_gettext "\$error 不支持的系统")\n"
                return 1
            ;;
        esac

        if ! su postgres -c 'psql -c "\du"' | grep -q "$USER"
        then
            su postgres -c "createuser --superuser $USER"
            createdb "$USER"
        fi

        Println "$(eval_gettext "\$info postgresql 安装成功")\n"
    }
    YqInstall()
    {
        local install="$(gettext "更新")"

        if [ -z "${1:-}" ] 
        then
            if [[ -x $(command -v yq) ]] 
            then
                return 0
            fi
            install="$(gettext "安装")"
        elif [[ ! -x $(command -v yq) ]] 
        then
            install="$(gettext "安装")"
        fi

        DepsCheck
        ArchCheck

        if [ "$dist" == "mac" ] 
        then
            echo
            inquirer list_input_index "$(gettext "是否编译(brew安装可能会很慢)")" ny_options ny_index
            if [ "$ny_index" -eq 1 ] 
            then
                brew install yq
                Println "$(eval_gettext "\$info yq \${install}成功")\n"
                return 0
            fi
            if [ "$arch" == "x86_64" ] 
            then
                yq_name=yq_darwin_amd64
            else
                yq_name=yq_darwin_arm64
            fi
        else
            case $arch in
                i386) yq_name=yq_linux_386
                ;;
                x86_64) yq_name=yq_linux_amd64
                ;;
                arm64|s390x) yq_name=yq_linux_$arch
                ;;
                arm*) yq_name=yq_linux_arm
                ;;
                *) Println "$(eval_gettext "不支持的架构: \$arch")"; return 1
                ;;
            esac
        fi

        if curl -L "$FFMPEG_MIRROR_LINK/yq/$yq_name" -o "$YQ_FILE"_tmp
        then
            mv "$YQ_FILE"_tmp "$YQ_FILE"
            chmod +x "$YQ_FILE"
        else
            rm -f "$YQ_FILE"_tmp
            Println "`eval_gettext \"\\\$error 下载 yq 失败, 请重试 !\"`"
            return 1
        fi

        Println "$(eval_gettext "\$info yq \${install}成功")\n"
    }

    YQ()
    {
        case $1 in
            update)
                local pattern replace
                pattern="${yq_path}" replace="${yq_replace}" yq -i 'setpath(env(pattern); env(replace))' "$2"
            ;;
            update_key)
                local pattern_new pattern_old
                pattern_new="${yq_path_new}" pattern_old="${yq_path_old}" yq -i 'eval(strenv(pattern_new)) = eval(strenv(pattern_old)) | del(eval(strenv(pattern_old)))' "$2"
            ;;
        esac

        return 0
    }

    DepInstall sudo

    docker_options=( "$(gettext "服务")" "$(gettext "管理证书")" "$(gettext "安装/更新 docker")" "$(gettext "安装/更新 postgresql")" "$(gettext "安装/更新 yq")" )
    echo
    inquirer list_input_index "$i18n_please_select" docker_options docker_options_index

    case $docker_options_index in
        0) DockerService
        ;;
        1) DockerCrtManage
        ;;
        2) DockerInstall update
        ;;
        3) PostgresqlInstall update
        ;;
        4) YqInstall update
        ;;
    esac
elif [ "$self" == "ha" ]
then
    HAProxyInstall()
    {
        local install="$i18n_update"

        if [ -z "${1:-}" ] 
        then
            if [[ -x $(command -v haproxy) ]] 
            then
                Println "$(eval_gettext "\$error haproxy 已安装 !")\n"
                return 0
            fi
            install="$i18n_install"
        elif [[ ! -x $(command -v haproxy) ]] 
        then
            install="$i18n_install"
        fi

        DepsCheck

        args=()
        ldflags=()

        if [ "$dist" == "mac" ] 
        then
            if [ -d "$DEPENDS_ROOT"/haproxy ] 
            then
                Println "$(eval_gettext "\$info 已经存在 \$DEPENDS_ROOT/haproxy !")\n"
                return 1
            fi

            if [ ! -f /etc/paths.d/haproxy ] 
            then
                sudo mkdir -p /etc/paths.d
                echo "$DEPENDS_ROOT"/haproxy/bin | sudo tee /etc/paths.d/haproxy
            fi
        else
            echo
            inquirer list_input_index "$(gettext "开启 USE_GETADDRINFO")" yn_options yn_index

            if [ "$yn_index" -eq 0 ] 
            then
                args+=( USE_GETADDRINFO=1 )
            fi
        fi

        echo
        pcre_options=( pcre pcre2 )
        inquirer list_input_index "$(gettext "选择 pcre 版本")" pcre_options pcre_options_index

        if [ "$pcre_options_index" -eq 0 ] 
        then
            pcre_args=( USE_STATIC_PCRE USE_PCRE )
            echo
            inquirer list_input_index "$(gettext "开启 USE_PCRE_JIT")" yn_options yn_index
            if [ "$yn_index" -eq 0 ] 
            then
                args+=( USE_PCRE_JIT=1 )
            fi
        else
            pcre_args=( USE_STATIC_PCRE2 USE_PCRE2 )
            echo
            inquirer list_input_index "$(gettext "开启 USE_PCRE2_JIT")" yn_options yn_index
            if [ "$yn_index" -eq 0 ] 
            then
                args+=( USE_PCRE2_JIT=1 )
            fi
        fi

        echo
        local pcre_opt="${pcre_options[pcre_options_index]}"
        inquirer list_input_index "$(eval_gettext "选择 \$pcre_opt 编译选项")" pcre_args pcre_args_index
        args+=( "${pcre_args[pcre_args_index]}=1" )

        if [ "$pcre_args_index" -eq 0 ] 
        then
            static_pcre=true
        else
            static_pcre=false
        fi

        Println "$(eval_gettext "\$tip 如果选择 openssl, haproxy 将不支持 QUIC 0-RTT")"
        openssl_options=( openssl@1.1 openssl@3 quictls )
        inquirer list_input_index "$(gettext "选择 openssl 版本")" openssl_options openssl_options_index

        args+=( USE_OPENSSL=1 )

        if [ "$openssl_options_index" -eq 2 ] 
        then
            args+=( USE_QUIC=1 )
        fi

        echo
        inquirer list_input_index "$(gettext "开启硬件加密加速 USE_ENGINE")" yn_options yn_index

        if [ "$yn_index" -eq 0 ] 
        then
            args+=( USE_ENGINE=1 )
        fi

        if [ "$openssl_options_index" -eq 1 ] 
        then
            echo
            inquirer list_input_index "$(gettext "开启 USE_PTHREAD_EMULATION")" yn_options yn_index

            if [ "$yn_index" -eq 0 ] 
            then
                args+=( USE_PTHREAD_EMULATION=1 )
            fi
        fi

        echo
        local openssl_opt="${openssl_options[openssl_options_index]}"
        inquirer list_input_index "$(eval_gettext "静态链接 \$openssl_opt")" yn_options yn_index

        if [ "$yn_index" -eq 0 ] 
        then
            tls_install_args=(static)
            static_ssl=true
        else
            tls_install_args=()
            static_ssl=false
        fi

        echo
        inquirer list_input_index "$(gettext "静态链接 zlib")" yn_options yn_index

        if [ "$yn_index" -eq 0 ] 
        then
            zlib_install_args=(static)
            args+=( USE_ZLIB=1 ZLIB_INC="$DEPENDS_ROOT"/zlib-static/include ZLIB_LIB="$DEPENDS_ROOT"/zlib-static/lib )
        else
            zlib_install_args=()
            ldflags+=("$DEPENDS_ROOT"/zlib/lib)
            args+=( USE_ZLIB=1 ZLIB_INC="$DEPENDS_ROOT"/zlib/include ZLIB_LIB="$DEPENDS_ROOT"/zlib/lib )
        fi

        echo
        inquirer list_input_index "$(gettext "静态链接 Lua")" yn_options yn_index

        if [ "$yn_index" -eq 0 ] 
        then
            static_lua=true
            LuaInstall static
            args+=( USE_LUA=1 LUA_INC="$DEPENDS_ROOT"/lua-static/include LUA_LIB="$DEPENDS_ROOT"/lua-static/lib )
        else
            static_lua=false
            LuaInstall
            ldflags+=("$DEPENDS_ROOT"/lua/lib)
            args+=( USE_LUA=1 LUA_INC="$DEPENDS_ROOT"/lua/include LUA_LIB="$DEPENDS_ROOT"/lua/lib )
        fi

        ZlibInstall ${zlib_install_args[@]+"${zlib_install_args[@]}"}

        case $openssl_options_index in
            0)
                OpensslSourceInstall "${openssl_options[0]}" ${tls_install_args[@]+"${tls_install_args[@]}"}
                if [ "$static_ssl" = false ] 
                then
                    ldflags+=("$DEPENDS_ROOT"/openssl/lib)
                    args+=( SSL_INC="$DEPENDS_ROOT"/openssl/include SSL_LIB="$DEPENDS_ROOT"/openssl/lib )
                else
                    args+=( SSL_INC="$DEPENDS_ROOT"/openssl-static/include SSL_LIB="$DEPENDS_ROOT"/openssl-static/lib )
                fi
            ;;
            1)
                OpensslSourceInstall "${openssl_options[1]}" ${tls_install_args[@]+"${tls_install_args[@]}"}
                if [ "$static_ssl" = false ] 
                then
                    ldflags+=("$DEPENDS_ROOT"/openssl3/lib)
                    args+=( SSL_INC="$DEPENDS_ROOT"/openssl3/include SSL_LIB="$DEPENDS_ROOT"/openssl3/lib )
                else
                    args+=( SSL_INC="$DEPENDS_ROOT"/openssl3-static/include SSL_LIB="$DEPENDS_ROOT"/openssl3-static/lib )
                fi
            ;;
            2)
                QuictlsInstall ${tls_install_args[@]+"${tls_install_args[@]}"}
                if [ "$static_ssl" = false ] 
                then
                    ldflags+=("$DEPENDS_ROOT"/quictls/lib)
                    args+=( SSL_INC="$DEPENDS_ROOT"/quictls/include SSL_LIB="$DEPENDS_ROOT"/quictls/lib )
                else
                    args+=( SSL_INC="$DEPENDS_ROOT"/quictls-static/include SSL_LIB="$DEPENDS_ROOT"/quictls-static/lib )
                fi
            ;;
        esac

        mkdir -p "$DEPENDS_ROOT"
        cd "$DEPENDS_ROOT"

        haproxy_ver=$(curl -s -L https://www.haproxy.org/ | grep -oPm1 '<a href="/download/(?!.*dev).+.tar.gz">\K[^<]+' || true)

        if [ ! -d haproxy-"${haproxy_ver}" ] 
        then
            if ! curl -Lm 30 "https://www.haproxy.org/download/${haproxy_ver%.*}/src/haproxy-${haproxy_ver}.tar.gz" -o haproxy-"${haproxy_ver}".tar.gz
            then
                curl -Lm 30 "$FFMPEG_MIRROR_LINK/haproxy/haproxy-${haproxy_ver}.tar.gz" -o haproxy-"${haproxy_ver}".tar.gz
            fi
            Println "$(eval_gettext "\$info 解压 haproxy-\${haproxy_ver} ...")"
            tar xzf haproxy-"${haproxy_ver}".tar.gz
        fi

        cd haproxy-"${haproxy_ver}"

        if [ "$dist" == "mac" ] 
        then
            SourceInstallReady "${pcre_options[pcre_options_index]}"

            if [ "$static_pcre" = false ] 
            then
                ldflags+=("$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/lib")
            fi

            args+=( PCRE_INC="$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/include" PCRE_LIB="$HOMEBREW_PREFIX/opt/${pcre_options[pcre_options_index]}/lib" )

            args+=( USE_PROMEX=1 )

            if [ -n "${ldflags:-}" ] 
            then
                args+=( LDFLAGS="-Wl,-rpath,$(JoinByString : "${ldflags[@]}")" )
            fi

            make TARGET=osx ${args[@]+"${args[@]}"}
        else
            if [ "$dist" == "rpm" ] 
            then
                if [ "$pcre_options_index" -eq 0 ] 
                then
                    SourceInstallReady pcre-devel
                else
                    SourceInstallReady pcre2-devel
                fi
            else
                if [ "$pcre_options_index" -eq 0 ] 
                then
                    SourceInstallReady libpcre3-dev
                else
                    SourceInstallReady libpcre2-dev
                fi
            fi

            args+=( USE_SYSTEMD=1 USE_PROMEX=1 )

            if [ -n "${ldflags:-}" ] 
            then
                args+=( LDFLAGS="-Wl,-rpath,$(JoinByString : "${ldflags[@]}")" )
            fi

            make TARGET=linux-glibc ${args[@]+"${args[@]}"}
        fi

        Println "$(eval_gettext "\$info haproxy \${install}成功")\n"
    }

    HAProxyUninstall()
    {


        Println "$(eval_gettext "\$info haproxy 卸载完成")\n"
    }

    HAProxyUpdate()
    {
        HAProxyInstall update
    }
    LuaInstall()
    {
        local build_dir=build lua_path="$DEPENDS_ROOT"/lua static=false patch=https://raw.githubusercontent.com/Homebrew/formula-patches/0dcd11880c7d63eb395105a5cdddc1ca05b40f4a/lua/lua-so.patch

        lua_package=$(curl -s -L https://www.lua.org/download.html | grep -oPm1 '<A HREF="ftp/\K[^"]+' || true)
        lua_name=${lua_package%.tar*}
        lua_ver=${lua_name#lua-}

        if [ -n "${1:-}" ] 
        then
            lua_install_options=("$@")

            if EleInArray static lua_install_options
            then
                build_dir+=-static
                lua_path+=-static
                static=true
            fi
        fi

        if [ ! -d "$DEPENDS_ROOT/$lua_name/$build_dir" ] 
        then
            mkdir -p "$DEPENDS_ROOT"
            cd "$DEPENDS_ROOT"

            if [ "$dist" == "mac" ] 
            then
                DepInstall readline
                DepInstall lua

                mkdir "$lua_name/$build_dir"/{bin,lib,include}
                cp "$HOMEBREW_PREFIX"/opt/lua/bin/{lua,luac} "$lua_name/$build_dir"/bin/
                cp "$HOMEBREW_PREFIX"/opt/lua/include/lua/* "$lua_name/$build_dir"/include/
                cp "$HOMEBREW_PREFIX"/opt/lua/lib/liblua.a "$lua_name/$build_dir"/lib/
                if ! $static 
                then
                    cp "$HOMEBREW_PREFIX"/opt/lua/lib/liblua.dylib "$lua_name/$build_dir"/lib/
                fi
            else
                if [ "$dist" == "rpm" ] 
                then
                    DepInstall readline-devel
                else
                    DepInstall libreadline-dev
                fi

                curl -L "https://www.lua.org/ftp/$lua_package" -o "$lua_package"
                Println "$(eval_gettext "\$info 解压 \$lua_name ...")"
                tar xzf "$lua_package"
                cd "$lua_name"

                if ! $static 
                then
                    curl -Lm 20 "$FFMPEG_MIRROR_LINK/${patch##*/}" -o "${patch##*/}"
                    patch -p1 < "${patch##*/}"
                fi

                make linux-readline INSTALL_TOP="$DEPENDS_ROOT/$lua_name/$build_dir"
                make install INSTALL_TOP="$DEPENDS_ROOT/$lua_name/$build_dir"

                mkdir "$build_dir"/lib/pkgconfig
            cat > "$build_dir"/lib/pkgconfig/lua.pc << EOF
V= ${lua_ver%.*}
R= ${lua_ver}
prefix= $DEPENDS_ROOT/$lua_name/$build_dir
INSTALL_BIN= \${prefix}/bin
INSTALL_INC= \${prefix}/include
INSTALL_LIB= \${prefix}/lib
INSTALL_MAN= \${prefix}/share/man/man1
INSTALL_LMOD= \${prefix}/share/lua/\${V}
INSTALL_CMOD= \${prefix}/lib/lua/\${V}
exec_prefix= \${prefix}
libdir= \${exec_prefix}/lib
includedir= \${prefix}/include

Name: Lua
Description: An Extensible Extension Language
Version: ${lua_ver}
Requires:
Libs: -L\${libdir} -llua -lm
Cflags: -I\${includedir}
EOF
            fi
        fi

        ln -sfn "$DEPENDS_ROOT/$lua_name/$build_dir" "$lua_path"
    }
    ZlibInstall()
    {
        local build_dir=build args=() zlib_path="$DEPENDS_ROOT"/zlib

        if [ -n "${1:-}" ]
        then
            zlib_install_options=("$@")

            if EleInArray static zlib_install_options
            then
                build_dir+=-static
                args=(--static)
                zlib_path="$DEPENDS_ROOT"/zlib-static
            fi
        fi

        while IFS= read -r line
        do
            if [[ $line =~ \<A\ HREF=\"(.+)\.tar\.gz ]] 
            then
                zlib_name=${BASH_REMATCH[1]}
                break
            fi
        done < <(curl -s -L -H "User-Agent: $USER_AGENT_BROWSER" https://www.zlib.net 2> /dev/null)

        if [ ! -d "$DEPENDS_ROOT/$zlib_name/$build_dir" ] 
        then
            mkdir -p "$DEPENDS_ROOT"
            cd "$DEPENDS_ROOT"
            curl -L "https://www.zlib.net/$zlib_name.tar.gz" -o "$zlib_name".tar.gz
            Println "$(eval_gettext "\$info 解压 \$zlib_name ...")"
            tar xzf "$zlib_name".tar.gz
            cd "$zlib_name"
            ./configure --prefix="$DEPENDS_ROOT/$zlib_name/$build_dir" ${args[@]+"${args[@]}"}
            make
            make install
        fi

        ln -sfn "$DEPENDS_ROOT/$zlib_name/$build_dir" "$zlib_path"
    }

    DepInstall sudo

    haproxy_options=( "$i18n_install" "$i18n_update" "$(gettext "卸载")" )
    echo
    inquirer list_input_index "$i18n_please_select" haproxy_options haproxy_options_index

    case $haproxy_options_index in
        0) HAProxyInstall
        ;;
        1) HAProxyUpdate
        ;;
        2) HAProxyUninstall
        ;;
    esac
elif [ "$self" == "tr" ]
then
    TrojanInstall()
    {
        if [ -s "$TR_CONFIG" ] 
        then
            Println "$(eval_gettext "\$error \$trojan_name 已存在...")\n"
            ExitOnList n "`gettext \"是否覆盖原安装\"`"
        fi

        DepsCheck
        JQInstall

        if ! grep -q "$trojan_name:" < "/etc/passwd"
        then
            if grep -q '\--group ' < <(adduser --help)
            then
                adduser $trojan_name --system --group --no-create-home > /dev/null
            else
                adduser $trojan_name --system --no-create-home > /dev/null
            fi
            usermod -s /usr/sbin/nologin $trojan_name
        fi

        Println "$(eval_gettext "\$info 安装 \$trojan_name...")"

        { curl -s -m 10 "$TR_LINK" || curl -s -m 30 "$TR_LINK_FALLBACK"; } \
        | sed "s+nobody+$trojan_name+g" \
        | sed "s+ 'sha1'++g" \
        | sed "s+ 'sha256'++g" \
        | sed "s+ 'sha512'++g" \
        | sed "s+https://api.github.com/repos/p4gefau1t/trojan-go/releases/latest+$FFMPEG_MIRROR_LINK/$trojan_name.json+g" \
        | sed "s+https://github.com/p4gefau1t/trojan-go/releases/download+$FFMPEG_MIRROR_LINK/$trojan_name+g" | bash

        TrojanConfigInstall

        systemctl daemon-reload
        systemctl enable $trojan_name
        systemctl start $trojan_name

        Println "$(eval_gettext "\$info \$trojan_name 安装成功")\n"
    }

    exit 0
fi
